static const uint16_t NET_LOG_PORT = 9999;
static int g_netLogSock = -1;
static SceNetSockaddrIn g_netLogAddr;
static char g_netInitMem[256 * 1024];

static void InitNetLog()
{

    if (sceSysmoduleLoadModule(SCE_SYSMODULE_NET) < 0) return;

    SceNetInitParam netInitParam;
    netInitParam.memory = g_netInitMem;
    netInitParam.size = sizeof(g_netInitMem);
    netInitParam.flags = 0;
    if (sceNetInit(&netInitParam) < 0) return;
    if (sceNetCtlInit() < 0) return;

    g_netLogSock = sceNetSocket("netlog", SCE_NET_AF_INET, SCE_NET_SOCK_DGRAM, 0);
    if (g_netLogSock < 0) { g_netLogSock = -1; return; }

    memset(&g_netLogAddr, 0, sizeof(g_netLogAddr));
    g_netLogAddr.sin_family = SCE_NET_AF_INET;
    g_netLogAddr.sin_port = sceNetHtons(NET_LOG_PORT);
    if (sceNetInetPton(SCE_NET_AF_INET, NET_LOG_PC_IP, &g_netLogAddr.sin_addr) <= 0)
    {
        sceNetSocketClose(g_netLogSock);
        g_netLogSock = -1;
    }
}

static int  g_netLogStrikes = 0;
static bool g_netLogDisabled = false;

static void NetLogSend(const char* text)
{
    if (g_netLogSock < 0 || g_netLogDisabled) return;
    const uint64_t t0 = sceKernelGetProcessTimeWide();
    sceNetSendto(g_netLogSock, text, (unsigned int)strlen(text), 0,
        (SceNetSockaddr*)&g_netLogAddr, sizeof(g_netLogAddr));
    const uint64_t elapsedUs = sceKernelGetProcessTimeWide() - t0;
    if (elapsedUs > 2000)
    {
        if (++g_netLogStrikes >= 8)
        {
            g_netLogDisabled = true;

        }
    }
    else if (g_netLogStrikes > 0)
    {
        g_netLogStrikes--;
    }
}

static FILE* g_log = nullptr;

static std::atomic_flag g_logWriteLock = ATOMIC_FLAG_INIT;
struct LogWriteGuard { LogWriteGuard() { while (g_logWriteLock.test_and_set(std::memory_order_acquire)) sceKernelDelayThread(50); } ~LogWriteGuard() { g_logWriteLock.clear(std::memory_order_release); } };

static bool LoadLogBuffered()
{
    static int s = -1;
    if (s < 0) { SceIoStat st; s = sceIoGetstat("ux0:data/swbf2/syncload", &st) >= 0 ? 0 : 1; }
    if (s == 0) return false;
    static uint64_t s_last = 0;
    const uint64_t now = sceKernelGetProcessTimeWide();
    if (now - s_last > 2000000) { s_last = now; return false; }
    return true;
}
static void logf(const char* fmt, ...)
{
    if (g_log == nullptr) return;
    char buf[512];
    va_list args;
    va_start(args, fmt);
    vsnprintf(buf, sizeof(buf), fmt, args);
    va_end(args);
    { LogWriteGuard lg;
      fputs(buf, g_log);
      if (!LoadLogBuffered()) fflush(g_log); }
    NetLogSend(buf);
}

static std::vector<std::string> g_pendingCheckpoints;

static void checkpoint(const char* msg)
{

    if (g_log != nullptr)
    {
        NetLogSend(msg);
        LogWriteGuard lg;
        fprintf(g_log, "%s\n", msg);
        if (!LoadLogBuffered()) fflush(g_log);
        return;
    }

    if (g_pendingCheckpoints.size() < 512)
    {
        g_pendingCheckpoints.push_back(msg);
    }
}

static void checkpointf(const char* fmt, ...)
{
    char buf[512];
    va_list args;
    va_start(args, fmt);
    vsnprintf(buf, sizeof(buf), fmt, args);
    va_end(args);
    checkpoint(buf);
}

