static std::string NormalizeLvlKey(const char* path)
{
    std::string k = path ? path : "";
    for (char& c : k) { if (c == '\\') c = '/'; c = (char)tolower((unsigned char)c); }
    const size_t at = k.find("_lvl_pc/");
    if (at != std::string::npos) k = k.substr(at + 8);
    return k;
}

struct MapDef
{
    std::string mission = "geo1c_con";
    std::string code = "geo1";
    char era = 'c';
    std::string mode = "con";
    std::string worldLvl;
    std::vector<std::string> worldSubs;
    std::string soundLvl, soundStream;
    bool fromScript = false;
};
static MapDef g_map;
static bool g_consoleOverlay = false;
static std::unordered_map<std::string, int> g_consoleMissionUnits;
static std::unordered_map<std::string, std::string> g_consoleWorld;
static std::unordered_map<std::string, std::vector<float>> g_consoleSky;

static bool ConsoleWorldProp(const std::string& instName, const char* prop, float& out)
{
    if (!g_consoleOverlay) return false;
    std::string k = g_map.code + "|" + instName + "|" + prop;
    for (char& c : k) c = (char)tolower((unsigned char)c);
    auto it = g_consoleWorld.find(k);
    if (it == g_consoleWorld.end()) return false;
    out = (float)atof(it->second.c_str());
    return true;
}

static const std::vector<float>* ConsoleMapVals(const char* key)
{
    if (!g_consoleOverlay) return nullptr;
    std::string k = g_map.code + "|" + key;
    for (char& c : k) c = (char)tolower((unsigned char)c);
    auto it = g_consoleSky.find(k);
    return it == g_consoleSky.end() ? nullptr : &it->second;
}

static std::string MapObjectiveKey()
{
    const std::string m = (g_map.mode == "con") ? "conquest" : (g_map.mode == "ctf" ? "ctf" : g_map.mode);
    return "level." + g_map.code + ".objectives." + m;
}

static const char* const SHELL_LAUNCH_PATH = "ux0:data/swbf2/launch.txt";
static bool g_fromShell = false;
static std::vector<std::string> g_playlistRest;
static void RelaunchApp(const char* why)
{
    checkpointf("M480 relaunch: %s", why);
    const int r = sceAppMgrLoadExec("app0:eboot.bin", nullptr, nullptr);
    checkpointf("M480 sceAppMgrLoadExec failed (0x%08X) - exiting", (unsigned)r);
    sceKernelExitProcess(0);
}
static void WriteLaunchFile(const std::vector<std::string>& missions)
{
    if (FILE* f = fopen(SHELL_LAUNCH_PATH, "w"))
    {
        for (const std::string& m : missions) fprintf(f, "%s\n", m.c_str());
        fclose(f);
    }
}

static void LeaveMission(bool nextInPlaylist)
{
    if (nextInPlaylist && !g_playlistRest.empty()) { WriteLaunchFile(g_playlistRest); RelaunchApp("next playlist mission"); }
    else { sceIoRemove(SHELL_LAUNCH_PATH); RelaunchApp("back to the shell"); }
}
static void ChooseMission()
{
    if (FILE* f = fopen(SHELL_LAUNCH_PATH, "r"))
    {
        char buf[64] = {};
        while (fscanf(f, "%63s", buf) == 1)
        {
            if (strlen(buf) < 6) continue;
            if (!g_fromShell) { g_map.mission = buf; g_fromShell = true; }
            else g_playlistRest.push_back(buf);
        }
        fclose(f);
        sceIoRemove(SHELL_LAUNCH_PATH);
        checkpointf("M480 launched from the shell: %s, %u more in the playlist", g_map.mission.c_str(), (unsigned)g_playlistRest.size());
    }
    else if (FILE* f = fopen("ux0:data/swbf2/mission.txt", "r"))
    {
        char buf[64] = {};
        if (fscanf(f, "%63s", buf) == 1 && strlen(buf) >= 6) g_map.mission = buf;
        fclose(f);
    }
    for (char& c : g_map.mission) c = (char)tolower((unsigned char)c);
    g_map.code = g_map.mission.substr(0, 4);
    g_map.era = g_map.mission.size() > 4 ? g_map.mission[4] : 'c';
    const size_t us = g_map.mission.find('_');
    g_map.mode = (us != std::string::npos) ? g_map.mission.substr(us + 1) : std::string();

    g_map.worldLvl = std::string(GAME_DATA_ROOT) + g_map.code.substr(0, 3) + "/" + g_map.code + ".lvl";
    g_map.worldSubs = { g_map.code + "_" + (g_map.mode == "con" ? std::string("conquest") : g_map.mode) };
}

static void ResolveMapFromScript()
{
    for (const DataFileRequest& req : g_dataFileManifest)
    {
        const std::string key = NormalizeLvlKey(req.lvlFile.c_str());
        const size_t slash = key.rfind('/');
        const std::string file = (slash == std::string::npos) ? key : key.substr(slash + 1);
        if (key.compare(0, 5, "side/") == 0 || key.compare(0, 6, "sound/") == 0 || file != g_map.code + ".lvl") continue;
        g_map.worldLvl = std::string(GAME_DATA_ROOT) + key;
        if (!req.subResources.empty()) g_map.worldSubs = req.subResources;
        g_map.fromScript = true;
    }
    for (const DataFileRequest& req : g_audioManifest)
    {
        const std::string key = NormalizeLvlKey(req.lvlFile.c_str());
        if (key.compare(0, 6, "sound/") != 0 || key == "sound/global.lvl" || req.subResources.empty()) continue;
        if (g_map.soundLvl.empty()) { g_map.soundLvl = std::string(GAME_DATA_ROOT) + key; g_map.soundStream = req.subResources[0]; }
    }
}

static bool IsSharedLvlKey(const std::string& key)
{
    return key == "ingame.lvl" || key.compare(0, 5, "side/") == 0;
}

static std::set<uint32_t> ScanSubLvlHashes(const char* path)
{
    std::set<uint32_t> out;
    FILE* f = fopen(path, "rb");
    if (f == nullptr) return out;
    uint32_t hdr[2];
    if (fread(hdr, 4, 2, f) == 2)
    {
        const long end = 8 + (long)hdr[1];
        long pos = 8;
        while (pos + 8 <= end && fseek(f, pos, SEEK_SET) == 0 && fread(hdr, 4, 2, f) == 2)
        {
            if (memcmp(&hdr[0], "lvl_", 4) == 0)
            {
                uint32_t h = 0;
                if (fread(&h, 4, 1, f) == 1) out.insert(h);
            }
            pos += 8 + (long)hdr[1];
            pos = (pos + 3) & ~3L;
        }
    }
    fclose(f);
    return out;
}

static void ReleaseLevel(Level* l)
{
    if (l == nullptr) return;
    for (SharedLevel& sl : g_sharedLevels) if (sl.lvl == l) { ++sl.released; return; }
    Level::Destroy(l);
}

static const int kCookVersion = 1;
static std::string CookedLevelPath(const char* original)
{
    static int s_cookOn = -1;
    if (s_cookOn < 0) { SceIoStat st; s_cookOn = sceIoGetstat("ux0:data/swbf2/cooked/off", &st) < 0 ? 1 : 0; }
    const std::string o = original;
    const char* kRoot = "GameData/data/_lvl_pc/";
    const size_t at = o.find(kRoot);
    if (!s_cookOn || at == std::string::npos) return o;
    const std::string cooked = "ux0:data/swbf2/cooked/_lvl_pc/" + o.substr(at + strlen(kRoot));
    SceIoStat so, sc;
    if (sceIoGetstat(o.c_str(), &so) < 0 || sceIoGetstat(cooked.c_str(), &sc) < 0) return o;
    FILE* f = fopen((cooked + ".cook").c_str(), "r");
    if (!f) return o;
    int ver = 0; long long srcSize = -1;
    const int got = fscanf(f, "cook %d srcsize %lld", &ver, &srcSize);
    fclose(f);
    if (got != 2 || ver != kCookVersion || srcSize != (long long)so.st_size)
    {
        checkpointf("M532 cook: %s is stale (stamp v%d size %lld, original %lld) - using the original", cooked.c_str(), ver, srcSize, (long long)so.st_size);
        return o;
    }
    checkpointf("M532 cook: %s -> cooked copy (%.1f MB instead of %.1f MB)", o.c_str(), sc.st_size / 1e6, so.st_size / 1e6);
    return cooked;
}

static Level* TimedLevelFromFile(const LibSWBF2::Types::String& path,
                                 const LibSWBF2::Types::List<LibSWBF2::Types::String>* subLvls = nullptr)
{
    const std::string key = NormalizeLvlKey(path.Buffer());
    const bool wantWhole = (subLvls == nullptr || subLvls->Size() == 0);
    bool cacheThis = false;
    LibSWBF2::Types::List<LibSWBF2::Types::String> unionSubs;
    if (IsSharedLvlKey(key))
    {
        for (SharedLevel& sl : g_sharedLevels)
        {
            if (sl.key != key) continue;
            std::string missing;
            if (!sl.whole)
            {
                if (wantWhole) missing = "<whole file>";
                else
                    for (size_t i = 0; i < subLvls->Size(); ++i)
                    {
                        const uint32_t h = LibSWBF2::FNV::Hash((*subLvls)[i]);
                        if (sl.loaded.count(h) || !sl.inFile.count(h)) continue;
                        if (!missing.empty()) missing += ",";
                        missing += (*subLvls)[i].Buffer();
                    }
            }
            if (missing.empty())
            {
                checkpointf("M385 %s: shared copy (%u name(s) requested)", key.c_str(),
                    subLvls ? (unsigned)subLvls->Size() : 0u);
                ++sl.served;
                return sl.lvl;
            }
            checkpointf("M385 extra open %s: not in the shared copy: %s", key.c_str(), missing.c_str());
            goto plainOpen;
        }

        cacheThis = true;
        if (!wantWhole)
        {
            std::set<std::string> names;
            for (size_t i = 0; i < subLvls->Size(); ++i) names.insert((*subLvls)[i].Buffer());
            for (const DataFileRequest& req : g_dataFileManifest)
                if (NormalizeLvlKey(req.lvlFile.c_str()) == key)
                {
                    if (req.subResources.empty()) { names.clear(); break; }
                    for (const std::string& n : req.subResources) names.insert(n);
                }
            for (const std::string& n : names) unionSubs.Add(n.c_str());
            subLvls = unionSubs.Size() > 0 ? &unionSubs : nullptr;
        }
    }
plainOpen:
    const uint64_t t0 = sceKernelGetProcessTimeWide();
    Level* l = Level::FromFile(String(CookedLevelPath(path.Buffer()).c_str()), subLvls);
    const double totalMs = (double)(sceKernelGetProcessTimeWide() - t0) / 1000.0;
    checkpointf("M382 open +%.1fs %s subLvls=%u%s%s: read %.0fms explore %.0fms total %.0fms%s",
        (double)(sceKernelGetProcessTimeWide() - g_loadStartTime) / 1e6, path.Buffer(), subLvls ? (unsigned)subLvls->Size() : 0u,
        (subLvls && subLvls->Size() > 0) ? " first=" : "",
        (subLvls && subLvls->Size() > 0) ? (*subLvls)[0].Buffer() : "",
        Level::s_LastReadMs, Level::s_LastExploreMs, totalMs, l ? "" : " FAILED");
    if (l != nullptr && cacheThis)
    {
        SharedLevel sl;
        sl.key = key; sl.lvl = l; sl.served = 1;
        sl.whole = (subLvls == nullptr || subLvls->Size() == 0);
        if (!sl.whole)
            for (size_t i = 0; i < subLvls->Size(); ++i) sl.loaded.insert(LibSWBF2::FNV::Hash((*subLvls)[i]));
        sl.inFile = ScanSubLvlHashes(path.Buffer());
        checkpointf("M385 shared %s: %s, %u of %u sub-LVL(s) in file", key.c_str(),
            sl.whole ? "whole file" : "restricted", (unsigned)sl.loaded.size(), (unsigned)sl.inFile.size());
        g_sharedLevels.push_back(std::move(sl));
        logMallinfo("M385 after shared open");
    }
    return l;
}

static void ReleaseUnusedSharedLevels()
{
    for (size_t i = 0; i < g_sharedLevels.size(); )
    {
        SharedLevel& sl = g_sharedLevels[i];
        checkpointf("M386 shared %s: served %u, released %u -> %s", sl.key.c_str(),
            sl.served, sl.released, sl.released >= sl.served ? "freed" : "kept (still referenced)");
        if (sl.released >= sl.served)
        {
            Level::Destroy(sl.lvl);
            g_sharedLevels.erase(g_sharedLevels.begin() + (long)i);
            continue;
        }
        ++i;
    }
}

static SceUID g_logQueueMutex = -1;
static std::vector<std::string> g_logQueue;

static volatile uint32_t g_logFlushUs = 0, g_logFlushMaxUs = 0;
static volatile uint32_t g_logBytes = 0;
static int LogWriterThreadMain(SceSize, void*)
{
    std::vector<std::string> batch;
    FILE* f = nullptr;
    for (;;)
    {
        sceKernelDelayThread(500 * 1000);
        sceKernelLockMutex(g_logQueueMutex, 1, nullptr);
        batch.swap(g_logQueue);
        sceKernelUnlockMutex(g_logQueueMutex, 1);
        if (batch.empty()) continue;
        for (const std::string& m : batch) NetLogSend(m.c_str());
        const uint64_t t0 = sceKernelGetProcessTimeWide();
        if (f == nullptr) f = fopen(LOG_PATH, "a");
        if (f != nullptr)
        {
            for (const std::string& m : batch) { fprintf(f, "%s\n", m.c_str()); g_logBytes += (uint32_t)m.size() + 1; }
            if (fflush(f) != 0) { fclose(f); f = nullptr; }
        }
        const uint32_t us = (uint32_t)(sceKernelGetProcessTimeWide() - t0);
        g_logFlushUs = us; if (us > g_logFlushMaxUs) g_logFlushMaxUs = us;
        batch.clear();
    }
    return 0;
}
static void checkpointBatch(const std::vector<std::string>& messages)
{
#ifdef SWBF2_HEADLESS
    static FILE* s_hl = nullptr;
    if (s_hl == nullptr) s_hl = fopen(LOG_PATH, "a");
    if (s_hl != nullptr) { for (const std::string& m : messages) fprintf(s_hl, "%s\n", m.c_str()); fflush(s_hl); }
    return;
#endif
    if (g_logQueueMutex < 0)
    {
        g_logQueueMutex = sceKernelCreateMutex("log_queue_mutex", 0, 0, nullptr);
        const SceUID t = sceKernelCreateThread("log_writer", LogWriterThreadMain, 0x10000100 + 10, 0x4000, 0, 0, nullptr);
        if (g_logQueueMutex < 0 || t < 0) { g_logQueueMutex = -1; return; }
        sceKernelStartThread(t, 0, nullptr);
    }
    sceKernelLockMutex(g_logQueueMutex, 1, nullptr);
    if (g_logQueue.size() < 8192)
        g_logQueue.insert(g_logQueue.end(), messages.begin(), messages.end());
    sceKernelUnlockMutex(g_logQueueMutex, 1);
}

