static void logMemory(const char* label)
{
    SceKernelFreeMemorySizeInfo info;
    info.size = sizeof(info);
    int ret = sceKernelGetFreeMemorySize(&info);
    char buf[256];
    if (ret < 0)
    {
        snprintf(buf, sizeof(buf), "mem[%s]: sceKernelGetFreeMemorySize FAILED (0x%08x)\n", label, (unsigned)ret);
    }
    else
    {
        snprintf(buf, sizeof(buf), "mem[%s]: user=%d KB cdram=%d KB phycont=%d KB\n",
            label, info.size_user / 1024, info.size_cdram / 1024, info.size_phycont / 1024);
    }
    NetLogSend(buf);

    if (g_log != nullptr)
    {
        fputs(buf, g_log);
        fflush(g_log);
        return;
    }

    std::string line(buf);
    while (!line.empty() && (line.back() == '\n' || line.back() == '\r')) line.pop_back();
    checkpoint(line.c_str());
}

