static bool SliceTriangleAtY(const float vx[3], const float vy[3], const float vz[3],
                             float yq, float& outAX, float& outAZ,
                             float& outBX, float& outBZ)
{
    float px[2], pz[2];
    int n = 0;
    for (int e = 0; e < 3 && n < 2; ++e)
    {
        const int j = (e + 1) % 3;
        const float y0 = vy[e], y1 = vy[j];
        if ((y0 - yq) * (y1 - yq) > 0.0f) continue;
        const float d = y1 - y0;
        if (fabsf(d) < 0.000001f) continue;
        const float t = (yq - y0) / d;
        px[n] = vx[e] + t * (vx[j] - vx[e]);
        pz[n] = vz[e] + t * (vz[j] - vz[e]);
        ++n;
    }
    if (n < 2) return false;
    outAX = px[0]; outAZ = pz[0]; outBX = px[1]; outBZ = pz[1];
    return true;
}

