struct ModelCellGrid
{
    struct Span { const uint32_t* b = nullptr; const uint32_t* e = nullptr; const uint32_t* begin() const { return b; } const uint32_t* end() const { return e; } size_t size() const { return (size_t)(e - b); } bool empty() const { return b == e; } };
    struct Found { bool ok = false; Span second; const Found* operator->() const { return this; } bool operator==(const Found& o) const { return ok == o.ok; } bool operator!=(const Found& o) const { return ok != o.ok; } };
    void Add(int64_t key, uint32_t id) { pend.push_back({ key, id }); }
    Found find(int64_t key) const
    {
        Freeze();
        Found f; const auto it = std::lower_bound(keys.begin(), keys.end(), key);
        if (it == keys.end() || *it != key) return f;
        const size_t c = (size_t)(it - keys.begin());
        f.ok = true; f.second.b = ids.data() + off[c]; f.second.e = ids.data() + off[c + 1];
        return f;
    }
    Found end() const { return Found(); }
    bool empty() const { return pend.empty() && keys.empty(); }
    size_t size() const { Freeze(); return keys.size(); }
    void Freeze() const
    {
        if (pend.empty()) return;

        std::vector<std::pair<int64_t, uint32_t>> all; all.reserve(ids.size() + pend.size());
        for (size_t c = 0; c < keys.size(); ++c) for (uint32_t k = off[c]; k < off[c + 1]; ++k) all.push_back({ keys[c], ids[k] });
        all.insert(all.end(), pend.begin(), pend.end()); std::vector<std::pair<int64_t, uint32_t>>().swap(pend);
        std::stable_sort(all.begin(), all.end(), [](const std::pair<int64_t, uint32_t>& a, const std::pair<int64_t, uint32_t>& b) { return a.first < b.first; });
        keys.clear(); off.clear(); ids.clear(); ids.reserve(all.size());
        for (size_t i = 0; i < all.size(); ++i)
        {
            if (keys.empty() || keys.back() != all[i].first) { keys.push_back(all[i].first); off.push_back((uint32_t)i); }
            ids.push_back(all[i].second);
        }
        off.push_back((uint32_t)ids.size());
    }
private:
    mutable std::vector<std::pair<int64_t, uint32_t>> pend;
    mutable std::vector<int64_t> keys; mutable std::vector<uint32_t> off, ids;
};

