static void ComputeSmoothTerrainNormals(const Vector3* verts, uint32_t vCount,
    const uint32_t* indices, uint32_t iCount, std::vector<Vector3>& outNormals)
{
    outNormals.assign(vCount, Vector3(0.0f, 0.0f, 0.0f));
    if (verts == nullptr || indices == nullptr || vCount == 0 || iCount < 3) return;

    for (uint32_t i = 0; i + 2 < iCount; i += 3)
    {
        uint32_t i0 = indices[i], i1 = indices[i + 1], i2 = indices[i + 2];
        if (i0 >= vCount || i1 >= vCount || i2 >= vCount) continue;
        const Vector3& p0 = verts[i0];
        const Vector3& p1 = verts[i1];
        const Vector3& p2 = verts[i2];
        Vector3 e1(p1.m_X - p0.m_X, p1.m_Y - p0.m_Y, p1.m_Z - p0.m_Z);
        Vector3 e2(p2.m_X - p0.m_X, p2.m_Y - p0.m_Y, p2.m_Z - p0.m_Z);

        Vector3 fn(
            e1.m_Y * e2.m_Z - e1.m_Z * e2.m_Y,
            e1.m_Z * e2.m_X - e1.m_X * e2.m_Z,
            e1.m_X * e2.m_Y - e1.m_Y * e2.m_X);
        outNormals[i0].m_X += fn.m_X; outNormals[i0].m_Y += fn.m_Y; outNormals[i0].m_Z += fn.m_Z;
        outNormals[i1].m_X += fn.m_X; outNormals[i1].m_Y += fn.m_Y; outNormals[i1].m_Z += fn.m_Z;
        outNormals[i2].m_X += fn.m_X; outNormals[i2].m_Y += fn.m_Y; outNormals[i2].m_Z += fn.m_Z;
    }

    struct PosKey
    {
        int64_t x, y, z;
        bool operator==(const PosKey& o) const { return x == o.x && y == o.y && z == o.z; }
    };
    struct PosKeyHash
    {
        size_t operator()(const PosKey& k) const
        {
            return std::hash<int64_t>()(k.x) ^ (std::hash<int64_t>()(k.y) * 0x9E3779B97F4A7C15ULL) ^ (std::hash<int64_t>()(k.z) * 0xC2B2AE3D27D4EB4FULL);
        }
    };
    std::unordered_map<PosKey, std::vector<uint32_t>, PosKeyHash> byPos;
    byPos.reserve(vCount);
    const float QUANT = 64.0f;
    for (uint32_t i = 0; i < vCount; ++i)
    {
        PosKey k{ (int64_t)llroundf(verts[i].m_X * QUANT), (int64_t)llroundf(verts[i].m_Y * QUANT), (int64_t)llroundf(verts[i].m_Z * QUANT) };
        byPos[k].push_back(i);
    }
    for (auto& kv : byPos)
    {
        std::vector<uint32_t>& idxs = kv.second;
        if (idxs.size() < 2) continue;
        Vector3 sum(0.0f, 0.0f, 0.0f);
        for (uint32_t idx : idxs)
        {
            sum.m_X += outNormals[idx].m_X;
            sum.m_Y += outNormals[idx].m_Y;
            sum.m_Z += outNormals[idx].m_Z;
        }
        for (uint32_t idx : idxs) outNormals[idx] = sum;
    }

    for (uint32_t i = 0; i < vCount; ++i)
    {
        Vector3& n = outNormals[i];
        float len = sqrtf(n.m_X * n.m_X + n.m_Y * n.m_Y + n.m_Z * n.m_Z);
        if (len > 0.00001f)
        {
            n.m_X /= len; n.m_Y /= len; n.m_Z /= len;
        }
        else
        {
            n.m_X = 0.0f; n.m_Y = 1.0f; n.m_Z = 0.0f;
        }
    }
}

static void NormalizeInPlace(Vector3& v)
{
    float len = sqrtf(v.m_X * v.m_X + v.m_Y * v.m_Y + v.m_Z * v.m_Z);
    if (len > 0.00001f) { v.m_X /= len; v.m_Y /= len; v.m_Z /= len; }
    else { v = Vector3(0.0f, 1.0f, 0.0f); }
}

static bool GetTerrainHeightAt(const TerrainData& td, float x, float z, float& outY, Vector3& outNormal, uint32_t& hintTriangle)
{
    outNormal = Vector3(0.0f, 1.0f, 0.0f);
    if (!td.valid || td.verts == nullptr || td.indices == nullptr) return false;
    const bool haveNormals = (td.normals != nullptr && td.nCount == td.vCount);

    if (hintTriangle + 2 < td.iCount)
    {
        const Vector3& ha = td.verts[td.indices[hintTriangle]];
        const Vector3& hb = td.verts[td.indices[hintTriangle + 1]];
        const Vector3& hc = td.verts[td.indices[hintTriangle + 2]];
        const float hv0x = hc.m_X - ha.m_X, hv0z = hc.m_Z - ha.m_Z;
        const float hv1x = hb.m_X - ha.m_X, hv1z = hb.m_Z - ha.m_Z;
        const float hv2x = x - ha.m_X, hv2z = z - ha.m_Z;
        const float hdot00 = hv0x * hv0x + hv0z * hv0z;
        const float hdot01 = hv0x * hv1x + hv0z * hv1z;
        const float hdot02 = hv0x * hv2x + hv0z * hv2z;
        const float hdot11 = hv1x * hv1x + hv1z * hv1z;
        const float hdot12 = hv1x * hv2x + hv1z * hv2z;
        const float hdenom = hdot00 * hdot11 - hdot01 * hdot01;
        if (fabsf(hdenom) >= 0.00001f)
        {
            const float hinvDenom = 1.0f / hdenom;
            const float hu = (hdot11 * hdot02 - hdot01 * hdot12) * hinvDenom;
            const float hv = (hdot00 * hdot12 - hdot01 * hdot02) * hinvDenom;
            if (hu >= -0.001f && hv >= -0.001f && (hu + hv) <= 1.001f &&
                x >= fminf(ha.m_X, fminf(hb.m_X, hc.m_X)) - kTerrainAnswerBoxSlack &&
                x <= fmaxf(ha.m_X, fmaxf(hb.m_X, hc.m_X)) + kTerrainAnswerBoxSlack &&
                z >= fminf(ha.m_Z, fminf(hb.m_Z, hc.m_Z)) - kTerrainAnswerBoxSlack &&
                z <= fmaxf(ha.m_Z, fmaxf(hb.m_Z, hc.m_Z)) + kTerrainAnswerBoxSlack)
            {
                outY = ha.m_Y + hu * (hc.m_Y - ha.m_Y) + hv * (hb.m_Y - ha.m_Y);
                if (haveNormals)
                {
                    const Vector3& na = td.normals[td.indices[hintTriangle]];
                    const Vector3& nb = td.normals[td.indices[hintTriangle + 1]];
                    const Vector3& nc = td.normals[td.indices[hintTriangle + 2]];
                    outNormal = Vector3(
                        na.m_X + hu * (nc.m_X - na.m_X) + hv * (nb.m_X - na.m_X),
                        na.m_Y + hu * (nc.m_Y - na.m_Y) + hv * (nb.m_Y - na.m_Y),
                        na.m_Z + hu * (nc.m_Z - na.m_Z) + hv * (nb.m_Z - na.m_Z));
                    NormalizeInPlace(outNormal);
                }
                return true;
            }
        }
    }

    if (td.triGridW > 0)
    {
        const int32_t cx = (int32_t)floorf(x / TERRAIN_GRID_CELL) - td.triGridX0;
        const int32_t cz = (int32_t)floorf(z / TERRAIN_GRID_CELL) - td.triGridZ0;
        if (cx >= 0 && cz >= 0 && cx < td.triGridW && cz < td.triGridH)
        {
            const size_t k = (size_t)cz * (size_t)td.triGridW + (size_t)cx;
            for (uint32_t ti = td.triGridStart[k]; ti < td.triGridStart[k + 1]; ++ti)
            {
                const uint32_t i = td.triGridTris[ti];
                const Vector3& a = td.verts[td.indices[i]];
                const Vector3& b = td.verts[td.indices[i + 1]];
                const Vector3& c = td.verts[td.indices[i + 2]];
                const float v0x = c.m_X - a.m_X, v0z = c.m_Z - a.m_Z;
                const float v1x = b.m_X - a.m_X, v1z = b.m_Z - a.m_Z;
                const float v2x = x - a.m_X, v2z = z - a.m_Z;
                const float dot00 = v0x * v0x + v0z * v0z;
                const float dot01 = v0x * v1x + v0z * v1z;
                const float dot02 = v0x * v2x + v0z * v2z;
                const float dot11 = v1x * v1x + v1z * v1z;
                const float dot12 = v1x * v2x + v1z * v2z;
                const float denom = dot00 * dot11 - dot01 * dot01;
                if (fabsf(denom) < 0.00001f) continue;
                const float invDenom = 1.0f / denom;
                const float u = (dot11 * dot02 - dot01 * dot12) * invDenom;
                const float v = (dot00 * dot12 - dot01 * dot02) * invDenom;
                if (u < -0.001f || v < -0.001f || (u + v) > 1.001f) continue;
                if (x < fminf(a.m_X, fminf(b.m_X, c.m_X)) - kTerrainAnswerBoxSlack ||
                    x > fmaxf(a.m_X, fmaxf(b.m_X, c.m_X)) + kTerrainAnswerBoxSlack ||
                    z < fminf(a.m_Z, fminf(b.m_Z, c.m_Z)) - kTerrainAnswerBoxSlack ||
                    z > fmaxf(a.m_Z, fmaxf(b.m_Z, c.m_Z)) + kTerrainAnswerBoxSlack) continue;

                outY = a.m_Y + u * (c.m_Y - a.m_Y) + v * (b.m_Y - a.m_Y);
                if (haveNormals)
                {
                    const Vector3& na = td.normals[td.indices[i]];
                    const Vector3& nb = td.normals[td.indices[i + 1]];
                    const Vector3& nc = td.normals[td.indices[i + 2]];
                    outNormal = Vector3(
                        na.m_X + u * (nc.m_X - na.m_X) + v * (nb.m_X - na.m_X),
                        na.m_Y + u * (nc.m_Y - na.m_Y) + v * (nb.m_Y - na.m_Y),
                        na.m_Z + u * (nc.m_Z - na.m_Z) + v * (nb.m_Z - na.m_Z));
                    NormalizeInPlace(outNormal);
                }
                hintTriangle = i;
                return true;
            }
        }

        return false;
    }

    for (uint32_t i = 0; i + 2 < td.iCount; i += 3)
    {
        const Vector3& a = td.verts[td.indices[i]];
        const Vector3& b = td.verts[td.indices[i + 1]];
        const Vector3& c = td.verts[td.indices[i + 2]];

        const float d00 = (c.m_X - a.m_X) * (c.m_X - a.m_X) + (c.m_Z - a.m_Z) * (c.m_Z - a.m_Z);
        const float v0x = c.m_X - a.m_X, v0z = c.m_Z - a.m_Z;
        const float v1x = b.m_X - a.m_X, v1z = b.m_Z - a.m_Z;
        const float v2x = x - a.m_X, v2z = z - a.m_Z;
        const float dot00 = v0x * v0x + v0z * v0z;
        const float dot01 = v0x * v1x + v0z * v1z;
        const float dot02 = v0x * v2x + v0z * v2z;
        const float dot11 = v1x * v1x + v1z * v1z;
        const float dot12 = v1x * v2x + v1z * v2z;
        (void)d00;
        const float denom = dot00 * dot11 - dot01 * dot01;
        if (fabsf(denom) < 0.00001f) continue;
        const float invDenom = 1.0f / denom;
        const float u = (dot11 * dot02 - dot01 * dot12) * invDenom;
        const float v = (dot00 * dot12 - dot01 * dot02) * invDenom;
        if (u < -0.001f || v < -0.001f || (u + v) > 1.001f) continue;
        if (x < fminf(a.m_X, fminf(b.m_X, c.m_X)) - kTerrainAnswerBoxSlack ||
            x > fmaxf(a.m_X, fmaxf(b.m_X, c.m_X)) + kTerrainAnswerBoxSlack ||
            z < fminf(a.m_Z, fminf(b.m_Z, c.m_Z)) - kTerrainAnswerBoxSlack ||
            z > fmaxf(a.m_Z, fmaxf(b.m_Z, c.m_Z)) + kTerrainAnswerBoxSlack) continue;

        outY = a.m_Y + u * (c.m_Y - a.m_Y) + v * (b.m_Y - a.m_Y);
        if (haveNormals)
        {
            const Vector3& na = td.normals[td.indices[i]];
            const Vector3& nb = td.normals[td.indices[i + 1]];
            const Vector3& nc = td.normals[td.indices[i + 2]];
            outNormal = Vector3(
                na.m_X + u * (nc.m_X - na.m_X) + v * (nb.m_X - na.m_X),
                na.m_Y + u * (nc.m_Y - na.m_Y) + v * (nb.m_Y - na.m_Y),
                na.m_Z + u * (nc.m_Z - na.m_Z) + v * (nb.m_Z - na.m_Z));
            NormalizeInPlace(outNormal);
        }
        hintTriangle = i;
        return true;
    }
    return false;
}

static Vector3 QuatRotateVector(const Vector4& q, const Vector3& v)
{
    float x = q.m_X, y = q.m_Y, z = q.m_Z, w = q.m_W;
    float uvx = y * v.m_Z - z * v.m_Y;
    float uvy = z * v.m_X - x * v.m_Z;
    float uvz = x * v.m_Y - y * v.m_X;
    float uuvx = y * uvz - z * uvy;
    float uuvy = z * uvx - x * uvz;
    float uuvz = x * uvy - y * uvx;
    return Vector3(
        v.m_X + 2.0f * (w * uvx + uuvx),
        v.m_Y + 2.0f * (w * uvy + uuvy),
        v.m_Z + 2.0f * (w * uvz + uuvz));
}

static char g_floorSupportName[64] = "none";

static uint32_t g_floorQueries = 0, g_floorTriVisits = 0;
static std::vector<uint32_t> g_floorModelVisits;
static const ModelData* g_floorModelBase = nullptr;

static bool GetModelFloorHeightAt(const ModelData& md, const PlacedInstance& pi,
    float worldX, float currentWorldY, float worldZ, float& outY,
    float acceptMaxWorldY, float acceptMinWorldY,
    float steepRejectAboveWorldY = 1e30f)
{
    if (md.floorTris.empty() || md.floorGrid.empty()) return false;

    Vector4 invRot(-pi.rotation.m_X, -pi.rotation.m_Y, -pi.rotation.m_Z, pi.rotation.m_W);
    Vector3 localPos = QuatRotateVector(invRot,
        Vector3(worldX - pi.position.m_X, currentWorldY - pi.position.m_Y, worldZ - pi.position.m_Z));

    const int32_t cx = (int32_t)floorf(localPos.m_X / SEGMENT_GRID_CELL);
    const int32_t cz = (int32_t)floorf(localPos.m_Z / SEGMENT_GRID_CELL);
    auto cellIt = md.floorGrid.find(PackGridCell(cx, cz));
    ++g_floorQueries;
    if (cellIt == md.floorGrid.end()) return false;
    g_floorTriVisits += (uint32_t)cellIt->second.size();
    if (g_floorModelBase && &md >= g_floorModelBase && (size_t)(&md - g_floorModelBase) < g_floorModelVisits.size())
        g_floorModelVisits[(size_t)(&md - g_floorModelBase)] += (uint32_t)cellIt->second.size();

    bool found = false;
    float bestLocalY = 0.0f;
    for (uint32_t ti : cellIt->second)
    {
        const CollisionFloorTri& tri = md.floorTris[ti];
        const float v0x = tri.localC.m_X - tri.localA.m_X, v0z = tri.localC.m_Z - tri.localA.m_Z;
        const float v1x = tri.localB.m_X - tri.localA.m_X, v1z = tri.localB.m_Z - tri.localA.m_Z;
        const float v2x = localPos.m_X - tri.localA.m_X, v2z = localPos.m_Z - tri.localA.m_Z;
        const float dot00 = v0x * v0x + v0z * v0z;
        const float dot01 = v0x * v1x + v0z * v1z;
        const float dot02 = v0x * v2x + v0z * v2z;
        const float dot11 = v1x * v1x + v1z * v1z;
        const float dot12 = v1x * v2x + v1z * v2z;
        const float denom = dot00 * dot11 - dot01 * dot01;
        if (fabsf(denom) < 0.00001f) continue;
        const float invDenom = 1.0f / denom;
        const float u = (dot11 * dot02 - dot01 * dot12) * invDenom;
        const float v = (dot00 * dot12 - dot01 * dot02) * invDenom;
        if (u < -0.001f || v < -0.001f || (u + v) > 1.001f) continue;

        const float localY = tri.localA.m_Y + u * (tri.localC.m_Y - tri.localA.m_Y) + v * (tri.localB.m_Y - tri.localA.m_Y);

        const float worldYHere = pi.position.m_Y + localY;
        if (worldYHere > acceptMaxWorldY || worldYHere < acceptMinWorldY) continue;
        if (worldYHere > steepRejectAboveWorldY)
        {

            const float e1x = tri.localB.m_X - tri.localA.m_X, e1y = tri.localB.m_Y - tri.localA.m_Y, e1z = tri.localB.m_Z - tri.localA.m_Z;
            const float e2x = tri.localC.m_X - tri.localA.m_X, e2y = tri.localC.m_Y - tri.localA.m_Y, e2z = tri.localC.m_Z - tri.localA.m_Z;
            const float nx = e1y * e2z - e1z * e2y, ny = e1z * e2x - e1x * e2z, nz = e1x * e2y - e1y * e2x;
            const float nl = sqrtf(nx * nx + ny * ny + nz * nz);
            if (nl > 1e-6f && fabsf(ny) / nl < AI_WALKABLE_NY_MIN) continue;
        }
        if (!found || localY > bestLocalY) { bestLocalY = localY; found = true; }
    }
    if (!found) return false;
    outY = pi.position.m_Y + bestLocalY;
    return true;
}

static float g_lastRefusedY = 0.0f;
static size_t g_lastRefusedPlaced = SIZE_MAX;

static bool GetCombinedGroundHeightAt(const TerrainData& terrainData, const std::vector<ModelData>& uniqueModels,
    const std::vector<PlacedInstance>& placed, float x, float currentY, float z,
    uint32_t& terrainHint, float& outY, Vector3& outNormal, size_t selfIndex = SIZE_MAX,
    bool recordDiag = false,
    bool aiWalker = false,
    bool* outRefusedStep = nullptr)
{
    size_t refusedPlaced = SIZE_MAX;
    float refusedY = -1e30f;

    float terrainY = 0.0f;
    Vector3 terrainN(0.0f, 1.0f, 0.0f);
    const bool terrainFound = GetTerrainHeightAt(terrainData, x, z, terrainY, terrainN, terrainHint);
    bool have = false;

    const float FLOOR_STEP_TOLERANCE = 1.78f;

    const float FLOOR_FALL_TOLERANCE = 8.0f;
    for (size_t fpi = 0; fpi < placed.size(); ++fpi)
    {
        if (fpi == selfIndex) continue;
        const PlacedInstance& fp = placed[fpi];
        if (fp.modelIndex >= uniqueModels.size()) continue;
        const ModelData& fmd = uniqueModels[fp.modelIndex];
        if (fmd.floorTris.empty()) continue;

        Vector3 rc = QuatRotateVector(fp.rotation, fmd.boundCenter);
        float bx = fp.position.m_X + rc.m_X, bz = fp.position.m_Z + rc.m_Z;
        float dx = bx - x, dz = bz - z;
        float reach = fmd.boundRadius + 2.0f;
        if (dx * dx + dz * dz > reach * reach) continue;

        float floorY;

        const float modelStepReach = aiWalker ? AI_STEP_UP_REACH : FLOOR_STEP_TOLERANCE;
        const bool aiFloorFound = GetModelFloorHeightAt(fmd, fp, x, currentY, z, floorY,
                currentY + modelStepReach, currentY - FLOOR_FALL_TOLERANCE,
                aiWalker ? currentY + 0.05f : 1e30f);

        if (aiWalker && outRefusedStep)
        {
            float legacyY;
            if (GetModelFloorHeightAt(fmd, fp, x, currentY, z, legacyY,
                    currentY + FLOOR_STEP_TOLERANCE, currentY - FLOOR_FALL_TOLERANCE)
                && (!aiFloorFound || legacyY > floorY + 0.05f)
                && legacyY > refusedY)
            {
                refusedY = legacyY;
                refusedPlaced = fpi;
            }
        }
        if (!aiFloorFound) continue;

        if (floorY > currentY + modelStepReach) continue;
        if (floorY < currentY - FLOOR_FALL_TOLERANCE) continue;
        if (!have || floorY > outY)
        {
            outY = floorY;
            outNormal = Vector3(0.0f, 1.0f, 0.0f);
            have = true;
            if (recordDiag) snprintf(g_floorSupportName, sizeof(g_floorSupportName), "%s", fmd.debugName.c_str());
        }
    }

    if (terrainFound && terrainY <= currentY + FLOOR_STEP_TOLERANCE)
    {
        if (!have || terrainY > outY)
        {
            outY = terrainY;
            outNormal = terrainN;
            have = true;
            if (recordDiag) snprintf(g_floorSupportName, sizeof(g_floorSupportName), "terrain");
        }
    }
    if (!have && recordDiag) snprintf(g_floorSupportName, sizeof(g_floorSupportName), "NONE");
    if (outRefusedStep)
    {
        *outRefusedStep = (refusedY > -1e29f) && (!have || refusedY > outY + 0.05f);
        if (*outRefusedStep) { g_lastRefusedY = refusedY; g_lastRefusedPlaced = refusedPlaced; }
    }

    const float LOST_BELOW_WORLD = 100.0f;
    if (!have && terrainFound && currentY < terrainY - LOST_BELOW_WORLD)
    {
        outY = terrainY;
        outNormal = terrainN;
        have = true;
    }
    return have;
}

static bool GetGroundUnderFootprint(const TerrainData& terrainData, const std::vector<ModelData>& uniqueModels,
    const std::vector<PlacedInstance>& placed, float x, float currentY, float z,
    uint32_t& terrainHint, float& outY, Vector3& outNormal, size_t selfIndex,
    bool recordDiag, bool aiWalker, bool* outRefusedStep)
{
    bool found = GetCombinedGroundHeightAt(terrainData, uniqueModels, placed, x, currentY, z, terrainHint,
                                           outY, outNormal, selfIndex, recordDiag, aiWalker, outRefusedStep);
    if (outRefusedStep && *outRefusedStep) return found;
    const float FOOT_DROP = 0.25f;
    if (found && outY >= currentY - FOOT_DROP) return true;
    const float FOOT_R = 0.3f;
    const float offs[4][2] = { { FOOT_R, 0.0f }, { -FOOT_R, 0.0f }, { 0.0f, FOOT_R }, { 0.0f, -FOOT_R } };
    for (int k = 0; k < 4; ++k)
    {
        float oy = 0.0f; Vector3 on; uint32_t hint = terrainHint;
        if (GetCombinedGroundHeightAt(terrainData, uniqueModels, placed, x + offs[k][0], currentY, z + offs[k][1], hint,
                                      oy, on, selfIndex, false, aiWalker, nullptr)
            && (!found || oy > outY))
        {
            outY = oy; outNormal = on; found = true;
        }
    }
    return found;
}

static bool GetCeilingHeightAt(const std::vector<ModelData>& uniqueModels,
    const std::vector<PlacedInstance>& placed, float x, float z,
    float fromHeadY, float toHeadY, float& outY, size_t selfIndex = SIZE_MAX)
{
    if (toHeadY <= fromHeadY) return false;
    bool found = false;
    for (size_t fpi = 0; fpi < placed.size(); ++fpi)
    {
        if (fpi == selfIndex) continue;
        const PlacedInstance& fp = placed[fpi];
        if (fp.modelIndex >= uniqueModels.size()) continue;
        const ModelData& fmd = uniqueModels[fp.modelIndex];
        if (fmd.floorTris.empty() || fmd.floorGrid.empty()) continue;

        Vector3 rc = QuatRotateVector(fp.rotation, fmd.boundCenter);
        float bx = fp.position.m_X + rc.m_X, bz = fp.position.m_Z + rc.m_Z;
        float dx = bx - x, dz = bz - z;
        float reach = fmd.boundRadius + 2.0f;
        if (dx * dx + dz * dz > reach * reach) continue;

        Vector4 invRot(-fp.rotation.m_X, -fp.rotation.m_Y, -fp.rotation.m_Z, fp.rotation.m_W);
        Vector3 localPos = QuatRotateVector(invRot,
            Vector3(x - fp.position.m_X, toHeadY - fp.position.m_Y, z - fp.position.m_Z));
        const int32_t cx = (int32_t)floorf(localPos.m_X / SEGMENT_GRID_CELL);
        const int32_t cz = (int32_t)floorf(localPos.m_Z / SEGMENT_GRID_CELL);
        auto cellIt = fmd.floorGrid.find(PackGridCell(cx, cz));
        if (cellIt == fmd.floorGrid.end()) continue;

        for (uint32_t ti : cellIt->second)
        {
            const CollisionFloorTri& tri = fmd.floorTris[ti];
            const float v0x = tri.localC.m_X - tri.localA.m_X, v0z = tri.localC.m_Z - tri.localA.m_Z;
            const float v1x = tri.localB.m_X - tri.localA.m_X, v1z = tri.localB.m_Z - tri.localA.m_Z;
            const float v2x = localPos.m_X - tri.localA.m_X, v2z = localPos.m_Z - tri.localA.m_Z;
            const float dot00 = v0x * v0x + v0z * v0z;
            const float dot01 = v0x * v1x + v0z * v1z;
            const float dot02 = v0x * v2x + v0z * v2z;
            const float dot11 = v1x * v1x + v1z * v1z;
            const float dot12 = v1x * v2x + v1z * v2z;
            const float denom = dot00 * dot11 - dot01 * dot01;
            if (fabsf(denom) < 0.00001f) continue;
            const float invDenom = 1.0f / denom;
            const float u = (dot11 * dot02 - dot01 * dot12) * invDenom;
            const float v = (dot00 * dot12 - dot01 * dot02) * invDenom;
            if (u < -0.001f || v < -0.001f || (u + v) > 1.001f) continue;

            const float localY = tri.localA.m_Y + u * (tri.localC.m_Y - tri.localA.m_Y) + v * (tri.localB.m_Y - tri.localA.m_Y);
            const float worldYHere = fp.position.m_Y + localY;

            if (worldYHere <= fromHeadY || worldYHere > toHeadY) continue;
            if (!found || worldYHere < outY) { outY = worldYHere; found = true; }
        }
    }
    return found;
}

static uint8_t g_axisCentreLX = 128, g_axisCentreLY = 128;
static uint8_t g_axisCentreRX = 128, g_axisCentreRY = 128;
static bool    g_axisCalibrated = false;

static float ReadAxisFrom(uint8_t raw, uint8_t centre)
{

    if (centre < 96 || centre > 160) centre = 128;
    const float span = 128.0f;
    float v = ((float)raw - (float)centre) / span;
    if (v > 1.0f) v = 1.0f;
    if (v < -1.0f) v = -1.0f;
    const float deadzone = 0.15f;
    if (fabsf(v) < deadzone) return 0.0f;
    float sign = (v > 0.0f) ? 1.0f : -1.0f;
    return sign * ((fabsf(v) - deadzone) / (1.0f - deadzone));
}

static float ReadAxis(uint8_t raw) { return ReadAxisFrom(raw, 128); }

static Vector3 GetForward(float yaw, float pitch)
{
    return Vector3(-cosf(pitch) * sinf(yaw), sinf(pitch), -cosf(pitch) * cosf(yaw));
}

static Vector3 GetRight(float yaw)
{
    return Vector3(cosf(yaw), 0.0f, -sinf(yaw));
}

static float YawFromForward(float fx, float fz)
{
    return atan2f(-fx, -fz);
}

static void QuatToMatrix(const Vector4& qIn, float m[16])
{
    float x = qIn.m_X, y = qIn.m_Y, z = qIn.m_Z, w = qIn.m_W;
    float len = sqrtf(x * x + y * y + z * z + w * w);
    if (len < 0.00001f) { x = y = z = 0.0f; w = 1.0f; }
    else { x /= len; y /= len; z /= len; w /= len; }

    const float xx = x * x, yy = y * y, zz = z * z;
    const float xy = x * y, xz = x * z, yz = y * z;
    const float wx = w * x, wy = w * y, wz = w * z;

    m[0] = 1.0f - 2.0f * (yy + zz); m[1] = 2.0f * (xy + wz);        m[2] = 2.0f * (xz - wy);        m[3] = 0.0f;
    m[4] = 2.0f * (xy - wz);        m[5] = 1.0f - 2.0f * (xx + zz); m[6] = 2.0f * (yz + wx);        m[7] = 0.0f;
    m[8] = 2.0f * (xz + wy);        m[9] = 2.0f * (yz - wx);        m[10] = 1.0f - 2.0f * (xx + yy); m[11] = 0.0f;
    m[12] = 0.0f;                   m[13] = 0.0f;                   m[14] = 0.0f;                    m[15] = 1.0f;
}

struct Glyph { char c; uint8_t rows[5]; };

static const Glyph FONT_GLYPHS[] = {
    {'0', {7,5,5,5,7}}, {'1', {2,6,2,2,7}}, {'2', {7,1,7,4,7}},
    {'3', {7,1,7,1,7}}, {'4', {5,5,7,1,1}}, {'5', {7,4,7,1,7}},
    {'6', {7,4,7,5,7}}, {'7', {7,1,1,1,1}}, {'8', {7,5,7,5,7}},
    {'9', {7,5,7,1,7}},
    {'A', {2,5,7,5,5}}, {'B', {6,5,6,5,6}}, {'C', {3,4,4,4,3}},
    {'D', {6,5,5,5,6}}, {'E', {7,4,6,4,7}}, {'F', {7,4,7,4,4}},
    {'G', {3,4,5,5,3}}, {'H', {5,5,7,5,5}}, {'I', {7,2,2,2,7}},
    {'J', {1,1,1,5,2}}, {'K', {5,5,6,5,5}}, {'L', {4,4,4,4,7}},
    {'M', {5,7,5,5,5}}, {'N', {5,7,7,5,5}}, {'O', {2,5,5,5,2}},
    {'P', {7,5,7,4,4}}, {'Q', {2,5,5,7,3}}, {'R', {6,5,6,5,5}},
    {'S', {7,4,7,1,7}}, {'T', {7,2,2,2,2}}, {'U', {5,5,5,5,2}},
    {'V', {5,5,5,5,2}}, {'W', {5,5,5,7,5}}, {'X', {5,5,2,5,5}},
    {'Y', {5,5,2,2,2}}, {'Z', {7,1,2,4,7}},
    {':', {0,2,0,2,0}}, {'.', {0,0,0,0,2}}, {'-', {0,0,7,0,0}},
    {' ', {0,0,0,0,0}},
};
static const uint8_t* FindGlyph(char c)
{
    if (c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
    for (size_t i = 0; i < sizeof(FONT_GLYPHS) / sizeof(FONT_GLYPHS[0]); ++i)
    {
        if (FONT_GLYPHS[i].c == c) return FONT_GLYPHS[i].rows;
    }
    return FONT_GLYPHS[sizeof(FONT_GLYPHS) / sizeof(FONT_GLYPHS[0]) - 1].rows;
}

struct RenderPass
{
    bool cull, depthTest, depthWrite, blend, lighting, fog, texture2D;
    GLenum blendSrc, blendDst;
    float r, g, b, a;
    GLenum matrixMode;

    bool alphaTest = false;
};

static bool g_worldAlphaMask = false;

static bool g_opaqueAlphaWrite = true;
static void ApplyPass(const RenderPass& p)
{
    if (p.cull) glEnable(GL_CULL_FACE); else glDisable(GL_CULL_FACE);
    if (p.depthTest) glEnable(GL_DEPTH_TEST); else glDisable(GL_DEPTH_TEST);
    glDepthMask(p.depthWrite ? GL_TRUE : GL_FALSE);
    if (p.blend) { glEnable(GL_BLEND); glBlendFunc(p.blendSrc, p.blendDst); }
    else glDisable(GL_BLEND);
    if (p.lighting) glEnable(GL_LIGHTING); else glDisable(GL_LIGHTING);
    if (p.fog) glEnable(GL_FOG); else glDisable(GL_FOG);
    if (p.texture2D) glEnable(GL_TEXTURE_2D); else glDisable(GL_TEXTURE_2D);
    if (p.alphaTest) glEnable(GL_ALPHA_TEST); else glDisable(GL_ALPHA_TEST);
    glColorMask(GL_TRUE, GL_TRUE, GL_TRUE, g_worldAlphaMask ? GL_FALSE : GL_TRUE);
    glColor4f(p.r, p.g, p.b, p.a);
    glMatrixMode(p.matrixMode);
}

