static void SaveScreenshotTGA(const std::string& name)
{
    std::vector<uint8_t> px((size_t)SCREEN_W * SCREEN_H * 4);
    glReadPixels(0, 0, SCREEN_W, SCREEN_H, GL_RGBA, GL_UNSIGNED_BYTE, px.data());
    const std::string path = "ux0:data/swbf2/shot_" + name + ".tga";
    FILE* f = fopen(path.c_str(), "wb");
    if (f == nullptr) { checkpointf("M452 screenshot: could not open %s", path.c_str()); return; }
    uint8_t hdr[18] = {0};
    hdr[2] = 2; hdr[12] = SCREEN_W & 0xff; hdr[13] = SCREEN_W >> 8; hdr[14] = SCREEN_H & 0xff; hdr[15] = SCREEN_H >> 8; hdr[16] = 24;
    fwrite(hdr, 1, 18, f);
    std::vector<uint8_t> row((size_t)SCREEN_W * 3);
    for (int y = 0; y < SCREEN_H; ++y)
    {
        const uint8_t* src = &px[(size_t)y * SCREEN_W * 4];
        for (int x = 0; x < SCREEN_W; ++x) { row[x * 3] = src[x * 4 + 2]; row[x * 3 + 1] = src[x * 4 + 1]; row[x * 3 + 2] = src[x * 4]; }
        fwrite(row.data(), 1, row.size(), f);
    }
    fclose(f);
    checkpointf("M452 screenshot saved: %s", path.c_str());
}

