static bool UiSpawnFlowActive()
{
    if (g_uiStack.empty()) return false;

    for (size_t i = g_uiStack.size(); i-- > 0; )
    {
        const UiScreenId id = g_uiStack[i].id;
        if (id == UI_SCREEN_FACTION || id == UI_SCREEN_POST || id == UI_SCREEN_UNIT) return true;
        if (id == UI_SCREEN_PAUSE) continue;
        break;
    }
    return false;
}

