{
    return !g_uiStack.empty() && g_uiStack.back().pausesGame;
}
static UiScreenState* UiTop() { return g_uiStack.empty() ? nullptr : &g_uiStack.back(); }

static void UiMoveCursor(UiScreenState& scr, int delta)
{
    if (scr.rows.empty()) return;
    const int n = (int)scr.rows.size();
    int i = scr.cursor;
    for (int step = 0; step < n; ++step)
    {
        i = (i + delta + n) % n;
        if (scr.rows[(size_t)i].selectable) { scr.cursor = i; return; }
    }
}

static void UiPush(const UiScreenState& scr)
{
    g_uiStack.push_back(scr);
    g_uiOpenAnimSec = 0.0f;
    UiScreenState& top = g_uiStack.back();
    if (!top.rows.empty() && !top.rows[(size_t)top.cursor].selectable)
        UiMoveCursor(top, +1);
    checkpointf("MILESTONE 122 - UI screen pushed (\"%s\"), depth %u",
        top.title.c_str(), (unsigned)g_uiStack.size());
}

static void UiPop()
{
    if (g_uiStack.empty()) return;
    checkpointf("MILESTONE 122 - UI screen popped (\"%s\"), depth %u",
        g_uiStack.back().title.c_str(), (unsigned)g_uiStack.size() - 1);
    g_uiStack.pop_back();
}

static void UiHandleInput(uint32_t buttons, uint32_t prevButtons)
{
    g_uiConsumedInputThisFrame = false;
    UiScreenState* scr = UiTop();
    if (scr == nullptr) return;
    g_uiConsumedInputThisFrame = true;

    const uint32_t pressed = buttons & ~prevButtons;
    if (scr->id == UI_SCREEN_MISSIONEND) return;

    if (!g_selPauseOldDbg && (pressed & SCE_CTRL_START)
        && (scr->id == UI_SCREEN_FACTION || scr->id == UI_SCREEN_POST || scr->id == UI_SCREEN_UNIT))
    {

        const int sid = (int)scr->id;
        const std::string stitle = scr->title;
        g_uiSwallowButtons |= SCE_CTRL_START;
        UiOpenPauseMenu();
        checkpointf("SELPAUSE [N3]: START on screen %d \"%s\" -> pause menu pushed (depth %u)",
                    sid, stitle.c_str(), (unsigned)g_uiStack.size());
        return;
    }

    if (scr->id == UI_SCREEN_POST)
    {
        UiRefreshPostScreen(*scr);
        int dx = 0, dy = 0;
        if (pressed & SCE_CTRL_LEFT) dx = -1; else if (pressed & SCE_CTRL_RIGHT) dx = 1;
        else if (pressed & SCE_CTRL_UP) dy = -1; else if (pressed & SCE_CTRL_DOWN) dy = 1;
        if (dx != 0 || dy != 0)
        {
            float cx0 = 0.0f, cy0 = 0.0f, best = 1e9f; int bestRow = -1;
            const bool haveCur = UiMapProject(scr->rows.empty() ? 0.0f : scr->mapX[(size_t)scr->cursor],
                                              scr->rows.empty() ? 0.0f : scr->mapZ[(size_t)scr->cursor], 0.0f, 0.0f, 1.0f, cx0, cy0);
            for (size_t i = 0; haveCur && i < scr->rows.size(); ++i)
            {
                if ((int)i == scr->cursor || !scr->rows[i].selectable) continue;
                float sx = 0.0f, sy = 0.0f;
                UiMapProject(scr->mapX[i], scr->mapZ[i], 0.0f, 0.0f, 1.0f, sx, sy);
                const float ex = sx - cx0, ey = sy - cy0;
                const float along = ex * dx + ey * dy;
                if (along <= 0.0f) continue;
                const float across = fabsf(ex * dy) + fabsf(ey * dx);
                const float score = along + 2.0f * across;
                if (score < best) { best = score; bestRow = (int)i; }
            }
            if (bestRow >= 0) { scr->cursor = bestRow; PlayUiSoundEffect(UI_SFX_NAVIGATE); }
        }
        if (pressed & SCE_CTRL_CROSS)
        {
            if (!scr->rows.empty() && scr->rows[(size_t)scr->cursor].selectable)
            {
                g_uiSwallowButtons |= SCE_CTRL_CROSS;
                PlayUiSoundEffect(UI_SFX_CONFIRM);
                g_uiPendingAction = scr->rows[(size_t)scr->cursor].action;
                g_uiPendingRow = scr->cursor;
                checkpointf("MILESTONE 123 - UI accept: row %d (\"%s\") action %d", scr->cursor,
                            scr->rows[(size_t)scr->cursor].label.c_str(), g_uiPendingAction);
            }
        }
        return;
    }
    if (scr->id == UI_SCREEN_UNIT && !scr->rows.empty())
    {
        if (pressed & SCE_CTRL_LEFT)  { UiMoveCursor(*scr, -1); PlayUiSoundEffect(UI_SFX_NAVIGATE); }
        if (pressed & SCE_CTRL_RIGHT) { UiMoveCursor(*scr, +1); PlayUiSoundEffect(UI_SFX_NAVIGATE); }
        if (pressed & SCE_CTRL_CIRCLE)
        {
            g_uiSwallowButtons |= SCE_CTRL_CIRCLE;
            PlayUiSoundEffect(UI_SFX_CANCEL);
            g_uiPendingAction = UI_ACT_BACK_TO_POST;
            return;
        }
    }
    if (scr->id == UI_SCREEN_FACTION && (pressed & SCE_CTRL_CIRCLE)) return;

    if ((pressed & SCE_CTRL_UP) && !scr->rows.empty())
    {
        UiMoveCursor(*scr, -1);
        PlayUiSoundEffect(UI_SFX_NAVIGATE);
    }
    if ((pressed & SCE_CTRL_DOWN) && !scr->rows.empty())
    {
        UiMoveCursor(*scr, +1);
        PlayUiSoundEffect(UI_SFX_NAVIGATE);
    }
    if (pressed & SCE_CTRL_CIRCLE)
    {
        g_uiSwallowButtons |= SCE_CTRL_CIRCLE;
        PlayUiSoundEffect(UI_SFX_CANCEL);
        UiPop();
        return;
    }
    if (pressed & SCE_CTRL_CROSS)
    {
        if (!scr->rows.empty() && scr->rows[(size_t)scr->cursor].selectable)
        {

            if (scr->id == UI_SCREEN_UNIT && (size_t)scr->cursor < g_uiUnitRoster.size()
                && UiUnitClassLocked(g_uiUnitRoster[(size_t)scr->cursor]))
            {
                g_uiSwallowButtons |= SCE_CTRL_CROSS;
                PlayUiSoundEffect(UI_SFX_CANCEL);
                ++g_unlockRefusals;
                checkpointf("UNLOCK: \"%s\" refused - %d points, needs %d (Get %d more)",
                    g_uiUnitRoster[(size_t)scr->cursor].c_str(), UiPlayerPoints(),
                    UiUnlockCostOf(g_uiUnitRoster[(size_t)scr->cursor]),
                    UiUnitClassLockedPointsLeft(g_uiUnitRoster[(size_t)scr->cursor]));
                return;
            }
            g_uiSwallowButtons |= SCE_CTRL_CROSS;
            PlayUiSoundEffect(UI_SFX_CONFIRM);
            g_uiPendingAction = scr->rows[(size_t)scr->cursor].action;
            g_uiPendingRow = scr->cursor;
            checkpointf("MILESTONE 123 - UI accept: row %d (\"%s\") action %d",
                scr->cursor, scr->rows[(size_t)scr->cursor].label.c_str(),
                g_uiPendingAction);
        }
    }
}

