static const int DYN_LIGHTS = 2;
struct DynLight { Vector3 pos; float radius; float r, g, b; float age, life; float raw = 1.0f; };
static std::vector<DynLight> g_dynLights;
static float g_dynWorld[DYN_LIGHTS][4] = {};
static float g_dynCol[DYN_LIGHTS][4] = {};
static float g_dynEye[DYN_LIGHTS][4] = {};
static void AddDynLight(const Vector3& pos, float radius, const float rgba[4], float life)
{
    if (radius <= 0.0f || life <= 0.0f) return;
    if (g_dynLights.size() >= 16) g_dynLights.erase(g_dynLights.begin());
    const float a = rgba[3] / 255.0f;
    g_dynLights.push_back(DynLight{ pos, radius, rgba[0] / 255.0f * a, rgba[1] / 255.0f * a, rgba[2] / 255.0f * a, 0.0f, life, a > 0.0f ? 1.0f / a : 1.0f });
}

static const float SHAKE_DEG_PER_UNIT = 4.0f;
static float g_camShakeAmp = 0.0f, g_camShakeLeft = 0.0f, g_camShakeLen = 0.0f;
static void AddCameraShake(float amount, float length)
{
    if (amount <= 0.0f || length <= 0.0f) return;
    const float cur = (g_camShakeLen > 0.0f) ? g_camShakeAmp * (g_camShakeLeft / g_camShakeLen) : 0.0f;
    if (amount < cur) return;
    g_camShakeAmp = amount; g_camShakeLeft = length; g_camShakeLen = length;
}
static void DynLightsToEye(const float view[16])
{
    for (int i = 0; i < DYN_LIGHTS; ++i)
    {
        const float* w = g_dynWorld[i];
        g_dynEye[i][0] = view[0] * w[0] + view[4] * w[1] + view[8]  * w[2] + view[12];
        g_dynEye[i][1] = view[1] * w[0] + view[5] * w[1] + view[9]  * w[2] + view[13];
        g_dynEye[i][2] = view[2] * w[0] + view[6] * w[1] + view[10] * w[2] + view[14];
        g_dynEye[i][3] = w[3];
    }
}

#define DYN_LIGHT_CG \
"uniform float4 UdynPos[2];\n" \
"uniform float4 UdynCol[2];\n" \
"float3 DynLight(float3 p, float3 n)\n" \
"{\n" \
"    float3 sum = float3(0.0f, 0.0f, 0.0f);\n" \
"    for (int i = 0; i < 2; i++)\n" \
"    {\n" \
"        float3 L = UdynPos[i].xyz - p;\n" \
"        float d = length(L);\n" \
"        float att = clamp(1.0f - d / max(UdynPos[i].w, 0.001f), 0.0f, 1.0f);\n" \
"        sum += UdynCol[i].rgb * (att * max(0.0f, dot(n, L / max(d, 0.001f))));\n" \
"    }\n" \
"    return sum;\n" \
"}\n"

static const int SHADOW_MAP_SIZE = 1024;
static const float SHADOW_MAP_HALF_M = 18.0f;
static const float SHADOW_MAP_BIAS = 0.006f;
static GLuint g_smTex = 0, g_smFbo = 0, g_smRb = 0, g_smProg = 0;
static bool g_smOk = false, g_smActive = false;
static GLint g_uSmMvp = -1, g_uSmBones = -1, g_uSmReach = -1;
static float g_smTexVP[16];
static uint32_t g_smCastersDrawn = 0;
static bool g_smDebugDraw = false;
static bool g_smSampleOff = false;
static bool g_smDebugTerrain = false;
static uint64_t g_smUs = 0;

static float g_shadowFactorForMap = 0.6f;
static void Mat4MultiplySm(const float a[16], const float b[16], float out[16])
{
    for (int c = 0; c < 4; ++c)
        for (int r = 0; r < 4; ++r)
            out[c * 4 + r] = a[0 * 4 + r] * b[c * 4 + 0] + a[1 * 4 + r] * b[c * 4 + 1] + a[2 * 4 + r] * b[c * 4 + 2] + a[3 * 4 + r] * b[c * 4 + 3];
}

static void BindShadowReceiver(GLint pLoc, GLint texLoc, bool receive = true)
{
    const float p[4] = { (g_smActive && !g_smSampleOff && receive) ? 1.0f : 0.0f, g_shadowFactorForMap, SHADOW_MAP_BIAS, 1.0f / (float)SHADOW_MAP_SIZE };
    if (pLoc >= 0) glUniform4fv(pLoc, 1, p);
    if (texLoc >= 0) glUniform1i(texLoc, 1);
    glActiveTexture(GL_TEXTURE1);
    glBindTexture(GL_TEXTURE_2D, g_smActive ? g_smTex : 0);
    glActiveTexture(GL_TEXTURE0);
}

static void SetShadowReceiverModel(GLint mvpLoc, const float model[16])
{
    if (mvpLoc < 0) return;
    float m[16]; Mat4MultiplySm(g_smTexVP, model, m);
    glUniformMatrix4fv(mvpLoc, 1, GL_FALSE, m);
}
static const char* kSkinVertCg = DYN_LIGHT_CG R"(
uniform float4x4 Umv;
uniform float4x4 Uproj;
uniform float4 Ubones[192];
uniform float3 UlightDir;
uniform float3 Ulight2Dir;  // M496: the level's Light2 (cor1 "BACK"), eye space
uniform float4 Ulight2Col;
uniform float4 UlightAmb;   // M457: Bottom ambient
uniform float4 UlightDiff;  // M457: sun colour
uniform float4 UlightDiff2; // M457: Top ambient
uniform float3 UupEye;      // M457: world +Y in eye space
uniform float4 UglobalAmb;
uniform float4 Ucolor;
uniform float Ulit;
uniform float2 UuvOff;
uniform float4x4 UshadowMvp; // M473: model -> shadow-map texture space
uniform float4 Uspec;        // M485: specular colour x sun (rgb), exponent (a)
void main(float3 aPos, float3 aNormal, float2 aUV, float aBone,
    float4 out vColor : COLOR, float2 out vUV : TEXCOORD0, float4 out vShadow : TEXCOORD1, float3 out vSpec : TEXCOORD2, float4 out gl_Position : POSITION)
{
    int b = (int)aBone * 3;
    float4 p4 = float4(aPos, 1.0f);
    float3 p = float3(dot(Ubones[b], p4), dot(Ubones[b + 1], p4), dot(Ubones[b + 2], p4));
    float3 n = float3(dot(Ubones[b].xyz, aNormal), dot(Ubones[b + 1].xyz, aNormal), dot(Ubones[b + 2].xyz, aNormal));
    float4 mvPos = mul(float4(p, 1.0f), Umv);
    gl_Position = mul(mvPos, Uproj);
    float3 en = normalize(mul(float4(n, 0.0f), Umv).xyz);
    float ndl = max(0.0f, dot(en, UlightDir));
    // MILESTONE 457: the real directional ambient - Bottom..Top by how far
    // the normal faces world-up (UupEye: world +Y in eye space) - plus the
    // real sun. The old vitaGL-default 0.2 global ambient is gone.
    float t = dot(en, UupEye) * 0.5f + 0.5f;
    float4 amb = lerp(UlightAmb, UlightDiff2, t);
    float4 lit = amb * Ucolor + UlightDiff * Ucolor * ndl;
    lit.rgb += Ulight2Col.rgb * Ucolor.rgb * max(0.0f, dot(en, Ulight2Dir)); // M496
    lit.rgb += DynLight(mvPos.xyz, en) * Ucolor.rgb; // M462
    lit.rgb /= max(max(lit.r, max(lit.g, lit.b)), 1.0f); // M530: T1 lighting_diffuse.h - scaled by its brightest channel, not clamped per channel
    vColor = lerp(Ucolor, clamp(lit, 0.0f, 1.0f), Ulit);
    vUV = aUV + UuvOff;
    vShadow = mul(float4(p, 1.0f), UshadowMvp);
    float3 hv = normalize(UlightDir + normalize(-mvPos.xyz));
    vSpec = (ndl > 0.0f) ? Uspec.rgb * pow(max(0.0f, dot(en, hv)), max(Uspec.a, 1.0f)) : float3(0.0f, 0.0f, 0.0f); // M485
}
)";
static const char* kSkinFragCg = R"(
uniform sampler2D Utex;
uniform float UuseTex;
uniform float UalphaCut;
uniform float4 UfogColor;
uniform float UfogRange;
uniform float UfogFar;
uniform float UfogOn;
uniform sampler2D UshadowMap : TEXUNIT1; // M473: the shadow map (packed depth, see kShadowCasterFragCg)
uniform float4 UshadowP;                 // x on, y lit-to-shadow factor, z depth bias, w texel size
uniform float Ugloss;                    // M485: 1 = the specular is masked by the texture alpha (Glossmap)
uniform float2 Ufade;                    // M486: keep the pixel when x <= dither < 1 - y (distance fade, LOD crossfade); (0,0) keeps all
uniform sampler2D UskyTex : TEXUNIT7;    // M541 (FOG): the sky alone (g_skyFarTex) - what the PS2's near scene fades into
uniform float4 UskyFar;                  // x on, yz 1 / the target's size (WPOS -> uv)
uniform float UalphaOut;                 // M541: x the alpha written (0 = "does not glow" for an opaque draw, see g_worldAlphaMask)
uniform float2 UfogBand;                 // M541: the far-scene fog's near/far band (g_fogBand)
float4 main(float4 vColor : COLOR, float2 vUV : TEXCOORD0, float4 vShadow : TEXCOORD1, float3 vSpec : TEXCOORD2, float4 coords : WPOS) : COLOR
{
    // PERF: the dither only exists for a fade (distance fade / LOD crossfade).
    // (0,0) keeps every pixel and the test below can never fire, so the 3 ALU
    // ops of the noise are skipped for every non-fading draw - trees, props,
    // most of the screen on a foliage map.
    if (Ufade.x > 0.0f || Ufade.y > 0.0f)
    {
        float dith = frac(52.9829189f * frac(dot(coords.xy, float2(0.06711056f, 0.00583715f)))); // interleaved gradient noise
        if (dith < Ufade.x || dith >= 1.0f - Ufade.y) discard;
    }
    float4 c = vColor;
    float4 t = float4(1.0f, 1.0f, 1.0f, 1.0f);
    if (UuseTex > 0.5f) { t = tex2D(Utex, vUV); c *= t; }
    if (c.a <= UalphaCut) discard;
    c.rgb += vSpec * ((Ugloss > 0.5f) ? t.a : 1.0f); // M485: the real material highlight
    if (Ugloss > 0.5f) c.a = vColor.a;              // the alpha was the gloss mask, not coverage
    if (UshadowP.x > 0.5f && vShadow.w > 0.0f)      // PERF: w = sun-facing; at 0 the shade is multiplied by 0 (exact skip)
    {
        float3 sc = vShadow.xyz;
        float edge = saturate(min(min(sc.x, 1.0f - sc.x), min(sc.y, 1.0f - sc.y)) * 20.0f);
        if (edge > 0.0f && sc.z < 1.0f)
        {
            // M474: filtered coverage, gated by the coarse depth (a wall in
            // FRONT of a caster, nearer the light, stays lit)
            float3 e = tex2D(UshadowMap, sc.xy).rgb;
            float shadowed = (1.0f - e.x) * ((sc.z - UshadowP.z > e.y) ? 1.0f : 0.0f);
            shadowed *= (sc.z <= e.z) ? 1.0f : 0.0f; // M530: within the caster's reach (not through the floor below)
            shadowed *= saturate(vShadow.w);         // M530: only surfaces facing the sun (not undersides)
            c.rgb *= lerp(1.0f, UshadowP.y, shadowed * edge);
        }
    }
    // PERF: no fog at all, or fully fogged past the far distance, means the
    // result is c.rgb unchanged - so the sky fetch (TEXUNIT7) and the two lerps
    // are skipped. Exact: f == 1 gives lerp(fogc, c, 1) == c for any fogc.
    if (UfogOn > 0.5f)
    {
        float fog_dist = coords.z / coords.w;
        float f = clamp((UfogFar - fog_dist) / UfogRange, 0.0f, 1.0f);
        if (UfogBand.y > 0.0f) f = 1.0f - (1.0f - f) * saturate((fog_dist - UfogBand.x) * UfogBand.y); // M541: no fog in the near scene
        if (f < 1.0f)
        {
            float3 fogc = UfogColor.rgb;
            if (UskyFar.x > 0.5f) fogc = tex2D(UskyTex, coords.xy * UskyFar.yz).rgb; // M541: fade into the sky behind, not a colour
            c.rgb = lerp(fogc, c.rgb, f); // M541 (fix 2026-10-28): f is VISIBILITY (1 near, 0 at the end) - the old order fogged the near scene and left the far one clear
        }
    }
    c.a *= UalphaOut;
    return c;
}
)";

static bool OpaqueFragCg(std::string& out)
{

    static const char* const kDropDither =
        "    if (Ufade.x > 0.0f || Ufade.y > 0.0f)\n"
        "    {\n"
        "        float dith = frac(52.9829189f * frac(dot(coords.xy, float2(0.06711056f, 0.00583715f)))); // interleaved gradient noise\n"
        "        if (dith < Ufade.x || dith >= 1.0f - Ufade.y) discard;\n"
        "    }";
    static const char* const kDropAlpha = "    if (c.a <= UalphaCut) discard;";
    out.assign(kSkinFragCg);
    const size_t pd = out.find(kDropDither), pa = out.find(kDropAlpha);
    if (pd == std::string::npos || pa == std::string::npos) return false;
    out.replace(pd, strlen(kDropDither), "    // M533 opaque variant: no dither discard");
    const size_t pa2 = out.find(kDropAlpha);
    if (pa2 == std::string::npos) return false;
    out.replace(pa2, strlen(kDropAlpha), "    // M533 opaque variant: no alpha-test discard");
    return true;
}

static const char* kWorldSimpleFragCg = R"(
float4 main(float4 vColor : COLOR) : COLOR
{
    return float4(1.0f, 0.0f, 1.0f, 1.0f);
}
)";

static bool WorldFragVariant(std::string& out, bool noShadow, bool noTex)
{
    static const char* const kTexBlock = "    if (UuseTex > 0.5f) { t = tex2D(Utex, vUV); c *= t; }";
    static const char* const kShadowHead = "    if (UshadowP.x > 0.5f && vShadow.w > 0.0f)";
    static const char* const kShadowTail = "    if (UfogOn > 0.5f)";
    out.assign(kSkinFragCg);
    if (noTex)
    {
        const size_t p = out.find(kTexBlock);
        if (p == std::string::npos) return false;
        out.replace(p, strlen(kTexBlock), "    // M533 fragab: no texture fetch");
    }
    if (noShadow)
    {
        const size_t a = out.find(kShadowHead), b = out.find(kShadowTail);
        if (a == std::string::npos || b == std::string::npos || b <= a) return false;
        out.erase(a, b - a);
    }
    return true;
}

static const char kShaderCacheDir[] = "ux0:data/swbf2/cache/shaders";
static const char kShaderCacheTag[] = "M532 cg fast/fm1/fp0/fi1";
static bool g_sharkReady = false;
static int g_shaderCacheState = -1;
static unsigned g_shaderCacheHits = 0, g_shaderCacheMisses = 0, g_shaderCacheFails = 0;
static uint64_t g_shaderCacheUs = 0;

static uint64_t ShaderFnv1a(const void* p, size_t n, uint64_t h)
{
    const uint8_t* b = (const uint8_t*)p;
    for (size_t i = 0; i < n; ++i) { h ^= b[i]; h *= 0x100000001b3ull; }
    return h;
}

static bool CompileCgCached(GLuint sh, const char* src, GLint len)
{
    const uint64_t t0 = sceKernelGetProcessTimeWide();
    if (g_shaderCacheState < 0)
    {
        sceIoMkdir("ux0:data/swbf2/cache", 0777);
        sceIoMkdir(kShaderCacheDir, 0777);
        SceIoStat st;
        g_shaderCacheState = sceIoGetstat("ux0:data/swbf2/cache/shaders/off", &st) < 0 ? 1 : 0;
        checkpointf("M532 shader cache: %s (%s)", g_shaderCacheState ? "on" : "OFF by kill-switch file", kShaderCacheDir);
    }
    GLint type = 0; glGetShaderiv(sh, GL_SHADER_TYPE, &type);
    const bool frag = type == GL_FRAGMENT_SHADER;
    bool ok = false;
    if (g_shaderCacheState == 1 && g_sharkReady)
    {
        uint64_t h = ShaderFnv1a(kShaderCacheTag, sizeof(kShaderCacheTag), 0xcbf29ce484222325ull);
        h = ShaderFnv1a(frag ? "f" : "v", 1, h);
        h = ShaderFnv1a(src, (size_t)len, h);
        char path[96];
        snprintf(path, sizeof(path), "%s/%016llx.gxp", kShaderCacheDir, (unsigned long long)h);
        SceUID fd = sceIoOpen(path, SCE_O_RDONLY, 0);
        if (fd >= 0)
        {
            const SceOff sz = sceIoLseek(fd, 0, SCE_SEEK_END);
            sceIoLseek(fd, 0, SCE_SEEK_SET);
            std::vector<uint8_t> buf(sz > 0 && sz < (1 << 20) ? (size_t)sz : 0);
            const bool read = !buf.empty() && sceIoRead(fd, buf.data(), (SceSize)buf.size()) == (int)buf.size();
            sceIoClose(fd);
            if (read && buf.size() > 4 && memcmp(buf.data(), "GXP", 3) == 0)
            {
                vglShaderGxpBinary(1, &sh, buf.data(), (GLsizei)buf.size());
                ++g_shaderCacheHits;
                g_shaderCacheUs += sceKernelGetProcessTimeWide() - t0;
                return true;
            }
            ++g_shaderCacheFails;
        }
        const std::string text(src, (size_t)len);
        uint32_t gxpSize = (uint32_t)text.size();
        const SceGxmProgram* gxp = shark_compile_shader_extended(text.c_str(), &gxpSize,
            frag ? SHARK_FRAGMENT_SHADER : SHARK_VERTEX_SHADER, SHARK_OPT_FAST, 1, 0, 1);
        if (gxp && gxpSize > 4)
        {
            fd = sceIoOpen(path, SCE_O_WRONLY | SCE_O_CREAT | SCE_O_TRUNC, 0777);
            if (fd >= 0) { sceIoWrite(fd, gxp, gxpSize); sceIoClose(fd); }
            vglShaderGxpBinary(1, &sh, gxp, (GLsizei)gxpSize);
            shark_clear_output();
            ++g_shaderCacheMisses;
            g_shaderCacheUs += sceKernelGetProcessTimeWide() - t0;
            return true;
        }

        shark_clear_output();
        ++g_shaderCacheFails;
        checkpointf("M540 shader cache: %s shader failed to compile (see the shark lines above)", frag ? "fragment" : "vertex");
        g_shaderCacheUs += sceKernelGetProcessTimeWide() - t0;
        return false;
    }
    glShaderSource(sh, 1, &src, &len);
    glCompileShader(sh);
    GLint st = 0; glGetShaderiv(sh, GL_COMPILE_STATUS, &st);
    ok = st != 0;
    if (!ok) checkpointf("M532 shader cache: %s shader failed in vitaGL's own compile too (shark %s, GL error 0x%x)",
                         frag ? "fragment" : "vertex", g_sharkReady ? "up" : "DOWN", (unsigned)glGetError());
    g_shaderCacheUs += sceKernelGetProcessTimeWide() - t0;
    return ok;
}

static bool CompileSkinShader(GLuint sh, const char* src, const char* what)
{
    const GLint len = (GLint)strlen(src);
    CompileCgCached(sh, src, len);
    GLint ok = 0;
    glGetShaderiv(sh, GL_COMPILE_STATUS, &ok);
    if (!ok)
    {
        char log[512] = { 0 }; GLsizei n = 0;
        glGetShaderInfoLog(sh, sizeof(log) - 1, &n, log);
        checkpointf("M364 GPU skinning: %s shader FAILED to compile: %s", what, log);
        return false;
    }
    return true;
}

static bool InitSkinProgVariant(GLuint& prog, SkProgLocs& L, const char* fragSrc, const char* label)
{
    GLuint vs = glCreateShader(GL_CG_VERTEX_SHADER_EXT);
    GLuint fs = glCreateShader(GL_CG_FRAGMENT_SHADER_EXT);
    if (!CompileSkinShader(vs, kSkinVertCg, "vertex") || !CompileSkinShader(fs, fragSrc, label)) return false;
    prog = glCreateProgram();
    glAttachShader(prog, vs);
    glAttachShader(prog, fs);
    glBindAttribLocation(prog, 0, "aPos");
    glBindAttribLocation(prog, 1, "aNormal");
    glBindAttribLocation(prog, 2, "aUV");
    glBindAttribLocation(prog, 3, "aBone");
    glLinkProgram(prog);
    GLint linked = 0;
    glGetProgramiv(prog, GL_LINK_STATUS, &linked);
    if (!linked) return false;
    L.mv = glGetUniformLocation(prog, "Umv");
    L.proj = glGetUniformLocation(prog, "Uproj");
    L.bones = glGetUniformLocation(prog, "Ubones");
    L.lightDir = glGetUniformLocation(prog, "UlightDir");
    L.light2Dir = glGetUniformLocation(prog, "Ulight2Dir"); L.light2Col = glGetUniformLocation(prog, "Ulight2Col");
    L.lightAmb = glGetUniformLocation(prog, "UlightAmb");
    L.lightDiff = glGetUniformLocation(prog, "UlightDiff");
    L.topAmb = glGetUniformLocation(prog, "UlightDiff2");
    L.upEye = glGetUniformLocation(prog, "UupEye");
    L.globalAmb = glGetUniformLocation(prog, "UglobalAmb");
    L.color = glGetUniformLocation(prog, "Ucolor");
    L.lit = glGetUniformLocation(prog, "Ulit");
    L.uvOff = glGetUniformLocation(prog, "UuvOff");
    L.spec = glGetUniformLocation(prog, "Uspec"); L.gloss = glGetUniformLocation(prog, "Ugloss");
    L.tex = glGetUniformLocation(prog, "Utex");
    L.useTex = glGetUniformLocation(prog, "UuseTex");
    L.alphaCut = glGetUniformLocation(prog, "UalphaCut");
    L.fade = glGetUniformLocation(prog, "Ufade");
    L.fogColor = glGetUniformLocation(prog, "UfogColor");
    L.fogRange = glGetUniformLocation(prog, "UfogRange");
    L.fogFar = glGetUniformLocation(prog, "UfogFar");
    L.fogOn = glGetUniformLocation(prog, "UfogOn");
    L.skyFar = glGetUniformLocation(prog, "UskyFar"); L.skyTex = glGetUniformLocation(prog, "UskyTex");
    L.alphaOut = glGetUniformLocation(prog, "UalphaOut"); L.fogBand = glGetUniformLocation(prog, "UfogBand");
    L.dynPos = glGetUniformLocation(prog, "UdynPos"); L.dynCol = glGetUniformLocation(prog, "UdynCol");
    L.shadowMvp = glGetUniformLocation(prog, "UshadowMvp"); L.shadowP = glGetUniformLocation(prog, "UshadowP");
    L.shadowTex = glGetUniformLocation(prog, "UshadowMap");
    return L.mv >= 0 && L.proj >= 0 && L.bones >= 0;
}

static void InitGpuSkinning(const float sunDir[4], const float sunAmbient[4], const float sunDiffuse[4],
                            const float fogColor[3], float fogStart, float fogEnd)
{

    float mv[16]; glGetFloatv(GL_MODELVIEW_MATRIX, mv);
    float ex = mv[0] * sunDir[0] + mv[4] * sunDir[1] + mv[8] * sunDir[2];
    float ey = mv[1] * sunDir[0] + mv[5] * sunDir[1] + mv[9] * sunDir[2];
    float ez = mv[2] * sunDir[0] + mv[6] * sunDir[1] + mv[10] * sunDir[2];
    const float el = sqrtf(ex * ex + ey * ey + ez * ez);
    if (el > 1e-6f) { g_sunEyeDir[0] = ex / el; g_sunEyeDir[1] = ey / el; g_sunEyeDir[2] = ez / el; }
    for (int i = 0; i < 4; ++i) { g_sunAmbient[i] = sunAmbient[i]; g_sunDiffuse[i] = sunDiffuse[i]; }
    g_fogColor[0] = fogColor[0]; g_fogColor[1] = fogColor[1]; g_fogColor[2] = fogColor[2]; g_fogColor[3] = 1.0f;
    g_fogStart = fogStart; g_fogEnd = fogEnd;

    if (!InitSkinProgVariant(g_skinProg, g_skloc, kSkinFragCg, "fragment"))
    {
        checkpoint("M364 GPU skinning: program FAILED to build - CPU skinning stays in use");
        return;
    }
    g_sklocCur = &g_skloc;
    g_gpuSkinOk = true;
    checkpointf("M364 GPU skinning: program READY (mv=%d proj=%d bones=%d light=%d fog=%d) sunEye=(%.2f,%.2f,%.2f)",
        (int)g_skloc.mv, (int)g_skloc.proj, (int)g_skloc.bones, (int)g_skloc.lightDir, (int)g_skloc.fogFar,
        g_sunEyeDir[0], g_sunEyeDir[1], g_sunEyeDir[2]);

    std::string src;
    if (OpaqueFragCg(src) && InitSkinProgVariant(g_skinOpaqueProg, g_sklocOpaque, src.c_str(), "fragment (opaque)"))
    {
        g_skinOpaqueOk = true;
        checkpointf("M534 skinned opaque program READY (fade=%d alphaCut=%d, both expected -1)",
                    (int)g_sklocOpaque.fade, (int)g_sklocOpaque.alphaCut);
    }
    else checkpoint("M534 skinned opaque program NOT available - every skinned segment keeps the discard path");
}

