struct CameraShot { float qw, qx, qy, qz; Vector3 pos; };
static std::vector<CameraShot> g_cameraShots;
static int Lua_AddCameraShot(lua_State* L)
{
    if (lua_gettop(L) < 7) return 0;
    CameraShot c;
    c.qw = (float)lua_tonumber(L, 1); c.qx = (float)lua_tonumber(L, 2); c.qy = (float)lua_tonumber(L, 3); c.qz = (float)lua_tonumber(L, 4);
    c.pos = Vector3((float)lua_tonumber(L, 5), (float)lua_tonumber(L, 6), (float)lua_tonumber(L, 7));

    if (g_map.code == "uta1" && fabsf(c.pos.m_X - 162.7f) < 0.5f && fabsf(c.pos.m_Z - 40.6f) < 0.5f)
    {
        logf("N16: uta1 AddCameraShot at (%.1f %.1f %.1f) skipped - outside the cliff ring\n", c.pos.m_X, c.pos.m_Y, c.pos.m_Z);
        return 0;
    }
    g_cameraShots.push_back(c);
    logf("MILESTONE 453: AddCameraShot #%u q(%.3f %.3f %.3f %.3f) pos (%.1f %.1f %.1f)\n", (unsigned)g_cameraShots.size(),
         c.qw, c.qx, c.qy, c.qz, c.pos.m_X, c.pos.m_Y, c.pos.m_Z);
    return 0;
}

