static bool IsFriend(int a, int b)
{
    if (a == b) return true;
    for (const auto& p : g_teamFriendPairs)
    {
        if (p.first == a && p.second == b) return true;
    }
    return false;
}

static bool IsHostile(int a, int b)
{
    return a >= 1 && b >= 1 && !IsFriend(a, b);
}

static bool IsCombatTeam(int team)
{
    return team >= 1 && team <= 3;
}

