static int Lua_SetReinforcementCount(lua_State* L)
{
    int teamIdx = (int)lua_tonumber(L, 1);
    int count = (int)lua_tonumber(L, 2);
    TeamInfo& team = GetOrAddTeam(teamIdx);

    if (count < 0)
    {
        team.reinforcementCount = -1;
        team.startingReinforcementCount = -1;
        logf("Lua: SetReinforcementCount(%d, %d) -> UNLIMITED (no ticket event)\n", teamIdx, count);
        checkpoint(("checkpoint: MILESTONE 28 - SetReinforcementCount(" + std::to_string(teamIdx) + ", " + std::to_string(count) + ") = unlimited").c_str());
        return 0;
    }
    team.reinforcementCount = count;

    if (team.startingReinforcementCount < 0) team.startingReinforcementCount = count;
    logf("Lua: SetReinforcementCount(%d, %d)\n", teamIdx, count);
    checkpoint(("checkpoint: MILESTONE 28 - SetReinforcementCount(" + std::to_string(teamIdx) + ", " + std::to_string(count) + ")").c_str());
    FireTicketCountChangeEvent(teamIdx, count);
    return 0;
}

static int Lua_AddReinforcements(lua_State* L)
{
    int teamIdx = (int)lua_tonumber(L, 1);
    int count = (int)lua_tonumber(L, 2);
    TeamInfo& team = GetOrAddTeam(teamIdx);

    if (team.reinforcementCount < 0)
    {
        logf("Lua: AddReinforcements(%d, %d) -> still UNLIMITED\n", teamIdx, count);
        return 0;
    }
    team.reinforcementCount += count;
    logf("Lua: AddReinforcements(%d, %d) -> total %d\n", teamIdx, count, team.reinforcementCount);
    checkpoint(("checkpoint: MILESTONE 28 - AddReinforcements(" + std::to_string(teamIdx) + ", " + std::to_string(count) + ")").c_str());
    FireTicketCountChangeEvent(teamIdx, team.reinforcementCount);
    return 0;
}

