static int Lua_ReadDataFile(lua_State* L)
{
    int nargs = lua_gettop(L);
    if (nargs < 1) return 0;
    const char* lvlFile = lua_tostring(L, 1);
    DataFileRequest req;
    req.lvlFile = (lvlFile != nullptr) ? lvlFile : "";

    size_t semi = req.lvlFile.find(';');
    if (semi != std::string::npos)
    {
        std::string embeddedSub = req.lvlFile.substr(semi + 1);
        req.lvlFile = req.lvlFile.substr(0, semi);
        if (!embeddedSub.empty()) req.subResources.push_back(embeddedSub);
    }

    for (int i = 2; i <= nargs; ++i)
    {
        const char* sub = lua_tostring(L, i);
        if (sub != nullptr) req.subResources.push_back(sub);
    }
    g_dataFileManifest.push_back(req);
    logf("Lua: ReadDataFile(\"%s\", %u real sub-resource(s)) - real file-manifest entry #%u\n",
        req.lvlFile.c_str(), (unsigned)req.subResources.size(), (unsigned)g_dataFileManifest.size());
    return 0;
}

static int Lua_OpenAudioStream(lua_State* L)
{
    int nargs = lua_gettop(L);
    const char* lvlFile = (nargs >= 1) ? lua_tostring(L, 1) : nullptr;
    const char* streamName = (nargs >= 2) ? lua_tostring(L, 2) : nullptr;
    DataFileRequest req;
    req.lvlFile = (lvlFile != nullptr) ? lvlFile : "";
    if (streamName != nullptr) req.subResources.push_back(streamName);
    g_audioManifest.push_back(req);
    logf("Lua: OpenAudioStream(\"%s\", \"%s\") - real audio-manifest entry #%u\n",
        req.lvlFile.c_str(), streamName != nullptr ? streamName : "", (unsigned)g_audioManifest.size());
    return 0;
}

static int Lua_AudioStreamAppendSegments(lua_State* L)
{
    int nargs = lua_gettop(L);
    const char* lvlFile = (nargs >= 1) ? lua_tostring(L, 1) : nullptr;
    DataFileRequest req;
    req.lvlFile = (lvlFile != nullptr) ? lvlFile : "";
    for (int i = 2; i <= nargs; ++i)
    {
        if (lua_type(L, i) != LUA_TSTRING) continue;
        const char* seg = lua_tostring(L, i);
        if (seg != nullptr) req.subResources.push_back(seg);
    }
    g_audioManifest.push_back(req);
    logf("Lua: AudioStreamAppendSegments(\"%s\", %u real segment(s)) - real audio-manifest entry #%u\n",
        req.lvlFile.c_str(), (unsigned)req.subResources.size(), (unsigned)g_audioManifest.size());
    return 0;
}

static void InstallRealDataFileManifestAPI(lua_State* L)
{
    lua_register(L, "ReadDataFile", Lua_ReadDataFile);
    lua_register(L, "OpenAudioStream", Lua_OpenAudioStream);
    lua_register(L, "AudioStreamAppendSegments", Lua_AudioStreamAppendSegments);
}

static void DumpDataFileManifest()
{
    logf("=== REAL DATA FILE MANIFEST (%u model/class request(s)) ===\n", (unsigned)g_dataFileManifest.size());
    for (const DataFileRequest& req : g_dataFileManifest)
    {
        if (req.subResources.empty())
        {
            logf("  %s (whole file)\n", req.lvlFile.c_str());
            continue;
        }
        std::string joined;
        for (size_t i = 0; i < req.subResources.size(); ++i)
        {
            if (i > 0) joined += ", ";
            joined += req.subResources[i];
        }
        logf("  %s: %s\n", req.lvlFile.c_str(), joined.c_str());
    }
    logf("=== REAL AUDIO MANIFEST (%u stream/segment request(s)) ===\n", (unsigned)g_audioManifest.size());
    for (const DataFileRequest& req : g_audioManifest)
    {
        std::string joined;
        for (size_t i = 0; i < req.subResources.size(); ++i)
        {
            if (i > 0) joined += ", ";
            joined += req.subResources[i];
        }
        logf("  %s: %s\n", req.lvlFile.c_str(), joined.c_str());
    }
    logf("=== END REAL MANIFEST ===\n");
}

