static void InstallRealTimerAPI(lua_State* L)
{
    lua_register(L, "CreateTimer", Lua_CreateTimer);
    lua_register(L, "OnTimerElapse", Lua_OnTimerElapse);
    lua_register(L, "SetTimerValue", Lua_SetTimerValue);
    lua_register(L, "StartTimer", Lua_StartTimer);
    lua_register(L, "StopTimer", Lua_StopTimer);
    lua_register(L, "SetTimerRate", Lua_SetTimerRate);
    lua_register(L, "DestroyTimer", Lua_DestroyTimer);
    lua_register(L, "FindTimer", Lua_FindTimer);
    lua_register(L, "GetTimerValue", Lua_GetTimerValue);
    lua_register(L, "ShowTimer", Lua_ShowTimer);
    lua_register(L, "ReleaseTimerElapse", Lua_ReleaseTimerElapse);
}

