struct SpawnClock { float cycleDelay = 0.0f, slotDelay = 0.0f, cycleTimer = 0.0f, slotTimer = 0.0f; int cycleIndex = 0; };
static SpawnClock g_spawnClock[8];
static const int REAL_AI_ALIVE_CAP_DEFAULT = 16;
static int  g_aiAliveCap = REAL_AI_ALIVE_CAP_DEFAULT;
static bool g_uberMode = false;
static int  g_aiAliveNow[8] = {};
static uint32_t g_waveSpawns = 0, g_capWaits = 0;

static bool g_playerAliveForAI = true;
static bool g_reinfTrace = false;
static uint32_t g_ticketWaits[8] = {};
static void ResetSpawnClocks()
{
    for (SpawnClock& c : g_spawnClock) c = SpawnClock();
    for (int t = 1; t <= 2; ++t) { g_spawnClock[t].cycleDelay = 15.0f; g_spawnClock[t].slotDelay = 0.5f; }
    g_aiAliveCap = REAL_AI_ALIVE_CAP_DEFAULT; g_uberMode = false;
}
static void TickSpawnClocks(float dt)
{
    for (SpawnClock& c : g_spawnClock)
    {
        c.cycleTimer -= dt;
        if (c.cycleTimer <= 0.0f) { c.cycleTimer += c.cycleDelay; c.cycleIndex++; c.slotTimer = c.slotDelay; }
        c.slotTimer -= dt;
    }
}

