static void TickMissionTimers(float deltaSec)
{
    if (g_missionLuaState == nullptr) return;
    for (size_t i = 0; i < g_timers.size(); ++i)
    {
        TimerState& t = g_timers[i];
        if (!t.inUse || !t.running) continue;
        t.value -= t.rate * deltaSec;
        if (t.value <= 0.0f)
        {
            t.value = 0.0f;
            t.running = false;
            if (t.callbackRef != LUA_NOREF)
            {

                checkpoint(("checkpoint: MILESTONE 45 - timer \"" + t.name + "\" elapsed - calling its real registered callback").c_str());
                lua_rawgeti(g_missionLuaState, LUA_REGISTRYINDEX, t.callbackRef);

                if (lua_type(g_missionLuaState, -1) != LUA_TFUNCTION)
                {
                    checkpointf("checkpoint: MILESTONE 45 - timer \"%s\" callbackRef=%d holds no function (type %d) - skipped",
                                t.name.c_str(), t.callbackRef, lua_type(g_missionLuaState, -1));
                    lua_pop(g_missionLuaState, 1);
                    continue;
                }

                lua_pushnumber(g_missionLuaState, (lua_Number)i);
                if (lua_pcall(g_missionLuaState, 1, 0, 0) != 0)
                {
                    const char* err = lua_isstring(g_missionLuaState, -1) ? lua_tostring(g_missionLuaState, -1) : "(no error message)";
                    checkpoint(("checkpoint: MILESTONE 45 - timer \"" + t.name + "\" callback returned an error: " + std::string(err)).c_str());
                    lua_pop(g_missionLuaState, 1);
                }
                else
                {
                    checkpoint(("checkpoint: MILESTONE 45 - timer \"" + t.name + "\" callback completed with no error").c_str());
                }
            }
        }
    }
}

static Level* s_missionLvl = nullptr;
static std::set<std::string> s_missionAlreadyHandled;
static void RunMissionScriptInit()
{
    checkpointf("checkpoint: MILESTONE 26/479 - about to run mission script \"%s\" (map %s, era %c, mode %s)",
        g_map.mission.c_str(), g_map.code.c_str(), g_map.era, g_map.mode.c_str());

    if (!FileExists(MISSION_LVL_PATH.c_str()))
    {
        logf("RunRealMissionScripts: %s not found - skipping\n", MISSION_LVL_PATH.c_str());
        return;
    }
    Level* missionLvl = nullptr;
    try { missionLvl = TimedLevelFromFile(MISSION_LVL_PATH.c_str()); }
    catch (const std::exception& e)
    {
        logf("RunRealMissionScripts: Level::FromFile threw: %s\n", e.what());
        return;
    }
    if (missionLvl == nullptr)
    {
        logf("RunRealMissionScripts: Level::FromFile returned null\n");
        return;
    }

    logLoadTiming("M532 mission.lvl opened");
    lua_State* L = lua_open();
    if (L == nullptr) { logf("RunRealMissionScripts: lua_open() failed\n"); return; }

    luaopen_base(L);
    luaopen_table(L);
    luaopen_string(L);
    luaopen_math(L);
    InstallGenericAPIStubs(L);
    InstallRealTeamAPI(L);
    InstallRealDoFileAPI(L);
    InstallRealDataFileManifestAPI(L);
    InstallRealTimerAPI(L);
    InstallRealConquestAPI(L);
    checkpoint("checkpoint: MILESTONE 26 - VM + stubs + real API ready, running real scripts");

    s_missionAlreadyHandled = {
        "print", "type", "tostring", "tonumber", "pairs", "ipairs", "next",
        "assert", "error", "pcall", "xpcall", "unpack", "select", "rawget",
        "rawset", "rawequal", "setmetatable", "getmetatable", "loadstring",
        "dofile", "gcinfo", "collectgarbage", "newproxy", "loadfile", "load",
        "require", "_ALERT",
        "SetTeamName", "SetTeamAsEnemy", "SetTeamAsFriend", "SetUnitCount",
        "AddUnitClass", "ScriptCB_GetAutoAssignTeams", "ScriptCB_DoFile",
        "SetReinforcementCount", "AddReinforcements", "SetHeroClass",
        "SetTeamIcon", "SetBleedRate", "ScriptCB_IsMissionSetupSaved",
        "ScriptCB_LoadMissionSetup",
        "ReadDataFile", "OpenAudioStream", "AudioStreamAppendSegments", "SetMaxFlyHeight",
        "CreateTimer", "OnTimerElapse", "SetTimerValue", "StartTimer",
        "StopTimer", "SetTimerRate", "DestroyTimer", "FindTimer",
    };
    std::set<std::string>& alreadyHandled = s_missionAlreadyHandled;

    g_doFileLvl = missionLvl;
    g_doFileL = L;
    g_doFileAlreadyHandled = &alreadyHandled;
    g_doFileCachedRef.clear();

    {
        int nret = RunScriptChunkAndCallbacks(L, missionLvl, "setup_teams", alreadyHandled);
        CacheDoFileResult(L, "setup_teams", nret);
    }

    {
        int nret = RunScriptChunkAndCallbacks(L, missionLvl, "gametype_capture", alreadyHandled);
        CacheDoFileResult(L, "gametype_capture", nret);
    }
    {
        int nret = RunScriptChunkAndCallbacks(L, missionLvl, "gametype_conquest", alreadyHandled);
        CacheDoFileResult(L, "gametype_conquest", nret);
    }

    const std::string campaignScript = g_map.code + g_map.era + "_c";
    const bool runCampaignFirst = false;
    if (runCampaignFirst && campaignScript != g_map.mission && missionLvl->GetScript(String(campaignScript.c_str())) != nullptr)
    {
        int nret = RunScriptChunkAndCallbacks(L, missionLvl, campaignScript.c_str(), alreadyHandled);
        if (nret > 0) lua_pop(L, nret);
    }
    if (missionLvl->GetScript(String(g_map.mission.c_str())) == nullptr)
        FailForever(("mission script \"" + g_map.mission + "\" is not in mission.lvl").c_str());
    {
        int nret = RunScriptChunkAndCallbacks(L, missionLvl, g_map.mission.c_str(), alreadyHandled);
        if (nret > 0) lua_pop(L, nret);
    }

    s_missionLvl = missionLvl;
    logLoadTiming("M532 mission scripts loaded into Lua");
    g_missionLuaState = L;
    for (const char* entryPoint : { "ScriptInit" })
    {
        lua_getglobal(L, entryPoint);
        if (!lua_isfunction(L, -1))
        {
            lua_pop(L, 1);
            logf("RunRealMissionScripts: real entry point \"%s\" is not defined - skipping\n", entryPoint);
            continue;
        }
        checkpoint((std::string("checkpoint: MILESTONE 61 - calling real deferred entry point \"") + entryPoint + "\"()").c_str());
        if (lua_pcall(L, 0, 0, 0) != 0)
        {
            const char* err = lua_isstring(L, -1) ? lua_tostring(L, -1) : "(no error message)";
            logf("RunRealMissionScripts: real entry point \"%s\"() returned an error: %s\n", entryPoint, err);
            lua_pop(L, 1);
        }
        else
        {
            logf("RunRealMissionScripts: real entry point \"%s\"() completed with no error\n", entryPoint);
        }
    }

    ResolveMapFromScript();
    checkpointf("M479 map: mission %s -> world %s (%s) sub-LVL(s) %u%s%s | sound %s stream \"%s\"",
        g_map.mission.c_str(), g_map.worldLvl.c_str(), g_map.fromScript ? "from ReadDataFile" : "FALLBACK - the script named no world file",
        (unsigned)g_map.worldSubs.size(), g_map.worldSubs.empty() ? "" : " first=", g_map.worldSubs.empty() ? "" : g_map.worldSubs[0].c_str(),
        g_map.soundLvl.empty() ? "(none)" : g_map.soundLvl.c_str(), g_map.soundStream.c_str());
}

static void RunMissionScriptPostLoad()
{
    lua_State* L = g_missionLuaState;
    Level* missionLvl = s_missionLvl;
    if (L == nullptr || missionLvl == nullptr) return;
    g_doFileLvl = missionLvl;
    g_doFileL = L;
    g_doFileAlreadyHandled = &s_missionAlreadyHandled;
    for (const char* entryPoint : { "ScriptPostLoad" })
    {
        lua_getglobal(L, entryPoint);
        if (!lua_isfunction(L, -1))
        {
            lua_pop(L, 1);
            logf("RunRealMissionScripts: real entry point \"%s\" is not defined - skipping\n", entryPoint);
            continue;
        }
        checkpoint((std::string("checkpoint: MILESTONE 61 - calling real deferred entry point \"") + entryPoint + "\"()").c_str());
        if (lua_pcall(L, 0, 0, 0) != 0)
        {
            const char* err = lua_isstring(L, -1) ? lua_tostring(L, -1) : "(no error message)";
            logf("RunRealMissionScripts: real entry point \"%s\"() returned an error: %s\n", entryPoint, err);
            lua_pop(L, 1);
        }
        else
        {
            logf("RunRealMissionScripts: real entry point \"%s\"() completed with no error\n", entryPoint);
        }
    }

    if (g_map.code == "pol1" && getenv("SWBF2_POLBARRIERS") == nullptr)
    {
        lua_dostring(L, "DisableBarriers(\"Barrier485\") DisableBarriers(\"Barrier486\") DisableBarriers(\"Barrier487\")");
        logf("C11: pol1 Barrier485/486/487 disabled (open Dynamic arcs Connection264/Connection110; pol1g_c.lua:72-74)\n");
    }
    g_doFileLvl = nullptr;
    g_doFileL = nullptr;
    g_doFileAlreadyHandled = nullptr;

    g_missionLuaState = L;

    ReleaseLevel(missionLvl);
    s_missionLvl = nullptr;
    checkpoint("checkpoint: MILESTONE 26 - real mission script run complete (missionLvl destroyed)");
    DumpDataFileManifest();
}

