static float RealExplosionFalloff(float dist, float inner, float outer)
{
    if (outer <= 0.0f) return 0.0f;
    if (dist >= outer) return 0.0f;
    if (dist <= inner) return 1.0f;
    if (outer <= inner) return 1.0f;
    return 1.0f - (dist - inner) / (outer - inner);
}

static bool GetFloatPropertyInherited(Level* lvl, const char* className, const char* propName, float& out);

static bool GetPropertyValueInherited(Level* lvl, const char* className, const char* propName, std::string& out);
static void LoadRealExplosion(Level* lvl, const std::string& expName, RealExplosion& out)
{
    if (expName.empty()) return;
    out.name = expName;
    out.valid = true;

    float health = 0.0f, armor = 0.0f;
    if (GetFloatPropertyInherited(lvl, expName.c_str(), "HealthScale", health))
    { out.personScale = out.animalScale = out.droidScale = health; }
    if (GetFloatPropertyInherited(lvl, expName.c_str(), "ArmorScale", armor))
    { out.vehicleScale = out.buildingScale = armor; }

    GetFloatPropertyInherited(lvl, expName.c_str(), "Damage",    out.damage);
    GetFloatPropertyInherited(lvl, expName.c_str(), "MaxDamage", out.damage);
    GetFloatPropertyInherited(lvl, expName.c_str(), "PersonScale",   out.personScale);
    GetFloatPropertyInherited(lvl, expName.c_str(), "AnimalScale",   out.animalScale);
    GetFloatPropertyInherited(lvl, expName.c_str(), "DroidScale",    out.droidScale);
    GetFloatPropertyInherited(lvl, expName.c_str(), "VehicleScale",  out.vehicleScale);
    GetFloatPropertyInherited(lvl, expName.c_str(), "BuildingScale", out.buildingScale);
    GetFloatPropertyInherited(lvl, expName.c_str(), "ShieldScale",   out.shieldScale);

    GetFloatPropertyInherited(lvl, expName.c_str(), "DamageRadiusInner", out.dmgRadiusInner);
    GetFloatPropertyInherited(lvl, expName.c_str(), "DamageRadiusOuter", out.dmgRadiusOuter);
    GetFloatPropertyInherited(lvl, expName.c_str(), "DamageRadius",      out.dmgRadiusOuter);

    GetFloatPropertyInherited(lvl, expName.c_str(), "Push",             out.push);
    GetFloatPropertyInherited(lvl, expName.c_str(), "PushRadiusInner",  out.pushRadiusInner);
    GetFloatPropertyInherited(lvl, expName.c_str(), "PushRadiusOuter",  out.pushRadiusOuter);
    GetFloatPropertyInherited(lvl, expName.c_str(), "PushRadius",       out.pushRadiusOuter);

    GetFloatPropertyInherited(lvl, expName.c_str(), "Shake",            out.shake);
    GetFloatPropertyInherited(lvl, expName.c_str(), "ShakeRadiusInner", out.shakeRadiusInner);
    GetFloatPropertyInherited(lvl, expName.c_str(), "ShakeRadiusOuter", out.shakeRadiusOuter);
    GetFloatPropertyInherited(lvl, expName.c_str(), "ShakeRadius",      out.shakeRadiusOuter);
    GetFloatPropertyInherited(lvl, expName.c_str(), "ShakeLength",      out.shakeLength);
    GetPropertyValueInherited(lvl, expName.c_str(), "Effect", out.effect);
    {
        std::string sp;
        if (GetPropertyValueInherited(lvl, expName.c_str(), "SoundProperty", sp)) out.soundDef = FindExpSoundDef(sp);
    }
    {
        std::string lc;
        if (GetPropertyValueInherited(lvl, expName.c_str(), "LightColor", lc))
            sscanf(lc.c_str(), "%f %f %f %f", &out.lightColor[0], &out.lightColor[1], &out.lightColor[2], &out.lightColor[3]);
        GetFloatPropertyInherited(lvl, expName.c_str(), "LightRadius",   out.lightRadius);
        GetFloatPropertyInherited(lvl, expName.c_str(), "LightDuration", out.lightDuration);
        logf("  M462 explosion \"%s\" light: (%.0f %.0f %.0f %.0f) r=%.1f dur=%.2f effect=%s\n", expName.c_str(),
             out.lightColor[0], out.lightColor[1], out.lightColor[2], out.lightColor[3], out.lightRadius, out.lightDuration, out.effect.c_str());
    }

    float f = 0.0f;
    if (GetFloatPropertyInherited(lvl, expName.c_str(), "PushDeadOnly", f)) out.pushDeadOnly = (f >= 0.5f);
    if (GetFloatPropertyInherited(lvl, expName.c_str(), "HurtOwner",    f)) out.hurtOwner    = (f >= 0.5f);

    logf("  M170 explosion \"%s\": Dmg=%.0f dmgR %.1f/%.1f | Push=%.1f pushR %.1f/%.1f | Shake=%.2f len=%.2f shakeR %.1f/%.1f"
         " | person=%.2f droid=%.2f veh=%.2f bldg=%.2f shield=%.2f | pushDeadOnly=%d hurtOwner=%d\n",
         expName.c_str(), out.damage, out.dmgRadiusInner, out.dmgRadiusOuter,
         out.push, out.pushRadiusInner, out.pushRadiusOuter,
         out.shake, out.shakeLength, out.shakeRadiusInner, out.shakeRadiusOuter,
         out.personScale, out.droidScale, out.vehicleScale, out.buildingScale, out.shieldScale,
         (int)out.pushDeadOnly, (int)out.hurtOwner);
}

