static void ReadClassUnlockCost(Level* lvl, const std::string& cls)
{
    if (lvl == nullptr || g_classUnlockCost.count(cls)) return;
    std::string up;
    g_classUnlockCost[cls] = GetPropertyValueInherited(lvl, cls.c_str(), "PointsToUnlock", up) ? atoi(up.c_str()) : 0;
    logf("UNLOCK: class \"%s\" PointsToUnlock %d\n", cls.c_str(), g_classUnlockCost[cls]);
}

