struct EngineGraph { int n; float x[6], y[6]; };
static float EvalGraph(const EngineGraph& g, float x)
{
    if (g.n <= 0) return 1.0f;
    if (x <= g.x[0]) return g.y[0];
    for (int i = 1; i < g.n; ++i)
        if (x <= g.x[i]) { const float t = (x - g.x[i - 1]) / fmaxf(1e-4f, g.x[i] - g.x[i - 1]); return g.y[i - 1] + (g.y[i] - g.y[i - 1]) * t; }
    return g.y[g.n - 1];
}
struct EngineLayer { const char* sample; float gain, minDist; EngineGraph speedPitch, accelGain; };
struct EngineDef { const char* cls; EngineLayer layers[3]; };
