static int ResolveFootstepClip(int archetype, int surface, bool running, bool isLeft, int variant1to4)
{
    if (archetype < 0 || archetype >= FOOTSTEP_ARCHETYPE_COUNT || surface < 0 || surface >= SURFACE_COUNT) return -1;
    char name[64];
    snprintf(name, sizeof(name), "mvt_%s_%s_%s_%s%02d",
        g_footstepArchetypes[archetype].clipToken,
        running ? "run" : "walk",
        g_footstepSurfaceNames[surface],
        isLeft ? "L" : "R",
        variant1to4);
    auto it = g_soundClipIndexByName.find(name);
    return (it != g_soundClipIndexByName.end()) ? it->second : -1;
}

static int ResolveFootstepArchetype(const std::string& className)
{
    auto it = g_classToFootstepArchetype.find(className);
    if (it == g_classToFootstepArchetype.end()) return -1;
    for (int i = 0; i < FOOTSTEP_ARCHETYPE_COUNT; ++i)
        if (strcmp(g_footstepArchetypes[i].clipToken, it->second) == 0) return i;
    return -1;
}

