static const int MAX_VOICES = 24;
static const int VO_VOICE_SLOT = MAX_VOICES - 1;
static const int PLAYER_WEAPON_VOICE_SLOT = MAX_VOICES - 2;
static const int PLAYER_THROW_VOICE_SLOT = MAX_VOICES - 3;
static const int PLAYER_RELOAD_VOICE_SLOT = MAX_VOICES - 4;

struct ActiveVoice { int clipIndex = -1; float posF = 0.0f; float rate = 1.0f; float volume = 1.0f; bool active = false; int ownerId = -1; };
static ActiveVoice g_voices[MAX_VOICES];
static SceUID g_audioMutex = -1;
static SceUID g_audioThreadId = -1;
static volatile bool g_audioThreadRunning = false;

