enum TroopVoiceMode { VOICE_ANY = 0, VOICE_HURT = 1, VOICE_DEATH = 2 };
static void PlayTroopVoice(const TroopVoiceData& data, int ownerId, float volume, int mode = VOICE_ANY)
{
    if (data.clips.empty()) return;
    if (mode != VOICE_ANY)
    {
        bool busy = false;
        sceKernelLockMutex(g_audioMutex, 1, nullptr);
        for (int i = 0; i < MAX_VOICES; ++i)
        {
            if (!g_voices[i].active || g_voices[i].ownerId != ownerId) continue;
            if (mode == VOICE_DEATH) g_voices[i].active = false; else busy = true;
        }
        sceKernelUnlockMutex(g_audioMutex, 1);
        if (busy) return;
    }
    if (data.playProbability < 1.0f && (float)(rand() % 1000) / 1000.0f >= data.playProbability) return;
    const char* name = data.clips[(size_t)rand() % data.clips.size()];
    auto it = g_soundClipIndexByName.find(name);
    if (it == g_soundClipIndexByName.end()) return;
    PlaySoundClip(it->second, volume, ownerId);
}

