static void PlayRealThrowSoundFrom(float distToListener, int ownerId)
{
    if (distToListener >= 30.0f) return;
    const char* name = g_realThrowClips[rand() % 5];
    auto it = g_soundClipIndexByName.find(name);
    if (it == g_soundClipIndexByName.end()) return;
    const float gain = 0.9f * (distToListener <= 6.0f ? 1.0f : 6.0f / (6.0f + 3.0f * (distToListener - 6.0f)));
    const float rate = 1.0f + ((float)(rand() % 1000) / 1000.0f - 0.5f) * 0.20f;
    PlaySoundClip(it->second, gain, ownerId, rate);
}

enum JetSoundEvent { JET_SOUND_ON, JET_SOUND_OFF, JET_SOUND_ENGINE };
static void PlayPlayerJetSound(JetSoundEvent ev)
{
    static const char* const names[3] = { "rep_weap_jetpack_turnon", "rep_weap_jetpack_turnoff", "rep_inf_jetpack" };
    static const float gains[3] = { 0.7f, 0.6f, 0.7f };
    auto it = g_soundClipIndexByName.find(names[ev]);
    if (it == g_soundClipIndexByName.end() || g_audioMutex < 0) return;
    const int clip = it->second;
    if (ev == JET_SOUND_ENGINE)
    {
        bool playing = false;
        sceKernelLockMutex(g_audioMutex, 1, nullptr);
        for (int i = 0; i < MAX_VOICES; ++i)
            if (g_voices[i].active && g_voices[i].ownerId == SOUND_OWNER_PLAYER_JET && g_voices[i].clipIndex == clip) { playing = true; break; }
        sceKernelUnlockMutex(g_audioMutex, 1);
        if (playing) return;
        PlaySoundClip(clip, gains[ev], SOUND_OWNER_PLAYER_JET, 1.0f);
        return;
    }
    if (ev == JET_SOUND_OFF)
    {
        auto eit = g_soundClipIndexByName.find(names[JET_SOUND_ENGINE]);
        sceKernelLockMutex(g_audioMutex, 1, nullptr);
        for (int i = 0; i < MAX_VOICES; ++i)
            if (g_voices[i].active && g_voices[i].ownerId == SOUND_OWNER_PLAYER_JET && eit != g_soundClipIndexByName.end() && g_voices[i].clipIndex == eit->second)
                g_voices[i].active = false;
        sceKernelUnlockMutex(g_audioMutex, 1);
    }
    const float rate = 1.1f + ((float)(rand() % 1000) / 1000.0f - 0.5f) * 0.2f;
    PlaySoundClip(clip, gains[ev], SOUND_OWNER_PLAYER_JET, rate);
}

static void PlayRandomRocketExplosionSound(float volume = 1.0f)
{

    int tries = 6;
    int pick = rand() % 6;
    while (tries-- > 0 && g_rocketExplosionClipIndex[pick] < 0) pick = rand() % 6;
    if (g_rocketExplosionClipIndex[pick] >= 0)
        PlaySoundClip(g_rocketExplosionClipIndex[pick], volume);
}

static bool PlayExplosionSound(int def, float dist)
{
    if (def < 0) return false;
    const ExpSoundDef& d = kExpSoundDefs[def];
    bool any = false;
    for (int li = d.firstLayer; li < d.firstLayer + d.layerCount; ++li)
    {
        const ExpSoundLayer& L = kExpLayers[li];
        if (dist >= L.maxDist) continue;
        float total = 0.0f;
        for (int si = L.first; si < L.first + L.count; ++si) if (g_expSampleClip[si] >= 0) total += kExpSamples[si].weight;
        if (total <= 0.0f) continue;
        float r = ((float)(rand() % 10000) / 10000.0f) * total; int clip = -1;
        for (int si = L.first; si < L.first + L.count; ++si)
        {
            if (g_expSampleClip[si] < 0) continue;
            clip = g_expSampleClip[si];
            r -= kExpSamples[si].weight; if (r <= 0.0f) break;
        }
        const float gain = L.gain * ((dist <= L.minDist) ? 1.0f : L.minDist / (L.minDist + L.rollOff * (dist - L.minDist)));
        if (L.delay > 0.001f) g_delayedSounds.push_back(DelayedSound{ clip, gain, L.delay });
        else PlaySoundClip(clip, gain);
        any = true;
    }
    return any;
}
static void TickDelayedSounds(float dt)
{
    for (size_t i = 0; i < g_delayedSounds.size(); )
    {
        g_delayedSounds[i].t -= dt;
        if (g_delayedSounds[i].t <= 0.0f) { PlaySoundClip(g_delayedSounds[i].clip, g_delayedSounds[i].gain); g_delayedSounds.erase(g_delayedSounds.begin() + (long)i); }
        else ++i;
    }
}

static void TriggerDistanceFootstep(float& distAccum, bool& nextIsLeft, float travel, bool active, bool running,
    int archetype, const Vector3& pos, int ownerId, float volume)
{
    if (!active || UiPausesGame())
    {
        distAccum = 0.0f;
        return;
    }
    distAccum += travel;
    const float stride = running ? FOOTSTEP_STRIDE_RUN : FOOTSTEP_STRIDE_WALK;
    while (distAccum >= stride)
    {
        distAccum -= stride;
        const int surface = DetermineFootSurfaceAt(pos);
        const int variant = rand() % 4 + 1;
        const int clip = ResolveFootstepClip(archetype, surface, running, nextIsLeft, variant);
        if (clip >= 0) PlaySoundClip(clip, volume, ownerId);
        nextIsLeft = !nextIsLeft;
    }
}

