struct SoundStreamRegion { Vector3 pos; Vector4 rot; Vector3 size; std::string type, segment; float volume = 0.0f; int slot = -1; };
static std::vector<SoundStreamRegion> g_soundStreamRegions;
static float g_ambienceSlotGain[2] = { 0.4f, 0.4f };

static float AMBIENCE_GAIN = 0.4f;

static const float AMBIENCE_SPIRE_RADIUS = 50.0f;

static int DetermineFootSurfaceAt(const Vector3& pos)
{
    float nearestDistSq = 1e18f;
    for (const Vector3& sp : g_ambience.stonespirePositions)
    {
        const float dx = sp.m_X - pos.m_X, dz = sp.m_Z - pos.m_Z;
        const float d2 = dx * dx + dz * dz;
        if (d2 < nearestDistSq) nearestDistSq = d2;
    }
    if (!g_ambience.stonespirePositions.empty() && nearestDistSq < (AMBIENCE_SPIRE_RADIUS * AMBIENCE_SPIRE_RADIUS))
        return SURFACE_STONE;
    return SURFACE_DIRT;
}

static bool SwitchAmbienceSegment(int idx)
{
    if (!g_ambience.valid || idx == g_ambience.currentSegment) return g_ambience.currentSegment == idx;
    if (!g_ambience.stream->SetSegment(g_ambienceSegmentHash[idx]))
    {
        checkpointf("MILESTONE 255: real ambience segment \"%s\" SetSegment FAILED", g_ambienceSegmentNames[idx]);
        return false;
    }
    sceKernelLockMutex(g_audioMutex, 1, nullptr);
    g_ambience.ringHead = g_ambience.ringTail = g_ambience.ringFilled = 0;
    sceKernelUnlockMutex(g_audioMutex, 1);
    g_ambience.currentSegment = idx;
    AMBIENCE_GAIN = g_ambienceSlotGain[idx];
    if (!g_soundStreamRegions.empty()) checkpointf("M485 ambience: now slot %d (gain %.2f)", idx, AMBIENCE_GAIN);
    return true;
}

static void InitAmbience(const std::vector<PlacedInstance>& placedRef, const std::vector<ModelData>& uniqueModels)
{

    if (g_map.soundLvl.empty())
    {
        checkpointf("M479: the mission opened no map sound stream - ambience off");
        return;
    }
    const std::string& GEO_SOUND_LVL_PATH = g_map.soundLvl;
    if (!FileExists(GEO_SOUND_LVL_PATH.c_str()))
    {
        checkpointf("MILESTONE 255: %s not found - real ambience disabled this session", GEO_SOUND_LVL_PATH.c_str());
        return;
    }

    g_ambience.lvl = TimedLevelFromFile(GEO_SOUND_LVL_PATH.c_str());
    if (g_ambience.lvl == nullptr)
    {
        checkpointf("MILESTONE 255: Level::FromFile FAILED for %s - real ambience disabled this session", GEO_SOUND_LVL_PATH.c_str());
        return;
    }
    g_ambience.stream = g_ambience.lvl->GetSoundStreamMutable(String(g_map.soundStream.c_str()));
    if (g_ambience.stream == nullptr)
    {
        checkpointf("MILESTONE 255: real stream \"%s\" not found in %s - real ambience disabled this session", g_map.soundStream.c_str(), GEO_SOUND_LVL_PATH.c_str());
        ReleaseLevel(g_ambience.lvl); g_ambience.lvl = nullptr;
        return;
    }
    if (!g_ambience.reader.Open(GEO_SOUND_LVL_PATH.c_str()))
    {
        checkpointf("MILESTONE 255: second reader Open FAILED for %s - real ambience disabled this session", GEO_SOUND_LVL_PATH.c_str());
        ReleaseLevel(g_ambience.lvl); g_ambience.lvl = nullptr; g_ambience.stream = nullptr;
        return;
    }

    const size_t adpcmBlockSize = (size_t)g_ambience.stream->GetNumChannels() * 36;
    g_ambience.encodedBuf.resize((64 * 1024 / adpcmBlockSize) * adpcmBlockSize);
    g_ambience.stream->SetFileReader(&g_ambience.reader);
    g_ambience.stream->SetFileStreamBuffer(g_ambience.encodedBuf.data(), g_ambience.encodedBuf.size());

    g_ambience.ring.assign((size_t)AUDIO_OUT_RATE * 2 * 3 / 2, 0);
    g_ambience.valid = true;
    {
        const char* found = nullptr;
        for (const AmbienceSegmentGain& ag : kAmbienceGains)
            if (g_ambience.stream->HasSegment(LibSWBF2::FNV::Hash(String(ag.name)))) { found = ag.name; AMBIENCE_GAIN = ag.gain; break; }
        for (int k = 0; k < 2; ++k)
        {
            const LibSWBF2::FNVHash h = LibSWBF2::FNV::Hash(String(g_ambienceSegmentNames[k]));
            g_ambienceSegmentHash[k] = g_ambience.stream->HasSegment(h) ? h : 0;
        }
        if (g_ambienceSegmentHash[0] == 0)
        {
            LibSWBF2::FNVHash h = found ? LibSWBF2::FNV::Hash(String(found)) : 0;
            if (h == 0 && g_ambience.stream->GetSounds().Size() > 0) h = g_ambience.stream->GetSounds()[0].GetHashedName();
            g_ambienceSegmentHash[0] = h;
        }
        if (g_ambienceSegmentHash[1] == 0) g_ambienceSegmentHash[1] = g_ambienceSegmentHash[0];
        g_ambienceSlotGain[0] = g_ambienceSlotGain[1] = AMBIENCE_GAIN;
        {
            std::vector<SoundStreamRegion*> rs;
            for (SoundStreamRegion& r : g_soundStreamRegions)
                if (g_ambience.stream->HasSegment(LibSWBF2::FNV::Hash(String(r.segment.c_str())))) rs.push_back(&r);
            std::stable_sort(rs.begin(), rs.end(), [](const SoundStreamRegion* a, const SoundStreamRegion* b) { return a->volume > b->volume; });
            std::vector<std::string> segs;
            for (SoundStreamRegion* r : rs)
                if (std::find(segs.begin(), segs.end(), r->segment) == segs.end() && segs.size() < 2) segs.push_back(r->segment);
            for (size_t k = 0; k < segs.size(); ++k)
            {
                g_ambienceSegmentHash[k] = LibSWBF2::FNV::Hash(String(segs[k].c_str()));
                for (const AmbienceSegmentGain& ag : kAmbienceGains) if (segs[k] == ag.name) g_ambienceSlotGain[k] = ag.gain;
            }
            if (segs.size() == 1) { g_ambienceSegmentHash[1] = g_ambienceSegmentHash[0]; g_ambienceSlotGain[1] = g_ambienceSlotGain[0]; }
            for (SoundStreamRegion* r : rs)
                for (size_t k = 0; k < segs.size(); ++k) if (r->segment == segs[k]) r->slot = (int)k;
            for (size_t k = 0; k < segs.size(); ++k)
                checkpointf("M485 ambience: slot %u = soundstream region segment \"%s\" (gain %.2f)", (unsigned)k, segs[k].c_str(), g_ambienceSlotGain[k]);
            if (!segs.empty()) AMBIENCE_GAIN = g_ambienceSlotGain[0];
        }
        checkpointf("M480 ambience: stream \"%s\" segment %s (gain %.2f), %u segment(s) in the stream", g_map.soundStream.c_str(),
                    found ? found : "(first in stream)", AMBIENCE_GAIN, (unsigned)g_ambience.stream->GetSounds().Size());
    }
    SwitchAmbienceSegment(0);

    for (const PlacedInstance& pi : placedRef)
    {
        if (pi.modelIndex >= uniqueModels.size()) continue;
        if (uniqueModels[pi.modelIndex].debugName.find("stonespire") != std::string::npos)
            g_ambience.stonespirePositions.push_back(pi.position);
    }

    checkpointf("MILESTONE 255: real ambience streaming initialized (%s, %u stonespire instance(s))", g_map.soundStream.c_str(),
        (unsigned)g_ambience.stonespirePositions.size());
}

static void UpdateAmbienceDecision(const Vector3& playerPos)
{
    if (!g_ambience.valid) return;

    float nearestDistSq = 1e18f;
    for (const Vector3& sp : g_ambience.stonespirePositions)
    {
        const float dx = sp.m_X - playerPos.m_X, dz = sp.m_Z - playerPos.m_Z;
        const float d2 = dx * dx + dz * dz;
        if (d2 < nearestDistSq) nearestDistSq = d2;
    }
    const bool nearSpire = !g_ambience.stonespirePositions.empty() && nearestDistSq < (AMBIENCE_SPIRE_RADIUS * AMBIENCE_SPIRE_RADIUS);
    int desired = nearSpire ? 1 : 0;
    {
        float best = 1e30f;
        for (const SoundStreamRegion& r : g_soundStreamRegions)
            if (r.slot >= 0 && r.volume < best && PointInRegion(r.pos, r.rot, r.size, r.type, playerPos)) { best = r.volume; desired = r.slot; }
    }

    sceKernelLockMutex(g_streamingMutex, 1, nullptr);
    g_ambience.desiredSegment = desired;
    sceKernelUnlockMutex(g_streamingMutex, 1);
}

static void StreamAmbience()
{
    if (!g_ambience.valid) return;

    sceKernelLockMutex(g_streamingMutex, 1, nullptr);
    const int desired = g_ambience.desiredSegment;
    sceKernelUnlockMutex(g_streamingMutex, 1);
    SwitchAmbienceSegment(desired);

    const size_t capacityFrames = g_ambience.ring.size() / 2;
    int16_t scratch[4096];
    const size_t wantSamples = 4096;
    const size_t wantFrames = wantSamples / 2;
    while (g_ambience.ringFilled + wantFrames <= capacityFrames)
    {
        if (g_ambience.stream->BytesLeftInSegment() <= 0)
        {

            if (!g_ambience.stream->SetSegment(g_ambienceSegmentHash[g_ambience.currentSegment]))
                break;
            if (g_ambience.stream->BytesLeftInSegment() <= 0) break;
        }
        int32_t got = g_ambience.stream->ReadSamples(scratch, wantSamples, wantSamples, ESoundFormat::PCM16);
        if (got <= 0) break;
        const size_t framesGot = (size_t)got / 2;
        sceKernelLockMutex(g_audioMutex, 1, nullptr);
        for (size_t f = 0; f < framesGot; ++f)
        {
            g_ambience.ring[g_ambience.ringTail * 2 + 0] = scratch[f * 2 + 0];
            g_ambience.ring[g_ambience.ringTail * 2 + 1] = scratch[f * 2 + 1];
            g_ambience.ringTail = (g_ambience.ringTail + 1) % capacityFrames;
        }
        g_ambience.ringFilled += framesGot;
        sceKernelUnlockMutex(g_audioMutex, 1);
    }
}

