static std::vector<std::string> g_musicActionPool = {
    "CISGeo01_Act01_lp", "RepUta01_Act03_lp", "RepFel01_Act01_lp",
    "CISGeo01_Amb01_lp", "CISGeo01_Amb02_lp", "RepKam01_Amb01_lp",
};
static bool g_musicCycle = false;
static size_t g_musicCycleIdx = 0;

static const char* const g_musicVictoryByTeam[3] = { nullptr, "rep_victory", "cis_victory" };
static const char* const g_musicDefeatByTeam[3]  = { nullptr, "rep_defeat",  "cis_defeat"  };

static float MUSIC_GAIN = 0.5f;

static bool PickNewActionSegment(const char* avoidName)
{
    if (g_musicActionPool.empty()) return false;
    const char* pick = nullptr;
    if (g_musicCycle) pick = g_musicActionPool[g_musicCycleIdx++ % g_musicActionPool.size()].c_str();
    else if (g_musicActionPool.size() <= 1) pick = g_musicActionPool[0].c_str();
    else
        for (int tries = 0; tries < 8; ++tries)
        {
            pick = g_musicActionPool[(size_t)rand() % g_musicActionPool.size()].c_str();
            if (avoidName == nullptr || strcmp(pick, avoidName) != 0) break;
        }
    if (!g_music.stream->SetSegment(LibSWBF2::FNV::Hash(String(pick)))) return false;
    g_music.currentSegment = pick;
    return true;
}

static void InitMusic(const std::string& GLOBAL_LVL_PATH = ::GLOBAL_LVL_PATH, const char* streamName = "cw_music")
{
    if (!FileExists(GLOBAL_LVL_PATH.c_str()))
    {
        checkpointf("MILESTONE 259: %s not found - real dynamic music disabled this session", GLOBAL_LVL_PATH.c_str());
        return;
    }
    logMallinfo("before opening global.lvl for real music");

    g_music.lvl = TimedLevelFromFile(GLOBAL_LVL_PATH.c_str());
    logMallinfo("after opening global.lvl for real music");
    if (g_music.lvl == nullptr)
    {
        checkpointf("MILESTONE 259: Level::FromFile FAILED for %s - real dynamic music disabled this session", GLOBAL_LVL_PATH.c_str());
        return;
    }
    g_music.stream = g_music.lvl->GetSoundStreamMutable(String(streamName));
    if (g_music.stream == nullptr)
    {
        checkpointf("MILESTONE 259: real stream \"cw_music\" not found in %s - real dynamic music disabled this session", GLOBAL_LVL_PATH.c_str());
        ReleaseLevel(g_music.lvl); g_music.lvl = nullptr;
        return;
    }
    if (!g_music.reader.Open(GLOBAL_LVL_PATH.c_str()))
    {
        checkpointf("MILESTONE 259: second reader Open FAILED for %s - real dynamic music disabled this session", GLOBAL_LVL_PATH.c_str());
        ReleaseLevel(g_music.lvl); g_music.lvl = nullptr; g_music.stream = nullptr;
        return;
    }

    const size_t adpcmBlockSize = (size_t)g_music.stream->GetNumChannels() * 36;
    g_music.encodedBuf.resize((64 * 1024 / adpcmBlockSize) * adpcmBlockSize);
    g_music.stream->SetFileReader(&g_music.reader);
    g_music.stream->SetFileStreamBuffer(g_music.encodedBuf.data(), g_music.encodedBuf.size());
    g_music.ring.assign((size_t)AUDIO_OUT_RATE * 2 * 3 / 2, 0);
    g_music.valid = true;
    PickNewActionSegment(nullptr);
    checkpointf("MILESTONE 259: real dynamic music initialized (%s, %d-track real pool%s)", streamName, (int)g_musicActionPool.size(), g_musicCycle ? ", cycled" : "");
}

static void UpdateMusicDecision(bool missionOver, int missionWinningTeam, int playerTeam)
{
    if (!g_music.valid) return;
    sceKernelLockMutex(g_streamingMutex, 1, nullptr);
    g_music.desiredMissionOver = missionOver;
    g_music.desiredWinningTeam = missionWinningTeam;
    g_music.desiredPlayerTeam = playerTeam;
    sceKernelUnlockMutex(g_streamingMutex, 1);
}

static void StreamMusic()
{
    if (!g_music.valid) return;

    sceKernelLockMutex(g_streamingMutex, 1, nullptr);
    const bool missionOver = g_music.desiredMissionOver;
    const int missionWinningTeam = g_music.desiredWinningTeam;
    const int playerTeam = g_music.desiredPlayerTeam;
    const bool stingerAlready = g_music.stingerActive;
    sceKernelUnlockMutex(g_streamingMutex, 1);

    if (missionOver && !stingerAlready)
    {
        const bool won = (missionWinningTeam == playerTeam);
        const char* stinger = nullptr;
        if (playerTeam >= 1 && playerTeam <= 2)
            stinger = won ? g_musicVictoryByTeam[playerTeam] : g_musicDefeatByTeam[playerTeam];
        if (stinger != nullptr && g_music.stream->SetSegment(LibSWBF2::FNV::Hash(String(stinger))))
        {
            sceKernelLockMutex(g_audioMutex, 1, nullptr);
            g_music.ringHead = g_music.ringTail = g_music.ringFilled = 0;
            sceKernelUnlockMutex(g_audioMutex, 1);
            g_music.currentSegment = stinger;
            g_music.stingerActive = true;
            checkpointf("MILESTONE 259: real music stinger \"%s\" (won=%d)", stinger, (int)won);
        }
    }

    const size_t capacityFrames = g_music.ring.size() / 2;
    int16_t scratch[4096];
    const size_t wantSamples = 4096;
    const size_t wantFrames = wantSamples / 2;
    while (g_music.ringFilled + wantFrames <= capacityFrames)
    {
        if (g_music.stream->BytesLeftInSegment() <= 0)
        {

            if (g_music.stingerActive) break;
            if (!PickNewActionSegment(g_music.currentSegment.c_str())) break;
            if (g_music.stream->BytesLeftInSegment() <= 0) break;
        }
        int32_t got = g_music.stream->ReadSamples(scratch, wantSamples, wantSamples, ESoundFormat::PCM16);
        if (got <= 0) break;
        const size_t framesGot = (size_t)got / 2;
        sceKernelLockMutex(g_audioMutex, 1, nullptr);
        for (size_t f = 0; f < framesGot; ++f)
        {
            g_music.ring[g_music.ringTail * 2 + 0] = scratch[f * 2 + 0];
            g_music.ring[g_music.ringTail * 2 + 1] = scratch[f * 2 + 1];
            g_music.ringTail = (g_music.ringTail + 1) % capacityFrames;
        }
        g_music.ringFilled += framesGot;
        sceKernelUnlockMutex(g_audioMutex, 1);
    }
}

