static std::vector<std::vector<Vector3>> g_boundaryShapes;

static std::vector<std::vector<Vector3>> g_boundaryShapesLast;
static bool g_boundsLastWinsDbg = false;

static const float BOUNDS_TIMER_SEC = 6.5f;

static float g_boundsWarnT = -1.0f;
static unsigned g_boundsKillsPlayer = 0, g_boundsKillsAi = 0;

static bool IsOutsideBattlefield(float x, float z)
{
    const std::vector<std::vector<Vector3>>& shapes =
        (g_boundsLastWinsDbg && !g_boundaryShapesLast.empty()) ? g_boundaryShapesLast : g_boundaryShapes;
    if (shapes.empty()) return false;
    for (const std::vector<Vector3>& shape : shapes)
    {
        if (shape.size() < 3) continue;
        bool inside = true;
        for (size_t i = 0; i < shape.size(); ++i)
        {
            const Vector3& a = shape[i];
            const Vector3& b = shape[(i + 1) % shape.size()];
            const float d = (x - a.m_X) * (a.m_Z - b.m_Z) + (z - a.m_Z) * (b.m_X - a.m_X);
            if (!(d <= 0.0f)) { inside = false; break; }
        }
        if (inside) return false;
    }
    return true;
}

static bool BoundsTimerTick(float& timer, float dt, bool outside)
{
    if (!outside) { timer = -1.0f; return false; }
    if (timer < 0.0f) timer = BOUNDS_TIMER_SEC;
    timer -= dt;
    return timer < 0.0f;
}

static std::vector<int16_t> ResampleMonoPCM16Linear(const std::vector<int16_t>& src, uint32_t srcRate, uint32_t dstRate)
{
    if (srcRate == dstRate || src.empty() || srcRate == 0) return src;
    const size_t dstCount = (size_t)((double)src.size() * (double)dstRate / (double)srcRate);
    std::vector<int16_t> dst(dstCount);
    for (size_t i = 0; i < dstCount; ++i)
    {
        const double srcPos = (double)i * (double)srcRate / (double)dstRate;
        const size_t i0 = (size_t)srcPos;
        const size_t i1 = (i0 + 1 < src.size()) ? i0 + 1 : i0;
        const double frac = srcPos - (double)i0;
        dst[i] = (int16_t)((double)src[i0] * (1.0 - frac) + (double)src[i1] * frac);
    }
    return dst;
}

