static bool IsOffhandSlot(const UnitLoadout& lo, size_t si)
{
    if (si >= lo.slotWeapon.size()) return false;
    const int wi = lo.slotWeapon[si];
    if (wi < 0 || (size_t)wi >= g_weaponTable.size()) return false;
    if (g_weaponTable[(size_t)wi].offhandWeapon) return true;
    return si < lo.slotChannel.size() && lo.slotChannel[si] == 1;
}

static bool IsAwardSlot(const UnitLoadout& lo, size_t si)
{
    return si < lo.slotName.size() && lo.slotName[si].find("award") != std::string::npos;
}

