static void ParseRealColorTriplet(const char* text, float& outR, float& outG, float& outB)
{
    if (text == nullptr) return;
    float c[3] = { 0.0f, 0.0f, 0.0f };
    if (sscanf(text, "%f %f %f", &c[0], &c[1], &c[2]) == 3)
    {
        outR = c[0] / 255.0f; outG = c[1] / 255.0f; outB = c[2] / 255.0f;
    }
}

static Level* g_commonItemsLvl = nullptr;
static bool   g_commonItemsLvlTried = false;
static const EntityClass* GetEntityClassAnyLevel(Level* primary, const char* name, Level*& foundIn)
{
    foundIn = primary;
    const EntityClass* ec = (primary != nullptr) ? primary->GetEntityClass(String(name)) : nullptr;
    if (ec != nullptr) return ec;
    if (!g_commonItemsLvlTried)
    {
        g_commonItemsLvlTried = true;
        g_commonItemsLvl = TimedLevelFromFile(INGAME_LVL_PATH.c_str());
    }
    if (g_commonItemsLvl != nullptr && g_commonItemsLvl != primary)
    {
        ec = g_commonItemsLvl->GetEntityClass(String(name));
        if (ec != nullptr) { foundIn = g_commonItemsLvl; return ec; }
    }
    return nullptr;
}

struct ConsoleClass { std::string base; std::unordered_map<std::string, std::vector<std::string>> num; std::unordered_set<std::string> text; bool charged = false;   };
static std::unordered_map<std::string, ConsoleClass> g_consoleClasses;
static std::string LowerStr(const char* p) { std::string r(p ? p : ""); for (char& c : r) c = (char)tolower((unsigned char)c); return r; }
static void LoadConsoleOverlay()
{
    g_consoleClasses.clear(); g_consoleMissionUnits.clear(); g_consoleWorld.clear(); g_consoleSky.clear(); g_consoleOverlay = false;

    if (getenv("SWBF2_PC_DATA") != nullptr) return;
    if (AiRulesMode() != AI_RULES_PS2) return;

    FILE* f = fopen("ux0:data/swbf2/ps2_classes.txt", "r");
    const char* src = f ? "ux0:data/swbf2/ps2_classes.txt" : "built in";
    char line[1024]; ConsoleClass* cur = nullptr; size_t nv = 0, li = 0;
    const size_t nBuiltIn = sizeof(kConsoleDataLines) / sizeof(kConsoleDataLines[0]);
    while (f ? (fgets(line, sizeof line, f) != nullptr) : (li < nBuiltIn && (snprintf(line, sizeof line, "%s", kConsoleDataLines[li++]), true)))
    {
        size_t L = strlen(line); while (L && (line[L - 1] == '\n' || line[L - 1] == '\r')) line[--L] = 0;
        char* a = strchr(line, '\t'); if (!a) continue; *a++ = 0;
        char* b = strchr(a, '\t'); if (b) *b++ = 0;
        if (line[0] == 'C') { cur = &g_consoleClasses[LowerStr(a)]; cur->base = LowerStr(b ? b : ""); }
        else if (cur && line[0] == 'P' && b)
        {

            const std::string k = LowerStr(a);
            if (cur->charged) continue;
            if (k == "nextcharge") cur->charged = true;
            cur->num[k].push_back(b); ++nv;
        }
        else if (cur && line[0] == 'S') cur->text.insert(LowerStr(a));
        else if (line[0] == 'M' && b) g_consoleMissionUnits[LowerStr(a)] = atoi(b);
        else if (line[0] == 'Y' && b)
        {
            char* c2 = strchr(b, '\t'); if (!c2) continue; *c2++ = 0;
            std::vector<float> v; for (char* t = strtok(c2, " "); t; t = strtok(nullptr, " ")) v.push_back((float)atof(t));
            g_consoleSky[LowerStr(a) + "|" + LowerStr(b)] = v;
        }
        else if (line[0] == 'W' && b)
        {
            char* c2 = strchr(b, '\t'); if (!c2) continue; *c2++ = 0;
            char* c3 = strchr(c2, '\t'); if (!c3) continue; *c3++ = 0;
            g_consoleWorld[LowerStr(a) + "|" + LowerStr(b) + "|" + LowerStr(c2)] = c3;
        }
    }
    if (f) fclose(f);
    g_consoleOverlay = !g_consoleClasses.empty();
    logf("CONSOLE DATA: %u PS2 classes, %u numeric values, %u missions (%s; AI Rules = PS2)\n", (unsigned)g_consoleClasses.size(), (unsigned)nv, (unsigned)g_consoleMissionUnits.size(), src);
}

static int ConsoleLookup(const char* className, const char* propName, const std::vector<std::string>** out)
{
    if (!g_consoleOverlay) return 0;
    auto it = g_consoleClasses.find(LowerStr(className));
    if (it == g_consoleClasses.end()) return 0;
    const std::string prop = LowerStr(propName);
    for (int guard = 0; it != g_consoleClasses.end() && guard < 16; ++guard)
    {
        auto p = it->second.num.find(prop);
        if (p != it->second.num.end()) { *out = &p->second; return 1; }
        if (it->second.text.count(prop)) return 0;
        if (it->second.base.empty()) break;
        it = g_consoleClasses.find(it->second.base);
    }
    if (it == g_consoleClasses.end()) return 0;
    {
        static std::unordered_set<std::string> s_seen;
        const std::string k = LowerStr(className) + "." + prop;
        if (s_seen.insert(k).second) logf("CONSOLE DATA: %s not on the disc's chain - default\n", k.c_str());
    }
    return -1;
}

static bool GetPropertyListInherited(Level* lvl, const char* className, const char* propName, List<String>& out)
{
    if (lvl == nullptr || className == nullptr || className[0] == '\0') return false;
    {
        const std::vector<std::string>* cv = nullptr; const int r = ConsoleLookup(className, propName, &cv);
        if (r == 1) { out = List<String>(); for (const std::string& v : *cv) out.Add(String(v.c_str())); return true; }
        if (r == -1) return false;
    }
    Level* activeLvl = lvl;
    const EntityClass* cur = GetEntityClassAnyLevel(activeLvl, className, activeLvl);
    int guard = 0;
    while (cur != nullptr && guard++ < 16)
    {
        List<String> vals;
        if (cur->GetProperty(String(propName), vals) && vals.Size() > 0) { out = vals; return true; }
        String base = cur->GetBaseName();
        if (base.Length() == 0) break;
        cur = GetEntityClassAnyLevel(activeLvl, base.Buffer(), activeLvl);
    }
    return false;
}

static CollisionLayerSelect ReadCollisionLayers(Level* lvl, const char* className, const Model& model)
{
    CollisionLayerSelect sel;
    if (getenv("SWBF2_NOLAYERS") != nullptr) return sel;
    std::vector<std::string> bodies;
    {
        List<CollisionPrimitive> prims = model.GetCollisionPrimitives();
        for (size_t p = 0; p < prims.Size(); ++p) bodies.push_back(LowerStr(prims[p].GetName().Buffer()));
        uint32_t vc = 0; Vector3* v = nullptr;
        model.GetCollisionMesh().GetVertexBuffer(vc, v);
        if (vc > 0) bodies.push_back("collisionmesh");
    }
    auto readList = [&](const char* prop, bool& isSet, std::vector<std::string>& into)
    {
        List<String> vals;
        if (!GetPropertyListInherited(lvl, className, prop, vals)) return;
        for (size_t i = 0; i < vals.Size(); ++i)
        {
            const std::string n = LowerStr(vals[i].Buffer());
            if (n == "none" || n == "clear") { isSet = true; into.clear(); continue; }
            if (!CollisionLayerSelect::Has(bodies, n)) continue;
            isSet = true;
            if (!CollisionLayerSelect::Has(into, n)) into.push_back(n);
        }
    };
    readList("SoldierCollision", sel.soldierSet, sel.soldier);
    readList("OrdnanceCollision", sel.ordnanceSet, sel.ordnance);
    bool vehSet = false;
    readList("VehicleCollisionOnly", vehSet, sel.vehicleOnly);
    if (sel.soldierSet || !sel.vehicleOnly.empty())
        logf("COLLMASK2 class \"%s\": soldier %s (%u), ordnance %s (%u), vehicle-only %u\n", className,
             sel.soldierSet ? "set" : "default", (unsigned)sel.soldier.size(), sel.ordnanceSet ? "set" : "default",
             (unsigned)sel.ordnance.size(), (unsigned)sel.vehicleOnly.size());
    return sel;
}

static std::string ClassLabelOf(Level* lvl, const char* className)
{
    if (lvl == nullptr || className == nullptr) return std::string();
    Level* activeLvl = lvl;
    const EntityClass* cur = GetEntityClassAnyLevel(activeLvl, className, activeLvl);
    if (cur == nullptr) return std::string();
    std::string label = className;
    for (int guard = 0; cur != nullptr && guard < 16; ++guard)
    {
        const String base = cur->GetBaseName();
        if (base.Length() == 0) break;
        label = base.Buffer();
        cur = GetEntityClassAnyLevel(activeLvl, base.Buffer(), activeLvl);
    }
    return label;
}

static bool GetPropertyValueInherited(Level* lvl, const char* className, const char* propName, std::string& out)
{
    if (lvl == nullptr || className == nullptr || className[0] == '\0') return false;
    {
        const std::vector<std::string>* cv = nullptr; const int r = ConsoleLookup(className, propName, &cv);
        if (r == 1) { out = cv->back(); return !out.empty(); }
        if (r == -1) return false;
    }
    Level* activeLvl = lvl;
    const EntityClass* cur = GetEntityClassAnyLevel(activeLvl, className, activeLvl);
    const LibSWBF2::FNVHash want = LibSWBF2::FNV::Hash(String(propName));
    int guard = 0;
    while (cur != nullptr && guard++ < 16)
    {

        List<LibSWBF2::FNVHash> hs; List<String> vs;
        cur->GetOverriddenProperties(hs, vs);

        const LibSWBF2::FNVHash nextCharge = LibSWBF2::FNV::Hash(String("NEXTCHARGE"));
        uint32_t cutoff = hs.Size();
        for (uint32_t i = 0; i < hs.Size(); ++i) if (hs[i] == nextCharge) { cutoff = i; break; }
        const String* last = nullptr;
        for (uint32_t i = 0; i < cutoff; ++i) if (hs[i] == want) last = &vs[i];
        if (want == nextCharge && cutoff < hs.Size()) last = &vs[cutoff];
        if (last != nullptr)
        {
            out = last->Buffer();
            return !out.empty();
        }
        String base = cur->GetBaseName();
        if (base.Length() == 0) break;
        cur = GetEntityClassAnyLevel(activeLvl, base.Buffer(), activeLvl);
    }
    return false;
}

static size_t g_muzzleFlashModel = (size_t)-1;
static void ResolveMuzzleFlash(Level* lvl, const char* weaponName, WeaponStats& ws)
{
    std::vector<const EntityClass*> chain;
    Level* at = lvl;
    for (const EntityClass* c = GetEntityClassAnyLevel(at, weaponName, at); c != nullptr && chain.size() < 16; )
    {
        chain.push_back(c);
        String base = c->GetBaseName();
        if (base.Length() == 0) break;
        c = GetEntityClassAnyLevel(at, base.Buffer(), at);
    }
    auto H = [](const char* n) { return LibSWBF2::FNV::Hash(String(n)); };
    const LibSWBF2::FNVHash hMF = H("MuzzleFlash"), hR = H("FlashRadius"), hL = H("FlashLength"), hC = H("FlashColor"),
        hSmall = H("small_muzzle_flash"), hMed = H("med_muzzle_flash"), hLarge = H("large_muzzle_flash");
    for (size_t k = chain.size(); k-- > 0; )
    {
        List<LibSWBF2::FNVHash> hs; List<String> vs;
        chain[k]->GetOverriddenProperties(hs, vs);
        for (uint32_t i = 0; i < hs.Size(); ++i)
        {
            const char* v = vs[i].Buffer();
            if (hs[i] == hMF)
            {
                const LibSWBF2::FNVHash p = LibSWBF2::FNV::Hash(vs[i]);
                const float r = p == hSmall ? 0.6f : p == hMed ? 1.0f : p == hLarge ? 1.8f : -1.0f;
                if (r < 0.0f) continue;
                ws.flashRadius = r; ws.flashLength = p == hSmall ? 0.1f : p == hMed ? 0.15f : 0.3f;
                ws.flashColor[0] = 255; ws.flashColor[1] = 255; ws.flashColor[2] = 50; ws.flashColor[3] = 255;
            }
            else if (hs[i] == hR) ws.flashRadius = (float)atof(v);
            else if (hs[i] == hL) ws.flashLength = (float)atof(v);
            else if (hs[i] == hC)
            {
                int c[4] = { 255, 255, 255, 255 };
                sscanf(v, "%i %i %i %i", &c[0], &c[1], &c[2], &c[3]);
                for (int j = 0; j < 4; ++j) ws.flashColor[j] = (uint8_t)c[j];
            }
        }
    }
}

static bool GetFloatPropertyInherited(Level* lvl, const char* className, const char* propName, float& out)
{
    std::string v;
    if (!GetPropertyValueInherited(lvl, className, propName, v)) return false;
    out = (float)atof(v.c_str());
    return true;
}

static void ReadClassVoice(Level* lvl, const std::string& unitClass, UnitLoadout& lo)
{
    GetPropertyValueInherited(lvl, unitClass.c_str(), "HurtSound", lo.hurtSound);
    GetPropertyValueInherited(lvl, unitClass.c_str(), "DeathSound", lo.deathSound);
    GetPropertyValueInherited(lvl, unitClass.c_str(), "SndHeroSpawned", lo.heroSpawnCue);
    GetPropertyValueInherited(lvl, unitClass.c_str(), "SndHeroDefeated", lo.heroDefeatCue);
    float vt = -1.0f;
    if (GetFloatPropertyInherited(lvl, unitClass.c_str(), "VOUnitType", vt)) lo.voUnitType = (int)vt;
    List<String> vs;
    lo.voRows.clear();
    if (GetPropertyListInherited(lvl, unitClass.c_str(), "VOSound", vs))
        for (size_t i = 0; i < vs.Size(); ++i)
        {
            std::istringstream ss(vs[i].Buffer());
            UnitLoadout::VoRow row;
            if (!(ss >> row.cue >> row.event)) continue;
            std::string c;
            while (ss >> c) if (c.size() > 1 && c[0] == '+') row.conds.push_back(c.substr(1));
            lo.voRows.push_back(std::move(row));
        }
    logf("  M491 voice \"%s\": hurt \"%s\" death \"%s\" VOUnitType %d, %u VOSound row(s)%s%s%s\n",
        unitClass.c_str(), lo.hurtSound.c_str(), lo.deathSound.c_str(), lo.voUnitType, (unsigned)lo.voRows.size(),
        lo.heroSpawnCue.empty() ? "" : ", hero spawn \"", lo.heroSpawnCue.c_str(), lo.heroSpawnCue.empty() ? "" : "\"");
}

static std::map<std::string, TroopVoiceData> g_painVoice;
static const TroopVoiceData* PainVoiceByName(const std::string& n)
{
    if (g_painVoice.empty())
        for (const VoGenPain& p : kVoGenPain)
        {
            TroopVoiceData d;
            for (int i = 0; i < p.count; ++i) d.clips.push_back(kVoGenPainSamples[p.first + i]);
            d.playProbability = p.probability;
            g_painVoice.emplace(p.name, d);
        }
    auto it = g_painVoice.find(n);
    return (it == g_painVoice.end()) ? nullptr : &it->second;
}
static const TroopVoiceData& ClassPainVoice(const std::string& cls, int team, bool death)
{
    auto it = g_unitClassLoadout.find(cls);
    if (it != g_unitClassLoadout.end())
    {
        const std::string& n = death ? it->second.deathSound : it->second.hurtSound;
        if (!n.empty()) if (const TroopVoiceData* d = PainVoiceByName(n)) return *d;

        if (!it->second.heroSpawnCue.empty())
        {
            static const TroopVoiceData kSilent{ {}, 0.0f };
            return kSilent;
        }
    }
    const int t = (team == 2) ? 2 : (team == 1) ? 1 : 0;
    return death ? g_deathVoiceByTeam[t] : g_hurtVoiceByTeam[t];
}
static void CollectClassPainSamples(std::vector<const char*>& out)
{
    for (const auto& kv : g_unitClassLoadout)
        for (int k = 0; k < 2; ++k)
        {
            const std::string& n = k ? kv.second.deathSound : kv.second.hurtSound;
            if (const TroopVoiceData* d = n.empty() ? nullptr : PainVoiceByName(n))
                for (const char* c : d->clips) out.push_back(c);
        }
}
static void ReadClassJetpack(Level* lvl, const std::string& unitClass, UnitLoadout& lo)
{
    ReadClassVoice(lvl, unitClass, lo);
    std::string jt;
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "MaxHealth", lo.classMaxHealth);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "EnergyBar", lo.classEnergyBar);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "EnergyRestore", lo.classEnergyRestore);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "EnergyRestoreIdle", lo.classEnergyRestoreIdle);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "EnergyDrainSprint", lo.classEnergyDrainSprint);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "EnergyMinSprint", lo.classEnergyMinSprint);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "MaxStrafeSpeed", lo.classMaxStrafeSpeed);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "MaxTurnSpeed", lo.classMaxTurnSpeed);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JumpHeight", lo.classJumpHeight);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "MaxSpeed", lo.maxSpeed);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "CollisionRootScale", lo.collisionRootScale);

    {
        std::string cscale;
        if (GetPropertyValueInherited(lvl, unitClass.c_str(), "CollisionScale", cscale) && !cscale.empty())
        {
            float s0 = 1.0f, s1 = 0.0f, s2 = 0.0f;
            if (sscanf(cscale.c_str(), "%f %f %f", &s0, &s1, &s2) >= 1) lo.collisionScale = s0;
        }
    }

    const bool hasType = GetPropertyValueInherited(lvl, unitClass.c_str(), "JetType", jt) && !jt.empty();
    float jj = 0.0f;
    const bool hasJump = GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetJump", jj) && jj > 0.0f;
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetJump", lo.jetJump);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetPush", lo.jetPush);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetAcceleration", lo.jetAccel);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetFuelRechargeRate", lo.jetFuelRecharge);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetFuelCost", lo.jetFuelCost);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetFuelInitialCost", lo.jetFuelInitial);
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetFuelMinBorder", lo.jetFuelMin);
    std::string jetFx;
    GetPropertyValueInherited(lvl, unitClass.c_str(), "JetEffect", jetFx);
    const bool fuelOrFxJet = lo.jetFuelInitial > 0.0f || lo.jetFuelMin > 0.0f || lo.jetFuelCost > 0.0f || !jetFx.empty();
    if (!hasType && (!hasJump || !fuelOrFxJet))
    {

        lo.hasForceJump = hasJump;
        lo.forceJumpPush = jj;
        GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetEnergyDrain", lo.forceJumpEnergy);
        GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetAcceleration", lo.jetAccel);
        if (lo.forceJumpEnergy <= 0.0f) lo.forceJumpEnergy = 40.0f;
        if (hasJump)
            logf("  HEROES force jump \"%s\": push=%.1f energy=%.1f (a jet-jump push on the energy bar, no hover)\n",
                unitClass.c_str(), lo.forceJumpPush, lo.forceJumpEnergy);
        return;
    }
    if (!hasType) jt = "(jump jet)";
    lo.hasJet = true;

    lo.jetHover = hasType && jt == "hover";
    GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetDuration", lo.jetDuration);
    { float sh = 1.0f; if (GetFloatPropertyInherited(lvl, unitClass.c_str(), "JetShowHud", sh)) lo.jetShowHud = sh >= 0.5f; }
    List<String> cs;
    if (GetPropertyListInherited(lvl, unitClass.c_str(), "ControlSpeed", cs))
        for (size_t ci = 0; ci < cs.Size(); ++ci)
        {
            char st[16] = {0}; float a = 1, b = 1, c = 1;
            if (sscanf(cs[ci].Buffer(), "%15s %f %f %f", st, &a, &b, &c) == 4 && strcmp(st, "jet") == 0)
            { lo.jetThrust = a; lo.jetStrafe = b; }
        }
    logf("  M430 jet \"%s\": type=%s jump=%.1f push=%.1f accel=%.1f fuel(recharge %.2f cost %.2f initial %.2f min %.2f) ControlSpeed jet %.2f/%.2f hover %d\n",
        unitClass.c_str(), jt.c_str(), lo.jetJump, lo.jetPush, lo.jetAccel, lo.jetFuelRecharge,
        lo.jetFuelCost, lo.jetFuelInitial, lo.jetFuelMin, lo.jetThrust, lo.jetStrafe, (int)lo.jetHover);
}

static float MeleeComboTime(const Field& f, uint8_t first, bool& fromAnim)
{
    float v = f.GetFloat(first);
    fromAnim = false;
    if (f.GetNumValues() > first + 1)
    {
        const std::string unit = f.GetString(first + 1).Buffer();
        if (strcasecmp(unit.c_str(), "frames") == 0) v *= 0.033333335f;
        else if (strcasecmp(unit.c_str(), "fromanim") == 0) fromAnim = true;
    }
    return v;
}
static bool ParseMeleeCombo(Level* lvl, const std::string& comboName, MeleeCombo& out)
{
    out = MeleeCombo();
    if (lvl == nullptr || comboName.empty()) return false;
    const uint32_t want = LibSWBF2::FNV::Hash(String(comboName.c_str()));
    const List<const Config*> cfgs = lvl->GetConfigs(EConfigType::Combo);
    const Config* cfg = nullptr;
    for (size_t i = 0; i < cfgs.Size(); ++i) if (cfgs[i]->m_Name == want) { cfg = cfgs[i]; break; }
    if (cfg == nullptr) { logf("  MELEE combo \"%s\": not in this .lvl (%u combo configs)\n", comboName.c_str(), (unsigned)cfgs.Size()); return false; }
    auto H = [](const char* n) { return LibSWBF2::FNV::Hash(String(n)); };
    const uint32_t hState = H("State"), hAnim = H("Animation"), hRestart = H("RestartAnimation"), hDur = H("Duration"),
                  hAttack = H("Attack"), hTrans = H("Transition"), hIf = H("If"), hButton = H("Button"), hBreak = H("Break"),
                  hTStart = H("TimeStart"), hTEnd = H("TimeEnd"), hSound = H("Sound"), hDTime = H("DamageTime"),
                  hDLen = H("DamageLength"), hDWid = H("DamageWidth"), hDmg = H("Damage"), hPush = H("Push");
    struct PendingTrans { size_t state; std::string target; bool fire; };
    std::vector<PendingTrans> trans;
    std::string idleFireTarget;
    const List<const Field*> top = cfg->GetFields(hState);
    for (size_t i = 0; i < top.Size(); ++i)
    {
        const Field& sf = *top[i];
        const std::string name = sf.GetString(0).Buffer();
        const List<const Field*> body = sf.m_Scope.GetFields();
        if (strcasecmp(name.c_str(), "IDLE") == 0)
        {
            for (size_t k = 0; k < body.Size(); ++k)
                if (body[k]->GetNameHash() == hTrans && body[k]->GetNumValues() > 0)
                { idleFireTarget = body[k]->GetString(0).Buffer(); break; }
            continue;
        }
        MeleeState st;
        st.name = name;
        for (size_t k = 0; k < body.Size(); ++k)
        {
            const Field& f = *body[k];
            const uint32_t h = f.GetNameHash();
            if (h == hAnim && f.GetNumValues() > 0) st.anim = f.GetString(0).Buffer();
            else if (h == hRestart) st.restart = true;
            else if (h == hDur && f.GetNumValues() > 0) st.duration = MeleeComboTime(f, 0, st.durationFromAnim);
            else if (h == hSound && f.GetNumValues() > 0) st.swingSound = strcasecmp(f.GetString(0).Buffer(), "com_weap_throw") == 0;
            else if (h == hAttack)
            {
                MeleeAttack a;
                const List<const Field*> af = f.m_Scope.GetFields();
                for (size_t j = 0; j < af.Size(); ++j)
                {
                    const Field& g = *af[j];
                    const uint32_t gh = g.GetNameHash();
                    if (gh == hDTime && g.GetNumValues() >= 2)
                    {
                        bool fa = false;
                        a.t0 = g.GetFloat(0); a.t1 = g.GetFloat(1);
                        if (g.GetNumValues() >= 3)
                        {
                            const std::string unit = g.GetString(2).Buffer();
                            if (strcasecmp(unit.c_str(), "frames") == 0) { a.t0 *= 0.033333335f; a.t1 *= 0.033333335f; }
                            else if (strcasecmp(unit.c_str(), "fromanim") == 0) fa = true;
                        }
                        a.fromAnim = fa;
                    }
                    else if (gh == hDLen && g.GetNumValues() > 0) a.length = g.GetFloat(0);
                    else if (gh == hDWid && g.GetNumValues() > 0) a.width = g.GetFloat(0);
                    else if (gh == hDmg && g.GetNumValues() > 0) a.damage = g.GetFloat(0);
                    else if (gh == hPush && g.GetNumValues() > 0) a.push = g.GetFloat(0);
                }
                st.attacks.push_back(a);
            }
            else if (h == hTrans && f.GetNumValues() > 0)
            {
                PendingTrans pt{ out.states.size(), f.GetString(0).Buffer(), false };
                const List<const Field*> tf = f.m_Scope.GetFields(hIf);
                if (tf.Size() > 0)
                {
                    const List<const Field*> cond = tf[0]->m_Scope.GetFields();
                    for (size_t j = 0; j < cond.Size(); ++j)
                    {
                        const Field& c = *cond[j];
                        const uint32_t ch = c.GetNameHash();
                        bool fa = false;
                        if (ch == hButton && c.GetNumValues() > 0 && strcasecmp(c.GetString(0).Buffer(), "Fire") == 0) pt.fire = true;
                        else if (ch == hBreak && c.GetNumValues() > 0) st.fireBreak = MeleeComboTime(c, 0, fa);
                        else if (ch == hTStart && c.GetNumValues() > 0) st.fireStart = MeleeComboTime(c, 0, fa);
                        else if (ch == hTEnd && c.GetNumValues() > 0) st.fireEndFromEnd = MeleeComboTime(c, 0, fa);
                    }
                    if (!pt.fire) continue;
                }
                trans.push_back(pt);
            }
        }
        out.states.push_back(st);
    }
    auto find = [&](const std::string& n) -> int
    {
        if (strcasecmp(n.c_str(), "IDLE") == 0) return -1;
        for (size_t i = 0; i < out.states.size(); ++i) if (strcasecmp(out.states[i].name.c_str(), n.c_str()) == 0) return (int)i;
        return -1;
    };
    for (MeleeState& st : out.states) st.onFire = -2;
    for (const PendingTrans& pt : trans)
    {
        if (pt.fire) out.states[pt.state].onFire = find(pt.target);
        else if (out.states[pt.state].next == -1) out.states[pt.state].next = find(pt.target);
    }
    out.start = find(idleFireTarget);
    logf("  MELEE combo \"%s\": %u state(s), Fire from IDLE -> %s\n", comboName.c_str(), (unsigned)out.states.size(),
         out.start >= 0 ? out.states[(size_t)out.start].name.c_str() : "(none)");
    for (const MeleeState& st : out.states)
    {
        logf("    state %s anim \"%s\" restart %d duration %.3f%s next %d onFire %d (break %.2f, %.2f..end-%.2f) sound %d\n",
             st.name.c_str(), st.anim.c_str(), st.restart ? 1 : 0, st.duration, st.durationFromAnim ? " of the clip" : " s",
             st.next, st.onFire, st.fireBreak, st.fireStart, st.fireEndFromEnd, st.swingSound ? 1 : 0);
        for (const MeleeAttack& a : st.attacks)
            logf("      attack: damage time %.3f..%.3f%s length %.2f width %.2f damage %.0f push %.1f\n",
                 a.t0, a.t1, a.fromAnim ? " of the clip" : " s", a.length, a.width, a.damage, a.push);
    }
    return out.start >= 0;
}

static int ResolveWeaponByName(Level* lvl, const std::string& weaponName)
{
    if (lvl == nullptr || weaponName.empty()) return -1;
    for (size_t i = 0; i < g_weaponTable.size(); ++i)
        if (g_weaponTable[i].name == weaponName) return (int)i;

    WeaponStats ws;
    ws.name = weaponName;
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "ShotDelay",   ws.shotDelay);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "MaxRange",    ws.maxRange);

    GetFloatPropertyInherited(lvl, weaponName.c_str(), "MinRange",     ws.minRange);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "OptimalRange", ws.optimalRange);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "ShotElevate",  ws.shotElevate);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "YawSpread",   ws.yawSpread);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "AIBubbleSizeMultiplier", ws.aiBubbleSizeMult);
    { float c = 0.0f; if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "AIBubbleCircle", c)) ws.aiBubbleCircle = (c != 0.0f); }
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "AIBubbleScaleDistDivider", ws.aiBubbleDistDiv);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "AIBubbleScaleClamp", ws.aiBubbleClamp);
    if (ws.aiBubbleDistDiv < 0.01f) ws.aiBubbleDistDiv = 20.0f;
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "SpreadPerShot", ws.spreadPerShot);
    { float v = 0.0f; if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "BarrageMin", v)) ws.barrageMin = (int)v;
                      if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "BarrageMax", v)) ws.barrageMax = (int)v; }
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "BarrageDelay", ws.barrageDelay);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "SpreadRecoverRate", ws.spreadRecover);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "SpreadLimit", ws.spreadLimit);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "SpreadThreshold", ws.spreadThreshold);
    {

        float cntF = 0.0f;
        if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "ShotPatternCount", cntF) && cntF >= 1.0f)
        {
            List<String> py;
            if (GetPropertyListInherited(lvl, weaponName.c_str(), "ShotPatternPitchYaw", py))
                for (size_t i = 0; i < py.Size() && (int)i < (int)cntF; ++i)
                {
                    float p = 0.0f, y = 0.0f;
                    if (sscanf(py[i].Buffer(), "%f %f", &p, &y) >= 1) { ws.patPitch.push_back(p); ws.patYaw.push_back(y); }
                }
            if (!ws.patYaw.empty()) logf("    SPREAD pattern \"%s\": %d entries (first yaw %.2f, last %.2f)\n", weaponName.c_str(), (int)ws.patYaw.size(), ws.patYaw.front(), ws.patYaw.back());
        }
    }
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "StandStillSpread", ws.standStill);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "StandMoveSpread", ws.standMove);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "CrouchStillSpread", ws.crouchStill);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "CrouchMoveSpread", ws.crouchMove);
    if (ws.aiBubbleSizeMult != 1.0f || ws.aiBubbleCircle)
        logf("M498 weapon bubble \"%s\": AIBubbleSizeMultiplier=%.2f AIBubbleCircle=%d\n", weaponName.c_str(), ws.aiBubbleSizeMult, (int)ws.aiBubbleCircle);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "PitchSpread", ws.pitchSpread);
    {

        float salvo = 1.0f;
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "ShotsPerSalvo", salvo);
        ws.shotsPerSalvo = (salvo >= 1.0f) ? (int)salvo : 1;
    }
    {
        std::string bank;
        if (GetPropertyValueInherited(lvl, weaponName.c_str(), "AnimationBank", bank) && !bank.empty())
        {
            ws.animBank = bank;
            ws.animBankDeclared = true;
        }

    }
    {
        std::string wgeo;
        if (GetPropertyValueInherited(lvl, weaponName.c_str(), "GeometryName", wgeo)) g_weaponGeometry[weaponName] = wgeo;
        else
        {

            std::string tag;
            if (GetPropertyValueInherited(lvl, weaponName.c_str(), "HUDTag", tag) && !tag.empty())
            {

                if (weaponName == "rep_weap_inf_buff_defense")
                    tag = "hud_rep_weap_defense_buff_icon";

                for (char& ch : tag) ch = (char)tolower((unsigned char)ch);
                g_weaponGeometry[weaponName] = tag;
                ws.modelIsIconOnly = true;
            }
            else
            {

                for (const HudNameMesh* e = kHudNameMesh; e->weapon != nullptr; ++e)
                    if (weaponName == e->weapon) { g_weaponHudMesh[weaponName] = e->mesh; break; }
            }
        }

        if (ClassLabelOf(lvl, weaponName.c_str()) == "melee")
        {
            std::string tag;
            if (GetPropertyValueInherited(lvl, weaponName.c_str(), "HUDTag", tag) && !tag.empty())
            {
                for (char& ch : tag) ch = (char)tolower((unsigned char)ch);
                g_weaponHudMesh[weaponName] = tag;
            }
        }
    }
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "ReloadTime",  ws.reloadTime);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "RoundsPerClip", ws.roundsPerClip);

    {
        std::string wlabel;
        const EntityClass* wec = GetEntityClassAnyLevel(lvl, weaponName.c_str(), lvl);
        if (wec != nullptr) wlabel = wec->GetBaseName().Buffer();
        if (wlabel == "shield")
        {
            ws.isShieldWeapon = GetFloatPropertyInherited(lvl, weaponName.c_str(), "MaxShield", ws.shieldMax)
                                && ws.shieldMax > 0.0f;
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "AddShield",    ws.shieldAddOn);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "AddShieldOff", ws.shieldAddOff);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "ShieldRadius", ws.shieldRadius);
            std::string off;
            if (GetPropertyValueInherited(lvl, weaponName.c_str(), "ShieldOffset", off))
            {
                float ox = 0.0f, oy = 0.0f, oz = 0.0f;
                if (sscanf(off.c_str(), "%f %f %f", &ox, &oy, &oz) == 3) ws.shieldOffset = Vector3(ox, oy, oz);
            }
            logf("MILESTONE 312: real shield weapon \"%s\": max=%.0f on=%.0f/s off=%.0f/s radius=%.2f offset=(%.2f,%.2f,%.2f)\n",
                 weaponName.c_str(), ws.shieldMax, ws.shieldAddOn, ws.shieldAddOff, ws.shieldRadius,
                 ws.shieldOffset.m_X, ws.shieldOffset.m_Y, ws.shieldOffset.m_Z);
        }
    }

    if (ws.shotDelay <= 0.0f && ws.reloadTime > 0.0f && ws.roundsPerClip <= 1.0f)
    {
        ws.shotDelay = ws.reloadTime;
    }

    {
        float f = 0.0f;
        if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "SalvoCount", f) && f >= 1.0f)
            ws.salvoCount = (int)(f + 0.5f);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "SalvoDelay", ws.salvoDelay);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "InitialSalvoDelay", ws.initialSalvoDelay);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "EnergyDrain", ws.energyCost);

    if (ClassLabelOf(lvl, weaponName.c_str()) == "areaeffectweapon")
    {
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "AreaRange", ws.aeRange);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "AreaRadius", ws.aeRadius);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "AreaHeight", ws.aeHeight);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "EffectDamage", ws.aeDamage);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "EffectStrength", ws.aeStrength);
        GetPropertyValueInherited(lvl, weaponName.c_str(), "EffectType", ws.aeType);
        ws.isAreaEffect = (ws.aeType == "Choke" && ws.aeRange > 0.0f);
        if (ws.isAreaEffect)
            logf("  HEROES choke \"%s\": range %.1f radius %.1f height %.1f damage %.1f strength %.1f\n",
                 weaponName.c_str(), ws.aeRange, ws.aeRadius, ws.aeHeight, ws.aeDamage, ws.aeStrength);
    }

    GetFloatPropertyInherited(lvl, weaponName.c_str(), "LockOnRange", ws.lockOnRange);

    if (ClassLabelOf(lvl, weaponName.c_str()) == "melee")
    {
        ws.isMelee = true;
        ws.weaponClassLabel = "melee";
        std::string cab;
        if (GetPropertyValueInherited(lvl, weaponName.c_str(), "ComboAnimationBank", cab))
        {
            char setName[64] = {}, parent[64] = {}, comboName[64] = {};
            if (sscanf(cab.c_str(), "%63s %63s %63s", setName, parent, comboName) == 3)
            {
                const char* us = strchr(setName, '_');
                ws.animBank = us != nullptr ? us + 1 : setName;
                ws.animBankDeclared = true;
                ParseMeleeCombo(lvl, comboName, ws.combo);
                if (combo::Parse(lvl, comboName, ws.jedi))
                    logf("  HEROES combo \"%s\": %u state(s), IDLE %d, %u unknown keyword(s)\n", comboName,
                         (unsigned)ws.jedi.states.size(), ws.jedi.idle, (unsigned)ws.jedi.unknown.size());
            }
        }
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "PersonScale", ws.meleePersonScale);

        GetFloatPropertyInherited(lvl, weaponName.c_str(), "LightSaberLength", ws.saberLength);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "LightSaberWidth", ws.saberWidth);
        if (GetPropertyValueInherited(lvl, weaponName.c_str(), "LightSaberTexture", ws.saberTexture) && !ws.saberTexture.empty())
            GrabLvlTexture(lvl, ws.saberTexture.c_str());
    }
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "LockTime", ws.lockTime);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "LockOnAngle", ws.lockOnAngle);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "LockOffAngle", ws.lockOffAngle);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "AutoAimSize", ws.autoAimSize);
    {

        std::string wcur = weaponName;
        Level* al = lvl;
        for (int hop = 0; hop < 8; ++hop)
        {
            const EntityClass* e = GetEntityClassAnyLevel(al, wcur.c_str(), al);
            if (e == nullptr) break;
            const std::string b = e->GetBaseName().Buffer();
            if (b.empty()) break;
            wcur = b;
        }
        ws.isRepairType = (wcur == "repair");
        if (wcur == "invisibility")
        {
            ws.isInvisibility = true;
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "InitialEnergyDrain", ws.invInitDrain);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "EnergyDrain", ws.invDrain);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "InvisibilityMin", ws.invMin);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "InvisibilityMax", ws.invMax);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "SpeedForInvisibilityMin", ws.invSpdMin);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "SpeedForInvisibilityMax", ws.invSpdMax);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "InvisibilityIncRate", ws.invInc);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "InvisibilityDecRate", ws.invDec);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "FlickerAmplitude", ws.invFlickAmp);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "FlickerTimeMin", ws.invFlickMin);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "FlickerTimeMax", ws.invFlickMax);
            logf("  CLASSKIT stealth \"%s\": drain %.0f + %.0f/s, invisibility %.2f..%.2f at %.1f..%.1f m/s, +%.1f/-%.1f per s, flicker -%.1f every %.0f-%.0f s\n",
                 weaponName.c_str(), ws.invInitDrain, ws.invDrain, ws.invMin, ws.invMax, ws.invSpdMax, ws.invSpdMin, ws.invInc, ws.invDec,
                 ws.invFlickAmp, ws.invFlickMin, ws.invFlickMax);
        }
        if (ws.isRepairType)
        {
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "BuildingHealth",  ws.repairBuildingHealth);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "BuildingRebuild", ws.repairBuildingRebuild);
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "VehicleHealth",   ws.repairVehicleHealth);
            logf("  M469 repair weapon \"%s\": BuildingHealth %.0f BuildingRebuild %.0f VehicleHealth %.0f LockOnRange %.1f LockOnAngle %.0f\n",
                 weaponName.c_str(), ws.repairBuildingHealth, ws.repairBuildingRebuild, ws.repairVehicleHealth, ws.lockOnRange, ws.lockOnAngle);
        }
    }
    {
        float tp = 1.0f, td = 1.0f, tv = 0.0f;
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "TargetPerson", tp);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "TargetDroid", td);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "TargetVehicle", tv);
        ws.targetPerson = (tp != 0.0f);
        ws.targetDroid = (td != 0.0f);
        ws.targetVehicle = (tv != 0.0f);
        {
            float all = -1.0f, ap = -1.0f, ad = -1.0f, av = -1.0f;
            GetFloatPropertyInherited(lvl, weaponName.c_str(), "AITargetAll", all);
            if (all >= 0.0f) ws.aiTargetPerson = ws.aiTargetDroid = ws.aiTargetVehicle = (all != 0.0f);
            if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "AITargetPerson", ap))  ws.aiTargetPerson = (ap != 0.0f);
            if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "AITargetDroid", ad))   ws.aiTargetDroid = (ad != 0.0f);
            if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "AITargetVehicle", av)) ws.aiTargetVehicle = (av != 0.0f);
        }
    }
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "ZoomMin", ws.zoomMin);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "ZoomMax", ws.zoomMax);
    ws.zoomTurnDivisorMin = ws.zoomMin;
    ws.zoomTurnDivisorMax = ws.zoomMax;
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "ZoomTurnDivisorMin", ws.zoomTurnDivisorMin);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "ZoomTurnDivisorMax", ws.zoomTurnDivisorMax);
    GetFloatPropertyInherited(lvl, weaponName.c_str(), "ZoomRate", ws.zoomRate);
    { float zfp = 0.0f; GetFloatPropertyInherited(lvl, weaponName.c_str(), "ZoomFirstPerson", zfp); ws.zoomFirstPerson = zfp > 0.5f; }
        float ts = 0.0f;
        if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "TriggerSingle", ts))
            ws.triggerSingle = (ts >= 0.5f);

    }

    std::string ordName;
    if (GetPropertyValueInherited(lvl, weaponName.c_str(), "OrdnanceName", ordName) && !ordName.empty())
    {
        GetFloatPropertyInherited(lvl, ordName.c_str(), "MaxDamage",         ws.maxDamage);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "VehicleScale",      ws.ordVehicleScale);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "ArmorScale",        ws.ordBuildingScale);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "BuildingScale",     ws.ordBuildingScale);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "DamageFinalDamage", ws.finalDamage);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "DamageTransitionDelay",  ws.damageTransitionDelay);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "DamageTransitionPeriod", ws.damageTransitionPeriod);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "Velocity",          ws.boltVelocity);

        GetFloatPropertyInherited(lvl, ordName.c_str(), "LifeSpan",     ws.ordLifeSpan);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "CableLength", ws.ordCableLength);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "InitialCableLength", ws.ordInitialCableLength);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "Gravity",      ws.ordGravity);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "Acceleration", ws.ordAcceleration);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "MinSpeed",     ws.ordMinSpeed);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "MaxHealth",    ws.ordMaxHealth);

        GetFloatPropertyInherited(lvl, ordName.c_str(), "Rebound",  ws.ordRebound);
        {
            std::string lc;
            if (GetPropertyValueInherited(lvl, ordName.c_str(), "LightColor", lc))
                sscanf(lc.c_str(), "%f %f %f %f", &ws.ordLightColor[0], &ws.ordLightColor[1], &ws.ordLightColor[2], &ws.ordLightColor[3]);
            GetFloatPropertyInherited(lvl, ordName.c_str(), "LightRadius", ws.ordLightRadius);
            if (GetPropertyValueInherited(lvl, ordName.c_str(), "EndLightColor", lc))
                sscanf(lc.c_str(), "%f %f %f %f", &ws.ordEndLightColor[0], &ws.ordEndLightColor[1], &ws.ordEndLightColor[2], &ws.ordEndLightColor[3]);
            { float f = 0.0f; if (GetFloatPropertyInherited(lvl, ordName.c_str(), "FadeLightColor", f)) ws.ordFadeLightColor = (f >= 0.5f); }
            GetPropertyValueInherited(lvl, ordName.c_str(), "TrailEffect", ws.ordTrailEffect);
            if (!GetPropertyValueInherited(lvl, ordName.c_str(), "ImpactEffectTerrain", ws.ordImpactEffect)
                && !GetPropertyValueInherited(lvl, ordName.c_str(), "ImpactEffect", ws.ordImpactEffect))
                GetPropertyValueInherited(lvl, ordName.c_str(), "ExpireEffect", ws.ordImpactEffect);
            { std::string cs; if (GetPropertyValueInherited(lvl, ordName.c_str(), "CollisionSound", cs)) ws.ordCollisionSnd = FindExpSoundDef(cs); }
            logf("  M462 ordnance \"%s\": light (%.0f %.0f %.0f %.0f) r=%.1f trail=%s\n", ordName.c_str(),
                 ws.ordLightColor[0], ws.ordLightColor[1], ws.ordLightColor[2], ws.ordLightColor[3], ws.ordLightRadius, ws.ordTrailEffect.c_str());
        }
        GetFloatPropertyInherited(lvl, ordName.c_str(), "Friction", ws.ordFriction);

        GetFloatPropertyInherited(lvl, ordName.c_str(), "SoldierHealth", ws.pickupHealth);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "SoldierAmmo",   ws.pickupAmmo);
        {
            float tc = 0.0f;
            if (GetFloatPropertyInherited(lvl, ordName.c_str(), "TriggerContact", tc)) ws.triggerContact = (tc >= 0.5f);
            GetFloatPropertyInherited(lvl, ordName.c_str(), "TriggerRadius", ws.triggerRadius);
        }

        {
            ws.isBuffWeapon = GetFloatPropertyInherited(lvl, ordName.c_str(), "BuffDefenseTimer", ws.buffDebuffDuration);
            if (ws.isBuffWeapon)
                GetFloatPropertyInherited(lvl, ordName.c_str(), "BuffDefenseMult", ws.buffDamageMult);
            ws.isDebuffWeapon = GetFloatPropertyInherited(lvl, ordName.c_str(), "DebuffDamageTimer", ws.buffDebuffDuration);
            if (ws.isDebuffWeapon)
                GetFloatPropertyInherited(lvl, ordName.c_str(), "DebuffDamageRate", ws.debuffDamageRate);

            if (!ws.isBuffWeapon && !ws.isDebuffWeapon
                && GetFloatPropertyInherited(lvl, ordName.c_str(), "BuffOffenseTimer", ws.buffDebuffDuration) && ws.buffDebuffDuration > 0.0f)
            {
                ws.isBuffWeapon = ws.isOffenseBuff = true;
                GetFloatPropertyInherited(lvl, ordName.c_str(), "BuffOffenseMult", ws.buffOffenseMult);
            }
            if (!ws.isBuffWeapon && !ws.isDebuffWeapon
                && GetFloatPropertyInherited(lvl, ordName.c_str(), "BuffHealthTimer", ws.buffDebuffDuration) && ws.buffDebuffDuration > 0.0f)
            {
                ws.isBuffWeapon = ws.isHealthBuff = true;
                GetFloatPropertyInherited(lvl, ordName.c_str(), "BuffHealthRate", ws.buffHealthRate);
            }
            if (ws.isBuffWeapon || ws.isDebuffWeapon)
            {
                float af = 0.0f, ae = 0.0f, aooo = 0.0f;
                if (GetFloatPropertyInherited(lvl, ordName.c_str(), "AffectFriends", af)) ws.buffDebuffAffectFriends = (af >= 0.5f);
                if (GetFloatPropertyInherited(lvl, ordName.c_str(), "AffectEnemies", ae)) ws.buffDebuffAffectEnemies = (ae >= 0.5f);
                if (GetFloatPropertyInherited(lvl, ordName.c_str(), "ApplyOnOwnerIfOnOthers", aooo)) ws.buffApplyToOwnerToo = (aooo >= 0.5f);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "Radius", ws.buffDebuffConeRadius);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "ConeAngle", ws.buffDebuffConeAngleDeg);
                float mt = 0.0f;
                if (GetFloatPropertyInherited(lvl, ordName.c_str(), "MaxTargets", mt)) ws.buffDebuffMaxTargets = (int)mt;
                GetPropertyValueInherited(lvl, ordName.c_str(), "PlayEffectOnOwner", ws.buffOwnerFx);
            }
        }

        {
            std::string ogeo;
            if (GetPropertyValueInherited(lvl, ordName.c_str(), "GeometryName", ogeo) && !ogeo.empty())
                g_ordnanceGeometry[weaponName] = ogeo;
        }
        {
            float f = 0.0f;
            if (GetFloatPropertyInherited(lvl, ordName.c_str(), "StickTerrain", f))  ws.ordStickTerrain = (f >= 0.5f);
            if (GetFloatPropertyInherited(lvl, ordName.c_str(), "StickBuilding", f)) ws.ordStickBuilding = (f >= 0.5f);
            if (GetFloatPropertyInherited(lvl, ordName.c_str(), "StickPerson", f))   ws.ordStickPerson = (f >= 0.5f);
            if (GetFloatPropertyInherited(lvl, ordName.c_str(), "StickVehicle", f))  ws.ordStickVehicle = (f >= 0.5f);

            if (GetFloatPropertyInherited(lvl, ordName.c_str(), "StickAll", f) && f >= 0.5f)
                ws.ordStickTerrain = ws.ordStickBuilding = ws.ordStickPerson = ws.ordStickVehicle = true;

            {

                std::string label;
                {
                    std::string cur = ordName;
                    Level* activeLvl = lvl;
                    for (int hop = 0; hop < 8; ++hop)
                    {

                        const EntityClass* ec2 = GetEntityClassAnyLevel(activeLvl, cur.c_str(), activeLvl);
                        if (ec2 == nullptr) { label = cur; break; }
                        const std::string base = ec2->GetBaseName().Buffer();
                        if (base.empty()) { label = cur; break; }
                        cur = base;
                    }
                }
                ws.ordClassLabel = label;

                {
                    std::string wcur = weaponName;
                    Level* activeLvl = lvl;
                    for (int hop = 0; hop < 8; ++hop)
                    {
                        const EntityClass* wc2 = GetEntityClassAnyLevel(activeLvl, wcur.c_str(), activeLvl);
                        if (wc2 == nullptr) { ws.weaponClassLabel = wcur; break; }
                        const std::string wb = wc2->GetBaseName().Buffer();
                        if (wb.empty()) { ws.weaponClassLabel = wcur; break; }
                        wcur = wb;
                    }
                }

                ws.ordIsThrown = (label == "grenade" || label == "sticky" || label == "mine" || label == "powerupitem");

                ws.isDetonatorType = (ws.weaponClassLabel == "detonator");

                ws.isPickupType = (label == "powerupitem");

                ws.alwaysSticksOnContact = (label == "mine" || label == "powerupitem");
            }
        }

        float ncl = 0.0f;
        if (GetFloatPropertyInherited(lvl, ordName.c_str(), "NEXTCHARGE", ncl)
            || GetFloatPropertyInherited(lvl, ordName.c_str(), "NextCharge", ncl))
        {
            ws.hasNextCharge = true;
            ws.nextChargeLevel = ncl;
        }
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "MaxPressedTime", ws.maxPressedTime);

        GetFloatPropertyInherited(lvl, weaponName.c_str(), "MinStrength", ws.minStrength);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "MaxStrength", ws.maxStrength);
        ws.isDispenserToss = ws.ordIsThrown && ws.boltVelocity <= 0.0001f && ws.maxStrength > 0.0001f;

        if (ws.weaponClassLabel == "dispenser") ws.isDispenserToss = true;

        { float ow = 0.0f;
          if (GetFloatPropertyInherited(lvl, weaponName.c_str(), "OffhandWeapon", ow)) ws.offhandWeapon = (ow >= 0.5f); }

        GetFloatPropertyInherited(lvl, weaponName.c_str(), "HeatPerShot",     ws.heatPerShot);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "HeatRecoverRate", ws.heatRecoverRate);
        GetFloatPropertyInherited(lvl, weaponName.c_str(), "HeatThreshold",   ws.heatThreshold);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "LaserLength",       ws.laserLength);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "LaserWidth",        ws.laserWidth);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "FadeOutTime",       ws.fadeOutTime);
        ResolveMuzzleFlash(lvl, weaponName.c_str(), ws);
        if (ws.flashRadius > 0.0f)
            logf("  MUZZLE FLASH \"%s\": radius %.2f length %.3f colour %u %u %u %u\n", weaponName.c_str(), ws.flashRadius, ws.flashLength,
                 (unsigned)ws.flashColor[0], (unsigned)ws.flashColor[1], (unsigned)ws.flashColor[2], (unsigned)ws.flashColor[3]);
        { std::string os;
          if (GetPropertyValueInherited(lvl, ordName.c_str(), "OrdnanceSound", os))
              ws.ordHum = (os == "com_weap_inf_ord_hum_sm") ? 1 : (os == "com_weap_inf_ord_hum_lg") ? 2 : 0; }
        ws.ordIsBeam = (ClassLabelOf(lvl, ordName.c_str()) == "beam");
        ws.ordIsFatRay = (ClassLabelOf(lvl, ordName.c_str()) == "fatray");
        if (ClassLabelOf(lvl, ordName.c_str()) == "emitterordnance" && !ws.isBuffWeapon && !ws.isDebuffWeapon)
        {
            float dmg = 0.0f, mdmg = 0.0f, mt = 1.0f, nc = 0.0f, vd = 0.0f, push = 0.0f, af = 0.0f;
            GetFloatPropertyInherited(lvl, ordName.c_str(), "Damage", dmg);
            GetFloatPropertyInherited(lvl, ordName.c_str(), "MaxDamage", mdmg);
            ws.emDamage = (dmg > 0.0f) ? dmg : mdmg;
            GetFloatPropertyInherited(lvl, ordName.c_str(), "Push", push);
            ws.emPush = push;
            if (ws.emDamage > 0.0f || ws.emPush > 0.0f)
            {
                ws.ordIsEmitter = true;
                GetFloatPropertyInherited(lvl, ordName.c_str(), "ConeLength", ws.emConeLen);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "ConeAngle", ws.emConeAngle);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "FirstRadius", ws.emFirstRadius);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "MaxJumpDistance", ws.emMaxJump);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "JumpDeduction", ws.emJumpDeduct);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "PersonScale", ws.emPersonScale);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "DroidScale", ws.emDroidScale);
                GetFloatPropertyInherited(lvl, ordName.c_str(), "SmolderEffectTimer", ws.emSmolderTimer);
                if (GetFloatPropertyInherited(lvl, ordName.c_str(), "AffectFriends", af)) ws.emAffectsFriends = af >= 0.5f;
                if (GetFloatPropertyInherited(lvl, ordName.c_str(), "MaxTargets", mt) && mt >= 1.0f) ws.emMaxTargets = (int)mt;
                if (GetFloatPropertyInherited(lvl, ordName.c_str(), "NoChaining", nc)) ws.emNoChain = nc >= 0.5f;
                if (GetFloatPropertyInherited(lvl, ordName.c_str(), "SmolderVanishDeath", vd)) ws.emVanish = vd >= 0.5f;
                GetPropertyValueInherited(lvl, ordName.c_str(), "LightningEffect", ws.emLightning);
                GetPropertyValueInherited(lvl, ordName.c_str(), "PlayEffectOnOwnerAimer", ws.emOwnerAimerFx);
                GetPropertyValueInherited(lvl, ordName.c_str(), "SmolderEffect", ws.emSmolderFx);
                std::string ex;
                if (GetPropertyValueInherited(lvl, ordName.c_str(), "Explosion", ex)) GetPropertyValueInherited(lvl, ex.c_str(), "Effect", ws.emExpEffect);
                if (ws.emConeLen <= 0.0f) ws.emConeLen = 10.0f;
                ws.maxRange = ws.emConeLen;
                logf("  M491 emitter \"%s\": cone %.1f m x %.0f deg, first radius %.1f, %d target(s) %s, jump %.1f m (-%.0f), damage %.0f, push %.1f friends %d, lightning \"%s\", owner fx \"%s\", hit fx \"%s\"\n",
                    weaponName.c_str(), ws.emConeLen, ws.emConeAngle, ws.emFirstRadius, ws.emMaxTargets, ws.emNoChain ? "(no chaining)" : "(chain)",
                    ws.emMaxJump, ws.emJumpDeduct, ws.emDamage, ws.emPush, (int)ws.emAffectsFriends, ws.emLightning.c_str(), ws.emOwnerAimerFx.c_str(), ws.emExpEffect.c_str());
            }
        }
        if (ws.ordIsFatRay)
        {
            GetFloatPropertyInherited(lvl, ordName.c_str(), "RayRadius", ws.rayRadius);
            logf("  M474 fatray \"%s\": RayRadius %.1f LifeSpan %.2f Velocity %.0f\n", weaponName.c_str(), ws.rayRadius, ws.ordLifeSpan, ws.boltVelocity);
        }
        {

            std::string secName; float per = 0.0f, md = 0.0f;
            if ((GetPropertyValueInherited(lvl, weaponName.c_str(), "SecondaryOrdnanceName", secName) || GetPropertyValueInherited(lvl, weaponName.c_str(), "SecondaryOrdnance", secName))
                && !secName.empty() && GetFloatPropertyInherited(lvl, weaponName.c_str(), "SecondaryOrdnancePeriod", per) && per >= 1.0f
                && (!GetFloatPropertyInherited(lvl, secName.c_str(), "MaxDamage", md) || md <= 0.0f) && ClassLabelOf(lvl, secName.c_str()) == "bolt")
            {
                ws.secTracer = true;
                GetFloatPropertyInherited(lvl, secName.c_str(), "LaserLength", ws.secLaserLen);
                GetFloatPropertyInherited(lvl, secName.c_str(), "LaserWidth", ws.secLaserWidth);
                GetFloatPropertyInherited(lvl, secName.c_str(), "Velocity", ws.secTracerVel);
                GetFloatPropertyInherited(lvl, secName.c_str(), "FadeOutTime", ws.secFadeOutTime);
                ws.secTracerPeriod = (int)per;
                std::string col, tex;
                if (GetPropertyValueInherited(lvl, secName.c_str(), "LaserGlowColor", col)) { float c[4] = { 255, 255, 255, 255 }; sscanf(col.c_str(), "%f %f %f %f", &c[0], &c[1], &c[2], &c[3]); ws.secR = c[0] / 255.0f; ws.secG = c[1] / 255.0f; ws.secB = c[2] / 255.0f; }
                if (GetPropertyValueInherited(lvl, secName.c_str(), "LaserTexture", tex)) ws.secTexBlue = tex.find("blue") != std::string::npos;
                logf("  CLASSKIT visual secondary \"%s\" on \"%s\": length %.1f width %.2f colour %.2f %.2f %.2f\n", secName.c_str(), weaponName.c_str(), ws.secLaserLen, ws.secLaserWidth, ws.secR, ws.secG, ws.secB);
            }
        }
        {
            std::string secName; float per = 0.0f, md = 0.0f;
            if ((GetPropertyValueInherited(lvl, weaponName.c_str(), "SecondaryOrdnanceName", secName)
                 || GetPropertyValueInherited(lvl, weaponName.c_str(), "SecondaryOrdnance", secName))
                && GetFloatPropertyInherited(lvl, weaponName.c_str(), "SecondaryOrdnancePeriod", per) && per >= 1.0f
                && GetFloatPropertyInherited(lvl, secName.c_str(), "MaxDamage", md) && md > 0.0f)
            {
                float sv = 0.0f, sl = 0.0f;
                GetFloatPropertyInherited(lvl, secName.c_str(), "Velocity", sv);
                GetFloatPropertyInherited(lvl, secName.c_str(), "LifeSpan", sl);
                ws.secPeriod = (int)per; ws.secMaxDamage = md; ws.secRange = sv * sl;
                ws.secIsFatRay = (ClassLabelOf(lvl, secName.c_str()) == "fatray");
                ws.secVel = sv;
                if (ws.secIsFatRay)
                {
                    GetFloatPropertyInherited(lvl, secName.c_str(), "RayRadius", ws.secRayRadius);
                    GetPropertyValueInherited(lvl, secName.c_str(), "TrailEffect", ws.secTrail);
                }
                GetFloatPropertyInherited(lvl, secName.c_str(), "PersonScale", ws.secPersonScale);
                GetFloatPropertyInherited(lvl, secName.c_str(), "DroidScale", ws.secDroidScale);
                GetFloatPropertyInherited(lvl, secName.c_str(), "VehicleScale", ws.secVehicleScale);
                GetFloatPropertyInherited(lvl, secName.c_str(), "BuildingScale", ws.secBuildingScale);
                GetPropertyValueInherited(lvl, secName.c_str(), "ImpactEffect", ws.secImpactEffect);
                std::string sx, fs;
                if (GetPropertyValueInherited(lvl, secName.c_str(), "ExplosionName", sx))
                {
                    GetPropertyValueInherited(lvl, sx.c_str(), "Effect", ws.secExpEffect);
                    GetPropertyValueInherited(lvl, sx.c_str(), "SoundProperty", ws.secExpSound);
                }
                ws.secExpSoundIsFire = !ws.secExpSound.empty()
                    && GetPropertyValueInherited(lvl, weaponName.c_str(), "FireSound", fs) && fs == ws.secExpSound;
                logf("  M476 secondary explosion \"%s\": effect \"%s\" sound \"%s\"%s\n", sx.c_str(),
                    ws.secExpEffect.c_str(), ws.secExpSound.c_str(), ws.secExpSoundIsFire ? " (= the weapon's FireSound)" : "");
                logf("  M475 secondary ordnance \"%s\" on \"%s\": every %d shot(s), MaxDamage %.0f, range %.0f m, person %.2f droid %.2f vehicle %.2f building %.2f, impact \"%s\"\n",
                    secName.c_str(), weaponName.c_str(), ws.secPeriod, ws.secMaxDamage, ws.secRange,
                    ws.secPersonScale, ws.secDroidScale, ws.secVehicleScale, ws.secBuildingScale, ws.secImpactEffect.c_str());
            }
        }
        if (ws.ordIsBeam)
        {
            GetFloatPropertyInherited(lvl, ordName.c_str(), "LaserWidth", ws.beamWidth);
            GetFloatPropertyInherited(lvl, ordName.c_str(), "LifeSpan", ws.beamLife);
        }

        std::string col;
        if (GetPropertyValueInherited(lvl, ordName.c_str(), "LaserGlowColor", col))
            ParseRealColorTriplet(col.c_str(), ws.r, ws.g, ws.b);

        std::string tex;
        if (GetPropertyValueInherited(lvl, ordName.c_str(), "LaserTexture", tex))
            ws.laserTexIsBlue = (tex.find("blue") != std::string::npos);

        std::string impactName, expireName, triggerName;
        if (!GetPropertyValueInherited(lvl, ordName.c_str(), "ExplosionName", impactName) || impactName.empty())
            if (!GetPropertyValueInherited(lvl, ordName.c_str(), "ExplosionImpact", impactName) || impactName.empty())
                GetPropertyValueInherited(lvl, ordName.c_str(), "Explosion", impactName);
        GetPropertyValueInherited(lvl, ordName.c_str(), "ExplosionExpire", expireName);

        GetPropertyValueInherited(lvl, ordName.c_str(), "ExplosionTrigger", triggerName);

        LoadRealExplosion(lvl, impactName, ws.explImpact);
        LoadRealExplosion(lvl, expireName, ws.explExpire);
        LoadRealExplosion(lvl, triggerName, ws.explTrigger);

        const RealExplosion& primary = ws.explImpact.valid ? ws.explImpact : ws.explExpire;

        float lwHidden = -1.0f, llHidden = -1.0f;
        GetFloatPropertyInherited(lvl, ordName.c_str(), "LaserWidth", lwHidden);
        GetFloatPropertyInherited(lvl, ordName.c_str(), "LaserLength", llHidden);
        if (primary.valid && lwHidden == 0.0f && llHidden == 0.0f && primary.damage <= 0.0f && primary.push <= 0.0f)
        {
            ws.ordHidden = true;
            ws.hiddenExpEffect = primary.effect;
            std::string fs;
            GetPropertyValueInherited(lvl, impactName.c_str(), "SoundProperty", ws.hiddenExpSound);
            ws.hiddenExpSoundIsFire = !ws.hiddenExpSound.empty()
                && GetPropertyValueInherited(lvl, weaponName.c_str(), "FireSound", fs) && fs == ws.hiddenExpSound;
            logf("  M476 hidden bolt \"%s\": no laser, impact effect \"%s\" sound \"%s\"%s\n", ordName.c_str(),
                ws.hiddenExpEffect.c_str(), ws.hiddenExpSound.c_str(), ws.hiddenExpSoundIsFire ? " (= FireSound)" : "");
        }
        else if (primary.valid)
        {
            ws.hasExplosion = true;
            ws.explDamage       = primary.damage;
            ws.explRadiusInner  = primary.dmgRadiusInner;
            ws.explRadiusOuter  = primary.dmgRadiusOuter;
            ws.explPersonScale  = primary.personScale;
            ws.explDroidScale   = primary.droidScale;
            ws.explVehicleScale = primary.vehicleScale;
            ws.explBuildingScale = primary.buildingScale;
            ws.explPush         = primary.push;
            ws.explPushRadius   = primary.pushRadiusOuter;
        }
    }

    if (ws.maxPressedTime > 0.0f)
    {
        Level* fl = lvl;
        const EntityClass* ec = GetEntityClassAnyLevel(lvl, weaponName.c_str(), fl);
        if (ec)
        {
            List<LibSWBF2::FNVHash> hs; List<String> vs;
            ec->GetOverriddenProperties(hs, vs);
            auto Hs = [](const char* n) { return LibSWBF2::FNV::Hash(String(n)); };
            const LibSWBF2::FNVHash hNext = Hs("NEXTCHARGE"), hSalvo = Hs("ShotsPerSalvo"), hOrd = Hs("OrdnanceName"),
                          hPatN = Hs("ShotPatternCount"), hPat = Hs("ShotPatternPitchYaw"), hDelay = Hs("ShotDelay");
            float level = -1.0f; std::string ord; int salvo = -1; float delay = -1.0f; std::vector<float> pp, py; bool patSet = false;
            for (size_t i = 0; i < hs.Size(); ++i)
            {
                if (hs[i] == hNext) { if (level >= 0.0f) break; level = (float)atof(vs[i].Buffer()); continue; }
                if (level < 0.0f) continue;
                if (hs[i] == hSalvo) salvo = atoi(vs[i].Buffer());
                else if (hs[i] == hOrd) ord = vs[i].Buffer();
                else if (hs[i] == hDelay) delay = (float)atof(vs[i].Buffer());
                else if (hs[i] == hPatN) { pp.clear(); py.clear(); patSet = true; }
                else if (hs[i] == hPat) { float p = 0, y = 0; if (sscanf(vs[i].Buffer(), "%f %f", &p, &y) >= 1) { pp.push_back(p); py.push_back(y); } }
            }
            if (level >= 0.0f)
            {
                auto c = std::make_shared<WeaponStats>(ws);
                c->charged.reset(); c->chargeLevel = -1.0f;
                if (salvo >= 1) c->shotsPerSalvo = salvo;
                if (delay > 0.0f) c->shotDelay = delay;
                if (patSet) { c->patPitch = pp; c->patYaw = py; }
                if (!ord.empty())
                {
                    GetFloatPropertyInherited(lvl, ord.c_str(), "MaxDamage", c->maxDamage);
                    GetFloatPropertyInherited(lvl, ord.c_str(), "DamageFinalDamage", c->finalDamage);
                    GetFloatPropertyInherited(lvl, ord.c_str(), "DamageTransitionDelay", c->damageTransitionDelay);
                    GetFloatPropertyInherited(lvl, ord.c_str(), "DamageTransitionPeriod", c->damageTransitionPeriod);
                    GetFloatPropertyInherited(lvl, ord.c_str(), "Velocity", c->boltVelocity);
                    GetFloatPropertyInherited(lvl, ord.c_str(), "LifeSpan", c->ordLifeSpan);
                    GetFloatPropertyInherited(lvl, ord.c_str(), "Gravity", c->ordGravity);
                }
                ws.chargeLevel = level; ws.charged = c;
                logf("    CHARGE state of \"%s\" at %.2f: ShotsPerSalvo %d, ordnance \"%s\" (damage %.0f, velocity %.0f), pattern %d\n",
                     weaponName.c_str(), level, c->shotsPerSalvo, ord.c_str(), c->maxDamage, c->boltVelocity, (int)c->patYaw.size());
            }
        }
    }
    g_weaponTable.push_back(ws);
    logf("  real weapon resolved: \"%s\" ShotDelay=%.3f (Reload=%.1f Rounds=%.0f) MaxRange=%.1f Yaw=%.3f Dmg=%.0f/%.0f Vel=%.0f %s\n",
        ws.name.c_str(), ws.shotDelay, ws.reloadTime, ws.roundsPerClip,
        ws.maxRange, ws.yawSpread, ws.maxDamage, ws.finalDamage, ws.boltVelocity,
        ws.laserTexIsBlue ? "blue" : "red");

    logf("  WEAPONSTAT \"%s\" class=%s min=%.2f opt=%.2f max=%.2f dmg=%.2f final=%.2f scaleP=%.3f scaleV=%.3f "
         "shot=%.3f clip=%.0f reload=%.2f salvo=%d shots=%d salvoD=%.2f initD=%.2f "
         "sprPer=%.3f sprRec=%.2f sprThr=%.2f sprLim=%.2f laserL=%.2f laserW=%.3f vel=%.1f\n",
         ws.name.c_str(), ws.weaponClassLabel.c_str(), ws.minRange, ws.optimalRange, ws.maxRange,
         ws.maxDamage, ws.finalDamage, ws.explPersonScale, ws.explVehicleScale,
         ws.shotDelay, ws.roundsPerClip, ws.reloadTime, ws.salvoCount, ws.shotsPerSalvo,
         ws.salvoDelay, ws.initialSalvoDelay, ws.spreadPerShot, ws.spreadRecover, ws.spreadThreshold,
         ws.spreadLimit, ws.laserLength, ws.laserWidth, ws.boltVelocity);

    logf("    M226 lock-on: range=%.1f onAngle=%.1f offAngle=%.1f autoAimSize=%.1f "
         "targets[person=%d droid=%d vehicle=%d]%s\n",
         ws.lockOnRange, ws.lockOnAngle, ws.lockOffAngle, ws.autoAimSize,
         (int)ws.targetPerson, (int)ws.targetDroid, (int)ws.targetVehicle,
         ws.lockOnRange <= 0.001f ? "  <- NO ASSIST (real)" : "");
    logf("    M203 anim type inputs: bank=\"%s\"%s classLabel=\"%s\"\n",
        ws.animBank.c_str(), ws.animBankDeclared ? "(declared)" : "(DEFAULTED)",
        ws.weaponClassLabel.c_str());

    logf("    M169 salvo: SalvoCount=%d ShotsPerSalvo=%d SalvoDelay=%.3f InitialSalvoDelay=%.3f TrigSingle=%d"
         " | DmgTransition delay=%.3f period=%.3f  %.0f -> %.0f\n",
         ws.salvoCount, ws.shotsPerSalvo, ws.salvoDelay, ws.initialSalvoDelay, (int)ws.triggerSingle,
         ws.damageTransitionDelay, ws.damageTransitionPeriod, ws.maxDamage, ws.finalDamage);
    logf("    M173 ordnance: LifeSpan=%.2f Velocity=%.0f Gravity=%.2f Accel=%.0f MinSpeed=%.0f"
         " | MaxPressedTime=%.2f NextCharge=%d@%.2f | explImpact=%d explExpire=%d\n",
         ws.ordLifeSpan, ws.boltVelocity, ws.ordGravity, ws.ordAcceleration, ws.ordMinSpeed,
         ws.maxPressedTime, (int)ws.hasNextCharge, ws.nextChargeLevel,
         (int)ws.explImpact.valid, (int)ws.explExpire.valid);
    logf("    M195 class: label=\"%s\" thrown=%d rebound=%.2f friction=%.2f stick(t=%d b=%d p=%d)\n",
         ws.ordClassLabel.c_str(), (int)ws.ordIsThrown, ws.ordRebound, ws.ordFriction,
         (int)ws.ordStickTerrain, (int)ws.ordStickBuilding, (int)ws.ordStickPerson);
    return (int)(g_weaponTable.size() - 1);
}

static int ResolveWeaponForUnitClass(Level* lvl, const std::string& unitClass)
{
    if (lvl == nullptr) return -1;

    {

        std::string ut;
        if (GetPropertyValueInherited(lvl, unitClass.c_str(), "UnitType", ut))
        { for (char& ch : ut) ch = (char)tolower((unsigned char)ch); g_classIsScout[unitClass] = (ut == "scout"); }
    }
    std::string weaponName;
    {
        List<String> allWeapons;
        if (GetPropertyListInherited(lvl, unitClass.c_str(), "WeaponName", allWeapons))
        {
            for (size_t i = 0; i < allWeapons.Size(); ++i)
            {
                const std::string cand = allWeapons[i].Buffer();
                if (cand.find("_inf_") != std::string::npos) { weaponName = cand; break; }
            }
            if (weaponName.empty() && allWeapons.Size() > 0) weaponName = allWeapons[0].Buffer();
        }
    }
    if (weaponName.empty()
        && !GetPropertyValueInherited(lvl, unitClass.c_str(), "WeaponName", weaponName)) return -1;

    return ResolveWeaponByName(lvl, weaponName);
}

static void ResolvePerSideWeapons(const char* lvlPath, const std::set<std::string>& unitClasses)
{
    if (unitClasses.empty()) return;
    if (!FileExists(lvlPath)) return;

    for (const std::string& unitClass : unitClasses)
    {
        Level* lvl = nullptr;
        try
        {
            List<String> subLvls;
            subLvls.Add(String(unitClass.c_str()));
            lvl = TimedLevelFromFile(String(lvlPath), &subLvls);
            if (lvl != nullptr)
            {
                const int idx = ResolveWeaponForUnitClass(lvl, unitClass);
                if (idx >= 0) g_unitClassWeapon[unitClass] = idx;
                else logf("  real weapon NOT resolved for unit class \"%s\" - it will fall back to the shared rifle stats\n", unitClass.c_str());
                ReadClassUnlockCost(lvl, unitClass);

                {
                    UnitLoadout lo;
                    List<String> names, ammos;
                    GetPropertyListInherited(lvl, unitClass.c_str(), "WeaponName", names);
                    GetPropertyListInherited(lvl, unitClass.c_str(), "WeaponAmmo", ammos);
                    for (size_t i = 0; i < names.Size(); ++i)
                    {
                        const std::string wn = names[i].Buffer();
                        if (wn.empty()) continue;

                        if (wn.find("_award_") != std::string::npos) continue;
                        const int wIdx = ResolveWeaponByName(lvl, wn);
                        lo.slotWeapon.push_back(wIdx);
                        lo.slotName.push_back(wn);
                        lo.slotAmmo.push_back((i < ammos.Size()) ? atoi(ammos[i].Buffer()) : 0);
                    }
                    ReadClassJetpack(lvl, unitClass, lo);
                    { float ne = 0.0f; if (GetFloatPropertyInherited(lvl, unitClass.c_str(), "NoEnterVehicles", ne)) lo.noEnterVehicles = (ne != 0.0f); }
                    if (!lo.slotWeapon.empty())
                    {
                        g_unitClassLoadout[unitClass] = lo;
                        std::string dump;
                        for (size_t i = 0; i < lo.slotName.size(); ++i)
                        {
                            char b[160];
                            snprintf(b, sizeof(b), " [%u:%s ammo=%d%s]", (unsigned)i,
                                     lo.slotName[i].c_str(), lo.slotAmmo[i],
                                     lo.slotWeapon[i] < 0 ? " UNRESOLVED" : "");
                            dump += b;
                        }
                        logf("  M180 loadout \"%s\":%s\n", unitClass.c_str(), dump.c_str());
                    }
                }
            }
            else
            {
                logf("  ResolvePerSideWeapons: load failed for \"%s\"\n", unitClass.c_str());
            }
        }
        catch (const std::exception& e)
        {
            logf("  ResolvePerSideWeapons: exception resolving \"%s\": %s - falling back to shared rifle stats\n",
                unitClass.c_str(), e.what());
        }
        catch (...)
        {
            logf("  ResolvePerSideWeapons: unknown exception resolving \"%s\" - falling back to shared rifle stats\n",
                unitClass.c_str());
        }
        if (lvl != nullptr) { try { ReleaseLevel(lvl); } catch (...) {} }
    }
}

static size_t LoadExternalModel(const std::string& lvlPath, const char* modelName, std::vector<ModelData>& uniqueModels,
    const AnimationBank* animBank = nullptr, CRCChecksum animCRC = 0, uint16_t animFrame = 0)
{
    checkpoint(("checkpoint: about to load external model \"" + std::string(modelName) + "\" from " + lvlPath).c_str());

    if (!FileExists(lvlPath.c_str()))
    {
        checkpoint(("checkpoint: " + lvlPath + " does not exist - skipping").c_str());
        logf("external level \"%s\" not found - skipping (model \"%s\")\n", lvlPath.c_str(), modelName);
        return MODEL_LOAD_FAILED;
    }

    Level* extLvl = nullptr;
    try
    {
        extLvl = TimedLevelFromFile(lvlPath.c_str());
    }
    catch (const std::exception& e)
    {
        checkpoint(("checkpoint: " + lvlPath + " Level::FromFile THREW: " + std::string(e.what())).c_str());
        logf("external level \"%s\" threw an exception while loading (%s) - skipping (model \"%s\")\n",
            lvlPath.c_str(), e.what(), modelName);
        return MODEL_LOAD_FAILED;
    }
    if (extLvl == nullptr)
    {
        logf("external level \"%s\" Level::FromFile returned null - skipping (model \"%s\")\n", lvlPath.c_str(), modelName);
        return MODEL_LOAD_FAILED;
    }
    checkpoint(("checkpoint: " + lvlPath + " loaded successfully").c_str());

    const Model* m = extLvl->GetModel(String(modelName));
    if (m == nullptr)
    {
        logf("model \"%s\" not found in %s - skipping\n", modelName, lvlPath.c_str());
        ReleaseLevel(extLvl);
        return MODEL_LOAD_FAILED;
    }

    ModelData md;
    BuildModelData(*m, md, animBank, animCRC, animFrame);
    if (md.segments.empty())
    {
        logf("model \"%s\" in %s had no renderable segments - skipping\n", modelName, lvlPath.c_str());
        ReleaseLevel(extLvl);
        return MODEL_LOAD_FAILED;
    }

    size_t idx = uniqueModels.size();
    uniqueModels.push_back(md);
    logf("model \"%s\" loaded from %s (unique model index %u, %u segment(s))\n",
        modelName, lvlPath.c_str(), (unsigned)idx, (unsigned)md.segments.size());

    ReleaseLevel(extLvl);
    return idx;
}

static void LoadExternalModels(const std::string& lvlPath, const std::vector<const char*>& modelNames,
    std::vector<ModelData>& uniqueModels, std::vector<size_t>& outIndices)
{
    outIndices.assign(modelNames.size(), MODEL_LOAD_FAILED);

    checkpoint(("checkpoint: MILESTONE 24 - about to load external level " + lvlPath +
        " (" + std::to_string(modelNames.size()) + " model(s), sub-LVL-restricted)").c_str());

    if (!FileExists(lvlPath.c_str()))
    {
        checkpoint(("checkpoint: " + lvlPath + " does not exist - skipping").c_str());
        logf("external level \"%s\" not found - skipping all %u requested model(s)\n",
            lvlPath.c_str(), (unsigned)modelNames.size());
        return;
    }

    List<String> subLvls;
    for (const char* name : modelNames) subLvls.Add(String(name));

    Level* extLvl = nullptr;
    const uint64_t lvlT0 = sceKernelGetProcessTimeWide();
    try
    {
        extLvl = TimedLevelFromFile(lvlPath.c_str(), &subLvls);
    }
    catch (const std::exception& e)
    {
        checkpoint(("checkpoint: " + lvlPath + " Level::FromFile THREW: " + std::string(e.what())).c_str());
        logf("external level \"%s\" threw an exception while loading (%s) - skipping all %u requested model(s)\n",
            lvlPath.c_str(), e.what(), (unsigned)modelNames.size());
        return;
    }
    if (extLvl == nullptr)
    {
        checkpoint(("checkpoint: " + lvlPath + " Level::FromFile returned null").c_str());
        logf("external level \"%s\" Level::FromFile returned null - skipping all %u requested model(s)\n",
            lvlPath.c_str(), (unsigned)modelNames.size());
        return;
    }
    {
        char tmsg[192];
        snprintf(tmsg, sizeof(tmsg), "LVL TIME: %s took %.2fs for %u sub-LVL(s)",
            lvlPath.c_str(), (float)(sceKernelGetProcessTimeWide() - lvlT0) / 1000000.0f,
            (unsigned)subLvls.Size());
        checkpoint(tmsg);
    }
    checkpoint(("checkpoint: " + lvlPath + " loaded successfully").c_str());
    logMemory(("after loading " + lvlPath).c_str());

    for (size_t n = 0; n < modelNames.size(); ++n)
    {
        const Model* m = extLvl->GetModel(String(modelNames[n]));
        if (m == nullptr)
        {
            logf("model \"%s\" not found in %s - skipping\n", modelNames[n], lvlPath.c_str());
            continue;
        }
        ModelData md;
        BuildModelData(*m, md);
        if (md.segments.empty())
        {
            logf("model \"%s\" in %s had no renderable segments - skipping\n", modelNames[n], lvlPath.c_str());
            continue;
        }
        size_t idx = uniqueModels.size();
        uniqueModels.push_back(md);
        outIndices[n] = idx;
        logf("model \"%s\" loaded from %s (unique model index %u, %u segment(s))\n",
            modelNames[n], lvlPath.c_str(), (unsigned)idx, (unsigned)md.segments.size());
    }

    ReleaseLevel(extLvl);
}

struct VehicleSpring { float x = 0, y = 0, z = 0, radius = 0, length = 0; };
