static float HorizontalToVerticalFov4x3(float horizontalDeg)
{
    if (horizontalDeg <= 1.0f) return 52.06f;

    const float halfRad = horizontalDeg * 0.5f * 3.14159265f / 180.0f;
    return 2.0f * atanf(tanf(halfRad) * 0.7666f) * 180.0f / 3.14159265f;
}
