static bool GlobMatch(const char* p, const char* s)
{
    if (*p == 0) return *s == 0;
    if (*p == '*') return GlobMatch(p + 1, s) || (*s != 0 && GlobMatch(p, s + 1));
    return *s == *p && GlobMatch(p + 1, s + 1);
}
