static float CurrentThirdPersonFovDeg()
{
    if (g_playerVehicle >= 0 && (size_t)g_playerVehicle < g_vehicles.size())
    {
        auto dit = g_vehicleClassDefs.find(g_vehicles[(size_t)g_playerVehicle].cls);
        if (dit != g_vehicleClassDefs.end())
        {

            if (g_vehFovH > 1.0f) return HorizontalToVerticalFov4x3(g_vehFovH);
            if (dit->second.thirdPersonFov > 1.0f) return HorizontalToVerticalFov4x3(dit->second.thirdPersonFov);
        }
    }
    return HorizontalToVerticalFov4x3(g_soldierFovHDeg);
}
