static std::string LowerStr(const std::string& in)
{
    std::string out = in;
    for (char& c : out) c = (char)tolower((unsigned char)c);
    return out;
}

static void BuildSpawnPathsFromLevel(Level* lvl)
{
    g_spawnPaths.clear();
    if (lvl == nullptr) return;
    List<const Config*> cfgs = lvl->GetConfigs(EConfigType::Path);
    uint32_t totalNodes = 0;
    uint32_t dupPaths = 0;
    std::string dupNote;
    for (uint32_t c = 0; c < cfgs.Size(); ++c)
    {
        List<const Field*> fields = cfgs[c]->GetFields();
        for (uint32_t i = 0; i < fields.Size(); ++i)
        {

            static const LibSWBF2::FNVHash PATH_FIELD_HASH = LibSWBF2::FNV::Hash(String("path"));
            if (fields[i]->GetNameHash() != PATH_FIELD_HASH) continue;
            String pathName = fields[i]->GetString();
            if (pathName.Length() == 0) continue;

            std::vector<SpawnPathNode> nodes;
            List<const Field*> props = fields[i]->m_Scope.GetFields();
            for (uint32_t pi2 = 0; pi2 < props.Size(); ++pi2)
            {
                List<const Field*> maybeNodes = props[pi2]->m_Scope.GetFields();
                for (uint32_t nj = 0; nj < maybeNodes.Size(); ++nj)
                {
                    List<const Field*> nf = maybeNodes[nj]->m_Scope.GetFields();
                    if (nf.Size() == 0) continue;
                    SpawnPathNode node;
                    bool havePos = false, haveRot = false;
                    for (uint32_t k = 0; k < nf.Size(); ++k)
                    {
                        const uint8_t nv = nf[k]->GetNumValues();
                        if (nv == 3 && !havePos) { node.position = nf[k]->GetVector3(); havePos = true; }
                        else if (nv == 4 && !haveRot)
                        {
                            const float qw = nf[k]->GetFloat(0);
                            const float qy = nf[k]->GetFloat(2);
                            node.yaw = 2.0f * atan2f(qy, qw);
                            haveRot = true;
                        }
                    }
                    if (!havePos) continue;

                    node.position.m_Z = -node.position.m_Z;

                    node.yaw = -node.yaw;
                    nodes.push_back(node);
                }
            }
            if (nodes.empty()) continue;

            const std::string lowerName = LowerStr(pathName.Buffer());
            auto prev = g_spawnPaths.find(lowerName);
            if (prev == g_spawnPaths.end())
            {
                g_spawnPaths[lowerName] = nodes;
                totalNodes += (uint32_t)nodes.size();
            }
            else if (g_spawnPathLastDbg)
            {
                totalNodes += (uint32_t)nodes.size() - (uint32_t)prev->second.size();
                prev->second = nodes;
            }
            else
            {

                float maxOffSq = 0.0f;
                const size_t n = (prev->second.size() < nodes.size()) ? prev->second.size() : nodes.size();
                for (size_t k = 0; k < n; ++k)
                {
                    const float dx = prev->second[k].position.m_X - nodes[k].position.m_X;
                    const float dz = prev->second[k].position.m_Z - nodes[k].position.m_Z;
                    if (dx * dx + dz * dz > maxOffSq) maxOffSq = dx * dx + dz * dz;
                }
                ++dupPaths;
                dupNote += dupNote.empty() ? "" : "; ";
                dupNote += lowerName + " (" + std::to_string((unsigned)prev->second.size()) + " vs " +
                           std::to_string((unsigned)nodes.size()) + " nodes, up to " +
                           std::to_string((unsigned)sqrtf(maxOffSq)) + " m apart)";
            }
        }
    }
    logf("BuildSpawnPathsFromLevel: MILESTONE 106 - %u real spawn path(s), %u real node(s) total%s\n",
        (unsigned)g_spawnPaths.size(), totalNodes,
        g_spawnPathLastDbg ? " (LAST copy of a name wins - `spawnlast` A/B)" : " (FIRST copy of a name wins - T1r 0x00820c20)");
    if (dupPaths > 0)
        logf("BuildSpawnPathsFromLevel: SPAWNSAFE - %u duplicate path name(s) with a DIFFERENT path: %s\n",
            (unsigned)dupPaths, dupNote.c_str());
}

static void ReadBoundaryPathNodes(const Field* field, std::vector<Vector3>& out)
{
    out.clear();
    List<const Field*> props = field->m_Scope.GetFields();
    for (uint32_t pi2 = 0; pi2 < props.Size(); ++pi2)
    {
        List<const Field*> maybeNodes = props[pi2]->m_Scope.GetFields();
        for (uint32_t nj = 0; nj < maybeNodes.Size(); ++nj)
        {
            List<const Field*> nf = maybeNodes[nj]->m_Scope.GetFields();
            if (nf.Size() == 0) continue;
            bool havePos = false;
            Vector3 p;
            for (uint32_t k = 0; k < nf.Size(); ++k)
                if (nf[k]->GetNumValues() == 3 && !havePos) { p = nf[k]->GetVector3(); havePos = true; }
            if (!havePos) continue;
            p.m_Z = -p.m_Z;
            out.push_back(p);
        }
    }
}

static void BuildBattlefieldBoundaryFromLevel(Level* lvl)
{
    g_boundaryShapes.clear();
    g_boundaryShapesLast.clear();
    if (lvl == nullptr) return;
    static const LibSWBF2::FNVHash BOUNDARY_HASH = LibSWBF2::FNV::Hash(String("boundary"));
    static const LibSWBF2::FNVHash PATH_HASH = LibSWBF2::FNV::Hash(String("path"));

    std::vector<std::pair<std::string, std::vector<Vector3>>> firstPaths, lastPaths;
    std::map<std::string, size_t> firstIndex, lastIndex;
    List<const Config*> paths = lvl->GetConfigs(EConfigType::Path);
    for (uint32_t c = 0; c < paths.Size(); ++c)
    {
        List<const Field*> fields = paths[c]->GetFields();
        for (uint32_t i = 0; i < fields.Size(); ++i)
        {
            if (fields[i]->GetNameHash() != PATH_HASH) continue;
            String pathName = fields[i]->GetString();
            if (pathName.Length() == 0) continue;
            const std::string name = LowerStr(pathName.Buffer());
            std::vector<Vector3> nodes;
            ReadBoundaryPathNodes(fields[i], nodes);
            if (nodes.empty()) continue;
            auto it = lastIndex.find(name);
            if (it == lastIndex.end()) { firstIndex[name] = firstPaths.size(); firstPaths.push_back({name, nodes}); }
            else { lastPaths[(it->second)] = {name, nodes}; continue; }
            lastIndex[name] = lastPaths.size();
            lastPaths.push_back({name, nodes});
        }
    }
    List<const Config*> cfgs = lvl->GetConfigs(EConfigType::Boundary);
    uint32_t wanted = 0, dangling = 0, totalNodes = 0;
    std::string matchedNames, dupNote;
    for (uint32_t c = 0; c < cfgs.Size(); ++c)
    {
        List<const Field*> fields = cfgs[c]->GetFields();
        for (uint32_t i = 0; i < fields.Size(); ++i)
        {
            if (fields[i]->GetNameHash() != BOUNDARY_HASH) continue;
            List<const Field*> named = fields[i]->m_Scope.GetFields();
            for (uint32_t j = 0; j < named.Size(); ++j)
            {
                if (named[j]->GetNameHash() != PATH_HASH) continue;
                if (named[j]->GetNumValues() == 0) continue;
                ++wanted;
                const uint32_t nameHash = named[j]->GetUInt32(0);
                bool found = false;
                for (size_t p = 0; p < firstPaths.size(); ++p)
                {
                    if (LibSWBF2::FNV::Hash(String(firstPaths[p].first.c_str())) != nameHash) continue;
                    const std::vector<Vector3>& shape = firstPaths[p].second;
                    if (shape.size() >= 3) { g_boundaryShapes.push_back(shape); totalNodes += (uint32_t)shape.size(); matchedNames += (matchedNames.empty() ? "" : ", ") + firstPaths[p].first; }

                    for (size_t q = 0; q < lastPaths.size(); ++q)
                        if (lastPaths[q].first == firstPaths[p].first) { g_boundaryShapesLast.push_back(lastPaths[q].second); break; }

                    for (size_t q = 0; q < lastPaths.size(); ++q)
                    {
                        if (lastPaths[q].first != firstPaths[p].first) continue;
                        if (lastPaths[q].second.size() != shape.size()) { dupNote += dupNote.empty() ? "" : "; "; dupNote += firstPaths[p].first + " duplicate path name (different node count) - PS2 takes the first"; break; }
                        float md = 0.0f;
                        for (size_t n2 = 0; n2 < shape.size(); ++n2)
                        {
                            const float dx = lastPaths[q].second[n2].m_X - shape[n2].m_X;
                            const float dz = lastPaths[q].second[n2].m_Z - shape[n2].m_Z;
                            if (dx * dx + dz * dz > md) md = dx * dx + dz * dz;
                        }
                        if (md > 0.0001f)
                        {
                            dupNote += dupNote.empty() ? "" : "; ";
                            dupNote += firstPaths[p].first + " duplicate path name - PS2 takes the first, the name-keyed map the last";
                        }
                        break;
                    }
                    found = true;
                    break;
                }
                if (!found) ++dangling;
            }
        }
    }
    logf("BOUNDS: %u boundary shape(s), %u node(s) from the map's bnd_ chunk (%u named path(s), %u unresolved) - %s%s%s\n",
        (unsigned)g_boundaryShapes.size(), totalNodes, wanted, dangling,
        g_boundaryShapes.empty() ? "no boundary on this map" : "boundary active",
        matchedNames.empty() ? "" : "; path(s): ", matchedNames.c_str());
    if (!dupNote.empty()) logf("BOUNDS: %s (T1p C4 / T1r 0x00820c20 - `bndlast` for the old behaviour)\n", dupNote.c_str());

    for (size_t s = 0; s < g_boundaryShapes.size(); ++s)
    {
        const std::vector<Vector3>& shape = g_boundaryShapes[s];
        float ax = 0.0f, az = 0.0f, area = 0.0f;
        for (size_t i = 0; i < shape.size(); ++i)
        {
            const Vector3& a = shape[i];
            const Vector3& b = shape[(i + 1) % shape.size()];
            ax += a.m_X; az += a.m_Z;
            area += a.m_X * b.m_Z - b.m_X * a.m_Z;
        }
        ax /= (float)shape.size(); az /= (float)shape.size();
        logf("BOUNDS: shape %u - %u node(s), shoelace area %.0f m2, centre (%.1f,%.1f) %s\n",
            (unsigned)s, (unsigned)shape.size(), 0.5f * area, ax, az,
            IsOutsideBattlefield(ax, az) ? "OUTSIDE (WINDING WRONG - check!)" : "inside");
    }
}

static bool RealSpawnPathNode(const std::string& spawnPath, uint32_t slot, Vector3& outPos, float* outYaw)
{
    if (spawnPath.empty()) return false;
    auto it = g_spawnPaths.find(LowerStr(spawnPath));
    if (it == g_spawnPaths.end() || it->second.empty()) return false;
    const SpawnPathNode& node = it->second[slot % it->second.size()];
    outPos = node.position;
    if (outYaw != nullptr) *outYaw = node.yaw;
    return true;
}

