static std::string LocKeyForClass(const std::string& cls, bool weapon)
{
    const size_t u = cls.find('_');
    if (u == std::string::npos) return cls;
    const std::string side = cls.substr(0, u), rest = cls.substr(u + 1);
    if (weapon && rest.compare(0, 5, "weap_") == 0) return "weapons." + side + ".weap." + rest.substr(5);
    return (weapon ? "weapons." : "entity.") + side + "." + rest;
}
static void LoadLocalizedStrings(const std::vector<std::string>& keys)
{
    Level* lvl = nullptr;
    try { lvl = Level::FromFile(String(CookedLevelPath(CORE_LVL_PATH.c_str()).c_str())); } catch (...) { lvl = nullptr; }
    if (lvl == nullptr) { logf("MILESTONE 452: core.lvl not loaded - UI falls back to built-in text\n"); return; }
    const LibSWBF2::Wrappers::Localization* loc = lvl->GetLocalization(String("english"));
    unsigned found = 0;
    for (const std::string& k : keys)
    {
        uint16_t* ch = nullptr; uint32_t n = 0;
        if (loc == nullptr || !loc->GetLocalizedWideString(String(k.c_str()), ch, n) || ch == nullptr) continue;
        std::string out;
        for (uint32_t i = 0; i < n; ++i) out += (ch[i] > 0 && ch[i] < 128) ? (char)ch[i] : (ch[i] == 0 ? '\0' : '?');
        while (!out.empty() && (out.back() == '\0' || out.back() == ' ' || out.back() == '\r' || out.back() == '\n')) out.pop_back();
        g_loc[k] = out; ++found;
    }
    Level::Destroy(lvl);
    logf("MILESTONE 452: %u/%u localized strings from core.lvl (e.g. chooseteam=\"%s\")\n", found, (unsigned)keys.size(),
         LocString("ifs.sideselect.chooseteam", "?").c_str());
}

