static void ReadCpHologramData(Level* lvl, const char* cpClass)
{
    if (g_cpHolo.read || lvl == nullptr) return;
    g_cpHolo.read = true;
    std::string holo;
    GetFloatPropertyInherited(lvl, cpClass, "HoloTurnOnTime", g_cpHolo.turnOnTime);
    if (GetPropertyValueInherited(lvl, cpClass, "HoloOdf", holo))
    {
        const char* h = holo.c_str();
        GetFloatPropertyInherited(lvl, h, "HoloHeight", g_cpHolo.height);
        GetFloatPropertyInherited(lvl, h, "HoloSize", g_cpHolo.size);
        GetFloatPropertyInherited(lvl, h, "HoloVisibleDistance", g_cpHolo.visibleDist);
        GetFloatPropertyInherited(lvl, h, "HoloBeamInitialWidth", g_cpHolo.beamWidth0);
        GetFloatPropertyInherited(lvl, h, "HoloBeamIntensity", g_cpHolo.beamI);
        GetFloatPropertyInherited(lvl, h, "HoloLightIntensity", g_cpHolo.lightI);
        GetFloatPropertyInherited(lvl, h, "HoloImageIntensity", g_cpHolo.imageI);
        GetFloatPropertyInherited(lvl, h, "HoloFlareIntensity", g_cpHolo.flareI);
        GetFloatPropertyInherited(lvl, h, "HoloLightRadius", g_cpHolo.lightRadius);
        GetFloatPropertyInherited(lvl, h, "HoloRotateRate", g_cpHolo.rotateRate);
        GetFloatPropertyInherited(lvl, h, "HoloFlickerRate", g_cpHolo.flickerRate);
        GetFloatPropertyInherited(lvl, h, "HoloFlickerAlphaMin", g_cpHolo.flickerMin);
        GetFloatPropertyInherited(lvl, h, "HoloFlickerAlphaMax", g_cpHolo.flickerMax);
        GetFloatPropertyInherited(lvl, h, "HoloFadeInTime", g_cpHolo.fadeIn);
    }
    List<String> imgs;
    if (GetPropertyListInherited(lvl, cpClass, "HoloImageGeometry", imgs))
        for (size_t i = 0; i < imgs.Size(); ++i)
        {
            char geo[96] = {}, fac[64] = {};
            if (sscanf(imgs[i].Buffer(), "%95s %63s", geo, fac) != 2) continue;
            std::string f = fac;
            for (char& ch : f) ch = (char)tolower((unsigned char)ch);
            g_cpHolo.icons.push_back({ f, geo });
        }
    checkpointf("M478 CP hologram: HoloOdf \"%s\" height %.2f size %.2f visible %.0f beam %.2f (w0 %.2f) light %.2f r %.1f image %.2f flare %.2f rotate %.2f flicker %.2f %.2f..%.2f fadeIn %.1f turnOn %.1f, %u logo(s)",
        holo.c_str(), g_cpHolo.height, g_cpHolo.size, g_cpHolo.visibleDist, g_cpHolo.beamI, g_cpHolo.beamWidth0, g_cpHolo.lightI,
        g_cpHolo.lightRadius, g_cpHolo.imageI, g_cpHolo.flareI, g_cpHolo.rotateRate, g_cpHolo.flickerRate, g_cpHolo.flickerMin,
        g_cpHolo.flickerMax, g_cpHolo.fadeIn, g_cpHolo.turnOnTime, (unsigned)g_cpHolo.icons.size());
}

static const char* CpHoloFaction(int team)
{
    if (team <= 0) return nullptr;
    std::string n = ((size_t)team < g_teams.size()) ? g_teams[(size_t)team].name : std::string();
    for (char& ch : n) ch = (char)tolower((unsigned char)ch);
    if (n.compare(0, 3, "rep") == 0) return "republic";
    if (n.compare(0, 3, "cis") == 0) return "cis";
    if (n.compare(0, 3, "imp") == 0 || n.compare(0, 3, "emp") == 0) return "empire";
    if (n.compare(0, 3, "all") == 0) return "alliance";
    if (n.empty()) return team == 1 ? "republic" : team == 2 ? "cis" : nullptr;
    return nullptr;
}

static void CpHoloColour(int team, float c[3])
{
    if (team <= 0) { c[0] = c[1] = c[2] = 1.0f; return; }
    if (team != g_playerTeam && IsHostile(g_playerTeam, team)) { c[0] = 150.0f / 255.0f; c[1] = 30.0f / 255.0f; c[2] = 30.0f / 255.0f; }
    else { c[0] = 1.0f / 255.0f; c[1] = 86.0f / 255.0f; c[2] = 213.0f / 255.0f; }
}

static float CpHoloOnFraction(size_t i)
{
    if (i >= g_cpHoloState.size()) return 1.0f;
    const float t = g_cpHoloState[i].sinceChange - g_cpHolo.turnOnTime;
    return t <= 0.0f ? 0.0f : fminf(1.0f, t / fmaxf(0.01f, g_cpHolo.fadeIn));
}

struct RegionList
{
    std::vector<const Region*> v;
    size_t Size() const { return v.size(); }
    const Region& operator[](size_t i) const { return *v[i]; }
};
static void GatherRealSpawnRequests(Level* lvl,
    std::vector<VehicleReq>& outVehicleReqs,
    std::vector<CommandPostInfo>& outCommandPosts,
    std::vector<VehicleReq>& outTurretReqs)
{
    if (lvl == nullptr) return;
    struct InstList
    {
        std::vector<const Instance*> v;
        size_t Size() const { return v.size(); }
        const Instance& operator[](size_t i) const { return *v[i]; }
    } allInsts;
    RegionList allRegions;
    {
        const List<World>& ws = lvl->GetWorlds();
        for (size_t w = 0; w < ws.Size(); ++w)
        {
            for (size_t k = 0; k < ws[w].GetInstances().Size(); ++k) allInsts.v.push_back(&ws[w].GetInstances()[k]);
            for (size_t k = 0; k < ws[w].GetRegions().Size(); ++k) allRegions.v.push_back(&ws[w].GetRegions()[k]);
        }
    }
    const RegionList* regions = allRegions.Size() > 0 ? &allRegions : nullptr;
    if (regions == nullptr)
    {
        logf("GatherRealSpawnRequests: no regions in any loaded world - command posts will have no real capture-region data\n");
    }

    g_deathRegions.clear();
    g_allRegionsByName.clear();
    if (regions != nullptr)
        for (size_t r = 0; r < regions->Size(); ++r)
        {
            const Region& region = (*regions)[r];
            DeathRegionInfo a; a.name = region.GetName().Buffer(); a.pos = region.GetPosition(); a.rot = region.GetRotation();
            a.size = region.GetSize(); a.type = region.GetType().Buffer();
            g_allRegionsByName.push_back(a);
        }
    if (regions != nullptr)
    {
        for (const std::string& drName : g_deathRegionNames)
        {
            bool found = false, nameTaken = false;
            for (size_t r = 0; r < regions->Size(); ++r)
            {
                const Region& region = (*regions)[r];

                bool match = !nameTaken && strcasecmp(region.GetName().Buffer(), drName.c_str()) == 0;
                if (match) nameTaken = true;
                if (!match)
                {
                    List<LibSWBF2::FNVHash> ph; List<String> pv;
                    region.GetProperties(ph, pv);
                    for (size_t k = 0; k < ph.Size() && k < pv.Size(); ++k)
                        if ((uint32_t)ph[k] == 0x8d39bde6u   && strcasecmp(pv[k].Buffer(), drName.c_str()) == 0) { match = true; break; }
                }
                if (!match) continue;
                bool dup = false;
                for (const DeathRegionInfo& e : g_deathRegions)
                    if (e.pos.m_X == region.GetPosition().m_X && e.pos.m_Y == region.GetPosition().m_Y && e.pos.m_Z == region.GetPosition().m_Z) dup = true;
                if (dup) { found = true; continue; }
                DeathRegionInfo dr;
                dr.name = region.GetName().Buffer();
                dr.pos = region.GetPosition();
                dr.rot = region.GetRotation();
                dr.size = region.GetSize();
                dr.type = region.GetType().Buffer();
                g_deathRegions.push_back(dr);
                logf("  death region \"%s\": %s at (%.1f, %.1f, %.1f) size (%.1f, %.1f, %.1f)\n", drName.c_str(), dr.type.c_str(),
                     dr.pos.m_X, dr.pos.m_Y, dr.pos.m_Z, dr.size.m_X, dr.size.m_Y, dr.size.m_Z);
                found = true;
            }
            if (!found)
                logf("GatherRealSpawnRequests: real death region \"%s\" named but not found in base world's region list\n", drName.c_str());
        }
    }
    g_soundStreamRegions.clear();
    if (regions != nullptr)
        for (size_t r = 0; r < regions->Size(); ++r)
        {
            const Region& region = (*regions)[r];
            char seg[96] = {0}; char word[32] = {0};
            if (sscanf(region.GetName().Buffer(), "%31s %95s", word, seg) != 2 || strcasecmp(word, "soundstream") != 0) continue;
            SoundStreamRegion sr;
            sr.pos = region.GetPosition(); sr.rot = region.GetRotation(); sr.size = region.GetSize();
            sr.type = region.GetType().Buffer(); sr.segment = seg;
            const Vector3& z = sr.size;
            sr.volume = sr.type == "sphere" ? z.m_X * z.m_X * z.m_X : z.m_X * z.m_Y * z.m_Z;
            g_soundStreamRegions.push_back(sr);
            logf("  M485 soundstream region \"%s\": %s at (%.1f, %.1f, %.1f) size (%.1f, %.1f, %.1f)\n", seg, sr.type.c_str(),
                 sr.pos.m_X, sr.pos.m_Y, sr.pos.m_Z, z.m_X, z.m_Y, z.m_Z);
        }

    if (regions != nullptr)
        for (size_t r = 0; r < regions->Size() && !g_mapBoundsValid; ++r)
        {
            const Region& region = (*regions)[r];
            if (std::string(region.GetType().Buffer()) != "box" || std::string(region.GetName().Buffer()) != "mapbounds") continue;
            const Vector4 q = region.GetRotation();
            const float r00 = fabsf(1.0f - 2.0f * (q.m_Y * q.m_Y + q.m_Z * q.m_Z)), r22 = fabsf(1.0f - 2.0f * (q.m_X * q.m_X + q.m_Y * q.m_Y));
            const float hx = region.GetSize().m_X * r00, hz = region.GetSize().m_Z * r22, h = fmaxf(hx, hz);
            g_mapMinX = region.GetPosition().m_X - h; g_mapMinZ = region.GetPosition().m_Z - h;
            g_mapSizeX = g_mapSizeZ = 2.0f * h;
            g_mapBoundsValid = (h > 0.5f);
        }
    if (lvl != nullptr)
    {

        std::vector<std::string> names = { g_map.code };
        const List<World>& ws = lvl->GetWorlds();
        for (size_t w = 0; w < ws.Size(); ++w) names.push_back(ws[w].GetName().Buffer());
        for (const std::string& nm : names)
        {
            const Texture* mt = lvl->GetTexture(String((nm + "_map").c_str()));
            const uint8_t* mpx = nullptr; uint16_t mw = 0, mh = 0;
            if (mt != nullptr && mt->GetImageData(ETextureFormat::R8_G8_B8_A8, 0, mw, mh, mpx) && mpx != nullptr)
            {
                g_mapPixels.assign(mpx, mpx + (size_t)mw * mh * 4);
                g_mapPixW = mw; g_mapPixH = mh;
                logf("M530 map image \"%s_map\"\n", nm.c_str());
                break;
            }
        }
    }
    logf("MILESTONE 452: map bounds %s min (%.1f,%.1f) size %.1f x %.1f, map image %ux%u\n", g_mapBoundsValid ? "real" : "MISSING",
         g_mapMinX, g_mapMinZ, g_mapSizeX, g_mapSizeZ, (unsigned)g_mapPixW, (unsigned)g_mapPixH);
    logf("GatherRealSpawnRequests: %u/%u real death region(s) resolved\n",
        (unsigned)g_deathRegions.size(), (unsigned)g_deathRegionNames.size());

    g_damageRegions.clear();
    if (regions != nullptr)
        for (size_t r = 0; r < regions->Size(); ++r)
        {
            const Region& region = (*regions)[r];
            DamageRegionInfo d;
            if (!ParseDamageRegionName(region.GetName().Buffer(), d)) continue;
            d.pos = region.GetPosition(); d.rot = region.GetRotation();
            d.size = region.GetSize(); d.type = region.GetType().Buffer();
            List<LibSWBF2::FNVHash> ph; List<String> pv;
            region.GetProperties(ph, pv);
            for (size_t k = 0; k < ph.Size() && k < pv.Size(); ++k)
                if ((uint32_t)ph[k] == 0x8d39bde6u  ) d.name = pv[k].Buffer();
            g_damageRegions.push_back(d);
            logf("  damage region \"%s\": %s at (%.1f, %.1f, %.1f) size (%.1f, %.1f, %.1f) rate %.1f scales %.1f/%.1f/%.1f/%.1f\n",
                 d.name.c_str(), d.type.c_str(), d.pos.m_X, d.pos.m_Y, d.pos.m_Z,
                 d.size.m_X, d.size.m_Y, d.size.m_Z, d.rate, d.scale[0], d.scale[1], d.scale[2], d.scale[3]);
        }
    logf("LAVA: %u real damage region(s) loaded\n", (unsigned)g_damageRegions.size());

    const InstList& insts = allInsts;

    for (size_t i = 0; i < insts.Size(); ++i)
    {
        const Instance& inst = insts[i];
        if (std::string(inst.GetEntityClassName().Buffer()) != "com_item_vehicle_spawn") continue;

        String vehicleClassProp;
        bool found = false;
        for (const char* propName : VEHICLE_CLASS_PROPS)
        {
            if (inst.GetProperty(String(propName), vehicleClassProp) && vehicleClassProp.Length() > 0)
            {
                found = true;
                break;
            }
        }
        if (!found)
        {
            logf("  vehicle spawn \"%s\": no real vehicle class property found - skipping\n", inst.GetName().Buffer());
            continue;
        }

        std::string cls = vehicleClassProp.Buffer();
        VehicleReq vr;
        vr.position = inst.GetPosition(); vr.rotation = inst.GetRotation(); vr.name = inst.GetName().Buffer(); vr.vehicleClass = cls;
        {

            String v;
            if (inst.GetProperty(String("ControlZone"), v)) vr.controlZone = v.Buffer();
            if (inst.GetProperty(String("Team"), v) && v.Length() > 0) vr.fixedTeam = atoi(v.Buffer());
            if (inst.GetProperty(String("SpawnTime"), v)) vr.spawnTime = (float)atof(v.Buffer());
            if (inst.GetProperty(String("ExpireTimeEnemy"), v)) vr.expireTimeEnemy = (float)atof(v.Buffer());
            if (inst.GetProperty(String("ExpireTimeField"), v)) vr.expireTimeField = (float)atof(v.Buffer());
            if (inst.GetProperty(String("DecayTime"), v)) vr.decayTime = (float)atof(v.Buffer());
            for (const char* fac : { "rep", "cis", "imp", "all" })
                for (const char* col : { "atk", "def" })
                {
                    const std::string key = std::string(fac) + col;
                    if (inst.GetProperty(String(("class" + key).c_str()), v) && v.Length() > 0) vr.classByKey[key] = v.Buffer();
                }
            std::string keys;
            for (const auto& kv : vr.classByKey) keys += (keys.empty() ? "" : " ") + kv.first + "=" + kv.second;
            logf("  M432 vehicle spawn \"%s\": cp \"%s\" team %d spawn %.0fs expire enemy %.0fs field %.0fs decay %.0fs, %u class field(s) [%s]\n",
                vr.name.c_str(), vr.controlZone.c_str(), vr.fixedTeam, vr.spawnTime, vr.expireTimeEnemy, vr.expireTimeField,
                vr.decayTime, (unsigned)vr.classByKey.size(), keys.c_str());
        }
        outVehicleReqs.push_back(vr);

        {
            bool knownPrefix = false;
            for (const char* pref : { "rep_", "cis_", "imp_", "all_", "tur_", "gam_", "geo_", "wok_" })
                if (cls.rfind(pref, 0) == 0) { knownPrefix = true; break; }
            if (!knownPrefix)
                logf("  vehicle spawn \"%s\": class \"%s\" has an unknown side prefix (not rep/cis/imp/all/tur) - trying it anyway\n",
                    inst.GetName().Buffer(), cls.c_str());
        }
    }

    std::set<std::string> turClasses;
    for (const DataFileRequest& req : g_dataFileManifest)
        if (NormalizeLvlKey(req.lvlFile.c_str()) == "side/tur.lvl")
            for (const std::string& sub : req.subResources) turClasses.insert(LowerStr(sub));
    for (size_t i = 0; i < insts.Size(); ++i)
    {
        const Instance& inst = insts[i];
        const std::string cls = inst.GetEntityClassName().Buffer();
        if (!turClasses.count(LowerStr(cls))) continue;
        outTurretReqs.push_back({ inst.GetPosition(), inst.GetRotation(), inst.GetName().Buffer(), cls });
    }

    ReadCpHologramData(lvl, "com_bldg_controlzone");
    std::map<std::string, bool> isPostClass;
    for (size_t i = 0; i < insts.Size(); ++i)
    {
        const Instance& inst = insts[i];
        const std::string postCls = inst.GetEntityClassName().Buffer();
        auto pcIt = isPostClass.find(postCls);
        if (pcIt == isPostClass.end())
            pcIt = isPostClass.emplace(postCls, postCls == "com_bldg_controlzone" || ClassLabelOf(lvl, postCls.c_str()) == "commandpost").first;
        if (!pcIt->second) continue;
        if (IsKilledObjectName(inst.GetName().Buffer())) { logf("  M525 KillObject: command post \"%s\" removed\n", inst.GetName().Buffer()); continue; }

        CommandPostInfo cp;
        cp.position = inst.GetPosition();
        cp.rotation = inst.GetRotation();

        cp.name = inst.GetName().Buffer();
        for (char& c : cp.name) c = (char)tolower((unsigned char)c);
        cp.className = postCls;
        if (postCls != "com_bldg_controlzone")
        {
            GetFloatPropertyInherited(lvl, postCls.c_str(), "CaptureTime", cp.captureTime);
            GetFloatPropertyInherited(lvl, postCls.c_str(), "NeutralizeTime", cp.neutralizeTime);
            std::string mt, ho;
            cp.mapIcon = GetPropertyValueInherited(lvl, postCls.c_str(), "MapTexture", mt) && !mt.empty();
            cp.holo = GetPropertyValueInherited(lvl, postCls.c_str(), "HoloOdf", ho) && !ho.empty();
            logf("  command post \"%s\": class %s capture %.1f neutralize %.1f map icon %d hologram %d\n", cp.name.c_str(),
                 postCls.c_str(), cp.captureTime, cp.neutralizeTime, cp.mapIcon ? 1 : 0, cp.holo ? 1 : 0);
        }

        String teamStr;
        if (inst.GetProperty(String("Team"), teamStr) && teamStr.Length() > 0)
        {
            cp.team = atoi(teamStr.Buffer());
        }
        else
        {
            logf("  command post \"%s\": no real \"Team\" property found - treating as unowned\n", cp.name.c_str());
        }
        {
            const auto st = g_scriptObjectTeam.find(cp.name);
            if (st != g_scriptObjectTeam.end()) { logf("  M530 command post \"%s\": team %d (SetObjectTeam; map %d)\n", cp.name.c_str(), st->second, cp.team); cp.team = st->second; }
        }

        for (const char* fac : { "Republic", "CIS", "Empire", "Alliance", "Locals" })
        {
            String v;
            if (inst.GetProperty(String((std::string("Value_ATK_") + fac).c_str()), v) && v.Length() > 0) cp.valueAtk[fac] = (float)atof(v.Buffer());
            if (inst.GetProperty(String((std::string("Value_DEF_") + fac).c_str()), v) && v.Length() > 0) cp.valueDef[fac] = (float)atof(v.Buffer());
            float cv;
            if (ConsoleWorldProp(cp.name, (std::string("Value_ATK_") + fac).c_str(), cv)) cp.valueAtk[fac] = cv;
            if (ConsoleWorldProp(cp.name, (std::string("Value_DEF_") + fac).c_str(), cv)) cp.valueDef[fac] = cv;
        }

        String spawnPathName;
        if (inst.GetProperty(String("SpawnPath"), spawnPathName) && spawnPathName.Length() > 0)
            cp.spawnPath = spawnPathName.Buffer();
        String allyPathName;
        if (inst.GetProperty(String("AllyPath"), allyPathName) && allyPathName.Length() > 0)
            cp.allyPath = allyPathName.Buffer();
        { String ac; if (inst.GetProperty(String("AllyCount"), ac) && ac.Length() > 0) cp.allyCount = atoi(ac.Buffer()); }
        { float cv; if (ConsoleWorldProp(cp.name, "AllyCount", cv)) { if ((int)cv != cp.allyCount) logf("CONSOLE DATA: %s AllyCount %d (PS2 map) instead of %d\n", cp.name.c_str(), (int)cv, cp.allyCount); cp.allyCount = (int)cv; } }
        {
            String hi;
            if (inst.GetProperty(String("HUDIndex"), hi) && hi.Length() > 0) cp.hudIndex = atoi(hi.Buffer());
        }
        logf("  command post \"%s\": real SpawnPath=\"%s\" AllyPath=\"%s\"\n",
            cp.name.c_str(), cp.spawnPath.c_str(), cp.allyPath.c_str());

        String captureRegionName;
        if (regions != nullptr && inst.GetProperty(String("CaptureRegion"), captureRegionName) && captureRegionName.Length() > 0)
        {
            for (size_t r = 0; r < regions->Size(); ++r)
            {
                const Region& region = (*regions)[r];

                if (strcasecmp(region.GetName().Buffer(), captureRegionName.Buffer()) != 0) continue;
                cp.hasCaptureRegion = true;
                cp.captureRegionPos = region.GetPosition();
                cp.captureRegionRot = region.GetRotation();
                cp.captureRegionSize = region.GetSize();
                cp.captureRegionType = region.GetType().Buffer();
                break;
            }
            if (!cp.hasCaptureRegion)
            {
                logf("  command post \"%s\": CaptureRegion \"%s\" named but not found in real region list\n",
                    cp.name.c_str(), captureRegionName.Buffer());
            }
        }
        else
        {
            logf("  command post \"%s\": no real \"CaptureRegion\" property found - no real capture-presence check possible\n", cp.name.c_str());
        }

        outCommandPosts.push_back(cp);
    }
    if (!g_mapBoundsValid && !outCommandPosts.empty())
    {
        float x0 = 1e9f, x1 = -1e9f, z0 = 1e9f, z1 = -1e9f;
        for (const CommandPostInfo& c : outCommandPosts) { x0 = fminf(x0, c.position.m_X); x1 = fmaxf(x1, c.position.m_X); z0 = fminf(z0, c.position.m_Z); z1 = fmaxf(z1, c.position.m_Z); }
        const float h = fmaxf((x1 - x0) * 0.5f, (z1 - z0) * 0.5f) + 100.0f;
        g_mapMinX = (x0 + x1) * 0.5f - h; g_mapMinZ = (z0 + z1) * 0.5f - h; g_mapSizeX = g_mapSizeZ = 2.0f * h; g_mapBoundsValid = true;
        logf("M530 map bounds from the posts: min (%.1f,%.1f) size %.1f\n", g_mapMinX, g_mapMinZ, g_mapSizeX);
    }
}

static std::string AnimCharacterTypeForClass(const std::string& unitClass);

static void GatherPowerupStations(Level* lvl)
{
    g_stations.clear();

    std::vector<const Instance*> insts;
    {
        const List<World>& ws = lvl->GetWorlds();
        for (size_t w = 0; w < ws.Size(); ++w)
            for (size_t k = 0; k < ws[w].GetInstances().Size(); ++k)
            {
                insts.push_back(&ws[w].GetInstances()[k]);
            }
    }
    for (size_t i = 0; i < insts.size(); ++i)
    {
        const Instance& inst = *insts[i];
        PowerupStationState s;
        s.cls = inst.GetEntityClassName().Buffer();
        s.name = inst.GetName().Buffer();
        std::string label = s.cls;
        {
            Level* al = lvl;
            for (int hop = 0; hop < 8; ++hop)
            {
                const EntityClass* e = GetEntityClassAnyLevel(al, label.c_str(), al);
                if (e == nullptr) break;
                const std::string b = e->GetBaseName().Buffer();
                if (b.empty()) break;
                label = b;
            }
        }
        if (strcasecmp(label.c_str(), "powerupstation") != 0) continue;
        s.position = inst.GetPosition();
        s.rotation = inst.GetRotation();
        GetFloatPropertyInherited(lvl, s.cls.c_str(), "Radius", s.radius);
        {
            String v;
            if (inst.GetProperty(String("Radius"), v) && v.Length() > 0) s.radius = (float)atof(v.Buffer());
        }
        GetFloatPropertyInherited(lvl, s.cls.c_str(), "MaxHealth", s.maxHealth);
        GetFloatPropertyInherited(lvl, s.cls.c_str(), "PowerupDelay", s.powerupDelay);
        GetFloatPropertyInherited(lvl, s.cls.c_str(), "SoldierHealth", s.soldierHealth);
        GetFloatPropertyInherited(lvl, s.cls.c_str(), "SoldierAmmo", s.soldierAmmo);
        s.hitPoints = s.maxHealth;
        GetPropertyValueInherited(lvl, s.cls.c_str(), "GeometryName", s.liveGeometry);
        GetPropertyValueInherited(lvl, s.cls.c_str(), "DestroyedGeometryName", s.deadGeometry);
        GetPropertyValueInherited(lvl, s.cls.c_str(), "UnbuiltGeometryName", s.unbuiltGeometry);

        GetFloatPropertyInherited(lvl, s.cls.c_str(), "IdleRotateSpeed", s.idleRotateSpeed);
        GetFloatPropertyInherited(lvl, s.cls.c_str(), "IdleWaitTime", s.idleWaitTime);
        GetFloatPropertyInherited(lvl, s.cls.c_str(), "IdleWobbleFactor", s.idleWobbleFactor);
        GetPropertyValueInherited(lvl, s.cls.c_str(), "IdleWobbleNode", s.wobbleNode);
        GetPropertyValueInherited(lvl, s.cls.c_str(), "IdleWobbleLeftFoot", s.wobbleFootL);
        GetPropertyValueInherited(lvl, s.cls.c_str(), "IdleWobbleRightFoot", s.wobbleFootR);
        GetPropertyValueInherited(lvl, s.cls.c_str(), "ActiveSpinNode", s.spinNode);
        if (GetPropertyValueInherited(lvl, s.cls.c_str(), "AmbientSound", s.ambientSound))
            s.ambientSound = s.ambientSound.substr(0, s.ambientSound.find(' '));
        {

            const EntityClass* e = GetEntityClassAnyLevel(lvl, s.cls.c_str(), lvl);
            List<String> vals;
            if (e != nullptr && e->GetProperty(String("ActiveRotateNode"), vals))
                for (size_t vi = 0; vi < vals.Size(); ++vi) s.activeNodes.push_back(vals[vi].Buffer());
        }
        logf("  M470 station \"%s\" motion: IdleRotateSpeed %.2f IdleWaitTime %.2f wobble \"%s\" x%.2f feet \"%s\"/\"%s\" spin \"%s\" active %u node(s) ambient \"%s\"\n",
             s.name.c_str(), s.idleRotateSpeed, s.idleWaitTime, s.wobbleNode.c_str(), s.idleWobbleFactor, s.wobbleFootL.c_str(), s.wobbleFootR.c_str(),
             s.spinNode.c_str(), (unsigned)s.activeNodes.size(), s.ambientSound.c_str());
        std::string expName;
        if (GetPropertyValueInherited(lvl, s.cls.c_str(), "ExplosionName", expName)) LoadRealExplosion(lvl, expName, s.explosion);
        logf("  M469 station \"%s\" %s at (%.1f,%.1f,%.1f): MaxHealth %.0f Radius %.1f PowerupDelay %.2f SoldierHealth %.1f SoldierAmmo %.1f explosion %s\n",
             s.name.c_str(), s.cls.c_str(), s.position.m_X, s.position.m_Y, s.position.m_Z, s.maxHealth, s.radius, s.powerupDelay,
             s.soldierHealth, s.soldierAmmo, s.explosion.valid ? s.explosion.name.c_str() : "(none)");
        g_stations.push_back(s);
    }
    checkpointf("M469: %u health/ammo droid(s) from every loaded world (M479)", (unsigned)g_stations.size());
}

static unsigned BindRigidSegmentsToBones(ModelData& clone)
{
                        clone.bindBones = clone.rigidBones;
                        const std::vector<BoneWorldTransform> bw = ComputeBoneWorldTransforms(clone.bindBones);
                        unsigned rigid = 0;
                        for (SegmentData& sd : clone.segments)
                        {
                            int bi = -1;
                            for (size_t b = 0; b < clone.bindBones.Size() && b < 255; ++b)
                                if (strcasecmp(clone.bindBones[b].m_BoneName.Buffer(), sd.rigidBone.c_str()) == 0) { bi = (int)b; break; }
                            if (bi < 0 || (size_t)bi >= bw.size() || sd.verts == nullptr || sd.vCount == 0) continue;
                            const Vector4& q = bw[(size_t)bi].rotation; const Vector4 qi(-q.m_X, -q.m_Y, -q.m_Z, q.m_W);
                            const Vector3& t = bw[(size_t)bi].position;
                            Vector3* lv = new Vector3[sd.vCount]; uint8_t* bix = new uint8_t[sd.vCount]; Vector3* own = new Vector3[sd.vCount];
                            for (uint32_t k = 0; k < sd.vCount; ++k)
                            {
                                lv[k] = QuatRotateVector(qi, Vector3(sd.verts[k].m_X - t.m_X, sd.verts[k].m_Y - t.m_Y, sd.verts[k].m_Z - t.m_Z));
                                bix[k] = (uint8_t)bi; own[k] = sd.verts[k];
                            }
                            sd.localVerts = lv; sd.vertexBoneIndices = bix; sd.verts = own;
                            if (sd.normals != nullptr)
                            {
                                Vector3* ln = new Vector3[sd.vCount]; Vector3* on = new Vector3[sd.vCount];
                                for (uint32_t k = 0; k < sd.vCount; ++k) { ln[k] = QuatRotateVector(qi, sd.normals[k]); on[k] = sd.normals[k]; }
                                sd.localNormals = ln; sd.normals = on;
                            }
                            ++rigid;
                        }
    return rigid;
}

static void SpawnRealVehiclesAndUnits(const std::vector<VehicleReq>& vehicleReqs,
    const std::vector<CommandPostInfo>& commandPosts,
    const std::vector<VehicleReq>& turretReqs,
    std::vector<ModelData>& uniqueModels, std::vector<PlacedInstance>& placed,
    size_t& outSoldierModelIndex)
{
    logLoadTiming("M532 SpawnRealVehiclesAndUnits start");

    std::set<std::string> repDirect, cisDirect;

    std::map<std::string, std::set<std::string>> localDirect;

    auto scriptLoads = [](const char* sideKey, const std::string& cls) {
        for (const DataFileRequest& req : g_dataFileManifest)
            if (NormalizeLvlKey(req.lvlFile.c_str()) == sideKey)
                for (const std::string& sub : req.subResources) if (strcasecmp(sub.c_str(), cls.c_str()) == 0) return true;
        return false;
    };
    auto addVehicleClass = [&](const std::string& cls) {
        if (cls.rfind("rep_", 0) == 0 && scriptLoads("side/rep.lvl", cls)) repDirect.insert(cls);
        else if (cls.rfind("cis_", 0) == 0 && scriptLoads("side/cis.lvl", cls)) cisDirect.insert(cls);
        else if (cls.find('_') != std::string::npos && scriptLoads(("side/" + cls.substr(0, cls.find('_')) + ".lvl").c_str(), cls))
            localDirect[std::string(GAME_DATA_ROOT) + "side/" + cls.substr(0, cls.find('_')) + ".lvl"].insert(cls);
        else logf("  M485 vehicle class \"%s\": not in the mission's ReadDataFile list - not loaded\n", cls.c_str());
    };
    for (const VehicleReq& req : vehicleReqs)
    {
        addVehicleClass(req.vehicleClass);
        for (const auto& kv : req.classByKey) addVehicleClass(kv.second);
    }

    for (const SkyObjectDef& so : g_skyObjectDefs)
        for (const DataFileRequest& req : g_dataFileManifest)
        {
            const std::string key = NormalizeLvlKey(req.lvlFile.c_str());
            bool listed = false;
            for (const std::string& sub : req.subResources) if (strcasecmp(sub.c_str(), so.geometry.c_str()) == 0) listed = true;
            if (!listed) continue;
            if (key == "side/rep.lvl") repDirect.insert(so.geometry);
            else if (key == "side/cis.lvl") cisDirect.insert(so.geometry);
            else if (key.compare(0, 5, "side/") == 0) localDirect[std::string(GAME_DATA_ROOT) + key].insert(so.geometry);
        }

    static const size_t MAX_UNITS_PER_TEAM = 25;

    struct UnitReq { int teamIdx; std::string teamName; std::string unitClass; };
    std::vector<UnitReq> unitReqs;
    std::set<std::string> repClass, cisClass, geoClass;

    std::map<std::string, std::set<std::string>> localClass;

    auto localSideFor = [](const std::string& cls) -> std::string {
        for (const DataFileRequest& req : g_dataFileManifest)
        {
            const std::string key = NormalizeLvlKey(req.lvlFile.c_str());
            if (key.rfind("side/", 0) != 0 || key == "side/rep.lvl" || key == "side/cis.lvl") continue;
            for (const std::string& s : req.subResources)
                if (s == cls) return std::string(GAME_DATA_ROOT) + key;
        }
        const size_t us = cls.find('_');
        if (us == std::string::npos) return std::string();
        const std::string key = "side/" + cls.substr(0, us) + ".lvl";
        for (const DataFileRequest& req : g_dataFileManifest)
            if (NormalizeLvlKey(req.lvlFile.c_str()) == key) return std::string(GAME_DATA_ROOT) + key;
        return std::string();
    };
    for (size_t t = 0; t < g_teams.size(); ++t)
    {
        const TeamInfo& team = g_teams[t];
        if (team.unitClasses.empty()) continue;

        for (const std::string& cls : team.unitClasses)
        {
            if (cls.rfind("rep_", 0) == 0) repClass.insert(cls);
            else if (cls.rfind("cis_", 0) == 0) cisClass.insert(cls);
            else if (!localSideFor(cls).empty()) localClass[localSideFor(cls)].insert(cls);
            else logf("  team %d (\"%s\") unit class \"%s\" has an unrecognized side prefix - skipping\n",
                (int)t, team.name.c_str(), cls.c_str());
        }

        size_t target = (size_t)(team.unitCount > 0 ? team.unitCount : 0);
        if (target > MAX_UNITS_PER_TEAM) target = MAX_UNITS_PER_TEAM;
        for (size_t u = 0; u < target; ++u)
        {
            const std::string& cls = team.unitClasses[u % team.unitClasses.size()];
            unitReqs.push_back({ (int)t, team.name, cls });
        }
        logf("  team %d (\"%s\"): targeting %u real unit(s) (real SetUnitCount=%d, capped at %u), cycling %u real class(es)\n",
            (int)t, team.name.c_str(), (unsigned)target, team.unitCount, (unsigned)MAX_UNITS_PER_TEAM, (unsigned)team.unitClasses.size());
    }

    static const size_t MAX_REAL_UNIT_CLASSES_PER_SIDE = 8;
    auto capClassSet = [](std::set<std::string>& s, size_t maxCount)
    {
        while (s.size() > maxCount) s.erase(std::prev(s.end()));
    };
    capClassSet(repClass, MAX_REAL_UNIT_CLASSES_PER_SIDE);
    capClassSet(cisClass, MAX_REAL_UNIT_CLASSES_PER_SIDE);
    for (auto& kv : localClass) capClassSet(kv.second, MAX_REAL_UNIT_CLASSES_PER_SIDE);

    for (size_t t = 0; t < g_teams.size(); ++t)
    {
        const std::string& hc = g_teams[t].heroClass;
        if (hc.empty()) continue;
        if (hc.rfind("rep_", 0) == 0) repClass.insert(hc);
        else if (hc.rfind("cis_", 0) == 0) cisClass.insert(hc);
        else if (!localSideFor(hc).empty()) localClass[localSideFor(hc)].insert(hc);
        else { logf("  HEROES team %d hero class \"%s\": no side file names it - no hero\n", (int)t, hc.c_str()); continue; }
        logf("  HEROES team %d hero class \"%s\" loads with its side\n", (int)t, hc.c_str());
    }

    std::vector<const char*> repDirectV, cisDirectV, repClassV, cisClassV, geoClassV, empty;
    for (const std::string& s : repDirect) repDirectV.push_back(s.c_str());
    for (const std::string& s : cisDirect) cisDirectV.push_back(s.c_str());
    for (const std::string& s : repClass) repClassV.push_back(s.c_str());
    for (const std::string& s : cisClass) cisClassV.push_back(s.c_str());
    (void)geoClass; (void)geoClassV;

    if (cisClass.count("cis_inf_rifleman"))
        for (const HudNameMesh* e = kHudNameMesh; e->weapon != nullptr; ++e) cisDirectV.push_back(e->mesh);

    if (cisClass.count("cis_inf_droideka")) cisDirectV.push_back("hud_droideka_shield");

    std::map<std::string, size_t> nameToModelIndex;
    if (!repDirectV.empty() || !repClassV.empty())
        LoadExternalModelsMixed(REP_LVL_PATH, repDirectV, repClassV, uniqueModels, nameToModelIndex);
    logLoadTiming("rep.lvl done");
    if (!cisDirectV.empty() || !cisClassV.empty())
        LoadExternalModelsMixed(CIS_LVL_PATH, cisDirectV, cisClassV, uniqueModels, nameToModelIndex);
    logLoadTiming("cis.lvl done");
    checkpointf("M532 load profile (cumulative after cis): BuildModelData shadow %.2f, prims+mesh %.2f, grids %.2f, visible-floor %.2f, segments+rest %.2f", g_m532BmdUs[0] / 1e6, g_m532BmdUs[4] / 1e6, g_m532BmdUs[5] / 1e6, g_m532BmdUs[1] / 1e6, g_m532BmdUs[3] / 1e6);
    for (const HudNameMesh* e = kHudNameMesh; e->weapon != nullptr; ++e)
    {
        auto hm = nameToModelIndex.find(e->mesh);
        if (hm != nameToModelIndex.end() && hm->second != MODEL_LOAD_FAILED) g_hudIconMeshIndex[e->mesh] = hm->second;
    }
    {
        auto hm = nameToModelIndex.find("hud_droideka_shield");
        if (hm != nameToModelIndex.end() && hm->second != MODEL_LOAD_FAILED) g_hudIconMeshIndex["hud_droideka_shield"] = hm->second;
        logf("M465 hud_droideka_shield from cis.lvl: %s\n", (hm != nameToModelIndex.end() && hm->second != MODEL_LOAD_FAILED) ? "loaded" : "NOT loaded");
    }

    std::set<std::string> localFiles;
    for (const auto& kv : localClass) localFiles.insert(kv.first);
    for (const auto& kv : localDirect) localFiles.insert(kv.first);
    for (const std::string& path : localFiles)
    {
        std::vector<const char*> v, d;
        auto cit = localClass.find(path);
        if (cit != localClass.end()) for (const std::string& c : cit->second) v.push_back(c.c_str());
        auto dit = localDirect.find(path);
        if (dit != localDirect.end()) for (const std::string& c : dit->second) d.push_back(c.c_str());
        long bytes = 0;
        if (FILE* lf = fopen(path.c_str(), "rb")) { fseek(lf, 0, SEEK_END); bytes = ftell(lf); fclose(lf); }
        const bool small = bytes > 0 && bytes < 16L * 1024 * 1024;
        logf("M488 side file %s: %ld KB, %u class(es) + %u model(s), %s\n", path.c_str(), bytes / 1024, (unsigned)v.size(), (unsigned)d.size(),
             small ? "whole" : "restricted");
        if (cit != localClass.end()) g_localSideLvls.insert(path);

        if (small && cit != localClass.end())
        {
            Level* ll = nullptr;
            try { ll = TimedLevelFromFile(String(path.c_str())); } catch (...) { ll = nullptr; }
            if (ll != nullptr)
            {
                for (const std::string& c : cit->second)
                {
                    std::string low;
                    if (!GetPropertyValueInherited(ll, c.c_str(), "GeometryLowRes", low) || low.empty()) continue;
                    g_localLowPending.push_back(LocalLowBody{ path, c, low });
                }
                ReleaseLevel(ll);
            }
        }
        LoadExternalModelsMixed(path, d, v, uniqueModels, nameToModelIndex,  !small);
    }
    logLoadTiming("local side files done");
    for (SkyObjectDef& so : g_skyObjectDefs)
    {
        auto it = nameToModelIndex.find(so.geometry);
        if (it != nameToModelIndex.end() && it->second != MODEL_LOAD_FAILED) so.modelIndex = it->second;
        logf("M468 sky object \"%s\" x%d: %s\n", so.geometry.c_str(), so.count, so.modelIndex != (size_t)-1 ? "model loaded" : "NO MODEL (not drawn)");
    }
    for (const auto& kv : g_unitClassRootScale)
    {
        auto it = nameToModelIndex.find(kv.first);
        if (it != nameToModelIndex.end() && it->second != MODEL_LOAD_FAILED && it->second < uniqueModels.size()) uniqueModels[it->second].rootScale = kv.second;
    }

    {
        auto it = nameToModelIndex.find(Team1PrimaryClass());
        outSoldierModelIndex = (it != nameToModelIndex.end()) ? it->second : MODEL_LOAD_FAILED;

        logf("SpawnRealVehiclesAndUnits: real player-soldier model index = %u (%s)\n",
            (unsigned)outSoldierModelIndex, outSoldierModelIndex != MODEL_LOAD_FAILED ? "resolved" : "NOT FOUND - soldier will be invisible");
    }

    uint32_t vehiclesPlaced = 0;
    g_vehicles.clear(); g_vehicleSpawns.clear();
    for (const VehicleReq& req : vehicleReqs)
    {
        VehicleSpawnState vs;
        vs.name = req.name; vs.position = req.position; vs.rotation = req.rotation;
        vs.controlZone = req.controlZone; vs.fixedTeam = req.fixedTeam;
        vs.spawnTime = req.spawnTime; vs.expireTimeEnemy = req.expireTimeEnemy;
        vs.expireTimeField = req.expireTimeField; vs.decayTime = req.decayTime;
        int ownerAtLoad = req.fixedTeam;
        for (const CommandPostInfo& cpi : commandPosts)
            if (!req.controlZone.empty() && strcasecmp(cpi.name.c_str(), req.controlZone.c_str()) == 0) ownerAtLoad = cpi.team;
        for (int team = 1; team <= 2; ++team)
        {
            if ((size_t)team >= g_teams.size()) continue;
            const std::string key = g_teams[(size_t)team].name + (team == 1 ? "atk" : "def");
            auto ck = req.classByKey.find(key);
            if (ck == req.classByKey.end()) continue;
            auto it = nameToModelIndex.find(ck->second);
            if (it == nameToModelIndex.end() || it->second == MODEL_LOAD_FAILED)
            {
                logf("  vehicle spawn \"%s\" (%s): model unavailable - skipping\n", req.name.c_str(), ck->second.c_str());
                continue;
            }
            PlacedInstance pi;
            pi.modelIndex = it->second;
            pi.position = req.position;
            pi.rotation = req.rotation;
            pi.isVehicle = true;
            pi.team = team;
            const bool outNow = (team == ownerAtLoad);
            if (!outNow) pi.position.m_Y = VEHICLE_PARK_Y;
            VehicleState v;
            v.spawn = (int)g_vehicleSpawns.size(); v.team = team; v.cls = ck->second;
            v.placedIndex = placed.size();
            auto dit = g_vehicleClassDefs.find(v.cls);
            v.hitPoints = (dit != g_vehicleClassDefs.end()) ? dit->second.maxHealth : 1000.0f;
            v.alive = outNow;
            vs.vehicleForTeam[team] = (int)g_vehicles.size();
            if (outNow) vs.active = (int)g_vehicles.size();
            v.yaw = 2.0f * atan2f(req.rotation.m_Y, req.rotation.m_W) + 3.14159265f;
            v.awake = outNow;
            if (dit != g_vehicleClassDefs.end()) v.boostEnergy = dit->second.energyBar;

            if (dit != g_vehicleClassDefs.end())
                for (size_t g = 0; g < dit->second.gunSeats.size() && g < (size_t)MAX_GUN_SEATS; ++g) v.gunYaw[g] = dit->second.gunSeats[g].RestYawRad();
            g_vehicles.push_back(v);
            placed.push_back(pi);
            vehiclesPlaced++;
            if (v.cls.find("snowspeeder") != std::string::npos)
            {
                const ModelData& smd = uniqueModels[it->second];
                logf("FLYERCAM model \"%s\": boundCenter (%.2f %.2f %.2f) radius %.2f halfX %.2f halfY %.2f halfZ %.2f minY %.2f\n",
                     v.cls.c_str(), smd.boundCenter.m_X, smd.boundCenter.m_Y, smd.boundCenter.m_Z, smd.boundRadius,
                     smd.boundHalfX, smd.boundHalfY, smd.boundHalfZ, smd.boundMinY);
            }
            logf("  vehicle spawn \"%s\": team %d \"%s\" at pos=(%.1f,%.1f,%.1f)%s\n", req.name.c_str(), team, v.cls.c_str(),
                req.position.m_X, req.position.m_Y, req.position.m_Z, outNow ? " - out at match start" : " - parked until its team owns the CP");
        }
        g_vehicleSpawns.push_back(vs);
    }

    for (VehicleState& v : g_vehicles)
    {
        auto dit = g_vehicleClassDefs.find(v.cls);
        if (dit == g_vehicleClassDefs.end() || v.placedIndex >= placed.size()) continue;
        if (dit->second.poses.empty() && !dit->second.HasGunner() && dit->second.wheels.empty() && !dit->second.hasWalk) continue;
        const size_t base = placed[v.placedIndex].modelIndex;
        if (base >= uniqueModels.size() || uniqueModels[base].bindBones.Size() == 0) continue;
        ModelData clone = uniqueModels[base];
        clone.textureShareBase = base;
        clone.isAnimated = true;
        clone.animBank = nullptr;
        clone.gpuSkinChecked = false;
        clone.gpuSkin = false;
        v.poseModel = uniqueModels.size();
        v.poseBones = clone.bindBones;
        {

            const std::vector<BoneWorldTransform> bw = ComputeBoneWorldTransforms(clone.bindBones);
            float fmin = 1e9f;
            for (size_t b = 0; b < clone.bindBones.Size() && b < bw.size(); ++b)
            {
                std::string bn = clone.bindBones[b].m_BoneName.Buffer();
                for (char& ch : bn) ch = (char)tolower((unsigned char)ch);
                if (bn.find("foot") != std::string::npos || bn.find("toe") != std::string::npos) fmin = fminf(fmin, bw[b].position.m_Y);
            }
            if (fmin < 1e8f) v.walkSole = fmin - clone.boundMinY;

            if (dit->second.hasWalk && dit->second.walk[VehicleClassDef::WALK_IDLE].frames > 0)
            {
                const VehicleClassDef::WalkClip& idle = dit->second.walk[VehicleClassDef::WALK_IDLE];
                List<Bone> idlePose = clone.bindBones;
                const size_t nb2 = idlePose.Size();
                if (idle.rot.size() >= nb2 && idle.pos.size() >= nb2)
                {
                    for (size_t b = 0; b < nb2; ++b) { idlePose[b].m_Rotation = idle.rot[b]; idlePose[b].m_Position = idle.pos[b]; }
                    const std::vector<BoneWorldTransform> ibw = ComputeBoneWorldTransforms(idlePose);
                    float idleFootMin = 1e9f;
                    for (size_t b = 0; b < nb2 && b < ibw.size(); ++b)
                    {
                        std::string bn = idlePose[b].m_BoneName.Buffer();
                        for (char& ch : bn) ch = (char)tolower((unsigned char)ch);
                        if (bn.find("foot") != std::string::npos || bn.find("toe") != std::string::npos) idleFootMin = fminf(idleFootMin, ibw[b].position.m_Y);
                    }
                    logf("  M450 walker \"%s\": bind foot Y (sole ref) %.2f, real idle-clip foot Y %.2f - %s\n", v.cls.c_str(),
                         fmin < 1e8f ? fmin : -1.0f, idleFootMin,
                         (idleFootMin < 1e8f && fmin < 1e8f && fabsf(idleFootMin - fmin) > 1.0f)
                             ? "MISMATCH: the idle-clip stance is not the bind stance - the bind-derived ground offset does not apply to it"
                             : "consistent");
                }
            }
        }

        if (!dit->second.poses.empty()) v.poseBones = dit->second.poses[4];
        uniqueModels.push_back(clone);
        placed[v.placedIndex].modelIndex = v.poseModel;
    }

    {
        std::set<std::string> reservedCp;
        for (VehicleState& v : g_vehicles)
        {
            const VehicleSpawnState& sp = g_vehicleSpawns[(size_t)v.spawn];
            auto dit = g_vehicleClassDefs.find(v.cls);
            if (dit == g_vehicleClassDefs.end() || !dit->second.reserveOneForPlayer) continue;
            const std::string key = LowerStr(sp.controlZone) + "/" + std::to_string(v.team);
            if (reservedCp.insert(key).second)
            {
                v.reservedForPlayer = true;
                logf("  M438 vehicle \"%s\" at %s is left for the player (ReserveOneForPlayer)\n", v.cls.c_str(), sp.name.c_str());
            }
        }
    }
    logf("SpawnRealVehiclesAndUnits: placed %u vehicle(s) at %u real vehicle spawn(s) (one per team's class field)\n", vehiclesPlaced, (unsigned)vehicleReqs.size());

    size_t cpModelIdx = LoadExternalModel(INGAME_LVL_PATH, "com_bldg_controlzone", uniqueModels);
    logLoadTiming("ingame.lvl (command-post model) done");
    uint32_t cpModelsPlaced = 0;
    if (cpModelIdx != MODEL_LOAD_FAILED)
    {
        for (size_t cpi = 0; cpi < commandPosts.size(); ++cpi)
        {
            const CommandPostInfo& cp = commandPosts[cpi];
            PlacedInstance pi;
            pi.modelIndex = cpModelIdx;
            pi.position = cp.position;
            pi.rotation = cp.rotation;
            pi.cpIndex = (int)cpi;
            placed.push_back(pi);
            cpModelsPlaced++;
        }
    }
    logf("SpawnRealVehiclesAndUnits: placed %u of %u real command-post model(s)\n",
        cpModelsPlaced, (unsigned)commandPosts.size());

    g_muzzleFlashModel = LoadExternalModel(INGAME_LVL_PATH, "com_sfx_muzzleflash", uniqueModels);
    logf("MUZZLE FLASH model com_sfx_muzzleflash: %s\n", g_muzzleFlashModel != MODEL_LOAD_FAILED ? "loaded" : "MISSING");
    if (g_muzzleFlashModel == MODEL_LOAD_FAILED) g_muzzleFlashModel = (size_t)-1;

    for (const auto& fi : g_cpHolo.icons)
    {
        const size_t mi = LoadExternalModel(INGAME_LVL_PATH, fi.second.c_str(), uniqueModels);
        if (mi != MODEL_LOAD_FAILED) g_cpHolo.iconModel[fi.first] = mi;
        logf("M478 CP hologram logo \"%s\" (%s): %s\n", fi.second.c_str(), fi.first.c_str(), mi != MODEL_LOAD_FAILED ? "loaded" : "MISSING");
    }

    if (!g_stations.empty())
    {
        std::vector<std::string> names;
        for (const PowerupStationState& s : g_stations)
            for (const std::string* n : { &s.liveGeometry, &s.deadGeometry, &s.unbuiltGeometry })
                if (!n->empty() && std::find(names.begin(), names.end(), *n) == names.end()) names.push_back(*n);
        std::vector<const char*> direct, noClasses;
        for (const std::string& n : names) direct.push_back(n.c_str());
        std::map<std::string, size_t> idx;
        LoadExternalModelsMixed(INGAME_LVL_PATH, direct, noClasses, uniqueModels, idx,  false);
        unsigned placedCount = 0;
        for (PowerupStationState& s : g_stations)
        {
            auto li = idx.find(s.liveGeometry), di = idx.find(s.deadGeometry);
            s.liveModel = (li != idx.end()) ? li->second : MODEL_LOAD_FAILED;
            s.deadModel = (di != idx.end()) ? di->second : MODEL_LOAD_FAILED;
            if (s.liveModel == MODEL_LOAD_FAILED) { logf("  M469 station \"%s\": model \"%s\" not loaded - not placed\n", s.name.c_str(), s.liveGeometry.c_str()); continue; }
            if (s.deadModel == MODEL_LOAD_FAILED) s.deadModel = SIZE_MAX;
            if (!s.unbuiltGeometry.empty())
            {
                auto ui = idx.find(s.unbuiltGeometry);
                if (ui != idx.end() && ui->second != MODEL_LOAD_FAILED) s.unbuiltModel = ui->second;
            }

            if (uniqueModels[s.liveModel].bindBones.Size() > 0)
            {
                ModelData clone = uniqueModels[s.liveModel];
                clone.textureShareBase = s.liveModel;
                clone.isAnimated = true;
                clone.animBank = nullptr;
                clone.gpuSkinChecked = false;
                clone.gpuSkin = false;

                uint32_t unbaked = 0;
                for (SegmentData& sd : clone.segments)
                    if (sd.vertexBoneIndices != nullptr && sd.localVerts != nullptr && sd.interleavedVbo != 0) { sd.interleavedVbo = 0; ++unbaked; }
                s.poseModel = uniqueModels.size();
                s.poseBones = clone.bindBones;
                uniqueModels.push_back(clone);
                auto boneIdx = [&](const std::string& n) -> int {
                    if (n.empty()) return -1;
                    for (size_t b = 0; b < s.poseBones.Size(); ++b)
                        if (strcasecmp(s.poseBones[b].m_BoneName.Buffer(), n.c_str()) == 0) return (int)b;
                    return -1;
                };
                s.boneRoot = boneIdx("dummyroot");
                s.boneWobble = boneIdx(s.wobbleNode);
                s.boneFootL = boneIdx(s.wobbleFootL);
                s.boneFootR = boneIdx(s.wobbleFootR);
                s.boneSpin = boneIdx(s.spinNode);
                for (const std::string& n : s.activeNodes) { s.boneActive.push_back(boneIdx(n)); s.activeAngle.push_back(0.0f); s.activeTarget.push_back(0.0f); }
                s.liveModel = s.poseModel;
                s.idleWait = (float)(rand() % 100) * 0.01f * s.idleWaitTime;
                logf("  M470 station \"%s\" posed clone %u: bones %u root %d wobble %d feet %d/%d spin %d active %d/%d, M471 unbaked %u segment(s)\n", s.name.c_str(),
                     (unsigned)s.poseModel, (unsigned)s.poseBones.Size(), s.boneRoot, s.boneWobble, s.boneFootL, s.boneFootR, s.boneSpin,
                     s.boneActive.size() > 0 ? s.boneActive[0] : -1, s.boneActive.size() > 1 ? s.boneActive[1] : -1, unbaked);
            }
            PlacedInstance pi;
            pi.modelIndex = s.liveModel;

            if (s.unbuiltModel != SIZE_MAX) { pi.modelIndex = s.unbuiltModel; s.alive = false; s.hitPoints = 0.0f; }
            pi.position = s.position;
            pi.rotation = s.rotation;
            pi.stationIndex = (int)(&s - &g_stations[0]);
            s.placedIndex = placed.size();
            placed.push_back(pi);
            placedCount++;
        }
        logf("SpawnRealVehiclesAndUnits: M469 placed %u of %u health/ammo droid(s)\n", placedCount, (unsigned)g_stations.size());
    }
    logLoadTiming("M469 health/ammo droids placed");

    std::map<std::string, size_t> turretNameToModelIndex;
    std::set<std::string> turretClassSet;
    for (const VehicleReq& req : turretReqs) turretClassSet.insert(req.vehicleClass);
    if (!turretReqs.empty())
    {
        std::vector<const char*> turretClassNames;
        for (const std::string& c : turretClassSet) turretClassNames.push_back(c.c_str());
        std::vector<const char*> turretDirect;
        LoadExternalModelsMixed(TUR_LVL_PATH, turretDirect, turretClassNames, uniqueModels, turretNameToModelIndex);
    }
    logLoadTiming("tur.lvl done");

    {
        std::vector<std::string> names;
        for (const std::string& c : turretClassSet)
        {
            auto d = g_vehicleClassDefs.find(c);
            if (d != g_vehicleClassDefs.end() && d->second.deadGeometry.empty() && !d->second.unbuiltGeometry.empty() &&
                std::find(names.begin(), names.end(), d->second.unbuiltGeometry) == names.end())
                names.push_back(d->second.unbuiltGeometry);
        }
        if (!names.empty())
        {
            std::vector<const char*> direct, noClasses;
            for (const std::string& n : names) direct.push_back(n.c_str());
            LoadExternalModelsMixed(INGAME_LVL_PATH, direct, noClasses, uniqueModels, turretNameToModelIndex,  false);
        }
    }
    uint32_t turretsPlaced = 0;
    for (const VehicleReq& req : turretReqs)
    {
        auto turretModelIt = turretNameToModelIndex.find(req.vehicleClass);
        if (turretModelIt == turretNameToModelIndex.end() || turretModelIt->second == MODEL_LOAD_FAILED)
        {
            logf("  M481 turret \"%s\" (%s): model unavailable - skipping\n", req.name.c_str(), req.vehicleClass.c_str());
            continue;
        }

        auto tdit = g_vehicleClassDefs.find(req.vehicleClass);
        size_t deadModel = SIZE_MAX;
        if (tdit != g_vehicleClassDefs.end() && (!tdit->second.deadGeometry.empty() || !tdit->second.unbuiltGeometry.empty()))
        {
            auto deadIt = turretNameToModelIndex.find(!tdit->second.deadGeometry.empty() ? tdit->second.deadGeometry : tdit->second.unbuiltGeometry);
            if (deadIt != turretNameToModelIndex.end() && deadIt->second != MODEL_LOAD_FAILED) deadModel = deadIt->second;
        }
        {
            PlacedInstance pi;
            pi.modelIndex = turretModelIt->second;
            pi.position = req.position;
            pi.rotation = req.rotation;
            if (tdit != g_vehicleClassDefs.end() && tdit->second.HasGunner())
            {
                pi.isVehicle = true; pi.team = 0;
                VehicleState v;
                v.spawn = -1; v.team = 0; v.cls = req.vehicleClass; v.isTurret = true;
                v.placedIndex = placed.size(); v.alive = true; v.hitPoints = tdit->second.maxHealth;
                v.yaw = 2.0f * atan2f(req.rotation.m_Y, req.rotation.m_W) + 3.14159265f;
                v.liveModel = pi.modelIndex; v.deadModel = deadModel;
                const size_t base = pi.modelIndex;
                if (base < uniqueModels.size() && (uniqueModels[base].bindBones.Size() > 0 || uniqueModels[base].rigidBones.Size() > 0))
                {
                    ModelData clone = uniqueModels[base];

                    if (clone.bindBones.Size() == 0)
                    {
                        const unsigned rigid = BindRigidSegmentsToBones(clone);
                        logf("  M490 turret \"%s\": %u rigid segment(s) bound to their bones for posing\n", req.name.c_str(), rigid);
                    }
                    clone.textureShareBase = base;
                    clone.isAnimated = true; clone.animBank = nullptr;
                    clone.gpuSkinChecked = false; clone.gpuSkin = false;
                    v.poseModel = uniqueModels.size();
                    v.poseBones = clone.bindBones;
                    uniqueModels.push_back(clone);
                    pi.modelIndex = v.poseModel; v.liveModel = v.poseModel;
                }
                g_vehicles.push_back(v);
                logf("  M472 turret \"%s\" (%s) usable: vehicle #%u, health %.0f, respawn %.0fs, seat weapon \"%s\", turret node \"%s\", fire points %u, dead model \"%s\" %s\n",
                     req.name.c_str(), req.vehicleClass.c_str(), (unsigned)(g_vehicles.size() - 1), tdit->second.maxHealth, tdit->second.respawnTime,
                     tdit->second.gunSeats[0].weapon.weaponName.c_str(), tdit->second.gunSeats[0].turretNode.c_str(),
                     (unsigned)tdit->second.gunSeats[0].weapon.firePoints.size(), !tdit->second.deadGeometry.empty() ? tdit->second.deadGeometry.c_str() : tdit->second.unbuiltGeometry.c_str(), deadModel != SIZE_MAX ? "loaded" : "none (stays as it stood)");
            }
            else logf("  M472 turret \"%s\": class not parsed as a vehicle - static prop\n", req.name.c_str());
            placed.push_back(pi);
            turretsPlaced++;
        }
    }
    logf("SpawnRealVehiclesAndUnits: placed %u of %u real stationary turret(s)\n",
        turretsPlaced, (unsigned)turretReqs.size());

    std::map<int, std::vector<CommandPostInfo>> cpsByTeam;
    for (const CommandPostInfo& cp : commandPosts) cpsByTeam[cp.team].push_back(cp);

    std::map<int, size_t> perTeamCursor;

    uint32_t unitsPlaced = 0;
    if (commandPosts.empty())
    {
        logf("SpawnRealVehiclesAndUnits: no real command posts in any loaded world - nowhere to spawn units\n");
    }
    else
    {
        for (size_t r = 0; r < unitReqs.size(); ++r)
        {
            const UnitReq& req = unitReqs[r];

            bool localsOwnPost = false;
            for (const CommandPostInfo& ocp : commandPosts) if (ocp.team == req.teamIdx) localsOwnPost = true;
            const bool isLocals = !IsCapturingTeam(req.teamIdx) && !localsOwnPost;
            std::vector<CommandPostInfo> allyCps;
            if (isLocals)
            {
                for (const CommandPostInfo& acp : commandPosts)
                    if (!acp.allyPath.empty() && acp.team >= 1 && IsFriend(acp.team, req.teamIdx)) allyCps.push_back(acp);
                if (allyCps.empty())
                {
                    logf("  team %d (\"%s\") unit class \"%s\": no friendly command post with an AllyPath - not spawning\n",
                        req.teamIdx, req.teamName.c_str(), req.unitClass.c_str());
                    continue;
                }
            }

            auto it = nameToModelIndex.find(req.unitClass);
            if (it == nameToModelIndex.end() || it->second == MODEL_LOAD_FAILED)
            {
                logf("  team %d (\"%s\") unit class \"%s\": model unavailable - skipping\n",
                    req.teamIdx, req.teamName.c_str(), req.unitClass.c_str());
                continue;
            }

            auto ownedIt = cpsByTeam.find(req.teamIdx);
            const bool hasOwnCPs = (ownedIt != cpsByTeam.end() && !ownedIt->second.empty());
            const std::vector<CommandPostInfo>& eligibleCPs = isLocals ? allyCps : (hasOwnCPs ? ownedIt->second : commandPosts);

            size_t& cursor = perTeamCursor[req.teamIdx];
            const CommandPostInfo& cp = eligibleCPs[cursor % eligibleCPs.size()];
            float angle = (float)cursor * 0.9f;
            float radius = 3.0f + 1.5f * (float)(cursor / eligibleCPs.size());
            Vector3 pos(cp.position.m_X + cosf(angle) * radius, cp.position.m_Y, cp.position.m_Z + sinf(angle) * radius);

            uint32_t allyNode = 0;
            bool allyNodeReal = false;
            float allyYaw = 0.0f;
            {
                static std::map<std::string, uint32_t> s_spawnSlotPerCp;
                Vector3 nodePos;

                if (isLocals)
                {
                    uint32_t& slot = s_spawnSlotPerCp["#ally:" + LowerStr(cp.allyPath)];
                    allyNode = slot;
                    allyNodeReal = RealSpawnPathNode(cp.allyPath, slot++, nodePos, &allyYaw);
                    if (allyNodeReal) pos = nodePos;
                    else logf("  M476 AllyPath \"%s\" has no nodes - using the post itself\n", cp.allyPath.c_str());
                }
                else if (RealSpawnPathNode(cp.spawnPath, s_spawnSlotPerCp[cp.name]++, nodePos, nullptr)) pos = nodePos;
            }
            cursor++;
            if (isLocals)
                for (size_t ci = 0; ci < commandPosts.size(); ++ci)
                    if (commandPosts[ci].name == cp.name) { g_initialAllyCp[placed.size()] = (int)ci; g_initialAllyCount[(int)ci] = cp.allyCount; }

            PlacedInstance pi;
            pi.modelIndex = it->second;
            pi.position = pos;
            pi.rotation = cp.rotation;
            if (allyNodeReal) pi.rotation = ModelQuatFromFacingYaw(allyYaw);
            pi.team = req.teamIdx;
            pi.isSoldier = true;
            pi.isDroideka = (req.unitClass == "cis_inf_droideka");

            pi.animCharacterType = AnimCharacterTypeForClass(req.unitClass);
            pi.unitClass = req.unitClass;

            {
                auto loIt = g_unitClassLoadout.find(req.unitClass);
                if (loIt != g_unitClassLoadout.end())
                {
                    for (int wIdx : loIt->second.slotWeapon)
                    {
                        if (wIdx >= 0 && (size_t)wIdx < g_weaponTable.size() && g_weaponTable[(size_t)wIdx].isShieldWeapon)
                        { pi.shieldWeaponIdx = wIdx; break; }
                    }
                }
            }
            {

                auto wIt = g_unitClassWeapon.find(req.unitClass);
                pi.weaponIndex = (wIt != g_unitClassWeapon.end()) ? wIt->second : -1;
            }
            placed.push_back(pi);
            unitsPlaced++;
            if (isLocals)
                logf("  team %d (\"%s\"): placed real \"%s\" at friendly post \"%s\" (owned by team %d) via its real AllyPath \"%s\"%s (node %u) pos=(%.1f,%.1f,%.1f) yaw=%.2f\n",
                    req.teamIdx, req.teamName.c_str(), req.unitClass.c_str(), cp.name.c_str(), cp.team,
                    cp.allyPath.c_str(), allyNodeReal ? "" : " (no nodes - the post itself)", allyNode,
                    pos.m_X, pos.m_Y, pos.m_Z, allyYaw);
            else
                logf("  team %d (\"%s\"): placed real \"%s\" at real command post \"%s\" (owned by team %d%s) pos=(%.1f,%.1f,%.1f)\n",
                    req.teamIdx, req.teamName.c_str(), req.unitClass.c_str(), cp.name.c_str(), cp.team,
                    hasOwnCPs ? "" : " - no real CP owned by this team, used the full list", pos.m_X, pos.m_Y, pos.m_Z);
        }
    }
    logf("SpawnRealVehiclesAndUnits: placed %u of %u real (team, unit class) representative(s)\n", unitsPlaced, (unsigned)unitReqs.size());

}

