{
    std::string name;
    Vector3 position;

    bool hasCaptureRegion = false;
    Vector3 captureRegionPos;
    Vector4 captureRegionRot;
    Vector3 captureRegionSize;
    std::string captureRegionType;
    std::string spawnPath;
    std::string allyPath;
    int allyCount = 0;
    int hudIndex = 0;
    float captureTime = -1.0f, neutralizeTime = -1.0f;
    bool mapIcon = true, holo = true;

    int team = -1;
    std::map<std::string, float> valueAtk, valueDef;
    int captureTeam = 0;
    bool captureDisputed = false;
    bool captureToNeutral = false;
    float captureTimer = 0.0f;
    int captureCount = 0;
};
static std::vector<CommandPostState> g_commandPosts;
static void ScriptSetPostTeam(const std::string& lowerName, int team)
{
    for (CommandPostState& cp : g_commandPosts) if (cp.name == lowerName) { cp.team = team; cp.captureTeam = 0; cp.captureTimer = 0.0f; }
}

struct CpLostEvent { int cp; int formerTeam; };
static std::vector<CpLostEvent> g_cpLostEvents;
static std::vector<int> g_cpCapturedEvents;
static std::vector<int> s_cpAssigned[8], s_cpEnemiesNear[8];
static int s_teamAlive[8] = {};

static std::vector<int> s_cpDeaths[8];
static std::vector<float> s_cpDeathDistSum[8];

static uint32_t g_shotNearCpDiagCount = 0;
static uint32_t g_aiStuckDiagCount = 0;
static void LogShotNearCommandPost(const Vector3& fireOrigin, const Vector3& fireDir,
    bool hit, float hitDist, const Vector3& hitPoint)
{
    if (g_shotNearCpDiagCount >= 80) return;
    for (const CommandPostState& cp : g_commandPosts)
    {
        const float dx = cp.position.m_X - fireOrigin.m_X, dz = cp.position.m_Z - fireOrigin.m_Z;
        const float d = sqrtf(dx * dx + dz * dz);
        if (d > 40.0f) continue;
        g_shotNearCpDiagCount++;
        if (kDiagVerbose) checkpointf("M316 shotNearCP: cp=\"%s\" cpDist=%.1fm origin=(%.1f,%.1f,%.1f) dir=(%.2f,%.2f,%.2f) hit=%d hitDist=%.1f hitPt=(%.1f,%.1f,%.1f)",
            cp.name.c_str(), d, fireOrigin.m_X, fireOrigin.m_Y, fireOrigin.m_Z,
            fireDir.m_X, fireDir.m_Y, fireDir.m_Z, (int)hit, hit ? hitDist : -1.0f,
            hitPoint.m_X, hitPoint.m_Y, hitPoint.m_Z);
        break;
    }
}

static float g_commandPostCaptureTime = 10.0f;
static float g_commandPostNeutralizeTime = 12.0f;

static std::map<std::string, float> g_cpBleedValueByFaction = {
    { "rep", 10.0f }, { "cis", 10.0f }, { "all", 10.0f }, { "imp", 10.0f },
    { "locals", 0.0f }, { "neutral", 0.0f },
};

static void ResolveCommandPostClassTimings()
{
    if (!FileExists(INGAME_LVL_PATH.c_str())) return;
    List<String> subLvls;
    subLvls.Add(String("com_bldg_controlzone"));
    Level* lvl = nullptr;
    try { lvl = TimedLevelFromFile(INGAME_LVL_PATH.c_str(), &subLvls); }
    catch (const std::exception& e)
    {
        logf("ResolveCommandPostClassTimings: Level::FromFile threw: %s - using fallback timings\n", e.what());
        return;
    }
    if (lvl == nullptr)
    {
        logf("ResolveCommandPostClassTimings: Level::FromFile returned null - using fallback timings\n");
        return;
    }
    const EntityClass* ec = lvl->GetEntityClass(String("com_bldg_controlzone"));
    if (ec != nullptr)
    {
        String v;
        if (ec->GetProperty(String("CaptureTime"), v)) g_commandPostCaptureTime = (float)atof(v.Buffer());
        if (ec->GetProperty(String("NeutralizeTime"), v)) g_commandPostNeutralizeTime = (float)atof(v.Buffer());
        logf("ResolveCommandPostClassTimings: real CaptureTime=%.1f NeutralizeTime=%.1f (from ingame.lvl's real EntityClass)\n",
            g_commandPostCaptureTime, g_commandPostNeutralizeTime);

        struct { const char* prop; const char* faction; } bleedProps[] = {
            { "ValueBleed_Republic", "rep" }, { "ValueBleed_CIS", "cis" },
            { "ValueBleed_Alliance", "all" }, { "ValueBleed_Empire", "imp" },
            { "ValueBleed_Locals", "locals" }, { "ValueBleed_Neutral", "neutral" },
        };
        for (const auto& bp : bleedProps)
        {
            if (ec->GetProperty(String(bp.prop), v))
                g_cpBleedValueByFaction[bp.faction] = (float)atof(v.Buffer());
        }
        logf("ResolveCommandPostClassTimings: real per-faction CP bleed values: rep=%.1f cis=%.1f locals=%.1f neutral=%.1f\n",
            g_cpBleedValueByFaction.count("rep") ? g_cpBleedValueByFaction["rep"] : -1.0f,
            g_cpBleedValueByFaction.count("cis") ? g_cpBleedValueByFaction["cis"] : -1.0f,
            g_cpBleedValueByFaction.count("locals") ? g_cpBleedValueByFaction["locals"] : -1.0f,
            g_cpBleedValueByFaction.count("neutral") ? g_cpBleedValueByFaction["neutral"] : -1.0f);
    }
    else
    {
        logf("ResolveCommandPostClassTimings: com_bldg_controlzone EntityClass not found - using fallback timings\n");
    }
    ReleaseLevel(lvl);
}

static int g_missionWinningTeam = 0;
static bool g_missionOver = false;

static float g_matchOverAutoRestartTimer = -1.0f;

