{
    int timerIdx = -1;
    int kind = 0;
    int team = 0;
};
static HudTimerSlot g_hudTimerSlot;

static bool g_noVictoryTimerDbg = getenv("SWBF2_NOVICTIMER") != nullptr;

static std::vector<int> g_onFinishCaptureRefs;
static std::vector<int> g_onFinishNeutralizeRefs;
