static CommandPostState* FindCommandPostByName(const char* name)
{
    if (name == nullptr) return nullptr;
    std::string want(name);
    for (char& c : want) c = (char)tolower((unsigned char)c);
    for (CommandPostState& cp : g_commandPosts)
    {
        std::string have = cp.name;
        for (char& c : have) c = (char)tolower((unsigned char)c);
        if (have == want) return &cp;
    }
    return nullptr;
}

static int Lua_GetCommandPostBleedValue(lua_State* L)
{
    int team = (int)lua_tonumber(L, 2);
    float value = 0.0f;
    if (team >= 0 && (size_t)team < g_teams.size())
    {
        auto it = g_cpBleedValueByFaction.find(g_teams[team].name);
        if (it != g_cpBleedValueByFaction.end()) value = it->second;
    }
    lua_pushnumber(L, value);
    return 1;
}

static int Lua_GetObjectTeam(lua_State* L)
{
    const char* name = lua_isstring(L, 1) ? lua_tostring(L, 1) : nullptr;
    CommandPostState* cp = FindCommandPostByName(name);
    lua_pushnumber(L, cp != nullptr ? (lua_Number)cp->team : 0);
    return 1;
}

static int Lua_IsObjectAlive(lua_State* L)
{
    const char* name = lua_isstring(L, 1) ? lua_tostring(L, 1) : nullptr;
    lua_pushboolean(L, FindCommandPostByName(name) != nullptr ? 1 : 0);
    return 1;
}

static int Lua_GetReinforcementCount(lua_State* L)
{
    int team = (int)lua_tonumber(L, 1);
    lua_Number count = 0;
    if (team >= 0 && (size_t)team < g_teams.size()) count = (lua_Number)g_teams[team].reinforcementCount;
    lua_pushnumber(L, count);
    return 1;
}

static int Lua_GetNumTeamMembersAlive(lua_State* L)
{
    int team = (int)lua_tonumber(L, 1);
    int alive = 0;
    const std::vector<PlacedInstance>& placedRef = (g_placedForScripts != nullptr) ? *g_placedForScripts : g_emptyPlaced;
    for (const PlacedInstance& pi : placedRef) if (pi.team == team && !pi.isVehicle) alive++;
    lua_pushnumber(L, (lua_Number)alive);
    return 1;
}

static int Lua_GetEntityName(lua_State* L)
{
    if (lua_isstring(L, 1)) lua_pushstring(L, lua_tostring(L, 1));
    else lua_pushstring(L, "");
    return 1;
}

static int Lua_MissionVictory(lua_State* L)
{
    int team = (int)lua_tonumber(L, 1);
    g_missionWinningTeam = team;
    g_missionOver = true;
    checkpointf("MILESTONE 62 - real MissionVictory(team=%d) - match won", team);
    return 0;
}

static int Lua_MissionDefeat(lua_State* L)
{
    int team = (int)lua_tonumber(L, 1);

    g_missionWinningTeam = (team == 1) ? 2 : 1;
    g_missionOver = true;
    checkpointf("MILESTONE 62 - real MissionDefeat(team=%d) - match lost by that team", team);
    return 0;
}

static void HudTimerSlotSet(int timerIdx, int kind, int team)
{
    if (g_hudTimerSlot.timerIdx == timerIdx && g_hudTimerSlot.kind == kind && g_hudTimerSlot.team == team) return;
    g_hudTimerSlot.timerIdx = timerIdx; g_hudTimerSlot.kind = kind; g_hudTimerSlot.team = team;
    checkpointf("CAPTUREWIN slot <- timer=%d kind=%d team=%d", timerIdx, kind, team);
}
static int Lua_SetDefeatTimer(lua_State* L)
{
    HudTimerSlotSet(lua_isnumber(L, 1) ? (int)lua_tonumber(L, 1) : -1,
                    -1,
                    lua_isnumber(L, 2) ? (int)lua_tonumber(L, 2) : 0);
    return 0;
}

static int Lua_SetVictoryTimer(lua_State* L)
{
    HudTimerSlotSet(lua_isnumber(L, 1) ? (int)lua_tonumber(L, 1) : -1,
                    1,
                    lua_isnumber(L, 2) ? (int)lua_tonumber(L, 2) : 0);
    return 0;
}

static int Lua_SetMissionTimer(lua_State* L)
{
    HudTimerSlotSet(lua_isnumber(L, 1) ? (int)lua_tonumber(L, 1) : -1, 0, 0);
    return 0;
}

static int HudTimerEvent(int viewerTeam, float& outSeconds, bool& outRunning)
{
    outSeconds = 0.0f; outRunning = false;
    const HudTimerSlot& s = g_hudTimerSlot;
    if (s.timerIdx < 0 || (size_t)s.timerIdx >= g_timers.size() || !g_timers[(size_t)s.timerIdx].inUse) return 0;
    const TimerState& t = g_timers[(size_t)s.timerIdx];
    outSeconds = t.value > 0.0f ? t.value : 0.0f;
    outRunning = t.running;
    if (s.kind == 0) return 0;

    const int relation = (viewerTeam == s.team) ? 1 : -1;
    return s.kind * relation;
}

static int RegisterLuaCallback(lua_State* L, std::vector<int>& into)
{
    if (!lua_isfunction(L, 1)) return 0;
    lua_pushvalue(L, 1);
    int ref = luaL_ref(L, LUA_REGISTRYINDEX);
    into.push_back(ref);
    lua_pushnumber(L, (lua_Number)ref);
    return 1;
}
static int Lua_OnFinishCapture(lua_State* L)       { return RegisterLuaCallback(L, g_onFinishCaptureRefs); }
static int Lua_OnFinishNeutralize(lua_State* L)    { return RegisterLuaCallback(L, g_onFinishNeutralizeRefs); }
static int Lua_OnCommandPostRespawn(lua_State* L)  { return RegisterLuaCallback(L, g_onCommandPostRespawnRefs); }
static int Lua_OnCommandPostKill(lua_State* L)     { return RegisterLuaCallback(L, g_onCommandPostKillRefs); }
static int Lua_OnCharacterDeath(lua_State* L)      { return RegisterLuaCallback(L, g_onCharacterDeathRefs); }
