struct AIGoalEntry
{
    int handle;
    std::string type;
    float weight;
    std::string target;
};
static std::map<int, std::vector<AIGoalEntry>> g_aiGoalsByTeam;
static int g_nextAIGoalHandle = 1;

static int Lua_AddAIGoal(lua_State* L)
{
    int team = (int)lua_tonumber(L, 1);
    const char* goalType = lua_isstring(L, 2) ? lua_tostring(L, 2) : "?";
    float weight = lua_isnumber(L, 3) ? (float)lua_tonumber(L, 3) : 1.0f;
    std::string target;
    if (lua_gettop(L) >= 4 && lua_isstring(L, 4)) target = lua_tostring(L, 4);
    int handle = g_nextAIGoalHandle++;
    g_aiGoalsByTeam[team].push_back(AIGoalEntry{ handle, goalType, weight, target });
    checkpointf("MILESTONE 63 - real AddAIGoal(team=%d, \"%s\", weight=%.1f, target=\"%s\") -> handle %d",
        team, goalType, weight, target.c_str(), handle);
    lua_pushnumber(L, (lua_Number)handle);
    return 1;
}

static int Lua_ClearAIGoals(lua_State* L)
{
    int team = (int)lua_tonumber(L, 1);
    g_aiGoalsByTeam[team].clear();
    checkpointf("MILESTONE 63 - real ClearAIGoals(team=%d)", team);
    return 0;
}

static int Lua_DeleteAIGoal(lua_State* L)
{
    int handle = (int)lua_tonumber(L, 1);
    for (auto& kv : g_aiGoalsByTeam)
    {
        std::vector<AIGoalEntry>& goals = kv.second;
        for (size_t i = 0; i < goals.size(); ++i)
        {
            if (goals[i].handle == handle) { goals.erase(goals.begin() + (long)i); break; }
        }
    }
    checkpointf("MILESTONE 63 - real DeleteAIGoal(handle=%d)", handle);
    return 0;
}

static void FireCommandPostEvent(const std::vector<int>& refs, const char* cpName)
{
    if (g_missionLuaState == nullptr || refs.empty()) return;
    lua_State* L = g_missionLuaState;
    for (int ref : refs)
    {
        lua_rawgeti(L, LUA_REGISTRYINDEX, ref);
        if (!lua_isfunction(L, -1)) { lua_pop(L, 1); continue; }
        lua_pushstring(L, cpName);
        if (lua_pcall(L, 1, 0, 0) != 0)
        {
            const char* err = lua_isstring(L, -1) ? lua_tostring(L, -1) : "(no error message)";
            checkpointf("MILESTONE 62 - real command-post event callback error: %s", err);
            lua_pop(L, 1);
        }
    }
}

