static int Lua_GetCharacterTeam(lua_State* L)
{
    void* handle = lua_touserdata(L, 1);
    int team = -1;
    if (handle != nullptr && handle == g_playerSoldierForScripts) team = g_playerTeamForScripts;
    else if (handle != nullptr) team = GetAIUnitTeamByHandle(handle);
    lua_pushnumber(L, (lua_Number)team);
    return 1;
}

static void FireCharacterDeathEvent(const std::vector<int>& refs, void* character, void* killer = nullptr)
{
    if (g_missionLuaState == nullptr || refs.empty()) return;
    lua_State* L = g_missionLuaState;
    for (int ref : refs)
    {
        lua_rawgeti(L, LUA_REGISTRYINDEX, ref);
        if (!lua_isfunction(L, -1)) { lua_pop(L, 1); continue; }
        lua_pushlightuserdata(L, character);

        if (killer != nullptr) lua_pushlightuserdata(L, killer);
        else lua_pushnil(L);
        if (lua_pcall(L, 2, 0, 0) != 0)
        {
            const char* err = lua_isstring(L, -1) ? lua_tostring(L, -1) : "(no error message)";
            checkpointf("MILESTONE 63 - real OnCharacterDeath callback error: %s", err);
            lua_pop(L, 1);
        }
    }
}

static void FireTicketCountChangeEvent(int team, int newCount)
{
    if (g_missionLuaState == nullptr || g_onTicketCountChangeRefs.empty()) return;
    lua_State* L = g_missionLuaState;
    for (int ref : g_onTicketCountChangeRefs)
    {
        lua_rawgeti(L, LUA_REGISTRYINDEX, ref);
        if (!lua_isfunction(L, -1)) { lua_pop(L, 1); continue; }
        lua_pushnumber(L, (lua_Number)team);
        lua_pushnumber(L, (lua_Number)newCount);
        if (lua_pcall(L, 2, 0, 0) != 0)
        {
            const char* err = lua_isstring(L, -1) ? lua_tostring(L, -1) : "(no error message)";
            checkpointf("MILESTONE 63 - real OnTicketCountChange callback error: %s", err);
            lua_pop(L, 1);
        }
    }
}

