static float RealChargedMaxDamage(const WeaponStats& w, float chargeStrength)
{
    if (!w.hasNextCharge || w.nextChargeDamage <= 0.0f || chargeStrength <= 0.0f)
        return w.maxDamage;
    const float t = (w.nextChargeLevel > 0.0001f)
                  ? fminf(1.0f, chargeStrength / w.nextChargeLevel) : 1.0f;
    return w.maxDamage + (w.nextChargeDamage - w.maxDamage) * t;
}

static float RealDamageAtFlightTime(const WeaponStats& w, float flightSec)
{

    if (w.finalDamage < 0.0f) return w.maxDamage;
    if (w.damageTransitionDelay < 0.0f) return w.maxDamage;
    if (flightSec <= w.damageTransitionDelay) return w.maxDamage;
    if (w.damageTransitionPeriod <= 0.0001f) return w.finalDamage;
    float t = (flightSec - w.damageTransitionDelay) / w.damageTransitionPeriod;
    if (t > 1.0f) t = 1.0f;
    return w.maxDamage + (w.finalDamage - w.maxDamage) * t;
}

