static float GetAnimBlendTime(CRCChecksum anim)
{
    if (anim == ANIM_JUMP) return 0.4f;
    if (anim == ANIM_FALL) return 0.8f;
    if (anim == ANIM_LANDHARD || anim == ANIM_LANDSOFT) return 0.05f;

    if (anim == ANIM_SHOOT) return 0.02f;
    if (anim == ANIM_RELOAD) return 0.5f;
    return 0.15f;
}

