{

    if (anim == ANIM_WALK_FWD_ALERT || anim == ANIM_RUN_FWD_ALERT) return AIMTYPE_TORSO;
    return AIMTYPE_HEAD;
}

static Vector3 MuzzleWorldPos(const Vector3& instPos, const Vector4& instRot,
                              const ModelData& md, float fallbackHeight)
{
    if (!md.hpWeaponsValid)
    {
        Vector3 p = instPos; p.m_Y += fallbackHeight; return p;
    }
    const Vector3 off = QuatRotateVector(instRot, md.hpWeapons.position);
    return Vector3(instPos.m_X + off.m_X, instPos.m_Y + off.m_Y, instPos.m_Z + off.m_Z);
}

static Vector3 WeaponFireWorldPos(const Vector3& instPos, const Vector4& instRot,
                                  const ModelData& bodyMd, const ModelData* weaponMd,
                                  float fallbackHeight)
{
    const Vector3 grip = MuzzleWorldPos(instPos, instRot, bodyMd, fallbackHeight);
    if (!bodyMd.hpWeaponsValid || weaponMd == nullptr || !weaponMd->hpFireValid) return grip;
    const Vector4 weaponRot = QuatMultiply(instRot, bodyMd.hpWeapons.rotation);
    const Vector3 tip = QuatRotateVector(weaponRot, weaponMd->hpFire);
    return Vector3(grip.m_X + tip.m_X, grip.m_Y + tip.m_Y, grip.m_Z + tip.m_Z);
}

static Vector4 ModelQuatFromFacingYaw(float facingYaw)
{
    const float modelYaw = facingYaw + 3.14159265f;
    const float h = modelYaw * 0.5f;
    return Vector4(0.0f, sinf(h), 0.0f, cosf(h));
}

static bool AnimLoops(CRCChecksum anim)
{

    return anim != ANIM_JUMP && anim != ANIM_LANDHARD && anim != ANIM_LANDSOFT
        && anim != ANIM_DIVE_FORWARD
        && anim != ANIM_DEATH_FORWARD && anim != ANIM_DEATH_BACKWARD
        && anim != ANIM_DEATH_LEFT && anim != ANIM_DEATH_RIGHT;
}

