static const CRCChecksum ANIM_DROIDEKA_TURNRIGHT = CRC::CalcLowerCRC("turnr");

static const CRCChecksum ANIM_DROIDEKA_WALK_R_L   = CRC::CalcLowerCRC("walk_rightfoot_leftfoot");
static const CRCChecksum ANIM_DROIDEKA_IDLE_TO_L  = CRC::CalcLowerCRC("idle_to_leftfoot");
static const CRCChecksum ANIM_DROIDEKA_L_TO_IDLE  = CRC::CalcLowerCRC("leftfoot_to_idle");
static const CRCChecksum ANIM_DROIDEKA_R_TO_IDLE  = CRC::CalcLowerCRC("rightfoot_to_idle");
static float DekaTableClipRate(CRCChecksum a)
{

    return (a == ANIM_DROIDEKA_IDLE_TO_L || a == ANIM_DROIDEKA_WALK
            || a == ANIM_DROIDEKA_WALK_R_L || a == ANIM_DROIDEKA_L_TO_IDLE || a == ANIM_DROIDEKA_R_TO_IDLE) ? kDekaTableClipRate : 1.0f;
}

static bool PlayerAnimLoops(CRCChecksum anim)
{
    if (anim == ANIM_DROIDEKA_DEATH || anim == ANIM_DROIDEKA_FOLD || anim == ANIM_DROIDEKA_UNFOLD) return false;
    if (anim == ANIM_DROIDEKA_WALK || anim == ANIM_DROIDEKA_WALK_R_L || anim == ANIM_DROIDEKA_IDLE_TO_L
        || anim == ANIM_DROIDEKA_L_TO_IDLE || anim == ANIM_DROIDEKA_R_TO_IDLE) return false;
    return AnimLoops(anim);
}

static const AnimationBank* g_soldierAnimBank2 = nullptr;

enum AnimWeaponType { AWT_RIFLE = 0, AWT_BAZOOKA, AWT_TOOL, AWT_PISTOL,
                      AWT_GRENADE, AWT_MELEE, AWT_SABRE, AWT_COUNT };

static const char* const kAnimWeaponName[AWT_COUNT] =
    { "rifle", "bazooka", "tool", "pistol", "grenade", "melee", "sabre" };

static const int kAnimWeaponParent[AWT_COUNT] =
    { -1, AWT_RIFLE, AWT_RIFLE, AWT_TOOL, AWT_TOOL, AWT_TOOL, AWT_MELEE };

static const bool kAnimWeaponHasAlert[AWT_COUNT] =
    { true, false, true, true, true, false, false };

static const char* const kAnimPostureName[AP_POSTURE_COUNT] =
    { "stand", "crouch", "prone", "standalert", "crouchalert", "pronealert" };

static const int kAnimPostureNonAlert[AP_POSTURE_COUNT] =
    { AP_STAND, AP_CROUCH, AP_PRONE, AP_STAND, AP_CROUCH, AP_PRONE };

struct ResolvedAnim
{
    CRCChecksum crc = 0;
    const AnimationBank* bank = nullptr;
    AnimScope scope = AS_FULL;
    bool loop = false;
    float blendTime = 0.15f;
    uint32_t frames = 0;
    bool valid = false;
};

static std::vector<const AnimationBank*> g_animBanks;
static const AnimationBank* g_humanSabreBank = nullptr;
static void RegisterAnimBank(const AnimationBank* b)
{
    if (b == nullptr) return;
    for (const AnimationBank* e : g_animBanks) if (e == b) return;
    g_animBanks.push_back(b);
}

static bool AnimRealLoop(AnimCategory cat, const char* anim)
{
    switch (cat)
    {
        case ACAT_WEAPON:   return false;
        case ACAT_MOVEMENT: return strncmp(anim, "turn", 4) != 0;
        case ACAT_ACTION:

            return strcmp(anim, "sprint") == 0
                || strcmp(anim, "thrown_flail") == 0
                || strcmp(anim, "thrown_tumblefront") == 0
                || strcmp(anim, "thrown_tumbleback") == 0
                || strcmp(anim, "jetpack_hover") == 0;
    }
    return false;
}

static AnimScope AnimRealDefaultScope(AnimCategory cat, int weaponType, const char* anim, const char* character)
{
    const bool isHuman = (character == nullptr) || strcmp(character, "human") == 0;
    if (cat == ACAT_WEAPON) return AS_UPPER;
    if (cat == ACAT_MOVEMENT)
    {

        if (strncmp(anim, "turn", 4) == 0) return AS_LOWER;
        return (isHuman && weaponType == AWT_RIFLE) ? AS_FULL : AS_UPPER;
    }

    return (isHuman && weaponType == AWT_RIFLE) ? AS_FULL : AS_UPPER;
}

static bool TryResolveAnimName(const std::string& base, AnimCategory cat, int weaponType,
                               const char* anim, const char* character, ResolvedAnim& out)
{
    struct { const char* suffix; AnimScope scope; bool explicitScope; } kTry[] = {
        { "_full",  AS_FULL,  true  },
        { "_upper", AS_UPPER, true  },
        { "_lower", AS_LOWER, true  },
        { "",       AS_FULL,  false },
    };
    for (const auto& t : kTry)
    {
        const std::string full = base + t.suffix;
        const CRCChecksum crc = CRC::CalcLowerCRC(full.c_str());
        for (const AnimationBank* bank : g_animBanks)
        {
            uint32_t frames = 0, bones = 0;
            if (!bank->GetAnimationMetadata(crc, frames, bones) || frames == 0) continue;
            out.crc = crc;
            out.bank = bank;
            out.frames = frames;
            out.scope = t.explicitScope ? t.scope : AnimRealDefaultScope(cat, weaponType, anim, character);
            out.valid = true;
            return true;
        }
    }
    return false;
}

static bool ResolveSoldierAnim(AnimCategory cat, const char* character, int weaponType,
                               AnimPosture posture, const char* anim, ResolvedAnim& out)
{
    out = ResolvedAnim();
    if (anim == nullptr || character == nullptr) return false;
    if (weaponType < 0 || weaponType >= AWT_COUNT) weaponType = AWT_RIFLE;

    std::string charNorm;
    if (const char* sp = strchr(character, ' '))
    {
        charNorm.assign(character, sp);
        character = charNorm.c_str();
    }

    if (posture >= AP_STANDALERT && !kAnimWeaponHasAlert[weaponType])
        posture = (AnimPosture)kAnimPostureNonAlert[posture];

    for (int wt = weaponType; wt >= 0; wt = kAnimWeaponParent[wt])
    {

        AnimPosture postureChain[3];
        int pc = 0;
        postureChain[pc++] = posture;
        if (kAnimPostureNonAlert[posture] != posture)
            postureChain[pc++] = (AnimPosture)kAnimPostureNonAlert[posture];
        if (postureChain[pc - 1] != AP_STAND) postureChain[pc++] = AP_STAND;

        for (int pi = 0; pi < pc; ++pi)
        {
            std::string base;
            if (cat == ACAT_ACTION)
            {

                base = std::string(character) + "_" + kAnimWeaponName[wt] + "_" + anim;
            }
            else
            {
                base = std::string(character) + "_" + kAnimWeaponName[wt] + "_"
                     + kAnimPostureName[postureChain[pi]] + "_" + anim;
            }
            if (TryResolveAnimName(base, cat, wt, anim, character, out))
            {
                out.loop = AnimRealLoop(cat, anim);
                out.blendTime = AnimRealBlendTime(cat, anim, posture);
                return true;
            }
            if (cat == ACAT_ACTION) break;
        }
    }

    if (cat == ACAT_WEAPON)
    {
        const std::string base = std::string(character) + "_" + kAnimWeaponName[weaponType] + "_" + anim;
        if (TryResolveAnimName(base, ACAT_ACTION, weaponType, anim, character, out))
        {
            out.loop = AnimRealLoop(cat, anim);
            out.blendTime = AnimRealBlendTime(cat, anim, posture);
            return true;
        }
    }
    return false;
}

struct LayeredAnim
{
    ResolvedAnim base;
    ResolvedAnim upper;
    bool hasUpper = false;
    bool valid = false;
};

static bool ResolveSoldierAnimLayered(AnimCategory cat, const char* character, int weaponType,
                                      AnimPosture posture, const char* anim, LayeredAnim& out)
{
    out = LayeredAnim();

    if (posture >= AP_STANDALERT && weaponType >= 0 && weaponType < AWT_COUNT && !kAnimWeaponHasAlert[weaponType])
        posture = (AnimPosture)kAnimPostureNonAlert[posture];
    ResolvedAnim r;
    if (!ResolveSoldierAnim(cat, character, weaponType, posture, anim, r)) return false;

    if (r.scope == AS_FULL)
    {
        out.base = r; out.valid = true; return true;
    }

    ResolvedAnim cover;
    bool haveCover = false;
    for (int wt = (weaponType >= 0 && weaponType < AWT_COUNT) ? kAnimWeaponParent[weaponType] : -1;
         wt >= 0; wt = kAnimWeaponParent[wt])
    {
        ResolvedAnim c;
        if (ResolveSoldierAnim(cat, character, wt, posture, anim, c) && c.scope != r.scope)
        {
            cover = c; haveCover = true; break;
        }
    }

    if (!haveCover && character != nullptr && strcmp(character, "human") != 0)
    {
        for (int wt = weaponType; wt >= 0; wt = kAnimWeaponParent[wt])
        {
            ResolvedAnim c;
            if (ResolveSoldierAnim(cat, "human", wt, posture, anim, c) && c.scope != r.scope)
            {
                cover = c; haveCover = true; break;
            }
        }
    }

    if (r.scope == AS_UPPER)
    {
        out.upper = r; out.hasUpper = true;
        if (haveCover) out.base = cover;
        else           out.base = r;
    }
    else
    {
        out.base = r;
        if (haveCover) { out.upper = cover; out.hasUpper = true; }
    }
    out.valid = true;
    return true;
}

static std::map<uint64_t, ResolvedAnim> g_animResolveCache;
static const ResolvedAnim& ResolveSoldierAnimCached(AnimCategory cat, const char* character,
    int weaponType, AnimPosture posture, const char* anim)
{
    uint64_t key = (uint64_t)CRC::CalcLowerCRC(anim);
    key = key * 131u + (uint64_t)cat;
    key = key * 131u + (uint64_t)weaponType;
    key = key * 131u + (uint64_t)posture;
    key = key * 131u + (uint64_t)CRC::CalcLowerCRC(character);
    auto it = g_animResolveCache.find(key);
    if (it != g_animResolveCache.end()) return it->second;
    ResolvedAnim r;
    ResolveSoldierAnim(cat, character, weaponType, posture, anim, r);

    if (!r.valid) { static const ResolvedAnim kNoAnim; return kNoAnim; }
    return g_animResolveCache.emplace(key, r).first->second;
}

static std::map<uint64_t, LayeredAnim> g_animLayeredCache;
static const LayeredAnim& ResolveSoldierAnimLayeredCached(AnimCategory cat, const char* character,
    int weaponType, AnimPosture posture, const char* anim)
{
    uint64_t key = (uint64_t)CRC::CalcLowerCRC(anim);
    key = key * 131u + (uint64_t)cat;
    key = key * 131u + (uint64_t)weaponType;
    key = key * 131u + (uint64_t)posture;
    key = key * 131u + (uint64_t)CRC::CalcLowerCRC(character);
    auto it = g_animLayeredCache.find(key);
    if (it != g_animLayeredCache.end()) return it->second;
    LayeredAnim r;
    ResolveSoldierAnimLayered(cat, character, weaponType, posture, anim, r);
    return g_animLayeredCache.emplace(key, r).first->second;
}

static const LayeredAnim& ResolveSoldierAnimForCharacter(AnimCategory cat, const char* characterType,
    int weaponType, AnimPosture posture, const char* anim)
{
    if (characterType != nullptr && characterType[0] != '\0')
    {
        const LayeredAnim& own = ResolveSoldierAnimLayeredCached(cat, characterType, weaponType, posture, anim);
        if (own.valid) return own;
    }
    return ResolveSoldierAnimLayeredCached(cat, "human", weaponType, posture, anim);
}

static const ResolvedAnim& ResolveWeaponAnimForCharacter(AnimCategory cat, const char* characterType,
    int weaponType, AnimPosture posture, const char* anim)
{
    if (characterType != nullptr && characterType[0] != '\0')
    {
        const ResolvedAnim& own = ResolveSoldierAnimCached(cat, characterType, weaponType, posture, anim);
        if (own.valid) return own;
    }
    return ResolveSoldierAnimCached(cat, "human", weaponType, posture, anim);
}

static const ResolvedAnim& PickSingleLayerClip(const LayeredAnim& la)
{
    if (!la.hasUpper || !la.upper.valid || la.upper.bank == nullptr) return la.base;
    if (la.base.bank == nullptr || la.upper.crc == la.base.crc) return la.base;
    uint32_t uf = 0, ub = 0, bf = 0, bb = 0;
    if (!la.upper.bank->GetAnimationMetadata(la.upper.crc, uf, ub) || uf == 0) return la.base;
    if (!la.base.bank->GetAnimationMetadata(la.base.crc, bf, bb)) return la.base;
    return (ub >= bb) ? la.upper : la.base;
}

static std::string AnimCharacterTypeForClass(const std::string& unitClass)
{
    auto it = g_unitClassSkeleton.find(unitClass);
    if (it == g_unitClassSkeleton.end()) return "";
    return it->second;
}

static int AnimWeaponTypeFromBankName(const std::string& bankName)
{
    for (int i = 0; i < AWT_COUNT; ++i)
        if (bankName == kAnimWeaponName[i]) return i;
    return AWT_RIFLE;
}

static int AnimWeaponTypeForWeapon(const WeaponStats& w)
{

    if (w.animBankDeclared)
    {
        for (int i = 0; i < AWT_COUNT; ++i)
            if (w.animBank == kAnimWeaponName[i]) return i;
    }
    for (int i = 0; i < AWT_COUNT; ++i)
        if (w.weaponClassLabel == kAnimWeaponName[i]) return i;
    return AWT_RIFLE;
}

static CRCChecksum ANIM_BZK_WALK = 0, ANIM_BZK_RUN = 0, ANIM_BZK_SHOOT = 0,
                   ANIM_BZK_RELOAD = 0, ANIM_BZK_CROUCH_WALK = 0, ANIM_BZK_CROUCH_SHOOT = 0;

static CRCChecksum ANIM_BZK_IDLE = 0, ANIM_BZK_RUN_BWD = 0,
                   ANIM_BZK_CROUCH_IDLE = 0, ANIM_BZK_CROUCH_WALK_BWD = 0;

static void LoadTwoAnimationBanksFromOneLevel(const std::string& lvlPath,
                                              const char* bankA, const char* bankB,
                                              const AnimationBank*& outA,
                                              const AnimationBank*& outB)
{
    outA = nullptr; outB = nullptr;
    if (!FileExists(lvlPath.c_str()))
    {
        logf("animation banks: \"%s\" not found - skipping \"%s\"/\"%s\"\n",
            lvlPath.c_str(), bankA, bankB);
        return;
    }
    List<String> subLvls;
    subLvls.Add(String(bankA));
    subLvls.Add(String(bankB));
    Level* extLvl = nullptr;
    try { extLvl = TimedLevelFromFile(lvlPath.c_str(), &subLvls); }
    catch (const std::exception& e)
    {
        logf("animation banks: \"%s\" threw (%s)\n", lvlPath.c_str(), e.what());
        return;
    }
    if (extLvl == nullptr)
    {
        logf("animation banks: \"%s\" returned null\n", lvlPath.c_str());
        return;
    }
    outA = extLvl->GetAnimationBank(String(bankA));
    outB = extLvl->GetAnimationBank(String(bankB));

}

static void LoadSoldierAnimationBanks()
{

    logMallinfo("before loading real droideka animation bank");

    bool dekaOnRoster = false;
    for (const TeamInfo& ti : g_teams) for (const std::string& c : ti.unitClasses) if (c == "cis_inf_droideka") dekaOnRoster = true;
    g_droidekaAnimBank = dekaOnRoster ? LoadExternalAnimationBank(CIS_LVL_PATH, "cis_walk_droideka", {"cis_inf_droideka"}) : nullptr;
    logf("MILESTONE 292: real droideka animation bank \"cis_walk_droideka\" %s\n",
         g_droidekaAnimBank != nullptr ? "loaded" : "MISSING");
    logMallinfo("after loading real droideka animation bank");

    for (const auto& kv : g_skeletonBankRequests)
    {
        const std::string& charType = kv.first;
        const SkeletonBankRequest& req = kv.second;
        if (charType.empty() || charType == "human") continue;
        const AnimationBank* bank = LoadExternalAnimationBank(req.lvlPath, charType.c_str(), req.classes);

        if (bank == nullptr && charType.find(' ') != std::string::npos)
        {
            const std::string firstWord = charType.substr(0, charType.find(' '));
            bank = LoadExternalAnimationBank(req.lvlPath, firstWord.c_str(), req.classes);
            if (bank != nullptr) logf("HEROES character bank \"%s\": loaded as \"%s\" (SkeletonName's first word)\n", charType.c_str(), firstWord.c_str());
        }
        g_characterAnimBanks[charType] = bank;
        logf("MILESTONE 309: real character bank \"%s\" %s (requested via %u real class(es) in %s)\n",
             charType.c_str(), bank != nullptr ? "loaded" : "MISSING",
             (unsigned)req.classes.size(), req.lvlPath.c_str());
    }
    LoadTwoAnimationBanksFromOneLevel(INGAME_LVL_PATH, "human_0", "human_1",
                                      g_soldierAnimBank0, g_soldierAnimBank1);

    {
        const AnimationBank* unusedB = nullptr;
        LoadTwoAnimationBanksFromOneLevel(INGAME_LVL_PATH, "human_2", "human_2",
                                          g_soldierAnimBank2, unusedB);
        ANIM_BZK_WALK         = CRC::CalcLowerCRC("human_bazooka_stand_walkforward");
        ANIM_BZK_RUN          = CRC::CalcLowerCRC("human_bazooka_stand_runforward");
        ANIM_BZK_SHOOT        = CRC::CalcLowerCRC("human_bazooka_stand_shoot_full");
        ANIM_BZK_RELOAD       = CRC::CalcLowerCRC("human_bazooka_stand_reload_full");
        ANIM_BZK_CROUCH_WALK  = CRC::CalcLowerCRC("human_bazooka_crouch_walkforward");
        ANIM_BZK_CROUCH_SHOOT = CRC::CalcLowerCRC("human_bazooka_crouch_shoot");

        ANIM_BZK_IDLE          = CRC::CalcLowerCRC("human_bazooka_stand_idle_emote");
        ANIM_BZK_RUN_BWD       = CRC::CalcLowerCRC("human_bazooka_stand_runbackward");
        ANIM_BZK_CROUCH_IDLE   = CRC::CalcLowerCRC("human_bazooka_crouch_idle_emote");
        ANIM_BZK_CROUCH_WALK_BWD = CRC::CalcLowerCRC("human_bazooka_crouch_walkbackward");
    }

    {
        const AnimationBank* bank3 = nullptr; const AnimationBank* bank4 = nullptr;
        LoadTwoAnimationBanksFromOneLevel(INGAME_LVL_PATH, "human_3", "human_4", bank3, bank4);

        {

            const AnimationBank* sabreDup = nullptr;
            for (const std::string* path : { &INGAME_LVL_PATH, &JED_LVL_PATH, &REP_LVL_PATH, &CIS_LVL_PATH, &ALL_LVL_PATH, &IMP_LVL_PATH })
            {
                LoadTwoAnimationBanksFromOneLevel(*path, "human_sabre", "human_melee",
                                                  g_humanSabreBank, sabreDup);
                if (g_humanSabreBank != nullptr) { logf("HEROES shared sabre bank from \"%s\"\n", path->c_str()); break; }
            }
            RegisterAnimBank(g_humanSabreBank);
            RegisterAnimBank(sabreDup);
            logf("HEROES shared sabre animation bank \"human_sabre\": %s\n",
                 g_humanSabreBank != nullptr ? "loaded" : "MISSING");
        }
        RegisterAnimBank(g_soldierAnimBank0);
        RegisterAnimBank(g_soldierAnimBank1);
        RegisterAnimBank(g_soldierAnimBank2);
        RegisterAnimBank(bank3);
        RegisterAnimBank(bank4);
        g_humanBank4 = bank4;
        RegisterAnimBank(g_droidekaAnimBank);

        for (const auto& kv : g_characterAnimBanks) RegisterAnimBank(kv.second);
        logf("MILESTONE 162: %u real animation bank(s) registered with the resolver\n",
             (unsigned)g_animBanks.size());

        {
            struct { AnimCategory cat; const char* anim; } kProbe[] = {
                { ACAT_MOVEMENT, "idle_emote" },   { ACAT_MOVEMENT, "walkforward" },
                { ACAT_MOVEMENT, "runforward" },   { ACAT_MOVEMENT, "walkbackward" },
                { ACAT_MOVEMENT, "runbackward" },  { ACAT_MOVEMENT, "turnleft" },
                { ACAT_WEAPON,   "shoot" },        { ACAT_WEAPON,   "reload" },

                { ACAT_WEAPON,   "shoot_secondary" },
                { ACAT_WEAPON,   "shoot_secondary2" },
                { ACAT_WEAPON,   "throw" },
                { ACAT_ACTION,   "sprint" },       { ACAT_ACTION,   "jump" },
                { ACAT_ACTION,   "fall" },         { ACAT_ACTION,   "landsoft" },
                { ACAT_ACTION,   "diveforward" },
                { ACAT_ACTION,   "stand_death_forward" },
                { ACAT_ACTION,   "stand_death_backward" },
                { ACAT_ACTION,   "stand_death_left" },
                { ACAT_ACTION,   "stand_death_right" },
            };
            const char* kScopeName[] = { "upper", "lower", "full" };
            for (int wt = 0; wt < AWT_COUNT; ++wt)
            {
                for (int pi = 0; pi < 2; ++pi)
                {
                    for (const auto& pr : kProbe)
                    {
                        const ResolvedAnim& r = ResolveSoldierAnimCached(
                            pr.cat, "human", wt, (AnimPosture)pi, pr.anim);
                        logf("M162 resolve %-8s %-6s %-22s -> %s scope=%s loop=%d blend=%.2f frames=%u\n",
                             kAnimWeaponName[wt], kAnimPostureName[pi], pr.anim,
                             r.valid ? "OK " : "MISS",
                             r.valid ? kScopeName[r.scope] : "-",
                             (int)r.loop, r.blendTime, r.frames);
                    }
                }
            }
        }

        for (const auto& bankKv : g_characterAnimBanks)
        {
            if (bankKv.second == nullptr) continue;
            const std::string& charType = bankKv.first;
            struct { AnimCategory cat; const char* anim; AnimPosture posture; } kBdroidProbe[] = {
                { ACAT_MOVEMENT, "idle_emote",   AP_STAND },
                { ACAT_MOVEMENT, "walkforward",  AP_STAND },
                { ACAT_MOVEMENT, "runforward",   AP_STAND },
                { ACAT_WEAPON,   "shoot",        AP_STAND },
                { ACAT_WEAPON,   "reload",       AP_STAND },
                { ACAT_ACTION,   "stand_death_forward", AP_STAND },
            };
            const char* kScopeName2[] = { "upper", "lower", "full" };
            for (const auto& pr : kBdroidProbe)
            {
                LayeredAnim la;
                ResolveSoldierAnimLayered(pr.cat, charType.c_str(), AWT_RIFLE, pr.posture, pr.anim, la);
                uint32_t bf = 0, bb = 0, uf = 0, ub = 0;
                if (la.valid && la.base.bank != nullptr) la.base.bank->GetAnimationMetadata(la.base.crc, bf, bb);
                if (la.hasUpper && la.upper.bank != nullptr) la.upper.bank->GetAnimationMetadata(la.upper.crc, uf, ub);
                logf("M309 probe %-10s %-22s -> valid=%d base_bank=%s base_scope=%s base_frames=%u base_bones=%u"
                     " hasUpper=%d upper_bank=%s upper_frames=%u upper_bones=%u\n",
                     charType.c_str(), pr.anim, (int)la.valid,
                     (la.valid && la.base.bank != nullptr) ? la.base.bank->GetName().Buffer() : "-",
                     la.valid ? kScopeName2[la.base.scope] : "-", bf, bb,
                     (int)la.hasUpper,
                     (la.hasUpper && la.upper.bank != nullptr) ? la.upper.bank->GetName().Buffer() : "-", uf, ub);
            }
        }
        logf("LoadSoldierAnimationBanks: MILESTONE 149 - bazooka bank %s\n",
            g_soldierAnimBank2 != nullptr ? "OK" : "MISSING");
    }
    logf("LoadSoldierAnimationBanks: bank0(walk/run/idle)=%s bank1(sprint/jump/fall)=%s\n",
        g_soldierAnimBank0 != nullptr ? "OK" : "MISSING", g_soldierAnimBank1 != nullptr ? "OK" : "MISSING");

    for (const auto& kv : g_unitClassLoadout)
    {
        const UnitLoadout& lo = kv.second;
        for (int wi : lo.slotWeapon)
        {
            if (wi < 0 || (size_t)wi >= g_weaponTable.size()) continue;
            const WeaponStats& w = g_weaponTable[(size_t)wi];
            if (!w.isMelee || w.jedi.states.empty()) continue;

            std::string ch;
            auto lit = g_unitClassAnimName.find(kv.first);
            if (lit != g_unitClassAnimName.end() && !lit->second.empty()) ch = lit->second;
            else
            {
                auto sit = g_unitClassSkeleton.find(kv.first);
                if (sit != g_unitClassSkeleton.end()) ch = sit->second;
            }
            const int wt = AnimWeaponTypeForWeapon(w);
            int total = 0, miss = 0, own = 0; std::string firstMiss;
            auto check = [&](std::string clip)
            {
                if (clip.empty()) return;
                ++total;

                for (const char* suf : { "_upper", "_lower" })
                {
                    const size_t n = strlen(suf);
                    if (clip.size() > n && clip.compare(clip.size() - n, n, suf) == 0) { clip.erase(clip.size() - n); break; }
                }

                AnimPosture posture = AP_STAND; std::string anim = clip;
                for (int p = 0; p < AP_POSTURE_COUNT; ++p)
                {
                    const size_t n = strlen(kAnimPostureName[p]);
                    if (clip.size() > n + 1 && strncmp(clip.c_str(), kAnimPostureName[p], n) == 0 && clip[n] == '_')
                    { posture = (AnimPosture)p; anim = clip.substr(n + 1); }
                }

                if (!ch.empty())
                {
                    LayeredAnim lown;
                    if (ResolveSoldierAnimLayered(ACAT_WEAPON, ch.c_str(), wt, posture, anim.c_str(), lown) && lown.valid) ++own;
                }
                const LayeredAnim& la = ResolveSoldierAnimForCharacter(ACAT_WEAPON, ch.empty() ? "human" : ch.c_str(), wt, posture, anim.c_str());
                if (!(la.valid && la.base.valid)) { ++miss; if (firstMiss.empty()) firstMiss = clip; }
            };
            for (const combo::State& st : w.jedi.states) check(st.anim);

            AnimPosture tp = AP_STAND; std::string ta = w.jedi.throwAnim;
            if (!ta.empty())
            {
                ++total;
                for (int p = 0; p < AP_POSTURE_COUNT; ++p)
                {
                    const size_t n = strlen(kAnimPostureName[p]);
                    if (ta.size() > n + 1 && strncmp(ta.c_str(), kAnimPostureName[p], n) == 0 && ta[n] == '_')
                    { tp = (AnimPosture)p; ta = ta.substr(n + 1); }
                }
                const LayeredAnim& la = ResolveSoldierAnimForCharacter(ACAT_WEAPON, ch.empty() ? "human" : ch.c_str(), wt, tp, ta.c_str());
                if (!(la.valid && la.base.valid)) { ++miss; if (firstMiss.empty()) firstMiss = "throw:" + ta; }
            }
            logf("HEROES anim coverage \"%s\" (%s): %d/%d resolved (%d from its own bank)%s%s\n",
                 kv.first.c_str(), ch.empty() ? "human" : ch.c_str(), total - miss, total, own,
                 miss ? ", FIRST MISSING " : "", miss ? firstMiss.c_str() : "");

            if (g_animProbe)
            {
                static const char* kProbe[] = { "attack1c", "attack1c_end", "attack3", "attack2", "attack1a_end", "catch", "useforce", "throw" };
                static const char* kChars[] = { "human", "mace", "vader", "maul", "yoda", "obiwan", "luke", "anakin", "dooku", "grievous" };
                for (const char* pc : kChars)
                    for (const char* pn : kProbe)
                    {
                        const LayeredAnim& pla = ResolveSoldierAnimForCharacter(ACAT_WEAPON, pc, wt, AP_STAND, pn);
                        if (pla.valid && pla.base.valid)
                            logf("ANIMPROBE \"%s\": sabre stand %s -> %08x %u frames (bank %s, %u banks loaded)\n", pc, pn,
                                 (unsigned)pla.base.crc, pla.base.frames, pla.base.bank != nullptr ? "yes" : "-",
                                 (unsigned)g_animBanks.size());
                    }
            }
        }
    }
}

static int g_playerWeaponIndex = -1;
static std::map<std::string, size_t> g_classBodyModel;

static bool g_soldierLodOn = true;
static bool g_soldierLodAll = false;
struct SoldierLowClone { size_t lowBase = (size_t)-1; ModelData md; std::vector<int> boneMap; };
static std::deque<SoldierLowClone> g_soldierLowClones;
static std::vector<int> g_soldierLowCloneOf;
static uint32_t g_soldierLowDrawn = 0, g_soldierHiDrawn = 0;

static const ModelData* SoldierLowBody(size_t pIdx, const PlacedInstance& pi, const ModelData& hiMd, const std::vector<ModelData>& uniqueModels)
{
    auto lit = g_classLowModel.find(pi.unitClass);
    if (lit == g_classLowModel.end() || lit->second >= uniqueModels.size()) return nullptr;
    const ModelData& lowBase = uniqueModels[lit->second];
    if (!lowBase.gpuSkin || !hiMd.gpuSkin || hiMd.bonePalette.empty())
    {
        static int s_n = 0;
        if (s_n++ < 6) checkpointf("M541 soldier LOD: \"%s\" kept hi - low gpuSkin %d (checked %d, animated %d, bones %u), hi gpuSkin %d palette %u\n",
                            pi.unitClass.c_str(), (int)lowBase.gpuSkin, (int)lowBase.gpuSkinChecked, (int)lowBase.isAnimated,
                            (unsigned)lowBase.bindBones.Size(), (int)hiMd.gpuSkin, (unsigned)hiMd.bonePalette.size());
        return nullptr;
    }
    if (g_soldierLowCloneOf.size() <= pIdx) g_soldierLowCloneOf.resize(pIdx + 1, -1);
    int& ci = g_soldierLowCloneOf[pIdx];
    if (ci < 0 || g_soldierLowClones[(size_t)ci].lowBase != lit->second)
    {
        SoldierLowClone c; c.lowBase = lit->second; c.md = lowBase;
        const size_t nb = lowBase.bindBones.Size();
        c.boneMap.assign(nb, -1);
        bool all = true;
        for (size_t j = 0; j < nb; ++j)
        {
            for (size_t k = 0; k < hiMd.bindBones.Size(); ++k)
                if (strcasecmp(hiMd.bindBones[k].m_BoneName.Buffer(), lowBase.bindBones[j].m_BoneName.Buffer()) == 0) { c.boneMap[j] = (int)k; break; }
            if (c.boneMap[j] < 0) all = false;
        }
        if (!all) { static std::set<std::string> s_warned; if (s_warned.insert(pi.unitClass).second) checkpointf("M541 soldier LOD: \"%s\" low body has bones the hi body lacks - kept hi\n", pi.unitClass.c_str()); return nullptr; }
        if (ci < 0) { ci = (int)g_soldierLowClones.size(); g_soldierLowClones.push_back(std::move(c)); }
        else g_soldierLowClones[(size_t)ci] = std::move(c);
    }

    {
        int missing = 0;
        for (const SegmentData& sd : lowBase.segments) if (sd.texId == 0 && sd.iCount > 0) ++missing;
        static std::set<std::string> s_told;
        if (s_told.insert(pi.unitClass).second)
            checkpointf("M541 soldier LOD: \"%s\" low body %u seg(s), %d without a texture (keep hi: %d)",
                        pi.unitClass.c_str(), (unsigned)lowBase.segments.size(), missing, (int)(missing > 0));
        if (missing > 0) return nullptr;
    }
    SoldierLowClone& c = g_soldierLowClones[(size_t)ci];
    c.md.bonePalette.resize(c.boneMap.size() * 12);
    for (size_t j = 0; j < c.boneMap.size(); ++j)
    {
        const size_t src = (size_t)c.boneMap[j] * 12;
        if (src + 12 > hiMd.bonePalette.size())
        {
            static int s_n = 0;
            if (s_n++ < 6) checkpointf("M541 soldier LOD: \"%s\" kept hi - low bone %u maps to hi bone %d, past the hi palette (%u floats, %u hi bones, %u low bones)\n",
                                pi.unitClass.c_str(), (unsigned)j, c.boneMap[j], (unsigned)hiMd.bonePalette.size(), (unsigned)hiMd.bindBones.Size(), (unsigned)c.boneMap.size());
            return nullptr;
        }
        memcpy(&c.md.bonePalette[j * 12], &hiMd.bonePalette[src], 12 * sizeof(float));
    }
    return &c.md;
}

static size_t g_missileModelIndex = (size_t)-1;

static size_t g_grenadeModelIndex = (size_t)-1;
static size_t g_weaponModelIndex = (size_t)-1;

static void LoadAnimatedSoldierModel(std::vector<ModelData>& uniqueModels, size_t& soldierModelIndex)
{
    if (g_soldierAnimBank0 == nullptr)
    {
        logf("LoadAnimatedSoldierModel: no real animation bank available - keeping the static (non-animated) model\n");
        return;
    }
    std::map<std::string, size_t> dedicatedMap;

    for (int team = 1; team <= 2; ++team)
    {
        if ((size_t)team >= g_teams.size()) continue;
        const TeamInfo* ti = &g_teams[(size_t)team];
        std::map<std::string, std::vector<std::string>> classesByFile;
        std::vector<std::string> rosterAndHero = ti->unitClasses;
        if (!ti->heroClass.empty()) rosterAndHero.push_back(ti->heroClass);
        for (const std::string& cls : rosterAndHero)
            for (const DataFileRequest& req : g_dataFileManifest)
            {
                const std::string key = NormalizeLvlKey(req.lvlFile.c_str());
                if (key.compare(0, 5, "side/") != 0) continue;
                bool listed = false;
                for (const std::string& sub : req.subResources) if (strcasecmp(sub.c_str(), cls.c_str()) == 0) listed = true;
                if (listed) { classesByFile[key].push_back(cls); break; }
            }
        for (const auto& fc : classesByFile)
        {
            const std::string fullPath = std::string(GAME_DATA_ROOT) + fc.first;
            std::vector<std::string> keepClasses, weaponGeoms;
            std::map<std::string, std::string> lowGeoms;
            {
                LibSWBF2::Types::List<LibSWBF2::Types::String> subs;
                for (const std::string& c : fc.second) subs.Add(c.c_str());
                Level* lvl = nullptr;
                try { lvl = TimedLevelFromFile(fullPath.c_str(), &subs); } catch (...) { lvl = nullptr; }
                for (const std::string& c : fc.second)
                {
                    const std::string label = ClassLabelOf(lvl, c.c_str());
                    if (!label.empty() && strcasecmp(label.c_str(), "soldier") != 0)
                    {
                        logf("M387 %s: \"%s\" skipped (ClassLabel \"%s\")\n", fc.first.c_str(), c.c_str(), label.c_str());
                        continue;
                    }
                    keepClasses.push_back(c);
                    {
                        std::string low;
                        if (GetPropertyValueInherited(lvl, c.c_str(), "GeometryLowRes", low) && !low.empty())
                        {
                            lowGeoms[c] = low;
                            if (std::find(weaponGeoms.begin(), weaponGeoms.end(), low) == weaponGeoms.end()) weaponGeoms.push_back(low);
                        }
                    }
                    auto lit = g_unitClassLoadout.find(c);
                    if (lit == g_unitClassLoadout.end()) continue;
                    for (int wi : lit->second.slotWeapon)
                    {
                        if (wi < 0 || (size_t)wi >= g_weaponTable.size() || g_weaponTable[(size_t)wi].offhandWeapon) continue;
                        auto git = g_weaponGeometry.find(g_weaponTable[(size_t)wi].name);
                        if (git == g_weaponGeometry.end() || git->second.empty()) continue;
                        if (std::find(weaponGeoms.begin(), weaponGeoms.end(), git->second) == weaponGeoms.end())
                            weaponGeoms.push_back(git->second);
                    }
                }
                ReleaseLevel(lvl);
            }
            std::vector<const char*> classPtrs, directPtrs;
            for (const std::string& c : keepClasses) classPtrs.push_back(c.c_str());
            for (const std::string& w : weaponGeoms) directPtrs.push_back(w.c_str());
            std::string joined;
            for (const std::string& c : keepClasses) joined += c + " ";
            for (const std::string& w : weaponGeoms) joined += "+" + w + " ";
            logf("M387 team %d %s: %s\n", team, fc.first.c_str(), joined.c_str());
            if (classPtrs.empty()) continue;
            LoadExternalModelsMixed(fullPath, directPtrs, classPtrs, uniqueModels, dedicatedMap,
                 true, g_soldierAnimBank0, ANIM_IDLE, 0);
            for (const auto& kv : dedicatedMap)
                if (kv.second != MODEL_LOAD_FAILED) g_classBodyModel[kv.first] = kv.second;

            for (const auto& kv : dedicatedMap)
                if (kv.second != MODEL_LOAD_FAILED && kv.second < uniqueModels.size())
                {
                    auto rsIt = g_unitClassRootScale.find(kv.first);
                    if (rsIt != g_unitClassRootScale.end()) uniqueModels[kv.second].rootScale = rsIt->second;
                }

            for (const auto& kv : dedicatedMap)
            {
                if (kv.second == MODEL_LOAD_FAILED || kv.second >= uniqueModels.size()) continue;
                const ModelData& bm = uniqueModels[kv.second];
                if (bm.isAnimated && bm.bindBones.Size() > 0)
                {
                    logf("  M590 body \"%s\": authored height %.2f m (y %.2f..%.2f), radius %.2f\n",
                         kv.first.c_str(), 2.0f * bm.boundHalfY, bm.boundMinY, bm.boundMinY + 2.0f * bm.boundHalfY, bm.boundRadius);
                    if (kv.first.find("yoda") != std::string::npos)
                    {
                        float maxY = -1e9f; size_t hi = 0;
                        for (size_t bi2 = 0; bi2 < bm.bindBones.Size(); ++bi2)
                            if (bm.bindBones[bi2].m_Position.m_Y > maxY) { maxY = bm.bindBones[bi2].m_Position.m_Y; hi = bi2; }
                        logf("  M590 YODA \"%s\": %u bind bones, root (%.2f %.2f %.2f) rootScale %.3f, top bone \"%s\" y %.2f\n",
                             kv.first.c_str(), (unsigned)bm.bindBones.Size(), bm.bindBones[0].m_Position.m_X,
                             bm.bindBones[0].m_Position.m_Y, bm.bindBones[0].m_Position.m_Z, bm.rootScale,
                             bm.bindBones[hi].m_BoneName.Buffer(), maxY);
                    }
                }
            }
            for (const auto& lg : lowGeoms)
            {
                auto it = dedicatedMap.find(lg.second);
                const bool ok = it != dedicatedMap.end() && it->second != MODEL_LOAD_FAILED && uniqueModels[it->second].isAnimated;
                if (ok)
                {
                    g_classLowModel[lg.first] = it->second;
                    auto rsIt = g_unitClassRootScale.find(lg.first);
                    if (rsIt != g_unitClassRootScale.end()) uniqueModels[it->second].rootScale = rsIt->second;
                }
                logf("M541 class \"%s\": GeometryLowRes \"%s\" %s\n", lg.first.c_str(), lg.second.c_str(), ok ? "loaded" : "NOT loaded");
            }
        }
    }
    {

        std::map<std::string, std::vector<const LocalLowBody*>> byPath;
        for (const LocalLowBody& lb : g_localLowPending) byPath[lb.path].push_back(&lb);
        for (const auto& kv : byPath)
        {
            std::vector<std::string> names; std::vector<const char*> ptrs, none;
            for (const LocalLowBody* lb : kv.second) if (std::find(names.begin(), names.end(), lb->low) == names.end()) names.push_back(lb->low);
            for (const std::string& n : names) ptrs.push_back(n.c_str());
            std::map<std::string, size_t> lowMap;
            LoadExternalModelsMixed(kv.first, ptrs, none, uniqueModels, lowMap,  false, g_soldierAnimBank0, ANIM_IDLE, 0);
            for (const LocalLowBody* lb : kv.second)
            {
                auto it = lowMap.find(lb->low);
                const bool ok = it != lowMap.end() && it->second != MODEL_LOAD_FAILED && it->second < uniqueModels.size() && uniqueModels[it->second].isAnimated;
                if (ok) g_classLowModel[lb->cls] = it->second;
                logf("LOCALSLOD class \"%s\": GeometryLowRes \"%s\" %s\n", lb->cls.c_str(), lb->low.c_str(), ok ? "loaded" : "NOT loaded");
            }
        }
        g_localLowPending.clear();
    }
    {

        std::vector<const char*> comDirect = { "com_weap_inf_torpedo", "com_weap_missile",
                                               "com_weap_inf_grenadethermal_ord",
                                               "com_weap_inf_landmine",
                                               "com_weap_inf_landmine_placed",
                                               "com_weap_inf_detpack",
                                               "com_weap_inf_grenadethermal",
                                               "com_item_powerup_dual",
                                               "com_weap_inf_dropturret",
                                               "com_weap_probedroid",
                                               "hud_rep_weap_defense_buff_icon",
                                               "hud_poison",
                                               "hud_infinite_ammo_icon",
                                               "hud_lightsaber",
                                               "hud_weapon_backdrop", "hud_weapon2_backdrop" };

        static std::vector<std::string> s_hudTagMeshes;
        s_hudTagMeshes.clear();
        for (const WeaponStats& ws : g_weaponTable)
        {
            if (!ws.modelIsIconOnly) continue;
            auto git = g_weaponGeometry.find(ws.name);
            if (git == g_weaponGeometry.end() || git->second.empty()) continue;
            std::string lower = git->second;
            for (char& ch : lower) ch = (char)tolower((unsigned char)ch);
            bool have = false;
            for (const char* c : comDirect) if (lower == c) have = true;
            for (const std::string& s : s_hudTagMeshes) if (lower == s) have = true;
            if (!have) s_hudTagMeshes.push_back(lower);
        }
        for (const std::string& s : s_hudTagMeshes) comDirect.push_back(s.c_str());
        std::vector<const char*> noClasses;
        LoadExternalModelsMixed(INGAME_LVL_PATH, comDirect, noClasses, uniqueModels, dedicatedMap,
             false, nullptr, 0, 0);
        {
            auto mit2 = dedicatedMap.find("com_weap_missile");
            if (mit2 != dedicatedMap.end() && mit2->second != MODEL_LOAD_FAILED)
            {
                g_missileModelIndex = mit2->second;
                logf("MILESTONE 150 - real missile model \"com_weap_missile\" index %u\n",
                    (unsigned)g_missileModelIndex);
            }
            auto inf2 = dedicatedMap.find("hud_infinite_ammo_icon");
            if (inf2 != dedicatedMap.end() && inf2->second != MODEL_LOAD_FAILED)
            {
                g_hudInfiniteAmmoModel = inf2->second;
                logf("MILESTONE 451 - real hud_infinite_ammo_icon model index %u\n", (unsigned)g_hudInfiniteAmmoModel);
            }
            else logf("MILESTONE 451 - hud_infinite_ammo_icon NOT loaded\n");
            for (int bi = 0; bi < 2; ++bi)
            {
                auto bd = dedicatedMap.find(bi == 0 ? "hud_weapon_backdrop" : "hud_weapon2_backdrop");
                if (bd != dedicatedMap.end() && bd->second != MODEL_LOAD_FAILED)
                {
                    g_hudWeaponBackdropModel[bi] = bd->second;

                    for (SegmentData& sd : uniqueModels[bd->second].segments)
                        for (size_t ci = 3; ci < sd.hudColors.size(); ci += 4)
                            sd.hudColors[ci] = (uint8_t)std::min(255, (int)sd.hudColors[ci] * 13 / 10);
                }
                logf("M485 %s: %s\n", bi == 0 ? "hud_weapon_backdrop" : "hud_weapon2_backdrop", g_hudWeaponBackdropModel[bi] != (size_t)-1 ? "loaded" : "NOT loaded");
            }
            auto at2 = dedicatedMap.find("com_weap_inf_dropturret");
            if (at2 != dedicatedMap.end() && at2->second != MODEL_LOAD_FAILED) g_autoturretModel = at2->second;
            auto git2 = dedicatedMap.find("com_weap_inf_grenadethermal_ord");
            if (git2 != dedicatedMap.end() && git2->second != MODEL_LOAD_FAILED)
            {
                g_grenadeModelIndex = git2->second;
                logf("MILESTONE 194 - real grenade ordnance model index %u\n",
                    (unsigned)g_grenadeModelIndex);
            }
            else logf("MILESTONE 194 - real grenade ordnance model NOT loaded\n");
        }
    }
    auto it = dedicatedMap.find(Team1PrimaryClass());
    if (it != dedicatedMap.end() && it->second != MODEL_LOAD_FAILED)
    {
        soldierModelIndex = it->second;
        logf("LoadAnimatedSoldierModel: real animated player-soldier model index = %u (isAnimated=%d)\n",
            (unsigned)soldierModelIndex, (int)uniqueModels[soldierModelIndex].isAnimated);

        (void)MaskForScope(uniqueModels[soldierModelIndex], AS_UPPER);
    }
    else
    {
        logf("LoadAnimatedSoldierModel: dedicated animated load FAILED - keeping the static (non-animated) model\n");
    }

    for (WeaponStats& ws : g_weaponTable)
    {
        auto git = g_weaponGeometry.find(ws.name);
        const bool hasGeom = (git != g_weaponGeometry.end() && !git->second.empty());
        if (!hasGeom) continue;

        auto mit = dedicatedMap.find(ws.name);
        if (mit == dedicatedMap.end() || mit->second == MODEL_LOAD_FAILED)
            mit = dedicatedMap.find(git->second);
        if (mit != dedicatedMap.end() && mit->second != MODEL_LOAD_FAILED)
        {
            ws.modelIndex = mit->second;
            logf("LoadAnimatedSoldierModel: real weapon \"%s\" -> geometry \"%s\" model index %u (halfZ %.3f radius %.3f tex \"%s\" hpFire %.3f %.3f %.3f valid %d)\n",
                ws.name.c_str(), git->second.c_str(), (unsigned)ws.modelIndex, uniqueModels[ws.modelIndex].boundHalfZ,
                uniqueModels[ws.modelIndex].boundRadius,
                uniqueModels[ws.modelIndex].segments.empty() ? "" : uniqueModels[ws.modelIndex].segments[0].texName.c_str(),
                uniqueModels[ws.modelIndex].hpFire.m_X, uniqueModels[ws.modelIndex].hpFire.m_Y, uniqueModels[ws.modelIndex].hpFire.m_Z,
                (int)uniqueModels[ws.modelIndex].hpFireValid);
        }
        else if (g_localWeaponModels.count(git->second) && g_localWeaponModels[git->second] != MODEL_LOAD_FAILED)
        {
            ws.modelIndex = g_localWeaponModels[git->second];
            logf("LoadAnimatedSoldierModel: real weapon \"%s\" -> local geometry \"%s\" model index %u\n", ws.name.c_str(), git->second.c_str(), (unsigned)ws.modelIndex);
        }
        else if (ws.modelIsIconOnly && g_hudIconMeshIndex.count(git->second))
        {
            ws.modelIndex = g_hudIconMeshIndex[git->second];
            logf("LoadAnimatedSoldierModel: real weapon \"%s\" -> side HUD mesh \"%s\" model index %u\n",
                ws.name.c_str(), git->second.c_str(), (unsigned)ws.modelIndex);
        }
        else
        {
            logf("LoadAnimatedSoldierModel: real weapon \"%s\" geometry \"%s\" NOT loaded - that unit renders unarmed\n",
                ws.name.c_str(), git->second.c_str());
        }
    }

    for (WeaponStats& ws : g_weaponTable)
    {
        auto hit = g_weaponHudMesh.find(ws.name);
        if (hit == g_weaponHudMesh.end()) continue;
        auto hmit = dedicatedMap.find(hit->second);
        auto sideIt = g_hudIconMeshIndex.find(hit->second);
        if ((hmit != dedicatedMap.end() && hmit->second != MODEL_LOAD_FAILED) || sideIt != g_hudIconMeshIndex.end())
        {
            ws.hudIconModelIndex = (sideIt != g_hudIconMeshIndex.end()) ? sideIt->second : hmit->second;
            logf("MILESTONE 321: HUD icon for \"%s\" -> mesh \"%s\" model index %u (halfZ %.3f radius %.3f)\n",
                ws.name.c_str(), hit->second.c_str(), (unsigned)ws.hudIconModelIndex,
                uniqueModels[ws.hudIconModelIndex].boundHalfZ, uniqueModels[ws.hudIconModelIndex].boundRadius);
        }
        else
            logf("MILESTONE 321: HUD icon mesh \"%s\" for \"%s\" NOT loaded - no HUD icon\n",
                hit->second.c_str(), ws.name.c_str());
    }

    for (WeaponStats& ws : g_weaponTable)
    {
        auto ogit = g_ordnanceGeometry.find(ws.name);
        if (ogit == g_ordnanceGeometry.end() || ogit->second.empty()) continue;
        auto omit = dedicatedMap.find(ogit->second);
        if (omit != dedicatedMap.end() && omit->second != MODEL_LOAD_FAILED)
        {
            ws.ordModelIndex = omit->second;
            logf("LoadAnimatedSoldierModel: real ordnance for \"%s\" -> geometry \"%s\" model index %u\n",
                ws.name.c_str(), ogit->second.c_str(), (unsigned)ws.ordModelIndex);
        }
        else
        {
            logf("LoadAnimatedSoldierModel: real ordnance for \"%s\" geometry \"%s\" NOT loaded - falls back to the shared grenade/missile mesh\n",
                ws.name.c_str(), ogit->second.c_str());
        }
    }

    auto wit = dedicatedMap.find("rep_weap_inf_rifle");
    if (wit != dedicatedMap.end() && wit->second != MODEL_LOAD_FAILED)
    {
        g_weaponModelIndex = wit->second;
        logf("LoadAnimatedSoldierModel: real rifle model index = %u\n", (unsigned)g_weaponModelIndex);
    }
    else
    {
        logf("LoadAnimatedSoldierModel: real rifle model load FAILED - player will render with no weapon\n");
    }
}

enum AIPose
{
    AIPOSE_IDLE = 0,
    AIPOSE_WALK,
    AIPOSE_RUN,
    AIPOSE_SHOOT,
    AIPOSE_CROUCH,
    AIPOSE_DEATH,
    AIPOSE_THROWN,
    AIPOSE_THROW,
    AIPOSE_HOVER,
    AIPOSE_COUNT
};

struct AIPoseSelector { AnimCategory cat; const char* name; AnimPosture posture; };
static AIPoseSelector AIPoseSelectorFor(int pose)
{
    switch (pose)
    {
        case AIPOSE_WALK:   return { ACAT_MOVEMENT, "walkforward",         AP_STAND  };
        case AIPOSE_RUN:    return { ACAT_MOVEMENT, "runforward",          AP_STAND  };
        case AIPOSE_SHOOT:  return { ACAT_WEAPON,   "shoot",               AP_STAND  };
        case AIPOSE_CROUCH: return { ACAT_MOVEMENT, "idle_emote",          AP_CROUCH };
        case AIPOSE_DEATH:  return { ACAT_ACTION,   "stand_death_forward", AP_STAND  };
        case AIPOSE_THROWN: return { ACAT_ACTION,   "thrown_flail",        AP_STAND  };

        case AIPOSE_THROW:  return { ACAT_WEAPON,   "shoot_secondary2",    AP_STAND  };
        case AIPOSE_HOVER:  return { ACAT_ACTION,   "jetpack_hover",       AP_STAND  };
        default:            return { ACAT_MOVEMENT, "idle_emote",          AP_STAND  };
    }
}

static CRCChecksum AIPoseAnim(int pose)
{
    switch (pose)
    {
        case AIPOSE_WALK:   return ANIM_WALK_FWD;
        case AIPOSE_RUN:    return ANIM_RUN_FWD;
        case AIPOSE_SHOOT:  return ANIM_SHOOT;
        case AIPOSE_CROUCH: return ANIM_CROUCH_IDLE;

        case AIPOSE_DEATH:  return ANIM_DEATH_FORWARD;

        case AIPOSE_THROWN: return ANIM_FALL;
        case AIPOSE_THROW:  return ANIM_SHOOT;
        case AIPOSE_HOVER:  return ANIM_FALL;
        default:            return ANIM_IDLE;
    }
}

static CRCChecksum DroidekaPoseAnim(int pose)
{
    switch (pose)
    {
        case AIPOSE_WALK:  return ANIM_DROIDEKA_WALK;

        case AIPOSE_RUN:   return ANIM_DROIDEKA_ROLL;
        case AIPOSE_DEATH: return ANIM_DROIDEKA_DEATH;
        default:           return ANIM_DROIDEKA_IDLE;
    }
}

static std::map<size_t, std::array<size_t, AIPOSE_COUNT>> g_aiPoseVariants;

static std::set<size_t> g_bazookaBodyModels;

struct AIAnimSlot
{
    size_t modelIndex = (size_t)-1;
    size_t ownerAiIdx = (size_t)-1;
    List<Bone> blendState;
    CRCChecksum lastAnim = 0;
    float blendWeight = 1.0f;
    float clock = 0.0f;
};

static const size_t AI_ANIM_SLOTS_PER_MODEL = 8;
static std::map<size_t, std::vector<AIAnimSlot>> g_aiAnimSlots;

static void BuildAIPoseVariants(std::vector<ModelData>& uniqueModels,
                                std::vector<PlacedInstance>& placedRef,
                                size_t soldierModelIndex)
{
    g_aiPoseVariants.clear();
    if (g_soldierAnimBank0 == nullptr)
    {
        logf("BuildAIPoseVariants: no real animation bank - AI keep the M65 shared pose\n");
        return;
    }

    std::map<size_t, uint32_t> instancesPerModel;
    for (const PlacedInstance& pi : placedRef)
    {
        if (!pi.isSoldier) continue;
        if (pi.modelIndex >= uniqueModels.size()) continue;
        if (pi.modelIndex == soldierModelIndex) continue;
        if (!uniqueModels[pi.modelIndex].isAnimated) continue;
        instancesPerModel[pi.modelIndex]++;
    }

    const uint32_t MIN_INSTANCES_FOR_VARIANTS = 1;
    std::set<size_t> bases;
    for (const auto& kv : instancesPerModel)
    {
        if (kv.second >= MIN_INSTANCES_FOR_VARIANTS) bases.insert(kv.first);
        else logf("BuildAIPoseVariants: model %u has only %u unit(s) - keeping the single shared pose\n",
                  (unsigned)kv.first, (unsigned)kv.second);
    }
    uint32_t made = 0;
    logMallinfo("before BuildAIPoseVariants clone loop");
    for (size_t base : bases)
    {
        std::array<size_t, AIPOSE_COUNT> variants;

        bool isDroidekaBase = false;

        std::string baseCharacterType;
        bool isLocalsBase = false;
        for (const PlacedInstance& pi : placedRef)
            if (pi.modelIndex == base && pi.team >= 1 && !IsCapturingTeam(pi.team)) { isLocalsBase = true; break; }
        for (const PlacedInstance& pi : placedRef)
        {
            if (pi.modelIndex != base) continue;
            if (g_droidekaAnimBank != nullptr && pi.isDroideka) { isDroidekaBase = true; break; }
            if (!pi.animCharacterType.empty()) { baseCharacterType = pi.animCharacterType; break; }
        }

        for (int pose = 0; pose < AIPOSE_COUNT; ++pose)
        {
            if (pose == AIPOSE_HOVER && !isLocalsBase) { variants[pose] = base; continue; }
            if (isDroidekaBase)
            {
                variants[pose] = base;
                continue;
            }

            const AIPoseSelector sel = AIPoseSelectorFor(pose);
            int aiWeaponType = (g_bazookaBodyModels.count(base) != 0) ? AWT_BAZOOKA : AWT_RIFLE;

            CRCChecksum crc = AIPoseAnim(pose);
            const AnimationBank* poseBank = g_soldierAnimBank0;
            {

                const LayeredAnim& la = ResolveSoldierAnimForCharacter(
                    sel.cat, baseCharacterType.empty() ? nullptr : baseCharacterType.c_str(),
                    aiWeaponType, sel.posture, sel.name);

                const ResolvedAnim& vClip = (sel.cat == ACAT_WEAPON) ? PickSingleLayerClip(la) : la.base;
                if (la.valid && vClip.valid && vClip.bank != nullptr)
                {
                    crc = vClip.crc;
                    poseBank = vClip.bank;
                }
            }
            uint32_t frames = 0, bones = 0;
            if (!poseBank->GetAnimationMetadata(crc, frames, bones) || frames == 0)
            {
                variants[pose] = base;
                continue;
            }
            ModelData clone = uniqueModels[base];
            clone.textureShareBase = base;
            clone.isAnimated = true;
            clone.animBank = poseBank;
            clone.animCRC = crc;
            clone.animFrameCount = frames;
            clone.animLoopsFlag = AnimLoops(crc);
            clone.animLocalClock = 0.0f;
            clone.lastSkinnedFrame = 0xFFFF;
            variants[pose] = uniqueModels.size();
            uniqueModels.push_back(clone);

            {
                BoneWorldTransform hpX; bool hpFound = false;
                ModelData& justAdded = uniqueModels.back();
                UpdateAnimatedModel(justAdded, 0, HP_WEAPONS_BONE_CRC, &hpX, &hpFound);
                if (hpFound) { justAdded.hpWeapons = hpX; justAdded.hpWeaponsValid = true; }
                justAdded.lastSkinnedFrame = 0;
            }
            made++;
        }

        logf("  pose variants for model %u: idle=%u walk=%u run=%u shoot=%u crouch=%u death=%u%s\n",
            (unsigned)base,
            (unsigned)variants[AIPOSE_IDLE],  (unsigned)variants[AIPOSE_WALK],
            (unsigned)variants[AIPOSE_RUN],   (unsigned)variants[AIPOSE_SHOOT],
            (unsigned)variants[AIPOSE_CROUCH],(unsigned)variants[AIPOSE_DEATH],
            (variants[AIPOSE_DEATH] == base) ? "   <<< DEATH FELL BACK TO THE BASE WALK POSE" : "");
        g_aiPoseVariants[base] = variants;

        {
            std::vector<AIAnimSlot> slots;
            for (size_t sl = 0; sl < AI_ANIM_SLOTS_PER_MODEL; ++sl)
            {
                ModelData slotClone = uniqueModels[base];
                slotClone.textureShareBase = base;
                slotClone.isAnimated = true;
                slotClone.animBank = g_soldierAnimBank0;
                slotClone.animCRC = AIPoseAnim(AIPOSE_IDLE);
                uint32_t f0 = 0, b0 = 0;
                g_soldierAnimBank0->GetAnimationMetadata(slotClone.animCRC, f0, b0);
                slotClone.animFrameCount = (f0 > 0) ? f0 : 1;
                slotClone.animLoopsFlag = true;
                slotClone.isNearBlendSlot = true;
                slotClone.lastSkinnedFrame = 0xFFFF;
                AIAnimSlot slot;
                slot.modelIndex = uniqueModels.size();
                uniqueModels.push_back(slotClone);
                {
                    BoneWorldTransform hpX; bool hpFound = false;
                    ModelData& justAdded = uniqueModels.back();
                    UpdateAnimatedModel(justAdded, 0, HP_WEAPONS_BONE_CRC, &hpX, &hpFound);
                    if (hpFound) { justAdded.hpWeapons = hpX; justAdded.hpWeaponsValid = true; }
                    justAdded.lastSkinnedFrame = 0;
                }
                slots.push_back(std::move(slot));
                made++;
            }
            g_aiAnimSlots[base] = std::move(slots);
        }
    }
    logf("BuildAIPoseVariants: MILESTONE 112 - %u real pose variant(s) across %u AI soldier model(s)\n",
        made, (unsigned)bases.size());
}

static void ActivateAIUnitWalkAnimation(std::vector<ModelData>& uniqueModels, const std::vector<PlacedInstance>& placedRef, size_t soldierModelIndex)
{
    if (g_soldierAnimBank0 == nullptr)
    {
        logf("ActivateAIUnitWalkAnimation: no real animation bank available - AI units stay static\n");
        return;
    }
    uint32_t numFrames = 0, numBones = 0;
    if (!g_soldierAnimBank0->GetAnimationMetadata(ANIM_WALK_FWD, numFrames, numBones) || numFrames == 0)
    {
        logf("ActivateAIUnitWalkAnimation: real walk-cycle metadata lookup failed - AI units stay static\n");
        return;
    }

    std::set<size_t> done;
    for (const PlacedInstance& pi : placedRef)
    {
        if (!pi.isSoldier) continue;
        if (pi.modelIndex >= uniqueModels.size()) continue;
        if (pi.modelIndex == soldierModelIndex) continue;
        if (done.count(pi.modelIndex) != 0) continue;
        done.insert(pi.modelIndex);

        ModelData& md = uniqueModels[pi.modelIndex];
        if (md.isAnimated) continue;
        if (md.bindBones.Size() == 0) continue;

        md.isAnimated = true;
        md.animBank = g_soldierAnimBank0;
        md.animCRC = ANIM_WALK_FWD;
        md.animFrameCount = numFrames;
    }
    logf("ActivateAIUnitWalkAnimation: real walk-cycle activated on %u distinct AI unit model(s)\n", (unsigned)done.size());
}

static void ResolveSoldierClassProperties()
{
    if (!FileExists(INGAME_LVL_PATH.c_str())) return;
    List<String> subLvls;
    subLvls.Add(String("com_inf_default"));
    Level* lvl = nullptr;
    try { lvl = TimedLevelFromFile(INGAME_LVL_PATH.c_str(), &subLvls); }
    catch (const std::exception& e)
    {
        logf("ResolveSoldierClassProperties: Level::FromFile threw: %s - using real fallback values\n", e.what());
        return;
    }
    if (lvl == nullptr)
    {
        logf("ResolveSoldierClassProperties: Level::FromFile returned null - using real fallback values\n");
        return;
    }
    const EntityClass* ec = lvl->GetEntityClass(String("com_inf_default"));
    if (ec != nullptr)
    {
        String v;
        if (ec->GetProperty(String("MaxHealth"), v)) g_soldierMaxHealth = (float)atof(v.Buffer());
        if (ec->GetProperty(String("MaxSpeed"), v)) g_soldierMaxSpeed = (float)atof(v.Buffer());
        if (ec->GetProperty(String("MaxStrafeSpeed"), v)) g_soldierMaxStrafeSpeed = (float)atof(v.Buffer());
        if (ec->GetProperty(String("JumpForwardSpeedFactor"), v)) g_soldierJumpForwardSpeedFactor = (float)atof(v.Buffer());
        if (ec->GetProperty(String("JumpStrafeSpeedFactor"), v))  g_soldierJumpStrafeSpeedFactor = (float)atof(v.Buffer());
        if (ec->GetProperty(String("MaxTurnSpeed"), v)) g_soldierMaxTurnSpeed = (float)atof(v.Buffer());
        if (ec->GetProperty(String("Acceleration"), v)) g_soldierAcceleration = (float)atof(v.Buffer());
        if (ec->GetProperty(String("JumpHeight"), v)) g_soldierJumpHeight = (float)atof(v.Buffer());
        if (ec->GetProperty(String("SprintAccelerateTime"), v)) g_soldierSprintAccelerateTime = (float)atof(v.Buffer());
        if (ec->GetProperty(String("EnergyBar"), v)) g_soldierEnergyBar = (float)atof(v.Buffer());
        if (ec->GetProperty(String("EnergyRestore"), v)) g_soldierEnergyRestore = (float)atof(v.Buffer());
        if (ec->GetProperty(String("EnergyRestoreIdle"), v)) g_soldierEnergyRestoreIdle = (float)atof(v.Buffer());
        if (ec->GetProperty(String("EnergyDrainSprint"), v)) g_soldierEnergyDrainSprint = (float)atof(v.Buffer());
        if (ec->GetProperty(String("EnergyMinSprint"), v)) g_soldierEnergyMinSprint = (float)atof(v.Buffer());
        if (ec->GetProperty(String("EnergyCostRoll"), v)) g_soldierEnergyCostRoll = (float)atof(v.Buffer());
        if (ec->GetProperty(String("RollSpeedFactor"), v)) g_soldierRollSpeedFactor = (float)atof(v.Buffer());
        if (ec->GetProperty(String("EnergyCostJump"), v)) g_soldierEnergyCostJump = (float)atof(v.Buffer());

        List<String> csRows;
        if (ec->GetProperty(String("ControlSpeed"), csRows) && csRows.Size() > 0)
        {
            std::vector<ControlSpeedRow> parsed;
            for (size_t i = 0; i < csRows.Size(); ++i)
            {
                char nameBuf[64];
                float t = 0.0f, s = 0.0f, tu = 0.0f;
                if (sscanf(csRows[i].Buffer(), "%63s %f %f %f", nameBuf, &t, &s, &tu) == 4)
                {
                    parsed.push_back({ std::string(nameBuf), t, s, tu });
                }
            }
            if (!parsed.empty()) g_soldierControlSpeed = parsed;
        }

        logf("ResolveSoldierClassProperties: real MaxHealth=%.1f MaxSpeed=%.2f MaxStrafeSpeed=%.2f MaxTurnSpeed=%.2f Acceleration=%.1f JumpHeight=%.2f EnergyBar=%.1f (from ingame.lvl's real com_inf_default EntityClass, %u real ControlSpeed row(s))\n",
            g_soldierMaxHealth, g_soldierMaxSpeed, g_soldierMaxStrafeSpeed, g_soldierMaxTurnSpeed, g_soldierAcceleration, g_soldierJumpHeight, g_soldierEnergyBar, (unsigned)g_soldierControlSpeed.size());
    }
    else
    {
        logf("ResolveSoldierClassProperties: com_inf_default EntityClass not found - using real fallback values\n");
    }
    ReleaseLevel(lvl);
}

static const uint8_t* g_hudBarPixels = nullptr;

static std::vector<std::string> g_texDumpNames;
static bool g_texDumpOn = false;
static std::map<std::string, GLuint> g_lvlTex;
static std::string g_lvlTexRepeatName;
static void GrabLvlTexture(const Level* lvl, const char* name)
{
    if (lvl == nullptr || g_lvlTexPixels.count(name)) return;
    const Texture* t = lvl->GetTexture(String(name));
    const uint8_t* px = nullptr; uint16_t w = 0, h = 0;
    if (t == nullptr || !t->GetImageData(ETextureFormat::R8_G8_B8_A8, 0, w, h, px) || px == nullptr) return;
    LvlTexPixels& e = g_lvlTexPixels[name];
    e.w = w; e.h = h; e.px.assign(px, px + (size_t)w * h * 4);
}
static void UploadLvlTextures()
{
    for (auto& kv : g_lvlTexPixels)
    {
        GLuint id = 0;
        glGenTextures(1, &id);
        glBindTexture(GL_TEXTURE_2D, id);

        const bool water = kv.first.find("water") != std::string::npos;
        const bool repeat = water || (!g_lvlTexRepeatName.empty() && kv.first == g_lvlTexRepeatName);
        const bool mips = repeat && (kv.second.w >= 128 || kv.second.h >= 128);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, mips ? GL_LINEAR_MIPMAP_LINEAR : GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, repeat ? GL_REPEAT : GL_CLAMP_TO_EDGE);
        glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, repeat ? GL_REPEAT : GL_CLAMP_TO_EDGE);
        glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, kv.second.w, kv.second.h, 0, GL_RGBA, GL_UNSIGNED_BYTE, kv.second.px.data());
        if (mips) glGenerateMipmap(GL_TEXTURE_2D);

        if (g_texDumpOn || getenv("SWBF2_TEXDUMP") != nullptr)
        {
            mkdir("texdump", 0777);
            for (const std::string& want : g_texDumpNames)
            {
                if (want != kv.first) continue;
                std::string path = "texdump/" + kv.first + ".ppm";
                FILE* pf = fopen(path.c_str(), "wb");
                if (pf == nullptr) break;
                fprintf(pf, "P6\n%u %u\n255\n", (unsigned)kv.second.w, (unsigned)kv.second.h);
                const size_t n = (size_t)kv.second.w * kv.second.h;
                double mr = 0.0, mg = 0.0, mb = 0.0;
                for (size_t i = 0; i < n; ++i)
                {
                    const uint8_t* s = &kv.second.px[i * 4];
                    fwrite(s, 1, 3, pf);
                    mr += s[0]; mg += s[1]; mb += s[2];
                }
                fclose(pf);
                checkpointf("TEXDUMP %s %ux%u mean %.1f %.1f %.1f (%.3f %.3f %.3f)", kv.first.c_str(),
                            (unsigned)kv.second.w, (unsigned)kv.second.h, mr / (double)n, mg / (double)n, mb / (double)n,
                            mr / (double)n / 255.0, mg / (double)n / 255.0, mb / (double)n / 255.0);
                break;
            }
        }
        g_lvlTex[kv.first] = id;
    }
    checkpointf("MILESTONE 454 - %u game textures uploaded from the .lvl files", (unsigned)g_lvlTex.size());
    g_lvlTexPixels.clear();
}
static GLuint LvlTex(const char* name)
{
    auto it = g_lvlTex.find(name);
    return (it != g_lvlTex.end()) ? it->second : 0;
}

static float FxRand() { return (float)rand() / (float)RAND_MAX; }
