    FxRange startRot, rotVel; float fadeIn = 0.0f;
    float life = 1.0f; std::vector<FxKey> posKeys, sizeKeys, colKeys;
    bool additive = false; int type = 0;
    bool flat = false;
    std::string texName; GLuint tex = 0; bool texLooked = false; float sparkLen = 0.5f;
    bool rideAlong = false;
