struct FxTxtNode;
struct FxTxtStr { std::string s; const char* Buffer() const { return s.c_str(); } };
struct FxTxtList { std::vector<const FxTxtNode*> v; size_t Size() const { return v.size(); } const FxTxtNode* operator[](size_t i) const { return v[i]; } };
struct FxTxtScope { std::vector<FxTxtNode> kids; FxTxtList GetFields(uint32_t h) const; };
struct FxTxtNode
{
    uint32_t h = 0; std::vector<std::string> vals; FxTxtScope m_Scope;
    uint8_t GetNumValues() const { return (uint8_t)std::min<size_t>(vals.size(), 255); }
    float GetFloat(uint8_t i) const { return i < vals.size() ? (float)atof(vals[i].c_str()) : 0.0f; }
    FxTxtStr GetString(uint8_t i) const { return FxTxtStr{ i < vals.size() ? vals[i] : std::string() }; }
};
FxTxtList FxTxtScope::GetFields(uint32_t h) const { FxTxtList l; for (const FxTxtNode& k : kids) if (k.h == h) l.v.push_back(&k); return l; }

static bool FxTxtParseBlock(const std::string& t, size_t& i, std::vector<FxTxtNode>& out, int depth)
{
    auto skipWs = [&]() {
        for (;;)
        {
            while (i < t.size() && isspace((unsigned char)t[i])) ++i;
            if (i + 1 < t.size() && t[i] == '/' && t[i + 1] == '/') { while (i < t.size() && t[i] != '\n') ++i; continue; }
            break;
        }
    };
    for (;;)
    {
        skipWs();
        if (i >= t.size()) return depth == 0;
        if (t[i] == '}') { ++i; return depth > 0; }
        size_t n0 = i;
        while (i < t.size() && (isalnum((unsigned char)t[i]) || t[i] == '_')) ++i;
        if (i == n0) { ++i; continue; }
        FxTxtNode node; node.h = LibSWBF2::FNV::Hash(String(t.substr(n0, i - n0).c_str()));
        skipWs();
        if (i < t.size() && t[i] == '(')
        {
            ++i; std::string cur; bool inStr = false, had = false;
            for (; i < t.size(); ++i)
            {
                const char c = t[i];
                if (inStr) { if (c == '"') { inStr = false; } else cur += c; continue; }
                if (c == '"') { inStr = true; had = true; continue; }
                if (c == ',' || c == ')')
                {
                    while (!cur.empty() && isspace((unsigned char)cur.back())) cur.pop_back();
                    size_t b = 0; while (b < cur.size() && isspace((unsigned char)cur[b])) ++b;
                    if (had || b < cur.size()) node.vals.push_back(cur.substr(b));
                    cur.clear(); had = false;
                    if (c == ')') { ++i; break; }
                    continue;
                }
                cur += c;
            }
        }
        skipWs();
        if (i < t.size() && t[i] == ';') ++i;
        skipWs();
        if (i < t.size() && t[i] == '{') { ++i; if (!FxTxtParseBlock(t, i, node.m_Scope.kids, depth + 1)) return false; }
        out.push_back(std::move(node));
    }
}
static const FxTxtNode* FxF(const FxTxtScope& s, uint32_t h) { for (const FxTxtNode& k : s.kids) if (k.h == h) return &k; return nullptr; }
static const Field* FxF(const LibSWBF2::Wrappers::Scope& s, uint32_t h)
{
    List<const Field*> f = s.GetFields(h);
    return f.Size() > 0 ? f[0] : nullptr;
}

static const Field* FxLast(const LibSWBF2::Wrappers::Scope& s, uint32_t h)
{
    List<const Field*> f = s.GetFields(h);
    return f.Size() > 0 ? f[f.Size() - 1] : nullptr;
}
template <class N> static FxRange FxR2(const N* f, FxRange def = FxRange())
{
    if (f == nullptr) return def;
    FxRange r; r.lo = f->GetFloat(0); r.hi = (f->GetNumValues() > 1) ? f->GetFloat(1) : r.lo; return r;
}
template <class N> static FxRange FxR3(const N* f, FxRange def = FxRange())
{
    if (f == nullptr || f->GetNumValues() < 3) return def;
    FxRange r; r.lo = f->GetFloat(1); r.hi = f->GetFloat(2); return r;
}
template <class N> static float FxF1(const N* f, float def) { return (f != nullptr && f->GetNumValues() > 0) ? f->GetFloat(0) : def; }
template <class N> static void FxKeys(const N* first, std::vector<FxKey>& out)
{
    for (const N* k = first; k != nullptr && out.size() < 16; )
    {
        const auto& s = k->m_Scope;
        FxKey key; key.life = FxF1(FxF(s, FxH::LifeTime), 0.0f);
        const N* f = nullptr;
        if ((f = FxF(s, FxH::Scale)) != nullptr)           { key.kind = 1; key.v[0] = FxF1(f, 1.0f); }
        else if ((f = FxF(s, FxH::Move)) != nullptr)       { key.kind = 2; for (int i = 0; i < 4 && i < f->GetNumValues(); ++i) key.v[i] = f->GetFloat((uint8_t)i); }
        else if ((f = FxF(s, FxH::Reach)) != nullptr)      { key.kind = 3; for (int i = 0; i < 4 && i < f->GetNumValues(); ++i) key.v[i] = f->GetFloat((uint8_t)i); }
        else if ((f = FxF(s, FxH::Accelerate)) != nullptr) { key.kind = 4; for (int i = 0; i < 3 && i < f->GetNumValues(); ++i) key.v[i] = f->GetFloat((uint8_t)i); }
        out.push_back(key);
        k = FxF(s, FxH::Next);
    }
}

template <class N> static void FxParseEmitter(const N& em, FxEmitterDef& d, const Level* lvl);
template <class L> static void FxParseEmitterList(const L& fields, std::vector<FxEmitterDef>& out, const Level* lvl)
{
    for (size_t i = 0; i < fields.Size() && out.size() < 16; ++i)
    {
        out.emplace_back();
        FxParseEmitter(*fields[i], out.back(), lvl);
        FxParseEmitterList(fields[i]->m_Scope.GetFields(FxH::ParticleEmitter), out, lvl);
    }
}
template <class N> static void FxParseEmitter(const N& em, FxEmitterDef& d, const Level* lvl)
{
    const auto& s = em.m_Scope;
    d.maxParticles = FxR2(FxF(s, FxH::MaxParticles), d.maxParticles);
    d.startDelay = FxR2(FxF(s, FxH::StartDelay));
    d.burstDelay = FxR2(FxF(s, FxH::BurstDelay));
    d.burstCount = FxR2(FxF(s, FxH::BurstCount), d.burstCount);
    d.maxLod = FxF1(FxF(s, FxH::MaxLodDist), 1e9f);
    d.rideAlong = FxF(s, FxH::NoRegisterStep) != nullptr;
    d.minLod = FxF1(FxF(s, FxH::MinLodDist), 0.0f);
    d.gSize = FxR2(FxF(s, FxH::Size), FxRange{ 1, 1 }).lo;
    d.gAlpha = FxR2(FxF(s, FxH::Alpha), FxRange{ 255, 255 }).lo / 255.0f;
    if (const auto* sp = FxF(s, FxH::Spawner))
    {
        const auto& ss = sp->m_Scope;
        const auto* shape = FxF(ss, FxH::Circle);
        if (shape == nullptr) { shape = FxF(ss, FxH::Spread); d.spread = (shape != nullptr); }
        if (shape) { d.px = FxR2(FxF(shape->m_Scope, FxH::PositionX)); d.py = FxR2(FxF(shape->m_Scope, FxH::PositionY)); d.pz = FxR2(FxF(shape->m_Scope, FxH::PositionZ)); }
        if (const auto* off = FxF(ss, FxH::Offset))
        { d.ox = FxR2(FxF(off->m_Scope, FxH::PositionX)); d.oy = FxR2(FxF(off->m_Scope, FxH::PositionY)); d.oz = FxR2(FxF(off->m_Scope, FxH::PositionZ)); }
        d.posScale = FxR2(FxF(ss, FxH::PositionScale), d.posScale);
        d.velScale = FxR2(FxF(ss, FxH::VelocityScale));
        d.inheritVel = FxR2(FxF(ss, FxH::InheritVelocityFactor));
        d.size = FxR3(FxF(ss, FxH::Size), d.size);
        if (FxF(ss, FxH::Hue) != nullptr) { d.hsv = true; d.c0 = FxR3(FxF(ss, FxH::Hue), d.c0); d.c1 = FxR3(FxF(ss, FxH::Saturation), d.c1); d.c2 = FxR3(FxF(ss, FxH::Value), d.c2); }
        else { d.c0 = FxR3(FxF(ss, FxH::Red), d.c0); d.c1 = FxR3(FxF(ss, FxH::Green), d.c1); d.c2 = FxR3(FxF(ss, FxH::Blue), d.c2); }
        d.alpha = FxR3(FxF(ss, FxH::Alpha), d.alpha);
        d.startRot = FxR3(FxF(ss, FxH::StartRotation));
        d.rotVel = FxR3(FxF(ss, FxH::RotationVelocity));
        d.fadeIn = FxF1(FxF(ss, FxH::FadeInTime), 0.0f);
    }
    if (const auto* tr = FxF(s, FxH::Transformer))
    {
        const auto& ts = tr->m_Scope;
        d.life = fmaxf(0.01f, FxF1(FxF(ts, FxH::LifeTime), 1.0f));
        FxKeys(FxF(ts, FxH::Position), d.posKeys);
        FxKeys(FxF(ts, FxH::Size), d.sizeKeys);
        FxKeys(FxF(ts, FxH::Color), d.colKeys);
    }
    if (const auto* ge = FxF(s, FxH::Geometry))
    {
        const auto& gs = ge->m_Scope;
        if (const auto* bm = FxF(gs, FxH::BlendMode)) d.additive = (strcasecmp(bm->GetString(0).Buffer(), "ADDITIVE") == 0);
        if (FxF(gs, FxH::BlendMode) != nullptr && strcasecmp(FxF(gs, FxH::BlendMode)->GetString(0).Buffer(), "BLUR") == 0)
            d.blur = FxF1(FxF(gs, (uint32_t)LibSWBF2::FNV::Hash(String("BlurValue"))), 0.1f);
        std::string ty = "PARTICLE";
        if (const auto* t = FxF(gs, FxH::Type)) ty = t->GetString(0).Buffer();
        if (strcasecmp(ty.c_str(), "EMITTER") == 0) d.type = 1;
        else if (strcasecmp(ty.c_str(), "SPARK") == 0 || strcasecmp(ty.c_str(), "STREAK") == 0) d.type = 2;
        else if (strcasecmp(ty.c_str(), "PARTICLE") == 0 || strcasecmp(ty.c_str(), "BILLBOARD") == 0 || strcasecmp(ty.c_str(), "ANIMATED") == 0) d.type = 0;
        else d.type = 3;
        d.flat = (strcasecmp(ty.c_str(), "BILLBOARD") == 0);
        if (const auto* tx = FxF(gs, FxH::Texture)) { d.texName = tx->GetString(0).Buffer(); if (!d.texName.empty()) GrabLvlTexture(lvl, d.texName.c_str()); }
        if (strcasecmp(ty.c_str(), "ANIMATED") == 0)
        {
            const float fs = FxF1(FxF(gs, FxH::FrameSize), 0.0f);
            d.animFrames = (int)FxF1(FxF(gs, FxH::TotalFrames), 0.0f);
            d.animFrameTime = fmaxf(0.001f, FxF1(FxF(gs, FxH::TimePerFrame), 0.05f));
            d.animLoop = FxF1(FxF(gs, FxH::Looping), 0.0f) != 0.0f;
            auto px = g_lvlTexPixels.find(d.texName);
            if (fs >= 1.0f && px != g_lvlTexPixels.end() && px->second.w > 0 && px->second.h > 0)
            {
                d.animCols = std::max(1, (int)(px->second.w / fs));
                d.animRows = std::max(1, (int)(px->second.h / fs));
            }
            else d.animFrames = 0;
        }
        d.sparkLen = FxF1(FxF(gs, FxH::SparkLength), 0.5f);
        FxParseEmitterList(gs.GetFields(FxH::ParticleEmitter), d.children, lvl);
    }
}

static void LoadEffectDefs(const Level* lvl, const char* what)
{
    if (lvl == nullptr) return;
    const List<const Config*> cfgs = lvl->GetConfigs(EConfigType::Effect);
    uint32_t n = 0;
    for (size_t c = 0; c < cfgs.Size(); ++c)
    {
        FxDef def;
        FxParseEmitterList(cfgs[c]->GetFields(FxH::ParticleEmitter), def.emitters, lvl);
        if (!def.emitters.empty()) { g_fxDefs[cfgs[c]->m_Name] = std::move(def); ++n; }
    }
    checkpointf("M461 effects: %u of %u Effect configs parsed from %s", n, (unsigned)cfgs.Size(), what);
}

static void LoadConsoleEffects()
{
    static const char* const kConsoleFx[] = { "com_sfx_ord_exp" };
    const std::string dir = "ux0:data/swbf2/BF2_ModTools/data/Common/effects/";
    for (const char* name : kConsoleFx)
    {
        std::string t;
        if (FILE* f = fopen((dir + name + ".fx").c_str(), "rb"))
        {
            char buf[4096]; size_t r;
            while ((r = fread(buf, 1, sizeof buf, f)) > 0) t.append(buf, r);
            fclose(f);
        }
        if (t.empty()) { checkpointf("CONSOLE FX %s: no ModTools source - keeping the PC effect", name); continue; }

        for (size_t q = t.find("Texture(\""); q != std::string::npos; q = t.find("Texture(\"", q + 1))
        {
            const size_t a0 = q + 9, a1 = t.find('"', a0);
            if (a1 == std::string::npos) break;
            const std::string tex = t.substr(a0, a1 - a0);
            if (tex.empty() || g_lvlTexPixels.count(tex)) continue;

            FILE* f = fopen((dir + tex + ".tga").c_str(), "rb");
            if (f == nullptr) { checkpointf("CONSOLE FX %s: texture %s.tga not in ModTools", name, tex.c_str()); continue; }
            uint8_t h[18] = {};
            if (fread(h, 1, 18, f) == 18 && h[2] == 2 && (h[16] == 32 || h[16] == 24))
            {
                const uint16_t w = (uint16_t)(h[12] | (h[13] << 8)), hh = (uint16_t)(h[14] | (h[15] << 8));
                const int bp = h[16] / 8; const bool topDown = (h[17] & 0x20) != 0;
                if (h[0]) fseek(f, h[0], SEEK_CUR);
                std::vector<uint8_t> raw((size_t)w * hh * bp);
                if (w && hh && fread(raw.data(), 1, raw.size(), f) == raw.size())
                {
                    LvlTexPixels& e = g_lvlTexPixels[tex]; e.w = w; e.h = hh; e.px.resize((size_t)w * hh * 4);
                    for (uint32_t y = 0; y < hh; ++y)
                        for (uint32_t x = 0; x < w; ++x)
                        {
                            const uint8_t* sp = &raw[((size_t)(topDown ? y : hh - 1 - y) * w + x) * bp];
                            uint8_t* dp = &e.px[((size_t)y * w + x) * 4];
                            dp[0] = sp[2]; dp[1] = sp[1]; dp[2] = sp[0]; dp[3] = (bp == 4) ? sp[3] : 255;
                        }
                    checkpointf("CONSOLE FX %s: texture %s %ux%u from ModTools", name, tex.c_str(), (unsigned)w, (unsigned)hh);
                }
            }
            fclose(f);
        }
        std::vector<FxTxtNode> top; size_t i = 0;
        if (!FxTxtParseBlock(t, i, top, 0)) { checkpointf("CONSOLE FX %s: parse failed - keeping the PC effect", name); continue; }
        FxTxtList roots; for (const FxTxtNode& n : top) if (n.h == FxH::ParticleEmitter) roots.v.push_back(&n);
        FxDef def;
        FxParseEmitterList(roots, def.emitters, nullptr);
        if (def.emitters.empty()) { checkpointf("CONSOLE FX %s: no emitters - keeping the PC effect", name); continue; }
        g_fxDefs[LibSWBF2::FNV::Hash(String(name))] = std::move(def);
        checkpointf("CONSOLE FX %s: the console source replaces the PC effect (%u emitters)", name, (unsigned)g_fxDefs[LibSWBF2::FNV::Hash(String(name))].emitters.size());
    }
}

