static void GodrayDir(float d[3])
{
    float x = -g_sunWorldDir[0], y = -g_sunWorldDir[1], z = -g_sunWorldDir[2];
    const float a = g_godray.offsetAngle, ca = cosf(a), sa = sinf(a);
    const float rx = x * ca - z * sa, rz = x * sa + z * ca;
    x = rx; z = rz;
    const float l = sqrtf(x * x + y * y + z * z);
    if (l > 1e-5f) { x /= l; y /= l; z /= l; } else { x = 0.0f; y = -1.0f; z = 0.0f; }
    d[0] = x; d[1] = y; d[2] = z;
}

static void PrepareGodrays(const std::vector<PlacedInstance>& placed, const std::vector<ModelData>& uniqueModels, const TerrainData& td)
{
    GodrayFx& g = g_godray;
    if (!g.on || g.insts.empty()) return;
    struct Occ { float x, y, z, rx, hy; };
    std::vector<Occ> occ;
    occ.reserve(placed.size());
    for (const PlacedInstance& pi : placed)
    {
        if (pi.isSoldier || pi.isVehicle || pi.isActiveOrdnance || pi.modelIndex >= uniqueModels.size()) continue;
        const ModelData& md = uniqueModels[pi.modelIndex];
        if (md.boundRadius < 4.0f || md.boundRadius > 300.0f) continue;
        const float hy = md.boundHalfY > 0.0f ? md.boundHalfY : md.boundRadius;
        if (hy < 4.0f) continue;
        const Vector3 c = QuatRotateVector(pi.rotation, md.boundCenter);
        occ.push_back({ pi.position.m_X + c.m_X, pi.position.m_Y + c.m_Y, pi.position.m_Z + c.m_Z,
                        sqrtf(md.boundHalfX * md.boundHalfX + md.boundHalfZ * md.boundHalfZ), hy });
    }

    float sd[3]; GodrayDir(sd);
    uint32_t covered = 0, groundClipped = 0, totalRays = 0;
    float lenSum = 0.0f;
    uint32_t hint = 0;
    Vector3 n;
    for (GodrayInst& gi : g.insts)
    {
        totalRays += (uint32_t)std::max(1, gi.numRays);

        bool hit = false;
        const float yA = gi.pos.m_Y, yB = gi.pos.m_Y + sd[1] * g.maxLen;
        const float ylo = fminf(yA, yB), yhi = fmaxf(yA, yB);
        for (const Occ& o : occ)
        {
            if (yhi < o.y - o.hy || ylo > o.y + o.hy) continue;
            const float dx = gi.pos.m_X - o.x, dz = gi.pos.m_Z - o.z;
            if (dx * dx + dz * dz > o.rx * o.rx) continue;
            hit = true; break;
        }

        float len = g.maxLen, prevT = 0.0f;
        for (int k = 1; k <= 8; ++k)
        {
            const float t = g.maxLen * (float)k / 8.0f;
            float ty = 0.0f;
            if (!GetTerrainHeightAt(td, gi.pos.m_X + sd[0] * t, gi.pos.m_Z + sd[2] * t, ty, n, hint)) { prevT = t; continue; }
            if (gi.pos.m_Y + sd[1] * t <= ty + 0.25f)
            {
                float lo = prevT, hi = t;
                for (int b = 0; b < 6; ++b)
                {
                    const float mid = 0.5f * (lo + hi);
                    float my = 0.0f;
                    if (GetTerrainHeightAt(td, gi.pos.m_X + sd[0] * mid, gi.pos.m_Z + sd[2] * mid, my, n, hint)
                        && gi.pos.m_Y + sd[1] * mid <= my + 0.25f) hi = mid; else lo = mid;
                }
                len = hi; ++groundClipped;
                break;
            }
            prevT = t;
        }
        gi.cover = hit;
        gi.losLen = len;
        if (hit) ++covered;
        lenSum += len;
    }
    checkpointf("M530 godray prepare: %u clusters / %u seeded rays, %u over geometry, %u clipped by ground, mean shaft %.1f m (occ %u)",
                (unsigned)g.insts.size(), totalRays, covered, groundClipped, lenSum / (float)g.insts.size(), (unsigned)occ.size());
}
