static const int kBubbleSkillAlly[3]  = { 6, 11, 11 };
static const int kBubbleSkillEnemy[3] = { 4, 14, 17 };
static const char* const kDifficultyName[4] = { "?", "(1: not offered)", "Normal", "Elite" };
static AimBubble g_playerBubble;
