static float BubbleSkillF(bool ownerOnPlayerTeam)
{
    int s = ownerOnPlayerTeam ? kBubbleSkillEnemy[AiDifficultyLevel() - 1] : kBubbleSkillAlly[AiDifficultyLevel() - 1];
    if (s < 1) s = 1;
    if (s > 20) s = 20;
    return (float)(s - 1) * 0.05263158f;
}
static inline float BubbleLerp(float a, float b, float f) { return (b - a) * f + a; }

static void BubbleAdd(AimBubble& b, float a, float skillF)
{
    if (a > 0.0f) { if (a > b.budget) a = b.budget; b.budget -= a; }
    b.scale += a;
    const float minScale = fmaxf(0.0f, BubbleLerp(1.6f, 0.4f, skillF));
    if (b.scale < minScale) b.scale = minScale;
    else if (b.scale > 2.0f) b.scale = 2.0f;
}

enum { BUBBLE_EV_ROLL = 0, BUBBLE_EV_SPRINT = 1, BUBBLE_EV_JUMP = 2, BUBBLE_EV_JET = 3 };
static void BubbleEvent(AimBubble& b, int ev, float skillF)
{
    static const float kAmount[5] = { 2.0f, 2.0f, 1.0f, 5.0f, 5.0f };
    if (ev >= 0 && ev < 5) BubbleAdd(b, kAmount[ev], skillF);
}

static float BubbleRand01() { return (float)rand() / (float)RAND_MAX; }

static void BubbleUpdate(AimBubble& b, const Vector3& pos, float maxSpeed, float dt, float skillF, float width)
{
    if (dt <= 0.0f) return;
    const float rate = BubbleLerp(-0.1f, -1.1f, skillF) * dt;
    BubbleAdd(b, rate, skillF);
    b.budget = fminf(5.0f, fmaxf(0.0f, b.budget - rate * 0.5f));
    const float vmax = fmaxf(maxSpeed, 0.1f);
    float moved = 0.0f;
    if (b.havePrev)
    {
        const float dx = pos.m_X - b.prev.m_X, dy = pos.m_Y - b.prev.m_Y, dz = pos.m_Z - b.prev.m_Z;
        moved = sqrtf(dx * dx + dy * dy + dz * dz);
        if (moved > 20.0f) moved = 0.0f;
    }
    b.prev = pos; b.havePrev = true;
    BubbleAdd(b, moved / vmax * 0.455f, skillF);
    b.speed = moved / dt;

    float rx = BubbleRand01() * 2.0f - 1.0f, ry = BubbleRand01() * 2.0f - 1.0f, rz = BubbleRand01() * 2.0f - 1.0f;
    b.ax += rx; b.ay += ry; b.az += rz;
    float al = sqrtf(b.ax * b.ax + b.ay * b.ay + b.az * b.az);
    if (al < 1e-4f) { b.ax = 1.0f; b.ay = 0.0f; b.az = 0.0f; al = 1.0f; }
    b.ax /= al; b.ay /= al; b.az /= al;
    const float th = 2.0f * dt, c = cosf(th), s = sinf(th);
    const float kd = b.ax * b.ux + b.ay * b.uy + b.az * b.uz;
    const float cx = b.ay * b.uz - b.az * b.uy, cy = b.az * b.ux - b.ax * b.uz, cz = b.ax * b.uy - b.ay * b.ux;
    b.ux = b.ux * c + cx * s + b.ax * kd * (1.0f - c);
    b.uy = b.uy * c + cy * s + b.ay * kd * (1.0f - c);
    b.uz = b.uz * c + cz * s + b.az * kd * (1.0f - c);
    const float ul = sqrtf(b.ux * b.ux + b.uy * b.uy + b.uz * b.uz);
    if (ul > 1e-4f) { b.ux /= ul; b.uy /= ul; b.uz /= ul; }

    const float maxSize = fmaxf(0.0f, BubbleLerp(2.2f, 1.2f, skillF));
    const float s0 = fminf((b.speed / vmax * 0.6f + 1.0f) * b.scale, maxSize);
    b.size = s0 * width;
}

static Vector3 BubbleAimOffset(const AimBubble& b, const Vector3& eye, const Vector3& aim, float weaponMult)
{
    const float fx = aim.m_X - eye.m_X, fz = aim.m_Z - eye.m_Z;
    const float hl = sqrtf(fx * fx + fz * fz);
    if (hl < 1e-3f) return Vector3(0.0f, 0.0f, 0.0f);
    const float rx = -fz / hl, rz = fx / hl;
    const float lat = b.ux * b.size * weaponMult;
    float ver = b.uy * b.size * weaponMult;
    const float cap = 2.0f + BubbleRand01();
    ver = fmaxf(0.0f, fminf(cap, ver));
    return Vector3(rx * lat, ver, rz * lat);
}

static inline float AiSpreadTri() { return ((float)rand() / (float)RAND_MAX) - ((float)rand() / (float)RAND_MAX); }
static Vector3 BubbleAimPointOffset(const AimBubble& b, const Vector3& eye, const Vector3& aim, float sizeMult, float distDiv, float clampK,
                                    bool targetCarriesHuman, bool shooterWithHuman)
{
    const float dx = aim.m_X - eye.m_X, dy = aim.m_Y - eye.m_Y, dz = aim.m_Z - eye.m_Z;
    const float k = retail_ai::BubbleK(sqrtf(dx * dx + dy * dy + dz * dz), distDiv, clampK, targetCarriesHuman, shooterWithHuman);
    if (k == 0.0f) return Vector3(0.0f, 0.0f, 0.0f);
    const Vector3 o = BubbleAimOffset(b, eye, aim, sizeMult);
    return Vector3(o.m_X * k, o.m_Y * k, o.m_Z * k);
}

