static inline const char* ThrownAnimName(int phase, bool front, int dir, bool sliding, float airSec)
{

    (void)dir; (void)sliding; (void)airSec;
    if (phase <= 1) return front ? "thrown_tumblefront" : "thrown_tumbleback";
    if (phase == 2) return front ? "thrown_restfrontsoft" : "thrown_restbacksoft";
    return front ? "stand_getupfront" : "stand_getupback";
}

static inline int ThrownDirFromPush(const Vector3& push, const Vector3& fwd)
{
    const float f = push.m_X * fwd.m_X + push.m_Z * fwd.m_Z;
    const float r = push.m_X * -fwd.m_Z + push.m_Z * fwd.m_X;
    if (fabsf(r) > fabsf(f)) return (r > 0.0f) ? 3 : 2;
    return (f >= 0.0f) ? 0 : 1;
}

static void AIBeginThrown(AIUnitState& au, const PlacedInstance& pi, const Vector3& push)
{
    const Vector3 fwd = QuatRotateVector(pi.rotation, Vector3(0.0f, 0.0f, 1.0f));
    au.thrown = true;
    au.thrownPhase = 1;
    au.thrownTimer = 0.0f;
    au.thrownFront = (push.m_X * fwd.m_X + push.m_Z * fwd.m_Z) >= 0.0f;
    au.thrownDir = ThrownDirFromPush(push, fwd);
    au.thrownSliding = false;
}

static void UiBlitRotated(GLuint tex, float cx, float cy, float size, float ang, float r, float g, float b, float a)
{
    if (tex == 0) return;
    const float h = size * 0.5f, c = cosf(ang), sn = sinf(ang);
    const float cs[4][2] = { { -h, -h }, { h, -h }, { h, h }, { -h, h } }, uv[4][2] = { { 0, 0 }, { 1, 0 }, { 1, 1 }, { 0, 1 } };
    float px[4], py[4];
    for (int k = 0; k < 4; ++k) { px[k] = cx + cs[k][0] * c - cs[k][1] * sn; py[k] = cy + cs[k][0] * sn + cs[k][1] * c; }
    glEnable(GL_TEXTURE_2D);
    glBindTexture(GL_TEXTURE_2D, tex);
    glColor4f(r, g, b, a);
    glBegin(GL_TRIANGLES);
    const int order[6] = { 0, 1, 2, 0, 2, 3 };
    for (int k = 0; k < 6; ++k) { glTexCoord2f(uv[order[k]][0], uv[order[k]][1]); glVertex2f(px[order[k]], py[order[k]]); }
    glEnd();
    glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
    glDisable(GL_TEXTURE_2D);
}

struct MapUnitDot { float x, z, yaw; int team; };
static void CollectMapUnits(std::vector<MapUnitDot>& out)
{
    out.clear();
    if (g_placedForScripts == nullptr) return;
    for (const AIUnitState& au : g_aiUnits)
    {
        if (au.life != AI_LIFE_ALIVE || au.placedIndex >= g_placedForScripts->size()) continue;
        const PlacedInstance& pi = (*g_placedForScripts)[au.placedIndex];
        if (pi.team < 1 || pi.inVehicle) continue;
        const Vector3 f = QuatRotateVector(pi.rotation, Vector3(0.0f, 0.0f, 1.0f));
        out.push_back({ pi.position.m_X, pi.position.m_Z, atan2f(-f.m_X, -f.m_Z), pi.team });
    }
}

static const int UI_POST_WALKER_BASE = 10000;
static int UiPostWalker(int rowValue)
{
    if (rowValue < UI_POST_WALKER_BASE) return -1;
    const size_t vi = (size_t)(rowValue - UI_POST_WALKER_BASE);
    return (vi < g_vehicles.size() && g_vehicles[vi].alive) ? (int)vi : -1;
}

static bool UiMapProject(float wx, float wz, float cx, float cy, float radius, float& sx, float& sy)
{
    if (!g_mapBoundsValid) return false;

    const float u = (wx - g_mapMinX) / g_mapSizeX, v = (wz - g_mapMinZ) / g_mapSizeZ;
    sx = cx + (u - 0.5f) * 2.0f * radius;
    sy = cy + (v - 0.5f) * 2.0f * radius;
    return true;
}

static void UiBorder9(GLuint tex, float x, float y, float w, float h, float corner, float a)
{
    if (tex == 0) return;
    const float xs[4] = { x, x + corner, x + w - corner, x + w }, ys[4] = { y, y + corner, y + h - corner, y + h };
    const float us[4] = { 0.0f, 0.25f, 0.75f, 1.0f };
    glEnable(GL_TEXTURE_2D);
    glBindTexture(GL_TEXTURE_2D, tex);
    glColor4f(1.0f, 1.0f, 1.0f, a);
    glBegin(GL_TRIANGLES);
    for (int j = 0; j < 3; ++j)
        for (int i = 0; i < 3; ++i)
        {
            glTexCoord2f(us[i], us[j]);         glVertex2f(xs[i], ys[j]);
            glTexCoord2f(us[i + 1], us[j]);     glVertex2f(xs[i + 1], ys[j]);
            glTexCoord2f(us[i + 1], us[j + 1]); glVertex2f(xs[i + 1], ys[j + 1]);
            glTexCoord2f(us[i], us[j]);         glVertex2f(xs[i], ys[j]);
            glTexCoord2f(us[i + 1], us[j + 1]); glVertex2f(xs[i + 1], ys[j + 1]);
            glTexCoord2f(us[i], us[j + 1]);     glVertex2f(xs[i], ys[j + 1]);
        }
    glEnd();
    glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
    glDisable(GL_TEXTURE_2D);
}

static void UiTextCentered(const char* t, float cx, float baseline, float scale, float r, float g, float b, float a)
{
    const float w = RealTextWidth(g_uiFont, t, scale);
    DrawRealText(g_uiFont, t, cx - w * 0.5f, baseline, scale, r, g, b, a);
}

static void UiTeamColour(int team, float& r, float& g, float& b)
{
    if (team <= 0)                 { r = 230.0f / 255.0f; g = 230.0f / 255.0f; b = 230.0f / 255.0f; }
    else if (team == g_playerTeam) { r = 1.0f / 255.0f;   g = 86.0f / 255.0f;  b = 213.0f / 255.0f; }
    else                           { r = 210.0f / 255.0f; g = 26.0f / 255.0f;  b = 34.0f / 255.0f; }
}

static void DrawCpCaptureIndicator(const Vector3& playerPos, bool canCapture, float dt)
{
    static float s_alpha = 0.0f, s_t = 0.0f, s_frac = 0.0f, s_r = 1.0f, s_g = 1.0f, s_b = 1.0f;
    static bool s_disputed = false;
    s_t += dt;
    const CommandPostState* in = nullptr;
    if (canCapture)
        for (const CommandPostState& cp : g_commandPosts)
            if (cp.hasCaptureRegion && PointInRegion(cp.captureRegionPos, cp.captureRegionRot, cp.captureRegionSize, cp.captureRegionType, playerPos)) { in = &cp; break; }
    if (in != nullptr)
    {
        int colourTeam = in->team;
        float frac = 1.0f;
        if (in->team <= 0)
        {
            colourTeam = in->captureTeam;
            const float ct = in->captureTime >= 0.0f ? in->captureTime : g_commandPostCaptureTime;
            frac = ct > 0.0f ? fminf(1.0f, in->captureTimer / ct) : 0.0f;
        }
        else if (in->captureTeam > 0 && in->captureTeam != in->team)
        {
            const float nt = in->neutralizeTime >= 0.0f ? in->neutralizeTime : g_commandPostNeutralizeTime;
            frac = nt > 0.0f ? fmaxf(0.0f, 1.0f - in->captureTimer / nt) : 1.0f;
        }
        s_frac = frac; s_disputed = in->captureDisputed;
        UiTeamColour(colourTeam, s_r, s_g, s_b);
        s_alpha = fminf(1.0f, s_alpha + dt / 1.0f);
    }
    else s_alpha = fmaxf(0.0f, s_alpha - dt / 1.0f);
    const GLuint icon = g_uiChrome.cpTimer != 0 ? g_uiChrome.cpTimer : g_uiChrome.flag;
    if (s_alpha <= 0.0f || icon == 0) return;
    const float sz = 0.14f * SCREEN_H;
    const float x0 = 0.915f * SCREEN_W - sz * 0.5f, y0 = 0.50f * SCREEN_H - sz * 0.5f;
    const float flash = s_disputed ? (0.35f + 0.65f * (0.5f + 0.5f * cosf(s_t * 6.2831853f * 4.0f))) : 1.0f;
    glMatrixMode(GL_PROJECTION); glPushMatrix(); glLoadIdentity(); glOrtho(0, SCREEN_W, SCREEN_H, 0, -1, 1);
    glMatrixMode(GL_MODELVIEW); glPushMatrix(); glLoadIdentity();
    ApplyPass(PASS_HUD_2D);
    glEnable(GL_TEXTURE_2D); glBindTexture(GL_TEXTURE_2D, icon);
    glEnableClientState(GL_VERTEX_ARRAY); glEnableClientState(GL_TEXTURE_COORD_ARRAY);
    auto quad = [&](float vTop, float r, float g, float b, float a) {
        const float yt = y0 + sz * vTop, x1 = x0 + sz, y1 = y0 + sz;
        const float v[12] = { x0,yt, x1,yt, x1,y1,  x0,yt, x1,y1, x0,y1 };
        const float uv[12] = { 0,vTop, 1,vTop, 1,1,  0,vTop, 1,1, 0,1 };
        glVertexPointer(2, GL_FLOAT, 0, v); glTexCoordPointer(2, GL_FLOAT, 0, uv);
        glColor4f(r, g, b, a); glDrawArrays(GL_TRIANGLES, 0, 6);
    };
    quad(0.0f, 0.9f, 0.9f, 0.9f, 0.55f * s_alpha);
    if (s_frac > 0.0f) quad(1.0f - s_frac, s_r, s_g, s_b, 0.95f * s_alpha * flash);
    glDisableClientState(GL_TEXTURE_COORD_ARRAY); glDisableClientState(GL_VERTEX_ARRAY);
    ApplyPass(PASS_WORLD_BASELINE);
    glMatrixMode(GL_PROJECTION); glPopMatrix();
    glMatrixMode(GL_MODELVIEW); glPopMatrix();
}

static void UiFooter(bool back, bool select, float anim)
{
    const float sc = 0.62f, base = 0.957f * SCREEN_H;
    if (back)
        DrawRealText(g_uiFont, LocString("common.back", "Back").c_str(), 0.069f * SCREEN_W, base, sc,
                     UI_UNSEL_R, UI_UNSEL_G, UI_UNSEL_B, 0.9f * anim);
    if (select)
    {
        const std::string t = LocString("common.select", "Select");
        DrawRealText(g_uiFont, t.c_str(), 0.930f * SCREEN_W - RealTextWidth(g_uiFont, t.c_str(), sc), base, sc,
                     UI_UNSEL_R, UI_UNSEL_G, UI_UNSEL_B, 0.9f * anim);
    }
}

static void UiDrawConsoleScreen(const UiScreenState& scr, float anim)
{
    const float W = (float)SCREEN_W, H = (float)SCREEN_H;
    UiDrawQuad(0.0f, 0.0f, W, H, 0.0f, 0.0f, 0.0f, 0.30f * anim);

    if (scr.id == UI_SCREEN_FACTION)
    {

        const float x0 = 0.584f * W, w = 0.294f * W, rh = 0.061f * H, pitch = 0.0715f * H;
        float y = 0.373f * H;
        UiDrawRowStrip(g_uiChrome.topL, g_uiChrome.titleC, g_uiChrome.topR, x0, y, w, rh, 0.95f * anim);
        UiTextCentered(scr.title.c_str(), x0 + w * 0.5f, y + rh * 0.74f, 0.82f, UI_TITLE_R, UI_TITLE_G, UI_TITLE_B, anim);
        for (size_t i = 0; i < scr.rows.size(); ++i)
        {
            y += pitch;
            const bool focused = ((int)i == scr.cursor), last = (i + 1 == scr.rows.size());
            UiDrawRowStrip(last ? g_uiChrome.botL : g_uiChrome.midL, g_uiChrome.itemsC, last ? g_uiChrome.botR : g_uiChrome.midR,
                           x0, y, w, rh, (focused ? 1.0f : 0.75f) * anim);
            float r = UI_UNSEL_R, g = UI_UNSEL_G, b = UI_UNSEL_B;
            if (focused) { r = UI_SEL_R; g = UI_SEL_G; b = UI_SEL_B; }
            UiTextCentered(scr.rows[i].label.c_str(), x0 + w * 0.5f, y + rh * 0.74f, 0.82f, r, g, b, anim);
        }
        return;
    }

    if (scr.id == UI_SCREEN_POST)
    {

        const float cx = 0.303f * W, cy = 0.471f * H, R = 0.265f * H;
        if (g_mapTex != 0)
        {
            glEnable(GL_TEXTURE_2D);
            glBindTexture(GL_TEXTURE_2D, g_mapTex);
            glColor4f(1.0f, 1.0f, 1.0f, 0.6f * anim);
            glBegin(GL_TRIANGLES);
            const int N = 48;
            for (int k = 0; k < N; ++k)
            {
                const float a0 = 6.2831853f * k / N, a1 = 6.2831853f * (k + 1) / N;
                const float img = g_mapNorthSmall ? 0.0f : g_mapNorthRad;
                const float t0 = a0 + img, t1 = a1 + img;
                glTexCoord2f(0.5f, 0.5f); glVertex2f(cx, cy);
                glTexCoord2f(0.5f + 0.5f * cosf(t0), 0.5f + 0.5f * sinf(t0)); glVertex2f(cx + R * cosf(a0), cy + R * sinf(a0));
                glTexCoord2f(0.5f + 0.5f * cosf(t1), 0.5f + 0.5f * sinf(t1)); glVertex2f(cx + R * cosf(a1), cy + R * sinf(a1));
            }
            glEnd();
            glColor4f(1.0f, 1.0f, 1.0f, 1.0f);
            glDisable(GL_TEXTURE_2D);
        }

        UiBlit(g_uiChrome.north, cx - 12.0f, 0.191f * H - 12.0f, 24.0f, 24.0f, 1, 1, 1, 0.95f * anim);

        for (size_t i = 0; i < scr.rows.size() && i < scr.mapX.size(); ++i)
        {
            float sx, sy;
            const int cpi = (i < g_uiPostRows.size()) ? g_uiPostRows[i] : -1;
            const int walker = UiPostWalker(cpi);
            float wx = scr.mapX[i], wz = scr.mapZ[i];
            if (walker >= 0 && g_placedForScripts != nullptr && g_vehicles[(size_t)walker].placedIndex < g_placedForScripts->size())
            {
                wx = (*g_placedForScripts)[g_vehicles[(size_t)walker].placedIndex].position.m_X;
                wz = (*g_placedForScripts)[g_vehicles[(size_t)walker].placedIndex].position.m_Z;
            }
            if (!UiMapProject(wx, wz, cx, cy, R, sx, sy)) continue;
            const int team = (walker >= 0) ? g_vehicles[(size_t)walker].team
                           : (cpi >= 0 && (size_t)cpi < g_commandPosts.size()) ? g_commandPosts[(size_t)cpi].team : 0;
            float r, g, b; UiTeamColour(team, r, g, b);
            const float is = 20.0f;
            if (walker >= 0)
                UiBlitRotated(g_uiChrome.atte, sx, sy, is * 2.2f / 2.5f, -g_vehicles[(size_t)walker].yaw, r, g, b, anim);
            else
                UiBlit(g_uiChrome.flag, sx - is * 0.5f, sy - is * 0.5f, is, is, r, g, b, anim);
            if ((int)i == scr.cursor)
            {
                const float fs = 30.0f;
                UiBlit(g_uiChrome.flash, sx - fs * 0.5f, sy - fs * 0.5f, fs, fs, r, g, b, anim);
            }
            if (!scr.rows[i].detail.empty())
                UiTextCentered(scr.rows[i].detail.c_str(), sx, sy - is * 0.55f, 0.5f, 1.0f, 1.0f, 1.0f, 0.95f * anim);
        }

        {
            std::vector<MapUnitDot> units; CollectMapUnits(units);
            for (const MapUnitDot& u : units)
            {
                if (u.team != g_playerTeam) continue;
                float sx, sy;
                if (!UiMapProject(u.x, u.z, cx, cy, R, sx, sy)) continue;
                UiBlitRotated(g_uiChrome.troop, sx, sy, 9.0f, -u.yaw, 1.0f / 255.0f, 86.0f / 255.0f, 213.0f / 255.0f, 0.95f * anim);
            }
        }

        if (scr.cursor >= 0 && (size_t)scr.cursor < g_uiPostRows.size())
        {
            const int cpi = g_uiPostRows[(size_t)scr.cursor];
            const int walker = UiPostWalker(cpi);
            const int team = (walker >= 0) ? g_vehicles[(size_t)walker].team
                           : (cpi >= 0 && (size_t)cpi < g_commandPosts.size()) ? g_commandPosts[(size_t)cpi].team : 0;
            float r, g, b; UiTeamColour(team, r, g, b);
            const float ls = 30.0f;
            if (walker >= 0) UiBlitRotated(g_uiChrome.atte, 0.166f * W, 0.775f * H, ls, 0.0f, r, g, b, anim);
            else UiBlit(g_uiChrome.flag, 0.166f * W - ls * 0.5f, 0.775f * H - ls * 0.5f, ls, ls, r, g, b, anim);
            const std::string legend = (walker >= 0) ? LocString(LocKeyForClass(g_vehicles[(size_t)walker].cls, false), "AT-TE")
                                                     : LocString("game.spawndisplay.spawnpointtitle", "Command Post");
            DrawRealText(g_uiFont, legend.c_str(), 0.194f * W, 0.775f * H + 6.0f, 0.6f, 1.0f, 1.0f, 1.0f, 0.9f * anim);
        }

        DrawRealText(g_uiFont, LocString(MapObjectiveKey().c_str(), "Capture all the Enemy CPs").c_str(),
                     0.569f * W, 0.197f * H, 0.72f, UI_TITLE_R, UI_TITLE_G, UI_TITLE_B, 0.95f * anim);
        UiFooter(false, true, anim);
        return;
    }

    if (scr.id == UI_SCREEN_UNIT && !scr.rows.empty())
    {

        const size_t sel = (size_t)scr.cursor;
        const std::string cls = (sel < g_uiUnitRoster.size()) ? g_uiUnitRoster[sel] : std::string();
        const float tx = 0.460f * W, tw = 0.499f * W, th = 0.055f * H, ty = 0.203f * H;
        UiDrawRowStrip(g_uiChrome.topL, g_uiChrome.titleC, g_uiChrome.topR, tx, ty, tw, th, 0.95f * anim);
        UiTextCentered(scr.rows[sel].label.c_str(), tx + tw * 0.5f, ty + th * 0.76f, 0.78f, UI_TITLE_R, UI_TITLE_G, UI_TITLE_B, anim);
        UiBorder9(g_uiChrome.border3, 0.461f * W, 0.271f * H, 0.493f * W, 0.507f * H, 18.0f, 0.85f * anim);

        std::vector<std::string> lines;
        {

            if (UiUnitClassLocked(cls))
            {
                std::string nfmt = LocString("game.spawndisplay.needmorepoints", "Get %d more points to unlock!");
                const std::string n = std::to_string(UiUnitClassLockedPointsLeft(cls));
                const size_t np = nfmt.find("%d");
                if (np != std::string::npos) nfmt = nfmt.substr(0, np) + n + nfmt.substr(np + 2);
                while (!nfmt.empty() && (nfmt.back() == '\n' || nfmt.back() == '\r')) nfmt.pop_back();
                lines.push_back(nfmt);
                static std::string s_lastNeed;
                if (s_lastNeed != cls + "|" + n)
                {
                    s_lastNeed = cls + "|" + n;
                    checkpointf("UNLOCK panel: \"%s\" locked - showing \"%s\" (points %d, cost %d)",
                        cls.c_str(), nfmt.c_str(), UiPlayerPoints(), UiUnlockCostOf(cls));
                }
            }
            int count = 0;
            if (g_placedForScripts != nullptr)
                for (const AIUnitState& au : g_aiUnits)
                    if (au.life == AI_LIFE_ALIVE && au.placedIndex < g_placedForScripts->size()
                        && (*g_placedForScripts)[au.placedIndex].team == g_playerTeam
                        && (*g_placedForScripts)[au.placedIndex].unitClass == cls) ++count;
            std::string fmt = LocString("game.spawndisplay.unitcount", "Unit Count: %d");
            const size_t pc = fmt.find("%d");
            if (pc != std::string::npos) fmt = fmt.substr(0, pc) + std::to_string(count) + fmt.substr(pc + 2);
            lines.push_back(fmt);
        }
        auto lo = g_unitClassLoadout.find(cls);
        if (lo != g_unitClassLoadout.end())
            for (size_t si2 = 0; si2 < lo->second.slotWeapon.size(); ++si2)
            {
                const int wi = lo->second.slotWeapon[si2];
                if (wi < 0 || (size_t)wi >= g_weaponTable.size()) continue;
                if (IsAwardSlot(lo->second, si2) && !g_awardUnlocked[cls]) continue;
                const std::string& wn = g_weaponTable[(size_t)wi].name;
                const std::string nm = LocString(LocKeyForClass(wn, true), wn);
                if (std::find(lines.begin(), lines.end(), nm) == lines.end()) lines.push_back(nm);
            }
        for (size_t i = 0; i < lines.size(); ++i)
            DrawRealText(g_uiFont, lines[i].c_str(), 0.469f * W, (0.380f + 0.0467f * i) * H, 0.66f, 1.0f, 1.0f, 1.0f, anim);
        UiFooter(true, true, anim);
        return;
    }
}

static bool g_mmArrowDbg = false;
static bool g_mmArrowFlatDbg = false;
static void DrawMiniMap(const Vector3& pos, float yaw)
{
    if (!g_mapBoundsValid || g_mapTex == 0) return;
    if (!std::isfinite(pos.m_X) || !std::isfinite(pos.m_Z) || !std::isfinite(yaw))
    {
        static int s_n = 0; if (s_n++ < 5) checkpointf("M467 minimap: non-finite centre (%f,%f) yaw %f - not drawn", pos.m_X, pos.m_Z, yaw);
        return;
    }
    const float W = (float)SCREEN_W, H = (float)SCREEN_H;
    const float cx = 0.838962f * W, cy = 0.186248f * H, R = 0.089f * H;
    const float worldR = 50.0f;
    const float ppm = R / worldR;
    const float c = cosf(yaw), sn = sinf(yaw);

    const float mapNorthImg = (g_mapNorthRad != 0.0f && !g_mapNorthSmall) ? g_mapNorthRad : 0.0f;
    const float mapRot = yaw - mapNorthImg;
    glDisableClientState(GL_VERTEX_ARRAY); glDisableClientState(GL_NORMAL_ARRAY);
    glDisableClientState(GL_TEXTURE_COORD_ARRAY); glDisableClientState(GL_COLOR_ARRAY);

    auto toScreen = [&](float wx, float wz, float& sx, float& sy) {
        const float dx = (wx - pos.m_X) * ppm, dy = (wz - pos.m_Z) * ppm;
        sx = cx + dx * c - dy * sn; sy = cy + dx * sn + dy * c;
    };
    glMatrixMode(GL_PROJECTION); glPushMatrix(); glLoadIdentity(); glOrtho(0, W, H, 0, -1, 1);
    glMatrixMode(GL_MODELVIEW);  glPushMatrix(); glLoadIdentity();
    ApplyPass(PASS_HUD_2D);

    glEnable(GL_TEXTURE_2D);
    glBindTexture(GL_TEXTURE_2D, g_mapTex);
    glBegin(GL_TRIANGLES);
    const int N = 40;
    auto uvAt = [&](float ox, float oy, float& u, float& v) {
        const float dx = (ox * c + oy * sn) / ppm, dz = (-ox * sn + oy * c) / ppm;
        u = (pos.m_X + dx - g_mapMinX) / g_mapSizeX; v = (pos.m_Z + dz - g_mapMinZ) / g_mapSizeZ;
        if (mapNorthImg != 0.0f)
        { const float nc = cosf(mapNorthImg), ns = sinf(mapNorthImg), du = u - 0.5f, dv = v - 0.5f; u = 0.5f + du * nc - dv * ns; v = 0.5f + du * ns + dv * nc; }
    };
    float u0, v0; uvAt(0.0f, 0.0f, u0, v0);
    for (int k = 0; k < N; ++k)
    {
        const float a0 = 6.2831853f * k / N, a1 = 6.2831853f * (k + 1) / N;
        float ua, va, ub, vb;
        uvAt(R * cosf(a0), R * sinf(a0), ua, va); uvAt(R * cosf(a1), R * sinf(a1), ub, vb);
        glColor4f(1.0f, 1.0f, 1.0f, 0.5f * 0.85f);
        glTexCoord2f(u0, v0); glVertex2f(cx, cy);
        glTexCoord2f(ua, va); glVertex2f(cx + R * cosf(a0), cy + R * sinf(a0));
        glTexCoord2f(ub, vb); glVertex2f(cx + R * cosf(a1), cy + R * sinf(a1));
    }
    glEnd();
    glDisable(GL_TEXTURE_2D);

    glColor4f(0.85f, 0.85f, 0.85f, 0.7f);
    glBegin(GL_TRIANGLES);
    for (int k = 0; k < N; ++k)
    {
        const float a0 = 6.2831853f * k / N, a1 = 6.2831853f * (k + 1) / N, r0 = R, r1 = R + 1.5f;
        glVertex2f(cx + r0 * cosf(a0), cy + r0 * sinf(a0)); glVertex2f(cx + r1 * cosf(a0), cy + r1 * sinf(a0)); glVertex2f(cx + r1 * cosf(a1), cy + r1 * sinf(a1));
        glVertex2f(cx + r0 * cosf(a0), cy + r0 * sinf(a0)); glVertex2f(cx + r1 * cosf(a1), cy + r1 * sinf(a1)); glVertex2f(cx + r0 * cosf(a1), cy + r0 * sinf(a1));
    }
    glEnd();

    glColor4f(1.0f, 1.0f, 1.0f, 0.8f);
    glBegin(GL_TRIANGLES);
    for (int side = -1; side <= 1; side += 2)
    {
        const float ang = -1.5707963f + side * 0.5235988f, ex = cx + R * 0.85f * cosf(ang), ey = cy + R * 0.85f * sinf(ang);
        const float nx = -sinf(ang) * 0.8f, ny = cosf(ang) * 0.8f;
        glVertex2f(cx - nx, cy - ny); glVertex2f(cx + nx, cy + ny); glVertex2f(ex + nx, ey + ny);
        glVertex2f(cx - nx, cy - ny); glVertex2f(ex + nx, ey + ny); glVertex2f(ex - nx, ey - ny);
    }
    glEnd();
    glColor4f(1.0f, 1.0f, 1.0f, 1.0f);

    for (const CommandPostState& cp : g_commandPosts)
    {
        if (!cp.mapIcon) continue;
        float sx, sy; toScreen(cp.position.m_X, cp.position.m_Z, sx, sy);
        if (!std::isfinite(sx) || !std::isfinite(sy)) continue;
        const float ox = sx - cx, oy = sy - cy, d = sqrtf(ox * ox + oy * oy);
        if (d > R - 5.0f && d > 0.001f) { sx = cx + ox * (R - 5.0f) / d; sy = cy + oy * (R - 5.0f) / d; }
        float r, g, b; UiTeamColour(cp.team, r, g, b);
        const float is = 12.0f;
        UiBlit(g_uiChrome.flag, sx - is * 0.5f, sy - is * 0.5f, is, is, r, g, b, 0.9f);
    }

    for (const VehicleState& v : g_vehicles)
    {
        if (!v.alive || g_placedForScripts == nullptr || v.placedIndex >= g_placedForScripts->size()) continue;
        auto dit = g_vehicleClassDefs.find(v.cls);
        if (dit == g_vehicleClassDefs.end() || dit->second.mapTexture.empty()) continue;
        const GLuint tex = LvlTex(dit->second.mapTexture.c_str());
        if (tex == 0)
        {
            static std::set<std::string> s_mmvMissing;
            if (s_mmvMissing.insert(v.cls).second) checkpointf("MMVEH \"%s\": MapTexture \"%s\" not loaded - no icon", v.cls.c_str(), dit->second.mapTexture.c_str());
            continue;
        }
        const Vector3& vp = (*g_placedForScripts)[v.placedIndex].position;
        if (vp.m_Y < VEHICLE_PARK_Y + 100.0f) continue;
        float sx, sy; toScreen(vp.m_X, vp.m_Z, sx, sy);
        if (!std::isfinite(sx) || !std::isfinite(sy)) continue;
        const float ox = sx - cx, oy = sy - cy, d = sqrtf(ox * ox + oy * oy);
        if (d > R - 4.0f) continue;
        if (v.team > 0 && v.team != g_playerTeam && (fabsf(atan2f(ox, -oy)) > 0.5235988f || d < 1.0f)) continue;
        float r, g, b; UiTeamColour(v.team, r, g, b);
        const float is = 4.8f * (dit->second.mapScale > 0.1f ? dit->second.mapScale : 2.5f);
        UiBlitRotated(tex, sx, sy, is, yaw - v.yaw, r, g, b, 0.95f);
        static std::set<std::string> s_mmvLogged;
        if (s_mmvLogged.insert(v.cls).second) checkpointf("MMVEH minimap icon \"%s\" (%s, %.0f px, team %d)", v.cls.c_str(), dit->second.mapTexture.c_str(), is, v.team);
    }

    {
        std::vector<MapUnitDot> units; CollectMapUnits(units);
        const float coneHalf = 0.5235988f;
        for (const MapUnitDot& u : units)
        {
            float sx, sy; toScreen(u.x, u.z, sx, sy);
            if (!std::isfinite(sx) || !std::isfinite(sy) || !std::isfinite(u.yaw))
            { static int s_bad = 0; if (s_bad++ < 5) checkpointf("M467 minimap: unit dot not finite (%f,%f yaw %f team %d)", u.x, u.z, u.yaw, u.team); continue; }
            const float ox = sx - cx, oy = sy - cy, d = sqrtf(ox * ox + oy * oy);
            if (d > R - 3.0f) continue;
            const bool friendly = (u.team == g_playerTeam);
            if (!friendly)
            {
                const float angFromUp = atan2f(ox, -oy);
                if (fabsf(angFromUp) > coneHalf || d < 1.0f) continue;
            }
            float r, g, b; UiTeamColour(u.team, r, g, b);
            UiBlitRotated(g_uiChrome.troop, sx, sy, 7.0f, yaw - u.yaw, r, g, b, 0.95f);
        }
    }

    {
        const float bear = g_mmArrowFlatDbg ? yaw : mapRot;
        const float ox = sinf(bear), oy = -cosf(bear);
        const float px = cx + ox * (R + 4.0f), py = cy + oy * (R + 4.0f);
        if (g_mmArrowFlatDbg) UiBlit(g_uiChrome.north, px - 7.0f, py - 7.0f, 14.0f, 14.0f, 1, 1, 1, 0.9f);
        else UiBlitRotated(g_uiChrome.north, px, py, 14.0f, bear, 1, 1, 1, 0.9f);
        if (g_mmArrowDbg)
        {
            static int s_mmN = 0;
            if (s_mmN++ % 30 == 0)
                checkpointf("MMARROW maprot=%.4f rad (%.1f deg) arrow=%.4f rad (%.1f deg) northimg=%.4f yaw=%.4f "
                            "rim=(%.1f,%.1f) r=%.1f flat=%d (%s)",
                            mapRot, mapRot * 57.2958f, bear, bear * 57.2958f, mapNorthImg, yaw, px, py, R,
                            (int)g_mmArrowFlatDbg, fabsf(bear - mapRot) < 0.002f ? "arrow==map" : "arrow!=map");
        }
    }
    ApplyPass(PASS_WORLD_BASELINE);
    glMatrixMode(GL_MODELVIEW); glPopMatrix();
    glMatrixMode(GL_PROJECTION); glPopMatrix();
    glMatrixMode(GL_MODELVIEW);
}

static void UiDrawMissionEnd(float anim)
{
    const float W = (float)SCREEN_W, H = (float)SCREEN_H;
    UiDrawQuad(0.0f, 0.0f, W, H, 0.0f, 0.0f, 0.0f, 0.35f * anim);
    const GLuint tex = LvlTex("_localize_english_ig_victory_defeat");
    const bool won = (g_missionWinningTeam == g_playerTeam);
    float r, g, b; UiTeamColour(g_missionWinningTeam, r, g, b);
    const float w = 256.0f * (W / 640.0f), h = 64.0f * (W / 640.0f);
    const float x = (W - w) * 0.5f, y = (H - h) * 0.5f;
    if (tex != 0)
    {
        const float v0 = won ? 0.0f : 0.5f, v1 = won ? 0.5f : 1.0f;
        glEnable(GL_TEXTURE_2D);
        glBindTexture(GL_TEXTURE_2D, tex);
        glColor4f(r, g, b, anim);
        glBegin(GL_TRIANGLES);
        glTexCoord2f(0, v0); glVertex2f(x, y);     glTexCoord2f(1, v0); glVertex2f(x + w, y); glTexCoord2f(1, v1); glVertex2f(x + w, y + h);
        glTexCoord2f(0, v0); glVertex2f(x, y);     glTexCoord2f(1, v1); glVertex2f(x + w, y + h); glTexCoord2f(0, v1); glVertex2f(x, y + h);
        glEnd();
        glColor4f(1, 1, 1, 1);
        glDisable(GL_TEXTURE_2D);
    }
    else UiTextCentered(won ? "VICTORY" : "DEFEAT", W * 0.5f, H * 0.5f, 1.4f, r, g, b, anim);
}

