static bool g_playerIsHero = false;

static bool g_heroesEnabled = false;
static bool g_heroSwapHidden = false;

static const std::string* HeroClassForTeam(int team)
{
    if (team < 1 || (size_t)team >= g_teams.size() || g_teams[(size_t)team].heroClass.empty()) return nullptr;
    if (g_classBodyModel.find(g_teams[(size_t)team].heroClass) == g_classBodyModel.end()) return nullptr;
    return &g_teams[(size_t)team].heroClass;
}

static void UiOpenUnitSelect(int playerTeam)
{
    g_uiUnitRoster.clear();
    UiScreenState scr;
    scr.id = UI_SCREEN_UNIT;
    scr.title = "Select Character";
    scr.prompt = "";
    scr.pausesGame = false;

    const TeamInfo* team = (playerTeam >= 0 && (size_t)playerTeam < g_teams.size())
        ? &g_teams[(size_t)playerTeam] : nullptr;
    std::vector<std::string> roster;
    if (team != nullptr) roster = team->unitClasses;

    if (g_playerIsHero && HeroClassForTeam(playerTeam) != nullptr) roster.insert(roster.begin(), *HeroClassForTeam(playerTeam));
    if (roster.empty())
        for (const auto& kv : g_unitClassWeapon) roster.push_back(kv.first);

    for (const std::string& cls : roster)
    {
        if (cls.empty()) continue;

        if (g_classBodyModel.find(cls) == g_classBodyModel.end()) continue;

        std::string label = cls;
        const size_t lastUnderscore = label.find_last_of('_');
        if (lastUnderscore != std::string::npos && lastUnderscore + 1 < label.size())
            label = label.substr(lastUnderscore + 1);
        if (!label.empty()) label[0] = (char)toupper((unsigned char)label[0]);
        label = LocString(LocKeyForClass(cls, false), label);

        UiRow row;
        row.label = label;
        row.action = UI_ACT_PICK_UNIT;

        {
            auto wq = g_unitClassWeapon.find(cls);
            const char* wname = "(none)";
            int hasExpl = 0;
            if (wq != g_unitClassWeapon.end() && wq->second >= 0
                && (size_t)wq->second < g_weaponTable.size())
            {
                wname = g_weaponTable[(size_t)wq->second].name.c_str();
                hasExpl = (int)g_weaponTable[(size_t)wq->second].hasExplosion;
            }
            checkpointf("M151 roster: \"%s\" body=%u weapon=\"%s\" hasExplosion=%d",
                cls.c_str(), (unsigned)g_classBodyModel[cls], wname, hasExpl);
        }
        scr.rows.push_back(row);
        g_uiUnitRoster.push_back(cls);
    }
    if (scr.rows.empty())
    {
        UiRow row; row.label = "NO CLASSES RESOLVED"; row.selectable = false;
        scr.rows.push_back(row);
    }
    UiPush(scr);
}

static void UiOpenPostSelect(int playerTeam)
{
    g_uiPostRows.clear();
    UiScreenState scr;
    scr.id = UI_SCREEN_POST;
    scr.title = "Command Post";
    scr.prompt = "";
    scr.pausesGame = false;
    for (size_t i = 0; i < g_commandPosts.size(); ++i)
    {
        const CommandPostState& cp = g_commandPosts[i];
        if (!cp.mapIcon) continue;
        UiRow row;
        std::string label = cp.name;
        if (!label.empty()) label[0] = (char)toupper((unsigned char)label[0]);
        row.label = label;
        const bool friendly = (cp.team == playerTeam);
        row.selectable = friendly;
        row.enemy = (cp.team > 0 && !friendly);
        row.detail = (cp.hudIndex > 0) ? std::to_string(cp.hudIndex) : std::string();
        row.action = UI_ACT_PICK_POST;
        scr.rows.push_back(row);
        scr.mapX.push_back(cp.position.m_X); scr.mapZ.push_back(cp.position.m_Z);
        g_uiPostRows.push_back((int)i);
    }

    for (size_t vi = 0; vi < g_vehicles.size(); ++vi)
    {
        const VehicleState& v = g_vehicles[vi];
        auto dit = g_vehicleClassDefs.find(v.cls);
        if (!v.alive || v.team != playerTeam || dit == g_vehicleClassDefs.end() || dit->second.spawnPoints.empty()) continue;
        if (g_placedForScripts == nullptr || v.placedIndex >= g_placedForScripts->size()) continue;
        const Vector3& vp = (*g_placedForScripts)[v.placedIndex].position;
        UiRow row;
        row.label = LocString(LocKeyForClass(v.cls, false), v.cls);
        row.selectable = true;
        row.action = UI_ACT_PICK_POST;
        scr.rows.push_back(row);
        scr.mapX.push_back(vp.m_X); scr.mapZ.push_back(vp.m_Z);
        g_uiPostRows.push_back(UI_POST_WALKER_BASE + (int)vi);
    }

    for (size_t r = 0; r < g_uiPostRows.size(); ++r)
        if (g_uiPostRows[r] == g_uiChosenPost && scr.rows[r].selectable) scr.cursor = (int)r;
    UiPush(scr);
}

static bool UiPostRowFriendly(int postRow, int playerTeam)
{
    const int walker = UiPostWalker(postRow);
    if (walker >= 0) return (size_t)walker < g_vehicles.size() && g_vehicles[(size_t)walker].alive && g_vehicles[(size_t)walker].team == playerTeam;
    return postRow >= 0 && (size_t)postRow < g_commandPosts.size() && g_commandPosts[(size_t)postRow].team == playerTeam;
}
static void UiRefreshPostScreen(UiScreenState& scr)
{
    for (size_t r = 0; r < scr.rows.size() && r < g_uiPostRows.size(); ++r)
    {
        const int pr = g_uiPostRows[r];
        scr.rows[r].selectable = UiPostRowFriendly(pr, g_playerTeam);
        if (UiPostWalker(pr) < 0 && pr >= 0 && (size_t)pr < g_commandPosts.size())
            scr.rows[r].enemy = g_commandPosts[(size_t)pr].team > 0 && !scr.rows[r].selectable;
    }
    if (!scr.rows.empty() && !scr.rows[(size_t)scr.cursor].selectable)
        for (size_t r = 0; r < scr.rows.size(); ++r) if (scr.rows[r].selectable) { scr.cursor = (int)r; break; }
}

static void BuildPerUnitAnimModels(std::vector<ModelData>& uniqueModels,
                                   std::vector<PlacedInstance>& placedRef)
{
    if (g_soldierAnimBank0 == nullptr) return;
    uint32_t made = 0;
    for (size_t n = 0; n < g_aiUnits.size(); ++n)
    {
        AIUnitState& au = g_aiUnits[n];
        if (au.placedIndex >= placedRef.size()) continue;
        PlacedInstance& pi = placedRef[au.placedIndex];
        if (au.baseModelIndex >= uniqueModels.size()) continue;
        const ModelData& base = uniqueModels[au.baseModelIndex];
        if (!base.isAnimated) continue;

        ModelData clone = base;

        for (SegmentData& sd : clone.segments)
        {
            if (sd.verts != nullptr && sd.vCount > 0)
            {
                Vector3* ownVerts = new Vector3[sd.vCount];
                memcpy(ownVerts, sd.verts, sizeof(Vector3) * sd.vCount);
                sd.verts = ownVerts;
            }
            if (sd.normals != nullptr && sd.vCount > 0)
            {
                Vector3* ownNormals = new Vector3[sd.vCount];
                memcpy(ownNormals, sd.normals, sizeof(Vector3) * sd.vCount);
                sd.normals = ownNormals;
            }
        }
        clone.textureShareBase = au.baseModelIndex;
        clone.isAnimated = true;
        clone.animBank = g_soldierAnimBank0;
        clone.animCRC = AIPoseAnim(AIPOSE_IDLE);
        uint32_t f0 = 0, b0 = 0;
        g_soldierAnimBank0->GetAnimationMetadata(clone.animCRC, f0, b0);
        clone.animFrameCount = (f0 > 0) ? f0 : 1;
        clone.animLoopsFlag = true;
        clone.isNearBlendSlot = true;
        clone.lastSkinnedFrame = 0xFFFF;
        au.ownModelIndex = uniqueModels.size();
        uniqueModels.push_back(clone);
        {
            BoneWorldTransform hpX; bool hpFound = false;
            ModelData& justAdded = uniqueModels.back();
            UpdateAnimatedModel(justAdded, 0, HP_WEAPONS_BONE_CRC, &hpX, &hpFound);
            if (hpFound) { justAdded.hpWeapons = hpX; justAdded.hpWeaponsValid = true; }
            justAdded.lastSkinnedFrame = 0;
        }
        pi.modelIndex = au.ownModelIndex;
        made++;
    }
    logf("BuildPerUnitAnimModels: MILESTONE 133 - %u per-unit skinned model(s), one per AI unit\n", made);
}

static void BuildPlayerDroidekaBody(std::vector<ModelData>& uniqueModels, const std::vector<PlacedInstance>& placedRef)
{
    if (g_droidekaAnimBank == nullptr || g_classBodyModel.count("cis_inf_droideka")) return;
    for (const AIUnitState& au : g_aiUnits)
    {
        if (au.placedIndex >= placedRef.size() || !placedRef[au.placedIndex].isDroideka) continue;
        if (au.baseModelIndex >= uniqueModels.size()) continue;
        ModelData clone = uniqueModels[au.baseModelIndex];
        for (SegmentData& sd : clone.segments)
        {
            if (sd.verts != nullptr && sd.vCount > 0)
            {
                Vector3* ownVerts = new Vector3[sd.vCount];
                memcpy(ownVerts, sd.verts, sizeof(Vector3) * sd.vCount);
                sd.verts = ownVerts;
            }
            if (sd.normals != nullptr && sd.vCount > 0)
            {
                Vector3* ownNormals = new Vector3[sd.vCount];
                memcpy(ownNormals, sd.normals, sizeof(Vector3) * sd.vCount);
                sd.normals = ownNormals;
            }
        }
        clone.textureShareBase = au.baseModelIndex;
        clone.isAnimated = true;
        clone.animBank = g_droidekaAnimBank;
        clone.animCRC = ANIM_DROIDEKA_IDLE;
        uint32_t f0 = 0, b0 = 0;
        g_droidekaAnimBank->GetAnimationMetadata(clone.animCRC, f0, b0);
        clone.animFrameCount = (f0 > 0) ? f0 : 1;
        clone.animLoopsFlag = true;
        clone.isNearBlendSlot = true;
        clone.lastSkinnedFrame = 0xFFFF;
        g_classBodyModel["cis_inf_droideka"] = uniqueModels.size();
        uniqueModels.push_back(clone);
        logf("M465 player droideka body: model %u (copy of %u)\n", (unsigned)(uniqueModels.size() - 1), (unsigned)au.baseModelIndex);
        return;
    }
    logf("M465 player droideka body: no AI droideka to copy - not offered\n");
}

