struct EventLine { std::string text; float r, g, b, t; };
static std::vector<EventLine> g_eventLines;
static void PushEventLine(const std::string& text, int team, int viewerTeam)
{
    if (g_eventLines.size() >= 4) return;
    float r = 192.0f / 255.0f, g = 192.0f / 255.0f, b = 192.0f / 255.0f;
    if (team > 0 && team == viewerTeam) { r = 1.0f / 255.0f; g = 86.0f / 255.0f; b = 213.0f / 255.0f; }
    else if (team > 0) { r = 200.0f / 255.0f; g = 100.0f / 255.0f; b = 100.0f / 255.0f; }
    g_eventLines.push_back(EventLine{ text, r, g, b, 0.0f });
    checkpointf("EVMSG \"%s\" (team %d, viewer %d)", text.c_str(), team, viewerTeam);
}

static std::string FormatEventLine(const std::string& fmt, const std::string& a, const std::string& b = std::string())
{
    std::string out; int k = 0;
    for (size_t i = 0; i < fmt.size(); ++i)
        if (fmt[i] == '%' && i + 1 < fmt.size() && fmt[i + 1] == 's') { out += (k++ == 0) ? a : b; ++i; }
        else out += fmt[i];
    return out;
}

static std::string AiDisplayName(size_t aiIdx, int team)
{
    const std::string side = (team >= 0 && (size_t)team < g_teams.size()) ? g_teams[(size_t)team].name : std::string();
    std::vector<std::string> first, last;
    char key[96];
    for (int i = 1; i <= 64 && !side.empty(); ++i)
    {
        snprintf(key, sizeof(key), "common.sides.%s.firstnames.%02d", side.c_str(), i);
        const std::string f = LocString(key, ""); if (!f.empty()) first.push_back(f);
        snprintf(key, sizeof(key), "common.sides.%s.lastnames.%02d", side.c_str(), i);
        const std::string l = LocString(key, ""); if (!l.empty()) last.push_back(l);
    }
    uint32_t h = (uint32_t)aiIdx * 2654435761u; h ^= h >> 15; h *= 2246822519u; h ^= h >> 13;
    char buf[64];
    if (!first.empty() && !last.empty()) return first[h % first.size()] + " " + last[(h >> 8) % last.size()];
    if (!first.empty()) { snprintf(buf, sizeof(buf), "%s %u", first[h % first.size()].c_str(), 100u + (h >> 8) % 900u); return buf; }
    snprintf(buf, sizeof(buf), "%c%c %u", 'A' + (char)(h % 26), 'A' + (char)((h >> 5) % 26), 100u + (h >> 10) % 900u);
    return buf;
}
