static int GetAIUnitTeamByHandle(void* handle)
{
    size_t idx;
    if (!IsAIUnitHandle(handle, idx)) return -1;
    const AIUnitState& au = g_aiUnits[idx];
    if (g_placedForScripts == nullptr || au.placedIndex >= g_placedForScripts->size()) return -1;
    return (*g_placedForScripts)[au.placedIndex].team;
}

