struct SaberSound { const char* prop; float gain, pitch; const char* samples[5]; };
static const SaberSound kSaberSounds[] = {
    { "saber_swing", 0.8f, 1.05f, { "ltsaberswing02", "ltsaberswing03" } },
    { "saber_attack_three", 0.8f, 1.05f, { "ltsaberswingdbl01" } },
    { "saber_double", 0.8f, 1.05f, { "saber_double", "ltsaberswing01", "ltsaberswing04", "ltsaberswing06", "ltsaberswingdbl01" } },
    { "saber_triple", 0.8f, 1.05f, { "saber_triple" } },
    { "imp_weap_lightsabre_block", 0.6f, 1.15f, { "ltsaberswing03", "ltsaberswing05" } },
    { "imp_weap_lightsabre_deflect", 1.0f, 1.0f, { "saber_deflect01", "saber_deflect02", "saber_deflect03" } },
    { "imp_weap_lightsabre_hit", 1.0f, 1.0f, { "saber_deflect01", "saber_deflect02", "saber_deflect03" } },
    { "saber_throw", 0.6f, 1.05f, { "saber_throw" } },
};
static void PlaySaberSound(const std::string& prop)
{
    for (const SaberSound& ss : kSaberSounds)
    {
        if (strcasecmp(prop.c_str(), ss.prop) != 0) continue;
        int n = 0; while (n < 5 && ss.samples[n] != nullptr) ++n;
        auto it = g_soundClipIndexByName.find(ss.samples[rand() % n]);
        if (it == g_soundClipIndexByName.end()) { static int s_miss = 0; if (++s_miss <= 5) checkpointf("HEROES sound \"%s\": sample not loaded", ss.prop); return; }
        PlaySoundClip(it->second, ss.gain, SOUND_OWNER_PLAYER_THROW, ss.pitch);
        return;
    }
}

static bool PlayerDeflects(const Vector3& from)
{
    if (g_pc.st < 0 || !g_pc.deflect) return false;
    const float dx = from.m_X - g_pc.pos.m_X, dz = from.m_Z - g_pc.pos.m_Z;
    float a = (atan2f(-dx, -dz) - g_pc.yaw) * 57.29578f;
    while (a > 180.0f) a -= 360.0f;
    while (a < -180.0f) a += 360.0f;
    if (!PlayerComboAngleIn(a, g_pc.defMin, g_pc.defMax)) return false;
    if (++g_pc.deflects <= 20 || g_pc.deflects % 50 == 0) checkpointf("HEROES deflected a shot (%.0f deg off the facing, #%u)", a, g_pc.deflects);
    PlaySaberSound("imp_weap_lightsabre_deflect");
    return true;
}
