static std::string ComboCharacterFor(const std::string& cls)
{
    auto it = g_unitClassAnimName.find(cls);
    if (it != g_unitClassAnimName.end() && !it->second.empty()) return it->second;
    return AnimCharacterTypeForClass(cls);
}

static bool PlayerComboAngleIn(float a, float lo, float hi)
{
    for (float k = -360.0f; k <= 360.0f; k += 360.0f) if (a + k >= lo && a + k <= hi) return true;
    return false;
}
static bool PlayerComboOp(char op, float v, float ref)
{
    switch (op) { case '>': return v > ref; case '<': return v < ref; case 'g': return v >= ref; case 'l': return v <= ref; default: return true; }
}
static void PlayerComboEnter(const WeaponStats& w, int idx, const std::string& character)
{

    const int prevSt = g_pc.st;
    const float prevT = g_pc.t;
    const std::string prevAnim = g_pc.anim;
    g_pc.entryPos = g_pc.pos;
    g_pc.st = idx; g_pc.t = 0.0f; g_pc.latched = -1; g_pc.latchAt = -1.0f; g_pc.hitN = 0; g_pc.bladeValid = false; ++g_pc.serial;
    g_pc.animLen = 0.0f; g_pc.anim.clear();
    g_pc.clipOffset = 0.0f;
    if (idx < 0 || (size_t)idx >= w.jedi.states.size()) return;
    const combo::State& st = w.jedi.states[(size_t)idx];
    if (!st.restart && prevSt >= 0 && !prevAnim.empty() && prevAnim == st.anim) g_pc.clipOffset = prevT;
    g_pc.restartPending = st.restart;

    if (idx != w.jedi.idle)
    {
        std::string baseAnim = !st.anim.empty() ? st.anim : (!st.animLower.empty() ? st.animLower : st.animUpper);
        for (const char* suf : { "_upper", "_lower" })
        {
            const size_t n = strlen(suf);
            if (baseAnim.size() > n && baseAnim.compare(baseAnim.size() - n, n, suf) == 0) { baseAnim.erase(baseAnim.size() - n); break; }
        }
        g_pc.anim = baseAnim;
    }
    if (!st.sound.empty()) PlaySaberSound(st.sound);
    if (!st.anim.empty())
    {
        MeleeState ms; ms.anim = st.anim;
        const ResolvedAnim* clip = MeleeClipFor(character, w, ms);
        g_pc.animLen = clip != nullptr ? (float)clip->frames / 30.0f : 0.0f;
        if (clip == nullptr && !st.anim.empty())
        {

            static int s_clipMissLog = 0;
            if (++s_clipMissLog <= 12)
            {
                AnimPosture mp; std::string ma; MeleeSplitAnim(st.anim, mp, ma);
                const int mwt = AnimWeaponTypeForWeapon(w);
                const std::string mch = character.empty() ? "human" : character;
                const std::string base = mch + "_" + kAnimWeaponName[mwt] + "_" + kAnimPostureName[mp] + "_" + ma;
                checkpointf("HEROES clip MISS \"%s\": state %s char \"%s\" wt %s posture %s base \"%s\" banks %u",
                            st.anim.c_str(), st.name.c_str(), mch.c_str(), kAnimWeaponName[mwt], kAnimPostureName[mp],
                            base.c_str(), (unsigned)g_animBanks.size());
                for (const AnimationBank* mb : g_animBanks)
                    for (const char* suf : { "_full", "_upper", "_lower", "" })
                    {
                        const std::string full = base + suf;
                        uint32_t mf = 0, mbn = 0;
                        if (mb->GetAnimationMetadata(CRC::CalcLowerCRC(full.c_str()), mf, mbn) && mf > 0)
                            checkpointf("  HEROES clip MISS: a bank HAS \"%s\" (%u frames)", full.c_str(), mf);
                    }
            }
        }
    }
    static uint32_t s_n = 0;
    if (++s_n <= 40 || s_n % 100 == 0) checkpointf("HEROES combo -> %s (clip \"%s\" %.2f s)", st.name.c_str(), st.anim.c_str(), g_pc.animLen);
}
static void PlayerComboTick(const WeaponStats& w, const PlayerComboIn& in, const std::string& character,
                            std::vector<PlacedInstance>& placedRef, const std::vector<ModelData>& uniqueModels, size_t bodyModel)
{
    const combo::Combo& cb = w.jedi;
    g_pc.energySpend = 0.0f;
    if (cb.idle < 0) { g_pc.st = -1; return; }
    if (g_pc.st < 0 || (size_t)g_pc.st >= cb.states.size()) PlayerComboEnter(w, cb.idle, character);

    bool press[combo::B_COUNT], release[combo::B_COUNT];
    for (int b = 0; b < combo::B_COUNT; ++b)
    {
        press[b] = in.down[b] && !g_pc.prevDown[b];
        release[b] = !in.down[b] && g_pc.prevDown[b];
        g_pc.downT[b] = in.down[b] ? g_pc.downT[b] + in.dt : 0.0f;
    }
    if (in.posture != g_pc.lastPosture) { g_pc.lastPosture = in.posture; g_pc.postureT = 0.0f; } else g_pc.postureT += in.dt;
    g_pc.t += in.dt;

    const combo::State& st = cb.states[(size_t)g_pc.st];
    const bool endless = st.duration.set && st.duration.v <= 0.0f;

    const float clipLeft = (g_pc.animLen > g_pc.clipOffset) ? g_pc.animLen - g_pc.clipOffset : 0.0f;
    const float stateLen = st.duration.set ? (endless ? 1e9f : st.duration.At(g_pc.animLen, 0.0f))
                                           : (g_pc.animLen > 0.0f ? (clipLeft > 0.02f ? clipLeft : g_pc.animLen) : 0.4f  );
    auto buttonOk = [&](const combo::Cond& c) -> bool
    {
        if (c.anyButton) { for (int b = 0; b < combo::B_COUNT; ++b) if (press[b]) return true; return false; }
        if (c.button == combo::B_NONE) return true;
        const int b = c.button;
        switch (c.mode)
        {
            case combo::BM_PRESS: return press[b];
            case combo::BM_RELEASE: return release[b];
            case combo::BM_DOWN: return in.down[b];
            case combo::BM_UP: return !in.down[b];
            case combo::BM_HOLD: return in.down[b] && g_pc.downT[b] >= 0.3f;
            case combo::BM_TAP: return release[b] && g_pc.downT[b] < 0.3f;
            default: return press[b];
        }
    };
    auto groupOk = [&](const combo::Cond& c) -> bool
    {
        if (g_pc.t < c.tStart.At(g_pc.animLen, stateLen)) return false;
        if (c.tEnd.set && g_pc.t > c.tEnd.At(g_pc.animLen, stateLen)) return false;
        if (c.postures != 0 && (c.postures & in.posture) == 0) return false;
        if (c.energyOp && !PlayerComboOp(c.energyOp, in.energyNow, c.energy)) return false;
        if (c.thrustOp && !PlayerComboOp(c.thrustOp, in.thrust, c.thrust)) return false;
        if (c.hasAngle && (in.thrust < 0.1f || !PlayerComboAngleIn(in.thrustAngDeg, c.angMin, c.angMax))) return false;
        if (c.velYOp && !PlayerComboOp(c.velYOp, in.vertSpeed, c.velY)) return false;
        if (c.tipOp && !PlayerComboOp(c.tipOp, g_pc.postureT, c.timeInPosture)) return false;
        return buttonOk(c);
    };
    int go = -1;
    for (size_t i = 0; i < st.transitions.size() && go < 0; ++i)
    {
        const combo::Transition& tr = st.transitions[i];
        if (tr.groups.empty() || (g_pc.latched >= 0 && g_pc.latched <= (int)i)) continue;
        if (tr.energyCost > 0.0f && in.energyNow < tr.energyCost) continue;
        for (const combo::Cond& c : tr.groups)
        {
            if (!groupOk(c)) continue;
            const float at = c.hasBreak ? c.brk.At(g_pc.animLen, stateLen) : stateLen;
            if (g_pc.t >= at) go = (int)i;
            else if (g_pc.latched < 0 || (int)i < g_pc.latched) { g_pc.latched = (int)i; g_pc.latchAt = at; }
            break;
        }
    }
    if (go < 0 && g_pc.latched >= 0 && g_pc.t >= g_pc.latchAt) go = g_pc.latched;

    if (st.mustShowOneFrame && g_pc.t < (1.0f / 30.0f)) { go = -1; g_pc.latched = -1; }
    if (go < 0 && g_pc.t >= stateLen)
    {
        if (g_pc.latched >= 0) go = g_pc.latched;
        else for (size_t i = 0; i < st.transitions.size(); ++i) if (st.transitions[i].groups.empty()) { go = (int)i; break; }
        if (go < 0) { PlayerComboEnter(w, cb.idle, character); go = -2; }
    }

    g_pc.energyOverride = st.hasEnergyRestore && !st.energyFromSoldier;
    g_pc.energyRate = st.energyRestore;
    const bool lockNow = st.inputLockSec >= 0.0f && (st.inputLockSec == 0.0f || g_pc.t <= st.inputLockSec);
    bool all = false, exJump = false, exCrouch = false, exSprint = false;
    for (const std::string& l : st.inputLock)
    {
        if (strcasecmp(l.c_str(), "All") == 0) all = true;
        else if (strcasecmp(l.c_str(), "!Jump") == 0) exJump = true;
        else if (strcasecmp(l.c_str(), "!Crouch") == 0) exCrouch = true;
        else if (strcasecmp(l.c_str(), "!Sprint") == 0) exSprint = true;
        else if (strcasecmp(l.c_str(), "Jump") == 0) exJump = false;
    }
    auto locks = [&](const char* n, bool ex) { if (!lockNow) return false; if (all) return !ex;
        for (const std::string& l : st.inputLock) if (strcasecmp(l.c_str(), n) == 0) return true; return false; };
    g_pc.lockJump = locks("Jump", exJump); g_pc.lockCrouch = locks("Crouch", exCrouch); g_pc.lockSprint = locks("Sprint", exSprint);
    g_pc.lockAll = lockNow && all;
    g_pc.deflect = st.deflect.on; g_pc.defMin = st.deflect.angMin; g_pc.defMax = st.deflect.angMax;
    g_pc.pos = in.pos; g_pc.yaw = in.bodyYaw;
    g_pc.aligned = st.alignedToThrust && g_pc.st != cb.idle;
    g_pc.turnFactor = st.turnFactor >= 0.0f ? st.turnFactor : 1.0f;
    g_pc.move = st.animatedMove && g_pc.st != cb.idle && !(st.until && groupOk(st.untilCond));
    {
        const float rel = in.thrustAngDeg * 0.017453293f;
        g_pc.moveFwd = st.velZ + st.velFromThrust * in.thrust * cosf(rel);
        g_pc.moveSide = st.velX + st.velFromStrafe * in.thrust * sinf(rel);
    }

    if (!st.attacks.empty() && bodyModel < uniqueModels.size())
    {
        PlacedInstance me; me.position = in.pos; me.rotation = ModelQuatFromFacingYaw(in.bodyYaw); me.team = in.team;
        Vector3 bp, bd;
        const bool bladeOk = MeleeBladeWorld(me, uniqueModels[bodyModel], w.modelIndex < uniqueModels.size() ? &uniqueModels[w.modelIndex] : nullptr, bp, bd);
        const float prevT = g_pc.t - in.dt;
        for (const combo::Attack& a : st.attacks)
        {
            const float t0 = a.t0.At(g_pc.animLen, stateLen), t1 = a.t1.At(g_pc.animLen, stateLen);
            if (!bladeOk || g_pc.t < t0 || prevT > t1) continue;
            const float len = (a.lengthFromEdge ? a.length : a.length) + 0.2f;
            Vector3 segs[2][2]; int nSeg = 0;
            auto addSeg = [&](const Vector3& p, const Vector3& d)
            {
                segs[nSeg][0] = Vector3(p.m_X - 0.2f * d.m_X, p.m_Y - 0.2f * d.m_Y, p.m_Z - 0.2f * d.m_Z);
                segs[nSeg][1] = Vector3(segs[nSeg][0].m_X + len * d.m_X, segs[nSeg][0].m_Y + len * d.m_Y, segs[nSeg][0].m_Z + len * d.m_Z);
                ++nSeg;
            };
            addSeg(bp, bd);
            if (g_pc.bladeValid)
            {
                Vector3 mp((bp.m_X + g_pc.bladeP.m_X) * 0.5f, (bp.m_Y + g_pc.bladeP.m_Y) * 0.5f, (bp.m_Z + g_pc.bladeP.m_Z) * 0.5f);
                Vector3 md(bd.m_X + g_pc.bladeD.m_X, bd.m_Y + g_pc.bladeD.m_Y, bd.m_Z + g_pc.bladeD.m_Z);
                const float ml = sqrtf(md.m_X * md.m_X + md.m_Y * md.m_Y + md.m_Z * md.m_Z);
                if (ml > 1e-4f) addSeg(mp, Vector3(md.m_X / ml, md.m_Y / ml, md.m_Z / ml));
            }
            const float reach = 0.4f + a.width;
            for (size_t oi = 0; oi < g_aiUnits.size() && g_pc.hitN < 16; ++oi)
            {
                const AIUnitState& o = g_aiUnits[oi];
                if (o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
                const PlacedInstance& op = placedRef[o.placedIndex];
                if (op.team < 0 || op.inVehicle || !IsHostile(in.team, op.team)) continue;
                bool seen = false; for (int k = 0; k < g_pc.hitN; ++k) if (g_pc.hits[k] == (int)oi) seen = true;
                if (seen) continue;
                const Vector3 lo(op.position.m_X, op.position.m_Y + 0.4f, op.position.m_Z), hi(op.position.m_X, op.position.m_Y + 1.45f, op.position.m_Z);
                bool hit = false;
                for (int k = 0; k < nSeg && !hit; ++k) hit = MeleeSegSegDist2(segs[k][0], segs[k][1], lo, hi) <= reach * reach;
                if (!hit) continue;
                g_pc.hits[g_pc.hitN++] = (int)oi;
                const float dmg = a.damage * (op.isDroideka ? 1.0f : w.meleePersonScale);
                checkpointf("HEROES saber %s hit AI %u for %.0f", st.name.c_str(), (unsigned)oi, dmg);
                PlaySaberSound("imp_weap_lightsabre_hit");
                PlayerHitMarker(op.team, false);
                g_damageByPlayer = true;
                ApplyDamageToAIUnit(oi, dmg, placedRef);
                g_damageByPlayer = false;
            }
        }
        g_pc.bladeValid = bladeOk;
        if (bladeOk) { g_pc.bladeP = bp; g_pc.bladeD = bd; }
    }
    for (int b = 0; b < combo::B_COUNT; ++b) g_pc.prevDown[b] = in.down[b];
    if (go != -1 && g_pc.move && g_pc.st >= 0)
    {
        static uint32_t s_ln = 0;
        const float ddx = in.pos.m_X - g_pc.entryPos.m_X, ddz = in.pos.m_Z - g_pc.entryPos.m_Z;
        if (++s_ln <= 12) checkpointf("HEROES lunge %s: %.2f m along the facing, %.2f across (thrust %.2f)", st.name.c_str(),
            -ddx * sinf(in.bodyYaw) - ddz * cosf(in.bodyYaw), ddx * cosf(in.bodyYaw) - ddz * sinf(in.bodyYaw), in.thrust);
    }
    if (go >= 0)
    {
        const combo::Transition& tr = st.transitions[(size_t)go];
        g_pc.energySpend += tr.energyCost;
        PlayerComboEnter(w, tr.to >= 0 ? tr.to : cb.idle, character);
    }
}

static void MeleeEnterState(AIUnitState& au, const PlacedInstance& pi, const WeaponStats& w, int idx, bool fromIdle,
                            const Vector3& playerPos)
{
    au.meleeState = idx;
    au.meleeStateClock = 0.0f;
    au.meleeFireQueued = false;
    au.meleeHitN = 0;
    au.meleeBladeValid = false;
    if (idx < 0) return;
    const MeleeState& st = w.combo.states[(size_t)idx];
    if (fromIdle || st.restart) { au.meleeAnimClock = 0.0f; au.animLastCRC = 0; }
    if (fromIdle) { static uint32_t s_swings = 0; ++s_swings; if (s_swings <= 5 || s_swings % 50 == 0) checkpointf("MELEE swing #%u by %s", s_swings, pi.unitClass.c_str()); }
    const ResolvedAnim* clip = MeleeClipFor(pi.animCharacterType, w, st);
    au.meleeAnimLen = clip != nullptr ? (float)clip->frames / 30.0f   : 0.0f;
    if (st.swingSound)
    {
        const float dx = pi.position.m_X - playerPos.m_X, dy = pi.position.m_Y - playerPos.m_Y, dz = pi.position.m_Z - playerPos.m_Z;
        PlayRealThrowSoundFrom(sqrtf(dx * dx + dy * dy + dz * dz), SOUND_OWNER_NONE);
    }
}

static void MeleeFirePress(AIUnitState& au, const PlacedInstance& pi, const WeaponStats& w, const Vector3& playerPos)
{
    if (w.combo.start < 0) return;
    if (au.meleeState < 0) { MeleeEnterState(au, pi, w, w.combo.start, true, playerPos); return; }
    const MeleeState& st = w.combo.states[(size_t)au.meleeState];
    if (st.onFire == -2) return;
    const float len = st.duration > 0.0f ? (st.durationFromAnim ? st.duration * au.meleeAnimLen : st.duration)
                                         : fmaxf(0.0f, au.meleeAnimLen - au.meleeAnimClock + au.meleeStateClock);
    if (au.meleeStateClock >= st.fireStart && au.meleeStateClock <= len - st.fireEndFromEnd) au.meleeFireQueued = true;
}

static void UpdateAIMelee(size_t ui, std::vector<PlacedInstance>& placedRef, const std::vector<ModelData>& uniqueModels,
                          const WeaponStats& w, float deltaSec, const Vector3& playerPos, int playerTeam,
                          float& playerHealth, bool& outPlayerKilled)
{
    AIUnitState& au = g_aiUnits[ui];
    if (au.meleeState < 0 || (size_t)au.meleeState >= w.combo.states.size()) { au.meleeState = -1; return; }
    PlacedInstance& pi = placedRef[au.placedIndex];
    const MeleeState& st = w.combo.states[(size_t)au.meleeState];
    const float prevAnim = au.meleeAnimClock;
    au.meleeStateClock += deltaSec;
    au.meleeAnimClock += deltaSec;

    const size_t bodyIdx = au.ownModelIndex < uniqueModels.size() ? au.ownModelIndex : pi.modelIndex;
    const size_t wModel = w.modelIndex;
    Vector3 bp, bd;
    const bool bladeOk = bodyIdx < uniqueModels.size()
        && MeleeBladeWorld(pi, uniqueModels[bodyIdx], wModel < uniqueModels.size() ? &uniqueModels[wModel] : nullptr, bp, bd);
    for (const MeleeAttack& a : st.attacks)
    {
        float t0 = a.fromAnim ? a.t0 * au.meleeAnimLen : a.t0, t1 = a.fromAnim ? a.t1 * au.meleeAnimLen : a.t1;
        if (au.meleeAnimLen > 0.0f) { t0 = fminf(t0, au.meleeAnimLen); t1 = fminf(t1, au.meleeAnimLen); }
        if (!bladeOk || au.meleeAnimClock < t0 || prevAnim > t1) continue;
        const float len = a.length + 0.2f;
        Vector3 segs[2][2]; int nSeg = 0;
        auto addSeg = [&](const Vector3& p, const Vector3& d)
        {
            segs[nSeg][0] = Vector3(p.m_X - 0.2f * d.m_X, p.m_Y - 0.2f * d.m_Y, p.m_Z - 0.2f * d.m_Z);
            segs[nSeg][1] = Vector3(segs[nSeg][0].m_X + len * d.m_X, segs[nSeg][0].m_Y + len * d.m_Y, segs[nSeg][0].m_Z + len * d.m_Z);
            ++nSeg;
        };
        addSeg(bp, bd);
        if (au.meleeBladeValid)
        {
            Vector3 mp((bp.m_X + au.meleeBladeP.m_X) * 0.5f, (bp.m_Y + au.meleeBladeP.m_Y) * 0.5f, (bp.m_Z + au.meleeBladeP.m_Z) * 0.5f);
            Vector3 md(bd.m_X + au.meleeBladeD.m_X, bd.m_Y + au.meleeBladeD.m_Y, bd.m_Z + au.meleeBladeD.m_Z);
            const float ml = sqrtf(md.m_X * md.m_X + md.m_Y * md.m_Y + md.m_Z * md.m_Z);
            if (ml > 1e-4f) addSeg(mp, Vector3(md.m_X / ml, md.m_Y / ml, md.m_Z / ml));
        }

        const float reach = 0.4f + a.width;
        auto hitBy = [&](const Vector3& feet, float top) -> bool
        {
            const Vector3 lo(feet.m_X, feet.m_Y + 0.4f, feet.m_Z), hi(feet.m_X, feet.m_Y + top - 0.4f, feet.m_Z);
            for (int k = 0; k < nSeg; ++k) if (MeleeSegSegDist2(segs[k][0], segs[k][1], lo, hi) <= reach * reach) return true;
            return false;
        };
        auto already = [&](int id) { for (int k = 0; k < au.meleeHitN; ++k) if (au.meleeHit[k] == id) return true; return false; };
        const float dmg = a.damage * w.meleePersonScale;
        for (size_t oi = 0; oi < g_aiUnits.size() && au.meleeHitN < 8; ++oi)
        {
            if (oi == ui) continue;
            const AIUnitState& o = g_aiUnits[oi];
            if (o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
            const PlacedInstance& op = placedRef[o.placedIndex];
            if (op.team < 0 || op.inVehicle || !IsHostile(pi.team, op.team) || already((int)oi)) continue;
            if (!hitBy(op.position, 1.85f)) continue;
            au.meleeHit[au.meleeHitN++] = (int)oi;
            checkpointf("MELEE AI %u (%s) hit AI %u for %.0f (%s)", (unsigned)ui, pi.unitClass.c_str(), (unsigned)oi, dmg, st.name.c_str());
            g_damageByAi = (int)ui;
            {
                const char* const savedSrc = g_damageSource;
                g_damageSource = w.name.c_str();
                ApplyDamageToAIUnit(oi, dmg, placedRef);
                g_damageSource = savedSrc;
            }
            g_damageByAi = -2;
        }
        if (au.meleeHitN < 8 && playerTeam >= 1 && playerHealth > 0.0f && IsHostile(pi.team, playerTeam) && !already(-1)
            && hitBy(playerPos, 1.85f))
        {
            au.meleeHit[au.meleeHitN++] = -1;
            checkpointf("MELEE AI %u (%s) hit the PLAYER for %.0f (%s)", (unsigned)ui, pi.unitClass.c_str(), dmg, st.name.c_str());
            playerHealth -= PlayerShieldAbsorb(dmg);
            g_lastPlayerAttackerPos = pi.position;
            g_lastPlayerAttackerAi = (int)ui;
            NoteAttackerHint((int)ui, pi.position);
            if (playerHealth <= 0.0f) { playerHealth = 0.0f; outPlayerKilled = true; }
        }
    }
    au.meleeBladeValid = bladeOk;
    if (bladeOk) { au.meleeBladeP = bp; au.meleeBladeD = bd; }

    const float dur = st.duration > 0.0f ? (st.durationFromAnim ? st.duration * au.meleeAnimLen : st.duration)
                                         : fmaxf(0.0f, au.meleeAnimLen - (au.meleeAnimClock - au.meleeStateClock));
    if (au.meleeFireQueued && st.fireBreak >= 0.0f && au.meleeStateClock >= st.fireBreak && au.meleeStateClock < dur)
    {

        const int to = st.onFire >= 0 ? st.onFire : w.combo.start;
        MeleeEnterState(au, pi, w, to, st.onFire < 0, playerPos);
        return;
    }
    if (au.meleeStateClock >= dur)
    {
        if (st.next >= 0) MeleeEnterState(au, pi, w, st.next, false, playerPos);
        else if (au.meleeFireQueued) MeleeEnterState(au, pi, w, w.combo.start, true, playerPos);
        else au.meleeState = -1;
    }
}

static void UpdateAICombat(std::vector<PlacedInstance>& placedRef, const std::vector<ModelData>& uniqueModels,
    float deltaSec, const Vector3& playerPos, int playerTeam, float& playerHealth, bool& outPlayerKilledThisCall,
    const TerrainData& terrainData)
{
    outPlayerKilledThisCall = false;
    uint32_t combatThinksThisFrame = 0;
    uint32_t combatShotsThisFrame = 0;
    const float DEG2RAD = 3.14159265f / 180.0f;
    const float AI_EYE_HEIGHT = 1.6f;
    const float AIM_POINT_HEIGHT = 1.2f;

    for (size_t ui = 0; ui < g_aiUnits.size(); ++ui)
    {

        struct CombatPhaseClock {
            int phase = 0; uint64_t mark = sceKernelGetProcessTimeWide();
            void to(int p) { const uint64_t n = sceKernelGetProcessTimeWide(); g_combatPhaseUs[phase] += n - mark; mark = n; phase = p; }
            uint64_t start = mark; size_t unit = 0;
            ~CombatPhaseClock()
            {
                const uint64_t n = sceKernelGetProcessTimeWide();
                g_combatPhaseUs[phase] += n - mark;
                if (n - start > g_combatWorstUs) { g_combatWorstUs = n - start; g_combatWorstUnit = unit; g_combatWorstPhase = phase; }
            }
        } phaseClock;
        phaseClock.unit = ui;
        AIUnitState& shooter = g_aiUnits[ui];
        if (shooter.fireCooldown > 0.0f) shooter.fireCooldown -= deltaSec;
        if (shooter.placedIndex >= placedRef.size()) continue;
        PlacedInstance& shooterPi = placedRef[shooter.placedIndex];
        if (shooterPi.team < 0 || !IsCombatTeam(shooterPi.team)) continue;
        if (shooterPi.inVehicle) continue;

        if (g_aiUnits[ui].life != AI_LIFE_ALIVE) continue;

        const WeaponStats* meleeW = (shooterPi.weaponIndex >= 0 && (size_t)shooterPi.weaponIndex < g_weaponTable.size()
                                     && g_weaponTable[(size_t)shooterPi.weaponIndex].isMelee) ? &g_weaponTable[(size_t)shooterPi.weaponIndex] : nullptr;
        if ((kDiagVerbose || g_heroAiDiag) && shooterPi.unitClass.find("_hero_") != std::string::npos)
        {
            static float s_hai = 0.0f; s_hai += deltaSec;
            if (s_hai > 5.0f && (ui % 3) == 0)
                checkpointf("HERO AI \"%s\": weapon %d \"%s\" melee %d range %.1f target %d hidden %d mode %d meleeState %d dist %.1f pos (%.0f,%.0f,%.0f) hint %d veh %d why %d",
                            shooterPi.unitClass.c_str(), shooterPi.weaponIndex,
                            (shooterPi.weaponIndex >= 0 && (size_t)shooterPi.weaponIndex < g_weaponTable.size()) ? g_weaponTable[(size_t)shooterPi.weaponIndex].name.c_str() : "-",
                            meleeW ? 1 : 0, meleeW ? meleeW->maxRange : 0.0f, (int)shooter.haveCachedTarget, (int)shooter.targetHidden, shooter.cmMode, shooter.meleeState,
                            sqrtf((shooter.cachedTargetPos.m_X - shooterPi.position.m_X) * (shooter.cachedTargetPos.m_X - shooterPi.position.m_X)
                                + (shooter.cachedTargetPos.m_Z - shooterPi.position.m_Z) * (shooter.cachedTargetPos.m_Z - shooterPi.position.m_Z)),
                            shooterPi.position.m_X, shooterPi.position.m_Y, shooterPi.position.m_Z,
                            shooter.hintNodeIdx, shooter.vehicle, (int)shooter.why);
            if (s_hai > 5.0f && ui + 1 == g_aiUnits.size()) s_hai = 0.0f;
        }
        if (meleeW != nullptr && shooter.meleeState >= 0)
            UpdateAIMelee(ui, placedRef, uniqueModels, *meleeW, deltaSec, playerPos, playerTeam, playerHealth, outPlayerKilledThisCall);

        if (shooter.actionTimer > 0.0f)
        {
            shooter.actionElapsed += deltaSec;
            shooter.actionTimer -= deltaSec;
            shooter.throwPoseTimer = fmaxf(shooter.throwPoseTimer, shooter.actionTimer);
            if (!shooter.actionReleased && shooter.actionElapsed >= shooter.actionReleaseDelay
                && shooter.actionWeapon >= 0 && (size_t)shooter.actionWeapon < g_weaponTable.size())
            {
                shooter.actionReleased = true;
                const Vector3 hand(shooterPi.position.m_X, shooterPi.position.m_Y + 1.3f, shooterPi.position.m_Z);
                SpawnRealOrdnance(hand, shooter.actionDir, shooter.actionWeapon,  false, ui, 0.0f);
                {
                    const float ldx = hand.m_X - playerPos.m_X, ldy = hand.m_Y - playerPos.m_Y, ldz = hand.m_Z - playerPos.m_Z;
                    PlayRealThrowSoundFrom(sqrtf(ldx * ldx + ldy * ldy + ldz * ldz), (int)ui);
                }
                for (AIUnitState::Ability& ab : shooter.abilities)
                    if (ab.weaponIndex == shooter.actionWeapon)
                    {
                        if (shooter.actionKind == ABIL_DISPENSER) { --ab.reserve; ab.cooldown = 20.0f; }
                        break;
                    }
                ++g_aiAbilityUses[shooter.actionKind];
                checkpointf("M408 AI %s released: unit %u (%s) \"%s\" at %.2fs of %.2fs",
                    AIAbilityName(shooter.actionKind), (unsigned)ui, shooterPi.unitClass.c_str(),
                    g_weaponTable[(size_t)shooter.actionWeapon].name.c_str(), shooter.actionElapsed,
                    shooter.actionElapsed + fmaxf(0.0f, shooter.actionTimer));
            }
            if (shooter.actionTimer <= 0.0f) { shooter.actionKind = 0; shooter.actionTimer = 0.0f; }
            continue;
        }

        if (!shooter.abilitiesReady)
        {
            shooter.abilities.clear();
            auto lit = g_unitClassLoadout.find(shooterPi.unitClass);
            if (lit != g_unitClassLoadout.end())
                for (size_t si = 0; si < lit->second.slotWeapon.size(); ++si)
                {
                    const int wi = lit->second.slotWeapon[si];
                    if (wi < 0 || (size_t)wi >= g_weaponTable.size() || !g_weaponTable[(size_t)wi].offhandWeapon) continue;
                    const WeaponStats& ow = g_weaponTable[(size_t)wi];
                    AIUnitState::Ability ab; ab.weaponIndex = wi;
                    if (ow.isBuffWeapon) ab.kind = ABIL_BUFF;
                    else if (ow.isDebuffWeapon) ab.kind = ABIL_DEBUFF;
                    else if (ow.isPickupType || ow.ordClassLabel == "powerupitem") ab.kind = ABIL_DISPENSER;
                    else if (ow.ordClassLabel == "grenade" || ow.ordClassLabel == "sticky") ab.kind = ABIL_GRENADE;
                    else if (ow.ordClassLabel == "mine" && !ow.isDetonatorType) ab.kind = ABIL_MINE;
                    else continue;
                    const int ammo = (si < lit->second.slotAmmo.size()) ? lit->second.slotAmmo[si] : 0;
                    ab.reserve = ammo > 0 ? ammo : 1;
                    ab.cooldown = 3.0f + 4.0f * ((float)rand() / (float)RAND_MAX);
                    shooter.abilities.push_back(ab);
                }
            shooter.abilitiesReady = true;
        }
        for (AIUnitState::Ability& ab : shooter.abilities)
        {
            if (ab.cooldown > 0.0f) { ab.cooldown -= deltaSec; continue; }
            if (ab.reserve <= 0 || ab.kind == ABIL_GRENADE || ab.kind == ABIL_MINE) continue;
            const WeaponStats& ow = g_weaponTable[(size_t)ab.weaponIndex];
            const Vector3& me = shooterPi.position;
            auto dist2 = [&](const Vector3& o) { const float dx = o.m_X - me.m_X, dz = o.m_Z - me.m_Z; return dx * dx + dz * dz; };
            const bool playerAlly = (playerTeam == shooterPi.team) && playerHealth > 0.0f;
            const bool playerEnemy = (playerTeam != shooterPi.team) && playerTeam > 0 && playerHealth > 0.0f;

            if (ab.kind == ABIL_DISPENSER)
            {

                if (shooter.supportAlly != -2) { ab.cooldown = 0.5f; continue; }

                const float R2 = 75.0f * 75.0f;
                int ally = -2;

                if (playerAlly && g_playerVehicle < 0 && playerHealth < g_soldierMaxHealth && dist2(playerPos) < R2) ally = -1;
                if (ally == -2) { ab.cooldown = 1.0f; continue; }
                shooter.supportAlly = ally;
                shooter.supportTimer = 20.0f;
                ab.cooldown = 0.5f;
                checkpointf("M408 AI dispenser: unit %u (%s) heading to %s%d", (unsigned)ui, shooterPi.unitClass.c_str(),
                    ally == -1 ? "the player" : "unit ", ally == -1 ? 0 : ally);
            }
            else if (ab.kind == ABIL_BUFF || ab.kind == ABIL_DEBUFF)
            {

                const float radius = (ow.buffDebuffConeRadius > 0.0f) ? ow.buffDebuffConeRadius : ow.lockOnRange;
                const float R2 = radius * radius;
                const bool wantAlly = (ab.kind == ABIL_BUFF);
                std::vector<std::pair<float, size_t>> cand;
                for (size_t oi = 0; oi < g_aiUnits.size(); ++oi)
                {
                    const AIUnitState& o = g_aiUnits[oi];
                    if (oi == ui || o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
                    const PlacedInstance& op = placedRef[o.placedIndex];
                    if (op.team <= 0 || (op.team == shooterPi.team) != wantAlly) continue;
                    const float d2 = dist2(op.position);
                    if (d2 <= R2) cand.push_back({ d2, oi });
                }
                const bool playerIn = (wantAlly ? playerAlly : playerEnemy) && dist2(playerPos) <= R2;
                const int count = (int)cand.size() + (playerIn ? 1 : 0);

                const bool use = wantAlly ? (count >= 2 && shooter.haveCachedTarget) : (count >= 1);
                if (!use) { ab.cooldown = 1.0f; continue; }
                std::sort(cand.begin(), cand.end());
                int budget = (ow.buffDebuffMaxTargets > 0) ? ow.buffDebuffMaxTargets : 1, hit = 0;
                if (playerIn && budget > 0)
                {
                    if (wantAlly && ow.isHealthBuff) { g_aiRegenForPlayer.timer = ow.buffDebuffDuration; g_aiRegenForPlayer.value = ow.buffHealthRate; }
                    else if (wantAlly && ow.isOffenseBuff) { g_aiOffenseForPlayer.timer = ow.buffDebuffDuration; g_aiOffenseForPlayer.value = ow.buffOffenseMult; }
                    else if (wantAlly) { g_aiBuffForPlayer.timer = ow.buffDebuffDuration; g_aiBuffForPlayer.value = ow.buffDamageMult; }
                    else          { g_aiPoisonForPlayer.timer = ow.buffDebuffDuration; g_aiPoisonForPlayer.value = ow.debuffDamageRate; }
                    --budget; ++hit;
                }
                for (size_t ci = 0; ci < cand.size() && budget > 0; ++ci, --budget, ++hit)
                {
                    AIUnitState& t = g_aiUnits[cand[ci].second];
                    if (wantAlly && ow.isHealthBuff) { t.regenTimer = fmaxf(t.regenTimer, ow.buffDebuffDuration); t.regenRate = ow.buffHealthRate; }
                    else if (wantAlly && ow.isOffenseBuff) { t.offenseBuffTimer = ow.buffDebuffDuration; t.offenseBuffMult = ow.buffOffenseMult; }
                    else if (wantAlly) { t.defenseBuffTimer = ow.buffDebuffDuration; t.defenseBuffMult = ow.buffDamageMult; }
                    else          { t.poisonTimer = ow.buffDebuffDuration; t.poisonRate = ow.debuffDamageRate; }
                }
                if (wantAlly && ow.buffApplyToOwnerToo && ow.isHealthBuff) { shooter.regenTimer = fmaxf(shooter.regenTimer, ow.buffDebuffDuration); shooter.regenRate = ow.buffHealthRate; }
                else if (wantAlly && ow.buffApplyToOwnerToo && ow.isOffenseBuff) { shooter.offenseBuffTimer = ow.buffDebuffDuration; shooter.offenseBuffMult = ow.buffOffenseMult; }
                else if (wantAlly && ow.buffApplyToOwnerToo) { shooter.defenseBuffTimer = ow.buffDebuffDuration; shooter.defenseBuffMult = ow.buffDamageMult; }
                if (ow.fireSoundClip >= 0)
                {

                    const float adx = me.m_X - playerPos.m_X, ady = me.m_Y - playerPos.m_Y, adz = me.m_Z - playerPos.m_Z;
                    const float dl = sqrtf(adx * adx + ady * ady + adz * adz);
                    if (dl < 400.0f)
                        PlaySoundClip(ow.fireSoundClip, dl <= 11.0f ? 1.0f : 11.0f / (11.0f + 3.5f * (dl - 11.0f)), (int)ui);
                }
                ab.cooldown = fmaxf(ow.shotDelay, 15.0f);

                if (!ow.buffOwnerFx.empty()) SpawnEffect(ow.buffOwnerFx, me, 32);
                ++g_aiAbilityUses[ab.kind];
                checkpointf("M407 AI %s: unit %u (%s) pulsed \"%s\" r=%.1f - %d target(s)%s", AIAbilityName(ab.kind), (unsigned)ui,
                    shooterPi.unitClass.c_str(), ow.name.c_str(), radius, hit, playerIn ? " incl. the player" : "");
            }
        }

        if (shooter.health < shooter.maxHealth)
        {
            const float PICK_R = PLAYER_COLLISION_RADIUS + 1.0f;
            for (auto oit = g_activeOrdnance.begin(); oit != g_activeOrdnance.end(); ++oit)
            {
                if (!oit->stuck || oit->weaponIndex < 0 || (size_t)oit->weaponIndex >= g_weaponTable.size()) continue;
                const WeaponStats& pw = g_weaponTable[(size_t)oit->weaponIndex];
                if (!pw.isPickupType || pw.pickupHealth <= 0.0f) continue;
                const float dx = oit->pos.m_X - shooterPi.position.m_X, dy = oit->pos.m_Y - shooterPi.position.m_Y, dz = oit->pos.m_Z - shooterPi.position.m_Z;
                if (dx * dx + dy * dy + dz * dz > PICK_R * PICK_R) continue;
                shooter.health = fminf(shooter.maxHealth, shooter.health + pw.pickupHealth);
                if (pw.pickupSoundClip >= 0)
                {
                    const float ldx = oit->pos.m_X - playerPos.m_X, ldy = oit->pos.m_Y - playerPos.m_Y, ldz = oit->pos.m_Z - playerPos.m_Z;
                    const float dl = sqrtf(ldx * ldx + ldy * ldy + ldz * ldz);
                    if (dl < 400.0f) PlaySoundClip(pw.pickupSoundClip, dl <= 11.0f ? 1.0f : 11.0f / (11.0f + 3.5f * (dl - 11.0f)), (int)ui);
                }
                g_activeOrdnance.erase(oit);
                checkpointf("M407 AI pickup: unit %u healed to %.0f/%.0f", (unsigned)ui, shooter.health, shooter.maxHealth);
                break;
            }
        }

        WeaponStats wpn;
        if (shooterPi.weaponIndex >= 0 && (size_t)shooterPi.weaponIndex < g_weaponTable.size())
        {
            wpn = g_weaponTable[(size_t)shooterPi.weaponIndex];
        }
        else
        {
            wpn.shotDelay = PlayerWeapon().shotDelay; wpn.maxRange = PlayerWeapon().maxRange;
            wpn.yawSpread = PlayerWeapon().yawSpread; wpn.pitchSpread = PlayerWeapon().pitchSpread;
            wpn.maxDamage = PlayerWeapon().maxDamage; wpn.finalDamage = PlayerWeapon().finalDamage;
            wpn.laserTexIsBlue = (shooterPi.team == 1);
            if (!wpn.laserTexIsBlue) { wpn.r = 253.0f / 255.0f; wpn.g = 43.0f / 255.0f; wpn.b = 43.0f / 255.0f; }
        }

        shooter.combatThinkTimer -= deltaSec;

        const uint32_t COMBAT_THINK_BUDGET_PER_FRAME = 10;
        phaseClock.to(1);
        if (shooter.combatThinkTimer <= 0.0f && combatThinksThisFrame < COMBAT_THINK_BUDGET_PER_FRAME)
        {
            combatThinksThisFrame++;

            {

                const float yw = shooter.aimYawValid ? shooter.aimYaw : 2.0f * atan2f(shooterPi.rotation.m_Y, shooterPi.rotation.m_W) - 3.14159265f;
                const float agentF = AiRulesMode() == AI_RULES_PS2 ? (shooter.haveCachedTarget ? 0.4f : 2.0f) : 1.0f;
                shooter.combatThinkTimer = agentF * kAiTierInterval[AiLodTier(shooterPi.position, playerPos, playerTeam >= 0, -sinf(yw), -cosf(yw))];
            }

            struct AiCand { float cost; Vector3 pos; bool isPlayer; size_t ai; };
            AiCand cands[5]; int nCand = 0;
            auto offer = [&](const AiCand& c) {
                int i = nCand < 5 ? nCand++ : 4;
                if (nCand == 5 && i == 4 && c.cost >= cands[4].cost) return;
                cands[i] = c;
                for (; i > 0 && cands[i].cost < cands[i - 1].cost; --i) std::swap(cands[i], cands[i - 1]);
            };
            const bool shooterInVeh = shooterPi.inVehicle;
            if (playerTeam >= 0 && IsHostile(shooterPi.team, playerTeam) && playerHealth > 0.0f
                && AIPickWeaponFor(shooterPi, g_playerVehicle >= 0) >= 0)
            {
                float r = 1.0f;
                if (g_playerVehicle >= 0 && (size_t)g_playerVehicle < g_vehicles.size())
                { auto vd = g_vehicleClassDefs.find(g_vehicles[(size_t)g_playerVehicle].cls); if (vd != g_vehicleClassDefs.end()) r = vd->second.hullRadius; }
                const float dx = playerPos.m_X - shooterPi.position.m_X, dy = playerPos.m_Y - shooterPi.position.m_Y, dz = playerPos.m_Z - shooterPi.position.m_Z;
                const float d = sqrtf(dx * dx + dy * dy + dz * dz);
                if (d <= AiSightRange(r, true) && (meleeW != nullptr || d <= wpn.maxRange))
                    offer({ AiTargetCost(d, 10, true, shooterInVeh), playerPos, true, (size_t)-1 });
            }
            for (size_t tj = 0; tj < g_aiUnits.size(); ++tj)
            {
                if (tj == ui) continue;
                const AIUnitState& other = g_aiUnits[tj];
                if (other.placedIndex >= placedRef.size()) continue;
                const PlacedInstance& otherPi = placedRef[other.placedIndex];
                if (other.life != AI_LIFE_ALIVE) { if (other.life == AI_LIFE_DYING) ++g_deadTgtSkipped; continue; }
                if (otherPi.team < 0 || !IsCombatTeam(otherPi.team) || !IsHostile(shooterPi.team, otherPi.team)) continue;
                if (other.vehicle >= 0 && other.vehicleSeat >= 1) continue;
                float r = 1.0f;
                if (other.vehicle >= 0 && (size_t)other.vehicle < g_vehicles.size())
                { auto vd = g_vehicleClassDefs.find(g_vehicles[(size_t)other.vehicle].cls); if (vd != g_vehicleClassDefs.end()) r = vd->second.hullRadius; }
                const float dx = otherPi.position.m_X - shooterPi.position.m_X, dy = otherPi.position.m_Y - shooterPi.position.m_Y, dz = otherPi.position.m_Z - shooterPi.position.m_Z;
                const float d = sqrtf(dx * dx + dy * dy + dz * dz);
                if (d > AiSightRange(r, false) || (meleeW == nullptr && d > wpn.maxRange * (shooter.hintKind == 1 && shooter.hintAt ? 2.0f : 1.0f))) continue;
                if (AIPickWeaponFor(shooterPi, otherPi.inVehicle) < 0) continue;
                offer({ AiTargetCost(d, 10, false, shooterInVeh), otherPi.position, false, tj });
            }
            Vector3 targetPos = Vector3(0.0f, 0.0f, 0.0f);
            bool targetIsPlayer = false;
            size_t targetAiIdx = (size_t)-1;

            {

                const float spd = sqrtf(shooter.velX * shooter.velX + shooter.velZ * shooter.velZ);
                const float nr = shooter.firedSinceThink ? 30.0f : fmaxf(8.0f, fminf(fminf(5.0f * spd, 50.0f), 30.0f));
                shooter.firedSinceThink = false;
                if (!shooterPi.inVehicle && !(g_fightOff & 2)) AiHearNoise(shooterPi.position, shooterPi.team, nr, ui, placedRef);
            }
            const bool hadT = shooter.haveCachedTarget;
            const bool prevTP = shooter.cachedTargetIsPlayer; const size_t prevTI = shooter.cachedTargetAiIdx;
            shooter.thinkRan = true; shooter.thinkHadT = hadT; shooter.thinkPrevTP = prevTP; shooter.thinkPrevTI = prevTI;
            shooter.haveCachedTarget = false;

            int nRay = 3;
            if (AiRulesMode() == AI_RULES_PS2 && !(g_fightOff & 32))
            {
                static const int kRays[5] = { 1, 1, 2, 4, 5 };
                const float yw2 = shooter.aimYawValid ? shooter.aimYaw : 2.0f * atan2f(shooterPi.rotation.m_Y, shooterPi.rotation.m_W) - 3.14159265f;
                nRay = kRays[AiLodTier(shooterPi.position, playerPos, playerTeam >= 0, -sinf(yw2), -cosf(yw2))];
            }
            for (int ck = 0; ck < nCand && ck < nRay && !shooter.haveCachedTarget; ++ck)
            {
                targetPos = cands[ck].pos; targetIsPlayer = cands[ck].isPlayer; targetAiIdx = cands[ck].ai;

                Vector3 eyeT = shooterPi.position; eyeT.m_Y += AI_EYE_HEIGHT;
                Vector3 aimPointT = targetPos; aimPointT.m_Y += AIM_POINT_HEIGHT;

                Vector3 toT(aimPointT.m_X - eyeT.m_X, aimPointT.m_Y - eyeT.m_Y, aimPointT.m_Z - eyeT.m_Z);
                float dT = sqrtf(toT.m_X * toT.m_X + toT.m_Y * toT.m_Y + toT.m_Z * toT.m_Z);
                if (dT >= 0.001f)
                {
                    Vector3 dirT(toT.m_X / dT, toT.m_Y / dT, toT.m_Z / dT);
                    float losD; Vector3 losP;

                    float losShort = 0.2f;
                    int tVeh = -1;
                    if (targetIsPlayer) tVeh = g_playerVehicle;
                    else if (targetAiIdx < g_aiUnits.size()) tVeh = g_aiUnits[targetAiIdx].vehicle;
                    if (tVeh >= 0 && (size_t)tVeh < g_vehicles.size())
                    {
                        auto tdit = g_vehicleClassDefs.find(g_vehicles[(size_t)tVeh].cls);
                        if (tdit != g_vehicleClassDefs.end()) losShort = tdit->second.hullRadius + 0.5f;
                    }

                    size_t losPlaced = SIZE_MAX;
                    const bool losBlocked = FireRayHitTest(eyeT, dirT, fmaxf(0.1f, dT - losShort), uniqueModels, placedRef, losD, losP, shooter.placedIndex, true, &losPlaced);
                    const bool hitOwnHull = losBlocked && tVeh >= 0 && (size_t)tVeh < g_vehicles.size() && losPlaced == g_vehicles[(size_t)tVeh].placedIndex;
                    if (!losBlocked || hitOwnHull)
                    {

                        const int pick = AIPickWeaponFor(shooterPi, tVeh >= 0);
                        if (pick >= 0 && pick != shooterPi.weaponIndex) { shooterPi.weaponIndex = pick; shooter.ammoInClip = -1; }
                        shooter.haveCachedTarget = true; shooter.targetHidden = false;
                        shooter.cachedTargetIsPlayer = targetIsPlayer;
                        shooter.cachedTargetAiIdx = targetAiIdx;
                        shooter.cachedTargetPos = targetPos;

                        if (!(g_fightOff & 1) && !targetIsPlayer && targetAiIdx < g_aiUnits.size() && tVeh < 0)
                        {
                            AIUnitState& seen = g_aiUnits[targetAiIdx];
                            if (!seen.haveCachedTarget && seen.life == AI_LIFE_ALIVE)
                            {
                                seen.haveCachedTarget = true; seen.cachedTargetIsPlayer = false; seen.cachedTargetAiIdx = ui;
                                seen.cachedTargetPos = shooterPi.position; seen.noiseSec = 0.0f; seen.lookSec = 0.0f;
                            }
                        }

                        if (!hadT || (targetIsPlayer && !prevTP))
                        {
                            shooter.aimSec = fmaxf(shooter.aimSec, 0.4f);
                            ++g_aiDiagReact;
                        }
                        if (!hadT || prevTP != targetIsPlayer || (!targetIsPlayer && prevTI != targetAiIdx))
                        {
                            const std::string& tcls = targetIsPlayer ? g_playerClassName
                                : (targetAiIdx < g_aiUnits.size() && g_aiUnits[targetAiIdx].placedIndex < placedRef.size())
                                ? placedRef[g_aiUnits[targetAiIdx].placedIndex].unitClass : g_playerClassName;
                            TryChatter(shooterPi.unitClass, shooterPi.position, "AcquiredTarget",
                                       ChatterTargetCtx(tcls, shooterPi.position.m_Y, targetPos.m_Y));
                        }
                    }
                }
            }
        }

        if (shooter.thinkRan)
        {

            shooter.thinkRan = false;
            if (!shooter.haveCachedTarget && shooter.thinkHadT && !(g_fightOff & 16))
            {
                bool alive = false; Vector3 tp;
                if (shooter.thinkPrevTP) { alive = playerHealth > 0.0f; tp = playerPos; }
                else if (shooter.thinkPrevTI < g_aiUnits.size())
                {
                    const AIUnitState& t = g_aiUnits[shooter.thinkPrevTI];
                    alive = t.life == AI_LIFE_ALIVE && t.placedIndex < placedRef.size() && placedRef[t.placedIndex].team >= 0;
                    if (alive) tp = placedRef[t.placedIndex].position;
                }
                const float rng = wpn.maxRange > 0.0f ? wpn.maxRange : 60.0f;
                const float dx = tp.m_X - shooterPi.position.m_X, dz = tp.m_Z - shooterPi.position.m_Z;
                if (alive && dx * dx + dz * dz < (rng + 10.0f) * (rng + 10.0f))
                {
                    shooter.haveCachedTarget = true; shooter.targetHidden = true;
                    shooter.cachedTargetIsPlayer = shooter.thinkPrevTP; shooter.cachedTargetAiIdx = shooter.thinkPrevTI;
                }
            }
        }
        phaseClock.to(2);
        if (shooter.haveCachedTarget && shooter.targetHidden) { shooter.trig.state = 0; shooter.trkValid = false; continue; }
        if (!shooter.haveCachedTarget) { shooter.trig.state = 0; shooter.trkValid = false; continue; }

        bool targetIsPlayer = shooter.cachedTargetIsPlayer;
        Vector3 targetPos = shooter.cachedTargetPos;
        if (!targetIsPlayer)
        {
            if (shooter.cachedTargetAiIdx >= g_aiUnits.size()) { shooter.haveCachedTarget = false; continue; }
            const AIUnitState& tgt = g_aiUnits[shooter.cachedTargetAiIdx];
            if (tgt.placedIndex >= placedRef.size()) { shooter.haveCachedTarget = false; continue; }
            const PlacedInstance& tgtPi = placedRef[tgt.placedIndex];
            if (tgtPi.team < 0 || tgt.life != AI_LIFE_ALIVE) { if (tgtPi.team >= 0) ++g_deadTgtDropped; shooter.haveCachedTarget = false; continue; }
            targetPos = tgtPi.position;
        }
        else if (playerHealth <= 0.0f) { shooter.haveCachedTarget = false; continue; }

        const size_t shooterWeaponModel = (shooterPi.weaponIndex >= 0 && (size_t)shooterPi.weaponIndex < g_weaponTable.size())
            ? g_weaponTable[(size_t)shooterPi.weaponIndex].modelIndex : (size_t)-1;
        Vector3 eye = (shooterPi.modelIndex < uniqueModels.size())
            ? WeaponFireWorldPos(shooterPi.position, shooterPi.rotation, uniqueModels[shooterPi.modelIndex],
                  shooterWeaponModel < uniqueModels.size() ? &uniqueModels[shooterWeaponModel] : nullptr, AI_EYE_HEIGHT)
            : Vector3(shooterPi.position.m_X, shooterPi.position.m_Y + AI_EYE_HEIGHT, shooterPi.position.m_Z);
        Vector3 aimPoint = targetPos; aimPoint.m_Y += AIM_POINT_HEIGHT;
        Vector3 toTarget(aimPoint.m_X - eye.m_X, aimPoint.m_Y - eye.m_Y, aimPoint.m_Z - eye.m_Z);
        float dist = sqrtf(toTarget.m_X * toTarget.m_X + toTarget.m_Y * toTarget.m_Y + toTarget.m_Z * toTarget.m_Z);
        if (dist < 0.001f) continue;
        Vector3 dir(toTarget.m_X / dist, toTarget.m_Y / dist, toTarget.m_Z / dist);

        float bubbleOffLen = -1.0f;
        Vector3 bubbleDir = dir;
        {
            const AimBubble* tb = targetIsPlayer ? &g_playerBubble
                : (shooter.cachedTargetAiIdx < g_aiUnits.size() ? &g_aiUnits[shooter.cachedTargetAiIdx].bubble : nullptr);
            if (tb)
            {
                const Vector3 off = BubbleAimPointOffset(*tb, eye, aimPoint, wpn.aiBubbleSizeMult, wpn.aiBubbleDistDiv, wpn.aiBubbleClamp, targetIsPlayer, false);
                const Vector3 bt(toTarget.m_X + off.m_X, toTarget.m_Y + off.m_Y, toTarget.m_Z + off.m_Z);
                const float bl = sqrtf(bt.m_X * bt.m_X + bt.m_Y * bt.m_Y + bt.m_Z * bt.m_Z);
                if (bl > 0.001f) bubbleDir = Vector3(bt.m_X / bl, bt.m_Y / bl, bt.m_Z / bl);
                bubbleOffLen = sqrtf(off.m_X * off.m_X + off.m_Y * off.m_Y + off.m_Z * off.m_Z);
            }
        }

        {
            const retail_ai::V3 want{ bubbleDir.m_X, bubbleDir.m_Y, bubbleDir.m_Z };
            if (!shooter.trkValid)
            {
                const float y0 = (shooter.aimYawValid && !shooterPi.isDroideka) ? shooter.aimYaw : 2.0f * atan2f(shooterPi.rotation.m_Y, shooterPi.rotation.m_W) - 3.14159265f;
                shooter.trkDir = retail_ai::V3{ -sinf(y0), 0.0f, -cosf(y0) }; shooter.trkVel = retail_ai::V3{ 0.0f, 0.0f, 0.0f }; shooter.trkValid = true;
            }
            if (!targetIsPlayer && AiLodTier(shooterPi.position, playerPos, playerTeam >= 0, shooter.trkDir.x, shooter.trkDir.z) < 3) { shooter.trkDir = want; shooter.trkVel = retail_ai::V3{ 0.0f, 0.0f, 0.0f }; }
            else
            {
                const float skF = BubbleSkillF(!(g_playerTeam >= 1 && shooterPi.team == g_playerTeam));
                const float half = retail_ai::IsWeaponCannonLabel(wpn.weaponClassLabel.c_str()) ? 1.0f : 0.5f;
                retail_ai::TrackStep(shooter.trkDir, shooter.trkVel, want, deltaSec, retail_ai::TrackAccel(skF) * half, retail_ai::TrackDamp(skF) * half);
            }
        }
        if (meleeW != nullptr)
        {

            const float targetYaw = atan2f(-dir.m_X, -dir.m_Z);
            shooter.wantYaw = targetYaw; shooter.haveWantYaw = true; shooter.wantSrc = 1;
            const float curYaw = shooter.aimYawValid ? shooter.aimYaw : 2.0f * atan2f(shooterPi.rotation.m_Y, shooterPi.rotation.m_W) - 3.14159265f;
            if (fabsf(AngleDiff(curYaw, targetYaw)) <= 45.0f * DEG2RAD && dist <= meleeW->maxRange)
                MeleeFirePress(shooter, shooterPi, *meleeW, playerPos);
            continue;
        }
        if (shooter.fireCooldown > 0.0f) continue;

        {
            const float targetYaw = atan2f(-dir.m_X, -dir.m_Z);
            if (shooter.poseSpeed < 1.0f || !shooterPi.isDroideka) { shooter.wantYaw = targetYaw; shooter.haveWantYaw = true; shooter.wantSrc = 1;   }
            const float curYaw = (shooter.aimYawValid && !shooterPi.isDroideka) ? shooter.aimYaw
                               : 2.0f * atan2f(shooterPi.rotation.m_Y, shooterPi.rotation.m_W) - 3.14159265f;
            const float FIRE_FACING_TOL = 0.35f;
            if (!shooterPi.isDroideka && fabsf(AngleDiff(curYaw, targetYaw)) > FIRE_FACING_TOL) { ++g_aiFireHeldForTurn; continue; }
        }

        if (shooter.grenadeCooldown > 0.0f) shooter.grenadeCooldown -= deltaSec;
        {

            AIUnitState::Ability* gab = nullptr;
            for (AIUnitState::Ability& ab : shooter.abilities) if (ab.kind == ABIL_GRENADE && ab.reserve > 0) { gab = &ab; break; }
            const bool canThrow = gab != nullptr && shooter.grenadeCooldown <= 0.0f;
            if (canThrow)
            {
                const int gw = gab->weaponIndex;
                const WeaponStats& gwpn = g_weaponTable[(size_t)gw];
                shooter.grenadeReserve = gab->reserve;

                if (shooter.grenadeReserve > 0
                    && dist >= gwpn.minRange && dist <= gwpn.maxRange)
                {

                    Vector3 gd = dir;
                    if (gwpn.shotElevate > 0.0001f)
                    {
                        const float el = gwpn.shotElevate;
                        const float hL = sqrtf(dir.m_X * dir.m_X + dir.m_Z * dir.m_Z);
                        if (hL > 0.0001f)
                        {
                            const float ce = cosf(el), se = sinf(el);
                            const float nh = dir.m_Y * -se + hL * ce;
                            const float ny = dir.m_Y * ce + hL * se;
                            gd = Vector3(dir.m_X / hL * nh, ny, dir.m_Z / hL * nh);
                        }
                    }

                    StartAIAction(shooter, ABIL_GRENADE, gw,  true, gd, targetPos);
                    shooter.grenadeReserve--;
                    gab->reserve = shooter.grenadeReserve;
                    shooter.grenadeCooldown = 8.0f;
                    checkpointf("M202 AI grenade: unit %u threw \"%s\" at %.1fm (band %.0f-%.0f) reserve=%d",
                        (unsigned)ui, gwpn.name.c_str(), dist, gwpn.minRange, gwpn.maxRange,
                        shooter.grenadeReserve);
                    continue;
                }
            }
        }

        const bool aiUnlimited = (wpn.roundsPerClip <= 0.0f);

        if (wpn.heatRecoverRate > 0.0f)
        {
            shooter.weaponHeat -= wpn.heatRecoverRate * deltaSec;
            if (shooter.weaponHeat < 0.0f) shooter.weaponHeat = 0.0f;
            if (shooter.overheated && shooter.weaponHeat < wpn.heatThreshold) shooter.overheated = false;
        }
        if (shooter.overheated) continue;

        if (!aiUnlimited && shooter.ammoInClip < 0)
            shooter.ammoInClip = (int)wpn.roundsPerClip;
        if (shooter.reloadTimer > 0.0f) continue;
        if (!aiUnlimited && shooter.ammoInClip <= 0)
        {
            shooter.reloadTimer = (wpn.reloadTime > 0.0f) ? wpn.reloadTime : 1.5f;
            shooter.reloadAnimClock = 0.0f;
            continue;
        }
        if (!AiTriggerAllows(shooter.trig, wpn, BubbleSkillF(!(g_playerTeam >= 1 && shooterPi.team == g_playerTeam)))) continue;
        if (!aiUnlimited) shooter.ammoInClip--;

        const int aiShots = (wpn.shotsPerSalvo > 1 ? wpn.shotsPerSalvo : 1)
                          * (wpn.salvoCount > 1 ? wpn.salvoCount : 1);

        if (wpn.heatPerShot > 0.0f)
        {
            shooter.weaponHeat += wpn.heatPerShot * (float)aiShots;
            if (shooter.weaponHeat >= 1.0f) { shooter.weaponHeat = 1.0f; shooter.overheated = true; }
        }

        shooter.fireCooldown = wpn.shotDelay;

        if (wpn.maxPressedTime > 0.0f)
        {
            const float tf = BubbleSkillF(!(g_playerTeam >= 1 && shooterPi.team == g_playerTeam));
            const float u = (float)rand() / (float)RAND_MAX;
            shooter.fireCooldown += (0.15f + (fmaxf(0.15f, tf) - 0.15f) * u) * wpn.maxPressedTime;
        }
        shooter.aimSec = 1.0f;
        combatShotsThisFrame++;

        if (wpn.fireSoundClip >= 0)
        {
            const float adx = eye.m_X - playerPos.m_X;
            const float ady = eye.m_Y - playerPos.m_Y;
            const float adz = eye.m_Z - playerPos.m_Z;
            const float distToListener = sqrtf(adx * adx + ady * ady + adz * adz);
            const float kRealMinDist = 11.0f;
            const float kRealMaxDist = 400.0f;
            const float kRealRollOff = 3.5f;
            if (distToListener < kRealMaxDist)
            {
                const float gain = (distToListener <= kRealMinDist) ? 1.0f
                    : kRealMinDist / (kRealMinDist + kRealRollOff * (distToListener - kRealMinDist));
                const bool cgPlayed = PlaySoundClip(wpn.fireSoundClip, gain, (int)ui, RandomWeaponFirePitchRate());
                if (wpn.name == "rep_weap_inf_chaingun")
                { static int s_cgN = 0; if (s_cgN++ < 8) checkpointf("M254 chaingun AI: clip %d gain %.2f dist %.1f played %d", wpn.fireSoundClip, gain, distToListener, (int)cgPlayed); }
            }
        }

        if (targetIsPlayer && bubbleOffLen >= 0.0f) { ++g_bubbleDiagShots; g_bubbleDiagOffSum += bubbleOffLen; }
        if (targetIsPlayer) g_smpShotsAtPlayer += (uint32_t)aiShots;
        const Vector3 aimLine(shooter.trkDir.x, shooter.trkDir.y, shooter.trkDir.z);

        if (wpn.ordIsEmitter)
            FireEmitterShot(eye, dir, wpn, shooterPi.team, ui, uniqueModels, placedRef, nullptr, (float)aiShots);

        if (shooter.aiSpreadWeapon != shooterPi.weaponIndex) { shooter.aiSpread = 0.0f; shooter.aiSpreadWeapon = shooterPi.weaponIndex; }
        const float spMove = fminf(1.0f, sqrtf(shooter.velX * shooter.velX + shooter.velZ * shooter.velZ) / fmaxf(0.1f, g_soldierMaxSpeed));
        const float spBase = wpn.standStill + (wpn.standMove - wpn.standStill) * spMove;
        const float spS = fmaxf(0.0f, shooter.aiSpread);
        for (int pellet = 0; pellet < (wpn.ordIsEmitter ? 0 : aiShots); ++pellet)
        {

        float sniperYawRad = 0.0f;
        if (wpn.yawSpread == 0.0f && wpn.triggerSingle && wpn.zoomMax >= 6.0f)
        {
            const float tb = dist < 20.0f ? 0.0997f : dist < 40.0f ? 0.0499f : dist < 60.0f ? 0.0333f : dist < 80.0f ? 0.025f
                           : dist < 100.0f ? 0.02f : dist < 120.0f ? 0.0167f : 0.0143f;
            sniperYawRad = tb * retail_ai::Lerp(2.0f, 0.0f, BubbleSkillF(!(g_playerTeam >= 1 && shooterPi.team == g_playerTeam)));
        }
        const int patN = (int)wpn.patYaw.size();
        const float patY = patN ? wpn.patYaw[(size_t)(shooter.patIdx % patN)] * DEG2RAD : 0.0f;
        const float patP = patN ? wpn.patPitch[(size_t)(shooter.patIdx % patN)] * DEG2RAD : 0.0f;
        if (patN) shooter.patIdx = (shooter.patIdx + 1) % patN;
        float randYaw = AiSpreadTri() * ((spS + spBase + wpn.yawSpread) * DEG2RAD + sniperYawRad) + patY;
        float randPitch = AiSpreadTri() * (spS + spBase + wpn.pitchSpread) * DEG2RAD + patP;
        float baseYaw = atan2f(-aimLine.m_X, -aimLine.m_Z);
        float basePitch = asinf(fmaxf(-1.0f, fminf(1.0f, aimLine.m_Y)));
        Vector3 fireDir = GetForward(baseYaw + randYaw, basePitch + randPitch);

        const float fireRayRange = fminf(wpn.maxRange, dist * 1.5f + 10.0f);
        float worldHitDist; Vector3 worldHitPoint;
        size_t worldPlaced = SIZE_MAX;
        bool worldHit = FireRayHitTest(eye, fireDir, fireRayRange, uniqueModels, placedRef, worldHitDist, worldHitPoint, shooter.placedIndex,
                                       true, &worldPlaced);

        if (worldHit) g_diagShotWorldBlocked++;

        {
            static uint32_t s_aiTerrHint = 0;
            const float aiTerrDist = RayTerrainImpactDist(eye, fireDir, fireRayRange, terrainData, s_aiTerrHint);
            if (aiTerrDist < (worldHit ? worldHitDist : fireRayRange))
            {
                worldHit = true; worldHitDist = aiTerrDist;
                worldHitPoint = Vector3(eye.m_X + fireDir.m_X * aiTerrDist, eye.m_Y + fireDir.m_Y * aiTerrDist,
                                        eye.m_Z + fireDir.m_Z * aiTerrDist);
                worldPlaced = SIZE_MAX;
                ++g_aiShotTerrain;

                static const bool s_terrBlockLog = getenv("SWBF2_TERRBLOCK") != nullptr;
                static uint32_t s_terrBlockLogged = 0;
                if (s_terrBlockLog && s_terrBlockLogged < 400)
                {
                    float tY = 0.0f; Vector3 tN; uint32_t tHint = 0;
                    const bool tOk = GetTerrainHeightAt(terrainData, eye.m_X, eye.m_Z, tY, tN, tHint);
                    ++s_terrBlockLogged;
                    checkpointf("TERRBLOCK eye=(%.1f,%.1f,%.1f) terrY=%.1f(%d) hitAt=%.2f targetAt=%.1f", eye.m_X, eye.m_Y, eye.m_Z,
                                tY, tOk ? 1 : 0, aiTerrDist, dist);
                }
            }
        }
        float charHitDist = fireRayRange; bool charHeadshot = false; bool hitPlayerChar = false; size_t hitAIUnitIdx = (size_t)-1;
        if (targetIsPlayer)
        {
            hitPlayerChar = FireRayHitPlayer(eye, fireDir, worldHit ? worldHitDist : fireRayRange, playerPos, charHitDist, charHeadshot);
        }
        else
        {
            hitPlayerChar = false;

            float aiOutDist; bool aiOutHead; size_t aiOutIdx;
            if (FireRayHitAIUnit(eye, fireDir, worldHit ? worldHitDist : fireRayRange, placedRef, aiOutIdx, aiOutDist, aiOutHead, ui))
            {
                hitAIUnitIdx = aiOutIdx; charHitDist = aiOutDist; charHeadshot = aiOutHead;
            }
        }

        bool hitSomething = hitPlayerChar || (hitAIUnitIdx != (size_t)-1);
        if (hitSomething) g_diagShotCharHit++; else if (!worldHit) g_diagShotClean++;

        if (g_atstAimDbg && targetIsPlayer && g_playerVehicle >= 0 && (size_t)g_playerVehicle < g_vehicles.size()
            && g_vehicles[(size_t)g_playerVehicle].placedIndex < placedRef.size())
        {
            const PlacedInstance& pvp = placedRef[g_vehicles[(size_t)g_playerVehicle].placedIndex];
            const int hv = worldHit ? VehicleIndexForPlaced(worldPlaced) : -1;
            ++g_atstAimShots;
            if (hv == g_playerVehicle) ++g_atstAimHullHits;
            else if (hv >= 0) ++g_atstAimOtherVeh;
            else if (worldHit) ++g_atstAimWorld;
            else ++g_atstAimNoWorld;
            const float ox = pvp.position.m_X - eye.m_X, oy = pvp.position.m_Y - eye.m_Y, oz = pvp.position.m_Z - eye.m_Z;
            const float tt = fmaxf(0.0f, ox * fireDir.m_X + oy * fireDir.m_Y + oz * fireDir.m_Z);
            const float mx = eye.m_X + fireDir.m_X * tt - pvp.position.m_X;
            const float my = eye.m_Y + fireDir.m_Y * tt - pvp.position.m_Y;
            const float mz = eye.m_Z + fireDir.m_Z * tt - pvp.position.m_Z;
            const float miss = sqrtf(mx * mx + my * my + mz * mz);
            g_atstAimMissSum += miss;
            g_atstAimAimAboveSum += aimPoint.m_Y - pvp.position.m_Y;
            g_atstAimEyeAboveSum += eye.m_Y - pvp.position.m_Y;
            if (g_atstAimLines < 40)
            {
                ++g_atstAimLines;
                checkpointf("ATSTAIM shot %u: aim (%.1f %.1f %.1f) hull (%.1f %.1f %.1f) d %.1f | ray miss %.2f m, reached %.2f m -> %s (%s)",
                            g_atstAimShots, aimPoint.m_X, aimPoint.m_Y, aimPoint.m_Z,
                            pvp.position.m_X, pvp.position.m_Y, pvp.position.m_Z, dist, miss,
                            worldHit ? worldHitDist : fireRayRange,
                            hv == g_playerVehicle ? "the role's vehicle" : hv >= 0 ? "another vehicle" : worldHit ? "world" : "nothing",
                            wpn.name.c_str());
            }
            if (g_atstAimShots % 20u == 0u)
                checkpointf("ATSTAIM summary: %u shots at the player's \"%s\": %u hit it, %u hit another vehicle, %u hit world, %u hit nothing | mean ray miss %.2f m, mean aim point %.2f m above the hull, AI eye %.2f m above it",
                            g_atstAimShots, g_vehicles[(size_t)g_playerVehicle].cls.c_str(), g_atstAimHullHits, g_atstAimOtherVeh,
                            g_atstAimWorld, g_atstAimNoWorld, g_atstAimMissSum / (float)g_atstAimShots,
                            g_atstAimAimAboveSum / (float)g_atstAimShots, g_atstAimEyeAboveSum / (float)g_atstAimShots);
        }
        float tracerDist = hitSomething ? charHitDist : (worldHit ? worldHitDist : fireRayRange);

        if (wpn.ordHidden)
            HiddenBoltImpact(wpn, Vector3(eye.m_X + fireDir.m_X * tracerDist, eye.m_Y + fireDir.m_Y * tracerDist, eye.m_Z + fireDir.m_Z * tracerDist));
        else if (wpn.secTracer)
        {

            if ((hitSomething || worldHit) && !wpn.ordImpactEffect.empty())
                SpawnEffect(wpn.ordImpactEffect, Vector3(eye.m_X + fireDir.m_X * tracerDist, eye.m_Y + fireDir.m_Y * tracerDist, eye.m_Z + fireDir.m_Z * tracerDist), 16);
            if (shooter.tracerShots++ % (uint32_t)std::max(1, wpn.secTracerPeriod) == 0)
            {
                AddActiveTracer(eye, fireDir, tracerDist, wpn.secR, wpn.secG, wpn.secB, wpn.secTexBlue ? g_laserTexBlue : g_laserTexRed, false);
                ActiveTracer& atr = g_activeTracers.back();
                if (wpn.secTracerVel > 0.1f) atr.vel = wpn.secTracerVel;
                if (wpn.secLaserLen > 0.01f) atr.len = wpn.secLaserLen;
                if (wpn.secLaserWidth > 0.001f) atr.wid = wpn.secLaserWidth;
                atr.fadeOut = wpn.secFadeOutTime;
            }
        }
        else
        {
            AddActiveTracer(eye, fireDir, tracerDist, wpn.r, wpn.g, wpn.b,
                wpn.laserTexIsBlue ? g_laserTexBlue : g_laserTexRed,
                wpn.hasExplosion, wpn.ordImpactEffect);
            if (!wpn.hasExplosion) SetNewestTracerShape(wpn);
        }
        if (wpn.flashRadius > 0.0f) { shooterPi.flashEnd = g_flashClock + wpn.flashLength; shooterPi.flashDir = fireDir; }

        {
            static int s_asLog = 0;
            if (s_asLog < 400)
            {
                ++s_asLog;
                const ActiveTracer& at = g_activeTracers.empty() ? ActiveTracer{} : g_activeTracers.back();
                const size_t amb = (shooter.ownModelIndex != (size_t)-1 && shooter.ownModelIndex < uniqueModels.size()) ? shooter.ownModelIndex : shooterPi.modelIndex;
                const uint32_t aCrc = (amb < uniqueModels.size()) ? (uint32_t)uniqueModels[amb].animCRC : 0u;
                const float aClk = (amb < uniqueModels.size()) ? uniqueModels[amb].animLocalClock : 0.0f;
                checkpointf("M549 shot A: ai %u \"%s\" sd=%.3f pellet %d pose %d | bolt %s len %.2f wid %.3f vel %.0f dist %.1f | sound %d | model clip %08x clk %.2f",
                            (unsigned)ui, wpn.name.c_str(), wpn.shotDelay, pellet, (int)shooter.currentPose,
                            wpn.ordHidden ? "hidden" : (wpn.secTracer ? "secondary" : "primary"),
                            at.len, at.wid, at.vel, tracerDist, wpn.fireSoundClip, aCrc, aClk);
            }
        }
        if (wpn.secIsFatRay && pellet == 0)
            FireFatRayWave(eye, fireDir, wpn, shooterPi.weaponIndex, shooterPi.team, ui, worldHit ? worldHitDist : wpn.secRange, placedRef);

        if (!hitSomething && worldHit && VehicleIndexForPlaced(worldPlaced) >= 0)
        {
            const int hv = VehicleIndexForPlaced(worldPlaced);
            if (g_vehicles[(size_t)hv].team != shooterPi.team)
            {
                g_vehicleShooter = (int)ui;
                ApplyDamageToVehicle((size_t)hv, RealDamageAtFlightTime(wpn, worldHitDist / ((wpn.boltVelocity > 0.1f) ? wpn.boltVelocity : 300.0f))
                                     * wpn.ordVehicleScale, placedRef, wpn.name.c_str());
                g_vehicleShooter = -2;
            }
        }
        else if (!hitSomething && worldHit)
            DirectHitStation(worldPlaced, RealDamageAtFlightTime(wpn, worldHitDist / ((wpn.boltVelocity > 0.1f) ? wpn.boltVelocity : 300.0f)),
                             wpn.ordBuildingScale, placedRef, wpn.name.c_str());

        if (wpn.hasExplosion)
        {

            float blastDist = hitSomething ? charHitDist
                            : (worldHit ? worldHitDist : fireRayRange);
            {
                static uint32_t blastHint = 0;
                const float groundDist = RayTerrainImpactDist(eye, fireDir, blastDist,
                                                              terrainData, blastHint);
                if (groundDist < blastDist) blastDist = groundDist;
            }
            const Vector3 blastAt(eye.m_X + fireDir.m_X * blastDist,
                                  eye.m_Y + fireDir.m_Y * blastDist,
                                  eye.m_Z + fireDir.m_Z * blastDist);
            ApplyRealExplosion(blastAt, wpn, placedRef, ui);

            const float pdx = playerPos.m_X - blastAt.m_X;
            const float pdy = (playerPos.m_Y + 0.9f) - blastAt.m_Y;
            const float pdz = playerPos.m_Z - blastAt.m_Z;
            const float pd = sqrtf(pdx * pdx + pdy * pdy + pdz * pdz);
            if (pd <= wpn.explRadiusOuter && g_playerVehicle < 0)
            {
                float t = 1.0f;
                if (pd > wpn.explRadiusInner && wpn.explRadiusOuter > wpn.explRadiusInner)
                    t = 1.0f - (pd - wpn.explRadiusInner) / (wpn.explRadiusOuter - wpn.explRadiusInner);
                if (t > 0.0f)
                {
                    playerHealth -= wpn.explDamage * t * wpn.explPersonScale;
                    g_lastPlayerAttackerPos = blastAt;
                    g_lastPlayerAttackerAi = (int)ui;
                    NoteAttackerHint((int)ui, shooterPi.position);
                    if (playerHealth <= 0.0f) { playerHealth = 0.0f; outPlayerKilledThisCall = true; }
                }
            }
            continue;
        }
        if (!hitSomething) continue;

        const float aiBoltVel = (wpn.boltVelocity > 0.1f) ? wpn.boltVelocity : 300.0f;
        float realDamage = ApplyHitLocation(RealDamageAtFlightTime(wpn, charHitDist / aiBoltVel),
                                            charHeadshot, false);
        charHeadshot = charHeadshot && HitLocationMult(true, false) > 1.0f;

        if (hitPlayerChar && PlayerDeflects(shooterPi.position)) {}
        else if (hitPlayerChar)
        {
            checkpointf("MILESTONE 72 - real AI unit hit the PLAYER for %.1f real damage%s", realDamage, charHeadshot ? " (HEADSHOT x3)" : "");
            playerHealth -= PlayerShieldAbsorb(realDamage);
            ++g_smpHitsOnPlayer;
            g_lastPlayerAttackerPos = shooterPi.position;
            g_lastPlayerAttackerAi = (int)ui;
            NoteAttackerHint((int)ui, shooterPi.position);
            if (playerHealth <= 0.0f) { playerHealth = 0.0f; outPlayerKilledThisCall = true; }
        }
        else
        {
            checkpointf("MILESTONE 72 - real AI unit hit AI unit #%u for %.1f real damage%s",
                (unsigned)hitAIUnitIdx, realDamage, charHeadshot ? " (HEADSHOT x3)" : "");
            g_damageByAi = (int)ui; g_damageHeadshot = charHeadshot;
            {
                const char* const savedSrc = g_damageSource;
                g_damageSource = wpn.name.c_str();
                ApplyDamageToAIUnit(hitAIUnitIdx, realDamage, placedRef);
                g_damageSource = savedSrc;
            }
            g_damageByAi = -2; g_damageHeadshot = false;
        }
        }
        {
            const bool shooterOnPlayerTeam = (g_playerTeam >= 1 && shooterPi.team == g_playerTeam);
            const float add = retail_ai::SpreadMult(BubbleSkillF(!shooterOnPlayerTeam)) * wpn.spreadPerShot;
            shooter.aiSpread += add;
            if (wpn.spreadLimit > 0.0f && shooter.aiSpread > wpn.spreadLimit) shooter.aiSpread = wpn.spreadLimit;
        }
    }
    g_combatThinkCount += combatThinksThisFrame;
    g_combatShotCount += combatShotsThisFrame;
}

static bool TeamHasConquestGoal(int team)
{
    auto it = g_aiGoalsByTeam.find(team);
    if (it == g_aiGoalsByTeam.end()) return false;
    for (const AIGoalEntry& g : it->second)
    {
        if (g.weight <= 0.0f) continue;
        if (strcasecmp(g.type.c_str(), "Conquest") == 0) return true;

        if (strcasecmp(g.type.c_str(), "Deathmatch") == 0 || strcasecmp(g.type.c_str(), "Hunt") == 0) return true;
    }
    return false;
}

static bool TeamDeathmatchOnly(int team)
{
    auto it = g_aiGoalsByTeam.find(team);
    if (it == g_aiGoalsByTeam.end()) return false;
    bool dm = false;
    for (const AIGoalEntry& g : it->second)
    {
        if (g.weight <= 0.0f) continue;
        if (strcasecmp(g.type.c_str(), "Conquest") == 0) return false;
        if (strcasecmp(g.type.c_str(), "Deathmatch") == 0 || strcasecmp(g.type.c_str(), "Hunt") == 0) dm = true;
    }
    return dm;
}

struct NavHub
{
    Vector3 position;
    float radius = 0.0f;

    int16_t slotNext[5][8];
    uint8_t rowCount[5] = { 0, 0, 0, 0, 0 };
    uint32_t setBase = 0, setCount = 0;
    std::vector<uint8_t> rows[5];
    NavHub() { for (int t = 0; t < 5; ++t) for (int k = 0; k < 8; ++k) slotNext[t][k] = -1; }
};
static std::vector<NavHub> g_navHubs;
static std::vector<std::vector<uint16_t>> g_navAdj;

static std::vector<std::vector<float>> g_navArcPenalty;

static std::unordered_map<uint32_t, uint8_t> g_navArcFlags;

static std::unordered_set<uint32_t> g_navArcJump;

struct NavArcRec { uint16_t a, b; uint8_t attr; };

static std::map<std::string, std::vector<std::pair<uint16_t, uint16_t>>> g_navArcByName;
static std::set<uint32_t> g_navBlocked;
static std::set<std::string> g_navBlockedNames;
static bool NavArcBlocked(uint32_t a, uint32_t b) { return !g_navBlocked.empty() && (g_navBlocked.count((a << 16) | b) || g_navBlocked.count((b << 16) | a)); }
static void NavSetArcsBlocked(const std::string& nameIn, bool blocked)
{
    std::string n = nameIn; for (char& c : n) c = (char)tolower((unsigned char)c);
    if (blocked) g_navBlockedNames.insert(n); else g_navBlockedNames.erase(n);
    auto it = g_navArcByName.find(n);
    if (it == g_navArcByName.end()) return;
    for (const auto& pr : it->second)
    {
        const uint32_t k = ((uint32_t)pr.first << 16) | pr.second;
        if (blocked) g_navBlocked.insert(k); else g_navBlocked.erase(k);
    }
}
static int Lua_BlockPlanningGraphArcs(lua_State* L)
{
    if (lua_gettop(L) >= 1 && lua_isstring(L, 1)) { NavSetArcsBlocked(lua_tostring(L, 1), true); checkpointf("M525 BlockPlanningGraphArcs(\"%s\")", lua_tostring(L, 1)); }
    return 0;
}
static int Lua_UnblockPlanningGraphArcs(lua_State* L)
{
    if (lua_gettop(L) >= 1 && lua_isstring(L, 1)) NavSetArcsBlocked(lua_tostring(L, 1), false);
    return 0;
}
static std::vector<NavArcRec> g_navArcList;
static std::vector<int> g_navComp;
static std::vector<uint8_t> g_navHubSoldier;
static uint32_t g_aiJumps = 0;
static uint32_t g_aiJumpShorts = 0;
static uint32_t g_aiHubBans = 0;

static bool NavArcAllowsSoldier(LibSWBF2::EArcFilterFlags f)
{
    return ((uint32_t)f & (uint32_t)LibSWBF2::EArcFilterFlags::Soldier) != 0;
}

struct NavBarrier
{
    Vector3 position;
    Vector4 rotation;
    float halfX = 0.0f, halfZ = 0.0f;
    uint32_t flag = 0;
    uint32_t realFlag = 0;
    std::string name;
};

static std::vector<NavBarrier> g_navBarriers;
static std::unordered_map<int64_t, std::vector<uint32_t>> g_navBarrierGrid;
static const float BARRIER_GRID_CELL = 16.0f;

static const uint32_t BARRIER_BANS_SOLDIER = 1u;

static bool PointInBarrier(const NavBarrier& b, float x, float z, float inflate)
{

    const Vector4 invRot(-b.rotation.m_X, -b.rotation.m_Y, -b.rotation.m_Z, b.rotation.m_W);
    const Vector3 local = QuatRotateVector(invRot, Vector3(x - b.position.m_X, 0.0f, z - b.position.m_Z));
    return fabsf(local.m_X) <= (b.halfX + inflate) && fabsf(local.m_Z) <= (b.halfZ + inflate);
}

static uint32_t g_barrierVersion = 1;
static void SetBarriersEnabled(const char* name, bool on)
{
    ++g_barrierVersion;
    if (name == nullptr) return;
    std::string n = name;
    for (char& ch : n) ch = (char)tolower((unsigned char)ch);
    if (on) g_disabledBarrierNames.erase(n); else g_disabledBarrierNames.insert(n);
    unsigned hit = 0;
    for (NavBarrier& b : g_navBarriers) if (b.name == n) { b.flag = on ? b.realFlag : 0u; ++hit; }
    checkpointf("M494 %s(\"%s\"): %u barrier(s)", on ? "EnableBarriers" : "DisableBarriers", name, hit);
}
static int Lua_DisableBarriers(lua_State* L) { SetBarriersEnabled(lua_tostring(L, 1), false); return 0; }
static int Lua_EnableBarriers(lua_State* L) { SetBarriersEnabled(lua_tostring(L, 1), true); return 0; }

static void BuildNavBarriersFromLevel(Level* lvl)
{
    g_navBarriers.clear();
    g_navBarrierGrid.clear();
    if (lvl == nullptr) return;

    const List<World>& worlds = lvl->GetWorlds();
    for (uint32_t w = 0; w < (uint32_t)worlds.Size(); ++w)
    {
        const List<LibSWBF2::Wrappers::Barrier>& barrs = worlds[w].GetBarriers();
        for (uint32_t i = 0; i < (uint32_t)barrs.Size(); ++i)
        {
            NavBarrier nb;

            nb.position = barrs[i].GetPosition();
            nb.position.m_Z = -nb.position.m_Z;
            {
                const Vector4 q = barrs[i].GetRotation();
                nb.rotation = Vector4(-q.m_X, -q.m_Y, q.m_Z, q.m_W);
            }
            const Vector3 sz = barrs[i].GetSize();
            nb.halfX = fabsf(sz.m_X);
            nb.halfZ = fabsf(sz.m_Z);
            nb.flag = barrs[i].GetFlag();
            nb.realFlag = nb.flag;
            nb.name = barrs[i].GetName().Buffer();
            for (char& ch : nb.name) ch = (char)tolower((unsigned char)ch);
            if (g_disabledBarrierNames.count(nb.name)) nb.flag = 0;
            g_navBarriers.push_back(nb);
        }
    }

    for (uint32_t i = 0; i < (uint32_t)g_navBarriers.size(); ++i)
    {
        const NavBarrier& b = g_navBarriers[i];
        const float reach = sqrtf(b.halfX * b.halfX + b.halfZ * b.halfZ);
        const int32_t cx0 = (int32_t)floorf((b.position.m_X - reach) / BARRIER_GRID_CELL);
        const int32_t cx1 = (int32_t)floorf((b.position.m_X + reach) / BARRIER_GRID_CELL);
        const int32_t cz0 = (int32_t)floorf((b.position.m_Z - reach) / BARRIER_GRID_CELL);
        const int32_t cz1 = (int32_t)floorf((b.position.m_Z + reach) / BARRIER_GRID_CELL);
        for (int32_t cz = cz0; cz <= cz1; ++cz)
        for (int32_t cx = cx0; cx <= cx1; ++cx)
            g_navBarrierGrid[PackGridCell(cx, cz)].push_back(i);
    }

    uint32_t soldierBanning = 0, perBit[6] = {};
    for (const NavBarrier& b : g_navBarriers)
    {
        if (b.flag & BARRIER_BANS_SOLDIER) soldierBanning++;
        for (int k = 0; k < 6; ++k) if (b.flag & (1u << k)) perBit[k]++;
    }
    logf("BuildNavBarriersFromLevel: real AI barriers loaded - %u total, %u ban Soldier | M463 per size: soldier %u hover %u small %u medium %u huge %u flyer %u\n",
        (unsigned)g_navBarriers.size(), soldierBanning, perBit[0], perBit[1], perBit[2], perBit[3], perBit[4], perBit[5]);
}

static bool PointBlockedByBarrier(float x, float z, float unitRadius)
{
    if (g_navBarrierGrid.empty()) return false;
    const int32_t cx = (int32_t)floorf(x / BARRIER_GRID_CELL);
    const int32_t cz = (int32_t)floorf(z / BARRIER_GRID_CELL);
    auto it = g_navBarrierGrid.find(PackGridCell(cx, cz));
    if (it == g_navBarrierGrid.end()) return false;
    for (uint32_t bi : it->second)
    {
        const NavBarrier& b = g_navBarriers[bi];
        if ((b.flag & BARRIER_BANS_SOLDIER) == 0) continue;
        if (PointInBarrier(b, x, z, unitRadius)) return true;
    }
    return false;
}

static uint32_t g_legPlans = 0, g_legCornerPlans = 0, g_legFails = 0, g_sideSteps = 0;
static rbl::Box ToLegBox(const NavBarrier& b)
{
    const Vector3 u = QuatRotateVector(b.rotation, Vector3(1.0f, 0.0f, 0.0f));
    const Vector3 v = QuatRotateVector(b.rotation, Vector3(0.0f, 0.0f, 1.0f));
    return rbl::Box{ b.position.m_X, b.position.m_Z, u.m_X, u.m_Z, v.m_X, v.m_Z, b.halfX, b.halfZ };
}
static void ForEachSoldierBarrier(float x0, float z0, float x1, float z1, float pad, const std::function<void(const rbl::Box&)>& fn)
{
    const int32_t cx0 = (int32_t)floorf((fminf(x0, x1) - pad) / BARRIER_GRID_CELL), cx1 = (int32_t)floorf((fmaxf(x0, x1) + pad) / BARRIER_GRID_CELL);
    const int32_t cz0 = (int32_t)floorf((fminf(z0, z1) - pad) / BARRIER_GRID_CELL), cz1 = (int32_t)floorf((fmaxf(z0, z1) + pad) / BARRIER_GRID_CELL);
    static std::vector<uint32_t> seen; seen.clear();
    for (int32_t cz = cz0; cz <= cz1; ++cz)
    for (int32_t cx = cx0; cx <= cx1; ++cx)
    {
        auto it = g_navBarrierGrid.find(PackGridCell(cx, cz));
        if (it == g_navBarrierGrid.end()) continue;
        for (uint32_t bi : it->second)
        {
            if ((g_navBarriers[bi].flag & BARRIER_BANS_SOLDIER) == 0) continue;
            if (std::find(seen.begin(), seen.end(), bi) != seen.end()) continue;
            seen.push_back(bi);
            fn(ToLegBox(g_navBarriers[bi]));
        }
    }
}

static bool PlanBarrierLeg(float sx, float sz, float gx, float gz, float r, std::vector<float>& corners)
{
    ++g_legPlans;
    const rbl::Result res = rbl::PlanLeg(ForEachSoldierBarrier, sx, sz, gx, gz, r, corners);
    if (res != rbl::STRAIGHT) ++g_legCornerPlans;
    if (res == rbl::GOAL_BLOCKED || res == rbl::NO_ROUTE) { ++g_legFails; corners.clear(); return false; }
    return true;
}

static bool PointBlockedByBarrierForSize(float x, float z, float radius, uint32_t sizeFlag)
{
    if (g_navBarrierGrid.empty()) return false;
    const int32_t cx = (int32_t)floorf(x / BARRIER_GRID_CELL);
    const int32_t cz = (int32_t)floorf(z / BARRIER_GRID_CELL);
    for (int32_t oz = -1; oz <= 1; ++oz)
    for (int32_t ox = -1; ox <= 1; ++ox)
    {
        auto it = g_navBarrierGrid.find(PackGridCell(cx + ox, cz + oz));
        if (it == g_navBarrierGrid.end()) continue;
        for (uint32_t bi : it->second)
        {
            const NavBarrier& b = g_navBarriers[bi];
            if ((b.flag & sizeFlag) == 0) continue;
            if (PointInBarrier(b, x, z, radius)) return true;
        }
    }
    return false;
}

enum HintNodeType
{
    HINT_SNIPE = 0, HINT_PATROL = 1, HINT_COVER = 2, HINT_ACCESS = 3,
    HINT_JETJUMP = 4, HINT_MINE = 5, HINT_LAND = 6,
    HINT_FORTIFICATION = 7, HINT_VEHICLECOVER = 8,
};

struct HintNodeData
{
    bool mined = false;
    Vector3 position;
    Vector3 forward;
    int type = -1;
    int primaryStance = 0;
    int secondaryStance = 0;
    int mode = 0;
    int reservedBy = -1;
};
static std::vector<HintNodeData> g_hintNodes;

static bool g_restartStateLog = false;
static std::string g_matchStateDump;
static unsigned RsMixBytes(unsigned h, const void* p, size_t n)
{
    const unsigned char* b = (const unsigned char*)p;
    for (size_t i = 0; i < n; ++i) { h ^= b[i]; h *= 16777619u; }
    return h;
}
template <typename T> static unsigned RsMixV(unsigned h, const T& v) { return RsMixBytes(h, &v, sizeof(T)); }

static std::string BuildMatchStateDump(unsigned matchNo, const char* when, const std::vector<PlacedInstance>& placedRef)
{
    std::string s;
    char buf[512];
    auto add = [&](const char* fmt, ...) { va_list ap; va_start(ap, fmt); vsnprintf(buf, sizeof(buf), fmt, ap); va_end(ap); s += buf; };
    add("RSTATE match %u (%s)\n", matchNo, when);

    {
        unsigned h = 2166136261u, live = 0;
        for (const PlacedInstance& pi : placedRef)
        {
            h = RsMixV(h, pi.modelIndex); h = RsMixV(h, pi.position.m_X); h = RsMixV(h, pi.position.m_Y); h = RsMixV(h, pi.position.m_Z);
            h = RsMixV(h, pi.rotation.m_X); h = RsMixV(h, pi.rotation.m_Y); h = RsMixV(h, pi.rotation.m_Z); h = RsMixV(h, pi.rotation.m_W);
            h = RsMixV(h, pi.team); h = RsMixV(h, pi.corpse); h = RsMixV(h, pi.isSoldier); h = RsMixV(h, pi.inVehicle);
            if (pi.modelIndex != MODEL_LOAD_FAILED) ++live;
        }
        add("RSTATE   placed n=%u live=%u h=%08x\n", (unsigned)placedRef.size(), live, h);
    }
    {
        unsigned h = 2166136261u, alive = 0, seated = 0;
        for (const AIUnitState& au : g_aiUnits)
        {
            h = RsMixV(h, au.life); h = RsMixV(h, au.placedIndex); h = RsMixV(h, au.health); h = RsMixV(h, au.ammoInClip);
            h = RsMixV(h, au.vehicle); h = RsMixV(h, au.vehicleSeat); h = RsMixV(h, au.points);
            if (au.life == AI_LIFE_ALIVE) ++alive;
            if (au.vehicle >= 0) ++seated;
        }
        add("RSTATE   ai n=%u alive=%u seated=%u h=%08x\n", (unsigned)g_aiUnits.size(), alive, seated, h);
    }
    {
        unsigned h = 2166136261u, alive = 0, manned = 0;
        for (const VehicleState& v : g_vehicles)
        {
            h = RsMixV(h, v.alive); h = RsMixV(h, v.hitPoints); h = RsMixV(h, v.team); h = RsMixV(h, v.spawn);
            h = RsMixV(h, v.pilot); h = RsMixV(h, v.gunner[0]); h = RsMixV(h, v.gunner[1]); h = RsMixV(h, v.poseModel);
            if (v.alive) ++alive;
            if (v.pilot >= 0 || v.gunner[0] >= 0 || v.gunner[1] >= 0) ++manned;
        }
        add("RSTATE   vehicles n=%u alive=%u manned=%u h=%08x\n", (unsigned)g_vehicles.size(), alive, manned, h);
    }
    {
        unsigned h = 2166136261u, active = 0;
        for (const VehicleSpawnState& vs : g_vehicleSpawns)
        {
            h = RsMixV(h, vs.cp); h = RsMixV(h, vs.active); h = RsMixV(h, vs.respawnClock);
            for (int t = 0; t < 3; ++t) h = RsMixV(h, vs.vehicleForTeam[t]);
            if (vs.active >= 0) ++active;
        }
        add("RSTATE   vspawns n=%u active=%u h=%08x\n", (unsigned)g_vehicleSpawns.size(), active, h);
    }
    {
        unsigned h = 2166136261u, alive = 0;
        for (const PowerupStationState& st : g_stations)
        {
            h = RsMixV(h, st.alive); h = RsMixV(h, st.hitPoints); h = RsMixV(h, st.rebuild); h = RsMixV(h, st.tickClock);
            h = RsMixV(h, st.serves); h = RsMixV(h, st.servesPlayer);
            if (st.alive) ++alive;
        }
        add("RSTATE   stations n=%u alive=%u h=%08x\n", (unsigned)g_stations.size(), alive, h);
    }
    {
        unsigned h = 2166136261u;
        for (const CommandPostState& cp : g_commandPosts)
        {
            h = RsMixV(h, cp.team); h = RsMixV(h, cp.captureTeam); h = RsMixV(h, cp.captureTimer);
            h = RsMixV(h, cp.captureDisputed); h = RsMixV(h, cp.captureToNeutral); h = RsMixV(h, cp.captureCount);
        }
        add("RSTATE   cps n=%u h=%08x\n", (unsigned)g_commandPosts.size(), h);
    }
    {
        unsigned open = 0;
        std::string detail;
        for (size_t i = 0; i < g_doors.size(); ++i)
        {
            const DoorState& d = g_doors[i];
            if (d.t > 0.0f) ++open;
            if (i < 6)
            {
                const char* nm = (d.placed < placedRef.size()) ? placedRef[d.placed].instName.c_str() : "?";
                char one[96];
                snprintf(one, sizeof(one), " %s=%.2f/%d", nm, d.t, d.frame);
                detail += one;
            }
        }
        add("RSTATE   doors n=%u open=%u%s\n", (unsigned)g_doors.size(), open, detail.c_str());
    }
    {
        unsigned running = 0;
        std::string detail;
        for (size_t i = 0; i < g_timers.size(); ++i)
        {
            const TimerState& t = g_timers[i];
            if (t.running) ++running;
            if (i < 4) { char one[96]; snprintf(one, sizeof(one), " %s=%.2f/%.2f/%d", t.name.c_str(), t.value, t.rate, (int)t.running); detail += one; }
        }
        add("RSTATE   timers n=%u running=%u%s\n", (unsigned)g_timers.size(), running, detail.c_str());
    }
    {
        unsigned h = 2166136261u;
        for (const TeamInfo& t : g_teams)
        {
            h = RsMixV(h, t.reinforcementCount); h = RsMixV(h, t.startingReinforcementCount); h = RsMixV(h, t.score);
        }
        add("RSTATE   teams n=%u h=%08x\n", (unsigned)g_teams.size(), h);
    }
    {
        unsigned n = 0;
        for (const auto& kv : g_aiGoalsByTeam) n += (unsigned)kv.second.size();
        add("RSTATE   goals teams=%u goals=%u\n", (unsigned)g_aiGoalsByTeam.size(), n);
    }

    add("RSTATE   fx ord=%u trc=%u blasts=%u beams=%u fx=%u worldfx=%u tow=%u boltlights=%u\n",
        (unsigned)g_activeOrdnance.size(), (unsigned)g_activeTracers.size(), (unsigned)g_blastFlashes.size(),
        (unsigned)g_beams.size(), (unsigned)g_fxLive.size(), (unsigned)g_worldFx.size(),
        (unsigned)g_towCables.size(), (unsigned)g_boltImpactLights.size());
    add("RSTATE   player points=%d heroPoints=%d kills=%d teamKills=%d hero=%d damageSource=%s\n",
        g_playerPoints, g_playerHeroPoints, g_playerKills, g_playerTeamKills, (int)g_playerIsHero,
        g_damageSource ? g_damageSource : "-");
    {
        unsigned mined = 0;
        for (const HintNodeData& hn : g_hintNodes) if (hn.mined) ++mined;
        add("RSTATE   hints n=%u mined=%u\n", (unsigned)g_hintNodes.size(), mined);
    }
    add("RSTATE   match over=%d win=%d aiClock=%.2f cpEvents=%u/%u tally=%u\n",
        (int)g_missionOver, g_missionWinningTeam, g_aiClock,
        (unsigned)g_cpLostEvents.size(), (unsigned)g_cpCapturedEvents.size(), (unsigned)g_deathTally.size());
    return s;
}

static void BuildHintNodesFromLevel(Level* lvl)
{
    g_hintNodes.clear();
    if (lvl == nullptr) return;

    const LibSWBF2::FNVHash HASH_PRIMARY   = LibSWBF2::FNV::Hash(String("PrimaryStance"));
    const LibSWBF2::FNVHash HASH_SECONDARY = LibSWBF2::FNV::Hash(String("SecondaryStance"));
    const LibSWBF2::FNVHash HASH_MODE      = LibSWBF2::FNV::Hash(String("Mode"));

    const List<World>& worlds = lvl->GetWorlds();
    for (uint32_t w = 0; w < (uint32_t)worlds.Size(); ++w)
    {
        const List<LibSWBF2::Wrappers::HintNode>& hints = worlds[w].GetHintNodes();
        for (uint32_t i = 0; i < (uint32_t)hints.Size(); ++i)
        {
            HintNodeData hn;
            hn.position = hints[i].GetPosition();
            const Vector4 rot = hints[i].GetRotation();

            hn.forward = QuatRotateVector(rot, Vector3(0.0f, 0.0f, -1.0f));

            const uint16_t rawType = hints[i].GetType();
            hn.type = (rawType >= '0' && rawType <= '9') ? (int)(rawType - '0') : (int)rawType;

            List<LibSWBF2::FNVHash> ph; List<String> pv;
            hints[i].GetProperties(ph, pv);
            for (uint32_t k = 0; k < (uint32_t)ph.Size(); ++k)
            {
                const int val = atoi(pv[k].Buffer());
                if (ph[k] == HASH_PRIMARY)        hn.primaryStance = val;
                else if (ph[k] == HASH_SECONDARY) hn.secondaryStance = val;
                else if (ph[k] == HASH_MODE)      hn.mode = val;
            }
            g_hintNodes.push_back(hn);
        }
    }

    int counts[9] = { 0 };
    for (const HintNodeData& h : g_hintNodes)
        if (h.type >= 0 && h.type < 9) counts[h.type]++;
    logf("BuildHintNodesFromLevel: real AI hint nodes loaded - %u total "
         "(Snipe=%d Cover=%d Fortification=%d VehicleCover=%d, others=%d)\n",
        (unsigned)g_hintNodes.size(), counts[HINT_SNIPE], counts[HINT_COVER],
        counts[HINT_FORTIFICATION], counts[HINT_VEHICLECOVER],
        counts[1] + counts[3] + counts[4] + counts[5] + counts[6]);
}

static void BuildNavGraphFromLevel(Level* lvl)
{
    g_navHubs.clear();
    g_navAdj.clear();
    g_navArcList.clear(); g_navHubSoldier.clear(); g_navComp.clear();
    g_navArcByName.clear(); g_navBlocked.clear();
    if (lvl == nullptr) return;

    const List<LibSWBF2::Wrappers::PlanSet>& plans = lvl->GetPlanSets();
    uint32_t totalArcs = 0, soldierArcs = 0;

    const uint32_t firstPlan = (plans.Size() > 0 && !getenv("SWBF2_ALL_PLANS")) ? (uint32_t)plans.Size() - 1 : 0;
    for (uint32_t p = firstPlan; p < (uint32_t)plans.Size(); ++p)
    {
        const List<LibSWBF2::Types::Hub>& hubs = plans[p].GetHubs();
        const List<LibSWBF2::Types::Connection>& cons = plans[p].GetConnections();

        const uint32_t base = (uint32_t)g_navHubs.size();
        for (uint32_t h = 0; h < (uint32_t)hubs.Size(); ++h)
        {
            NavHub nh;
            nh.position = hubs[h].m_Position;
            nh.radius = hubs[h].m_Radius;

            nh.setBase = base; nh.setCount = (uint32_t)hubs.Size();
            size_t layerOff = 0;
            for (int t = 0; t < 5; ++t)
            {
                for (int sl = 0; sl < 8; ++sl)
                {
                    const uint8_t c = hubs[h].m_ConnectionIndices[sl];
                    if (c == 0xff || c >= cons.Size() || ((uint32_t)cons[c].m_FilterFlags & (1u << t)) == 0) continue;
                    const uint32_t o = (cons[c].m_Start == h) ? cons[c].m_End : cons[c].m_Start;
                    if (o < (uint32_t)hubs.Size()) nh.slotNext[t][sl] = (int16_t)(base + o);
                }
                const int full = hubs[h].m_ConnectionsPerLayer[t];
                nh.rowCount[t] = (uint8_t)std::min<int>(4, full);
                const size_t need = (size_t)nh.rowCount[t] * nh.setCount;
                if (hubs[h].m_QuantizedDataBuffer.Size() >= layerOff + need)
                    nh.rows[t].assign(hubs[h].m_QuantizedDataBuffer.GetArrayPtr() + layerOff, hubs[h].m_QuantizedDataBuffer.GetArrayPtr() + layerOff + need);
                else nh.rowCount[t] = 0;
                layerOff += (size_t)full * nh.setCount;
            }
            g_navHubs.push_back(nh);
        }
        g_navAdj.resize(g_navHubs.size());

        for (uint32_t c = 0; c < (uint32_t)cons.Size(); ++c)
        {
            totalArcs++;
            if (!NavArcAllowsSoldier(cons[c].m_FilterFlags)) continue;
            const uint32_t a = base + (uint32_t)cons[c].m_Start;
            const uint32_t b = base + (uint32_t)cons[c].m_End;
            if (a >= g_navHubs.size() || b >= g_navHubs.size()) continue;
            soldierArcs++;

            g_navAdj[a].push_back((uint16_t)b);
            const bool oneWay = ((uint32_t)cons[c].m_AttributeFlags & (uint32_t)LibSWBF2::EArcAttributeFlags::OneWay) != 0;
            if (!oneWay) g_navAdj[b].push_back((uint16_t)a);
            g_navArcFlags[(a << 16) | b] = (uint8_t)cons[c].m_FilterFlags;
            g_navArcList.push_back({ (uint16_t)a, (uint16_t)b, (uint8_t)cons[c].m_AttributeFlags });
            {
                std::string cn = cons[c].m_Name.Buffer(); for (char& ch : cn) ch = (char)tolower((unsigned char)ch);
                g_navArcByName[cn].push_back({ (uint16_t)a, (uint16_t)b });
                if (g_navBlockedNames.count(cn)) g_navBlocked.insert((a << 16) | b);
            }
            if (g_navHubSoldier.size() < g_navHubs.size()) g_navHubSoldier.resize(g_navHubs.size(), 0);
            g_navHubSoldier[a] = g_navHubSoldier[b] = 1;
            if ((uint32_t)cons[c].m_AttributeFlags & (uint32_t)LibSWBF2::EArcAttributeFlags::Jump)
            {
                g_navArcJump.insert((a << 16) | b);
                if (!oneWay) g_navArcJump.insert((b << 16) | a);
            }
            if (!oneWay) g_navArcFlags[(b << 16) | a] = (uint8_t)cons[c].m_FilterFlags;
        }
    }

    logf("BuildNavGraphFromLevel: real AI planning graph loaded - %u hub(s), %u of %u real arc(s) soldier-traversable\n",
        (unsigned)g_navHubs.size(), soldierArcs, totalArcs);
    {
        uint32_t withRows[5] = {}, slots[5] = {};
        for (const NavHub& h : g_navHubs)
            for (int t = 0; t < 5; ++t) { if (h.rowCount[t]) ++withRows[t]; for (int k = 0; k < 8; ++k) if (h.slotNext[t][k] >= 0) ++slots[t]; }
        logf("VEHNAV route table by type (soldier hover small medium huge): hubs with rows %u %u %u %u %u | arc ends %u %u %u %u %u\n",
             withRows[0], withRows[1], withRows[2], withRows[3], withRows[4], slots[0], slots[1], slots[2], slots[3], slots[4]);
    }

    BuildNavBarriersFromLevel(lvl);

    BuildHintNodesFromLevel(lvl);

    {

        const float BARRIER_ARC_PENALTY = 12.0f;
        g_navArcPenalty.assign(g_navAdj.size(), std::vector<float>());
        uint32_t prunedByBarrier = 0;
        for (size_t h = 0; h < g_navAdj.size(); ++h)
        {
            std::vector<uint16_t> kept;
            std::vector<float> keptPenalty;
            kept.reserve(g_navAdj[h].size());
            keptPenalty.reserve(g_navAdj[h].size());
            for (uint16_t nb : g_navAdj[h])
            {
                if ((size_t)nb >= g_navHubs.size()) continue;
                const Vector3& pa = g_navHubs[h].position;
                const Vector3& pb = g_navHubs[nb].position;
                const float dx = pb.m_X - pa.m_X, dz = pb.m_Z - pa.m_Z;
                const float len = sqrtf(dx * dx + dz * dz);
                const int steps = (int)fminf(64.0f, fmaxf(2.0f, len * 0.5f));
                bool blocked = false;
                for (int i = 1; i < steps && !blocked; ++i)
                {
                    const float t = (float)i / (float)steps;
                    if (PointBlockedByBarrier(pa.m_X + dx * t, pa.m_Z + dz * t, PLAYER_COLLISION_RADIUS))
                        blocked = true;
                }
                if (blocked) prunedByBarrier++;
                kept.push_back(nb);
                keptPenalty.push_back(blocked ? BARRIER_ARC_PENALTY : 1.0f);
            }
            g_navAdj[h].swap(kept);
            g_navArcPenalty[h].swap(keptPenalty);
        }
        logf("BuildNavGraphFromLevel: MILESTONE 105 - %u real arc-direction(s) PENALIZED for crossing a real Soldier-banned barrier\n",
            prunedByBarrier);
    }
}

static void PruneNavArcsBlockedByWorld(const std::vector<ModelData>& uniqueModels,
                                       std::vector<PlacedInstance>& placed)
{
    const float CHEST_Y = 1.0f;

    const float WORLD_ARC_PENALTY = 1.0f;
    uint32_t pruned = 0, kept = 0;
    for (size_t h = 0; h < g_navAdj.size(); ++h)
    {
        std::vector<uint16_t> survivors;
        std::vector<float> survivorPenalty;
        survivors.reserve(g_navAdj[h].size());
        survivorPenalty.reserve(g_navAdj[h].size());
        for (uint16_t nb : g_navAdj[h])
        {
            if ((size_t)nb >= g_navHubs.size()) continue;
            const Vector3& pa = g_navHubs[h].position;
            const Vector3& pb = g_navHubs[nb].position;
            const float dx = pb.m_X - pa.m_X, dy = pb.m_Y - pa.m_Y, dz = pb.m_Z - pa.m_Z;
            const float len = sqrtf(dx * dx + dy * dy + dz * dz);
            if (len < 0.01f) { survivors.push_back(nb); kept++; continue; }
            const Vector3 origin(pa.m_X, pa.m_Y + CHEST_Y, pa.m_Z);
            const Vector3 dir(dx / len, dy / len, dz / len);
            float hitDist = 0.0f; Vector3 hitPt;

            const bool wallBetween = FireRayHitTest(origin, dir, len, uniqueModels, placed, hitDist, hitPt,
                                                    SIZE_MAX,  false);
            if (wallBetween) pruned++; else kept++;
            if (wallBetween)
                logf("M404 world-penalized arc (%.1f,%.1f,%.1f) -> (%.1f,%.1f,%.1f) hit at %.1f of %.1fm\n",
                    pa.m_X, pa.m_Y, pa.m_Z, pb.m_X, pb.m_Y, pb.m_Z, hitDist, len);
            survivors.push_back(nb);

            survivorPenalty.push_back((h < g_navArcPenalty.size() && survivorPenalty.size() < g_navArcPenalty[h].size()
                                       ? g_navArcPenalty[h][survivorPenalty.size()] : 1.0f)
                                      * (wallBetween ? WORLD_ARC_PENALTY : 1.0f));
        }
        g_navAdj[h].swap(survivors);
        if (h < g_navArcPenalty.size()) g_navArcPenalty[h].swap(survivorPenalty);
    }
    checkpointf("MILESTONE 105 - real nav arcs vs world geometry: %u direction(s) PENALIZED, %u clear",
        pruned, kept);
}

static int NavNearestHub(const Vector3& pos)
{
    int best = -1;
    float bestDistSq = 0.0f;
    for (size_t i = 0; i < g_navHubs.size(); ++i)
    {
        const float dx = g_navHubs[i].position.m_X - pos.m_X;
        const float dz = g_navHubs[i].position.m_Z - pos.m_Z;
        const float d = dx * dx + dz * dz;
        if (best < 0 || d < bestDistSq) { best = (int)i; bestDistSq = d; }
    }
    return best;
}

static bool NavFindPath(int startHub, int goalHub, std::vector<uint16_t>& outPath,
                        uint8_t requireFlag = 1,
                        const int* avoid = nullptr)
{
    outPath.clear();
    if (startHub < 0 || goalHub < 0) return false;
    if (startHub >= (int)g_navHubs.size() || goalHub >= (int)g_navHubs.size()) return false;
    if (startHub == goalHub) { outPath.push_back((uint16_t)startHub); return true; }

    const size_t n = g_navHubs.size();
    std::vector<float> gScore(n, 3.4e38f);
    std::vector<int> cameFrom(n, -1);
    std::vector<uint8_t> closed(n, 0);

    auto heuristic = [&](int a, int b)
    {
        const float dx = g_navHubs[a].position.m_X - g_navHubs[b].position.m_X;
        const float dz = g_navHubs[a].position.m_Z - g_navHubs[b].position.m_Z;
        return sqrtf(dx * dx + dz * dz);
    };

    std::vector<uint8_t> open(n, 0);
    gScore[startHub] = 0.0f;
    open[startHub] = 1;

    for (;;)
    {
        int current = -1;
        float bestF = 0.0f;
        for (size_t i = 0; i < n; ++i)
        {
            if (!open[i]) continue;
            const float f = gScore[i] + heuristic((int)i, goalHub);
            if (current < 0 || f < bestF) { current = (int)i; bestF = f; }
        }
        if (current < 0) return false;

        if (current == goalHub)
        {
            for (int at = goalHub; at >= 0; at = cameFrom[at]) outPath.push_back((uint16_t)at);
            std::reverse(outPath.begin(), outPath.end());
            return true;
        }

        open[current] = 0;
        closed[current] = 1;
        for (size_t ni = 0; ni < g_navAdj[current].size(); ++ni)
        {
            const uint16_t nb = g_navAdj[current][ni];
            if (nb >= n || closed[nb]) continue;
            if (NavArcBlocked((uint32_t)current, nb)) continue;
            if (avoid && nb != goalHub && (nb == avoid[0] || nb == avoid[1] || nb == avoid[2])) continue;
            if (requireFlag != 1)
            {
                auto fl = g_navArcFlags.find(((uint32_t)current << 16) | nb);
                if (fl == g_navArcFlags.end() || (fl->second & requireFlag) == 0) continue;
            }

            const float penalty = (current < g_navArcPenalty.size() && ni < g_navArcPenalty[current].size())
                                  ? g_navArcPenalty[current][ni] : 1.0f;
            const float tentative = gScore[current] + heuristic(current, nb) * penalty;
            if (tentative < gScore[nb])
            {
                gScore[nb] = tentative;
                cameFrom[nb] = current;
                open[nb] = 1;
            }
        }
    }
}

struct RnLocate { int hub = -1; int arcA = -1, arcB = -1; int tier = 0; };
static float RnArcProject(const NavHub& A, const NavHub& B, const Vector3& p, float& outDist, float& outR)
{
    const float ex = B.position.m_X - A.position.m_X, ey = B.position.m_Y - A.position.m_Y, ez = B.position.m_Z - A.position.m_Z;
    const float l2 = ex * ex + ey * ey + ez * ez;
    const float t = l2 > 1e-6f ? ((p.m_X - A.position.m_X) * ex + (p.m_Y - A.position.m_Y) * ey + (p.m_Z - A.position.m_Z) * ez) / l2 : 0.0f;
    const float qx = p.m_X - (A.position.m_X + ex * t), qy = p.m_Y - (A.position.m_Y + ey * t), qz = p.m_Z - (A.position.m_Z + ez * t);
    outDist = sqrtf(qx * qx + qy * qy + qz * qz);
    outR = t * B.radius + (1.0f - t) * A.radius;
    return t;
}
static RnLocate RetailNavLocate(const Vector3& p)
{
    RnLocate r;
    float best = 10000.0f;
    for (size_t i = 0; i < g_navHubs.size(); ++i)
    {
        if (i >= g_navHubSoldier.size() || !g_navHubSoldier[i]) continue;
        const NavHub& h = g_navHubs[i];
        if (h.radius >= best) continue;
        const float dx = h.position.m_X - p.m_X, dz = h.position.m_Z - p.m_Z;
        if (dx * dx + dz * dz < h.radius * h.radius) { best = h.radius; r.hub = (int)i; r.tier = 1; }
    }
    if (r.hub >= 0) return r;
    best = 10000.0f;
    for (const NavArcRec& a : g_navArcList)
    {
        if (a.attr & 7) continue;
        const NavHub& A = g_navHubs[a.a]; const NavHub& B = g_navHubs[a.b];
        if (A.radius + B.radius >= best) continue;
        float d, rr; const float t = RnArcProject(A, B, p, d, rr);
        if (t >= 0.0f && t <= 1.0f && d < rr) { best = A.radius + B.radius; r.arcA = a.a; r.arcB = a.b; r.tier = 2; }
    }
    if (r.arcA >= 0) return r;
    best = 3.4e38f;
    for (const NavArcRec& a : g_navArcList)
    {
        if (a.attr & 1) continue;
        const NavHub& A = g_navHubs[a.a]; const NavHub& B = g_navHubs[a.b];
        float d, rr; const float t = RnArcProject(A, B, p, d, rr);
        float g;
        if (t >= 0.0f && t <= 1.0f) g = d < rr ? 0.0f : d - rr;
        else
        {
            const NavHub& E = t < 0.0f ? A : B;
            const float x = p.m_X - E.position.m_X, y = p.m_Y - E.position.m_Y, z = p.m_Z - E.position.m_Z;
            g = fmaxf(0.0f, sqrtf(x * x + y * y + z * z) - E.radius);
        }
        if (g < best) { best = g; r.arcA = a.a; r.arcB = a.b; r.tier = 3; }
    }
    return r;
}

static float RnRouteLen(const std::vector<uint16_t>& path)
{
    float s = 0.0f;
    for (size_t i = 1; i < path.size(); ++i)
    {
        const Vector3& a = g_navHubs[path[i - 1]].position; const Vector3& b = g_navHubs[path[i]].position;
        s += sqrtf((a.m_X - b.m_X) * (a.m_X - b.m_X) + (a.m_Z - b.m_Z) * (a.m_Z - b.m_Z));
    }
    return s;
}
static uint32_t g_rnLocHub = 0, g_rnLocCorridor = 0, g_rnLocNearest = 0;

static int NavComponentOf(const Vector3& p)
{
    if (g_navComp.size() != g_navHubs.size())
    {
        g_navComp.assign(g_navHubs.size(), -1);
        std::vector<std::vector<uint16_t>> und(g_navHubs.size());
        for (const NavArcRec& a : g_navArcList) { und[a.a].push_back(a.b); und[a.b].push_back(a.a); }
        int c = 0;
        for (size_t s = 0; s < g_navHubs.size(); ++s)
        {
            if (g_navComp[s] >= 0) continue;
            std::vector<size_t> st{ s }; g_navComp[s] = c;
            while (!st.empty()) { size_t h = st.back(); st.pop_back(); for (uint16_t nb : und[h]) if (g_navComp[nb] < 0) { g_navComp[nb] = c; st.push_back(nb); } }
            ++c;
        }
    }
    const RnLocate l = RetailNavLocate(p);
    const int h = l.hub >= 0 ? l.hub : l.arcA;
    return h >= 0 ? g_navComp[(size_t)h] : -1;
}

static uint32_t g_routeLcg = 0x2545f491u;
static uint32_t RouteRand()
{
    const uint32_t a = g_routeLcg * 0x19660du + 0x3c6ef35fu;
    g_routeLcg = a * 0x19660du + 0x3c6ef35fu;
    return (g_routeLcg & 0xffff0000u) | (a >> 16);
}
static uint32_t g_routeWalks = 0, g_routeFallbacks = 0;

static int RouteNextHop(int h, int arr, int dest, int type = 0)
{
    const NavHub& H = g_navHubs[(size_t)h];
    const int16_t* slotNext = H.slotNext[type];
    const int rowCount = H.rowCount[type];
    if (rowCount == 0 || dest < (int)H.setBase || dest >= (int)(H.setBase + H.setCount)) return -1;
    const size_t di = (size_t)(dest - (int)H.setBase);
    auto entry = [&](int k) { return H.rows[type][(size_t)k * H.setCount + di]; };
    int budget = 31;
    if (arr >= 0)
        for (int k = 0; k < rowCount; ++k)
        {
            const uint8_t e = entry(k);
            if (e == 0) break;
            if ((e & 7) == arr) { budget = 31 - (e >> 3); break; }
        }
    if (budget < 1)
    {
        int o[8], n = 0;
        for (int sl = 0; sl < 8; ++sl) if (slotNext[sl] >= 0 && sl != arr) o[n++] = slotNext[sl];
        return n ? o[RouteRand() % (uint32_t)n] : -1;
    }
    if (entry(0) == 0) return -1;
    int r = (int)(RouteRand() % (uint32_t)budget);
    for (int k = 0; k < rowCount; ++k)
    {
        const uint8_t e = entry(k);
        if (e == 0) return -1;
        r -= (e >> 3);
        if (r < 1 && (e & 7) != arr) return slotNext[e & 7];
    }
    return -1;
}

static bool RouteWalk(int start, int goal, std::vector<uint16_t>& out, int type = 0)
{
    out.clear(); out.push_back((uint16_t)start);
    if (start == goal) return true;
    int h = start, arr = -1;
    for (uint32_t steps = 0; steps < 2u * g_navHubs[(size_t)start].setCount + 2u; ++steps)
    {
        const int nx = RouteNextHop(h, arr, goal, type);
        if (nx < 0 || NavArcBlocked((uint32_t)h, (uint32_t)nx)) return false;
        arr = -1;
        for (int sl = 0; sl < 8; ++sl) if (g_navHubs[(size_t)nx].slotNext[type][sl] == h) { arr = sl; break; }
        h = nx; out.push_back((uint16_t)h);
        if (h == goal) return true;
    }
    return false;
}
static bool RetailNavPlan(const Vector3& from, const Vector3& to, std::vector<uint16_t>& out, const int* avoid = nullptr)
{
    out.clear();
    const RnLocate s = RetailNavLocate(from), g = RetailNavLocate(to);
    std::vector<int> starts, goals;
    if (s.hub >= 0) starts.push_back(s.hub);
    else if (s.arcA >= 0) { starts.push_back(s.arcA); starts.push_back(s.arcB); }
    if (s.tier == 1) ++g_rnLocHub; else if (s.tier == 2) ++g_rnLocCorridor; else if (s.tier == 3) ++g_rnLocNearest;
    if (g.hub >= 0) goals.push_back(g.hub);
    else if (g.arcA >= 0) { goals.push_back(g.arcA); goals.push_back(g.arcB); }
    if (starts.empty() || goals.empty()) return false;
    float best = 3.4e38f;
    std::vector<uint16_t> path;
    for (int sh : starts)
        for (int gh : goals)
        {
            ++g_routeWalks;
            if (!RouteWalk(sh, gh, path))
            {
                ++g_routeFallbacks;
                if (!NavFindPath(sh, gh, path, 1, avoid) && !(avoid && NavFindPath(sh, gh, path))) continue;
            }
            const Vector3& a = g_navHubs[sh].position; const Vector3& b = g_navHubs[gh].position;
            const float c = sqrtf((from.m_X - a.m_X) * (from.m_X - a.m_X) + (from.m_Z - a.m_Z) * (from.m_Z - a.m_Z))
                          + RnRouteLen(path)
                          + sqrtf((to.m_X - b.m_X) * (to.m_X - b.m_X) + (to.m_Z - b.m_Z) * (to.m_Z - b.m_Z));
            if (c < best) { best = c; out = path; }
        }
    return !out.empty();
}

static const char* FactionSuffixForTeam(int team)
{
    if (team < 0 || (size_t)team >= g_teams.size()) return "Locals";
    const std::string& n = g_teams[(size_t)team].name;
    if (n == "rep") return "Republic";
    if (n == "cis") return "CIS";
    if (n == "imp") return "Empire";
    if (n == "all") return "Alliance";
    return "Locals";
}

static float CpValue(const std::map<std::string, float>& m, const char* fac)
{
    auto it = m.find(fac);
    return it != m.end() ? it->second : 10.0f;
}

static int NavComponentOf(const Vector3& p);

static int RetailConquestPost(int team, const Vector3& fromPos, bool& outDefend)
{
    const char* fac = FactionSuffixForTeam(team);
    const size_t n = g_commandPosts.size();
    if (n == 0) return -1;
    const int myComp = NavComponentOf(fromPos);
    for (int pass = 0; pass < 2; ++pass)
    {
        std::vector<float> w(n, 0.0f);
        float sum = 0.0f;
        for (size_t i = 0; i < n; ++i)
        {
            const CommandPostState& cp = g_commandPosts[i];
            const bool ally = cp.team == team, enemy = cp.team >= 1 && cp.team != team && IsHostile(cp.team, team);
            if (pass == 0 && ally) continue;
            const float v = ally ? CpValue(cp.valueDef, fac) : enemy ? CpValue(cp.valueAtk, fac)
                                 : 0.5f * (CpValue(cp.valueAtk, fac) + CpValue(cp.valueDef, fac));
            if (v <= 0.0f) continue;
            if (myComp >= 0) { const int c = NavComponentOf(cp.position); if (c >= 0 && c != myComp) continue; }
            w[i] = v; sum += v;
        }
        if (sum <= 0.0f) continue;
        float r = ((float)rand() / (float)RAND_MAX) * sum, acc = 0.0f;
        for (size_t i = 0; i < n; ++i)
        {
            if (w[i] <= 0.0f) continue;
            acc += w[i];
            if (r <= acc) { outDefend = (g_commandPosts[i].team == team); return (int)i; }
        }
        for (size_t i = n; i-- > 0; ) if (w[i] > 0.0f) { outDefend = (g_commandPosts[i].team == team); return (int)i; }
    }
    const int i = rand() % (int)n;
    outDefend = (g_commandPosts[(size_t)i].team == team);
    return i;
}
static bool g_retailConquest = true;
static int ChooseConquestPost(int team, const Vector3& fromPos, int currentCp,
                              const std::vector<int>& assigned, const std::vector<int>& enemiesNear,
                              int teamUnits, bool& outDefend)
{
    if (g_retailConquest) return RetailConquestPost(team, fromPos, outDefend);
    const char* fac = FactionSuffixForTeam(team);
    const size_t n = g_commandPosts.size();

    bool dmOnly = TeamDeathmatchOnly(team);
    std::vector<float> w(n, 0.0f);
    float sumW = 0.0f;
    for (size_t i = 0; i < n; ++i)
    {
        const CommandPostState& cp = g_commandPosts[i];
        if (cp.team == team)
        {
            if (dmOnly) continue;

            float threat = 0.25f + 0.5f * (float)enemiesNear[i];
            if (cp.captureCount > 0 && cp.captureTeam != team) threat += 2.0f;
            w[i] = CpValue(cp.valueDef, fac) * fminf(threat, 4.0f);
        }
        else
            w[i] = CpValue(cp.valueAtk, fac);
        sumW += w[i];
    }
    if (sumW <= 0.0f)
    {
        if (!dmOnly) return -1;

        int best = -1; float bd = -1.0f;
        for (size_t i = 0; i < n; ++i)
        {
            const float dx = g_commandPosts[i].position.m_X - fromPos.m_X;
            const float dz = g_commandPosts[i].position.m_Z - fromPos.m_Z;
            const float d = dx * dx + dz * dz;
            if (d > bd) { bd = d; best = (int)i; }
        }
        if (best < 0) return -1;
        outDefend = false;
        return best;
    }

    std::vector<float> score(n, 0.0f);
    float sumS = 0.0f;
    for (size_t i = 0; i < n; ++i)
    {
        if (w[i] <= 0.0f) continue;
        const CommandPostState& cp = g_commandPosts[i];
        const float dx = cp.position.m_X - fromPos.m_X, dz = cp.position.m_Z - fromPos.m_Z;
        const float dist = sqrtf(dx * dx + dz * dz);
        const float share = fmaxf(0.5f, (float)teamUnits * w[i] / sumW);
        const float crowd = 1.0f / (1.0f + (float)assigned[i] / share);
        const float near  = 1.0f / (1.0f + dist / 120.0f);
        score[i] = w[i] * crowd * near * ((int)i == currentCp ? 1.5f : 1.0f);
        sumS += score[i];
    }
    float r = ((float)rand() / (float)RAND_MAX) * sumS;
    for (size_t i = 0; i < n; ++i)
    {
        if (score[i] <= 0.0f) continue;
        r -= score[i];
        if (r <= 0.0f) { outDefend = (g_commandPosts[i].team == team); return (int)i; }
    }
    for (size_t i = n; i-- > 0; ) if (score[i] > 0.0f) { outDefend = (g_commandPosts[i].team == team); return (int)i; }
    return -1;
}

static const CommandPostState* ChooseAITargetCP(int team, const Vector3& fromPos, size_t unitIndex,
                                                int currentCpIndex = -1)
{
    const CommandPostState* candidates[3] = { nullptr, nullptr, nullptr };
    float candidateDistSq[3] = { 0.0f, 0.0f, 0.0f };
    int candidateCount = 0;
    for (const CommandPostState& cp : g_commandPosts)
    {
        if (cp.team == team) continue;
        float dx = cp.position.m_X - fromPos.m_X, dz = cp.position.m_Z - fromPos.m_Z;
        float distSq = dx * dx + dz * dz;

        int insertAt = candidateCount < 3 ? candidateCount : -1;
        for (int i = 0; i < candidateCount && i < 3; ++i)
        {
            if (distSq < candidateDistSq[i]) { insertAt = i; break; }
        }
        if (insertAt >= 0)
        {
            for (int i = (candidateCount < 3 ? candidateCount : 2); i > insertAt; --i)
            {
                candidates[i] = candidates[i - 1];
                candidateDistSq[i] = candidateDistSq[i - 1];
            }
            candidates[insertAt] = &cp;
            candidateDistSq[insertAt] = distSq;
            if (candidateCount < 3) candidateCount++;
        }
    }

    for (int i = 0; i < candidateCount; ++i)
        if (currentCpIndex >= 0 && candidates[i] == &g_commandPosts[(size_t)currentCpIndex]) return candidates[i];
    if (candidateCount > 0) return candidates[unitIndex % (size_t)candidateCount];

    const CommandPostState* best = nullptr;
    float bestDistSq = 0.0f;
    for (const CommandPostState& cp : g_commandPosts)
    {
        if (cp.team != team) continue;
        float dx = cp.position.m_X - fromPos.m_X, dz = cp.position.m_Z - fromPos.m_Z;
        float distSq = dx * dx + dz * dz;
        if (best == nullptr || distSq < bestDistSq) { best = &cp; bestDistSq = distSq; }
    }
    return best;
}

static uint64_t g_aiCollisionUs = 0;
static uint64_t g_postFxUs = 0;

static uint64_t g_aiLapT = 0, g_aiSecUs[15] = {};
static int g_aiLapSec = -1;
static bool g_aiProf = false;
static inline void AiLap(int nextSec)
{
    if (!g_aiProf) return;
    const uint64_t t = sceKernelGetProcessTimeWide();
    if (g_aiLapSec >= 0) g_aiSecUs[g_aiLapSec] += t - g_aiLapT;
    g_aiLapT = t; g_aiLapSec = nextSec;
}

static void IntegrateAIBlastPush(AIUnitState& au, PlacedInstance& pi, float deltaSec,
                                 const TerrainData& terrainData,
                                 const std::vector<ModelData>& uniqueModels,
                                 std::vector<PlacedInstance>& placedRef)
{
            if (au.pushVelX != 0.0f || au.pushVelY != 0.0f || au.pushVelZ != 0.0f)
            {
                const float startY = pi.position.m_Y;
                pi.position.m_X += au.pushVelX * deltaSec;
                pi.position.m_Y += au.pushVelY * deltaSec;
                pi.position.m_Z += au.pushVelZ * deltaSec;
                au.pushVelY -= 9.81f * deltaSec;
                const float decay = fmaxf(0.0f, 1.0f - deltaSec * 2.0f);
                au.pushVelX *= decay; au.pushVelZ *= decay;

                bool retailLanded = false;
                if (g_retailSoldierCollision)
                {
                    EnsureRetailWorld(uniqueModels, placedRef, terrainData);
                    rsc::Body& rb = au.rscBody;
                    rb.pos = rsc::V3(pi.position.m_X, pi.position.m_Y, pi.position.m_Z);
                    rb.vel = rsc::V3(au.pushVelX, au.pushVelY, au.pushVelZ);
                    rsc::ResolveContacts(g_rscWorld, rb, 0.0f, 0.0f, au.rscScale > 0.0f ? au.rscScale : 1.0f, nullptr, nullptr, 4, false);
                    pi.position = Vector3(rb.pos.x, rb.pos.y, rb.pos.z);
                    au.pushVelX = rb.vel.x; au.pushVelZ = rb.vel.z;
                    if (au.pushVelY < 0.0f || rb.vel.y < au.pushVelY) au.pushVelY = rb.vel.y;
                    retailLanded = rb.grounded && au.pushVelY <= 0.0f;
                    if (retailLanded && au.pushVelY < 0.0f) au.pushVelY = -0.01f;
                }

                if (au.pushVelY < 0.0f)
                {

                    float gy = pi.position.m_Y; Vector3 gn;
                    if (g_retailSoldierCollision ? retailLanded
                        : (GetCombinedGroundHeightAt(terrainData, uniqueModels, placedRef,
                                                     pi.position.m_X, fmaxf(startY, pi.position.m_Y), pi.position.m_Z,
                                                     au.terrainHint, gy, gn, au.placedIndex)
                           && pi.position.m_Y <= gy))
                    {
                        pi.position.m_Y = gy;
                        if (g_retailSoldierCollision) { au.rscBody.vel = rsc::V3(0, 0, 0); au.rscBody.airTime = 0.0f; }

                        const float hs = sqrtf(au.pushVelX * au.pushVelX + au.pushVelZ * au.pushVelZ);
                        if (au.thrown && au.thrownPhase == 1 && hs > 3.0f)
                        {
                            au.thrownSliding = true;
                            const float f = fmaxf(0.0f, 1.0f - 5.0f * deltaSec);
                            au.pushVelX *= f; au.pushVelZ *= f; au.pushVelY = 0.0f;
                            return;
                        }
                        au.pushVelX = au.pushVelY = au.pushVelZ = 0.0f;

                        if (au.thrown && au.life == AI_LIFE_ALIVE && au.thrownPhase == 1) { au.thrownPhase = 2; au.thrownTimer = 0.0f; au.thrownSliding = false; }
                        else if (au.thrown && au.life != AI_LIFE_ALIVE) { au.thrown = false; au.thrownPhase = 0; }
                    }
                    else
                    {

                        float ty; Vector3 tn;
                        if (GetTerrainHeightAt(terrainData, pi.position.m_X, pi.position.m_Z, ty, tn, au.terrainHint) && pi.position.m_Y < ty - 8.0f)
                        {
                            checkpointf("M470 fell through the world: AI placed %u at (%.1f,%.1f,%.1f) terrain %.1f - put back on the terrain",
                                        (unsigned)au.placedIndex, pi.position.m_X, pi.position.m_Y, pi.position.m_Z, ty);
                            pi.position.m_Y = ty;
                            au.pushVelX = au.pushVelY = au.pushVelZ = 0.0f;
                            if (au.thrown && au.life == AI_LIFE_ALIVE && au.thrownPhase == 1) { au.thrownPhase = 2; au.thrownTimer = 0.0f; au.thrownSliding = false; }
                            else if (au.thrown && au.life != AI_LIFE_ALIVE) { au.thrown = false; au.thrownPhase = 0; }
                        }
                    }
                }
            }

}

