static void BlackBoxDump(const std::vector<PlacedInstance>& placed, const Vector3& eye, float eyeYaw, float matchSec, const char* why)
{
    ++g_bbDumps;
    sceIoMkdir("ux0:data/swbf2/blackbox", 0777);
    char path[96]; snprintf(path, sizeof(path), "ux0:data/swbf2/blackbox/bb_%03u.txt", g_bbDumps);
    FILE* f = fopen(path, "w");

    int pick = g_bbFixedUnit; float bestD = 40.0f;
    const float fx = -sinf(eyeYaw), fz = -cosf(eyeYaw);
    if (pick < 0)
        for (size_t i = 0; i < g_aiUnits.size(); ++i)
        {
            const AIUnitState& au = g_aiUnits[i];
            if (au.life != AI_LIFE_ALIVE || au.placedIndex >= placed.size()) continue;
            const Vector3& p = placed[au.placedIndex].position;
            const float dx = p.m_X - eye.m_X, dz = p.m_Z - eye.m_Z, d = sqrtf(dx * dx + dz * dz);
            if (d < 0.5f || d > bestD || (dx * fx + dz * fz) < d * 0.866f) continue;
            bestD = d; pick = (int)i;
        }
    g_bbTraceUnit = pick; g_bbTraceLeft = pick >= 0 ? 10.0f : 0.0f;
    unsigned alive = 0;
    if (f)
    {
        fprintf(f, "BLACKBOX %u (%s) build M%d match t=%.1f s | player (%.2f,%.2f,%.2f) yaw %.2f | traced unit %d\n",
                g_bbDumps, why, SWBF2_BUILD_MILESTONE, matchSec, eye.m_X, eye.m_Y, eye.m_Z, eyeYaw, pick);
        for (const CommandPostState& c : g_commandPosts)
            fprintf(f, "post %s team %d at (%.1f,%.1f,%.1f)\n", c.name.c_str(), c.team, c.position.m_X, c.position.m_Y, c.position.m_Z);
    }
    for (size_t i = 0; i < g_aiUnits.size(); ++i)
    {
        const AIUnitState& au = g_aiUnits[i];
        if (au.placedIndex >= placed.size()) continue;
        const PlacedInstance& pi = placed[au.placedIndex];
        if (au.life == AI_LIFE_ALIVE) ++alive;
        if (!f) continue;
        fprintf(f, "u%u %s team %d life %d pos (%.2f,%.2f,%.2f) vel (%.2f,%.2f) inVeh %d | goal cp%d defend %d | route %u/%u hub %d wp (%.2f,%.2f) prev (%.2f,%.2f) leg %u/%u",
            (unsigned)i, pi.unitClass.c_str(), pi.team, (int)au.life, pi.position.m_X, pi.position.m_Y, pi.position.m_Z, au.velX, au.velZ,
            (int)pi.inVehicle, au.cachedTargetCpIndex, (int)au.targetIsDefend, (unsigned)au.navPathIndex, (unsigned)au.navPath.size(),
            au.rnHub, au.rnX, au.rnZ, au.rnPrevX, au.rnPrevZ, (unsigned)au.rnLegIdx, (unsigned)(au.rnLeg.size() / 2));
        for (size_t k = 0; k + 1 < au.rnLeg.size(); k += 2) fprintf(f, " c(%.2f,%.2f)", au.rnLeg[k], au.rnLeg[k + 1]);
        fprintf(f, " | anchorSec %.1f bestSec %.1f stuckEv %u blockEv %u | rw %d to (%.1f,%.1f) %.1fs | push (%.2f,%.2f) side %d | target %d hint %d why %d sec %d crowd %.1f | path:",
            au.rnAnchorSec, au.rnBestSec, au.rnStuck, au.rnBlocked, (int)au.rwActive, au.rwTX, au.rwTZ, au.rwSec,
            au.rscBody.wallPush.x, au.rscBody.wallPush.z, (int)au.sideStep, (int)au.haveCachedTarget, au.hintNodeIdx, (int)au.why, (int)au.exitSec, au.crowdTimer);
        for (uint16_t h : au.navPath) fprintf(f, " %u", (unsigned)h);
        fprintf(f, "\n");
    }
    if (f) fclose(f);
    checkpointf("M532 BLACKBOX %u (%s): %u AI alive, state of every unit -> %s; tracing u%d every frame for 10 s", g_bbDumps, why, alive, path, pick);
}
