static float DeepestWallOverlap(const rsc::World& w, const rsc::V3& s, float r)
{
    float worst = 0.0f;
    const int ax = (int)floorf((s.x - r) / w.cell), bx = (int)floorf((s.x + r) / w.cell);
    const int az = (int)floorf((s.z - r) / w.cell), bz = (int)floorf((s.z + r) / w.cell);
    for (int ix = ax; ix <= bx; ++ix) for (int iz = az; iz <= bz; ++iz)
        for (uint32_t id : w.grid.Cell(ix, iz))
        {
            if ((id & 0xC0000000u) == 0xC0000000u)
            {
                if (w.Off(w.boxObj[id & 0x3fffffffu])) continue;
                const rsc::Box& q = w.box[id & 0x3fffffffu];
                const rsc::V3 d = s - q.c;
                const float lx = rsc::Dot(d, q.ax), ly = rsc::Dot(d, q.ay), lz = rsc::Dot(d, q.az);
                const float px = q.h.x - fabsf(lx), py = q.h.y - fabsf(ly), pz = q.h.z - fabsf(lz);
                if (px <= 0 || py <= 0 || pz <= 0) continue;
                if (py <= px && py <= pz) continue;
                const float pen = fminf(px, pz) + r;
                if (pen > worst) worst = pen;
                continue;
            }
            if (id & 0x80000000u) continue;
            if (id & 0x40000000u)
            {
                const rsc::Cyl& q = w.cyl[id & 0x3fffffffu];
                const float cy = fmaxf(q.c.y - q.halfH, fminf(q.c.y + q.halfH, s.y));
                const float dx = s.x - q.c.x, dz = s.z - q.c.z; const float hl = sqrtf(dx * dx + dz * dz);
                if (hl >= q.r + r) continue;
                if (hl <= q.r) { const float pen = q.r - hl + r; if (pen > worst) worst = pen; }
                else { const float pen = r - (hl - q.r); if (pen > worst) worst = pen; }
                (void)cy;
                continue;
            }
            if (!w.objOff.empty() && w.Off(w.triObj[id])) continue;
            const rsc::V3 a = w.tri[id * 3], b = w.tri[id * 3 + 1], c = w.tri[id * 3 + 2];
            if (s.y + r < fminf(a.y, fminf(b.y, c.y)) || s.y - r > fmaxf(a.y, fmaxf(b.y, c.y))) continue;
            const rsc::V3 cp = rsc::ClosestOnTri(s, a, b, c);
            const rsc::V3 d = s - cp; const float l = rsc::Len(d);
            if (l >= r) continue;
            rsc::V3 n = (l > 1e-5f) ? d * (1.0f / l) : rsc::Norm(rsc::Cross(b - a, c - a));
            if (fabsf(n.y) >= 0.3f) continue;
            if (r - l > worst) worst = r - l;
        }
    return worst;
}
static float StaticOverlapAt(const Vector3& feet, float scale, bool crouch)
{
    if (!g_rscBuilt) return 0.0f;
    const float ys[2] = { rsc::kLowerY, rsc::UpperY(scale > 0.0f ? scale : 1.0f, crouch) };
    float worst = 0.0f;
    for (int k = 0; k < 2; ++k)
    {
        const float d = DeepestWallOverlap(g_rscWorld, rsc::V3(feet.m_X, feet.m_Y + ys[k], feet.m_Z), rsc::kRadius);
        if (d > worst) worst = d;
    }
    return worst;
}

struct ExitSpot { Vector3 pos; int cand; bool ground; };

static bool g_exitOldDbg = getenv("SWBF2_EXITOLD") != nullptr;
static bool g_exitGeoDbg = false;
static Vector3 ExitSpotOld(const Vector3& vp, float yaw, float side,
                           const TerrainData& terrainData, const std::vector<ModelData>& uniqueModels,
                           const std::vector<PlacedInstance>& placed, const char* cls)
{
    const Vector3 rgt = GetRight(yaw);
    Vector3 out(vp.m_X - rgt.m_X * side, vp.m_Y, vp.m_Z - rgt.m_Z * side);
    const Vector3 fwd = GetForward(yaw, 0.0f);
    const float cand[4][2] = { { -rgt.m_X, -rgt.m_Z }, { rgt.m_X, rgt.m_Z }, { -fwd.m_X, -fwd.m_Z }, { fwd.m_X, fwd.m_Z } };
    for (int ci = 0; ci < 4; ++ci)
    {
        const Vector3 c(vp.m_X + cand[ci][0] * side, vp.m_Y, vp.m_Z + cand[ci][1] * side);
        float cgy = c.m_Y; Vector3 cgn(0.0f, 1.0f, 0.0f); uint32_t ch = 0;
        if (!GetCombinedGroundHeightAt(terrainData, uniqueModels, placed, c.m_X, vp.m_Y + 2.0f, c.m_Z, ch, cgy, cgn)) continue;
        if (fabsf(cgy - vp.m_Y) > 3.0f) continue;
        out = c;
        if (ci > 0) checkpointf("EXITSPOT \"%s\": left spot unusable, exit %s", cls, ci == 1 ? "right" : ci == 2 ? "behind" : "ahead");
        break;
    }
    return out;
}
static ExitSpot RetailExitSpot(const Vector3& vp, float yaw, float hullRadius, float scale,
                               const TerrainData& terrainData, const std::vector<ModelData>& uniqueModels,
                               const std::vector<PlacedInstance>& placed, size_t selfPlaced)
{
    ExitSpot r; r.pos = vp; r.cand = 8; r.ground = false;
    const float rho = hullRadius + 0.684f;
    const float k = 0.7071f;
    const Vector3 fwd = GetForward(yaw, 0.0f);
    const Vector3 rgt = GetRight(yaw);
    const float cand[9][2] =
    {
        { 0.0f, -1.0f }, { -1.0f, 0.0f }, { 1.0f, 0.0f },
        { -k, -k }, { k, -k }, { k, k }, { -k, k },
        { 0.0f, 1.0f }, { 0.0f, 0.0f }
    };
    for (int i = 0; i < 9; ++i)
    {
        const Vector3 c(vp.m_X + rgt.m_X * cand[i][0] * rho + fwd.m_X * cand[i][1] * rho,
                        vp.m_Y + 1.0f,
                        vp.m_Z + rgt.m_Z * cand[i][0] * rho + fwd.m_Z * cand[i][1] * rho);
        if (i != 8)
        {

            const Vector3 a(vp.m_X, vp.m_Y + 1.0f, vp.m_Z);
            const Vector3 d(c.m_X - a.m_X, 0.0f, c.m_Z - a.m_Z);
            const float len = sqrtf(d.m_X * d.m_X + d.m_Z * d.m_Z);
            float hd = 0.0f; Vector3 hp;
            if (len > 0.01f && FireRayHitTest(a, d, len, uniqueModels, placed, hd, hp, selfPlaced, true) && hd < len - 0.02f) continue;
        }

        float upT = 1.0f;
        {
            float hd = 0.0f; Vector3 hp;
            if (FireRayHitTest(c, Vector3(0.0f, 1.0f, 0.0f), 5.0f, uniqueModels, placed, hd, hp, selfPlaced, true)) upT = hd / 5.0f;
        }
        const Vector3 top(c.m_X, c.m_Y + 5.0f * upT - 0.1f, c.m_Z);

        const float downMax = 15.5f;
        float best = downMax;
        {
            const Vector3 dn(0.0f, -1.0f, 0.0f);
            float hd = 0.0f; Vector3 hp;
            if (FireRayHitTest(top, dn, downMax, uniqueModels, placed, hd, hp, selfPlaced, true) && hd < best) best = hd;
            uint32_t th = 0;
            const float td = RayTerrainImpactDist(top, dn, downMax, terrainData, th);
            if (td < best) best = td;
        }
        if (best < 15.0f)
        {
            r.pos = Vector3(c.m_X, top.m_Y - best, c.m_Z);
            r.cand = i; r.ground = true;

            if (StaticOverlapAt(r.pos, scale, false) <= rsc::kRadius + 0.03f) return r;
        }
    }
    return r;
}

static float ExitWallDist(const Vector3& p, float reach, const std::vector<ModelData>& uniqueModels,
                          const std::vector<PlacedInstance>& placed, size_t selfPlaced)
{
    float best = 1e30f;
    const Vector3 o(p.m_X, p.m_Y + 0.9f, p.m_Z);
    for (int i = 0; i < 8; ++i)
    {
        const float a = i * 0.785398f;
        const Vector3 d(cosf(a), 0.0f, sinf(a));
        float hd = 0.0f; Vector3 hp;
        if (FireRayHitTest(o, d, reach, uniqueModels, placed, hd, hp, selfPlaced, true) && hd < best) best = hd;
    }
    return best;
}

static bool ExitPathBlocked(const Vector3& vp, const Vector3& spot, const std::vector<ModelData>& uniqueModels,
                            const std::vector<PlacedInstance>& placed, size_t selfPlaced, float& hitAt)
{
    const Vector3 a(vp.m_X, vp.m_Y + 1.0f, vp.m_Z);
    const Vector3 b(spot.m_X, vp.m_Y + 1.0f, spot.m_Z);
    const Vector3 d(b.m_X - a.m_X, 0.0f, b.m_Z - a.m_Z);
    const float len = sqrtf(d.m_X * d.m_X + d.m_Z * d.m_Z);
    hitAt = len;
    if (len < 0.01f) return false;
    float hd = 0.0f; Vector3 hp;
    if (!FireRayHitTest(a, d, len, uniqueModels, placed, hd, hp, selfPlaced, true)) return false;
    hitAt = hd;
    return hd < len - 0.02f;
}
struct ExitGeoTally
{
    unsigned spots = 0, wallSpots = 0;
    unsigned oldBlocked = 0, newBlocked = 0;
    unsigned oldWallBlocked = 0, newWallBlocked = 0;
    unsigned oldInside = 0, oldAny = 0, newInside = 0, newAny = 0;
    unsigned newDeep = 0;
    float oldMax = 0.0f, newMax = 0.0f;
    std::string oldWorst, newWorst;
    bool done = false;
};
static ExitGeoTally g_exitGeo;

static void ExitGeoSweep(float scale, const TerrainData& terrainData, const std::vector<ModelData>& uniqueModels,
                         const std::vector<PlacedInstance>& placed)
{
    if (!g_exitGeoDbg || g_exitGeo.done) return;
    g_exitGeo.done = true;
    int vehiclesDone = 0;
    for (size_t vi = 0; vi < g_vehicles.size() && vehiclesDone < 2; ++vi)
    {
        const VehicleState& v = g_vehicles[vi];
        if (!v.alive || v.isTurret || v.placedIndex >= placed.size()) continue;
        auto dit = g_vehicleClassDefs.find(v.cls);
        if (dit == g_vehicleClassDefs.end()) continue;
        const float hullR = dit->second.hullRadius, side = hullR + 1.0f;
        ++vehiclesDone;
        std::vector<Vector3> probes;
        for (const CommandPostState& cp : g_commandPosts) probes.push_back(cp.position);
        for (const VehicleSpawnState& vs : g_vehicleSpawns) probes.push_back(vs.position);
        const size_t base = probes.size();
        const float rings[3] = { 2.0f, 4.0f, 6.0f };
        for (size_t pi = 0; pi < base; ++pi)
            for (int r = 0; r < 3; ++r)
                for (int a = 0; a < 8; ++a)
                    probes.push_back(Vector3(probes[pi].m_X + rings[r] * cosf(a * 0.785398f), probes[pi].m_Y,
                                             probes[pi].m_Z + rings[r] * sinf(a * 0.785398f)));
        for (size_t pi = 0; pi < probes.size(); ++pi)
        {
            float gy = probes[pi].m_Y; Vector3 gn(0.0f, 1.0f, 0.0f); uint32_t hint = 0;
            if (!GetCombinedGroundHeightAt(terrainData, uniqueModels, placed, probes[pi].m_X, probes[pi].m_Y + 1.0f,
                                           probes[pi].m_Z, hint, gy, gn)) continue;
            const Vector3 p(probes[pi].m_X, gy, probes[pi].m_Z);
            const float wall = ExitWallDist(p, hullR + 4.0f, uniqueModels, placed, v.placedIndex);
            if (wall < hullR - 0.05f) continue;
            if (StaticOverlapAt(p, scale, false) > rsc::kRadius + 0.03f) continue;
            for (int yi = 0; yi < 8; ++yi)
            {
                const float yaw = yi * 0.785398f;
                const Vector3 oldS = ExitSpotOld(p, yaw, side, terrainData, uniqueModels, placed, v.cls.c_str());
                const ExitSpot ns = RetailExitSpot(p, yaw, hullR, scale, terrainData, uniqueModels, placed, v.placedIndex);

                Vector3 oldP = oldS, newP = ns.pos;
                { float oy = oldP.m_Y; Vector3 on(0.0f, 1.0f, 0.0f); uint32_t oh = 0;
                  if (GetCombinedGroundHeightAt(terrainData, uniqueModels, placed, oldP.m_X, p.m_Y + 2.0f, oldP.m_Z, oh, oy, on)) oldP.m_Y = oy; }
                { float ny = newP.m_Y; Vector3 nn(0.0f, 1.0f, 0.0f); uint32_t nh = 0;
                  if (GetCombinedGroundHeightAt(terrainData, uniqueModels, placed, newP.m_X, p.m_Y + 2.0f, newP.m_Z, nh, ny, nn)) newP.m_Y = ny; }
                const float ovOld = StaticOverlapAt(oldP, scale, false);
                const float ovNew = StaticOverlapAt(newP, scale, false);
                float hOld = 0.0f, hNew = 0.0f;
                const bool bOld = ExitPathBlocked(p, oldP, uniqueModels, placed, v.placedIndex, hOld);
                const bool bNew = ExitPathBlocked(p, newP, uniqueModels, placed, v.placedIndex, hNew);
                const bool wallSpot = wall < hullR + 1.5f;
                ++g_exitGeo.spots;
                if (wallSpot) ++g_exitGeo.wallSpots;
                if (bOld) { ++g_exitGeo.oldBlocked; if (wallSpot) ++g_exitGeo.oldWallBlocked; }
                if (bNew) { ++g_exitGeo.newBlocked; if (wallSpot) ++g_exitGeo.newWallBlocked; }
                if (ns.ground && newP.m_Y < p.m_Y - 3.0f) ++g_exitGeo.newDeep;
                if (ovOld > 0.05f) ++g_exitGeo.oldAny;
                if (ovNew > 0.05f) ++g_exitGeo.newAny;
                if (ovOld > 0.15f) ++g_exitGeo.oldInside;
                if (ovNew > 0.15f) ++g_exitGeo.newInside;
                char b[176];
                const float wallShow = (wall < 1e29f) ? wall : -1.0f;
                if (bOld || ovOld > g_exitGeo.oldMax)
                {
                    if (ovOld > g_exitGeo.oldMax) g_exitGeo.oldMax = ovOld;
                    snprintf(b, sizeof(b), "\"%s\" (%.1f,%.1f,%.1f) yaw %.0f wall %.1f old (%.1f,%.1f,%.1f) ov %.2f blocked %d at %.1f",
                             v.cls.c_str(), p.m_X, p.m_Y, p.m_Z, yaw * 57.2958f, wallShow, oldP.m_X, oldP.m_Y, oldP.m_Z, ovOld, (int)bOld, hOld);
                    g_exitGeo.oldWorst = b;
                }
                if (bNew || ovNew > g_exitGeo.newMax)
                {
                    if (ovNew > g_exitGeo.newMax) g_exitGeo.newMax = ovNew;
                    snprintf(b, sizeof(b), "\"%s\" (%.1f,%.1f,%.1f) yaw %.0f wall %.1f cand %d new (%.1f,%.1f,%.1f) ov %.2f blocked %d at %.1f",
                             v.cls.c_str(), p.m_X, p.m_Y, p.m_Z, yaw * 57.2958f, wallShow, ns.cand, newP.m_X, newP.m_Y, newP.m_Z, ovNew, (int)bNew, hNew);
                    g_exitGeo.newWorst = b;
                }
            }
        }
    }
    checkpointf("EXITGEO sweep: %u exits (%u wall-adjacent) | OLD path-through-wall %u (wall-adjacent %u), capsule >0.15 m %u, any >0.05 m %u, deepest %.2f | NEW path-through-wall %u (wall-adjacent %u), capsule >0.15 m %u, any >0.05 m %u, deepest %.2f | NEW >3 m below the hull %u",
                g_exitGeo.spots, g_exitGeo.wallSpots, g_exitGeo.oldBlocked, g_exitGeo.oldWallBlocked, g_exitGeo.oldInside,
                g_exitGeo.oldAny, g_exitGeo.oldMax, g_exitGeo.newBlocked, g_exitGeo.newWallBlocked, g_exitGeo.newInside,
                g_exitGeo.newAny, g_exitGeo.newMax, g_exitGeo.newDeep);
    checkpointf("EXITGEO worst old: %s", g_exitGeo.oldWorst.c_str());
    checkpointf("EXITGEO worst new: %s", g_exitGeo.newWorst.c_str());
}

static bool NearestVehicleGap(const Vector3& p, const std::vector<PlacedInstance>& placed, float& gap, bool& moving,
                              std::string& cls, size_t* outVeh = nullptr)
{
    bool found = false; float best = 1e30f; size_t bestV = SIZE_MAX;
    for (size_t vi = 0; vi < g_vehicles.size(); ++vi)
    {
        const VehicleState& v = g_vehicles[vi];
        if (!v.alive || v.isTurret || v.placedIndex >= placed.size()) continue;
        const Vector3& vp = placed[v.placedIndex].position;
        const float dx = vp.m_X - p.m_X, dz = vp.m_Z - p.m_Z;
        auto dit = g_vehicleClassDefs.find(v.cls);
        const float hull = (dit != g_vehicleClassDefs.end()) ? dit->second.hullRadius : 1.0f;
        const float g = sqrtf(dx * dx + dz * dz) - hull;
        if (g < best) { best = g; bestV = vi; cls = v.cls; found = true; }
    }
    if (!found) return false;
    gap = best;
    moving = (bestV < g_va.vehSpeed.size()) ? (g_va.vehSpeed[bestV] > 0.5f) : false;
    if (outVeh) *outVeh = bestV;
    return true;
}

static void VehAvoidTick(float dt, const std::vector<PlacedInstance>& placed)
{
    g_va.dtSum += dt;
    g_va.vehLast.resize(g_vehicles.size());
    g_va.vehOk.resize(g_vehicles.size(), 0);
    g_va.vehSpeed.resize(g_vehicles.size(), 0.0f);
    for (size_t vi = 0; vi < g_vehicles.size(); ++vi)
    {
        const VehicleState& v = g_vehicles[vi];
        if (!v.alive || v.placedIndex >= placed.size()) { g_va.vehOk[vi] = 0; g_va.vehSpeed[vi] = 0.0f; continue; }
        const Vector3& vp = placed[v.placedIndex].position;
        if (vi < g_va.vehOk.size() && g_va.vehOk[vi] && dt > 1e-4f)
        {
            const Vector3& lp = g_va.vehLast[vi];
            const float sdx = vp.m_X - lp.m_X, sdz = vp.m_Z - lp.m_Z;
            g_va.vehSpeed[vi] = sqrtf(sdx * sdx + sdz * sdz) / dt;
        }
        g_va.vehLast[vi] = vp;
        g_va.vehOk[vi] = 1;
    }
}
static void VehAvoidAiSample(AIUnitState& au, const PlacedInstance& pi, float intended, float achieved,
                             float dt, const std::vector<PlacedInstance>& placed)
{
    if (!g_vehAvoidDbg || au.life != AI_LIFE_ALIVE || pi.inVehicle) return;
    ++g_va.aiFrames;
    float gap = 1e30f; bool moving = false; std::string cls;
    const bool have = NearestVehicleGap(pi.position, placed, gap, moving, cls);
    const bool near = have && gap <= 1.0f;
    if (intended > 0.0001f && achieved < 0.35f * intended)
    {
        ++g_va.aiStuck;
        if (near)
        {
            ++g_va.aiStuckNear;
            if (moving) ++g_va.aiStuckNearMoving;
            if (gap < 0.0f) ++g_va.aiStuckInHull;

            if (au.stuckNearRun == 0) ++g_va.aiStuckNearRuns;
            au.stuckNearRun = (au.stuckNearRun < 60000) ? au.stuckNearRun + 1 : au.stuckNearRun;
            if (au.stuckNearRun > g_va.aiStuckNearRunMax) g_va.aiStuckNearRunMax = au.stuckNearRun;
        }
    }
    else if (near == false || intended <= 0.0001f) au.stuckNearRun = 0;
    if (au.vaVehPush) ++g_va.aiVehPush;
    const float ov = StaticOverlapAt(pi.position, ClassCollisionRootScale(pi.unitClass), au.currentPose == AIPOSE_CROUCH);
    if (ov > 0.05f)
    {
        ++g_va.aiInside;
        if (ov > g_va.aiInsideMax)
        {
            g_va.aiInsideMax = ov;
            char b[128]; snprintf(b, sizeof(b), "u%u (%.1f,%.1f,%.1f) ov %.2f near %s gap %.1f vehpush %d", (unsigned)(&au - &g_aiUnits[0]),
                                  pi.position.m_X, pi.position.m_Y, pi.position.m_Z, ov, have ? cls.c_str() : "-", gap, (int)au.vaVehPush);
            g_va.aiWorst = b;
        }
        if (near) ++g_va.aiInsideNear;
        if (au.vaVehPush) ++g_va.aiVehPushInside;
        if (ov > 0.15f)
        {
            ++g_va.aiDeep;
            if (au.vaVehPush) ++g_va.aiVehPushDeep;
        }
    }
    (void)dt;
}
static void VehAvoidPlayerSample(const Vector3& p, const std::string& cls, bool crouching, float dt, const std::vector<PlacedInstance>& placed)
{
    if (!g_vehAvoidDbg) return;
    ++g_va.pFrames;
    if (g_vaPlayerVehPush) ++g_va.pVehPush;
    const float ov = StaticOverlapAt(p, ClassCollisionRootScale(cls), crouching);
    if (ov > 0.05f)
    {
        ++g_va.pInside;
        if (ov > g_va.pInsideMax)
        {
            g_va.pInsideMax = ov;
            char b[128]; snprintf(b, sizeof(b), "(%.1f,%.1f,%.1f) ov %.2f vehpush %d", p.m_X, p.m_Y, p.m_Z, ov, (int)g_vaPlayerVehPush);
            g_va.pWorst = b;
        }
        if (g_vaPlayerVehPush) ++g_va.pVehPushInside;
    }
    VehAvoidTick(dt, placed);
    g_vaPlayerVehPush = false;
    if (g_va.dtSum >= 30.0f)
    {
        checkpointf("VEHAVOID %s: AI frames %u, stuck %u, stuck-near-vehicle %u (moving hull %u, inside hull %u, %u episodes, longest %u frames) | vehPush frames %u, vehPush+inside %u (deep %u) | inside static %u (deep %u, near veh %u), deepest %.2f %s",
                    "ai", g_va.aiFrames, g_va.aiStuck, g_va.aiStuckNear, g_va.aiStuckNearMoving, g_va.aiStuckInHull,
                    g_va.aiStuckNearRuns, g_va.aiStuckNearRunMax, g_va.aiVehPush, g_va.aiVehPushInside,
                    g_va.aiVehPushDeep, g_va.aiInside, g_va.aiDeep, g_va.aiInsideNear, g_va.aiInsideMax, g_va.aiWorst.c_str());
        checkpointf("VEHAVOID player: frames %u, vehPush %u, vehPush+inside %u | inside static %u, deepest %.2f %s",
                    g_va.pFrames, g_va.pVehPush, g_va.pVehPushInside, g_va.pInside, g_va.pInsideMax, g_va.pWorst.c_str());
        g_va.dtSum = 0.0f;
    }
}

static void RetailAIStep(AIUnitState& au, PlacedInstance& pi, const Vector3& startPos, float dt,
                         const std::vector<ModelData>& uniqueModels, std::vector<PlacedInstance>& placedRef, const TerrainData& td)
{
    EnsureRetailWorld(uniqueModels, placedRef, td);
    rsc::Body& b = au.rscBody;
    const float dx = pi.position.m_X - startPos.m_X, dz = pi.position.m_Z - startPos.m_Z;
    const float travel = sqrtf(dx * dx + dz * dz);
    float fx = 0.0f, fz = 0.0f;
    if (travel > 1e-3f) { fx = dx / travel; fz = dz / travel; }
    if (au.rscScale < 0.0f)
    {
        auto lit = g_unitClassLoadout.find(pi.unitClass);
        au.rscScale = (lit != g_unitClassLoadout.end()) ? lit->second.collisionRootScale : 1.0f;
    }
    const bool crouch = (au.currentPose == AIPOSE_CROUCH);
    const int boxH0 = rsc::BoxInsideHits(), boxD0 = rsc::BoxInsideDown();

    rsc::V3 preResolve = b.pos;
    b.wallPush = rsc::V3(0, 0, 0);
    int redo = 0;
    bool upperOnly = rsc::StepMove(g_rscWorld, b, rsc::V3(startPos.m_X, startPos.m_Y, startPos.m_Z), dx, dz, dt, fx, fz, au.rscScale, crouch, &preResolve, &redo);
    g_aiTunnelRedo += (uint32_t)redo;

    if (upperOnly && b.grounded)
    {
        if (rsc::LiftOutOfFloor(g_rscWorld, b, fx, fz, au.rscScale, crouch)) { upperOnly = false; ++g_aiUpperLift; }
    }

    if (upperOnly && !au.upperGroundLogged)
    {
        au.upperGroundLogged = true;
        static uint32_t s_upLog = 0;
        if (s_upLog++ < 16)
        {
            std::string tr;
            for (uint32_t k = 0; k < 8 && k < au.fallTrackN; ++k)
            {
                const Vector3& q = au.fallTrack[(au.fallTrackN - 1 - k) % 8];
                char cb[48]; snprintf(cb, sizeof(cb), " (%.2f,%.2f,%.2f)", q.m_X, q.m_Y, q.m_Z); tr += cb;
            }
            checkpointf("M509 upper-grounded u%u %s at (%.2f,%.2f,%.2f) pre (%.2f,%.2f,%.2f) start (%.2f,%.2f,%.2f) crouch=%d deka=%d airTime %.2f track (newest first):%s",
                (unsigned)(&au - g_aiUnits.data()), pi.unitClass.c_str(), b.pos.x, b.pos.y, b.pos.z, preResolve.x, preResolve.y, preResolve.z,
                startPos.m_X, startPos.m_Y, startPos.m_Z, (int)crouch, (int)pi.isDroideka, b.airTime, tr.c_str());
        }
    }
    else if (b.grounded && !upperOnly) au.upperGroundLogged = false;
    au.upperGroundNow = upperOnly;

    if (rsc::BoxInsideHits() != boxH0) { au.fallBoxHits += rsc::BoxInsideHits() - boxH0; au.fallBoxDown += rsc::BoxInsideDown() - boxD0; }
    au.fallTrackSec -= dt;
    if (au.fallTrackSec <= 0.0f && b.grounded)
    {
        au.fallTrackSec = 0.25f;
        au.fallTrack[au.fallTrackN % 8] = Vector3(b.pos.x, b.pos.y, b.pos.z); ++au.fallTrackN;
    }
    if (!b.grounded && b.airTime < 1.0f && b.airTime + dt >= 1.0f)
    {
        static uint32_t s_fallLog = 0;
        if (s_fallLog++ < 12)
        {
            std::string tr;
            for (uint32_t k = 0; k < 8 && k < au.fallTrackN; ++k)
            {
                const Vector3& q = au.fallTrack[(au.fallTrackN - 1 - k) % 8];
                char cb[48]; snprintf(cb, sizeof(cb), " (%.2f,%.2f,%.2f)", q.m_X, q.m_Y, q.m_Z); tr += cb;
            }
            checkpointf("M505 fall u%u at (%.2f,%.2f,%.2f) pre (%.2f,%.2f,%.2f) crouch=%d boxHits=%u boxDown=%u vel.y=%.1f last grounded (newest first):%s",
                (unsigned)(&au - g_aiUnits.data()), b.pos.x, b.pos.y, b.pos.z, preResolve.x, preResolve.y, preResolve.z, (int)crouch,
                au.fallBoxHits, au.fallBoxDown, b.vel.y, tr.c_str());
        }
    }
    if (b.grounded) au.fallBoxHits = au.fallBoxDown = 0;

    if (!b.grounded && b.airTime > 2.0f)
    {
        float ty; Vector3 tn;
        if (GetTerrainHeightAt(td, b.pos.x, b.pos.z, ty, tn, au.terrainHint) && b.pos.y < ty - 8.0f)
        {
            checkpointf("M506 fell through the world: AI u%u at (%.1f,%.1f,%.1f) terrain %.1f - put back on the terrain",
                        (unsigned)(&au - g_aiUnits.data()), b.pos.x, b.pos.y, b.pos.z, ty);
            b.pos.y = ty; b.vel = rsc::V3(0, 0, 0); b.airTime = 0.0f;
            au.collPending = false;
        }
    }
    if (b.grounded) { b.vel.y = 0.0f; b.airTime = 0.0f; } else b.airTime += dt;
    pi.position = Vector3(b.pos.x, b.pos.y, b.pos.z);

    const float keepY = pi.position.m_Y;
    g_zeroResolveVehiclesOnly = true;
    ResolveSoldierCollisionZero(pi.position, Vector3(startPos.m_X, keepY, startPos.m_Z), uniqueModels, placedRef, au.placedIndex);
    g_zeroResolveVehiclesOnly = false;
    pi.position.m_Y = keepY;
    if (g_vehAvoidDbg) au.vaVehPush = (g_resolveHits > 0) ? 1 : 0;
}

static void ApplyAIGroundContact(AIUnitState& au, PlacedInstance& pi, float deltaSec,
                                 const TerrainData& terrainData,
                                 const std::vector<ModelData>& uniqueModels,
                                 std::vector<PlacedInstance>& placedRef,
                                 bool collisionDeferred, size_t unitIndex,
                                 float preMoveX, float preMoveZ)
{

    if (au.pushVelX != 0.0f || au.pushVelY != 0.0f || au.pushVelZ != 0.0f) return;
    if (g_retailSoldierCollision)
    {
        if (au.rscDone) { au.rscDone = false; return; }
        if (collisionDeferred && au.rscBody.grounded) return;

        RetailAIStep(au, pi, Vector3(preMoveX, pi.position.m_Y, preMoveZ), (au.movedThisFrame || !au.rscBody.grounded) ? deltaSec : deltaSec * 8.0f,
                     uniqueModels, placedRef, terrainData);
        return;
    }

    float groundY; Vector3 groundN;

            bool refusedStep = false;
            const bool groundFound = GetGroundUnderFootprint(terrainData, uniqueModels, placedRef, pi.position.m_X, pi.position.m_Y, pi.position.m_Z,
                                                             au.terrainHint, groundY, groundN, au.placedIndex, false,  true, &refusedStep);

            if (refusedStep)
            {
                float hereY; Vector3 hereN; bool refusedHere = false;
                uint32_t hereHint = au.terrainHint;
                GetCombinedGroundHeightAt(terrainData, uniqueModels, placedRef, preMoveX, pi.position.m_Y, preMoveZ,
                                          hereHint, hereY, hereN, au.placedIndex, false,  true, &refusedHere);
                if (refusedHere) refusedStep = false;
            }
            if (refusedStep)
            {
                pi.position.m_X = preMoveX;
                pi.position.m_Z = preMoveZ;
                ++g_aiRefusedStepCount;
                au.lastRefuseAge = 0.0f; au.lastRefuseY = g_lastRefusedY; au.lastRefuseFeetY = pi.position.m_Y;
                au.lastRefusePlaced = g_lastRefusedPlaced; ++au.refuseCount;

                if (au.localPathValid) au.localPlanCooldown = 0.0f;
                au.localPathValid = false;
                return;
            }
            if (groundFound)
            {

                if (groundY > pi.position.m_Y)
                {
                    const float SOLDIER_HEAD = 1.8f;
                    float ceilY = 0.0f;
                    if (GetCeilingHeightAt(uniqueModels, placedRef, pi.position.m_X, pi.position.m_Z,
                            pi.position.m_Y + SOLDIER_HEAD, groundY + SOLDIER_HEAD, ceilY, au.placedIndex))
                    {
                        groundY = fminf(groundY, ceilY - SOLDIER_HEAD - 0.02f);
                        if (groundY < pi.position.m_Y) groundY = pi.position.m_Y;
                    }
                }

                const float rise = groundY - pi.position.m_Y;
                if (rise > 0.6f && g_aiBigRiseDiagCount < 40)
                {
                    ++g_aiBigRiseDiagCount;
                    checkpointf("M332 aiBigRise: unit=%u deferred=%d from=(%.1f,%.1f,%.1f) toY=%.2f rise=%.2f",
                        (unsigned)unitIndex, (int)collisionDeferred, pi.position.m_X, pi.position.m_Y, pi.position.m_Z, groundY, rise);
                }
                if (collisionDeferred && rise > 0.35f) groundY = pi.position.m_Y;
                pi.position.m_Y = groundY;
            }
            else
            {

                pi.position.m_Y -= 9.8f * deltaSec;
            }

}

static bool DroidekaInCombat(const AIUnitState& au)
{
    return au.haveCachedTarget || au.fireCooldown > 0.0f || au.hintNodeIdx >= 0 || au.shieldRaised;
}

