struct NavWall
{
    float x[3], y[3], z[3];
    float ylo, yhi;
    bool isSeg;
    bool steep = false;
    bool floorLip = false;
    bool notLedge = false;
};
struct NavWallCircle { float x, z, r, ylo, yhi; };
static std::vector<NavWall> g_navWalls;
static std::vector<NavWallCircle> g_navWallCircles;
static std::unordered_map<int64_t, std::vector<uint32_t>> g_navWallGrid;
static std::unordered_map<int64_t, std::vector<uint32_t>> g_navCircleGrid;
static std::vector<uint32_t> g_navWallStamp;
static uint32_t g_navWallStampNow = 0;
static bool g_navWallsBuilt = false;
static const float NAVWALL_GRID_CELL = 8.0f;

static void BuildNavWalls(const std::vector<ModelData>& uniqueModels, const std::vector<PlacedInstance>& placedRef)
{
    g_navWalls.clear(); g_navWallCircles.clear(); g_navWallGrid.clear(); g_navCircleGrid.clear();
    auto reg = [](std::unordered_map<int64_t, std::vector<uint32_t>>& grid, float minX, float minZ, float maxX, float maxZ, uint32_t idx) {
        const int32_t cx0 = (int32_t)floorf(minX / NAVWALL_GRID_CELL), cx1 = (int32_t)floorf(maxX / NAVWALL_GRID_CELL);
        const int32_t cz0 = (int32_t)floorf(minZ / NAVWALL_GRID_CELL), cz1 = (int32_t)floorf(maxZ / NAVWALL_GRID_CELL);
        for (int32_t cz = cz0; cz <= cz1; ++cz)
        for (int32_t cx = cx0; cx <= cx1; ++cx)
            grid[PackGridCell(cx, cz)].push_back(idx);
    };
    for (size_t pI = 0; pI < placedRef.size(); ++pI)
    {
        const PlacedInstance& pl = placedRef[pI];
        if (pl.isSoldier || pl.isActiveOrdnance) continue;
        if (pl.modelIndex >= uniqueModels.size()) continue;
        const ModelData& md = uniqueModels[pl.modelIndex];
        for (const CollisionSegment& seg : md.collisionSegments)
        {
            NavWall w;
            const Vector3 ra = QuatRotateVector(pl.rotation, seg.localA);
            const Vector3 rb = QuatRotateVector(pl.rotation, seg.localB);
            w.x[0] = pl.position.m_X + ra.m_X; w.y[0] = pl.position.m_Y + ra.m_Y; w.z[0] = pl.position.m_Z + ra.m_Z;
            w.x[1] = pl.position.m_X + rb.m_X; w.y[1] = pl.position.m_Y + rb.m_Y; w.z[1] = pl.position.m_Z + rb.m_Z;
            if (seg.isTri)
            {
                const Vector3 rcv = QuatRotateVector(pl.rotation, seg.localC);
                w.x[2] = pl.position.m_X + rcv.m_X; w.y[2] = pl.position.m_Y + rcv.m_Y; w.z[2] = pl.position.m_Z + rcv.m_Z;
                w.ylo = fminf(w.y[0], fminf(w.y[1], w.y[2])); w.yhi = fmaxf(w.y[0], fmaxf(w.y[1], w.y[2]));
                w.isSeg = false;
            }
            else
            {
                w.x[2] = w.x[1]; w.y[2] = w.y[1]; w.z[2] = w.z[1];
                w.ylo = pl.position.m_Y + seg.localMinY; w.yhi = pl.position.m_Y + seg.localMaxY;
                w.isSeg = true;
            }
            const uint32_t idx = (uint32_t)g_navWalls.size();
            g_navWalls.push_back(w);
            reg(g_navWallGrid, fminf(w.x[0], fminf(w.x[1], w.x[2])), fminf(w.z[0], fminf(w.z[1], w.z[2])),
                               fmaxf(w.x[0], fmaxf(w.x[1], w.x[2])), fmaxf(w.z[0], fmaxf(w.z[1], w.z[2])), idx);
        }

        for (const CollisionFloorTri& ft : md.floorTris)
        {
            const Vector3 ra = QuatRotateVector(pl.rotation, ft.localA);
            const Vector3 rb = QuatRotateVector(pl.rotation, ft.localB);
            const Vector3 rcv = QuatRotateVector(pl.rotation, ft.localC);
            const float e1x = rb.m_X - ra.m_X, e1y = rb.m_Y - ra.m_Y, e1z = rb.m_Z - ra.m_Z;
            const float e2x = rcv.m_X - ra.m_X, e2y = rcv.m_Y - ra.m_Y, e2z = rcv.m_Z - ra.m_Z;
            const float nx = e1y * e2z - e1z * e2y, ny = e1z * e2x - e1x * e2z, nz = e1x * e2y - e1y * e2x;
            const float nl = sqrtf(nx * nx + ny * ny + nz * nz);

            if (nl < 1e-6f || (fabsf(ny) / nl >= AI_WALKABLE_NY_MIN && !pl.isVehicle)) continue;
            NavWall w;
            w.x[0] = pl.position.m_X + ra.m_X;  w.y[0] = pl.position.m_Y + ra.m_Y;  w.z[0] = pl.position.m_Z + ra.m_Z;
            w.x[1] = pl.position.m_X + rb.m_X;  w.y[1] = pl.position.m_Y + rb.m_Y;  w.z[1] = pl.position.m_Z + rb.m_Z;
            w.x[2] = pl.position.m_X + rcv.m_X; w.y[2] = pl.position.m_Y + rcv.m_Y; w.z[2] = pl.position.m_Z + rcv.m_Z;
            w.ylo = fminf(w.y[0], fminf(w.y[1], w.y[2])); w.yhi = fmaxf(w.y[0], fmaxf(w.y[1], w.y[2]));
            w.isSeg = false;
            w.steep = true;
            const uint32_t idx = (uint32_t)g_navWalls.size();
            g_navWalls.push_back(w);
            reg(g_navWallGrid, fminf(w.x[0], fminf(w.x[1], w.x[2])), fminf(w.z[0], fminf(w.z[1], w.z[2])),
                               fmaxf(w.x[0], fmaxf(w.x[1], w.x[2])), fmaxf(w.z[0], fmaxf(w.z[1], w.z[2])), idx);
        }

        for (const CollisionCircle& cc : md.collisionCircles)
        {
            const Vector3 wc = QuatRotateVector(pl.rotation, cc.localCenter);
            NavWallCircle c;
            c.x = pl.position.m_X + wc.m_X; c.z = pl.position.m_Z + wc.m_Z; c.r = cc.radius;
            c.ylo = pl.position.m_Y + cc.localMinY; c.yhi = pl.position.m_Y + cc.localMaxY;
            const uint32_t idx = (uint32_t)g_navWallCircles.size();
            g_navWallCircles.push_back(c);
            reg(g_navCircleGrid, c.x - c.r, c.z - c.r, c.x + c.r, c.z + c.r, idx);
        }
    }

    {
        auto floorNear = [&](float x, float z, float y) {
            for (size_t pI = 0; pI < placedRef.size(); ++pI)
            {
                const PlacedInstance& pl = placedRef[pI];
                if (pl.isSoldier || pl.isActiveOrdnance || pl.isVehicle || pl.modelIndex >= uniqueModels.size()) continue;
                const ModelData& md = uniqueModels[pl.modelIndex];
                if (md.floorTris.empty()) continue;
                const Vector3 rc = QuatRotateVector(pl.rotation, md.boundCenter);
                const float dx = pl.position.m_X + rc.m_X - x, dz = pl.position.m_Z + rc.m_Z - z, rr = md.boundRadius + 0.5f;
                if (dx * dx + dz * dz > rr * rr) continue;
                float fy;
                if (GetModelFloorHeightAt(md, pl, x, y + 0.3f, z, fy, y + 0.3f, y - 0.3f)) return true;
            }
            return false;
        };
        uint32_t seams = 0;
        for (NavWall& w : g_navWalls)
        {
            if (w.isSeg) continue;
            const float e1x = w.x[1] - w.x[0], e1y = w.y[1] - w.y[0], e1z = w.z[1] - w.z[0];
            const float e2x = w.x[2] - w.x[0], e2y = w.y[2] - w.y[0], e2z = w.z[2] - w.z[0];
            const float nx = e1y * e2z - e1z * e2y, ny = e1z * e2x - e1x * e2z, nz = e1x * e2y - e1y * e2x;
            const float nl = sqrtf(nx * nx + ny * ny + nz * nz), hl = sqrtf(nx * nx + nz * nz);
            if (nl < 1e-6f || hl < 0.9f * nl) continue;
            const float hx = nx / hl * 0.3f, hz = nz / hl * 0.3f;

            float sx[3], sz[3]; int ns = 0;
            for (int k = 0; k < 3 && ns < 2; ++k) if (w.y[k] >= w.yhi - 0.05f) { sx[ns] = w.x[k]; sz[ns] = w.z[k]; ++ns; }
            if (ns == 2) { sx[2] = 0.5f * (sx[0] + sx[1]); sz[2] = 0.5f * (sz[0] + sz[1]); ns = 3; }
            bool inside = true;
            for (int k = 0; k < ns && inside; ++k)
            {

                float qx = sx[k], qz = sz[k];
                if (ns == 3 && k < 2) { qx += (sx[2] - sx[k]) * 0.1f; qz += (sz[2] - sz[k]) * 0.1f; }
                inside = floorNear(qx + hx, qz + hz, w.yhi) && floorNear(qx - hx, qz - hz, w.yhi);
            }
            if (inside) { w.notLedge = true; ++seams; }
        }
        checkpointf("M481 nav walls: %u upright face(s) are seams inside a floor - not ledges", seams);
    }
    g_navWallStamp.assign(g_navWalls.size() + g_navWallCircles.size(), 0);
    g_navWallsBuilt = true;
    checkpointf("MILESTONE 327: nav wall cache built - %u wall(s), %u circle(s), %u + %u grid cell(s)",
        (unsigned)g_navWalls.size(), (unsigned)g_navWallCircles.size(),
        (unsigned)g_navWallGrid.size(), (unsigned)g_navCircleGrid.size());
}

struct TerrainHTile { int16_t h[16 * 16]; };
static std::unordered_map<int64_t, TerrainHTile> g_terrHTiles;
static const int16_t TERR_H_NONE = (int16_t)-32768;
static const TerrainHTile* TerrainHTileFor(const TerrainData& td, int32_t tx, int32_t tz)
{
    const int64_t key = PackGridCell(tx, tz);
    auto it = g_terrHTiles.find(key);
    if (it != g_terrHTiles.end()) return &it->second;
    TerrainHTile t;
    uint32_t hint = 0;
    for (int j = 0; j < 16; ++j)
    for (int i = 0; i < 16; ++i)
    {
        float y = 0.0f; Vector3 n;
        const float wx = (float)(tx * 16 + i) + 0.5f, wz = (float)(tz * 16 + j) + 0.5f;
        if (GetTerrainHeightAt(td, wx, wz, y, n, hint))
        {
            const float cm = fmaxf(-32000.0f, fminf(32000.0f, y * 100.0f));
            t.h[j * 16 + i] = (int16_t)lrintf(cm);
        }
        else t.h[j * 16 + i] = TERR_H_NONE;
    }
    return &g_terrHTiles.emplace(key, t).first->second;
}

static bool AIStraightWalkClear(const Vector3& from, const Vector3& to,
    const std::vector<ModelData>& uniqueModels, const std::vector<PlacedInstance>& placedRef, size_t selfIndex,
    float* outBlockDist = nullptr)
{
    const float dx = to.m_X - from.m_X, dz = to.m_Z - from.m_Z;
    const float d = sqrtf(dx * dx + dz * dz);
    if (d < 0.5f) return true;
    const float len = fminf(d, 20.0f);
    const Vector3 dir(dx / d, 0.0f, dz / d);

    const float heights[3] = { LOCALNAV_BAND_LO + 0.05f, 1.15f, LOCALNAV_BAND_HI + 0.09f };
    const Vector3 side(-dir.m_Z * PLAYER_COLLISION_RADIUS, 0.0f, dir.m_X * PLAYER_COLLISION_RADIUS);
    const float rays[6][2] = { { heights[0], 0.0f }, { heights[1], 0.0f }, { heights[2], 0.0f },
                               { heights[1], 1.0f }, { heights[1], -1.0f },
                               { -LOCALNAV_LEDGE_DROP, 0.0f } };
    float nearest = 1e30f;
    for (const auto& r : rays)
    {
        const Vector3 o(from.m_X + side.m_X * r[1], from.m_Y + r[0], from.m_Z + side.m_Z * r[1]);
        float hd; Vector3 hp;
        if (FireRayHitTest(o, dir, len, uniqueModels, placedRef, hd, hp, selfIndex,  false))
        {
            if (outBlockDist == nullptr) return false;
            nearest = fminf(nearest, hd);
        }
    }
    if (nearest < 1e29f) { *outBlockDist = nearest; return false; }

    if (!PointBlockedByBarrier(from.m_X, from.m_Z, PLAYER_COLLISION_RADIUS))
        for (float t = 1.0f; t <= len; t += 1.0f)
            if (PointBlockedByBarrier(from.m_X + dir.m_X * t, from.m_Z + dir.m_Z * t, PLAYER_COLLISION_RADIUS))
                return false;
    return true;
}

static bool PlanLocalPath(const Vector3& start, const Vector3& target,
    const std::vector<ModelData>& uniqueModels, const std::vector<PlacedInstance>& placedRef,
    const TerrainData& terrainData, size_t selfIndex, std::vector<Vector3>& outPath,
    int* outExpanded, bool* outReached, bool centerOnStart = false,
    float barrierClearRadius = 0.0f)
{
    static std::vector<uint8_t> blocked;
    static std::vector<float> gcost;
    static std::vector<int> from;
    const int N = LOCALNAV_N;
    const float CELL = LOCALNAV_CELL;
    const float HALF = (float)N * CELL * 0.5f;
    blocked.assign((size_t)(N * N), 0);
    gcost.assign((size_t)(N * N), 1e30f);
    from.assign((size_t)(N * N), -1);
    outPath.clear();

    float cx = start.m_X, cz = start.m_Z;
    {
        const float dx = target.m_X - start.m_X, dz = target.m_Z - start.m_Z;
        const float d = sqrtf(dx * dx + dz * dz);
        const float reach = fminf(d, HALF * 0.8f);
        if (d > 0.01f && !centerOnStart) { cx += dx / d * reach * 0.5f; cz += dz / d * reach * 0.5f; }
    }

    const float ox = cx - HALF, oz = cz - HALF;
    const float feetY = start.m_Y;
    const float bandLo = feetY + LOCALNAV_BAND_LO, bandHi = feetY + LOCALNAV_BAND_HI;
    const float INF = LOCALNAV_INFLATE;

    auto cellOf = [&](float x, float z, int& i, int& j) {
        i = (int)floorf((x - ox) / CELL); j = (int)floorf((z - oz) / CELL); };
    auto markSeg = [&](float ax, float az, float bx, float bz, uint8_t tag) {
        int i0, j0, i1, j1;
        cellOf(fminf(ax, bx) - INF, fminf(az, bz) - INF, i0, j0);
        cellOf(fmaxf(ax, bx) + INF, fmaxf(az, bz) + INF, i1, j1);
        if (i1 < 0 || j1 < 0 || i0 >= N || j0 >= N) return;
        const float ex = bx - ax, ez = bz - az, l2 = ex * ex + ez * ez;
        for (int j = (j0 < 0 ? 0 : j0); j <= (j1 >= N ? N - 1 : j1); ++j)
        for (int i = (i0 < 0 ? 0 : i0); i <= (i1 >= N ? N - 1 : i1); ++i)
        {
            const float px = ox + (i + 0.5f) * CELL, pz = oz + (j + 0.5f) * CELL;
            float u = (l2 > 1e-9f) ? ((px - ax) * ex + (pz - az) * ez) / l2 : 0.0f;
            u = fmaxf(0.0f, fminf(1.0f, u));
            const float qx = ax + ex * u - px, qz = az + ez * u - pz;
            if (qx * qx + qz * qz <= INF * INF) blocked[(size_t)(j * N + i)] |= tag;
        }
    };

    uint64_t phT = sceKernelGetProcessTimeWide();
    auto phase = [&](int k) { const uint64_t t = sceKernelGetProcessTimeWide(); g_lnPhaseUs[k] += t - phT; phT = t; };

    if (!g_navWallsBuilt) BuildNavWalls(uniqueModels, placedRef);
    (void)selfIndex;

    const float topSlice = bandHi + 0.09f;

    const float sliceY[3] = { bandLo + 0.1f, (bandLo + bandHi) * 0.5f, topSlice };

    const float steepSliceY = feetY + 0.2f;

    float ledgeSliceY = -1e30f;
    {
        float ty = 0.0f; Vector3 tn; uint32_t th = 0;
        if (!GetTerrainHeightAt(terrainData, start.m_X, start.m_Z, ty, tn, th) || feetY > ty + LOCALNAV_LEDGE_DROP)
            ledgeSliceY = feetY - LOCALNAV_LEDGE_DROP;
    }
    if (++g_navWallStampNow == 0) { std::fill(g_navWallStamp.begin(), g_navWallStamp.end(), 0u); g_navWallStampNow = 1; }
    const int32_t gcx0 = (int32_t)floorf(ox / NAVWALL_GRID_CELL), gcx1 = (int32_t)floorf((ox + 2.0f * HALF) / NAVWALL_GRID_CELL);
    const int32_t gcz0 = (int32_t)floorf(oz / NAVWALL_GRID_CELL), gcz1 = (int32_t)floorf((oz + 2.0f * HALF) / NAVWALL_GRID_CELL);
    const size_t circleStampBase = g_navWalls.size();
    for (int32_t gz = gcz0; gz <= gcz1; ++gz)
    for (int32_t gx = gcx0; gx <= gcx1; ++gx)
    {
        auto wit = g_navWallGrid.find(PackGridCell(gx, gz));
        if (wit != g_navWallGrid.end())
        {
            for (uint32_t wi : wit->second)
            {
                if (g_navWallStamp[wi] == g_navWallStampNow) continue;
                g_navWallStamp[wi] = g_navWallStampNow;
                const NavWall& w = g_navWalls[wi];
                if (w.yhi < (ledgeSliceY > -1e29f ? ledgeSliceY : (w.steep ? steepSliceY : bandLo)) || w.ylo > topSlice) continue;
                if (ledgeSliceY > -1e29f)
                {
                    float ax, az, bx, bz;
                    if (!w.isSeg && !w.notLedge && SliceTriangleAtY(w.x, w.y, w.z, ledgeSliceY, ax, az, bx, bz)) markSeg(ax, az, bx, bz, 1);
                }
                if (w.yhi < (w.steep ? steepSliceY : bandLo)) continue;
                if (w.isSeg) { markSeg(w.x[0], w.z[0], w.x[1], w.z[1], 1); continue; }
                for (float yq : sliceY)
                {
                    float ax, az, bx, bz;
                    if (SliceTriangleAtY(w.x, w.y, w.z, yq, ax, az, bx, bz)) markSeg(ax, az, bx, bz, 1);
                }
                if (w.steep)
                {
                    float ax, az, bx, bz;
                    if (SliceTriangleAtY(w.x, w.y, w.z, steepSliceY, ax, az, bx, bz)) markSeg(ax, az, bx, bz, 1);
                }
            }
        }
        auto cit = g_navCircleGrid.find(PackGridCell(gx, gz));
        if (cit != g_navCircleGrid.end())
        {
            for (uint32_t ci2 : cit->second)
            {
                if (g_navWallStamp[circleStampBase + ci2] == g_navWallStampNow) continue;
                g_navWallStamp[circleStampBase + ci2] = g_navWallStampNow;
                const NavWallCircle& c = g_navWallCircles[ci2];
                if (c.yhi < bandLo || c.ylo > bandHi) continue;
                const float r = c.r + INF;
                int i0, j0, i1, j1;
                cellOf(c.x - r, c.z - r, i0, j0); cellOf(c.x + r, c.z + r, i1, j1);
                for (int j = (j0 < 0 ? 0 : j0); j <= (j1 >= N ? N - 1 : j1); ++j)
                for (int i = (i0 < 0 ? 0 : i0); i <= (i1 >= N ? N - 1 : i1); ++i)
                {
                    const float px = ox + (i + 0.5f) * CELL - c.x, pz = oz + (j + 0.5f) * CELL - c.z;
                    if (px * px + pz * pz <= r * r) blocked[(size_t)(j * N + i)] |= 2;
                }
            }
        }
    }

    phase(0);

    if (!PointBlockedByBarrier(start.m_X, start.m_Z, PLAYER_COLLISION_RADIUS))
    {
        for (const NavBarrier& b : g_navBarriers)
        {
            if ((b.flag & BARRIER_BANS_SOLDIER) == 0) continue;
            const float r = sqrtf(b.halfX * b.halfX + b.halfZ * b.halfZ) + INF;
            if (fabsf(b.position.m_X - cx) > HALF + r || fabsf(b.position.m_Z - cz) > HALF + r) continue;
            int i0, j0, i1, j1;
            cellOf(b.position.m_X - r, b.position.m_Z - r, i0, j0);
            cellOf(b.position.m_X + r, b.position.m_Z + r, i1, j1);

            const Vector3 axX = QuatRotateVector(b.rotation, Vector3(1.0f, 0.0f, 0.0f));
            const Vector3 axZ = QuatRotateVector(b.rotation, Vector3(0.0f, 0.0f, 1.0f));
            const float limX = b.halfX + INF, limZ = b.halfZ + INF;
            for (int j = (j0 < 0 ? 0 : j0); j <= (j1 >= N ? N - 1 : j1); ++j)
            for (int i = (i0 < 0 ? 0 : i0); i <= (i1 >= N ? N - 1 : i1); ++i)
            {
                const float ddx = ox + (i + 0.5f) * CELL - b.position.m_X;
                const float ddz = oz + (j + 0.5f) * CELL - b.position.m_Z;
                if (fabsf(ddx * axX.m_X + ddz * axX.m_Z) <= limX && fabsf(ddx * axZ.m_X + ddz * axZ.m_Z) <= limZ)
                    blocked[(size_t)(j * N + i)] |= 4;
            }
        }
    }

    phase(1);

    static std::vector<int16_t> s_terrHcm;
    s_terrHcm.assign((size_t)(N * N), TERR_H_NONE);
    {
        const int16_t cliffCm = (int16_t)lrintf(fmaxf(-32000.0f, fminf(32000.0f, (feetY + LOCALNAV_CLIFF) * 100.0f)));

        int32_t colTx[N]; int colIn[N];
        for (int ii = 0; ii < N; ++ii)
        {
            const int32_t mx = (int32_t)floorf(ox + ((float)ii + 0.5f) * CELL);
            colTx[ii] = (mx >= 0) ? mx / 16 : -((-mx + 15) / 16);
            colIn[ii] = (int)(mx - colTx[ii] * 16);
        }
        for (int jj = 0; jj < N; ++jj)
        {
            const int32_t mz = (int32_t)floorf(oz + ((float)jj + 0.5f) * CELL);
            const int32_t tz = (mz >= 0) ? mz / 16 : -((-mz + 15) / 16);
            const int rowOff = (int)(mz - tz * 16) * 16;
            int32_t lastTx = INT32_MIN;
            const TerrainHTile* tile = nullptr;
            for (int ii = 0; ii < N; ++ii)
            {
                if (colTx[ii] != lastTx) { lastTx = colTx[ii]; tile = TerrainHTileFor(terrainData, lastTx, tz); }
                s_terrHcm[(size_t)(jj * N + ii)] = tile->h[rowOff + colIn[ii]];
            }
        }

        const size_t sIdx = (size_t)((int)((start.m_Z - oz) / CELL) * N + (int)((start.m_X - ox) / CELL));
        const int16_t startTerr = (sIdx < s_terrHcm.size()) ? s_terrHcm[sIdx] : TERR_H_NONE;
        const bool onRaisedFloor = startTerr == TERR_H_NONE || (float)startTerr * 0.01f < feetY - 1.0f;
        const int16_t CLIFF_RISE_CM = 119;
        for (int jj = 0; jj < N; ++jj)
        for (int ii = 0; ii < N; ++ii)
        {
            const int16_t hc = s_terrHcm[(size_t)(jj * N + ii)];
            if (hc == TERR_H_NONE) continue;
            bool cliff = false;
            if (onRaisedFloor) cliff = hc > cliffCm;
            else
            {
                const int nb[4][2] = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
                for (const auto& d : nb)
                {
                    const int ni = ii + d[0], nj = jj + d[1];
                    if (ni < 0 || nj < 0 || ni >= N || nj >= N) continue;
                    const int16_t hn = s_terrHcm[(size_t)(nj * N + ni)];
                    if (hn != TERR_H_NONE && hc - hn > CLIFF_RISE_CM) { cliff = true; break; }
                }
            }
            if (cliff) blocked[(size_t)(jj * N + ii)] |= 8;
        }
    }

    phase(2);

    int si, sj, gi, gj;
    cellOf(start.m_X, start.m_Z, si, sj);
    if (si < 0 || sj < 0 || si >= N || sj >= N) return false;

    for (int dj = -1; dj <= 1; ++dj)
    for (int di = -1; di <= 1; ++di)
    {
        const int ni = si + di, nj = sj + dj;
        if (ni >= 0 && nj >= 0 && ni < N && nj < N)
        {
            uint8_t& cellB = blocked[(size_t)(nj * N + ni)];
            cellB = (di == 0 && dj == 0) ? 0 : (uint8_t)(cellB & 4);
        }
    }
    if (barrierClearRadius > 0.0f)
    {
        const int rc = (int)ceilf(barrierClearRadius / CELL);
        for (int dj = -rc; dj <= rc; ++dj)
        for (int di = -rc; di <= rc; ++di)
        {
            const int ni = si + di, nj = sj + dj;
            if (ni < 0 || nj < 0 || ni >= N || nj >= N || (float)(di * di + dj * dj) * CELL * CELL > barrierClearRadius * barrierClearRadius) continue;
            blocked[(size_t)(nj * N + ni)] &= (uint8_t)~4u;
        }
    }
    {
        const float gx = fmaxf(ox + CELL, fminf(ox + 2.0f * HALF - CELL, target.m_X));
        const float gz = fmaxf(oz + CELL, fminf(oz + 2.0f * HALF - CELL, target.m_Z));
        cellOf(gx, gz, gi, gj);
    }

    const float HEUR_W = 1.5f;
    auto heur = [&](int i, int j) {
        const float ax = fabsf((float)(i - gi)), az = fabsf((float)(j - gj));
        return HEUR_W * ((ax + az) + (1.41421f - 2.0f) * fminf(ax, az)); };
    typedef std::pair<float, int> QE;

    struct ReusableHeap : std::priority_queue<QE, std::vector<QE>, std::greater<QE>> { void reset() { c.clear(); } };
    static ReusableHeap open;
    open.reset();
    const int startC = sj * N + si, goalC = gj * N + gi;
    gcost[(size_t)startC] = 0.0f;
    open.push(QE(heur(si, sj), startC));
    int best = startC; float bestH = heur(si, sj); int expanded = 0;
    while (!open.empty())
    {
        const QE top = open.top(); open.pop();
        const int c = top.second, ci = c % N, cj = c / N;
        if (top.first - heur(ci, cj) > gcost[(size_t)c] + 1e-4f) continue;
        ++expanded;
        const float hc = heur(ci, cj);
        if (hc < bestH) { bestH = hc; best = c; }
        if (c == goalC) { best = c; break; }

        if (expanded >= LOCALNAV_N * LOCALNAV_N) break;
        for (int dj = -1; dj <= 1; ++dj)
        for (int di = -1; di <= 1; ++di)
        {
            if (di == 0 && dj == 0) continue;
            const int ni = ci + di, nj = cj + dj;
            if (ni < 0 || nj < 0 || ni >= N || nj >= N) continue;
            if (blocked[(size_t)(nj * N + ni)]) continue;
            if (di != 0 && dj != 0 && (blocked[(size_t)(cj * N + ni)] || blocked[(size_t)(nj * N + ci)])) continue;
            const float ng = gcost[(size_t)c] + ((di != 0 && dj != 0) ? 1.41421f : 1.0f);
            const int nc = nj * N + ni;
            if (ng < gcost[(size_t)nc]) { gcost[(size_t)nc] = ng; from[(size_t)nc] = c; open.push(QE(ng + heur(ni, nj), nc)); }
        }
    }
    if (outExpanded) *outExpanded = expanded;
    if (outReached) *outReached = (best == goalC);
    if (g_planSnapWanted)
    {
        g_planSnapWanted = false;
        g_planSnap.assign(blocked.begin(), blocked.end());
        g_planSnapStart = startC; g_planSnapGoal = goalC; g_planSnapBest = best;
        g_planSnapFeetY = feetY;
    }
    g_lnExpanded += (uint32_t)expanded;
    phase(3);
    if (best == startC) return false;

    std::vector<int> cells;
    for (int c = best; c != -1; c = from[(size_t)c]) cells.push_back(c);
    std::reverse(cells.begin(), cells.end());

    auto visible = [&](int a, int b) {
        const float ax = (float)(a % N) + 0.5f, az = (float)(a / N) + 0.5f;
        const float bx = (float)(b % N) + 0.5f, bz = (float)(b / N) + 0.5f;
        const float len = sqrtf((bx - ax) * (bx - ax) + (bz - az) * (bz - az));
        const int steps = (int)(len * 3.0f) + 1;
        for (int k = 1; k < steps; ++k)
        {
            const float t = (float)k / (float)steps;
            const int ci = (int)floorf(ax + (bx - ax) * t), cj = (int)floorf(az + (bz - az) * t);
            if (blocked[(size_t)(cj * N + ci)]) return false;
        }
        return true;
    };
    size_t k = 0;
    while (k + 1 < cells.size())
    {
        size_t far = k + 1;
        for (size_t m = cells.size() - 1; m > k + 1; --m)
            if (visible(cells[k], cells[m])) { far = m; break; }
        const int c = cells[far];
        outPath.push_back(Vector3(ox + ((float)(c % N) + 0.5f) * CELL, feetY, oz + ((float)(c / N) + 0.5f) * CELL));
        k = far;
    }
    phase(4);
    return !outPath.empty();
}

static void UpdateAIVehicle(size_t n, std::vector<PlacedInstance>& placedRef, const std::vector<ModelData>& uniqueModels,
    const TerrainData& terrainData, float deltaSec, const Vector3& playerPos);

struct LocalPlanJob
{
    uint32_t unit = 0; size_t placedIndex = 0;
    Vector3 start, target; float floorY = 0.0f; bool onRaisedFloor = false; bool allowRetry = false;
    std::vector<Vector3> path; bool planned = false, reached = false; int expanded = 0;
    bool floorWon = false, retryWon = false, retryFailed = false; uint64_t us = 0;
    bool snap = false;
};
static LocalPlanJob g_planJob;
static volatile int g_planJobState = 0;

static SceUID g_planJobSema = -1;
static const std::vector<ModelData>* g_planJobModels = nullptr;
static const std::vector<PlacedInstance>* g_planJobPlaced = nullptr;
static const TerrainData* g_planJobTerrain = nullptr;

static void RunLocalPlanJob(LocalPlanJob& j)
{
    const uint64_t t0 = sceKernelGetProcessTimeWide();
    g_planSnapWanted = j.snap;
    j.planned = PlanLocalPath(j.start, j.target, *g_planJobModels, *g_planJobPlaced, *g_planJobTerrain,
                              j.placedIndex, j.path, &j.expanded, &j.reached);
    g_planSnapWanted = false;

    if ((!j.planned || !j.reached) && j.allowRetry && j.onRaisedFloor)
    {
        static std::vector<Vector3> s_floorPath;
        int e3 = 0; bool r3 = false;
        const Vector3 floorStart(j.start.m_X, j.floorY, j.start.m_Z);
        if (PlanLocalPath(floorStart, j.target, *g_planJobModels, *g_planJobPlaced, *g_planJobTerrain,
                          j.placedIndex, s_floorPath, &e3, &r3,  true,  3.0f) && r3)
        {
            j.path.swap(s_floorPath); j.planned = true; j.reached = true; j.expanded += e3; j.floorWon = true;
        }
    }

    if (j.planned && !j.reached && j.allowRetry)
    {
        static std::vector<Vector3> s_retryPath;
        int e2 = 0; bool r2 = false;
        if (PlanLocalPath(j.start, j.target, *g_planJobModels, *g_planJobPlaced, *g_planJobTerrain,
                          j.placedIndex, s_retryPath, &e2, &r2,  true) && r2)
        {
            j.path.swap(s_retryPath); j.reached = true; j.expanded += e2; j.retryWon = true;
        }
        else j.retryFailed = true;
    }
    j.us = sceKernelGetProcessTimeWide() - t0;
}

static int LocalPlanThreadMain(SceSize, void*)
{
    for (;;)
    {
        sceKernelWaitSema(g_planJobSema, 1, nullptr);
        if (g_planJobState != 1) continue;
        __sync_synchronize();
        RunLocalPlanJob(g_planJob);
        __sync_synchronize();
        g_planJobState = 2;
    }
    return 0;
}

static bool StartLocalPlanWorker()
{
    if (g_planJobSema >= 0) return true;
    g_planJobSema = sceKernelCreateSema("localplan_sema", 0, 0, 1, nullptr);

    const SceUID t = sceKernelCreateThread("localplan_worker", LocalPlanThreadMain, 0x10000100 + 20, 0x10000, 0, SCE_KERNEL_CPU_MASK_USER_2, nullptr);
    if (g_planJobSema < 0 || t < 0)
    {
        checkpointf("M456 local plan worker FAILED (sema 0x%08x thread 0x%08x)", (unsigned)g_planJobSema, (unsigned)t);
        g_planJobSema = -1;
        return false;
    }
    sceKernelStartThread(t, 0, nullptr);
    checkpoint("M456 local plan worker started");
    return true;
}

static void UpdateLocalFlyer(size_t n, AIUnitState& au, PlacedInstance& pi, std::vector<PlacedInstance>& placedRef,
                             const std::vector<ModelData>& uniqueModels, const TerrainData& terrainData, float dt, const Vector3& playerPos)
{
    au.movedThisFrame = true;
    const UnitLoadout* lo = nullptr;
    { auto lit = g_unitClassLoadout.find(pi.unitClass); if (lit != g_unitClassLoadout.end()) lo = &lit->second; }
    const float runSpeed = (lo && lo->maxSpeed > 0.0f) ? lo->maxSpeed : 6.0f;
    const float flySpeed = runSpeed * ((lo && lo->jetThrust > 0.0f) ? lo->jetThrust : 2.0f);
    const float flyTime  = (lo && lo->jetDuration > 0.0f) ? lo->jetDuration : 30.0f;
    const float restTime = (lo && lo->jetFuelRecharge > 0.0f) ? fmaxf(1.0f, lo->jetFuelMin / lo->jetFuelRecharge) : 3.0f;
    const float kMaxFlyHeight = g_maxFlyHeight;

    float groundY = pi.position.m_Y; Vector3 gn;
    const bool haveGround = GetCombinedGroundHeightAt(terrainData, uniqueModels, placedRef, pi.position.m_X, pi.position.m_Y + 0.5f,
                                                      pi.position.m_Z, au.terrainHint, groundY, gn, au.placedIndex);
    const bool onGround = haveGround && pi.position.m_Y <= groundY + 0.05f;

    au.flyClock += dt;
    if (au.airborne && au.flyClock >= flyTime) { au.airborne = false; au.flyClock = 0.0f; }
    else if (!au.airborne && onGround && au.flyClock >= restTime) { au.airborne = true; au.flyClock = 0.0f; }
    if (!au.airborne && !onGround) au.flyClock = 0.0f;

    au.flyGoalTimer -= dt;
    if (au.flyGoalTimer <= 0.0f)
    {
        au.flyGoalTimer = 1.0f;
        au.flyHaveTarget = false;
        float bestD = 100.0f * 100.0f;
        for (const AIUnitState& o : g_aiUnits)
        {
            if (o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
            const PlacedInstance& op = placedRef[o.placedIndex];
            if (op.team < 1 || !IsHostile(pi.team, op.team)) continue;
            const float dx = op.position.m_X - pi.position.m_X, dz = op.position.m_Z - pi.position.m_Z;
            if (dx * dx + dz * dz < bestD) { bestD = dx * dx + dz * dz; au.flyLook = op.position; au.flyHaveTarget = true; }
        }
        if (g_playerTeamForScripts >= 1 && IsHostile(pi.team, g_playerTeamForScripts) && g_playerBlastPosValid)
        {
            const float dx = playerPos.m_X - pi.position.m_X, dz = playerPos.m_Z - pi.position.m_Z;
            if (dx * dx + dz * dz < bestD) { au.flyLook = playerPos; au.flyHaveTarget = true; }
        }
        if (!au.flyHaveTarget)
        {
            float bd = 1e18f;
            for (const CommandPostState& c : g_commandPosts)
            {
                if (c.team < 1 || !IsHostile(pi.team, c.team)) continue;
                const float dx = c.position.m_X - pi.position.m_X, dz = c.position.m_Z - pi.position.m_Z;
                if (dx * dx + dz * dz < bd) { bd = dx * dx + dz * dz; au.flyLook = c.position; }
            }
            if (bd > 1e17f) au.flyLook = pi.position;
        }
    }
    au.flyOrbit += 0.35f * dt;
    const float orbitR = au.flyHaveTarget ? 12.0f : 6.0f;
    const Vector3 goal(au.flyLook.m_X + cosf(au.flyOrbit) * orbitR, au.flyLook.m_Y, au.flyLook.m_Z + sinf(au.flyOrbit) * orbitR);

    float mx = goal.m_X - pi.position.m_X, mz = goal.m_Z - pi.position.m_Z;
    const float md = sqrtf(mx * mx + mz * mz);
    float speed = au.airborne ? flySpeed : (onGround ? 0.0f : runSpeed);
    if (md < 0.5f) speed = 0.0f;
    if (md > 0.001f) { mx /= md; mz /= md; }
    float step = fminf(md, speed * dt);

    if (step > 0.0f)
    {
        float hd = 0.0f; Vector3 hp;
        const Vector3 o(pi.position.m_X, pi.position.m_Y + 0.9f, pi.position.m_Z);
        auto blocked = [&](float dx, float dz) { return FireRayHitTest(o, Vector3(dx, 0.0f, dz), step + 2.0f, uniqueModels, placedRef, hd, hp, au.placedIndex); };
        if (blocked(mx, mz))
        {
            au.flyAlt = fminf(fmaxf(5.0f, kMaxFlyHeight - groundY), au.flyAlt + 8.0f * dt);
            bool found = false;
            const float side = (n & 1) ? 1.0f : -1.0f;
            const float tries[4] = { 0.61f * side, -0.61f * side, 1.22f * side, -1.22f * side };
            for (float a : tries)
            {
                const float c = cosf(a), s = sinf(a);
                const float tx = mx * c - mz * s, tz = mx * s + mz * c;
                if (!blocked(tx, tz)) { mx = tx; mz = tz; found = true; break; }
            }
            if (!found) step = 0.0f;
        }
        else if (au.flyAlt > 5.0f + (float)(n % 5)) au.flyAlt -= 3.0f * dt;
    }
    pi.position.m_X += mx * step;
    pi.position.m_Z += mz * step;

    float wantY = haveGround ? groundY : pi.position.m_Y;
    if (au.airborne)
    {
        wantY = (haveGround ? groundY : pi.position.m_Y) + au.flyAlt;
        if (au.flyHaveTarget) wantY = fmaxf(wantY, au.flyLook.m_Y + 4.0f);
        wantY = fminf(wantY, kMaxFlyHeight);
    }
    const float vy = au.airborne ? 4.0f : 5.0f;
    if (pi.position.m_Y < wantY) pi.position.m_Y = fminf(wantY, pi.position.m_Y + vy * dt);
    else pi.position.m_Y = fmaxf(wantY, pi.position.m_Y - vy * dt);
    if (haveGround && pi.position.m_Y < groundY) pi.position.m_Y = groundY;

    const float lx = au.flyLook.m_X - pi.position.m_X, lz = au.flyLook.m_Z - pi.position.m_Z;
    const float wantYaw = au.flyHaveTarget ? atan2f(-lx, -lz) : (md > 0.5f ? atan2f(-mx, -mz) : au.flyYaw);
    float dyaw = wantYaw - au.flyYaw;
    while (dyaw > 3.14159265f) dyaw -= 6.2831853f;
    while (dyaw < -3.14159265f) dyaw += 6.2831853f;
    const float turn = ((lo && lo->jetThrust > 0.0f) ? 2.25f : 2.25f) * dt;
    au.flyYaw += fmaxf(-turn, fminf(turn, dyaw));
    pi.rotation = ModelQuatFromFacingYaw(au.flyYaw);
    au.poseSpeed = au.airborne ? 0.0f : speed;

    static uint32_t s_flyLog = 0;
    static uint64_t s_flyLogUs = 0;
    const uint64_t nowUs = sceKernelGetProcessTimeWide();
    if (s_flyLog < 40 && nowUs - s_flyLogUs > 2000000ull)
    {
        s_flyLogUs = nowUs; ++s_flyLog;
        checkpointf("M476 flyer %u: %s at (%.1f,%.1f,%.1f) %.1f m over ground, target %d at %.0f m, clock %.1f",
            (unsigned)n, au.airborne ? "FLYING" : (onGround ? "resting" : "landing"), pi.position.m_X, pi.position.m_Y, pi.position.m_Z,
            pi.position.m_Y - groundY, (int)au.flyHaveTarget, sqrtf(lx * lx + lz * lz), au.flyClock);
    }
}

