static bool CaptureAgentIgnoresCombat(const AIUnitState& au, const std::vector<PlacedInstance>& placedRef, const Vector3& playerPos)
{
    if (au.targetIsDefend || au.cachedTargetCpIndex < 0 || (size_t)au.cachedTargetCpIndex >= g_commandPosts.size()) return false;
    if (au.placedIndex >= placedRef.size()) return false;
    const int myTeam = placedRef[au.placedIndex].team;
    if (!IsCapturingTeam(myTeam)) return false;
    const Vector3& cp = g_commandPosts[(size_t)au.cachedTargetCpIndex].position;
    const float R2 = 8.0f * 8.0f;
    auto near = [&](const Vector3& p) { const float dx = p.m_X - cp.m_X, dy = p.m_Y - cp.m_Y, dz = p.m_Z - cp.m_Z; return dx * dx + dy * dy + dz * dz <= R2; };
    for (const AIUnitState& o : g_aiUnits)
    {
        if (o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
        const PlacedInstance& op = placedRef[o.placedIndex];
        if (op.team <= 0 || IsFriend(op.team, myTeam)) continue;
        if (near(op.position)) return false;
    }
    if (g_playerTeam > 0 && !IsFriend(g_playerTeam, myTeam) && near(playerPos)) return false;
    return true;
}

struct DekaLow { uint32_t crc = 0; int loco = 0; float lo = 1e30f, hi = -1e30f; uint32_t n = 0; };
static DekaLow g_dekaLow[8]; static int g_dekaLowN = 0;
static void DekaLowNote(uint32_t crc, float lo, int loco)
{
    if (lo > 1e29f) return;
    int i = 0; while (i < g_dekaLowN && !(g_dekaLow[i].crc == crc && g_dekaLow[i].loco == loco)) ++i;
    if (i == g_dekaLowN) { if (g_dekaLowN == 8) return; g_dekaLow[g_dekaLowN++] = DekaLow{crc, loco}; }
    DekaLow& d = g_dekaLow[i]; d.lo = fminf(d.lo, lo); d.hi = fmaxf(d.hi, lo); ++d.n;
}
