static const int SOUND_OWNER_PLAYER_SABER = -11;
static void UpdateSaberAmbient()
{
    static int hum = -2, on = -2, off = -2, missLogged = 0;
    static bool wasLit = false;
    if (hum == -2)
    {
        auto look = [](const char* n) { auto it = g_soundClipIndexByName.find(n); return it == g_soundClipIndexByName.end() ? -1 : it->second; };
        hum = look("saber_idle02"); on = look("saberon"); off = look("saberoff");
        if (hum < 0 && ++missLogged <= 3) checkpointf("HEROES saber ambient: \"saber_idle02\" not decoded (%d/%d/%d)", hum, on, off);
    }
    const bool lit = g_playerWeaponValid && g_playerWeapon.isMelee && g_playerWeapon.saberLength > 0.0f
                  && g_playerVehicle < 0 && g_playerAliveForAI;
    if (lit && hum >= 0)
    {
        if (!wasLit && on >= 0) PlaySoundClip(on, 0.6f);
        SetOwnerVoice(SOUND_OWNER_PLAYER_SABER, hum, 0.5f, 1.0f, true);
        wasLit = true;
    }
    else if (wasLit)
    {
        StopOwnerVoices(SOUND_OWNER_PLAYER_SABER);
        if (off >= 0) PlaySoundClip(off, 0.6f);
        wasLit = false;
    }
}

static int AiEngageMode(int styleN, float dist, float range)
{
    static const int kW[2][4] = { { 2, 2, 1, 1 }, { 1, 1, 5, 1 } };
    const int* w = kW[AiDifficultyLevel() >= 3 ? 1 : 0];
    const float space = 0.0f;
    const bool ok[4] = { true, true, space > 10.0f, space > 5.0f };
    int total = 0; for (int i = 0; i < 4; ++i) if (ok[i]) total += w[i];
    int r = styleN % total, mode = 3;
    for (int i = 0; i < 4; ++i) { if (r < w[i] && ok[i]) { mode = 2 + i; break; } r -= w[i]; if (r < 0) break; }
    if (mode == 2 && dist > range) mode = 3;
    return mode;
}

static void AiHearNoise(const Vector3& pos, int team, float r, size_t emitterAi, const std::vector<PlacedInstance>& placedRef)
{
    if (r <= 0.0f || team < 1) return;
    for (size_t hj = 0; hj < g_aiUnits.size(); ++hj)
    {
        if (hj == emitterAi) continue;
        AIUnitState& h = g_aiUnits[hj];
        if (h.life != AI_LIFE_ALIVE || h.vehicle >= 0 || h.haveCachedTarget || h.placedIndex >= placedRef.size()) continue;
        const PlacedInstance& hp = placedRef[h.placedIndex];
        if (hp.team < 1 || !IsCombatTeam(hp.team) || !IsHostile(team, hp.team)) continue;
        const float dx = pos.m_X - hp.position.m_X, dz = pos.m_Z - hp.position.m_Z, d2 = dx * dx + dz * dz;
        if (d2 > r * r) continue;
        if (d2 < 9.0f)
        {
            h.haveCachedTarget = true; h.cachedTargetIsPlayer = emitterAi == SIZE_MAX; h.cachedTargetAiIdx = emitterAi == SIZE_MAX ? (size_t)-1 : emitterAi;
            h.cachedTargetPos = pos; h.noiseSec = 0.0f; h.lookSec = 0.0f;
        }
        else if (h.noiseSec <= 0.0f) { h.noiseSec = 10.0f; h.noiseX = pos.m_X; h.noiseZ = pos.m_Z; h.noiseStop = 2.0f; ++h.noiseSerial; ++g_whyTgt[6]; }
    }
}

