struct SquadOrderVoice { float at; int ui; const char* event; };
static std::vector<SquadOrderVoice> g_squadOrderVoices;
static bool g_squadNoVoDbg = getenv("SWBF2_SQNOVO") != nullptr;

static uint32_t s_squadVoiceRng = 0x9e3779b9u;
static float SquadVoiceRand01()
{
    s_squadVoiceRng ^= s_squadVoiceRng << 13; s_squadVoiceRng ^= s_squadVoiceRng >> 17; s_squadVoiceRng ^= s_squadVoiceRng << 5;
    return (float)(s_squadVoiceRng & 0xffffffu) / (float)0x1000000u;
}

static void SquadPlayVoiceLine(const std::string& speakerCls, const Vector3& at, const char* event, const char* what)
{
    if (g_squadNoVoDbg) { checkpointf("M16 FOLLOWVO %s: sqnovo - no line (old rule)", what); return; }
    if (!g_listenerValid) return;
    auto lit = g_unitClassLoadout.find(speakerCls);
    if (lit == g_unitClassLoadout.end()) { checkpointf("M16 FOLLOWVO %s: \"%s\" has no loadout voice", what, speakerCls.c_str()); return; }
    const UnitLoadout::VoRow* pick = nullptr; int ties = 0;
    for (const UnitLoadout::VoRow& r : lit->second.voRows)
        if (r.event == event) { ++ties; if (SquadVoiceRand01() * (float)ties < 1.0f) pick = &r; }
    if (pick == nullptr) { checkpointf("M16 FOLLOWVO %s: \"%s\" has no VOSound row for %s", what, speakerCls.c_str(), event); return; }
    const int ci = VoGenFind(pick->cue);
    if (ci < 0) { checkpointf("M16 FOLLOWVO %s: cue \"%s\" has no real segment data", what, pick->cue.c_str()); return; }
    const VoGenCue& c = kVoGenCues[ci];
    const float dx = at.m_X - g_listenerPos.m_X, dy = at.m_Y - g_listenerPos.m_Y, dz = at.m_Z - g_listenerPos.m_Z;
    const float d = sqrtf(dx * dx + dy * dy + dz * dz);
    float gain = 0.6f;
    if (c.pos3d)
    {
        if (c.maxDist > 0.0f && d > c.maxDist) { checkpointf("M16 FOLLOWVO %s: \"%s\" out of range (%.0f m > %.0f)", what, pick->cue.c_str(), d, c.maxDist); return; }
        if (d > c.minDist) gain *= c.minDist / (c.minDist + 3.0f * (d - c.minDist));
    }
    const bool queued = RequestVoiceOver(pick->cue, gain);
    checkpointf("M16 FOLLOWVO %s: \"%s\" plays \"%s\" (event %s, gain %.2f at %.0f m, %s)", what, speakerCls.c_str(),
                pick->cue.c_str(), event, gain, d, queued ? "queued" : "queue full - dropped");
}

static void SquadOrderVoiceSchedule(int ui, const char* event)
{
    if (g_squadNoVoDbg) { checkpointf("M16 FOLLOWVO: sqnovo - no answer queued for unit %d (old rule)", ui); return; }
    const float delay = 0.5f + SquadVoiceRand01() * 0.7f;
    if (g_squadOrderVoices.size() < 8) g_squadOrderVoices.push_back({ g_chatterClock + delay, ui, event });
}

static void UpdateSquadOrderVoice(const std::vector<PlacedInstance>& placedRef)
{
    for (size_t i = 0; i < g_squadOrderVoices.size(); )
    {
        const SquadOrderVoice v = g_squadOrderVoices[i];
        if (g_chatterClock < v.at) { ++i; continue; }
        const bool follow = strcmp(v.event, "SC_FollowResponse") == 0;
        const AIUnitState* u = ((size_t)v.ui < g_aiUnits.size()) ? &g_aiUnits[(size_t)v.ui] : nullptr;
        if (u != nullptr && u->life == AI_LIFE_ALIVE && u->placedIndex < placedRef.size() && u->follower == follow)
        {
            const PlacedInstance& p = placedRef[u->placedIndex];
            SquadPlayVoiceLine(p.unitClass, p.position, v.event, follow ? "follow order" : "release order");
        }
        else
            checkpointf("M16 FOLLOWVO: unit %d did not answer %s (dead or re-ordered inside the 0.5-1.2 s window)",
                        v.ui, v.event);
        g_squadOrderVoices.erase(g_squadOrderVoices.begin() + (long)i);
    }
}

static void SquadReleaseUnit(int ui, const char* why, bool ordered = false)
{
    if (ui < 0 || (size_t)ui >= g_aiUnits.size()) return;
    AIUnitState& u = g_aiUnits[(size_t)ui];
    if (!u.follower) return;
    u.follower = false; u.followState = 3; u.followAwaySec = 0.0f; u.followRepick = 0.0f;
    u.navPath.clear(); u.navRepathTimer = 0.0f; u.routeDoneGoal = -1;
    checkpointf("M10 FOLLOWME: unit %d released (%s) - followers now %d", ui, why, SquadFollowerCount());

    if (ordered) SquadOrderVoiceSchedule(ui, "SC_StopFollowResponse");
}

static void SquadReleaseAll(const char* why, bool ordered = false)
{
    for (size_t i = 0; i < g_aiUnits.size(); ++i) SquadReleaseUnit((int)i, why, ordered);
}

static int SquadReticlePick(const Vector3& eye, const Vector3& dir, float range,
                            std::vector<PlacedInstance>& placedRef, int playerTeam)
{
    size_t ui = SIZE_MAX; float dist = 0.0f; bool head = false;
    if (!FireRayHitAIUnit(eye, dir, range, placedRef, ui, dist, head, SIZE_MAX)) return -1;
    if (ui >= g_aiUnits.size()) return -1;
    const AIUnitState& u = g_aiUnits[ui];
    if (u.life != AI_LIFE_ALIVE || u.placedIndex >= placedRef.size()) return -1;
    const PlacedInstance& p = placedRef[u.placedIndex];
    if (p.team < 1 || p.team != playerTeam) return -1;
    if (u.vehicle >= 0) return -1;
    return (int)ui;
}

static void SquadCommandPress(const Vector3& eye, const Vector3& dir, float range,
                              std::vector<PlacedInstance>& placedRef, int playerTeam)
{
    if (g_squadOldDbg) { checkpoint("M10 FOLLOWME sqold: the D-pad-up command does nothing (old rule)"); return; }
    const int pick = SquadReticlePick(eye, dir, range, placedRef, playerTeam);
    if (pick < 0) { checkpointf("M10 FOLLOWME press: no friendly AI unit under the reticle (range %.0f)", range); return; }
    AIUnitState& t = g_aiUnits[(size_t)pick];
    if (t.follower)
    {
        checkpointf("M10 FOLLOWME press: unit %d was already a follower -> 0x12 \"stopfollowchr\"", pick);
        SquadReleaseUnit(pick, "the order was given on him again", true);
        return;
    }

    if (SquadFollowerCount() >= g_squadCap)
        for (size_t i = 0; i < g_aiUnits.size(); ++i)
            if (g_aiUnits[i].follower) { SquadReleaseUnit((int)i, "a full follower slot", true); break; }
    t.follower = true; t.followState = 3; t.followAwaySec = 0.0f; t.followRepick = 0.0f;
    t.navPath.clear(); t.navRepathTimer = 0.0f; t.routeDoneGoal = -1;
    if (t.hintNodeIdx >= 0 && t.hintNodeIdx < (int)g_hintNodes.size() && g_hintNodes[(size_t)t.hintNodeIdx].reservedBy == pick)
        g_hintNodes[(size_t)t.hintNodeIdx].reservedBy = -1;
    t.hintNodeIdx = -1; t.hintKind = 0; t.hintAt = false; t.hintHoldTime = 0.0f;
    checkpointf("M10 FOLLOWME press: unit %d \"%s\" -> 0x10 \"followchr\" (followers %d/%d)",
        pick, placedRef[t.placedIndex].unitClass.c_str(), SquadFollowerCount(), g_squadCap);
    SquadOrderVoiceSchedule(pick, "SC_FollowResponse");
}

static void UpdateAIUnits(std::vector<PlacedInstance>& placedRef, const std::vector<ModelData>& uniqueModels,
    const TerrainData& terrainData, float deltaSec, const Vector3& playerPos)
{
    TickSpawnClocks(deltaSec);
    ++g_aiFrameNo;
    if (!(g_fightOff & 2) && (g_aiFrameNo % 15) == 0 && g_playerAliveForAI && g_playerVehicle < 0 && g_playerTeamForScripts >= 1)
    {

        AiHearNoise(playerPos, g_playerTeamForScripts, g_playerFiredSince ? 30.0f : 8.0f, SIZE_MAX, placedRef);
        g_playerFiredSince = false;
    }
    for (int t = 0; t < 8; ++t) g_aiAliveNow[t] = 0;
    for (const AIUnitState& o : g_aiUnits) if (o.life == AI_LIFE_ALIVE && o.homeTeam >= 0 && o.homeTeam < 8) ++g_aiAliveNow[o.homeTeam];
    if (g_reinfTrace)
    {

        static float s_lastT = -1e9f;
        static int s_lastTickets[8] = { -999, -999, -999, -999, -999, -999, -999, -999 };
        bool tailChange = false;
        for (int t = 1; t <= 2; ++t)
        {
            const int tc = TeamTicketsLeft(t);
            if (tc >= 0 && tc <= 20 && tc != s_lastTickets[t]) tailChange = true;
        }
        if (g_aiClock - s_lastT >= 10.0f || tailChange)
        {
            s_lastT = g_aiClock;
            for (int t = 1; t <= 2; ++t)
            {
                const int tc = TeamTicketsLeft(t);
                s_lastTickets[t] = tc;
                const int pl = (g_playerTeamForScripts == t && g_playerAliveForAI) ? 1 : 0;
                checkpointf("REINF t=%.1f team%d tickets=%d aliveUnits=%d (ai=%d player=%d) ticketWaits=%u",
                    g_aiClock, t, tc, g_aiAliveNow[t] + pl, g_aiAliveNow[t], pl, (unsigned)g_ticketWaits[t]);
            }
        }
    }
    g_aiDiagActive = 0; g_aiDiagWithPath = 0; g_aiDiagStuck = 0; g_aiDiagNoGoal = 0; g_aiDiagBarrierBlocked = 0; g_aiDiagBarrierStop = 0; g_aiDiagUsingHint = 0; g_aiDiagEngaging = 0; g_aiDiagBodyAvoid = 0;
    static uint32_t s_aiCollFrame = 0;

    g_localPlansThisFrame = 0;

    g_planDebtUs += (int64_t)g_localPlanUsThisFrame - (int64_t)LOCALNAV_PLAN_BUDGET_US;
    if (g_planDebtUs < 0) g_planDebtUs = 0;
    g_localPlanUsThisFrame = 0;

    ++g_planFrame;
    for (size_t qi = 0; qi < g_planQueue.size() && qi < LOCALNAV_PLANS_PER_FRAME; )
    {
        const uint32_t u = g_planQueue[qi];
        if (u >= g_planAskFrame.size() || g_planAskFrame[u] + 1u < g_planFrame)
        {
            if (u < g_planQueuedFlag.size()) g_planQueuedFlag[u] = 0;
            g_planQueue.erase(g_planQueue.begin() + (std::ptrdiff_t)qi);
        }
        else ++qi;
    }

    if (g_planJobState == 2)
    {
        __sync_synchronize();
        LocalPlanJob& j = g_planJob;
        const size_t n = j.unit;
        if (n < g_aiUnits.size() && g_aiUnits[n].planInFlight && g_aiUnits[n].placedIndex < placedRef.size())
        {
            AIUnitState& au = g_aiUnits[n];
            const PlacedInstance& pi = placedRef[au.placedIndex];
            au.planInFlight = false;
            au.localPlanPending = false;
            if (j.floorWon || j.retryWon) ++g_localPlanRetriesWon;
            if (j.floorWon)
                checkpointf("M417 raised-floor re-plan: unit %u at (%.1f,%.2f,%.1f) routed from the floor below (%.2f)",
                    (unsigned)n, j.start.m_X, j.start.m_Y, j.start.m_Z, j.floorY);
            if (j.retryFailed) au.planRetryBlockSec = 5.0f;
            g_localNavPlanUs += j.us; ++g_localNavPlans;

            if (au.cpSpotFor >= 0 && (size_t)au.cpSpotFor < g_commandPosts.size()
                && fabsf(j.target.m_X - au.cpSpotX) < 0.5f && fabsf(j.target.m_Z - au.cpSpotZ) < 0.5f)
            {
                const CommandPostState& sc = g_commandPosts[(size_t)au.cpSpotFor];
                if (j.reached) au.cpSpotFails = 0;
                else if (sc.hasCaptureRegion && PointInRegion(sc.captureRegionPos, sc.captureRegionRot, sc.captureRegionSize, sc.captureRegionType, pi.position))
                {
                    if (AITraceUnit(n)) checkpointf("M486 spot u%u: (%.1f,%.1f) unreachable, inside %s - staying at (%.1f,%.1f)", (unsigned)n, au.cpSpotX, au.cpSpotZ, sc.name.c_str(), pi.position.m_X, pi.position.m_Z);
                    au.cpSpotX = pi.position.m_X; au.cpSpotZ = pi.position.m_Z; au.cpSpotFails = 0;
                    ++g_aiSpotUnreachable;
                }
                else if (++au.cpSpotFails >= 2)
                {
                    if (AITraceUnit(n)) checkpointf("M486 spot u%u: (%.1f,%.1f) unreachable twice - re-rolled", (unsigned)n, au.cpSpotX, au.cpSpotZ);
                    au.cpSpotFor = -1; au.cpSpotFails = 0;
                    ++g_aiSpotUnreachable;
                }
            }

            if (au.navPathIndex == 0 && au.navPathIndex < au.navPath.size() && au.navPath[0] < g_navHubs.size())
            {
                const NavHub& th = g_navHubs[au.navPath[0]];
                const float tdx = j.target.m_X - th.position.m_X, tdz = j.target.m_Z - th.position.m_Z;
                const float sr = fminf(th.radius * 0.6f, 6.0f) + 0.5f;
                if (tdx * tdx + tdz * tdz <= sr * sr)
                {
                    bool noProgress = !j.reached;
                    if (noProgress && j.planned && !j.path.empty())
                    {
                        const float ex = j.path.back().m_X - pi.position.m_X, ez = j.path.back().m_Z - pi.position.m_Z;
                        noProgress = (ex * ex + ez * ez) < 3.0f * 3.0f;
                    }
                    if (!noProgress) au.hubFails = 0;
                    else if (++au.hubFails >= 3)
                    {
                        au.badHub[2] = au.badHub[1]; au.badHub[1] = au.badHub[0]; au.badHub[0] = (int)au.navPath[0];
                        au.badHubSec = 60.0f; au.hubFails = 0;
                        if (AITraceUnit(n) || g_aiHubBans < 20)
                            checkpointf("M487 hub ban u%u: start hub %u (%.1f, %.1f) unreachable from (%.1f, %.1f) - rerouting",
                                        (unsigned)n, (unsigned)au.navPath[0], th.position.m_X, th.position.m_Z, pi.position.m_X, pi.position.m_Z);
                        ++g_aiHubBans;
                        au.navPath.clear(); au.navRepathTimer = 0.0f;
                    }
                }
            }
            if (au.life == AI_LIFE_ALIVE && j.planned && !j.path.empty())
            {
                au.localPath.swap(j.path);
                au.localPathValid = true;
                au.localPathIndex = 0;
                au.localPathTarget = j.target;

                const Vector3& last = au.localPath.back();
                const float ldx = last.m_X - pi.position.m_X, ldz = last.m_Z - pi.position.m_Z;
                if (!j.reached && ldx * ldx + ldz * ldz < 3.0f * 3.0f) au.localPlanCooldown = 3.0f;
            }
            else au.localPlanCooldown = 2.0f;
            if (AITraceUnit(n))
            {
                char wbuf[256]; int wl = 0; wbuf[0] = 0;
                for (size_t wi = 0; wi < au.localPath.size() && wi < 8 && wl < 220; ++wi)
                    wl += snprintf(wbuf + wl, sizeof(wbuf) - (size_t)wl, "(%.1f,%.1f)", au.localPath[wi].m_X, au.localPath[wi].m_Z);
                checkpointf("M344 plan u%u from=(%.2f,%.2f,%.2f) to=(%.1f,%.1f) ok=%d reached=%d expanded=%d wps=%s",
                    (unsigned)n, j.start.m_X, j.start.m_Y, j.start.m_Z, j.target.m_X, j.target.m_Z,
                    (int)j.planned, (int)j.reached, j.expanded, wbuf);

                static float s_lastGrid[64] = {};
                if (!j.reached && j.snap && g_planSnap.size() == (size_t)(LOCALNAV_N * LOCALNAV_N) && n < 64 && g_aiClock - s_lastGrid[n] > 60.0f)
                {
                    s_lastGrid[n] = g_aiClock;
                    const int N = LOCALNAV_N;
                    const int si = g_planSnapStart % N, sj = g_planSnapStart / N, gi = g_planSnapGoal % N, gj = g_planSnapGoal / N;
                    const int i0 = std::max(0, std::min(si, gi) - 14), i1 = std::min(N - 1, std::max(si, gi) + 14);
                    const int j0 = std::max(0, std::min(sj, gj) - 10), j1 = std::min(N - 1, std::max(sj, gj) + 10);
                    checkpointf("M481 plan grid u%u feet %.2f: cells %d..%d x %d..%d (0.5 m, +x right, +z down), start (%d,%d) goal (%d,%d)",
                                (unsigned)n, g_planSnapFeetY, i0, i1, j0, j1, si, sj, gi, gj);
                    for (int gjr = j0; gjr <= j1; ++gjr)
                    {
                        char row[200]; int rl = 0;
                        for (int gir = i0; gir <= i1 && rl < 190; ++gir)
                        {
                            const int c = gjr * N + gir; const uint8_t b = g_planSnap[(size_t)c];
                            row[rl++] = (c == g_planSnapStart) ? 'S' : (c == g_planSnapGoal) ? 'G' : (c == g_planSnapBest) ? '*'
                                      : (b & 1) ? '#' : (b & 2) ? 'o' : (b & 4) ? 'b' : b ? '?' : '.';
                        }
                        row[rl] = 0;
                        checkpointf("M481 grid %s", row);
                    }
                }
            }
            if (g_localNavDiagCount < 60)
            {
                ++g_localNavDiagCount;
                checkpointf("M327 localPath: unit=%u team=%d from=(%.1f,%.1f,%.1f) to=(%.1f,%.1f) ok=%d reached=%d expanded=%d waypoints=%u",
                    (unsigned)n, pi.team, j.start.m_X, j.start.m_Y, j.start.m_Z, j.target.m_X, j.target.m_Z,
                    (int)au.localPathValid, (int)j.reached, j.expanded, (unsigned)au.localPath.size());
            }
        }
        g_planJobState = 0;
    }
    {

        static float s_navCostClock = 0.0f;
        static uint32_t s_navCostFrames = 0;
        s_navCostClock += deltaSec; ++s_navCostFrames;
        if (s_navCostClock >= 1.0f)
        {
            uint32_t withPath = 0;
            for (const AIUnitState& u : g_aiUnits) if (u.localPathValid) ++withPath;
            const float np = g_localNavPlans ? (float)g_localNavPlans : 1.0f;
            checkpointf("M327 nav cost: plans=%u planMs/frame=%.2f (%.2f each: walls %.2f bar %.2f terr %.2f A* %.2f pull %.2f, avg expanded %u) checks=%u checkMs/frame=%.2f unitsOnPath=%u retriesWon=%u refusedSteps=%u resolverLifts=%u (max %.2fm) curbSteps=%u spreadInBarrier=%u fireHeldForTurn=%u turningUnitFrames=%u holdForPlanFrames=%u abilities(gren/disp/buff/debuff/mine)=%u/%u/%u/%u/%u queue=%u debtUs=%lld front=%d(asked %d frames ago) pendingUnits=%u",
                g_localNavPlans, (float)g_localNavPlanUs / 1000.0f / (float)s_navCostFrames,
                (float)g_localNavPlanUs / 1000.0f / np,
                (float)g_lnPhaseUs[0] / 1000.0f / np, (float)g_lnPhaseUs[1] / 1000.0f / np, (float)g_lnPhaseUs[2] / 1000.0f / np,
                (float)g_lnPhaseUs[3] / 1000.0f / np, (float)g_lnPhaseUs[4] / 1000.0f / np,
                (unsigned)(g_lnExpanded / (uint32_t)np),
                g_localNavChecks, (float)g_localNavCheckUs / 1000.0f / (float)s_navCostFrames, withPath, g_localPlanRetriesWon, g_aiRefusedStepCount, g_aiResolverLiftCount, g_aiResolverLiftMax, g_aiCurbSteps, g_aiSpreadInBarrier, g_aiFireHeldForTurn, g_aiTurningFrames, g_aiHoldForPlanFrames,
                g_aiAbilityUses[ABIL_GRENADE], g_aiAbilityUses[ABIL_DISPENSER], g_aiAbilityUses[ABIL_BUFF], g_aiAbilityUses[ABIL_DEBUFF], g_aiAbilityUses[ABIL_MINE],
                (unsigned)g_planQueue.size(), (long long)g_planDebtUs,
                g_planQueue.empty() ? -1 : (int)g_planQueue.front(),
                (!g_planQueue.empty() && g_planQueue.front() < g_planAskFrame.size()) ? (int)(g_planFrame - g_planAskFrame[g_planQueue.front()]) : -1,
                [](){ unsigned c = 0; for (const AIUnitState& u : g_aiUnits) if (u.localPlanPending && u.life == AI_LIFE_ALIVE) ++c; return c; }());
            g_aiFireHeldForTurn = 0; g_aiTurningFrames = 0; g_aiHoldForPlanFrames = 0;
            g_localPlanRetriesWon = 0;
            g_aiSpreadInBarrier = 0;
            g_aiRefusedStepCount = 0; g_aiResolverLiftCount = 0; g_aiResolverLiftMax = 0.0f; g_aiCurbSteps = 0;
            s_navCostClock = 0.0f; s_navCostFrames = 0;
            g_localNavPlanUs = 0; g_localNavCheckUs = 0; g_localNavPlans = 0; g_localNavChecks = 0;
            for (uint64_t& ph : g_lnPhaseUs) ph = 0;
            g_lnExpanded = 0;
        }
    }
    ++s_aiCollFrame;

    const size_t cpN = g_commandPosts.size();
            checkpointf("M501 retail nav: arrivals=%u stuckFrames=%u blockedEvents=%u (on=%d) M502 start: node=%u corridor=%u nearestArc=%u", g_rnArrivals, g_rnStuckEvents, g_rnBlockedEvents, (int)g_retailNav, g_rnLocHub, g_rnLocCorridor, g_rnLocNearest); g_rnArrivals = g_rnStuckEvents = g_rnBlockedEvents = 0; g_rnLocHub = g_rnLocCorridor = g_rnLocNearest = 0;
            { std::string fp; for (int a = 0; a < 16; ++a) for (int b = 0; b < 16; ++b) if (g_faceFlipPair[a][b]) fp += " " + std::to_string(a) + "->" + std::to_string(b) + ":" + std::to_string(g_faceFlipPair[a][b]); checkpointf("FACING flips by writer:%s", fp.c_str()); }
            checkpointf("FACING 6->6 flips by activity: route %u rw %u side %u circle %u wander %u cover %u lastleg %u snipe %u", g_flip66By[0], g_flip66By[1], g_flip66By[2], g_flip66By[3], g_flip66By[4], g_flip66By[5], g_flip66By[6], g_flip66By[7]);
            checkpointf("M531 route table: walks=%u A*fallbacks=%u | random walks: started=%u done=%u timedOut=%u | M532 legs: planned=%u round-barriers=%u failed=%u side-step frames=%u | DEADTGT bodies skipped=%u dead targets dropped=%u | FACING per 1000 unit-frames: snaps %.1f flips %.1f | foreign turns %u aim resets %u snaps with aim step %u", g_routeWalks, g_routeFallbacks, g_rwStarts, g_rwDone, g_rwTimeouts, g_legPlans, g_legCornerPlans, g_legFails, g_sideSteps, g_deadTgtSkipped, g_deadTgtDropped, g_faceFrames ? 1000.0 * g_faceSnaps / g_faceFrames : 0.0, g_faceFrames ? 1000.0 * g_faceFlips / g_faceFrames : 0.0, g_faceForeign, g_faceAimReset, g_faceSnapAim);
            g_routeWalks = g_routeFallbacks = g_rwStarts = g_rwDone = g_rwTimeouts = 0;
    for (int t = 0; t < 8; ++t)
    {
        s_cpAssigned[t].assign(cpN, 0);
        s_cpEnemiesNear[t].assign(cpN, 0);
        s_teamAlive[t] = 0;
    }
    for (const AIUnitState& u : g_aiUnits)
    {
        if (u.placedIndex >= placedRef.size() || u.life != AI_LIFE_ALIVE) continue;
        const PlacedInstance& up = placedRef[u.placedIndex];
        if (up.team <= 0 || up.team >= 8) continue;
        ++s_teamAlive[up.team];
        if (u.cachedTargetCpIndex >= 0 && (size_t)u.cachedTargetCpIndex < cpN) ++s_cpAssigned[up.team][(size_t)u.cachedTargetCpIndex];
        for (size_t c = 0; c < cpN; ++c)
        {
            const float dx = g_commandPosts[c].position.m_X - up.position.m_X, dz = g_commandPosts[c].position.m_Z - up.position.m_Z;
            if (dx * dx + dz * dz > 40.0f * 40.0f) continue;
            for (int t = 1; t < 8; ++t) if (t != up.team) ++s_cpEnemiesNear[t][c];
        }
    }

    g_cpLostEvents.clear();
    {

        static float s_spreadClock = 0.0f;
        s_spreadClock += deltaSec;
        if (s_spreadClock >= 10.0f)
        {
            s_spreadClock = 0.0f;
            for (int t = 1; t <= 2; ++t)
            {
                std::string line;

                std::vector<float> nearD(cpN, 1e9f), sumD(cpN, 0.0f);
                for (const AIUnitState& u : g_aiUnits)
                {
                    if (u.placedIndex >= placedRef.size() || u.life != AI_LIFE_ALIVE) continue;
                    const PlacedInstance& up = placedRef[u.placedIndex];
                    if (up.team != t || u.cachedTargetCpIndex < 0 || (size_t)u.cachedTargetCpIndex >= cpN) continue;
                    const Vector3& cpp = g_commandPosts[(size_t)u.cachedTargetCpIndex].position;
                    const float d = sqrtf((cpp.m_X - up.position.m_X) * (cpp.m_X - up.position.m_X) + (cpp.m_Z - up.position.m_Z) * (cpp.m_Z - up.position.m_Z));
                    nearD[(size_t)u.cachedTargetCpIndex] = fminf(nearD[(size_t)u.cachedTargetCpIndex], d);
                    sumD[(size_t)u.cachedTargetCpIndex] += d;
                }
                if (s_cpDeaths[t].size() != cpN) { s_cpDeaths[t].assign(cpN, 0); s_cpDeathDistSum[t].assign(cpN, 0.0f); }
                for (size_t c = 0; c < cpN; ++c)
                {
                    char b[96];
                    const int a = s_cpAssigned[t][c], dth = s_cpDeaths[t][c];
                    snprintf(b, sizeof(b), " %s(%s)=%d[near %.0f avg %.0f dead %d@%.0f]", g_commandPosts[c].name.c_str(),
                        g_commandPosts[c].team == t ? "own" : (g_commandPosts[c].team == 0 ? "neu" : "enemy"), a,
                        a > 0 ? nearD[c] : 0.0f, a > 0 ? sumD[c] / (float)a : 0.0f, dth, dth > 0 ? s_cpDeathDistSum[t][c] / (float)dth : 0.0f);
                    line += b;
                }
                s_cpDeaths[t].assign(cpN, 0); s_cpDeathDistSum[t].assign(cpN, 0.0f);
                checkpointf("M403 conquest team %d (%d alive):%s", t, s_teamAlive[t], line.c_str());
            }
            if (!g_deathTally.empty())
            {
                std::string tl;
                for (const auto& kv : g_deathTally) tl += " " + kv.first + "=" + std::to_string(kv.second);
                checkpointf("M447 deaths by cause (last period):%s", tl.c_str());
                g_deathTally.clear();
            }
            if (!g_killPairs.empty())
            {
                std::string kl;
                for (const auto& kv : g_killPairs) kl += " " + kv.first + "=" + std::to_string(kv.second);
                checkpointf("LOCALS kills by team (last period):%s", kl.c_str());
                g_killPairs.clear();
            }
            {

                static float s_locCensusSec = 0.0f;
                static std::map<size_t, Vector3> s_locLast;
                if (g_aiClock >= s_locCensusSec)
                {
                    s_locCensusSec = g_aiClock + 60.0f;
                    std::string wl;
                    unsigned nAlive = 0;
                    for (size_t ui = 0; ui < g_aiUnits.size(); ++ui)
                    {
                        const AIUnitState& au = g_aiUnits[ui];
                        if (au.homeTeam < 1 || IsCapturingTeam(au.homeTeam) || au.placedIndex >= placedRef.size()) continue;
                        const PlacedInstance& up = placedRef[au.placedIndex];
                        float moved = -1.0f;
                        auto li = s_locLast.find(ui);
                        if (li != s_locLast.end() && au.life == AI_LIFE_ALIVE)
                        {
                            const float dx = up.position.m_X - li->second.m_X, dz = up.position.m_Z - li->second.m_Z;
                            moved = sqrtf(dx * dx + dz * dz);
                        }
                        s_locLast[ui] = up.position;
                        char b[160];
                        snprintf(b, sizeof(b), " u%u(t%d%s %.0f,%.0f,%.0f moved=%.0fm cp%d tgt%d)",
                            (unsigned)ui, au.homeTeam, au.life == AI_LIFE_ALIVE ? "" : " dead",
                            up.position.m_X, up.position.m_Y, up.position.m_Z, moved,
                            au.cachedTargetCpIndex, (int)au.haveCachedTarget);
                        wl += b;
                        if (au.life == AI_LIFE_ALIVE) ++nAlive;
                    }
                    checkpointf("LOCALS census (%u alive):%s", nAlive, wl.c_str());
                }
            }
        }
    }

    g_aiuWorstUs = 0; g_aiuNavUs = 0; g_aiuVehUs = 0; g_aiuNavCalls = 0;
    g_aiClock += deltaSec;
    g_rayCalls = g_rayMarch = g_rayTris = g_rayWorstTris = 0; g_rayWorstPlaced = SIZE_MAX;
    for (size_t n = 0; n < g_aiUnits.size(); ++n)
    {

        struct UnitClock { size_t n; uint64_t t0 = sceKernelGetProcessTimeWide();
            ~UnitClock() { const uint64_t d = sceKernelGetProcessTimeWide() - t0; if (d > g_aiuWorstUs) { g_aiuWorstUs = d; g_aiuWorstUnit = n; } } } unitClock{ n };
        AIUnitState& au = g_aiUnits[n];
        if (n > 0) g_aiUnits[n - 1].exitSec = (int8_t)g_aiLapSec;
        AiLap(0);
        if (au.placedIndex >= placedRef.size()) continue;

        if (au.life == AI_LIFE_ALIVE)
        {
            const PlacedInstance& opi = placedRef[au.placedIndex];
            const float ovy = g_retailSoldierCollision ? au.rscBody.vel.y : 0.0f;
            const char* oow = nullptr;
            if (opi.position.m_Y < -1000.0f) oow = "fell below the world";
            else if (opi.position.m_Y > 1000.0f) oow = "flew over the world";
            else if (fabsf(opi.position.m_X) > 2500.0f || fabsf(opi.position.m_Z) > 2500.0f) oow = "flew out of the world";
            if (oow != nullptr)
            {
                checkpointf("OUTBOX AI unit %u (team %d) %s at (%.1f, %.1f, %.1f) vy %.1f - destroyed (retail box)",
                    (unsigned)n, opi.team, oow, opi.position.m_X, opi.position.m_Y, opi.position.m_Z, ovy);

                const char* const savedSrc = g_damageSource;
                g_damageSource = "out of world";
                ApplyDamageToAIUnit(n, 1.0e6f, placedRef);
                g_damageSource = savedSrc;
            }
        }
        au.movedLastFrame = au.movedThisFrame;
        if (au.life == AI_LIFE_ALIVE && au.vehicle < 0 && au.why < 32) ++g_whyHist[au.movedLastFrame ? 1 : 0][au.why];
        if (au.life == AI_LIFE_ALIVE && au.vehicle < 0) { ++g_whyTgt[0]; if (au.haveCachedTarget) ++g_whyTgt[1]; if (au.hintNodeIdx >= 0) { ++g_whyTgt[2]; if (au.hintAt) ++g_hintAtFrames; } }

        if (au.life == AI_LIFE_ALIVE && !au.abilities.empty())
            for (AIUnitState::Ability& ab : au.abilities)
            {
                if (ab.kind != ABIL_MINE || ab.reserve <= 0) continue;
                const PlacedInstance& mp = placedRef[au.placedIndex];
                for (HintNodeData& hn : g_hintNodes)
                {
                    if (hn.type != HINT_MINE || hn.mined) continue;
                    const float mdx = hn.position.m_X - mp.position.m_X, mdz = hn.position.m_Z - mp.position.m_Z;
                    if (mdx * mdx + mdz * mdz > 3.0f * 3.0f) continue;
                    SpawnRealOrdnance(Vector3(hn.position.m_X, hn.position.m_Y + 0.5f, hn.position.m_Z), Vector3(0.0f, -1.0f, 0.0f),
                                      ab.weaponIndex,  false, n, 0.0f);
                    hn.mined = true; --ab.reserve; ++g_aiAbilityUses[ABIL_MINE];
                    checkpointf("M407 AI mine: unit %u laid \"%s\" at a mine node", (unsigned)n, g_weaponTable[(size_t)ab.weaponIndex].name.c_str());
                    break;
                }
            }
        au.movedThisFrame = false;

        if (au.placedIndex < placedRef.size() && placedRef[au.placedIndex].isDroideka && au.life == AI_LIFE_ALIVE)
        {
            const PlacedInstance& rpi = placedRef[au.placedIndex];
            static float s_dekaClip[4] = { -1.0f, -1.0f, -1.0f, -1.0f };
            if (s_dekaClip[2] < 0.0f)
            {
                s_dekaClip[0] = 0.0f;
                s_dekaClip[1] = 1.00f; s_dekaClip[2] = 0.33f; s_dekaClip[3] = 3.33f;
                if (g_droidekaAnimBank != nullptr)
                {
                    uint32_t f = 0, b = 0;
                    if (g_droidekaAnimBank->GetAnimationMetadata(ANIM_DROIDEKA_FOLD, f, b) && f > 0) s_dekaClip[1] = AnimClipSec(f);
                    if (g_droidekaAnimBank->GetAnimationMetadata(ANIM_DROIDEKA_ROLL, f, b) && f > 0) s_dekaClip[2] = AnimClipSec(f);
                    if (g_droidekaAnimBank->GetAnimationMetadata(ANIM_DROIDEKA_UNFOLD, f, b) && f > 0) s_dekaClip[3] = AnimClipSec(f);
                }
                checkpointf("ROLLSTUCK clip lengths: fold %.3f roll %.3f unfold %.3f (s)", s_dekaClip[1], s_dekaClip[2], s_dekaClip[3]);
            }
            const int st = au.droidekaLocoState;
            if (st != au.rollDiagState)
            {

                if (au.rollDiagState >= 1 && au.rollDiagState <= 3 && au.rollDiagSec >= 5.0f && g_rollEpisodeLines < 60)
                {
                    ++g_rollEpisodeLines;
                    checkpointf("ROLLSTUCK episode: u%u t=%.2f state %d lasted %.2fs dist %.2fm",
                        (unsigned)n, g_aiClock, au.rollDiagState, au.rollDiagSec, au.rollDiagDist);
                }
                au.rollDiagState = st; au.rollDiagSec = 0.0f; au.rollDiagDist = 0.0f; au.rollDiagDone = 0;
                au.rollStillSec = 0.0f; au.rollStillLogged = 0;
                au.rollDiagX = rpi.position.m_X; au.rollDiagZ = rpi.position.m_Z;
                au.rollStillX = rpi.position.m_X; au.rollStillZ = rpi.position.m_Z;
            }
            else
            {
                au.rollDiagSec += deltaSec;
                const float mdx = rpi.position.m_X - au.rollDiagX, mdz = rpi.position.m_Z - au.rollDiagZ;
                au.rollDiagDist += sqrtf(mdx * mdx + mdz * mdz);
                au.rollDiagX = rpi.position.m_X; au.rollDiagZ = rpi.position.m_Z;
            }
            if (st >= 1 && st <= 3)
            {
                const float over = au.rollDiagSec - s_dekaClip[st];

                {
                    const float sdx = rpi.position.m_X - au.rollStillX, sdz = rpi.position.m_Z - au.rollStillZ;
                    if (sdx * sdx + sdz * sdz > 0.0025f)
                    { au.rollStillSec = 0.0f; au.rollStillX = rpi.position.m_X; au.rollStillZ = rpi.position.m_Z; }
                    else au.rollStillSec += deltaSec;
                    if (au.rollStillSec >= 1.0f && !au.rollStillLogged)
                    {
                        au.rollStillLogged = 1;
                        ++g_rollStillEpisodes;
                        if (g_rollStillLines < 60)
                        {
                            ++g_rollStillLines;
                            checkpointf("ROLLSTUCK in-place: u%u t=%.2f state %d still %.2fs (episode %.2fs, dist %.2fm) at (%.1f,%.1f,%.1f) why%d tgt%d combat%d goal %.1fm clip %08X",
                                (unsigned)n, g_aiClock, st, au.rollStillSec, au.rollDiagSec, au.rollDiagDist,
                                rpi.position.m_X, rpi.position.m_Y, rpi.position.m_Z, (int)au.why,
                                (int)au.haveCachedTarget, (int)DroidekaInCombat(au), au.goalD, (unsigned)au.animLastCRC);
                        }
                    }
                }
                if (!(au.rollDiagDone & 1) && over > 0.5f)
                {
                    au.rollDiagDone |= 1;
                    static uint32_t s_rollOverLines = 0;
                    if (s_rollOverLines < 300)
                    {
                        ++s_rollOverLines;
                        checkpointf("ROLLSTUCK state: unit %u state %d held %.2fs (clip %.2f, +%.2f over) dist %.2fm at (%.1f,%.1f,%.1f) why%d tgt%d combat%d goal %.1fm clip %08X",
                            (unsigned)n, st, au.rollDiagSec, s_dekaClip[st], over, au.rollDiagDist,
                            rpi.position.m_X, rpi.position.m_Y, rpi.position.m_Z, (int)au.why,
                            (int)au.haveCachedTarget, (int)DroidekaInCombat(au), au.goalD, (unsigned)au.animLastCRC);
                    }
                }
                if (!(au.rollDiagDone & 2) && au.rollDiagSec >= 10.0f)
                {
                    au.rollDiagDone |= 2;
                    static uint32_t s_roll10Lines = 0;
                    if (s_roll10Lines < 200)
                    {
                        ++s_roll10Lines;
                        checkpointf("ROLLSTUCK 10s: unit %u state %d for %.1fs dist %.2fm at (%.1f,%.1f,%.1f) why%d tgt%d combat%d goal %.1fm clip %08X",
                            (unsigned)n, st, au.rollDiagSec, au.rollDiagDist,
                            rpi.position.m_X, rpi.position.m_Y, rpi.position.m_Z, (int)au.why,
                            (int)au.haveCachedTarget, (int)DroidekaInCombat(au), au.goalD, (unsigned)au.animLastCRC);
                    }
                }
            }

            if (st != 2 && au.animLastCRC == ANIM_DROIDEKA_ROLL)
            {
                if (!au.rollLatchActive) { au.rollLatchActive = 1; au.rollLatchSec = 0.0f; au.rollLatchLogged = 0; }
                au.rollLatchSec += deltaSec;
                if (au.rollLatchSec > g_rollLatchMax) g_rollLatchMax = au.rollLatchSec;
                if (au.rollLatchSec > 0.5f && !au.rollLatchLogged)
                {
                    au.rollLatchLogged = 1;
                    ++g_rollLatchEpisodes;
                    if (g_rollLatchLines < 40)
                    {
                        ++g_rollLatchLines;
                        checkpointf("ROLLSTUCK latch: u%u t=%.2f state %d %.2fs in state, dist %.2fm pose %d poseSpeed %.2f locoTimer %.2f moving %d goal %.1fm why %d",
                            (unsigned)n, g_aiClock, st, au.rollDiagSec, au.rollDiagDist, au.currentPose, au.poseSpeed,
                            au.droidekaLocoTimer, (int)au.movedLastFrame, au.goalD, (int)au.why);
                    }
                }
            }
            else au.rollLatchActive = 0;
            if (g_aiClock - g_rollLatchSummaryT >= 30.0f)
            {
                g_rollLatchSummaryT = g_aiClock;
                checkpointf("ROLLSTUCK latch summary t=%.0f: episodes %u, longest %.2fs",
                    g_aiClock, (unsigned)g_rollLatchEpisodes, g_rollLatchMax);
            }
        }

        if (au.vehicle >= 0)
        {
            if (au.life == AI_LIFE_ALIVE) { const uint64_t tv = sceKernelGetProcessTimeWide(); UpdateAIVehicle(n, placedRef, uniqueModels, terrainData, deltaSec, playerPos); g_aiuVehUs += sceKernelGetProcessTimeWide() - tv; g_aiuVehUsWindow += sceKernelGetProcessTimeWide() - tv; }
            else
            {
                if ((size_t)au.vehicle < g_vehicles.size())
                {
                    VehicleState& rv = g_vehicles[(size_t)au.vehicle];
                    if (rv.pilot == (int)n) { rv.pilot = -1; rv.awake = true; }
                    for (int g = 0; g < MAX_GUN_SEATS; ++g) if (rv.gunner[g] == (int)n) rv.gunner[g] = -1;
                }
                au.vehicle = -1;
                placedRef[au.placedIndex].inVehicle = false;
                placedRef[au.placedIndex].riderVisible = false; placedRef[au.placedIndex].riderExposed = false;
            }
            continue;
        }

        AiLap(10);

        if (au.reloadTimer > 0.0f)
        {
            au.reloadTimer -= deltaSec;
            au.reloadAnimClock += deltaSec;
            if (au.reloadTimer <= 0.0f)
            {
                au.reloadTimer = 0.0f;
                au.reloadAnimClock = 0.0f;
                au.ammoInClip = -1;
            }
        }

        if (au.offenseBuffTimer > 0.0f && (au.offenseBuffTimer -= deltaSec) <= 0.0f) { au.offenseBuffTimer = 0.0f; au.offenseBuffMult = 1.0f; }
        if (au.defenseBuffTimer > 0.0f)
        {
            au.defenseBuffTimer -= deltaSec;
            if (au.defenseBuffTimer <= 0.0f) { au.defenseBuffTimer = 0.0f; au.defenseBuffMult = 1.0f; }
            else if (au.life == AI_LIFE_ALIVE && au.placedIndex < placedRef.size()) UnitFxKeep((uint32_t)n, placedRef[au.placedIndex].position, "com_sfx_buffed_defense");
        }
        if (au.regenTimer > 0.0f && au.life == AI_LIFE_ALIVE)
        {
            au.regenTimer -= deltaSec;
            au.health = fminf(au.maxHealth, au.health + au.regenRate * deltaSec);
            if (au.placedIndex < placedRef.size()) UnitFxKeep((uint32_t)n, placedRef[au.placedIndex].position, "com_sfx_buffed_regen");
            if (au.regenTimer <= 0.0f) { au.regenTimer = 0.0f; au.regenRate = 0.0f; }
        }
        if (au.poisonTimer > 0.0f && au.life == AI_LIFE_ALIVE)
        {
            au.poisonTimer -= deltaSec;
            if (au.placedIndex < placedRef.size()) UnitFxKeep((uint32_t)n, placedRef[au.placedIndex].position, "com_sfx_buffed_poison");
            ApplyDamageToAIUnit(n, au.poisonRate * deltaSec, placedRef);
            if (au.poisonTimer <= 0.0f) { au.poisonTimer = 0.0f; au.poisonRate = 0.0f; }
        }

        if (au.placedIndex < placedRef.size() && placedRef[au.placedIndex].isDroideka
            && au.life == AI_LIFE_ALIVE)
        {
            const bool inCombat = DroidekaInCombat(au);

            if (inCombat && (au.droidekaLocoState == 1 || au.droidekaLocoState == 2))
            {
                static uint32_t combatUnfoldDiag = 0;
                if (combatUnfoldDiag < 80)
                {
                    combatUnfoldDiag++;
                    const PlacedInstance& dpi = placedRef[au.placedIndex];
                    checkpointf("M314 droideka unit %u COMBAT-UNFOLD from state %d at (%.1f,%.1f,%.1f) target=%d fire=%d hint=%d shield=%d",
                        (unsigned)n, au.droidekaLocoState, dpi.position.m_X, dpi.position.m_Y, dpi.position.m_Z,
                        (int)au.haveCachedTarget, (int)(au.fireCooldown > 0.0f), (int)(au.hintNodeIdx >= 0), (int)au.shieldRaised);
                }
            }
            switch (au.droidekaLocoState)
            {
            case 1:
                if (inCombat) { au.droidekaLocoState = 3; au.droidekaLocoTimer = REAL_DROIDEKA_UNFOLD_TIME; break; }
                au.droidekaLocoTimer -= deltaSec;
                if (au.droidekaLocoTimer <= 0.0f) { au.droidekaLocoState = 2; au.droidekaLocoTimer = 0.0f; }
                break;
            case 2:
                if (inCombat) { au.droidekaLocoState = 3; au.droidekaLocoTimer = REAL_DROIDEKA_UNFOLD_TIME; }
                break;
            case 3:
                au.droidekaLocoTimer -= deltaSec;
                if (au.droidekaLocoTimer <= 0.0f) { au.droidekaLocoState = 0; au.droidekaLocoTimer = 0.0f; }
                break;
            default:
                if (au.droidekaRollCooldown > 0.0f) au.droidekaRollCooldown -= deltaSec;
                break;
            }
        }

        if (au.placedIndex < placedRef.size() && au.life == AI_LIFE_ALIVE)
        {
            const int swIdx = placedRef[au.placedIndex].shieldWeaponIdx;
            if (swIdx >= 0 && (size_t)swIdx < g_weaponTable.size())
            {
                const WeaponStats& sw = g_weaponTable[(size_t)swIdx];
                if (!au.shieldPoolInit) { au.shieldPool = sw.shieldMax; au.shieldPoolInit = true; }

                if (au.fireCooldown > 0.0f) au.shieldEngageHold = 2.0f;
                else if (au.shieldEngageHold > 0.0f) au.shieldEngageHold -= deltaSec;
                const bool upright  = (au.droidekaLocoState == 0);
                const bool engaging = (au.shieldEngageHold > 0.0f);
                const bool wasRaised = au.shieldRaised;
                if (au.shieldRaised)
                {
                    if (!upright || !engaging) au.shieldRaised = false;
                }
                else if (upright && engaging && au.shieldPool >= sw.shieldMax * 0.25f)
                {
                    au.shieldRaised = true;
                }

                au.shieldPool += (au.shieldRaised ? sw.shieldAddOn : sw.shieldAddOff) * deltaSec;
                if (au.shieldPool > sw.shieldMax) au.shieldPool = sw.shieldMax;
                if (au.shieldPool <= 0.0f) { au.shieldPool = 0.0f; au.shieldRaised = false; }

                if (au.shieldRaised != wasRaised)
                {
                    static uint32_t shieldDiag = 0;
                    if (shieldDiag < 120)
                    {
                        shieldDiag++;
                        checkpointf("M312 shield %s: unit %u pool=%.0f/%.0f upright=%d",
                            au.shieldRaised ? "RAISED" : "lowered", (unsigned)n,
                            au.shieldPool, sw.shieldMax, (int)upright);
                    }
                }
            }
        }

        if (au.pushVelX != 0.0f || au.pushVelY != 0.0f || au.pushVelZ != 0.0f)
        {
            IntegrateAIBlastPush(au, placedRef[au.placedIndex], deltaSec,
                                 terrainData, uniqueModels, placedRef);
        }

        if (au.thrown && au.thrownPhase == 1) au.thrownTimer += deltaSec;
        if (au.thrown && au.life == AI_LIFE_ALIVE && au.thrownPhase >= 2)
        {
            au.thrownTimer += deltaSec;
            if (au.thrownPhase == 2 && au.thrownTimer >= THROWN_REST_SEC) { au.thrownPhase = 3; au.thrownTimer = 0.0f; }
            else if (au.thrownPhase == 3 && au.thrownTimer >= ThrownGetupSec(au.thrownFront))
            { au.thrown = false; au.thrownPhase = 0; au.thrownTimer = 0.0f; }
        }

        if (au.life == AI_LIFE_DYING && au.thrown && (au.thrownPhase != 1 || (au.pushVelX == 0.0f && au.pushVelY == 0.0f && au.pushVelZ == 0.0f)))
        { au.thrown = false; au.thrownPhase = 0; }
        if (au.life == AI_LIFE_DYING && au.thrown)
        {

            au.currentPose = AIPOSE_THROWN;
            continue;
        }
        if (au.life == AI_LIFE_DYING)
        {
            PlacedInstance& dpi = placedRef[au.placedIndex];
            au.deathAnimTimer -= deltaSec;
            auto dvit = g_aiPoseVariants.find(au.baseModelIndex);
            if (dvit != g_aiPoseVariants.end())
            {

                const size_t before = dpi.modelIndex;
                if (au.ownModelIndex != (size_t)-1) dpi.modelIndex = au.ownModelIndex;
                else                                dpi.modelIndex = dvit->second[AIPOSE_DEATH];
                au.currentPose = AIPOSE_DEATH;

                if (au.deathTraceFrames < 8)
                {
                    au.deathTraceFrames++;
                    const ModelData& tmd = uniqueModels[dpi.modelIndex];
                    checkpointf("M126 trace f%d: model=%u frame=%u clock=%.2f timer=%.1f life=%d",
                        au.deathTraceFrames, (unsigned)dpi.modelIndex,
                        (unsigned)tmd.lastSkinnedFrame, tmd.animLocalClock,
                        au.deathAnimTimer, (int)au.life);
                }
                if (!au.deathPoseLogged)
                {
                    au.deathPoseLogged = true;
                    const ModelData& dmd = uniqueModels[dpi.modelIndex];
                    checkpointf("MILESTONE 123 - death pose: base=%u was=%u now=%u frame=%u clock=%.2f frames=%u loops=%d",
                        (unsigned)au.baseModelIndex, (unsigned)before, (unsigned)dpi.modelIndex,
                        (unsigned)dmd.lastSkinnedFrame, dmd.animLocalClock,
                        (unsigned)dmd.animFrameCount, (int)dmd.animLoopsFlag);
                }
            }
            if (au.deathAnimTimer <= 0.0f && IsCapturingTeam(au.homeTeam) && !RetailSpawnGate(au)) continue;
            if (au.deathAnimTimer <= 0.0f)
            {

                au.life = AI_LIFE_RESPAWNING;
                dpi.team = -1;
                dpi.position.m_Y = -10000.0f;
                RespawnAIUnit(n, placedRef);
            }
            continue;
        }
        if (au.waveSpawn)
        {
            if (au.deathAnimTimer > 0.0f) au.deathAnimTimer -= deltaSec;
            else if (RetailSpawnGate(au)) RespawnAIUnit(n, placedRef);
            continue;
        }

        if (au.thrown && au.life == AI_LIFE_ALIVE)
        {

            continue;
        }
        if (au.jumpLeg)
        {
            PlacedInstance& jp = placedRef[au.placedIndex];
            bool landed = (au.life != AI_LIFE_ALIVE);
            if (!landed)
            {
                const float prevY = jp.position.m_Y;
                au.jumpT += deltaSec;
                const float f = fminf(1.0f, au.jumpT / au.jumpDur);
                jp.position.m_X = au.jumpFrom.m_X + (au.jumpTo.m_X - au.jumpFrom.m_X) * f;
                jp.position.m_Z = au.jumpFrom.m_Z + (au.jumpTo.m_Z - au.jumpFrom.m_Z) * f;
                jp.position.m_Y = au.jumpFrom.m_Y + au.jumpVy * au.jumpT - 4.905f * au.jumpT * au.jumpT;

                const bool falling = (au.jumpVy - 9.81f * au.jumpT) < 0.0f;
                float gy; Vector3 gn;

                const float landRef = au.jumpTo.m_Y + 0.6f;
                if (f >= 0.8f && falling && GetCombinedGroundHeightAt(terrainData, uniqueModels, placedRef, jp.position.m_X, landRef, jp.position.m_Z,
                                                                     au.terrainHint, gy, gn, au.placedIndex) && jp.position.m_Y <= gy)
                { jp.position.m_Y = gy; landed = true; }
                else if (au.jumpT > au.jumpDur + 3.0f)
                {
                    float ty; Vector3 tn;
                    if (GetTerrainHeightAt(terrainData, jp.position.m_X, jp.position.m_Z, ty, tn, au.terrainHint)) jp.position.m_Y = ty;
                    landed = true;
                }
            }
            if (landed)
            {
                au.jumpLeg = false; au.localPathValid = false;

                const bool shortLanding = fabsf(jp.position.m_Y - au.jumpTo.m_Y) > 2.0f;
                if (shortLanding)
                {
                    au.jumpArcUntil = g_aiClock + 8.0f;
                    ++g_aiJumpShorts;
                }
                checkpointf("M487 jump landed: unit %u at (%.1f, %.1f, %.1f) after %.2f s%s", (unsigned)n, jp.position.m_X, jp.position.m_Y, jp.position.m_Z, au.jumpT,
                            shortLanding ? " - SHORT of the far hub, arc held off" : "");
            }
            else continue;
        }
        if (au.respawnTimer > 0.0f)
        {
            au.respawnTimer -= deltaSec;
            if (au.respawnTimer <= 0.0f) RespawnAIUnit(n, placedRef);
            continue;
        }
        PlacedInstance& pi = placedRef[au.placedIndex];
        AiLap(11);
        if (pi.team < 0) continue;

        const WeaponStats* dmW = (pi.weaponIndex >= 0 && (size_t)pi.weaponIndex < g_weaponTable.size()) ? &g_weaponTable[(size_t)pi.weaponIndex] : nullptr;
        const bool dmMelee = !au.flyer && dmW != nullptr && dmW->isMelee && !IsCapturingTeam(pi.team) && !TeamHasConquestGoal(pi.team)
                             && au.life == AI_LIFE_ALIVE && au.haveCachedTarget;
        if (!IsCapturingTeam(pi.team) && (au.flyer || !TeamHasConquestGoal(pi.team)) && !dmMelee)
        {
            if (au.flyer && au.life == AI_LIFE_ALIVE) UpdateLocalFlyer(n, au, pi, placedRef, uniqueModels, terrainData, deltaSec, playerPos);
            continue;
        }

        if (!TeamHasConquestGoal(pi.team) && !dmMelee) { g_aiDiagNoGoal++; continue; }

        if (au.actionTimer > 0.0f)
        {
            const float fx = au.actionFacePos.m_X - pi.position.m_X, fz = au.actionFacePos.m_Z - pi.position.m_Z;
            if (fx * fx + fz * fz > 0.01f) { au.wantYaw = atan2f(-fx, -fz); au.haveWantYaw = true; au.wantSrc = 2;   }
            continue;
        }

        bool supportSteer = false;
        float supportGX = 0.0f, supportGZ = 0.0f;
        if (au.supportAlly != -2)
        {
            Vector3 allyPos; bool allyOk = false;
            if (au.supportAlly == -1) { allyPos = playerPos; allyOk = g_playerAliveForAI && g_playerVehicle < 0; }
            else if ((size_t)au.supportAlly < g_aiUnits.size())
            {
                const AIUnitState& a = g_aiUnits[(size_t)au.supportAlly];
                if (a.life == AI_LIFE_ALIVE && a.placedIndex < placedRef.size()) { allyPos = placedRef[a.placedIndex].position; allyOk = true; }
            }
            au.supportTimer -= deltaSec;
            const float ax = allyPos.m_X - pi.position.m_X, az = allyPos.m_Z - pi.position.m_Z;
            const float ad = sqrtf(ax * ax + az * az);
            if (!allyOk || au.supportTimer <= 0.0f || ad > 30.0f)
            {
                au.supportAlly = -2;
            }
            else if (ad <= 2.5f)
            {
                int wi = -1;
                for (const AIUnitState::Ability& ab : au.abilities) if (ab.kind == ABIL_DISPENSER && ab.reserve > 0) { wi = ab.weaponIndex; break; }
                au.supportAlly = -2;
                if (wi >= 0)
                {

                    const Vector3 toss(ax / fmaxf(ad, 0.01f) * 0.8f, 0.6f, az / fmaxf(ad, 0.01f) * 0.8f);
                    StartAIAction(au, ABIL_DISPENSER, wi,  false, toss, allyPos);
                    au.wantYaw = atan2f(-ax, -az); au.haveWantYaw = true; au.wantSrc = 3;
                    continue;
                }
            }
            else { supportSteer = true; supportGX = allyPos.m_X; supportGZ = allyPos.m_Z; }
        }

        bool mayEnterVehicles = true;
        { auto lit = g_unitClassLoadout.find(pi.unitClass); if (lit != g_unitClassLoadout.end() && lit->second.noEnterVehicles) mayEnterVehicles = false; }
        if (au.life == AI_LIFE_ALIVE && au.supportAlly == -2 && au.vehicleClaim < 0 && mayEnterVehicles)
        {
            au.vehicleThinkSec -= deltaSec;
            if (au.vehicleThinkSec <= 0.0f)
            {
                au.vehicleThinkSec = 1.0f + (float)(rand() % 100) * 0.01f;
                int best = -1; float bestD = 50.0f;
                for (size_t vi = 0; vi < g_vehicles.size(); ++vi)
                {
                    const VehicleState& v = g_vehicles[vi];

                    if (v.isTurret)
                    {
                        if (!v.alive || v.claimedBy != -1 || (v.team != 0 && v.team != pi.team)) continue;
                        if (g_aiClock < v.aiNoClaimUntil) continue;
                        auto tdit = g_vehicleClassDefs.find(v.cls);
                        if (tdit == g_vehicleClassDefs.end() || FirstFreeGunSeat(v, tdit->second) == 0) continue;

                        if (!au.haveCachedTarget || v.placedIndex >= placedRef.size()) continue;
                        {
                            const VehicleClassDef::GunSeat& ags = tdit->second.gunSeats[(size_t)(FirstFreeGunSeat(v, tdit->second) - 1)];
                            if (ags.YawLimited())
                            {
                                const Vector3& tp0 = placedRef[v.placedIndex].position;
                                float rel = atan2f(-(au.cachedTargetPos.m_X - tp0.m_X), -(au.cachedTargetPos.m_Z - tp0.m_Z)) - v.yaw - ags.RestYawRad();
                                while (rel > 3.14159265f) rel -= 6.2831853f;
                                while (rel < -3.14159265f) rel += 6.2831853f;
                                if (fabsf(rel) > 0.5f * (ags.yawMax - ags.yawMin) * 0.01745329f) continue;
                            }
                        }
                        const float tgap = VehicleBoardingGap(vi, pi.position, uniqueModels, placedRef);
                        if (tgap < 50.0f && tgap < bestD) { bestD = tgap; best = (int)vi; }
                        continue;
                    }
                    if (!v.alive || v.claimedBy != -1 || v.team != pi.team) continue;
                    auto dit = g_vehicleClassDefs.find(v.cls);
                    if (dit == g_vehicleClassDefs.end()) continue;

                    const bool reserved = v.reservedForPlayer && v.team == g_playerTeam;
                    const bool driverFree = v.pilot == -1 && !reserved;
                    const bool gunnerFree = FirstFreeGunSeat(v, dit->second) > 0 && v.pilot != -1;
                    if (!driverFree && !gunnerFree) continue;
                    const float gap = VehicleBoardingGap(vi, pi.position, uniqueModels, placedRef);
                    if (gap < 40.0f && gap < bestD) { bestD = gap; best = (int)vi; }
                }
                if (best >= 0)
                {
                    au.vehicleClaim = best; au.vehicleClaimSec = 0.0f;
                    au.claimBestGap = 1e9f; au.claimStallSec = 0.0f;
                    g_vehicles[(size_t)best].claimedBy = (int)n;
                    checkpointf("M438 AI unit %u [%s] claims vehicle #%d \"%s\" (%.1fm)", (unsigned)n, pi.unitClass.c_str(), best, g_vehicles[(size_t)best].cls.c_str(), bestD);
                }
            }
        }
        if (au.vehicleClaim >= 0 && !supportSteer)
        {
            VehicleState& v = g_vehicles[(size_t)au.vehicleClaim];
            au.vehicleClaimSec += deltaSec;
            const float gap = VehicleBoardingGap((size_t)au.vehicleClaim, pi.position, uniqueModels, placedRef);
            auto cdit = g_vehicleClassDefs.find(v.cls);
            const bool driverFree = v.pilot == -1 && !v.isTurret;
            const int freeGun = (cdit != g_vehicleClassDefs.end()) ? FirstFreeGunSeat(v, cdit->second) : 0;
            const bool gunnerFree = freeGun > 0;
            const bool teamOk = v.isTurret ? (v.team == 0 || v.team == pi.team) : (v.team == pi.team);

            if (gap < au.claimBestGap - 0.5f) { au.claimBestGap = gap; au.claimStallSec = 0.0f; }
            else au.claimStallSec += deltaSec;
            const bool stalled = au.claimStallSec > 6.0f;
            if (!v.alive || (!driverFree && !gunnerFree) || !teamOk || au.vehicleClaimSec > 20.0f || stalled || gap > (v.isTurret ? 50.0f : 40.0f) || au.life != AI_LIFE_ALIVE)
            {
                if (v.isTurret && v.alive && (stalled || au.vehicleClaimSec > 20.0f) && gap > 1.0f)
                {
                    v.aiNoClaimUntil = g_aiClock + 120.0f;
                    checkpointf("M481 AI unit %u gave up on turret #%d \"%s\" %.1fm short after %.0fs - no AI claims it for 120s",
                                (unsigned)n, au.vehicleClaim, v.cls.c_str(), gap, au.vehicleClaimSec);
                }
                if (v.claimedBy == (int)n) v.claimedBy = -1;
                au.vehicleClaim = -1; au.vehicleThinkSec = 10.0f;
            }
            else if (gap <= 1.0f)
            {
                if (driverFree) { v.pilot = (int)n; au.vehicleSeat = 0; } else { v.gunner[freeGun - 1] = (int)n; au.vehicleSeat = freeGun; }
                if (v.isTurret) { v.team = pi.team; au.turretWaitSec = 0.0f; au.boardFromPos = pi.position; }
                v.claimedBy = -1; v.awake = true; v.decaying = false; v.enemyIdleSec = 0.0f;
                au.vehicle = au.vehicleClaim; au.vehicleClaim = -1;
                au.vehPath.clear(); au.vehPathCp = -1; au.vehStuckSec = au.vehReverseSec = 0.0f;
                pi.inVehicle = true;
                checkpointf("M438 AI unit %u [%s] BOARDED vehicle #%d \"%s\" as %s (seat %d)", (unsigned)n, pi.unitClass.c_str(), au.vehicle, v.cls.c_str(), au.vehicleSeat ? "gunner" : "driver", au.vehicleSeat);
                continue;
            }
            else
            {
                const Vector3& vp = placedRef[v.placedIndex].position;
                supportSteer = true; supportGX = vp.m_X; supportGZ = vp.m_Z;
            }
        }

        AiLap(12);

        const bool validCp = au.cachedTargetCpIndex >= 0 && au.cachedTargetCpIndex < (int)g_commandPosts.size();
        if (validCp && au.targetIsDefend && g_commandPosts[(size_t)au.cachedTargetCpIndex].team != pi.team)
            au.targetIsDefend = false;

        const bool friendlyNoDef = validCp && g_commandPosts[(size_t)au.cachedTargetCpIndex].team == pi.team
            && CpValue(g_commandPosts[(size_t)au.cachedTargetCpIndex].valueDef, FactionSuffixForTeam(pi.team)) <= 0.0f;
        bool needsReeval = (!validCp || friendlyNoDef || au.forceRepick) && !dmMelee;
        if (needsReeval)
        {
            bool defend = false;
            const int teamIdx = (pi.team >= 0 && pi.team < 8) ? pi.team : 0;
            std::vector<int> assigned = s_cpAssigned[teamIdx];
            if (validCp && assigned[(size_t)au.cachedTargetCpIndex] > 0) --assigned[(size_t)au.cachedTargetCpIndex];
            const int pick = ChooseConquestPost(pi.team, pi.position, validCp ? au.cachedTargetCpIndex : -1,
                                                assigned, s_cpEnemiesNear[teamIdx], s_teamAlive[teamIdx], defend);
            au.forceRepick = false; au.apArrived = false;
            if (pick >= 0)
            {
                if (validCp) --s_cpAssigned[teamIdx][(size_t)au.cachedTargetCpIndex];
                ++s_cpAssigned[teamIdx][(size_t)pick];
                au.cachedTargetCpIndex = pick;
                au.targetIsDefend = defend;
            }
        }
        const CommandPostState* target = dmMelee ? ChooseNearestFriendlyCP(pi.team, pi.position)
            : (au.cachedTargetCpIndex >= 0 && au.cachedTargetCpIndex < (int)g_commandPosts.size())
            ? &g_commandPosts[(size_t)au.cachedTargetCpIndex] : nullptr;
        if (target == nullptr) continue;

        bool followGoal = false;
        Vector3 followPos(0.0f, 0.0f, 0.0f);
        if (au.follower)
        {
            const float ldx = playerPos.m_X - pi.position.m_X, ldy = playerPos.m_Y - pi.position.m_Y, ldz = playerPos.m_Z - pi.position.m_Z;
            const float ld = sqrtf(ldx * ldx + ldy * ldy + ldz * ldz);
            if (!g_playerAliveForAI) SquadReleaseUnit((int)n, "the leader died");
            else if (g_playerVehicle >= 0) SquadReleaseUnit((int)n, "the leader boarded a vehicle (boarding is not ported)");
            else
            {

                if (ld > 20.0f) au.followAwaySec += deltaSec; else au.followAwaySec = 0.0f;
                if (au.followAwaySec > 10.0f) SquadReleaseUnit((int)n, "the leader was farther than 20 m for 10 s");
            }
        }
        if (au.follower)
        {
            const float ldx = playerPos.m_X - pi.position.m_X, ldz = playerPos.m_Z - pi.position.m_Z;
            const float ldist = sqrtf(ldx * ldx + ldz * ldz);
            au.followRepick -= deltaSec;
            if (au.followState == 3 && ldist <= 10.0f)
            {
                const float fx = g_aiPlayerFwdX, fz = g_aiPlayerFwdZ;
                au.followTX = playerPos.m_X + fx * (((float)rand() / (float)RAND_MAX - 0.5f) * 6.0f)
                                           + fz * (((float)rand() / (float)RAND_MAX - 0.5f) * 6.0f);
                au.followTZ = playerPos.m_Z + fz * (((float)rand() / (float)RAND_MAX - 0.5f) * 6.0f)
                                           - fx * (((float)rand() / (float)RAND_MAX - 0.5f) * 6.0f);
                const float sx = au.followTX - playerPos.m_X, sz = au.followTZ - playerPos.m_Z;
                if (sx * sx + sz * sz < 1.0f) { au.followTX = playerPos.m_X + 1.0f; au.followTZ = playerPos.m_Z; }
                au.followState = 4;
            }
            else if (au.followState == 4 && ldist > 9.0f) au.followState = 3;
            followGoal = true;
            followPos = (au.followState == 4) ? Vector3(au.followTX, playerPos.m_Y, au.followTZ) : playerPos;
        }

        Vector3 approachPos = followGoal ? followPos
                            : (target->hasCaptureRegion ? target->captureRegionPos : target->position);
        if (!followGoal && target->hasCaptureRegion)
        {
            const int tIdx = (int)(target - g_commandPosts.data());
            if (au.cpSpotFor != tIdx)
            {
                au.cpSpotFor = tIdx;
                au.cpSpotX = approachPos.m_X; au.cpSpotZ = approachPos.m_Z;
                const float rad = 0.6f * fminf(fabsf(target->captureRegionSize.m_X), fabsf(target->captureRegionSize.m_Z));

                const float floorY = target->position.m_Y;
                for (int tries = 0; tries < 8; ++tries)
                {
                    const float a = 6.2831853f * ((float)rand() / (float)RAND_MAX);
                    const float r = rad * sqrtf((float)rand() / (float)RAND_MAX);
                    const float sx = approachPos.m_X + cosf(a) * r, sz = approachPos.m_Z + sinf(a) * r;
                    if (PointBlockedByBarrier(sx, sz, PLAYER_COLLISION_RADIUS)) continue;
                    const float cdx = sx - target->position.m_X, cdz = sz - target->position.m_Z;
                    if (cdx * cdx + cdz * cdz < 1.5f * 1.5f) continue;
                    float hd; Vector3 hp;
                    if (FireRayHitTest(Vector3(sx, floorY + 0.3f, sz), Vector3(0.0f, 1.0f, 0.0f), 1.9f,
                                       uniqueModels, placedRef, hd, hp, au.placedIndex)) continue;
                    const float ldx = sx - approachPos.m_X, ldz = sz - approachPos.m_Z;
                    const float ll = sqrtf(ldx * ldx + ldz * ldz);

                    if (ll > 1.6f && FireRayHitTest(Vector3(approachPos.m_X + ldx / ll * 1.5f, floorY + 1.0f, approachPos.m_Z + ldz / ll * 1.5f),
                                                    Vector3(ldx / ll, 0.0f, ldz / ll), ll - 1.5f,
                                                    uniqueModels, placedRef, hd, hp, au.placedIndex)) continue;
                    au.cpSpotX = sx; au.cpSpotZ = sz;
                    break;
                }
            }
            approachPos.m_X = au.cpSpotX; approachPos.m_Z = au.cpSpotZ;
        }

        const bool snipeRoute = !followGoal && au.hintKind == 1 && !au.hintAt && au.hintNodeIdx >= 0 && (size_t)au.hintNodeIdx < g_hintNodes.size();
        if (snipeRoute) approachPos = g_hintNodes[(size_t)au.hintNodeIdx].position;

        const bool noiseRoute = !followGoal && !snipeRoute && au.noiseSec > 0.0f && !au.haveCachedTarget && au.lookSec <= 0.0f;
        if (noiseRoute) approachPos = Vector3(au.noiseX, pi.position.m_Y, au.noiseZ);

        const int routeGoalKey = followGoal ? 300000 : snipeRoute ? 100000 + au.hintNodeIdx : noiseRoute ? 200000 + (au.noiseSerial & 0xffff) : (int)(target - g_commandPosts.data());

        float dx = approachPos.m_X - pi.position.m_X;
        float dz = approachPos.m_Z - pi.position.m_Z;
        float dist = sqrtf(dx * dx + dz * dz);

        {
            static const bool s_noAutoFollow = getenv("SWBF2_NOAUTOFOLLOW") != nullptr;
            au.autoFollowSec -= deltaSec;
            if (!followGoal && !au.follower && !g_squadOldDbg && !s_noAutoFollow && au.autoFollowSec <= 0.0f)
            {
                au.autoFollowSec = 1.0f;
                const float pdx = playerPos.m_X - approachPos.m_X, pdz = playerPos.m_Z - approachPos.m_Z;
                if (g_playerAliveForAI && g_playerVehicle < 0 && au.vehicle < 0 && pi.team >= 1 && pi.team == g_playerTeamForScripts
                    && dist * dist >= 22500.0f && pdx * pdx + pdz * pdz <= 2500.0f
                    && SquadFollowerCount() < g_squadCap)
                {
                    au.follower = true; au.followState = 3; au.followAwaySec = 0.0f; au.followRepick = 0.0f;
                    au.navPath.clear(); au.navRepathTimer = 0.0f; au.routeDoneGoal = -1;
                    if (au.hintNodeIdx >= 0 && au.hintNodeIdx < (int)g_hintNodes.size() && g_hintNodes[(size_t)au.hintNodeIdx].reservedBy == (int)n)
                        g_hintNodes[(size_t)au.hintNodeIdx].reservedBy = -1;
                    au.hintNodeIdx = -1; au.hintKind = 0; au.hintAt = false; au.hintHoldTime = 0.0f;
                    ++g_autoFollowJoins;
                    checkpointf("M17 FOLLOWAUTO: unit %u \"%s\" joins the player on its own (dest %.0f m away, player %.0f m from it; joins %u)",
                                (unsigned)n, pi.unitClass.c_str(), dist, sqrtf(pdx * pdx + pdz * pdz), g_autoFollowJoins);
                }
            }
        }

        const float STOP_RADIUS = 1.5f;

        auto releaseHint = [&]() {
            if (au.hintNodeIdx >= 0 && au.hintNodeIdx < (int)g_hintNodes.size() && g_hintNodes[au.hintNodeIdx].reservedBy == (int)n)
                g_hintNodes[au.hintNodeIdx].reservedBy = -1;
            au.hintNodeIdx = -1; au.hintKind = 0; au.hintAt = false; au.hintHoldTime = 0.0f;
        };
        auto r01 = []() { return (float)rand() / (float)RAND_MAX; };
        const WeaponStats* hw = (pi.weaponIndex >= 0 && (size_t)pi.weaponIndex < g_weaponTable.size()) ? &g_weaponTable[(size_t)pi.weaponIndex] : nullptr;
        const float hwRange = hw && hw->maxRange > 0.0f ? hw->maxRange : 60.0f, hwOpt = hw && hw->optimalRange > 0.0f ? hw->optimalRange : 30.0f;
        const float hwInner = fminf(hwOpt, (hw ? hw->minRange : 0.0f) + 3.0f);
        auto coverOk = [&](const HintNodeData& hn) {
            if (hn.type != HINT_COVER) return false;
            const float R = fminf(40.0f, hwRange);
            const float hx = hn.position.m_X, hz = hn.position.m_Z, tx = au.cachedTargetPos.m_X, tz = au.cachedTargetPos.m_Z;
            if (fabsf(hx - pi.position.m_X) > R || fabsf(hz - pi.position.m_Z) > R) return false;
            if ((hx - tx) * (tx - pi.position.m_X) + (hz - tz) * (tz - pi.position.m_Z) >= 0.0f) return false;
            const float ht = sqrtf((tx - hx) * (tx - hx) + (tz - hz) * (tz - hz));
            if (ht <= hwInner || ht >= R) return false;
            return (hn.forward.m_X * (tx - hx) + hn.forward.m_Z * (tz - hz)) / ht > 0.5f;
        };
        au.hintReevalTimer -= deltaSec;
        if (au.hintKind == 1 && au.haveCachedTarget) { releaseHint(); au.hintReevalTimer = 8.0f + 4.0f * r01(); }
        if (au.hintKind == 2 && !au.haveCachedTarget) releaseHint();
        if (au.hintKind == 1 && au.hintAt && (au.hintHoldTime += deltaSec) > au.hintStandSec) { releaseHint(); au.hintReevalTimer = 8.0f + 4.0f * r01(); }
        const bool isScout = [&]() { auto it = g_classIsScout.find(pi.unitClass); return it != g_classIsScout.end() && it->second; }();
        if (au.hintKind == 0 && !au.haveCachedTarget && isScout && au.hintReevalTimer <= 0.0f && !g_hintNodes.empty() && !supportSteer)
        {
            au.hintReevalTimer = 8.0f + 4.0f * r01();
            std::vector<std::pair<float, int>> cand;
            for (size_t hi = 0; hi < g_hintNodes.size(); ++hi)
            {
                const HintNodeData& hn = g_hintNodes[hi];
                if (hn.type != HINT_SNIPE || hn.reservedBy >= 0) continue;
                if ((int)hi == au.hintFailIdx && g_aiClock < au.hintFailUntil) continue;
                if (fabsf(hn.position.m_Y - pi.position.m_Y) > 2.5f) continue;
                const float hx = hn.position.m_X - pi.position.m_X, hz = hn.position.m_Z - pi.position.m_Z;
                if (fabsf(hx) > 100.0f || fabsf(hz) > 100.0f) continue;
                cand.push_back({ hx * hx + hz * hz, (int)hi });
            }
            std::sort(cand.begin(), cand.end());
            if (cand.size() > 20) cand.resize(20);
            const int myComp = NavComponentOf(pi.position);
            for (size_t ci = 0; ci < cand.size() && ci < 11; ++ci)
            {
                const HintNodeData& hn = g_hintNodes[(size_t)cand[ci].second];
                if (myComp >= 0) { const int c = NavComponentOf(hn.position); if (c >= 0 && c != myComp) continue; }
                bool enemyNear = false;
                const float ax = pi.position.m_X, az = pi.position.m_Z, bx = hn.position.m_X - ax, bz = hn.position.m_Z - az, bl2 = bx * bx + bz * bz;
                for (const AIUnitState& o : g_aiUnits)
                {
                    if (o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
                    const PlacedInstance& op = placedRef[o.placedIndex];
                    if (op.team <= 0 || !IsHostile(pi.team, op.team)) continue;
                    float t = bl2 > 1e-6f ? ((op.position.m_X - ax) * bx + (op.position.m_Z - az) * bz) / bl2 : 0.0f;
                    t = fminf(1.0f, fmaxf(0.0f, t));
                    const float ex = ax + bx * t - op.position.m_X, ez = az + bz * t - op.position.m_Z;
                    if (ex * ex + ez * ez < 144.0f) { enemyNear = true; break; }
                }
                if (enemyNear) continue;
                ++g_hintPicks;
                au.hintNodeIdx = cand[ci].second; au.hintKind = 1; au.hintAt = false; au.hintHoldTime = 0.0f; au.hintBestD = 1e9f; au.hintStall = 0.0f;
                au.hintStandSec = 60.0f + 60.0f * r01();
                g_hintNodes[(size_t)au.hintNodeIdx].reservedBy = (int)n;
                break;
            }
        }
        else if (au.haveCachedTarget && au.hintReevalTimer <= 0.0f && !g_hintNodes.empty() && !supportSteer && !pi.isDroideka
                 && !(hw != nullptr && hw->isMelee))
        {
            au.hintReevalTimer = (float)(2 + rand() % 4);
            if (au.hintKind == 2 && !coverOk(g_hintNodes[(size_t)au.hintNodeIdx])) releaseHint();
            if (au.hintKind == 0 && rand() % 2 == 0)
            {
                int best = -1; float bestS = 1e30f;
                for (size_t hi = 0; hi < g_hintNodes.size(); ++hi)
                {
                    const HintNodeData& hn = g_hintNodes[hi];
                    if ((hn.reservedBy >= 0 && hn.reservedBy != (int)n) || !coverOk(hn)) continue;
                    const float mx = hn.position.m_X - pi.position.m_X, mz = hn.position.m_Z - pi.position.m_Z;
                    const float tx = hn.position.m_X - au.cachedTargetPos.m_X, tz = hn.position.m_Z - au.cachedTargetPos.m_Z;
                    const float sc = 2.25f * (mx * mx + mz * mz) + tx * tx + tz * tz;
                    if (sc < bestS) { bestS = sc; best = (int)hi; }
                }
                if (best >= 0) { au.hintNodeIdx = best; au.hintKind = 2; au.hintAt = false; au.hintHoldTime = 0.0f; au.hintBestD = 1e9f; au.hintStall = 0.0f; g_hintNodes[(size_t)best].reservedBy = (int)n; }
            }
        }

        AiLap(13);

        if (au.advanceSec > 0.0f) au.advanceSec -= deltaSec;

        const bool captureKeepsGoing = AiRulesMode() == AI_RULES_PC && CaptureAgentIgnoresCombat(au, placedRef, playerPos);

        bool cmCircling = false;

        const bool followClosing = followGoal && au.followState == 3;
        if (au.hintNodeIdx < 0 && au.haveCachedTarget && !supportSteer && !captureKeepsGoing && !followClosing)
        {
            if (au.styleN < 0) au.styleN = rand() % 101;
            au.apArrived = false;
            const WeaponStats* cw = (pi.weaponIndex >= 0 && (size_t)pi.weaponIndex < g_weaponTable.size()) ? &g_weaponTable[(size_t)pi.weaponIndex] : nullptr;
            const float wRange = cw && cw->maxRange > 0.0f ? cw->maxRange : 60.0f;
            const float wOpt = cw && cw->optimalRange > 0.0f ? cw->optimalRange : 30.0f;
            const float wMin = cw ? cw->minRange : 0.0f;
            const float fx = au.cachedTargetPos.m_X - pi.position.m_X, fz = au.cachedTargetPos.m_Z - pi.position.m_Z;
            const float fd = sqrtf(fx * fx + fz * fz);

            const int mode = (cw != nullptr && cw->isMelee) ? 7 : isScout ? (fd <= wRange ? 2 : 0) : AiEngageMode(au.styleN, fd, wRange);
            if (mode != au.cmMode) { au.cmMode = mode; au.cmHave = false; au.cmPause = 0.0f; }
            if (au.cmMode == 7)
            {

                if (fd <= wOpt)
                {
                    if (fabsf(fx) > 0.0001f || fabsf(fz) > 0.0001f) { au.wantYaw = atan2f(-fx, -fz); au.haveWantYaw = true; au.wantSrc = 4; }
                    g_aiDiagEngaging++; au.why = 6;
                    continue;
                }
                const float leg = fminf(fd, 25.0f) / fmaxf(fd, 0.001f);
                au.cmTX = pi.position.m_X + fx * leg; au.cmTZ = pi.position.m_Z + fz * leg; au.cmHave = true; au.cmPause = 0.0f;
                g_aiDiagEngaging++; cmCircling = true;
            }
            if (au.cmMode == 3)
            {
                au.cmThink -= deltaSec;
                if (au.cmThink <= 0.0f)
                {
                    au.cmThink = (AiRulesMode() == AI_RULES_PS2 ? 0.4f : 1.0f) * kAiTierInterval[AiLodTier(pi.position, playerPos, true)];
                    if (au.cmHave && au.cmPause <= 0.0f && rand() % 12 == 0) au.cmPause = 1.9f;
                }
                const float ax = au.cmTX - pi.position.m_X, az = au.cmTZ - pi.position.m_Z;
                if (au.cmHave && au.cmPause <= 0.0f && ax * ax + az * az < 1.0f) au.cmPause = 1.9f;
                if (au.cmHave && au.cmPause <= 0.0f)
                {

                    const float ad = sqrtf(ax * ax + az * az);
                    if (ad < au.cmBestD - 0.25f) { au.cmBestD = ad; au.cmStall = 0.0f; }
                    else if ((au.cmStall += deltaSec) > 1.5f) au.cmPause = 1.9f;
                }
                if (au.cmPause > 0.0f) { au.cmPause -= deltaSec; if (au.cmPause <= 0.0f) au.cmHave = false; }
                if (!au.cmHave)
                {
                    const float lo = wOpt - 0.2f * (wOpt - wMin), hi = wOpt + 0.2f * (wRange - wOpt);
                    for (int k = 0; k < 10; ++k)
                    {
                        const float a = 6.2831853f * (float)rand() / (float)RAND_MAX;
                        const float r = lo + (hi - lo) * (float)rand() / (float)RAND_MAX;
                        au.cmTX = au.cachedTargetPos.m_X + cosf(a) * r; au.cmTZ = au.cachedTargetPos.m_Z + sinf(a) * r;
                        if (!PointBlockedByBarrier(au.cmTX, au.cmTZ, rsc::kRadius)) break;
                    }
                    au.cmHave = true; au.cmBestD = 1e9f; au.cmStall = 0.0f;
                }
            }
            if (au.cmMode == 2 || au.cmPause > 0.0f)
            {
                if (fabsf(fx) > 0.0001f || fabsf(fz) > 0.0001f)
                {
                    au.wantYaw = atan2f(-fx, -fz);
                    au.haveWantYaw = true; au.wantSrc = 4;
                }
                g_aiDiagEngaging++;
                au.why = 6;
                continue;
            }
            if (au.cmMode == 3) { g_aiDiagEngaging++; cmCircling = true; }
        }
        else { au.cmMode = 0; au.cmHave = false; if (au.hintNodeIdx < 0) au.hintHoldTime = 0.0f; }

        bool hintSteer = false;

        if (!followGoal && au.hintNodeIdx >= 0 && au.hintNodeIdx < (int)g_hintNodes.size())
        {
            const HintNodeData& hn = g_hintNodes[au.hintNodeIdx];
            const float hdx = hn.position.m_X - pi.position.m_X;
            const float hdz = hn.position.m_Z - pi.position.m_Z;
            const float hdist = sqrtf(hdx * hdx + hdz * hdz);
            g_aiDiagUsingHint++;

            if (hdist <= ((g_fightOff & 8) ? 1.2f : 2.0f))
            {

                if (!au.hintAt) { au.coverPhase = 1; au.coverTimer = 0.0f; }
                au.hintAt = true;
                if (au.hintKind == 2 && (au.coverTimer -= deltaSec) <= 0.0f)
                {

                    au.coverPhase ^= 1;
                    au.coverTimer = au.coverPhase == 0 ? (float)(2 + rand() % 3) : (float)(2 + rand() % 5);
                    const int bits = (au.coverPhase == 0 ? hn.primaryStance : hn.secondaryStance) & 3;
                    au.coverCrouch = bits == 2 || (bits == 3 && (rand() & 1));
                }
                float fx = au.haveCachedTarget ? au.cachedTargetPos.m_X - pi.position.m_X : hn.forward.m_X;
                float fz = au.haveCachedTarget ? au.cachedTargetPos.m_Z - pi.position.m_Z : hn.forward.m_Z;
                if (fabsf(fx) > 0.0001f || fabsf(fz) > 0.0001f)
                {
                    au.wantYaw = atan2f(-fx, -fz);
                    au.haveWantYaw = true; au.wantSrc = 5;
                }
                au.why = 7;
                continue;
            }

            dx = hdx; dz = hdz; dist = hdist;

            if (hdist < au.hintBestD - 0.25f) { au.hintBestD = hdist; au.hintStall = 0.0f; }
            else if ((au.hintStall += deltaSec) > (au.hintKind == 1 ? 15.0f : 3.0f))
            {
                if (g_hintNodes[au.hintNodeIdx].reservedBy == (int)n) g_hintNodes[au.hintNodeIdx].reservedBy = -1;

                au.hintFailIdx = au.hintNodeIdx; au.hintFailUntil = g_aiClock + 120.0f; ++g_hintGiveUps;
                checkpointf("HINTFAIL u%u at (%.1f,%.1f,%.1f) hint %d (%.1f,%.1f,%.1f) best %.1f nav %u/%u", (unsigned)n, pi.position.m_X, pi.position.m_Y, pi.position.m_Z, au.hintNodeIdx, g_hintNodes[au.hintNodeIdx].position.m_X, g_hintNodes[au.hintNodeIdx].position.m_Y, g_hintNodes[au.hintNodeIdx].position.m_Z, au.hintBestD, (unsigned)au.navPathIndex, (unsigned)au.navPath.size());
                au.hintReevalTimer = 8.0f + 4.0f * (float)rand() / (float)RAND_MAX;
                au.hintNodeIdx = -1; au.hintKind = 0; au.hintAt = false;
            }
            else hintSteer = au.hintKind != 1;
        }

        if (supportSteer)
        {
            dx = supportGX - pi.position.m_X; dz = supportGZ - pi.position.m_Z;
            dist = sqrtf(dx * dx + dz * dz);
        }
        const bool insideCaptureRegion = !supportSteer && target->hasCaptureRegion &&
            PointInRegion(target->captureRegionPos, target->captureRegionRot,
                          target->captureRegionSize, target->captureRegionType, pi.position);

        AiLap(14);

        if (pi.isDroideka)
        {
            const float ROLL_ENTER_DIST = 15.0f;
            const float ROLL_EXIT_DIST = 6.0f;

            const bool inCombat = DroidekaInCombat(au);
            switch (au.droidekaLocoState)
            {
            case 2:

                if (au.unstickTimer > 0.0f)
                {
                    au.droidekaLocoState = 3;
                    au.droidekaLocoTimer = REAL_DROIDEKA_UNFOLD_TIME;
                    au.droidekaRollCooldown = 6.0f;
                    static uint32_t rollAbortDiag = 0;
                    if (rollAbortDiag < 60)
                    {
                        rollAbortDiag++;
                        checkpointf("M313 droideka unit %u ABORTED roll (stuck) at (%.1f,%.1f,%.1f) dist=%.1f - unfolding, cooldown 6s",
                            (unsigned)n, pi.position.m_X, pi.position.m_Y, pi.position.m_Z, dist);
                    }
                    break;
                }

                if (insideCaptureRegion || dist <= ROLL_EXIT_DIST || au.barrierStopTime > 0.5f)
                { au.droidekaLocoState = 3; au.droidekaLocoTimer = REAL_DROIDEKA_UNFOLD_TIME; }

                if (au.rollStillSec > 0.5f)
                {
                    au.droidekaLocoState = 3;
                    au.droidekaLocoTimer = REAL_DROIDEKA_UNFOLD_TIME;

                    au.droidekaRollCooldown = 6.0f;
                    if (g_rollNoStickLines < 60)
                    {
                        ++g_rollNoStickLines;
                        checkpointf("ROLLSTUCK no-stick: u%u t=%.2f was rolling %.2fs (dist %.2fm) without moving for %.2fs - unfolding",
                            (unsigned)n, g_aiClock, au.rollDiagSec, au.rollDiagDist, au.rollStillSec);
                    }
                }
                break;
            case 0:
                if (!insideCaptureRegion && dist > ROLL_ENTER_DIST && !inCombat
                    && au.droidekaRollCooldown <= 0.0f && au.unstickTimer <= 0.0f)
                { au.droidekaLocoState = 1; au.droidekaLocoTimer = REAL_DROIDEKA_FOLD_TIME; }
                break;
            default:
                break;
            }
        }

        bool noiseSteer = false;
        {
            if (au.hadTargetPrev && !au.haveCachedTarget && !(g_fightOff & 4)) { au.lookSec = 0.8f; ++g_whyTgt[7]; }
            au.hadTargetPrev = au.haveCachedTarget;
            if (au.haveCachedTarget) { au.noiseSec = 0.0f; au.lookSec = 0.0f; }
            else if (!supportSteer && !followGoal && au.hintNodeIdx < 0)
            {
                if (au.lookSec > 0.0f) { au.lookSec -= deltaSec; au.why = 12; continue; }
                if (au.noiseSec > 0.0f)
                {
                    au.noiseSec -= deltaSec;
                    const float nx = au.noiseX - pi.position.m_X, nz = au.noiseZ - pi.position.m_Z;
                    if (nx * nx + nz * nz < au.noiseStop * au.noiseStop || au.noiseSec <= 0.0f) { au.noiseSec = 0.0f; au.lookSec = (g_fightOff & 4) ? 0.0f : 0.8f; ++g_whyTgt[7]; }
                    else noiseSteer = true;
                }
            }
        }
        {
            static const int s_traceU = getenv("SWBF2_TRACE_UNIT") ? atoi(getenv("SWBF2_TRACE_UNIT")) : -1;
            static float s_traceT = 0.0f;
            if ((int)n == s_traceU && (s_traceT += deltaSec) >= 0.25f)
            {
                s_traceT = 0.0f;
                checkpointf("TRACE u%u t=%.2f pos(%.2f,%.2f) vel(%.2f,%.2f) why%d cp%d cpTeam%d myTeam%d inReg%d dist%.1f ap[arr%d tst%d have%d at%d sec%.1f T(%.1f,%.1f) wsec%.1f] nav%u/%u rn(%.1f,%.1f) hub%d tgt%d circ%d mode%d hint%d crowd%.1f repick%d",
                    (unsigned)n, g_aiClock, pi.position.m_X, pi.position.m_Z, au.velX, au.velZ, (int)au.why, au.cachedTargetCpIndex, target->team, pi.team,
                    (int)insideCaptureRegion, dist, (int)au.apArrived, (int)au.apTested, (int)au.apHave, (int)au.apAt, au.apSec, au.apTX, au.apTZ, au.apWanderSec,
                    (unsigned)au.navPathIndex, (unsigned)au.navPath.size(), au.rnX, au.rnZ, au.rnHub, (int)au.haveCachedTarget, (int)cmCircling, (int)au.cmMode,
                    au.hintNodeIdx, au.crowdTimer, (int)au.forceRepick);
                {   static bool s_compDump = false;
                    if (!s_compDump)
                    {
                        s_compDump = true; NavComponentOf(pi.position);
                        std::map<int, int> sz; for (int c : g_navComp) ++sz[c];
                        std::string o; for (auto& kv : sz) { char b[32]; snprintf(b, sizeof(b), " c%d:%d", kv.first, kv.second); o += b; }
                        for (size_t ci = 0; ci < g_commandPosts.size(); ++ci) { char b[64]; const Vector3& cpp = g_commandPosts[ci].position; snprintf(b, sizeof(b), " cp%u(%.0f,%.0f,%.0f)=c%d", (unsigned)ci, cpp.m_X, cpp.m_Y, cpp.m_Z, NavComponentOf(cpp)); o += b; }
                        checkpointf("TRACE nav components (hubs each):%s", o.c_str());
                    }
                }
                if (au.navPath.empty())
                {
                    const RnLocate ls = RetailNavLocate(pi.position), lg = RetailNavLocate(target->position);
                    std::vector<uint16_t> tp; const int sh = ls.hub >= 0 ? ls.hub : ls.arcA, gh = lg.hub >= 0 ? lg.hub : lg.arcA;
                    const bool rw = (sh >= 0 && gh >= 0) && RouteWalk(sh, gh, tp);
                    const bool as = (sh >= 0 && gh >= 0) && NavFindPath(sh, gh, tp, 1, nullptr);
                    checkpointf("TRACE u%u locate start tier%d hub%d arc%d-%d (comp %d) goal tier%d hub%d arc%d-%d (comp %d): routeWalk %d A* %d",
                        (unsigned)n, ls.tier, ls.hub, ls.arcA, ls.arcB, NavComponentOf(pi.position), lg.tier, lg.hub, lg.arcA, lg.arcB, NavComponentOf(target->position), (int)rw, (int)as);
                }
                if (au.hintNodeIdx >= 0 && au.hintNodeIdx < (int)g_hintNodes.size()) checkpointf("TRACE u%u hint kind%d at(%.1f,%.1f,%.1f) me y%.1f best%.1f stall%.1f hintAt%d hold%.1f", (unsigned)n, au.hintKind, g_hintNodes[au.hintNodeIdx].position.m_X, g_hintNodes[au.hintNodeIdx].position.m_Y, g_hintNodes[au.hintNodeIdx].position.m_Z, pi.position.m_Y, au.hintBestD, au.hintStall, (int)au.hintAt, au.hintHoldTime);
            }
        }
        bool apWandering = false;
        if (!supportSteer && !cmCircling && !noiseSteer && !followGoal && au.hintNodeIdx < 0)
        {
            const float pdx = target->position.m_X - pi.position.m_X, pdz = target->position.m_Z - pi.position.m_Z;
            const bool atPost = target->hasCaptureRegion ? insideCaptureRegion : (pdx * pdx + pdz * pdz < 100.0f);
            if (atPost && !au.apArrived) { au.apArrived = true; au.apSec = 0.0f; au.apTested = false; au.apHave = false; ++g_whyTgt[5]; }
            if (au.apArrived)
            {
                au.apSec += deltaSec;
                if (!au.apTested && au.apSec >= 5.0f)
                {
                    au.apTested = true;

                    bool ownsPost = false;
                    for (const CommandPostState& cpo : g_commandPosts) if (cpo.team == pi.team) { ownsPost = true; break; }
                    const bool roamDone = !IsCapturingTeam(pi.team) && (TeamDeathmatchOnly(pi.team) || (!g_ewokParkDbg && !ownsPost));
                    if (!target->hasCaptureRegion || target->team == pi.team || roamDone) { au.forceRepick = true; ++g_whyTgt[3]; }
                    else ++g_whyTgt[4];
                }
                if (!au.forceRepick && au.apTested && target->team == pi.team)
                {
                    au.apWanderSec -= deltaSec;
                    if (!au.apHave || au.apWanderSec <= 0.0f)
                    {
                        for (int k = 0; k < 10; ++k)
                        {
                            const float ux = 2.0f * (float)rand() / (float)RAND_MAX - 1.0f, uz = 2.0f * (float)rand() / (float)RAND_MAX - 1.0f;
                            const float rx = 8.0f + 6.0f * (float)rand() / (float)RAND_MAX, rz = 8.0f + 6.0f * (float)rand() / (float)RAND_MAX;
                            au.apTX = target->position.m_X + ux * rx; au.apTZ = target->position.m_Z + uz * rz;
                            if (!PointBlockedByBarrier(au.apTX, au.apTZ, rsc::kRadius)) break;
                        }
                        au.apHave = true; au.apAt = false; au.apBestD = 1e9f; au.apStall = 0.0f; au.apWanderSec = 20.0f + 10.0f * (float)rand() / (float)RAND_MAX;
                    }
                    const float wx = au.apTX - pi.position.m_X, wz = au.apTZ - pi.position.m_Z;
                    if (wx * wx + wz * wz < 1.0f) au.apAt = true;
                    {

                        const float wd = sqrtf(wx * wx + wz * wz);
                        if (wd < au.apBestD - 0.25f) { au.apBestD = wd; au.apStall = 0.0f; }
                        else if ((au.apStall += deltaSec) > 1.5f) au.apAt = true;
                    }
                    if (au.apAt) { au.why = 9; continue; }
                    apWandering = true;
                }
            }
        }

        if (au.crowdTimer > 0.0f) au.crowdTimer -= deltaSec;
        if (!cmCircling && !apWandering && !hintSteer && !noiseSteer && ((insideCaptureRegion && dist <= 2.5f) || dist <= STOP_RADIUS || (au.crowdTimer > 0.0f && dist < 15.0f)))
        {
            au.why = (insideCaptureRegion && dist <= 2.5f) ? 8 : (dist <= STOP_RADIUS ? 9 : 10);
            continue;
        }
        au.why = cmCircling ? 11 : 0;

        float unitSpeed = pi.isDroideka
            ? ((au.droidekaLocoState == 2) ? REAL_DROIDEKA_ROLL_SPEED : REAL_DROIDEKA_WALK_SPEED)
            : g_soldierMaxSpeed;

        au.navRepathTimer -= deltaSec;
        if (au.badHubSec > 0.0f && (au.badHubSec -= deltaSec) <= 0.0f) { au.badHub[0] = au.badHub[1] = au.badHub[2] = -1; }
        const int targetCpIdx = (int)(target - g_commandPosts.data());

        {
            const int goalKey = routeGoalKey;
            if (!au.navPath.empty() && au.navPathIndex >= au.navPath.size() && au.navPathGoalCp == goalKey) au.routeDoneGoal = goalKey;
        }
        const bool needRepath = (g_navHubs.empty() || au.rwActive || followGoal) ? false
            : ((au.navPath.empty() && au.navRepathTimer <= 0.0f)
               || au.navPathGoalCp != routeGoalKey
               || (au.navPathIndex >= au.navPath.size() && au.routeDoneGoal != au.navPathGoalCp));
        AiLap(6);
        if (needRepath)
        {

            int startHub = -1;
            if (!g_retailNav)
            {
                std::vector<std::pair<float, int>> cand;
                for (size_t hi = 0; hi < g_navHubs.size(); ++hi)
                {
                    const float hx = g_navHubs[hi].position.m_X - pi.position.m_X, hz = g_navHubs[hi].position.m_Z - pi.position.m_Z;
                    cand.push_back({ hx * hx + hz * hz, (int)hi });
                }
                std::sort(cand.begin(), cand.end());
                auto banned = [&](int h) { return h == au.badHub[0] || h == au.badHub[1] || h == au.badHub[2]; };
                for (size_t ci = 0; ci < cand.size() && ci < 6 && startHub < 0; ++ci)
                {
                    if (banned(cand[ci].second)) continue;
                    const Vector3& hp = g_navHubs[(size_t)cand[ci].second].position;
                    if (fabsf(hp.m_Y - pi.position.m_Y) > 2.5f) continue;
                    const float d = sqrtf(cand[ci].first);
                    if (d < 0.5f) { startHub = cand[ci].second; break; }

                    if (AIStraightWalkClear(pi.position, Vector3(hp.m_X, pi.position.m_Y, hp.m_Z), uniqueModels, placedRef, au.placedIndex))
                        startHub = cand[ci].second;
                }
                for (size_t ci = 0; ci < cand.size() && startHub < 0; ++ci)
                    if (!banned(cand[ci].second)) startHub = cand[ci].second;
                if (startHub < 0) startHub = NavNearestHub(pi.position);
            }
            const int goalHub = NavNearestHub(approachPos);
            const uint64_t tnav = sceKernelGetProcessTimeWide();
            const bool navOk = g_retailNav ? RetailNavPlan(pi.position, approachPos, au.navPath, au.badHubSec > 0.0f ? au.badHub : nullptr)
                                           : NavFindPath(startHub, goalHub, au.navPath);
            g_aiuNavUs += sceKernelGetProcessTimeWide() - tnav; ++g_aiuNavCalls;
            ++au.pcReplans;
            if (au.pcTrace)
            {
                std::string r;
                for (size_t k = 0; k < au.navPath.size() && k < 6; ++k)
                { char hb[40]; const Vector3& hp = g_navHubs[au.navPath[k]].position; snprintf(hb, sizeof(hb), " %u(%.0f,%.0f,%.0f)", (unsigned)au.navPath[k], hp.m_X, hp.m_Y, hp.m_Z); r += hb; }
                checkpointf("M503 trace u%u: plan ok=%d from (%.1f,%.1f,%.1f) to cp%d (%.1f,%.1f) bans %d/%d/%d:%s", (unsigned)n, (int)navOk,
                    pi.position.m_X, pi.position.m_Y, pi.position.m_Z, targetCpIdx, approachPos.m_X, approachPos.m_Z,
                    au.badHubSec > 0.0f ? au.badHub[0] : -1, au.badHubSec > 0.0f ? au.badHub[1] : -1, au.badHubSec > 0.0f ? au.badHub[2] : -1, r.c_str());
            }
            if (navOk)
            {
                au.navPathIndex = 0;
                au.navPathGoalCp = routeGoalKey;
                {

                    static int s_routeLog[16] = {};
                    if (targetCpIdx >= 0 && targetCpIdx < 16 && s_routeLog[targetCpIdx] < 12)
                    {
                        ++s_routeLog[targetCpIdx];
                        std::string r;
                        for (uint16_t hh : au.navPath)
                        {
                            char b[40]; const Vector3& hp = g_navHubs[hh].position;
                            snprintf(b, sizeof(b), " (%.0f,%.0f,%.0f)", hp.m_X, hp.m_Y, hp.m_Z); r += b;
                        }
                        checkpointf("M404 route team %d -> %s from (%.0f,%.0f):%s", pi.team,
                            g_commandPosts[(size_t)targetCpIdx].name.c_str(), pi.position.m_X, pi.position.m_Z, r.c_str());
                    }
                }
            }
            else
            {
                au.navPath.clear();
            }

            au.navRepathTimer = 3.0f + 0.05f * (float)(n % 20);
        }

        float steerX = dx, steerZ = dz, steerDist = dist;
        AiLap(7);
        if (cmCircling || apWandering || hintSteer)
        {
            const float gx = noiseSteer ? au.noiseX : hintSteer ? g_hintNodes[(size_t)au.hintNodeIdx].position.m_X : cmCircling ? au.cmTX : au.apTX;
            const float gz = noiseSteer ? au.noiseZ : hintSteer ? g_hintNodes[(size_t)au.hintNodeIdx].position.m_Z : cmCircling ? au.cmTZ : au.apTZ;
            const float tx = gx - pi.position.m_X, tz = gz - pi.position.m_Z;
            steerX = tx; steerZ = tz; steerDist = sqrtf(tx * tx + tz * tz);
        }
        else if (g_retailNav && au.rwActive)
        {

            au.rwSec += deltaSec; au.rwRepick -= deltaSec;
            const float ox = pi.position.m_X - au.rwOX, oz = pi.position.m_Z - au.rwOZ;
            if (ox * ox + oz * oz > 36.0f || au.rwSec > 15.0f)
            {
                if (au.rwSec > 15.0f) ++g_rwTimeouts; else ++g_rwDone;
                au.rwActive = false; au.navRepathTimer = 0.0f; au.routeDoneGoal = -1; au.navPath.clear();
            }
            else
            {
                float tx = au.rwTX - pi.position.m_X, tz = au.rwTZ - pi.position.m_Z;
                if (au.rwRepick <= 0.0f || tx * tx + tz * tz < 1.0f) { RandomWalkPick(au); tx = au.rwTX - pi.position.m_X; tz = au.rwTZ - pi.position.m_Z; }
                steerX = tx; steerZ = tz; steerDist = sqrtf(tx * tx + tz * tz);
            }
        }
        else if (g_retailNav && !supportSteer && !au.navPath.empty() && au.navPathIndex < au.navPath.size())
        {
            const uint16_t hubIdx = au.navPath[au.navPathIndex];
            if (hubIdx >= g_navHubs.size()) au.navPath.clear();
            else
            {
                const NavHub& hub = g_navHubs[hubIdx];
                if (au.rnHub != (int)hubIdx)
                {

                    au.rnX = hub.position.m_X; au.rnZ = hub.position.m_Z;

                    const float sx = hub.position.m_X - pi.position.m_X, sz = hub.position.m_Z - pi.position.m_Z;
                    if (au.navPathIndex == 0 && au.navPath.size() > 1 && sx * sx + sz * sz < hub.radius * hub.radius) { au.rnX = pi.position.m_X; au.rnZ = pi.position.m_Z; }
                    else
                    for (int k = 0; k < 100; ++k)
                    {
                        const float rr = hub.radius * sqrtf((float)rand() / (float)RAND_MAX);
                        const float aa = 6.2831853f * (float)rand() / (float)RAND_MAX;
                        const float px = hub.position.m_X + cosf(aa) * rr, pz = hub.position.m_Z + sinf(aa) * rr;
                        if (!PointBlockedByBarrier(px, pz, rsc::kRadius)) { au.rnX = px; au.rnZ = pz; break; }
                    }
                    au.rnHub = (int)hubIdx; au.rnBestD2 = 1e30f; au.rnBestSec = 0.0f;

                    au.rnLegIdx = 0;
                    if (!PlanBarrierLeg(pi.position.m_X, pi.position.m_Z, au.rnX, au.rnZ, rsc::kRadius, au.rnLeg))
                        au.rnLeg.clear();
                    if (au.pcTrace && !au.rnLeg.empty())
                        checkpointf("M532 trace u%u: leg to (%.1f,%.1f) round barriers via %u corner(s), first (%.1f,%.1f)", (unsigned)n,
                            au.rnX, au.rnZ, (unsigned)(au.rnLeg.size() / 2), au.rnLeg[0], au.rnLeg[1]);
                }

                while (au.rnLegIdx * 2 + 1 < au.rnLeg.size())
                {
                    const float cx = au.rnLeg[au.rnLegIdx * 2], cz = au.rnLeg[au.rnLegIdx * 2 + 1];
                    const float qx = cx - pi.position.m_X, qz = cz - pi.position.m_Z;
                    bool cPassed = false;
                    if (au.rnHavePrev) cPassed = (-qx) * (cx - au.rnPrevX) + (-qz) * (cz - au.rnPrevZ) > 0.0f;
                    if (qx * qx + qz * qz > 1.0f && !cPassed) break;
                    au.rnPrevX = cx; au.rnPrevZ = cz; au.rnHavePrev = true; ++au.rnLegIdx;
                    au.rnBestD2 = 1e30f; au.rnBestSec = 0.0f;
                }
                const bool onCorner = au.rnLegIdx * 2 + 1 < au.rnLeg.size();
                const float tgX = onCorner ? au.rnLeg[au.rnLegIdx * 2] : au.rnX, tgZ = onCorner ? au.rnLeg[au.rnLegIdx * 2 + 1] : au.rnZ;
                const float wx = tgX - pi.position.m_X, wz = tgZ - pi.position.m_Z;
                const float wd2 = wx * wx + wz * wz;
                if (!au.rnHavePrev) { au.rnPrevX = pi.position.m_X; au.rnPrevZ = pi.position.m_Z; au.rnHavePrev = true; }
                const bool last = (au.navPathIndex + 1 >= au.navPath.size());
                const float stopD = last ? 0.5f : 1.0f;
                bool passed = false;
                if (au.rnHavePrev)
                {
                    const float lx = tgX - au.rnPrevX, lz = tgZ - au.rnPrevZ;
                    passed = (-wx) * lx + (-wz) * lz > 0.0f;
                }
                if (!onCorner && (wd2 <= stopD * stopD || passed))
                {
                    au.rnPrevX = au.rnX; au.rnPrevZ = au.rnZ; au.rnHavePrev = true;
                    au.navPathIndex++; au.rnHub = -1; ++g_rnArrivals;
                }
                else
                {
                    steerX = wx; steerZ = wz; steerDist = sqrtf(wd2);
                    {

                        const float ux0 = tgX - au.rnPrevX, uz0 = tgZ - au.rnPrevZ, ul = sqrtf(ux0 * ux0 + uz0 * uz0);
                        if (ul >= 0.01f)
                        {
                            const float ux = ux0 / ul, uz = uz0 / ul;
                            const float t = (pi.position.m_X - au.rnPrevX) * ux + (pi.position.m_Z - au.rnPrevZ) * uz + sqrtf(au.velX * au.velX + au.velZ * au.velZ) + 0.2f;
                            if (t < ul)
                            {
                                steerX = au.rnPrevX + ux * t - pi.position.m_X; steerZ = au.rnPrevZ + uz * t - pi.position.m_Z;
                                steerDist = sqrtf(steerX * steerX + steerZ * steerZ);
                            }
                        }
                    }

                    if (wd2 >= 0.04f)
                    {
                        const float ax = pi.position.m_X - au.rnAnchor.m_X, az = pi.position.m_Z - au.rnAnchor.m_Z;
                        if (ax * ax + az * az <= 4.0f) au.rnAnchorSec += deltaSec;
                        else { au.rnAnchor = pi.position; au.rnAnchorSec = 0.0f; }
                        if (wd2 >= au.rnBestD2) au.rnBestSec += deltaSec; else { au.rnBestD2 = wd2; au.rnBestSec = 0.0f; }
                        const float notMoving = pi.isDroideka ? 6.0f : 3.0f, noProgress = pi.isDroideka ? 6.0f : 5.0f;
                        if (au.rnAnchorSec > notMoving || au.rnBestSec > noProgress)
                        {

                            ++au.rnStuck; ++g_rnStuckEvents;

                            RetailNavFail(au, (int)hubIdx, "stuck");
                            au.rwActive = true; au.rwOX = pi.position.m_X; au.rwOZ = pi.position.m_Z; au.rwSec = 0.0f;
                            RandomWalkPick(au); ++g_rwStarts;
                            steerX = au.rwTX - pi.position.m_X; steerZ = au.rwTZ - pi.position.m_Z;
                            steerDist = sqrtf(steerX * steerX + steerZ * steerZ);
                        }
                    }

                    au.rnSweepSec -= deltaSec;
                    if (!au.navPath.empty() && au.rnSweepSec <= 0.0f && steerDist > 0.5f)
                    {
                        au.rnSweepSec = 0.5f + 0.01f * (float)(n % 25);
                        const float ahead = fminf(5.0f, steerDist);
                        const Vector3 to(pi.position.m_X + steerX / steerDist * ahead, pi.position.m_Y, pi.position.m_Z + steerZ / steerDist * ahead);

                        bool barrierAhead = false;
                        if (!PointBlockedByBarrier(pi.position.m_X, pi.position.m_Z, rsc::kRadius))
                            for (float s = 0.5f; s <= ahead + 1e-3f && !barrierAhead; s += 0.5f)
                                barrierAhead = PointBlockedByBarrier(pi.position.m_X + steerX / steerDist * s, pi.position.m_Z + steerZ / steerDist * s, rsc::kRadius);
                        (void)to;
                        if (barrierAhead)
                        {
                            ++au.rnBlocked; ++g_rnBlockedEvents;
                            RetailNavFail(au, (int)hubIdx, "blocked");
                            steerX = dx; steerZ = dz; steerDist = dist;
                        }
                    }

                    if (!au.navPath.empty())
                    {
                        const rsc::V3 pv = au.rscBody.wallPush;
                        const float pl = sqrtf(pv.x * pv.x + pv.z * pv.z);
                        if (pl > 1e-4f)
                        {
                            const float qx = pv.z / pl, qz = -pv.x / pl;
                            if (au.sideStep == 0)
                                au.sideStep = (qx * (pi.position.m_X - tgX) + qz * (pi.position.m_Z - tgZ) <= 0.0f) ? 1 : -1;
                            steerX = (float)au.sideStep * 5.0f * qx; steerZ = (float)au.sideStep * 5.0f * qz; steerDist = 5.0f;
                            ++g_sideSteps;
                        }
                        else au.sideStep = 0;
                    }
                }
            }
        }
        else if (!supportSteer && !au.navPath.empty() && au.navPathIndex < au.navPath.size())
        {
            const uint16_t hubIdx = au.navPath[au.navPathIndex];
            if (hubIdx < g_navHubs.size())
            {
                const NavHub& hub = g_navHubs[hubIdx];

                const float spreadR = fminf(hub.radius * 0.6f, 6.0f);
                const float spreadAng = (float)n * 2.399963f;
                float hubTargetX = hub.position.m_X + cosf(spreadAng) * spreadR;
                float hubTargetZ = hub.position.m_Z + sinf(spreadAng) * spreadR;

                bool spreadBlocked = false;
                if (PointBlockedByBarrier(hubTargetX, hubTargetZ, PLAYER_COLLISION_RADIUS))
                {
                    spreadBlocked = true;
                    for (float f = 0.75f; f >= -0.01f; f -= 0.25f)
                    {
                        const float tx = hub.position.m_X + cosf(spreadAng) * spreadR * f;
                        const float tz = hub.position.m_Z + sinf(spreadAng) * spreadR * f;
                        if (!PointBlockedByBarrier(tx, tz, PLAYER_COLLISION_RADIUS))
                        { hubTargetX = tx; hubTargetZ = tz; spreadBlocked = false; break; }
                    }
                    ++g_aiSpreadInBarrier;
                }

                float hx = hubTargetX - pi.position.m_X;
                float hz = hubTargetZ - pi.position.m_Z;
                float hd = sqrtf(hx * hx + hz * hz);
                const float arrive = fmaxf(hub.radius * 0.5f, 2.0f);
                const float cdx = hub.position.m_X - pi.position.m_X, cdz = hub.position.m_Z - pi.position.m_Z;
                const bool insideHub = (cdx * cdx + cdz * cdz) <= hub.radius * hub.radius;
                if (hd <= arrive || (spreadBlocked && insideHub))
                {
                    au.navPathIndex++;
                }
                else
                {
                    steerX = hx; steerZ = hz; steerDist = hd;
                }
            }
            else
            {
                au.navPath.clear();
            }
        }

        if (g_retailNav && !au.rwActive && !cmCircling && !apWandering && !hintSteer && !supportSteer
            && au.routeDoneGoal >= 0 && au.routeDoneGoal == au.navPathGoalCp && au.navPathIndex >= au.navPath.size())
        {
            const float gd = sqrtf(dx * dx + dz * dz);
            if (gd < au.dlBestD - 0.25f) { au.dlBestD = gd; au.dlSec = 0.0f; } else au.dlSec += deltaSec;
            const float ax = pi.position.m_X - au.dlAX, az = pi.position.m_Z - au.dlAZ;
            if (ax * ax + az * az > 4.0f || au.dlASec < 0.0f) { au.dlAX = pi.position.m_X; au.dlAZ = pi.position.m_Z; au.dlASec = 0.0f; } else au.dlASec += deltaSec;
            if ((au.dlSec > 5.0f || au.dlASec > 3.0f) && gd > 2.0f)
            {
                au.dlASec = -1.0f;
                ++au.rnStuck; ++g_rnStuckEvents;
                au.rwActive = true; au.rwOX = pi.position.m_X; au.rwOZ = pi.position.m_Z; au.rwSec = 0.0f;
                RandomWalkPick(au); ++g_rwStarts;
                au.dlBestD = 1e9f; au.dlSec = 0.0f;
            }
        }
        else { au.dlBestD = 1e9f; au.dlSec = 0.0f; au.dlASec = -1.0f; }

        if (!supportSteer && au.navPathIndex >= 1 && au.navPathIndex < au.navPath.size() && !au.jumpLeg
            && au.pushVelX == 0.0f && au.pushVelY == 0.0f && au.pushVelZ == 0.0f)
        {
            const uint32_t ja = au.navPath[au.navPathIndex - 1], jb = au.navPath[au.navPathIndex];
            if (ja < g_navHubs.size() && jb < g_navHubs.size() && g_navArcJump.count((ja << 16) | jb)
                && !(au.jumpArcKey == ((ja << 16) | jb) && g_aiClock < au.jumpArcUntil))
            {
                const NavHub& ha = g_navHubs[ja];
                const NavHub& hb = g_navHubs[jb];
                const float abx = hb.position.m_X - ha.position.m_X, abz = hb.position.m_Z - ha.position.m_Z;
                const float reach = sqrtf(abx * abx + abz * abz) + ha.radius + 3.0f;
                const float jx = hb.position.m_X - pi.position.m_X, jz = hb.position.m_Z - pi.position.m_Z;
                const float jd = sqrtf(jx * jx + jz * jz);

                if (jd <= reach && jd > fmaxf(hb.radius * 0.5f, 1.0f))
                {

                    const float rise = hb.position.m_Y - pi.position.m_Y;
                    const float arcLen = fmaxf(jd, 0.6f);
                    const float dur = fmaxf(0.7f, fminf(1.8f, arcLen / 4.0f));
                    const float vy = (rise + 0.5f * 9.81f * dur * dur) / dur;
                    au.jumpDur = dur;
                    au.jumpVy = vy; au.jumpT = 0.0f;
                    au.jumpFrom = pi.position; au.jumpTo = hb.position;
                    au.jumpLeg = true; au.localPathValid = false;
                    au.jumpArcKey = (ja << 16) | jb;
                    ++g_aiJumps;
                    checkpointf("M487 jump: unit %u hub %u -> %u from (%.1f, %.1f, %.1f) to (%.1f, %.1f, %.1f) over %.1f m, %.2f s",
                                (unsigned)n, ja, jb, pi.position.m_X, pi.position.m_Y, pi.position.m_Z, hb.position.m_X, hb.position.m_Y, hb.position.m_Z, jd, au.jumpDur);
                    continue;
                }
            }
        }

        AiLap(8);

        bool followingLocalPath = false;
        bool holdForPlan = false;
        if (!g_retailNav)
        {
            const Vector3 coarseTarget(pi.position.m_X + steerX, pi.position.m_Y, pi.position.m_Z + steerZ);
            au.localPlanCooldown -= deltaSec;
            if (au.localPathValid)
            {

                const float tdx = coarseTarget.m_X - au.localPathTarget.m_X;
                const float tdz = coarseTarget.m_Z - au.localPathTarget.m_Z;
                if (tdx * tdx + tdz * tdz > 3.0f * 3.0f) { au.localPathValid = false; au.localPlanPending = false; }
            }
            if (au.localPathValid)
            {
                const float ARRIVE = 0.6f;
                while (au.localPathIndex < au.localPath.size())
                {
                    const float wx = au.localPath[au.localPathIndex].m_X - pi.position.m_X;
                    const float wz = au.localPath[au.localPathIndex].m_Z - pi.position.m_Z;
                    if (wx * wx + wz * wz > ARRIVE * ARRIVE) break;
                    ++au.localPathIndex;
                }
                if (au.localPathIndex >= au.localPath.size())
                {
                    au.localPathValid = false;
                    au.localPlanCooldown = 0.0f;
                }
            }
            if (!au.localPathValid && au.localPlanCooldown <= 0.0f && !au.planInFlight)
            {
                au.localPlanCooldown = 0.5f + 0.02f * (float)(n % 25);

                bool straightClear = false;
                if (!au.localPlanPending)
                {
                    const uint64_t chkT0 = sceKernelGetProcessTimeWide();
                    float blockDist = 1e30f;
                    straightClear = AIStraightWalkClear(pi.position, coarseTarget, uniqueModels, placedRef, au.placedIndex, &blockDist);
                    if (!straightClear)
                    {
                        const float bdx = coarseTarget.m_X - pi.position.m_X, bdz = coarseTarget.m_Z - pi.position.m_Z;
                        const float bd = sqrtf(bdx * bdx + bdz * bdz);
                        const float useD = blockDist < 1e29f ? blockDist : 0.0f;
                        au.blockPtX = pi.position.m_X + (bd > 0.01f ? bdx / bd : 0.0f) * useD;
                        au.blockPtZ = pi.position.m_Z + (bd > 0.01f ? bdz / bd : 0.0f) * useD;
                    }
                    g_localNavCheckUs += sceKernelGetProcessTimeWide() - chkT0; ++g_localNavChecks;

                    if (straightClear) au.localPlanCooldown += 0.5f;
                }
                if (!straightClear)
                {

                    if (n >= g_planAskFrame.size()) { g_planAskFrame.resize(n + 1, 0); g_planQueuedFlag.resize(n + 1, 0); }
                    g_planAskFrame[n] = g_planFrame;

                    if (!g_planQueuedFlag[n]) { g_planQueue.push_back((uint32_t)n); g_planQueuedFlag[n] = 1; }
                    size_t queuePos = SIZE_MAX;
                    for (size_t qi = 0; qi < g_planQueue.size() && qi < LOCALNAV_PLANS_PER_FRAME; ++qi)
                        if (g_planQueue[qi] == (uint32_t)n) { queuePos = qi; break; }

                    if (queuePos == 0 && g_planJobState == 0)
                    {
                        g_planQueue.erase(g_planQueue.begin());
                        g_planQueuedFlag[n] = 0;
                        ++g_localPlansThisFrame;
                        LocalPlanJob& j = g_planJob;
                        j.unit = (uint32_t)n; j.placedIndex = au.placedIndex; j.start = pi.position; j.target = coarseTarget;
                        j.snap = AITraceUnit(n);
                        j.path.clear(); j.planned = j.reached = false; j.expanded = 0; j.floorWon = j.retryWon = j.retryFailed = false; j.us = 0;
                        j.allowRetry = (au.planRetryBlockSec <= 0.0f);
                        float tY = 0.0f; Vector3 tN; uint32_t tH = au.terrainHint;
                        j.onRaisedFloor = GetTerrainHeightAt(terrainData, pi.position.m_X, pi.position.m_Z, tY, tN, tH) && pi.position.m_Y > tY + 1.0f;
                        j.floorY = tY;
                        if (!g_navWallsBuilt) BuildNavWalls(uniqueModels, placedRef);
                        g_planJobModels = &uniqueModels; g_planJobPlaced = &placedRef; g_planJobTerrain = &terrainData;
                        au.planInFlight = true;
                        au.localPlanPending = true;
                        if (StartLocalPlanWorker()) { __sync_synchronize(); g_planJobState = 1; sceKernelSignalSema(g_planJobSema, 1); }
                        else { RunLocalPlanJob(j); g_planJobState = 2; }
                    }
                    else { au.localPlanCooldown = 0.0f; au.localPlanPending = true; }
                }
            }
            if (au.localPathValid)
            {
                const Vector3& wp = au.localPath[au.localPathIndex];
                steerX = wp.m_X - pi.position.m_X;
                steerZ = wp.m_Z - pi.position.m_Z;
                steerDist = sqrtf(steerX * steerX + steerZ * steerZ);
                followingLocalPath = true;
                au.avoidActive = false;
            }

            else if (au.localPlanPending)
            {

                const float bx = au.blockPtX - pi.position.m_X, bz = au.blockPtZ - pi.position.m_Z;
                if (!au.movedLastFrame || bx * bx + bz * bz < 3.0f * 3.0f)
                {
                    holdForPlan = true;
                    ++g_aiHoldForPlanFrames;
                }
            }
        }

        au.goalX = steerX; au.goalZ = steerZ; au.goalD = steerDist;
        AiLap(9);

        if (!g_retailNav && au.unstickTimer > 0.0f)
        {
            au.unstickTimer -= deltaSec;
            const float perpX = -steerZ, perpZ = steerX;
            steerX += perpX * au.unstickSign * 1.5f;
            steerZ += perpZ * au.unstickSign * 1.5f;
            steerDist = sqrtf(steerX * steerX + steerZ * steerZ);
        }
        else if (!g_retailNav && steerDist > 0.0001f && !followingLocalPath)
        {
            au.avoidTimer -= deltaSec;
            const bool probeNow = (au.avoidTimer <= 0.0f);
            if (probeNow) au.avoidTimer = 0.15f + 0.003f * (float)(n % 25);

            Vector3 probeOrigin = pi.position;
            probeOrigin.m_Y += 1.0f;
            const float invLen = 1.0f / steerDist;
            const Vector3 fwd(steerX * invLen, 0.0f, steerZ * invLen);

            const float PROBE_DIST = 3.0f;
            float probeHitDist; Vector3 probeHitPoint;
            if (!probeNow)
            {

                if (au.avoidActive)
                {
                    steerX = au.avoidX;
                    steerZ = au.avoidZ;
                    steerDist = sqrtf(steerX * steerX + steerZ * steerZ);
                }
            }
            else if (FireRayHitTest(probeOrigin, fwd, PROBE_DIST, uniqueModels, placedRef,
                               probeHitDist, probeHitPoint, au.placedIndex,
                                false))
            {

                const Vector3 leftDir(-fwd.m_Z, 0.0f, fwd.m_X);
                const Vector3 rightDir(fwd.m_Z, 0.0f, -fwd.m_X);
                float lDist = PROBE_DIST, rDist = PROBE_DIST;
                Vector3 tmpPt;
                float d;
                if (FireRayHitTest(probeOrigin, leftDir, PROBE_DIST, uniqueModels, placedRef, d, tmpPt, au.placedIndex,  false)) lDist = d;
                if (FireRayHitTest(probeOrigin, rightDir, PROBE_DIST, uniqueModels, placedRef, d, tmpPt, au.placedIndex,  false)) rDist = d;

                const Vector3& around = (lDist >= rDist) ? leftDir : rightDir;

                steerX = fwd.m_X * 0.4f + around.m_X * 1.0f;
                steerZ = fwd.m_Z * 0.4f + around.m_Z * 1.0f;
                steerDist = sqrtf(steerX * steerX + steerZ * steerZ);
                au.avoidActive = true; au.avoidX = steerX; au.avoidZ = steerZ;
            }
            else
            {
                au.avoidActive = false;
            }
        }

        if (steerDist > 0.05f)
        {
            const float fx = steerX / steerDist, fz = steerZ / steerDist;
            const float px = -fz, pz = fx;
            const float LOOK = fminf(2.0f, steerDist + 0.5f), WIDE = 0.9f;
            float bestT = LOOK, bestLat = 0.0f; bool found = false;
            auto consider = [&](const Vector3& op)
            {
                const float rx = op.m_X - pi.position.m_X, rz = op.m_Z - pi.position.m_Z;
                if (fabsf(op.m_Y - pi.position.m_Y) > 1.5f) return;
                const float t = rx * fx + rz * fz;
                if (t <= 0.05f || t >= bestT) return;
                const float lat = rx * px + rz * pz;
                if (fabsf(lat) > WIDE) return;
                bestT = t; bestLat = lat; found = true;
            };
            for (size_t oi = 0; oi < g_aiUnits.size(); ++oi)
            {
                const AIUnitState& o = g_aiUnits[oi];
                if (&o == &au || o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size() || o.flyer) continue;
                const PlacedInstance& op = placedRef[o.placedIndex];
                if (op.team < 0 || op.inVehicle) continue;
                const float qx = op.position.m_X - pi.position.m_X, qz = op.position.m_Z - pi.position.m_Z;
                if (qx * qx + qz * qz > LOOK * LOOK) continue;
                consider(op.position);
            }
            if (g_playerVehicle < 0) consider(playerPos);
            if (found)
            {

                const float side = (bestLat > 0.02f) ? -1.0f : 1.0f;
                const float k = 1.4f * (1.0f - bestT / LOOK) + 0.4f;
                float nx = fx + px * side * k, nz = fz + pz * side * k;
                const float nl = sqrtf(nx * nx + nz * nz);
                steerX = nx / nl * steerDist; steerZ = nz / nl * steerDist;
                ++g_aiDiagBodyAvoid;
            }
        }

        if (steerDist < 0.0001f) steerDist = 0.0001f;

        float wantSpeed = unitSpeed;
        {
            const float steerYaw = atan2f(-steerX, -steerZ);

            const float curAim = au.aimYawValid ? au.aimYaw : (2.0f * atan2f(pi.rotation.m_Y, pi.rotation.m_W) - 3.14159265f);
            if (!pi.isDroideka)
            {
                const float a = AngleDiff(curAim, steerYaw);
                const float m = fmaxf(fabsf(cosf(a)) / fmaxf(0.01f, unitSpeed), fabsf(sinf(a)) / fmaxf(0.01f, g_soldierMaxStrafeSpeed));
                wantSpeed = fminf(unitSpeed, 1.0f / fmaxf(m, 1e-4f));
                au.dbgTurnFactor = wantSpeed / fmaxf(0.01f, unitSpeed);
            }
            else
            {
                const float off = fabsf(AngleDiff(curAim, steerYaw));
                wantSpeed *= fmaxf(0.0f, cosf(off));
            }
            if (holdForPlan) wantSpeed = 0.0f;
            if (au.yieldSec > 0.0f) { au.yieldSec -= deltaSec; wantSpeed = 0.0f; }

            (void)steerYaw;
            uint8_t src6 = 6;
            if (au.goalD > 0.5f) au.wantYaw = atan2f(-au.goalX, -au.goalZ);
            else { au.wantYaw = curAim; src6 = 7; }
            if (au.haveCachedTarget && !supportSteer && !pi.isDroideka)
            { au.wantYaw = atan2f(-(au.cachedTargetPos.m_X - pi.position.m_X), -(au.cachedTargetPos.m_Z - pi.position.m_Z)); src6 = 8; }
            au.haveWantYaw = true; au.wantSrc = src6;
        }
        if (!au.movedLastFrame) { au.velX = 0.0f; au.velZ = 0.0f; }
        {
            const float wvx = (steerX / steerDist) * wantSpeed, wvz = (steerZ / steerDist) * wantSpeed;
            float ddx = wvx - au.velX, ddz = wvz - au.velZ;
            const float dl = sqrtf(ddx * ddx + ddz * ddz);
            const float maxDv = g_soldierAcceleration * deltaSec;
            if (dl > maxDv) { ddx *= maxDv / dl; ddz *= maxDv / dl; }
            au.velX += ddx; au.velZ += ddz;
        }
        au.movedThisFrame = true;
        float moveDist = sqrtf(au.velX * au.velX + au.velZ * au.velZ) * deltaSec;
        if (moveDist > steerDist) moveDist = steerDist;
        const float velLen = sqrtf(au.velX * au.velX + au.velZ * au.velZ);
        float intendedX = (velLen > 0.0001f) ? (au.velX / velLen) * moveDist : 0.0f;
        float intendedZ = (velLen > 0.0001f) ? (au.velZ / velLen) * moveDist : 0.0f;
        const float preMoveX = pi.position.m_X, preMoveZ = pi.position.m_Z;
        au.dbgSteerX = steerX; au.dbgSteerZ = steerZ; au.dbgPreBarX = intendedX; au.dbgPreBarZ = intendedZ;
        au.dbgBarBranch = 0;

        AiLap(1);
        if (!g_navBarriers.empty() && au.unstickTimer <= 0.0f && !followingLocalPath && !g_noBarrierStop)
        {
            const float unitRadius = PLAYER_COLLISION_RADIUS;

            const bool alreadyInsideBarrier = PointBlockedByBarrier(preMoveX, preMoveZ, unitRadius);
            au.dbgInsideBar = alreadyInsideBarrier ? 1 : 0;
            au.barrierStopTime = fmaxf(0.0f, au.barrierStopTime - deltaSec * 0.5f);
            if (!alreadyInsideBarrier &&
                PointBlockedByBarrier(preMoveX + intendedX, preMoveZ + intendedZ, unitRadius))
            {

                const float AXIS_EPS = 1e-4f;
                const bool xOk = fabsf(intendedX) > AXIS_EPS && !PointBlockedByBarrier(preMoveX + intendedX, preMoveZ, unitRadius);
                const bool zOk = fabsf(intendedZ) > AXIS_EPS && !PointBlockedByBarrier(preMoveX, preMoveZ + intendedZ, unitRadius);
                if (xOk && !zOk)      { intendedZ = 0.0f; au.dbgBarBranch = 1; }
                else if (zOk && !xOk) { intendedX = 0.0f; au.dbgBarBranch = 2; }
                else if (xOk && zOk)  { intendedZ = 0.0f; au.dbgBarBranch = 3; }
                else
                {

                    const float perpX = -intendedZ, perpZ = intendedX;
                    const bool leftOk  = !PointBlockedByBarrier(preMoveX + perpX, preMoveZ + perpZ, unitRadius);
                    const bool rightOk = !PointBlockedByBarrier(preMoveX - perpX, preMoveZ - perpZ, unitRadius);
                    if (leftOk || rightOk)
                    {
                        const float sx = leftOk ? perpX : -perpX;
                        const float sz = leftOk ? perpZ : -perpZ;
                        intendedX = sx; intendedZ = sz;
                        au.avoidActive = true; au.avoidX = sx; au.avoidZ = sz;
                        au.dbgBarBranch = 4;
                    }
                    else
                    {
                        intendedX = 0.0f; intendedZ = 0.0f;
                        au.dbgBarBranch = 5;
                    }
                    au.barrierStopTime += deltaSec;
                    if (au.barrierStopTime > 1.5f)
                    {
                        au.navPath.clear();
                        au.navPathIndex = 0;
                        au.navPathGoalCp = -1;
                        au.navRepathTimer = 0.0f;
                        au.barrierStopTime = 0.0f;
                        g_aiDiagBarrierReplan++;
                    }
                    g_aiDiagBarrierStop++;
                }
                g_aiDiagBarrierBlocked++;

                au.localPlanCooldown = 0.0f;
            }
        }

        pi.position.m_X += intendedX;
        pi.position.m_Z += intendedZ;

        {
            const float aiTravel = sqrtf(intendedX * intendedX + intendedZ * intendedZ);
            const bool aiActive = (au.life == AI_LIFE_ALIVE) && aiTravel > 0.0001f;

            const bool aiRunning = deltaSec > 0.0001f && (aiTravel / deltaSec) > (g_soldierMaxSpeed * 0.5f);
            const int archetype = ResolveFootstepArchetype(pi.team == 1 ? "rep_inf_default" : "cis_inf_default");
            const float adx = pi.position.m_X - playerPos.m_X, adz = pi.position.m_Z - playerPos.m_Z;
            const float distToListener = sqrtf(adx * adx + adz * adz);
            const float kRealMinDist = 10.0f, kRealMaxDist = 50.0f, kRealRollOff = 3.0f;
            if (archetype >= 0 && distToListener < kRealMaxDist)
            {
                const float gain = (distToListener <= kRealMinDist) ? 1.0f
                    : kRealMinDist / (kRealMinDist + kRealRollOff * (distToListener - kRealMinDist));
                TriggerDistanceFootstep(au.footstepDistAccum, au.footstepNextIsLeft, aiTravel, aiActive, aiRunning,
                    archetype, pi.position, 1000000 + (int)n, gain * FOOTSTEP_GAIN);
            }
        }

        bool aiCollDeferred = false;
        AiLap(2);
        {
            uint64_t aiCollT0 = sceKernelGetProcessTimeWide();

            Vector3 aiStartPos(preMoveX, pi.position.m_Y, preMoveZ);
            if (intendedX * intendedX + intendedZ * intendedZ < 1e-8f)
                au.why = (uint8_t)(20 + (au.localPlanPending ? 1 : 0) + (au.localPathValid ? 2 : 0) + (au.avoidActive ? 4 : 0));

            bool aiSkipColl = false;
            {
                const float cdx = pi.position.m_X - playerPos.m_X, cdz = pi.position.m_Z - playerPos.m_Z;
                if (cdx * cdx + cdz * cdz > 25.0f * 25.0f)
                {
                    if (!au.collPending) { au.collStart = aiStartPos; au.collPending = true; }
                    if (((s_aiCollFrame + (uint32_t)n) % 3u) != 0u) aiSkipColl = true;
                    else { aiStartPos = Vector3(au.collStart.m_X, pi.position.m_Y, au.collStart.m_Z); au.collPending = false; }
                }
                else au.collPending = false;
            }

            if (!aiSkipColl && g_retailSoldierCollision)
            {
                RetailAIStep(au, pi, aiStartPos, deltaSec, uniqueModels, placedRef, terrainData);
                au.rscDone = true;
            }
            else if (!aiSkipColl)
            {

                const float aiPreResolveY = pi.position.m_Y;
                const Vector3 aiWantEnd = pi.position;
                ResolveSoldierCollisionZero(pi.position, aiStartPos, uniqueModels, placedRef, au.placedIndex);
                const float lift = pi.position.m_Y - aiPreResolveY;
                if (lift > 0.01f)
                {
                    ++g_aiResolverLiftCount;
                    if (lift > g_aiResolverLiftMax) g_aiResolverLiftMax = lift;
                }
                pi.position.m_Y = aiPreResolveY;

                const float wantX = aiWantEnd.m_X - aiStartPos.m_X, wantZ = aiWantEnd.m_Z - aiStartPos.m_Z;
                const float want2 = wantX * wantX + wantZ * wantZ;
                const float gotAlong = (pi.position.m_X - aiStartPos.m_X) * wantX + (pi.position.m_Z - aiStartPos.m_Z) * wantZ;
                if (want2 > 1e-6f && gotAlong < 0.5f * want2)
                {
                    const float AI_CURB_STEP = 0.45f;
                    Vector3 hiStart(aiStartPos.m_X, aiStartPos.m_Y + AI_CURB_STEP, aiStartPos.m_Z);
                    Vector3 hiEnd(aiWantEnd.m_X, aiWantEnd.m_Y + AI_CURB_STEP, aiWantEnd.m_Z);
                    ResolveSoldierCollisionZero(hiEnd, hiStart, uniqueModels, placedRef, au.placedIndex);
                    const float hiAlong = (hiEnd.m_X - aiStartPos.m_X) * wantX + (hiEnd.m_Z - aiStartPos.m_Z) * wantZ;
                    if (hiAlong > gotAlong + 1e-4f)
                    {
                        pi.position.m_X = hiEnd.m_X;
                        pi.position.m_Z = hiEnd.m_Z;
                        ++g_aiCurbSteps;
                    }
                }
            }
            aiCollDeferred = aiSkipColl;
            g_aiCollisionUs += sceKernelGetProcessTimeWide() - aiCollT0;
        }

        if (au.life == AI_LIFE_ALIVE && !pi.inVehicle)
            for (const DeathRegionInfo& dr : g_deathRegions)
                if (PointInRegion(dr.pos, dr.rot, dr.size, dr.type, pi.position))
                {
                    checkpointf("M480 AI unit %u (team %d) entered a death region at (%.1f, %.1f, %.1f)", (unsigned)n, pi.team, pi.position.m_X, pi.position.m_Y, pi.position.m_Z);
                    ApplyDamageToAIUnit(n, 1.0e6f, placedRef);
                    break;
                }

        if (au.life == AI_LIFE_ALIVE)
        {
            if (au.dmgRegionLog > 0) --au.dmgRegionLog;
            const PlacedInstance* dp = &pi;
            int dv = -1;
            if (au.vehicle >= 0 && (size_t)au.vehicle < g_vehicles.size()
                && g_vehicles[(size_t)au.vehicle].placedIndex < placedRef.size())
            {
                dv = au.vehicle;
                dp = &placedRef[g_vehicles[(size_t)dv].placedIndex];
            }
            const DamageRegionInfo* hitRegion = nullptr;
            const float dmg = DamageRegionDamageAt(dp->position, deltaSec, dv >= 0 ? 3 : 0, &hitRegion);
            if (dmg > 0.0f)
            {
                if (au.dmgRegionLog <= 0)
                {
                    checkpointf("LAVA AI unit %u (team %d) inside damage region \"%s\" at (%.1f, %.1f, %.1f), %.1f/s%s",
                        (unsigned)n, pi.team, hitRegion ? hitRegion->name.c_str() : "?", dp->position.m_X, dp->position.m_Y, dp->position.m_Z,
                        hitRegion ? hitRegion->rate * hitRegion->scale[dv >= 0 ? 3 : 0] : 0.0f, dv >= 0 ? " (in a vehicle - the vehicle goes too)" : "");
                    au.dmgRegionLog = 30;
                }
                if (dv >= 0) ApplyDamageToVehicle((size_t)dv, dmg, placedRef, "damage region");
                else
                {

                    const char* const savedSrc = g_damageSource;
                    g_damageSource = "damage region";
                    ApplyDamageToAIUnit(n, dmg, placedRef);
                    g_damageSource = savedSrc;
                }
            }
        }

        if (au.life == AI_LIFE_ALIVE)
        {
            const PlacedInstance* ep = &pi;
            int ev = -1;
            if (au.vehicle >= 0 && (size_t)au.vehicle < g_vehicles.size()
                && g_vehicles[(size_t)au.vehicle].placedIndex < placedRef.size())
            {
                ev = au.vehicle;
                ep = &placedRef[g_vehicles[(size_t)au.vehicle].placedIndex];
            }
            if (BoundsTimerTick(au.oobTimer, deltaSec, IsOutsideBattlefield(ep->position.m_X, ep->position.m_Z)))
            {
                ++g_boundsKillsAi;
                checkpointf("BOUNDS AI unit %u (team %d) killed after %.1f s outside the boundary at (%.1f, %.1f, %.1f)%s",
                    (unsigned)n, ep->team, BOUNDS_TIMER_SEC, ep->position.m_X, ep->position.m_Y, ep->position.m_Z,
                    ev >= 0 ? " (in a vehicle - the vehicle goes too)" : "");
                if (ev >= 0) ApplyDamageToVehicle((size_t)ev, 1.0e6f, placedRef, "out of bounds");
                else
                {

                    const char* const savedSrc = g_damageSource;
                    g_damageSource = "out of bounds";
                    ApplyDamageToAIUnit(n, 1.0e6f, placedRef);
                    g_damageSource = savedSrc;
                }
            }
        }
        if (pi.position.m_Y < LOST_BELOW_WORLD_Y)
        {
            checkpointf("MILESTONE 102 - AI unit u%u (team=%d) fell out of the world at (%.1f, %.1f, %.1f) - respawning",
                (unsigned)n, pi.team, pi.position.m_X, pi.position.m_Y, pi.position.m_Z);
            const CommandPostState* lostCp = nullptr;
            for (const CommandPostState& cp : g_commandPosts) { if (cp.team == au.homeTeam) { lostCp = &cp; break; } }
            if (lostCp == nullptr && !g_commandPosts.empty()) lostCp = &g_commandPosts[0];
            if (lostCp != nullptr)
            {
                pi.position = lostCp->position;

                au.rscBody = rsc::Body();
                au.rscBody.pos = rsc::V3(pi.position.m_X, pi.position.m_Y, pi.position.m_Z);
                au.rscDone = false;
                au.collPending = false;
            }
            au.navPath.clear(); au.navPathIndex = 0; au.navPathGoalCp = -1;
            g_aiDiagLostBelowWorld++;
        }

        AiLap(3);
        ApplyAIGroundContact(au, pi, deltaSec, terrainData, uniqueModels, placedRef, aiCollDeferred, n, preMoveX, preMoveZ);
        AiLap(4);

        ResolveCharacterVsCharacter(pi.position, placedRef, au.placedIndex, &playerPos);
        AiLap(5);

        {
            const float achievedX = pi.position.m_X - preMoveX;
            const float achievedZ = pi.position.m_Z - preMoveZ;
            const float achieved = sqrtf(achievedX * achievedX + achievedZ * achievedZ);
            const float intended = sqrtf(intendedX * intendedX + intendedZ * intendedZ);
            VehAvoidAiSample(au, pi, intended, achieved, deltaSec, placedRef);

            if (deltaSec > 0.0001f && au.movedThisFrame)
            {
                const float vPrev = sqrtf(au.velX * au.velX + au.velZ * au.velZ);
                float nvx = achievedX / deltaSec, nvz = achievedZ / deltaSec;
                const float vNew = sqrtf(nvx * nvx + nvz * nvz);
                if (vNew > vPrev && vNew > 0.0001f) { nvx *= vPrev / vNew; nvz *= vPrev / vNew; }
                au.velX = nvx; au.velZ = nvz;
            }

            {
                if (au.paceClock <= 0.0f) { au.paceStartX = preMoveX; au.paceStartZ = preMoveZ; au.paceTravel = 0.0f; }
                au.paceClock += deltaSec;
                au.paceTravel += achieved;
                if (au.paceClock >= 5.0f)
                {
                    const float ndx = pi.position.m_X - au.paceStartX, ndz = pi.position.m_Z - au.paceStartZ;
                    const float net = sqrtf(ndx * ndx + ndz * ndz);
                    static uint32_t s_paceTotal = 0;
                    if (au.paceTravel > 4.0f && net < 1.5f && au.paceLines < 6 && s_paceTotal < 200)
                    {
                        ++au.paceLines; ++s_paceTotal;
                        checkpointf("M377 pacing: unit=%u team=%d pos=(%.2f,%.2f,%.2f) walked=%.1fm net=%.2fm in 5s path=%d wp=%u/%u refuse(n=%u age=%.2f)",
                            (unsigned)n, pi.team, pi.position.m_X, pi.position.m_Y, pi.position.m_Z, au.paceTravel, net,
                            (int)au.localPathValid, (unsigned)au.localPathIndex, (unsigned)au.localPath.size(),
                            (unsigned)au.refuseCount, au.lastRefuseAge);
                    }
                    au.paceClock = 0.0f;
                }
            }

            if (intended > 0.02f && achieved < 0.3f * intended && dist < 15.0f)
            {
                for (const AIUnitState& o : g_aiUnits)
                {
                    if (&o == &au || o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
                    const PlacedInstance& op = placedRef[o.placedIndex];
                    if (op.team != pi.team) continue;
                    const float fx = op.position.m_X - pi.position.m_X, fz = op.position.m_Z - pi.position.m_Z;
                    if (fx * fx + fz * fz < 1.2f * 1.2f) { au.crowdTimer = 4.0f; break; }
                }
            }

            au.lastRefuseAge += deltaSec;
            if (au.planRetryBlockSec > 0.0f) au.planRetryBlockSec -= deltaSec;

            if ((int)n == g_bbTraceUnit && g_bbTraceLeft > 0.0f)
                checkpointf("BB trace u%u t-%.2f pos (%.2f,%.2f,%.2f) steer (%.2f,%.2f) %.2f int %.3f ach %.3f | route %u/%u hub %d wp (%.2f,%.2f) leg %u/%u | push (%.2f,%.2f) side %d | blk %u stk %u anchor %.1f best %.1f rw %d | why %d sec %d tgt %d hint %d crowd %.1f gnd %d",
                    (unsigned)n, g_bbTraceLeft, pi.position.m_X, pi.position.m_Y, pi.position.m_Z, steerX, steerZ, steerDist, intended, achieved,
                    (unsigned)au.navPathIndex, (unsigned)au.navPath.size(), au.rnHub, au.rnX, au.rnZ, (unsigned)au.rnLegIdx, (unsigned)(au.rnLeg.size() / 2),
                    au.rscBody.wallPush.x, au.rscBody.wallPush.z, (int)au.sideStep, au.rnBlocked, au.rnStuck, au.rnAnchorSec, au.rnBestSec, (int)au.rwActive,
                    (int)au.why, (int)au.exitSec, (int)au.haveCachedTarget, au.hintNodeIdx, au.crowdTimer, (int)au.rscBody.grounded);
            if (AITraceUnit(n))
            {
                static float s_traceClock[64] = {}, s_traceNext[64] = {};
                s_traceClock[n] += deltaSec;
                if (s_traceClock[n] <= 400.0f && s_traceClock[n] >= s_traceNext[n])
                {
                    s_traceNext[n] = s_traceClock[n] + (s_traceClock[n] < 20.0f ? 0.2f : 1.0f);
                    float wpX = 0.0f, wpZ = 0.0f;
                    if (au.localPathValid && au.localPathIndex < au.localPath.size())
                    { wpX = au.localPath[au.localPathIndex].m_X; wpZ = au.localPath[au.localPathIndex].m_Z; }
                    checkpointf("M344 trace u%u defer=%d t=%.1f pos=(%.2f,%.2f,%.2f) goalCp=%d hub=%u/%u path=%d wp=%u/%u next=(%.1f,%.1f) planFor=(%.1f,%.1f) cool=%.2f pend=%d intended=%.3f achieved=%.3f unstick=%.2f avoid=%d refuse(age=%.2f n=%u rise=%.2f)",
                        (unsigned)n, (int)aiCollDeferred, s_traceClock[n], pi.position.m_X, pi.position.m_Y, pi.position.m_Z,
                        au.navPathGoalCp, (unsigned)au.navPathIndex, (unsigned)au.navPath.size(),
                        (int)au.localPathValid, (unsigned)au.localPathIndex, (unsigned)au.localPath.size(), wpX, wpZ,
                        au.localPathTarget.m_X, au.localPathTarget.m_Z, au.localPlanCooldown, (int)au.localPlanPending,
                        intended, achieved, au.unstickTimer, (int)au.avoidActive,
                        au.lastRefuseAge, (unsigned)au.refuseCount, au.lastRefuseY - au.lastRefuseFeetY);
                    checkpointf("M366 combat u%u pose=%d cand=%d target=%d fireCd=%.2f poseSpeed=%.2f hint=%d",
                        (unsigned)n, (int)au.currentPose, (int)au.candidatePose, (int)au.haveCachedTarget,
                        au.fireCooldown, au.poseSpeed, au.hintNodeIdx);
                    checkpointf("M376 steer u%u facing=%.1f want=%.1f(have=%d) vel=(%.2f,%.2f) turnFactor=%.2f movedLast=%d",
                        (unsigned)n, (2.0f * atan2f(pi.rotation.m_Y, pi.rotation.m_W) - 3.14159265f) * 57.2957795f,
                        au.wantYaw * 57.2957795f, (int)au.haveWantYaw, au.velX, au.velZ, au.dbgTurnFactor, (int)au.movedLastFrame);
                    checkpointf("M346 why u%u steer=(%.2f,%.2f) preBarrier=(%.3f,%.3f) insideBarrier=%d barrierBranch=%d barStop=%.2f",
                        (unsigned)n, au.dbgSteerX, au.dbgSteerZ, au.dbgPreBarX, au.dbgPreBarZ,
                        (int)au.dbgInsideBar, (int)au.dbgBarBranch, au.barrierStopTime);
                }
            }
            if (intended > 0.0001f && achieved < intended * 0.35f)
            {
                au.stuckTimer += deltaSec;
                if (au.stuckTimer > 0.35f && au.unstickTimer <= 0.0f)
                {

                    au.unstickSign = ((n & 1) == 0) ? 1.0f : -1.0f;
                    au.unstickTimer = 1.2f;
                    au.stuckTimer = 0.0f;

                    {
                        const float sl = sqrtf(au.dbgSteerX * au.dbgSteerX + au.dbgSteerZ * au.dbgSteerZ);
                        if (sl > 0.001f)
                        {
                            const float fx = au.dbgSteerX / sl, fz = au.dbgSteerZ / sl;
                            float bestD = 0.95f, bAhead = 0.0f, bLat = 0.0f; bool bMoving = false, found = false;
                            for (const AIUnitState& o : g_aiUnits)
                            {
                                if (&o == &au || o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
                                const PlacedInstance& op = placedRef[o.placedIndex];
                                if (op.team != pi.team || op.inVehicle || fabsf(op.position.m_Y - pi.position.m_Y) > 1.5f) continue;
                                const float qx = op.position.m_X - pi.position.m_X, qz = op.position.m_Z - pi.position.m_Z;
                                const float q = sqrtf(qx * qx + qz * qz);
                                if (q >= bestD) continue;
                                bestD = q; bAhead = qx * fx + qz * fz; bLat = qx * -fz + qz * fx; bMoving = o.movedLastFrame; found = true;
                            }
                            if (found)
                            {

                                if (fabsf(bLat) > 0.12f) au.unstickSign = (bLat > 0.0f) ? -1.0f : 1.0f;
                                if (bAhead > 0.3f && bMoving) { au.yieldSec = 0.5f + 0.1f * (float)(n % 5); au.unstickTimer = 0.0f; }
                                ++g_aiDiagYield;
                            }
                        }
                    }

                    if (au.localPathValid) { au.localPathValid = false; au.localPlanCooldown = 1.3f; }

                    if (g_aiStuckDiagCount < 200 && au.stuckDiagLines < 4)
                    {
                        float cpDist = 1e9f; const char* cpName = "-";
                        for (const CommandPostState& cps : g_commandPosts)
                        {
                            const float cdx = cps.position.m_X - pi.position.m_X;
                            const float cdz = cps.position.m_Z - pi.position.m_Z;
                            const float cd = sqrtf(cdx * cdx + cdz * cdz);
                            if (cd < cpDist) { cpDist = cd; cpName = cps.name.c_str(); }
                        }
                        const char* refModel = "-";
                        if (au.lastRefusePlaced < placedRef.size() && placedRef[au.lastRefusePlaced].modelIndex < uniqueModels.size())
                            refModel = uniqueModels[placedRef[au.lastRefusePlaced].modelIndex].debugName.c_str();
                        float wpX = 0.0f, wpZ = 0.0f;
                        if (au.localPathValid && au.localPathIndex < au.localPath.size())
                        { wpX = au.localPath[au.localPathIndex].m_X; wpZ = au.localPath[au.localPathIndex].m_Z; }
                        g_aiStuckDiagCount++;
                        au.stuckDiagLines++;
                        checkpointf("M337 aiStuck: unit=%u team=%d cp=\"%s\"@%.1fm pos=(%.2f,%.2f,%.2f) intended=%.3f achieved=%.3f avoid=%d "
                                    "path=%d wp=%u/%u next=(%.1f,%.1f) pending=%d cool=%.2f "
                                    "refuse: age=%.2fs n=%u surfY=%.2f feetY=%.2f (rise %.2f) model=%s",
                            (unsigned)n, pi.team, cpName, cpDist,
                            pi.position.m_X, pi.position.m_Y, pi.position.m_Z,
                            intended, achieved, (int)au.avoidActive,
                            (int)au.localPathValid, (unsigned)au.localPathIndex, (unsigned)au.localPath.size(), wpX, wpZ,
                            (int)au.localPlanPending, au.localPlanCooldown,
                            au.lastRefuseAge, (unsigned)au.refuseCount, au.lastRefuseY, au.lastRefuseFeetY,
                            au.lastRefuseY - au.lastRefuseFeetY, refModel);

                        {
                            size_t nb = SIZE_MAX; float nd = 1e9f;
                            for (size_t oi = 0; oi < g_aiUnits.size(); ++oi)
                            {
                                const AIUnitState& o = g_aiUnits[oi];
                                if (&o == &au || o.life != AI_LIFE_ALIVE || o.placedIndex >= placedRef.size()) continue;
                                const Vector3& op = placedRef[o.placedIndex].position;
                                const float qx = op.m_X - pi.position.m_X, qz = op.m_Z - pi.position.m_Z, q = sqrtf(qx * qx + qz * qz);
                                if (q < nd) { nd = q; nb = oi; }
                            }
                            const float sx = au.dbgSteerX, sz = au.dbgSteerZ, sl = sqrtf(sx * sx + sz * sz) + 1e-6f;
                            float ahead = 0.0f, lat = 0.0f;
                            if (nb != SIZE_MAX)
                            {
                                const Vector3& op = placedRef[g_aiUnits[nb].placedIndex].position;
                                const float qx = op.m_X - pi.position.m_X, qz = op.m_Z - pi.position.m_Z;
                                ahead = (qx * sx + qz * sz) / sl; lat = (qx * -sz + qz * sx) / sl;
                            }
                            checkpointf("M493 stuck-near: unit=%u cls=%s turn=%.2f eng=%d adv=%.1f hold=%.1f | nearest unit=%d team=%d at %.2fm (ahead %.2f, side %.2f) moving=%d eng=%d player=%.2fm",
                                (unsigned)n, pi.unitClass.c_str(), au.dbgTurnFactor, (int)au.haveCachedTarget, au.advanceSec, au.hintHoldTime,
                                nb == SIZE_MAX ? -1 : (int)nb, nb == SIZE_MAX ? -1 : placedRef[g_aiUnits[nb].placedIndex].team, nd, ahead, lat,
                                nb == SIZE_MAX ? 0 : (int)g_aiUnits[nb].movedLastFrame, nb == SIZE_MAX ? 0 : (int)g_aiUnits[nb].haveCachedTarget,
                                g_playerBlastPosValid ? sqrtf((g_playerBlastPos.m_X - pi.position.m_X) * (g_playerBlastPos.m_X - pi.position.m_X) + (g_playerBlastPos.m_Z - pi.position.m_Z) * (g_playerBlastPos.m_Z - pi.position.m_Z)) : -1.0f);
                        }
                    }
                }
            }
            else
            {
                au.stuckTimer = 0.0f;
            }
            g_aiDiagStuck += (au.unstickTimer > 0.0f) ? 1 : 0;
        }
        g_aiDiagWithPath += au.navPath.empty() ? 0 : 1;
        g_aiDiagActive++;

        {
            float faceX = dx, faceZ = dz;
            if (au.lastPosValid)
            {
                const float mvx = pi.position.m_X - au.lastPos.m_X;
                const float mvz = pi.position.m_Z - au.lastPos.m_Z;
                if (mvx * mvx + mvz * mvz > 0.0004f) { faceX = mvx; faceZ = mvz; }
            }

            (void)faceX; (void)faceZ;
        }
    }
    if (!g_aiUnits.empty()) g_aiUnits.back().exitSec = (int8_t)g_aiLapSec;
    AiLap(-1);

    for (size_t n = 0; n < g_aiUnits.size(); ++n)
    {
        AIUnitState& au = g_aiUnits[n];
        if (au.life != AI_LIFE_ALIVE || au.placedIndex >= placedRef.size()) { au.stillClock = 0.0f; continue; }
        const PlacedInstance& pi = placedRef[au.placedIndex];
        const float sdx = pi.position.m_X - au.stillX, sdz = pi.position.m_Z - au.stillZ;
        bool holding = au.haveCachedTarget || au.hintNodeIdx >= 0 || au.actionTimer > 0.0f;
        if (au.targetIsDefend && au.cachedTargetCpIndex >= 0 && (size_t)au.cachedTargetCpIndex < g_commandPosts.size())
        {
            const Vector3& cpp = g_commandPosts[(size_t)au.cachedTargetCpIndex].position;
            const float gx = cpp.m_X - pi.position.m_X, gz = cpp.m_Z - pi.position.m_Z;
            if (gx * gx + gz * gz < 25.0f * 25.0f) holding = true;
        }
        if (holding || sdx * sdx + sdz * sdz > 1.0f) { au.stillClock = 0.0f; au.stillX = pi.position.m_X; au.stillZ = pi.position.m_Z; continue; }
        au.stillClock += deltaSec;
        static uint32_t s_stillTotal = 0;
        if (au.stillClock >= 8.0f && au.stillLines < 6 && s_stillTotal < 200)
        {
            ++au.stillLines; ++s_stillTotal;
            float wpX = 0.0f, wpZ = 0.0f;
            if (au.localPathValid && au.localPathIndex < au.localPath.size()) { wpX = au.localPath[au.localPathIndex].m_X; wpZ = au.localPath[au.localPathIndex].m_Z; }
            checkpointf("M414 standing: unit=%u team=%d cp=%d pos=(%.2f,%.2f,%.2f) 8s still | path=%d wp=%u/%u next=(%.1f,%.1f) pend=%d cool=%.2f hub=%u/%u unstick=%.2f avoid=%d barStop=%.2f insideBar=%d branch=%d steer=(%.2f,%.2f) intended=(%.3f,%.3f) refuse(n=%u age=%.1f rise=%.2f)",
                (unsigned)n, pi.team, au.cachedTargetCpIndex, pi.position.m_X, pi.position.m_Y, pi.position.m_Z,
                (int)au.localPathValid, (unsigned)au.localPathIndex, (unsigned)au.localPath.size(), wpX, wpZ,
                (int)au.localPlanPending, au.localPlanCooldown, (unsigned)au.navPathIndex, (unsigned)au.navPath.size(),
                au.unstickTimer, (int)au.avoidActive, au.barrierStopTime, (int)au.dbgInsideBar, (int)au.dbgBarBranch,
                au.dbgSteerX, au.dbgSteerZ, au.dbgPreBarX, au.dbgPreBarZ,
                (unsigned)au.refuseCount, au.lastRefuseAge, au.lastRefuseY - au.lastRefuseFeetY);
            au.stillClock = 0.0f;
        }
    }

    for (size_t n = 0; n < g_aiUnits.size(); ++n)
    {
        AIUnitState& au = g_aiUnits[n];
        if (au.movedThisFrame || au.life != AI_LIFE_ALIVE || au.placedIndex >= placedRef.size() || au.jumpLeg) continue;

        const bool airborne = g_retailSoldierCollision && !au.rscBody.grounded;
        if (!airborne && ((s_aiCollFrame + (uint32_t)n) & 7u) != 0u) continue;
        PlacedInstance& pi = placedRef[au.placedIndex];
        if (pi.team < 0 || pi.isDroideka) continue;
        ApplyAIGroundContact(au, pi, deltaSec, terrainData, uniqueModels, placedRef,  false, n,
                             pi.position.m_X, pi.position.m_Z);
    }

    for (size_t n2 = 0; n2 < g_aiUnits.size(); ++n2)
    {
        AIUnitState& au = g_aiUnits[n2];
        if (au.placedIndex >= placedRef.size()) continue;
        PlacedInstance& pi = placedRef[au.placedIndex];
        if (pi.team < 0) continue;

        if (au.life != AI_LIFE_ALIVE) continue;
        if (au.pcPrevValid)
        {
            const float wx = pi.position.m_X - au.pcPrev.m_X, wz = pi.position.m_Z - au.pcPrev.m_Z;
            const float wd = sqrtf(wx * wx + wz * wz);
            if (wd < 2.0f) au.pcWalk += wd;
        }
        au.pcPrev = pi.position; au.pcPrevValid = true;

        if (pi.inVehicle) au.facingDiagValid = false;
        else if (au.haveWantYaw && !pi.isDroideka)
        {

            if (au.facingDiagValid)
            { const float drawnNow = 2.0f * atan2f(pi.rotation.m_Y, pi.rotation.m_W) - 3.14159265f; if (fabsf(AngleDiff(au.lastBodyYaw, drawnNow)) > 0.349f) ++g_faceForeign; }
            if (!au.aimYawValid) { au.aimYaw = 2.0f * atan2f(pi.rotation.m_Y, pi.rotation.m_W) - 3.14159265f; au.aimYawValid = true; if (au.facingDiagValid) ++g_faceAimReset; }
            const float aimBefore = au.aimYaw;
            float d = AngleDiff(au.aimYaw, au.wantYaw);
            const float maxStep = g_soldierMaxTurnSpeed * deltaSec;
            if (fabsf(d) > maxStep) ++g_aiTurningFrames;
            if (d > maxStep) d = maxStep; else if (d < -maxStep) d = -maxStep;
            au.aimYaw = WrapAngle(au.aimYaw + d);
            float legTarget = 0.0f;
            const float mv2 = au.velX * au.velX + au.velZ * au.velZ;
            if (au.movedLastFrame && mv2 > 0.25f)
            {
                const float moveYaw = atan2f(-au.velX, -au.velZ);
                const float rel = AngleDiff(au.aimYaw, moveYaw);
                if (!au.backpedal && fabsf(rel) > 1.7453293f) au.backpedal = true;
                else if (au.backpedal && fabsf(rel) < 1.3962634f) au.backpedal = false;
                float leg = au.backpedal ? rel - copysignf(3.14159265f, rel) : rel;
                const float LEG_TURN_LIMIT = 0.96f;
                if (leg > LEG_TURN_LIMIT) leg = LEG_TURN_LIMIT; else if (leg < -LEG_TURN_LIMIT) leg = -LEG_TURN_LIMIT;
                legTarget = leg;
            }
            else au.backpedal = false;

            { float dl = legTarget - au.legYaw; if (dl > maxStep) dl = maxStep; else if (dl < -maxStep) dl = -maxStep; au.legYaw += dl; }
            float body = WrapAngle(au.aimYaw + au.legYaw);
            au.torsoTwist = AngleDiff(body, au.aimYaw);

            if (au.facingDiagValid)
            {
                if (fabsf(AngleDiff(au.lastBodyYaw, body)) > 0.349f) { ++g_faceSnaps; if (fabsf(AngleDiff(aimBefore, au.aimYaw)) > 0.349f) ++g_faceSnapAim;
                    static int s_snapLog = 0; if (s_snapLog < 6) { ++s_snapLog; checkpointf("FACING snap u%u: lastBody %.3f body %.3f | aim %.3f -> %.3f leg %.3f (target %.3f) dt %.3f want %.3f", (unsigned)n2, au.lastBodyYaw, body, aimBefore, au.aimYaw, au.legYaw, legTarget, deltaSec, au.wantYaw); } }
                if (fabsf(AngleDiff(au.lastWantYaw, au.wantYaw)) > 1.5708f)
                {
                    ++g_faceFlips; ++g_faceFlipPair[au.lastWantSrc & 15][au.wantSrc & 15];
                    if (au.wantSrc == 6 && au.lastWantSrc == 6)
                        ++g_flip66By[au.rwActive ? 1 : au.sideStep ? 2 : au.cmMode == 3 ? 3 : (au.apArrived && au.apTested) ? 4 : au.hintKind == 2 ? 5
                                     : (au.routeDoneGoal >= 0 && au.navPathIndex >= au.navPath.size()) ? 6 : au.hintKind == 1 ? 7 : 0];
                }
                ++g_faceFrames;
            }
            au.lastBodyYaw = body; au.lastWantYaw = au.wantYaw; au.lastWantSrc = au.wantSrc; au.facingDiagValid = true;
            pi.rotation = ModelQuatFromFacingYaw(body);
        }
        else if (au.haveWantYaw)
        {
            pi.rotation = ModelQuatFromFacingYaw(au.wantYaw);
        }
        auto vit = g_aiPoseVariants.find(au.baseModelIndex);
        if (vit == g_aiPoseVariants.end()) continue;

        float inst = 0.0f;
        if (au.lastPosValid && deltaSec > 0.0001f)
        {
            const float mx = pi.position.m_X - au.lastPos.m_X;
            const float mz = pi.position.m_Z - au.lastPos.m_Z;
            inst = sqrtf(mx * mx + mz * mz) / deltaSec;
        }

        if (au.movedThisFrame) au.stillSec = 0.0f; else au.stillSec += deltaSec;
        const bool stoppedOnPurpose = au.stillSec >= 0.1f;
        if (!stoppedOnPurpose && (au.barrierStopTime > 0.0f || au.avoidActive)) inst = fmaxf(inst, g_soldierMaxSpeed * 0.5f);
        au.poseSpeed += (inst - au.poseSpeed) * fminf(1.0f, deltaSec * 6.0f);
        if (stoppedOnPurpose) au.poseSpeed = 0.0f;

        const float RUN_SPEED = g_soldierMaxSpeed * 0.66f;
        const float MOVE_SPEED = 0.35f;

        int pose;
        const bool wasMoving = (au.currentPose == AIPOSE_WALK || au.currentPose == AIPOSE_RUN);
        const bool wasRunning = (au.currentPose == AIPOSE_RUN);
        const float enterMove = wasMoving ? MOVE_SPEED * 0.6f : MOVE_SPEED;
        const float enterRun  = wasRunning ? RUN_SPEED * 0.8f : RUN_SPEED;

        if (au.hintKind == 2 && au.hintAt && au.poseSpeed < enterMove)
            pose = au.coverCrouch ? AIPOSE_CROUCH : AIPOSE_SHOOT;
        else if (au.haveCachedTarget && au.cmMode == 2 && au.styleN >= 0 && au.styleN % 3 == 1 && au.poseSpeed < enterMove)
            pose = AIPOSE_CROUCH;

        else if ((au.fireCooldown > 0.0f || au.haveCachedTarget) && au.poseSpeed < enterMove)
            pose = AIPOSE_SHOOT;
        else if (au.hintNodeIdx >= 0 && au.poseSpeed < enterMove)
            pose = AIPOSE_CROUCH;
        else if (au.poseSpeed >= enterRun)
            pose = AIPOSE_RUN;
        else if (au.poseSpeed >= enterMove)
            pose = AIPOSE_WALK;
        else
            pose = AIPOSE_IDLE;

        const float POSE_DEBOUNCE_SEC =
            (pose == AIPOSE_IDLE && (au.currentPose == AIPOSE_WALK || au.currentPose == AIPOSE_RUN) && !stoppedOnPurpose)
                ? 0.75f
                : 0.10f;
        if (pose != au.candidatePose)
        {
            au.candidatePose = pose;
            au.candidateHoldSec = 0.0f;
        }
        else
        {
            au.candidateHoldSec += deltaSec;
        }
        if (au.candidatePose != au.currentPose && au.candidateHoldSec >= POSE_DEBOUNCE_SEC)
        {
            au.currentPose = au.candidatePose;
        }

        if (au.throwPoseTimer > 0.0f && au.life == AI_LIFE_ALIVE)
        {
            au.throwPoseTimer -= deltaSec;
            au.currentPose = AIPOSE_THROW;
            au.candidatePose = AIPOSE_THROW;
        }
        if (au.flyer && au.airborne && au.life == AI_LIFE_ALIVE)
        {
            au.currentPose = AIPOSE_HOVER;
            au.candidatePose = AIPOSE_HOVER;
        }
        if (au.thrown && au.life == AI_LIFE_ALIVE)
        {
            au.currentPose = AIPOSE_THROWN;
            au.candidatePose = AIPOSE_THROWN;
        }

        pi.modelIndex = (au.ownModelIndex != (size_t)-1)
            ? au.ownModelIndex
            : vit->second[(size_t)au.currentPose];

        au.lastPos = pi.position;
        au.lastPosValid = true;
    }

}

static void Mat4Multiply(const float a[16], const float b[16], float out[16])
{
    for (int col = 0; col < 4; ++col)
    {
        for (int row = 0; row < 4; ++row)
        {
            float sum = 0.0f;
            for (int k = 0; k < 4; ++k)
            {
                sum += a[k * 4 + row] * b[col * 4 + k];
            }
            out[col * 4 + row] = sum;
        }
    }
}

struct InstFade { int32_t model = -1; float vis = 0.0f, lod = 0.0f; };

struct RenderQueueItem
{
    uint32_t key = 0;
    const ModelData* md = nullptr;
    const SegmentData* sd = nullptr;
    bool skinned = false;
    float model[16];
    float col[4];
    float fade[2] = { 0.0f, 2.0f };
};
static std::vector<RenderQueueItem> g_renderQueue;

static bool IsOpaqueEligible(const RenderQueueItem& it)
{
    if (!g_worldOpaqueOk || g_fragab >= 0 || (g_dbgSkip & (32768 | 65536))) return false;
    if (it.skinned || it.sd->interleavedVbo == 0) return false;
    if (it.sd->hardedged || it.sd->transparent) return false;
    return it.fade[0] <= 0.0f && it.fade[1] >= 1.0f;
}

static bool IsOpaqueSkinnedEligible(const RenderQueueItem& it)
{
    if (!g_skinOpaqueOk || (g_dbgSkip & 262144)) return false;
    if (!it.skinned) return false;
    if (it.sd->hardedged || it.sd->transparent) return false;
    return it.fade[0] <= 0.0f && it.fade[1] >= 1.0f;
}

