static void KeepAwakeForTests()
{
    static int s_on = -1; static uint64_t s_lastUs = 0;
    if (s_on < 0)
    {
        FILE* f = fopen("ux0:data/swbf2/autotest.txt", "r");
        if (f == nullptr) f = fopen("ux0:data/swbf2/nosleep.txt", "r");
        s_on = (f != nullptr) ? 1 : 0;
        if (f) fclose(f);
    }
    if (s_on == 0) return;
    const uint64_t now = sceKernelGetProcessTimeWide();
    if (now - s_lastUs < 1000000ull) return;
    s_lastUs = now;
    sceKernelPowerTick(SCE_KERNEL_POWER_TICK_DISABLE_AUTO_SUSPEND);
}
