static float TerrainCellMeters(const TerrainData& td)
{
    std::vector<float> e;
    const uint32_t triCount = td.iCount / 3;
    for (uint32_t t = 0; t < triCount && e.size() < 2048; ++t)
    {
        float m = 1e30f;
        for (int k = 0; k < 3; ++k)
        {
            const Vector3& a = td.verts[td.indices[t * 3 + k]]; const Vector3& b = td.verts[td.indices[t * 3 + (k + 1) % 3]];
            const float dx = fabsf(a.m_X - b.m_X), dz = fabsf(a.m_Z - b.m_Z);
            if (dx > 0.01f) m = fminf(m, dx);
            if (dz > 0.01f) m = fminf(m, dz);
        }
        if (m < 1e29f) e.push_back(m);
    }
    if (e.empty()) return 8.0f;
    std::nth_element(e.begin(), e.begin() + e.size() / 2, e.end());
    return e[e.size() / 2];
}

static void BuildTerrainPatches(TerrainData& td, std::vector<uint32_t>& outIndices)
{
    td.patches.clear();
    outIndices.clear();
    const uint32_t triCount = td.iCount / 3;
    if (triCount == 0 || td.indices == nullptr || td.verts == nullptr) return;
    float minX = 1e30f, minZ = 1e30f, maxX = -1e30f, maxZ = -1e30f;
    for (uint32_t v = 0; v < td.vCount; ++v)
    {
        minX = fminf(minX, td.verts[v].m_X); maxX = fmaxf(maxX, td.verts[v].m_X);
        minZ = fminf(minZ, td.verts[v].m_Z); maxZ = fmaxf(maxZ, td.verts[v].m_Z);
    }
    const float TERRAIN_PATCH_METERS = g_terrainPatchMeters;
    const int nx = (int)ceilf((maxX - minX) / TERRAIN_PATCH_METERS + 1e-3f);
    const int nz = (int)ceilf((maxZ - minZ) / TERRAIN_PATCH_METERS + 1e-3f);

    std::vector<uint32_t> patchOf(triCount);
    std::vector<uint32_t> countOf((size_t)(nx * nz), 0);
    for (uint32_t t = 0; t < triCount; ++t)
    {
        const Vector3& a = td.verts[td.indices[t * 3]]; const Vector3& b = td.verts[td.indices[t * 3 + 1]]; const Vector3& c = td.verts[td.indices[t * 3 + 2]];
        int px = (int)(((a.m_X + b.m_X + c.m_X) / 3.0f - minX) / TERRAIN_PATCH_METERS);
        int pz = (int)(((a.m_Z + b.m_Z + c.m_Z) / 3.0f - minZ) / TERRAIN_PATCH_METERS);
        px = px < 0 ? 0 : (px >= nx ? nx - 1 : px); pz = pz < 0 ? 0 : (pz >= nz ? nz - 1 : pz);
        patchOf[t] = (uint32_t)(pz * nx + px);
        ++countOf[patchOf[t]];
    }
    std::vector<uint32_t> firstOf((size_t)(nx * nz), 0);
    uint32_t run = 0;
    for (size_t pi = 0; pi < countOf.size(); ++pi) { firstOf[pi] = run; run += countOf[pi] * 3; }
    outIndices.resize((size_t)triCount * 3);
    std::vector<uint32_t> fill = firstOf;
    for (size_t pi = 0; pi < countOf.size(); ++pi)
    {
        TerrainData::Patch p; p.first = firstOf[pi]; p.count = countOf[pi] * 3;
        p.minX = p.minY = p.minZ = 1e30f; p.maxX = p.maxY = p.maxZ = -1e30f;
        td.patches.push_back(p);
    }
    for (uint32_t t = 0; t < triCount; ++t)
    {
        TerrainData::Patch& p = td.patches[patchOf[t]];
        for (int k = 0; k < 3; ++k)
        {
            const uint32_t vi = td.indices[t * 3 + k];
            outIndices[fill[patchOf[t]]++] = vi;
            const Vector3& v = td.verts[vi];
            p.minX = fminf(p.minX, v.m_X); p.maxX = fmaxf(p.maxX, v.m_X);
            p.minY = fminf(p.minY, v.m_Y); p.maxY = fmaxf(p.maxY, v.m_Y);
            p.minZ = fminf(p.minZ, v.m_Z); p.maxZ = fmaxf(p.maxZ, v.m_Z);
        }
    }
    checkpointf("M456 terrain patches: %d x %d of %.0f m, %u triangles", nx, nz, TERRAIN_PATCH_METERS, triCount);
}

static void SplitTerrainPatchesByLayer(TerrainData& td, std::vector<uint32_t>& idx)
{
    if (td.blendWeights.empty() || td.patches.empty() || idx.empty()) return;
    std::vector<uint32_t> bucket[6];
    uint32_t trisByLayer[6] = { 0, 0, 0, 0, 0, 0 };
    for (TerrainData::Patch& p : td.patches)
    {
        p.runs = 0;
        const uint32_t triCount = p.count / 3;
        if (triCount == 0 || (size_t)p.first + p.count > idx.size()) continue;
        for (int g = 0; g < 6; ++g) bucket[g].clear();
        for (uint32_t t = 0; t < triCount; ++t)
        {
            const uint32_t base = p.first + t * 3;
            uint32_t mask = 0;
            for (int k = 0; k < 3; ++k)
            {
                const uint32_t vi = idx[base + (uint32_t)k];
                if (vi >= td.vCount) continue;
                const float* w = &td.blendWeights[(size_t)vi * TerrainData::MAX_BLEND_LAYERS];
                for (int i = 0; i < TerrainData::MAX_BLEND_LAYERS; ++i) if (w[i] != 0.0f) mask |= 1u << i;
            }
            int g = 5;
            if (mask != 0 && (mask & (mask - 1)) == 0) { g = 0; while ((mask & (1u << g)) == 0) ++g; }
            bucket[g].push_back(idx[base]); bucket[g].push_back(idx[base + 1]); bucket[g].push_back(idx[base + 2]);
            ++trisByLayer[g];
        }
        uint32_t at = p.first;
        for (int g = 0; g < 6; ++g)
        {
            if (bucket[g].empty()) continue;
            p.runLayer[p.runs] = (uint8_t)g;
            p.runFirst[p.runs] = at;
            p.runCount[p.runs] = (uint32_t)bucket[g].size();
            ++p.runs;
            std::copy(bucket[g].begin(), bucket[g].end(), idx.begin() + at);
            at += (uint32_t)bucket[g].size();
        }
    }
    checkpointf("M536 terrain layer split: single-layer tris L0..L4 %u/%u/%u/%u/%u, mixed %u (%.1f%% one fetch)",
                trisByLayer[0], trisByLayer[1], trisByLayer[2], trisByLayer[3], trisByLayer[4], trisByLayer[5],
                100.0f * (float)(td.iCount / 3 - trisByLayer[5]) / (float)(td.iCount / 3 ? td.iCount / 3 : 1));
}

static void DrawTerrainPatches(const TerrainData& td, const FrustumPlane fr[6], const Vector3& cam,
                               bool useRuns, const uint8_t* litFlags,
                               void (*setLayer)(void*, int, int), void* layerUser)
{
    if (g_terrainSkip) { g_terrainPatchesDrawn = 0; g_terrainTrisDrawn = 0; g_terrainLitCulled = 0; return; }
    uint32_t runFirst = 0, runCount = 0, patches = 0, idx = 0;
    int runLayer = -1, runLit = -1;
    auto flush = [&]() {
        if (runCount)
        {
            if (setLayer) setLayer(layerUser, runLayer, runLit);
            glDrawElements(GL_TRIANGLES, runCount, GL_UNSIGNED_INT, (const void*)(uintptr_t)(runFirst * sizeof(uint32_t)));
        }
        runCount = 0;
    };
    size_t patchIndex = 0;
    for (const TerrainData::Patch& p : td.patches)
    {
        const int lit = litFlags ? (int)litFlags[patchIndex] : 1;
        ++patchIndex;
        if (lit == 0xFF) continue;
        bool vis = p.count > 0;
        if (vis)
        {
            const Vector3 c((p.minX + p.maxX) * 0.5f, (p.minY + p.maxY) * 0.5f, (p.minZ + p.maxZ) * 0.5f);
            const float hx = (p.maxX - p.minX) * 0.5f, hy = (p.maxY - p.minY) * 0.5f, hz = (p.maxZ - p.minZ) * 0.5f;
            vis = SphereInFrustum(fr, c, sqrtf(hx * hx + hy * hy + hz * hz));
            if (vis)
            {
                const float dx = fmaxf(0.0f, fmaxf(p.minX - cam.m_X, cam.m_X - p.maxX));
                const float dy = fmaxf(0.0f, fmaxf(p.minY - cam.m_Y, cam.m_Y - p.maxY));
                const float dz = fmaxf(0.0f, fmaxf(p.minZ - cam.m_Z, cam.m_Z - p.maxZ));
                vis = (dx * dx + dy * dy + dz * dz) <= TERRAIN_FAR_SCENE_RANGE * TERRAIN_FAR_SCENE_RANGE;
            }
        }
        if (!vis) continue;
        ++patches; idx += p.count;
        if (!lit) ++g_terrainLitCulled;
        if (patches == 1) g_terrainLitCulled = lit ? 0 : 1;
        const bool layered = useRuns && p.runs > 0;
        const int n = layered ? (int)p.runs : 1;
        for (int r = 0; r < n; ++r)
        {
            const uint32_t rf = layered ? p.runFirst[r] : p.first;
            const uint32_t rc = layered ? p.runCount[r] : p.count;
            const int rl = layered ? (int)p.runLayer[r] : -1;
            if (runCount && rl == runLayer && lit == runLit && runFirst + runCount == rf) runCount += rc;
            else { flush(); runFirst = rf; runCount = rc; runLayer = rl; runLit = lit; }
        }
    }
    flush();
    if (td.patches.empty()) glDrawElements(GL_TRIANGLES, td.iCount, GL_UNSIGNED_INT, (const void*)0);
    g_terrainPatchesDrawn = patches; g_terrainTrisDrawn = idx / 3;
}

static GLuint LoadTerrainShader(const char* baseName, const char* defines = nullptr)
{
    char fname[256];
    char errmsg[160];
    snprintf(fname, sizeof(fname), "app0:%s.vert", baseName);
    FILE* vf = fopen(fname, "r");
    if (vf == nullptr)
    {
        snprintf(errmsg, sizeof(errmsg), "checkpoint: terrain shader (%s) FAILED - could not open %s", baseName, fname);
        checkpoint(errmsg);
        return 0;
    }
    fseek(vf, 0, SEEK_END);
    long vsize = ftell(vf);
    fseek(vf, 0, SEEK_SET);
    char* vsrc = (char*)malloc(vsize);
    fread(vsrc, 1, vsize, vf);
    fclose(vf);

    snprintf(fname, sizeof(fname), "app0:%s.frag", baseName);
    FILE* ff = fopen(fname, "r");
    if (ff == nullptr)
    {
        snprintf(errmsg, sizeof(errmsg), "checkpoint: terrain shader (%s) FAILED - could not open %s", baseName, fname);
        checkpoint(errmsg);
        free(vsrc);
        return 0;
    }
    fseek(ff, 0, SEEK_END);
    long fsize = ftell(ff);
    fseek(ff, 0, SEEK_SET);
    char* fsrc = (char*)malloc(fsize);
    fread(fsrc, 1, fsize, ff);
    fclose(ff);

    GLuint vshader = glCreateShader(GL_CG_VERTEX_SHADER_EXT);
    GLuint fshader = glCreateShader(GL_CG_FRAGMENT_SHADER_EXT);
    GLuint program = glCreateProgram();

    if (defines != nullptr && defines[0] != '\0')
    {
        const long dn = (long)strlen(defines);
        char* v2 = (char*)malloc(dn + vsize); memcpy(v2, defines, dn); memcpy(v2 + dn, vsrc, vsize); free(vsrc); vsrc = v2; vsize += dn;
        char* f2 = (char*)malloc(dn + fsize); memcpy(f2, defines, dn); memcpy(f2 + dn, fsrc, fsize); free(fsrc); fsrc = f2; fsize += dn;
    }
    GLint vsizeGL = (GLint)vsize;
    GLint fsizeGL = (GLint)fsize;
    const char* vsrcPtr = vsrc;
    const char* fsrcPtr = fsrc;
    CompileCgCached(vshader, vsrcPtr, vsizeGL);
    CompileCgCached(fshader, fsrcPtr, fsizeGL);
    free(vsrc);
    free(fsrc);

    GLint vok = 0, fok = 0;
    glGetShaderiv(vshader, GL_COMPILE_STATUS, &vok);
    glGetShaderiv(fshader, GL_COMPILE_STATUS, &fok);
    {
        char msg[128];
        snprintf(msg, sizeof(msg), "checkpoint: terrain shader (%s) compile status: vertex=%d fragment=%d", baseName, vok, fok);
        checkpoint(msg);
    }
    if (!vok || !fok)
    {
        return 0;
    }

    glAttachShader(program, vshader);
    glAttachShader(program, fshader);
    glBindAttribLocation(program, 0, "position");
    glBindAttribLocation(program, 1, "texcoord");
    glBindAttribLocation(program, 2, "weights0123");
    glBindAttribLocation(program, 3, "weight4");
    glBindAttribLocation(program, 4, "normal");
    glBindAttribLocation(program, 5, "color");
    glLinkProgram(program);

    GLint linkOk = 0;
    glGetProgramiv(program, GL_LINK_STATUS, &linkOk);
    {
        char msg[128];
        snprintf(msg, sizeof(msg), "checkpoint: terrain shader (%s) link status=%d", baseName, linkOk);
        checkpoint(msg);
    }
    if (!linkOk)
    {
        return 0;
    }

    return program;
}

