static bool g_heroAssaultAlways = false;
static bool ShellMissionIsHeroMode(const std::string& m)
{
    return m.size() > 4 && m.compare(m.size() - 4, 4, "_eli") == 0;
}
static bool ShellMissionBuiltWith(const std::string& m, bool heroesOn)
{
    bool built = false;
    for (const char* b : kShellBuiltMissions) if (m == b) { built = true; break; }
    if (!built) return false;
    if (ShellMissionIsHeroMode(m) && !heroesOn && !g_heroAssaultAlways) return false;
    return true;
}
static bool ShellMissionBuilt(const std::string& m) { return ShellMissionBuiltWith(m, g_heroesEnabled); }

struct ShellMapRow { std::string luafile, name; std::set<std::string> flags; };
struct ShellModeRow { std::string key, showstr, descstr, subst, icon; bool wildcard = false; };
struct ShellEraRow { std::string key, showstr, subst, icon1; bool wildcard = false; };
static std::vector<ShellMapRow> g_shellMaps;
static std::vector<ShellModeRow> g_shellModeDefs;
static std::vector<ShellEraRow> g_shellEraDefs;

static std::string ShellMissionName(const std::string& luafile, const std::string& era, const std::string& mode)
{
    std::string out; int arg = 0;
    for (size_t i = 0; i < luafile.size(); ++i)
    {
        if (luafile[i] == '%' && i + 1 < luafile.size() && luafile[i + 1] == 's') { out += (arg++ == 0) ? era : mode; ++i; }
        else out += luafile[i];
    }
    return out;
}

static std::string ShellLuaField(lua_State* L, int t, const char* k)
{
    lua_pushstring(L, k); lua_gettable(L, t);
    std::string v = lua_isstring(L, -1) ? lua_tostring(L, -1) : "";
    lua_pop(L, 1);
    return v;
}

static bool LoadShellMissionList(Level* shellLvl)
{
    const Script* script = shellLvl ? shellLvl->GetScript(String("missionlist")) : nullptr;
    const uint8_t* data = nullptr; size_t size = 0;
    if (script == nullptr || !script->GetData(data, size) || data == nullptr || size == 0) { checkpoint("M480 shell: no missionlist script in shell.lvl"); return false; }
    lua_State* L = lua_open();
    if (L == nullptr) return false;
    luaopen_base(L); luaopen_table(L); luaopen_string(L); luaopen_math(L);
    lua_pushstring(L, "gPlatformStr"); lua_pushstring(L, "XBox"); lua_settable(L, LUA_GLOBALSINDEX);
    if (luaL_loadbuffer(L, (const char*)data, size, "missionlist") != 0 || lua_pcall(L, 0, 0, 0) != 0)
    {
        checkpointf("M480 shell: missionlist failed: %s", lua_isstring(L, -1) ? lua_tostring(L, -1) : "?");
        lua_close(L);
        return false;
    }
    lua_pushstring(L, "sp_missionselect_listbox_contents"); lua_gettable(L, LUA_GLOBALSINDEX);
    if (lua_istable(L, -1))
    {
        const int t = lua_gettop(L);
        for (int i = 1; ; ++i)
        {
            lua_rawgeti(L, t, i);
            if (!lua_istable(L, -1)) { lua_pop(L, 1); break; }
            const int e = lua_gettop(L);
            ShellMapRow row;
            lua_pushnil(L);
            while (lua_next(L, e) != 0)
            {
                if (lua_type(L, -2) == LUA_TSTRING)
                {
                    const std::string k = lua_tostring(L, -2);
                    if (k == "mapluafile" && lua_isstring(L, -1)) row.luafile = lua_tostring(L, -1);
                    else if (!lua_isnil(L, -1) && lua_type(L, -1) != LUA_TBOOLEAN) row.flags.insert(k);
                    else if (lua_type(L, -1) == LUA_TBOOLEAN && lua_toboolean(L, -1)) row.flags.insert(k);
                }
                lua_pop(L, 1);
            }
            if (!row.luafile.empty()) g_shellMaps.push_back(row);
            lua_pop(L, 1);
        }
    }
    lua_pop(L, 1);
    lua_pushstring(L, "gMapModes"); lua_gettable(L, LUA_GLOBALSINDEX);
    if (lua_istable(L, -1))
        for (int i = 1; ; ++i)
        {
            lua_rawgeti(L, -1, i);
            if (!lua_istable(L, -1)) { lua_pop(L, 1); break; }
            const int e = lua_gettop(L);
            ShellModeRow m; m.key = ShellLuaField(L, e, "key"); m.showstr = ShellLuaField(L, e, "showstr");
            m.descstr = ShellLuaField(L, e, "descstr"); m.subst = ShellLuaField(L, e, "subst"); m.icon = ShellLuaField(L, e, "icon");
            g_shellModeDefs.push_back(m);
            lua_pop(L, 1);
        }
    lua_pop(L, 1);
    lua_pushstring(L, "gMapEras"); lua_gettable(L, LUA_GLOBALSINDEX);
    if (lua_istable(L, -1))
        for (int i = 1; ; ++i)
        {
            lua_rawgeti(L, -1, i);
            if (!lua_istable(L, -1)) { lua_pop(L, 1); break; }
            const int e = lua_gettop(L);
            ShellEraRow r; r.key = ShellLuaField(L, e, "key"); r.showstr = ShellLuaField(L, e, "showstr");
            r.subst = ShellLuaField(L, e, "subst"); r.icon1 = ShellLuaField(L, e, "icon1");
            g_shellEraDefs.push_back(r);
            lua_pop(L, 1);
        }
    lua_pop(L, 1);
    lua_close(L);
    checkpointf("M480 shell: missionlist -> %u maps, %u modes, %u eras", (unsigned)g_shellMaps.size(),
                (unsigned)g_shellModeDefs.size(), (unsigned)g_shellEraDefs.size());
    return !g_shellMaps.empty();
}

static std::vector<std::string> ShellMapKeyCandidates(const std::string& abbrev, const char* what)
{
    std::vector<std::string> keys;
    size_t l2 = abbrev.size();
    for (size_t i = 0; i + 1 < abbrev.size(); ++i) if (abbrev[i] == '_') l2 = i + 1;
    for (size_t i = 0; i < l2; ++i) keys.push_back(std::string("mapname.") + what + "." + abbrev.substr(0, l2 - i));
    return keys;
}
static std::string ShellMapText(const std::string& abbrev, const char* what)
{
    for (const std::string& k : ShellMapKeyCandidates(abbrev, what))
    {
        const std::string v = LocString(k, "");
        if (!v.empty()) return v;
    }
    return abbrev;
}

