static float ShellU() { return (float)SCREEN_H / 480.0f; }

static float ShellTextScale(float units) { return 0.82f * units / SHELL_FONT_LARGE; }

static std::string ShellTitleCase(std::string t)
{
    for (char c : t) if (c >= 'a' && c <= 'z') return t;
    bool start = true;
    for (char& c : t)
    {
        if (c >= 'A' && c <= 'Z' && !start) c = (char)(c - 'A' + 'a');
        start = (c == ' ' || c == '-');
    }
    return t;
}
