        g_aiPoisonForPlayer.timer = 0.0f; g_aiBuffForPlayer.timer = 0.0f; g_aiRegenForPlayer.timer = 0.0f; g_aiOffenseForPlayer.timer = 0.0f;

        g_activeOrdnance.clear(); g_activeTracers.clear(); g_blastFlashes.clear(); g_beams.clear();
        g_cpLostEvents.clear(); g_cpCapturedEvents.clear();
