        g_reticuleHitTimer = 0.0f; g_reticuleCritTimer = 0.0f;
        g_boundsWarnT = -1.0f;
        for (HintNodeData& hn : g_hintNodes) hn.mined = false;
        if (g_audioMutex >= 0)
        {
            sceKernelLockMutex(g_audioMutex, 1, nullptr);
            for (int vi2 = 0; vi2 < MAX_VOICES; ++vi2) g_voices[vi2].active = false;
            sceKernelUnlockMutex(g_audioMutex, 1);
        }
        while (UiIsActive()) UiPop();

